package com.gielinorskate;

import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import lombok.RequiredArgsConstructor;
import net.runelite.client.config.*;

/**
 * Settings. Display names may change freely, but a keyName never changes without a migration (renaming one
 * silently resets the player's saved value).
 */
@ConfigGroup(GielinorSkateConfig.GROUP)
public interface GielinorSkateConfig extends Config
{
	String GROUP = "gielinorskate";

	@ConfigSection(name = "RuneSkate", description = "The skate key and controller", position = 0)
	String GENERAL = "general";

	@ConfigSection(name = "Play together",
		description = "Join a RuneLite Party with your friends (Party plugin → Create/Join party) on the same world "
			+ "to see each other skate.",
		position = 1)
	String PARTY = "party";

	@ConfigSection(name = "Gameplay", description = "Tricks and bails", position = 2)
	String GAMEPLAY = "gameplay";

	@ConfigSection(name = "Camera & effects", description = "The chase camera, sounds and particles", position = 3)
	String CAMERA = "camera";

	@ConfigSection(name = "Advanced", description = "Key rebinds, fine tuning and everything else",
		position = 4, closedByDefault = true)
	String ADVANCED = "advanced";

	/** Which controller layout turns the pad's buttons into actions (see com.gielinorskate.controller). */
	@RequiredArgsConstructor
	enum ControllerPreset
	{
		SKATE_3("Skate 3"),
		THAW("Tony Hawk's American Wasteland"),
		CUSTOM("Custom");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How tricks are triggered: mouse flicks, keys, or both. */
	@RequiredArgsConstructor
	enum TrickControls
	{
		MOUSE("Mouse flicks"),
		KEYBOARD("Keyboard"),
		BOTH("Both");

		private final String label;

		/** True when Space and the number keys do tricks. */
		public boolean keyboard()
		{
			return this != MOUSE;
		}

		/** True when mouse flicks do tricks. */
		public boolean mouse()
		{
			return this != KEYBOARD;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** The mouse button held for a flick. */
	@RequiredArgsConstructor
	enum FlickButton
	{
		RIGHT("Right"),
		LEFT("Left"),
		MIDDLE("Middle");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** What a bail does after the fall: knocked off the board (walk back to it), or straight back on. */
	@RequiredArgsConstructor
	enum AfterBail
	{
		KNOCKED_OFF("Get knocked off (walk back to your board)"),
		HOP_BACK_ON("Hop straight back on");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** How detailed the baked board is drawn for you (party skaters' boards always use the lighter variant). */
	@RequiredArgsConstructor
	enum BoardDetail
	{
		HIGH("High"),
		NORMAL("Normal");

		private final String label;

		@Override
		public String toString()
		{
			return label;
		}
	}

	@RequiredArgsConstructor
	enum CameraHeight
	{
		LOW("Low", 6),
		MEDIUM("Medium", 14),
		HIGH("High", 22);

		private final String label;
		private final int degrees;

		/** Camera pitch in JAU14 (16384 per turn). */
		public int pitchJau14()
		{
			return Math.round(degrees * 16384f / 360f);
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	// ---- RuneSkate

	@ConfigItem(
		keyName = "toggleKey",
		name = "Skate mode key",
		description = "Starts or stops skating (the skateboard button in the sidebar does too).",
		position = 0,
		section = GENERAL
	)
	default Keybind toggleKey()
	{
		return new Keybind(KeyEvent.VK_K, InputEvent.CTRL_DOWN_MASK);
	}

	@ConfigItem(
		keyName = "controllerMode",
		name = "Controller mode",
		description = "For a gamepad through AntiMicroX (side panel: Controller setup): the pad's buttons do the "
			+ "Controller preset's actions, the right stick flicks with no button, and the card and panel show pad "
			+ "buttons.",
		position = 1,
		section = GENERAL
	)
	default boolean controllerMode()
	{
		return false;
	}

	@ConfigItem(
		keyName = "controllerPreset",
		name = "Controller preset",
		description = "What the pad's buttons do in Controller mode: Skate 3 (flick tricks on the right stick), Tony "
			+ "Hawk's American Wasteland (tricks on buttons, the right stick turns the camera), or your own layout "
			+ "(side panel: Customise controller).",
		position = 2,
		section = GENERAL
	)
	default ControllerPreset controllerPreset()
	{
		return ControllerPreset.SKATE_3;
	}

	// ---- Play together

	@ConfigItem(
		keyName = "shareWithParty",
		name = "Share my skater with my party",
		description = "Party members who are also skating see your skater (never in PvP areas).",
		position = 0,
		section = PARTY
	)
	default boolean shareWithParty()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showPartySkaters",
		name = "Show party skaters",
		description = "While you skate, shows the skaters of party members who share theirs.",
		position = 1,
		section = PARTY
	)
	default boolean showPartySkaters()
	{
		return true;
	}

	// ---- Gameplay

	@ConfigItem(
		keyName = "trickControls",
		name = "Trick controls",
		description = "Mouse flicks, Keyboard (Space: ollie, 1-0: flip tricks, Shift: hard version, Alt: nollie), "
			+ "or Both.",
		position = 0,
		section = GAMEPLAY
	)
	default TrickControls trickControls()
	{
		return TrickControls.MOUSE;
	}

	@ConfigItem(
		keyName = "forgivingCollisions",
		name = "Easy mode",
		description = "A smaller hitbox around your skater, and only harder hits make you bail.",
		position = 1,
		section = GAMEPLAY
	)
	default boolean forgivingCollisions()
	{
		return false;
	}

	@ConfigItem(
		keyName = "afterBail",
		name = "After a bail",
		description = "Get knocked off (F gets your board back, R gets straight back on) or hop straight back on.",
		position = 2,
		section = GAMEPLAY
	)
	default AfterBail afterBail()
	{
		return AfterBail.KNOCKED_OFF;
	}

	// ---- Camera & effects

	@Range(min = 200, max = 1400)
	@ConfigItem(
		keyName = "cameraZoom",
		name = "Camera zoom",
		description = "Chase camera zoom, higher is closer; the mouse wheel changes it while skating.",
		position = 0,
		section = CAMERA
	)
	default int cameraZoom()
	{
		return 700;
	}

	@ConfigItem(
		keyName = "cameraHeight",
		name = "Camera height",
		description = "How far above the skater the chase camera looks down from.",
		position = 1,
		section = CAMERA
	)
	default CameraHeight cameraHeight()
	{
		return CameraHeight.HIGH;
	}

	@ConfigItem(
		keyName = "soundEffects",
		name = "Sound effects",
		description = "Pops, landings, grinds and bails, following your in-game sound effect volume.",
		position = 2,
		section = CAMERA
	)
	default boolean soundEffects()
	{
		return true;
	}

	@ConfigItem(
		keyName = "particleEffects",
		name = "Particle effects",
		description = "Dust on big landings, sparks on rails and smoke on bails (only you see them).",
		position = 3,
		section = CAMERA
	)
	default boolean particleEffects()
	{
		return true;
	}

	// ---- Advanced

	@Range(min = 75, max = 150)
	@ConfigItem(
		keyName = "speedScale",
		name = "Speed %",
		description = "How hard you push and how fast you can go.",
		position = 0,
		section = ADVANCED
	)
	default int speedScale()
	{
		return 100;
	}

	@Range(min = 75, max = 150)
	@ConfigItem(
		keyName = "popScale",
		name = "Jump height %",
		description = "How high an ollie goes.",
		position = 1,
		section = ADVANCED
	)
	default int popScale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "passThroughVegetation",
		name = "Pass through vegetation",
		description = "Ride straight through plants, bushes and crops instead of colliding with them.",
		position = 2,
		section = ADVANCED
	)
	default boolean passThroughVegetation()
	{
		return true;
	}

	@ConfigItem(
		keyName = "allowPvpAreas",
		name = "Allow skating in PvP areas",
		description = "Skate in the Wilderness and on PvP worlds: other players are hidden while you skate there, "
			+ "and skating is still blocked in combat and ends when you take damage.",
		warning = "Your real character stands still and unattended while you skate. Other players are hidden "
			+ "while you skate there, but things you'd see in normal play (minimap dots, pets, other plugins' "
			+ "overlays) may still show. Only enable this if you're carrying nothing you'd mind losing. Continue?",
		position = 3,
		section = ADVANCED
	)
	default boolean allowPvpAreas()
	{
		return false;
	}

	@ConfigItem(
		keyName = "manualKey",
		name = "Wheelie (manual) key",
		description = "Hold while rolling for a manual, with W for a nose manual (with keyboard tricks on, a Space "
			+ "setting uses C instead).",
		position = 4,
		section = ADVANCED
	)
	default Keybind manualKey()
	{
		return new Keybind(KeyEvent.VK_SPACE, 0);
	}

	@ConfigItem(
		keyName = "leanForwardKey",
		name = "Lean forward key",
		description = "Hold with a grab (Q / E) in the air for a front flip; the Up arrow still pushes too.",
		position = 5,
		section = ADVANCED
	)
	default Keybind leanForwardKey()
	{
		return new Keybind(KeyEvent.VK_UP, 0);
	}

	@ConfigItem(
		keyName = "leanBackKey",
		name = "Lean back key",
		description = "Hold with a grab (Q / E) in the air for a back flip; the Down arrow still crouches too.",
		position = 6,
		section = ADVANCED
	)
	default Keybind leanBackKey()
	{
		return new Keybind(KeyEvent.VK_DOWN, 0);
	}

	@ConfigItem(
		keyName = "brakeKey",
		name = "Brake key",
		description = "Hold to powerslide brake like Shift alone; pick a key no other control uses.",
		position = 7,
		section = ADVANCED
	)
	default Keybind brakeKey()
	{
		return new Keybind(KeyEvent.VK_B, 0);
	}

	@ConfigItem(
		keyName = "boardKey",
		name = "Board on/off key",
		description = "Step off and carry the board, step back on, or call a dropped board back (a key a skate "
			+ "control already uses falls back to F).",
		position = 8,
		section = ADVANCED
	)
	default Keybind boardKey()
	{
		return new Keybind(KeyEvent.VK_F, 0);
	}

	@ConfigItem(
		keyName = "flickButton",
		name = "Flick button",
		description = "The mouse button you hold to wind up and flick tricks.",
		position = 11,
		section = ADVANCED
	)
	default FlickButton flickButton()
	{
		return FlickButton.RIGHT;
	}

	@ConfigItem(
		keyName = "mirrorFlicks",
		name = "Mirror flicks",
		description = "Swaps left and right flicks: up-left becomes a heelflip, left a FS shove-it, and so on.",
		position = 12,
		section = ADVANCED
	)
	default boolean mirrorFlicks()
	{
		return false;
	}

	@Range(min = 70, max = 150)
	@ConfigItem(
		keyName = "flickSensitivity",
		name = "Flick sensitivity %",
		description = "Higher means smaller or slower mouse flicks still count as tricks.",
		position = 13,
		section = ADVANCED
	)
	default int flickSensitivity()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "showControlsCard",
		name = "Show controls card",
		description = "Shows the controls card when you start skating until you've pushed and jumped once (H "
			+ "toggles it any time).",
		position = 14,
		section = ADVANCED
	)
	default boolean showControlsCard()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showTrickHints",
		name = "Show trick hints",
		description = "A short tip when a mouse flick almost became a trick.",
		position = 15,
		section = ADVANCED
	)
	default boolean showTrickHints()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showFlickVisualizer",
		name = "Show flick visualizer",
		description = "While you hold the flick button, the HUD ring shows your mouse path and each flick it "
			+ "recognises.",
		position = 16,
		section = ADVANCED
	)
	default boolean showFlickVisualizer()
	{
		return true;
	}

	@Range(min = 0, max = 100)
	@ConfigItem(
		keyName = "soundVolume",
		name = "Sound volume",
		description = "Skate sounds as a percentage of your in-game sound effect volume.",
		position = 17,
		section = ADVANCED
	)
	default int soundVolume()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "funnyBailMessages",
		name = "Funny bail messages",
		description = "A joke chat line when you bail, at most one every 20 seconds.",
		position = 18,
		section = ADVANCED
	)
	default boolean funnyBailMessages()
	{
		return true;
	}

	@ConfigItem(
		keyName = "levelUpNotification",
		name = "Level-up notifications",
		description = "A RuneLite notification when your Skating level goes up (the chat message always shows).",
		position = 19,
		section = ADVANCED
	)
	default Notification levelUpNotification()
	{
		return Notification.ON;
	}

	@ConfigItem(
		keyName = "showSessionGoals",
		name = "Show daily goals",
		description = "Shows today's three goals in the side panel and on the HUD (they still count when hidden).",
		position = 20,
		section = ADVANCED
	)
	default boolean showSessionGoals()
	{
		return true;
	}

	@ConfigItem(
		keyName = "boardDetail",
		name = "Board detail",
		description = "How finely your RuneSkate board is drawn: Normal is lighter on slower computers.",
		position = 22,
		section = ADVANCED
	)
	default BoardDetail boardDetail()
	{
		return BoardDetail.HIGH;
	}

	@ConfigItem(
		keyName = "smoothMotion",
		name = "Smooth motion",
		description = "Draws the skater and camera between physics steps, so motion stays smooth at any frame rate.",
		position = 23,
		section = ADVANCED
	)
	default boolean smoothMotion()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showGrindEdges",
		name = "Show grindable edges",
		description = "While skating, draws the edges and rails you can grind.",
		position = 24,
		section = ADVANCED
	)
	default boolean showGrindEdges()
	{
		return false;
	}

	/** The Custom controller preset, as a layout code (com.gielinorskate.controller.LayoutCode); empty: none. */
	@ConfigItem(
		keyName = "customControllerLayout",
		name = "",
		description = "",
		hidden = true
	)
	default String customControllerLayout()
	{
		return "";
	}

	/** Set once a Controller mode player has been shown how to set the controller up. */
	@ConfigItem(
		keyName = "controllerSetupHint",
		name = "",
		description = "",
		hidden = true
	)
	default boolean controllerSetupHint()
	{
		return false;
	}

	/** Set once the first-run welcome line has been shown. */
	@ConfigItem(
		keyName = "seenIntro",
		name = "",
		description = "",
		hidden = true
	)
	default boolean seenIntro()
	{
		return false;
	}

	/** Set once the player has pushed and jumped: the basics card no longer shows by itself. */
	@ConfigItem(
		keyName = "learnedBasics",
		name = "",
		description = "",
		hidden = true
	)
	default boolean learnedBasics()
	{
		return false;
	}
}

package com.gielinorskate;

import static com.gielinorskate.GielinorSkateConfig.GROUP;

import com.gielinorskate.controller.LayoutCode;
import com.gielinorskate.controller.PadPresets;
import com.gielinorskate.input.InputController;
import com.gielinorskate.overlay.*;
import com.gielinorskate.party.*;
import com.gielinorskate.progression.ProgressionService;
import com.gielinorskate.session.*;
import com.gielinorskate.ui.*;
import com.google.inject.Provides;
import java.awt.Component;
import java.io.*;
import java.util.List;
import java.util.concurrent.FutureTask;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.swing.JOptionPane;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.client.callback.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.*;
import net.runelite.client.input.*;
import net.runelite.client.party.WSClient;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.*;

@Slf4j
@PluginDescriptor(
	name = "RuneSkate",
	description = "Skateboard around Gielinor: Ctrl+K to start, flick the mouse for tricks",
	tags = {"skate", "skateboard", "fun", "minigame"},
	internalName = "rune-skate"
)
public class GielinorSkatePlugin extends Plugin
{
	/** The overlays, all singletons (the plugin injector gives the same one to add and remove). */
	private static final List<Class<? extends Overlay>> OVERLAYS = List.of(ScoreOverlay.class,
		GrindEdgesOverlay.class, ControlsCardOverlay.class, GhostLabelOverlay.class, ComfortHintsOverlay.class);
	/** The party messages, registered while the plugin runs. */
	private static final List<Class<? extends PartyMemberMessage>> MESSAGES = List.of(SkateGhostUpdate.class,
		SkateGhostStop.class);

	@Inject
	private Client client;
	@Inject
	private SkateChat skateChat;
	@Inject
	private ClientThread clientThread;
	@Inject
	private KeyManager keyManager;
	@Inject
	private MouseManager mouseManager;
	@Inject
	private RenderCallbackManager renderCallbackManager;
	@Inject
	private GielinorSkateConfig config;
	@Inject
	private InputController input;
	@Inject
	private SkateSession session;
	@Inject
	private OverlayManager overlayManager;
	@Inject
	private EventBus eventBus;
	@Inject
	private WSClient wsClient;
	@Inject
	private PartyGhostService partyGhosts;
	@Inject
	private ConfigManager configManager;
	@Inject
	private ClientToolbar clientToolbar;
	@Inject
	private ProgressionService progression;
	@Inject
	private ScheduledExecutorService executor;

	/** The sidebar panel and its button; built in startUp. */
	private SkatePanel panel;
	private NavigationButton navButton;

	private final RenderCallback playerHider = new RenderCallback()
	{
		@Override
		public boolean addEntity(Renderable renderable, boolean ui)
		{
			return !session.shouldHide(renderable);
		}
	};

	private final HotkeyListener toggleListener = new HotkeyListener(() -> config.toggleKey())
	{
		@Override
		public void hotkeyPressed()
		{
			clientThread.invoke(session::toggle);
		}
	};

	@Override
	protected void startUp()
	{
		// the first sans-serif font of the JVM is slow to make: not on the client thread when the card first shows
		executor.execute(ControlsCardOverlay::warmFonts);
		renderCallbackManager.register(playerHider);
		keyManager.registerKeyListener(toggleListener);
		keyManager.registerKeyListener(input);
		mouseManager.registerMouseListener(input);
		mouseManager.registerMouseWheelListener(input);
		OVERLAYS.forEach(c -> overlayManager.add(injector.getInstance(c)));
		MESSAGES.forEach(wsClient::registerMessage);
		partyGhosts.startUp();
		eventBus.register(partyGhosts);

		panel = new SkatePanel(() -> clientThread.invoke(session::toggle), this::set,
			design -> clientThread.invoke(() -> progression.selectDesign(design)));
		panel.setControllerActions(new SkatePanel.ControllerActions()
		{
			@Override
			public void saveCustomLayout(String code)
			{
				set("customControllerLayout", code);
				set("controllerPreset", GielinorSkateConfig.ControllerPreset.CUSTOM);
			}

			@Override
			public void openReleases()
			{
				LinkBrowser.browse("https://github.com/AntiMicroX/antimicrox/releases");
			}

			@Override
			public void saveProfile(Component from)
			{
				saveControllerProfile(from);
			}

			@Override
			public void watchKeys(KeyListener l, boolean on)
			{
				if (on)
					keyManager.registerKeyListener(l);
				else
					keyManager.unregisterKeyListener(l);
			}
		});
		refreshPanelSettings();
		navButton = NavigationButton.builder()
			.tooltip("RuneSkate")
			.icon(ImageUtil.loadImageResource(GielinorSkatePlugin.class, "panel_icon.png"))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		SkatePanel shown = panel;
		clientThread.invoke(() ->
		{
			// panel state is made on the client thread and handed to Swing
			session.setPanelListener(state -> SwingUtilities.invokeLater(() -> shown.update(state)));
			session.publishPanel();
			progression.setListener(state -> SwingUtilities.invokeLater(() -> shown.updateProgress(state)));
			progression.setLookListener(session::applyLook);
			// the logged-in account's XP (none until a profile is known: RuneScapeProfileChanged loads it then)
			progression.load();
		});
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		navButton = null;
		SkatePanel closing = panel;
		if (closing != null)
			// the pad test's key watcher goes with the panel
			SwingUtilities.invokeLater(closing::dispose);
		panel = null;
		eventBus.unregister(partyGhosts);
		// the party hears that we stopped while the types are registered
		partyGhosts.shutDown();
		MESSAGES.forEach(wsClient::unregisterMessage);
		OVERLAYS.forEach(c -> overlayManager.remove(injector.getInstance(c)));
		clientThread.invoke(() ->
		{
			session.exit(null);
			session.setPanelListener(null);
			progression.setListener(null);
			progression.setLookListener(null);
			progression.flush();
		});
		mouseManager.unregisterMouseWheelListener(input);
		mouseManager.unregisterMouseListener(input);
		keyManager.unregisterKeyListener(input);
		keyManager.unregisterKeyListener(toggleListener);
		renderCallbackManager.unregister(playerHider);
	}

	@Subscribe
	public void onBeforeRender(BeforeRender e)
	{
		session.onFrame();
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		session.checkPlayerMoved();
		progression.tick();
	}

	/** Skate XP and decks are per account: save the old account's, load the new one's. */
	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged e)
	{
		clientThread.invoke(progression::load);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		GameState state = e.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (!config.seenIntro())
			{
				set("seenIntro", true);
				skateChat.send(ComfortHints.welcome(config.toggleKey().toString()));
			}
			tellControllerSetup();
			return;
		}
		// on LOADING the scene is rebuilt (the skate world with it): say why skating stopped
		session.exit(state == GameState.LOADING ? Text.get("pl.loading", config.toggleKey()) : null);
		if (state == GameState.HOPPING || state == GameState.LOGIN_SCREEN)
		{
			partyGhosts.onSceneLost();
			progression.flush();
		}
	}

	/**
	 * RuneLite does not stop plugins on exit, so {@link #shutDown} is not guaranteed to run before the JVM
	 * closes. {@link ConfigManager#onClientShutdown} only sends what is already set, so any XP still debounced
	 * (up to {@code Progression.MAX_UNSAVED_SECONDS}) would otherwise be lost. Flush it on the client thread and
	 * make the shutdown wait for that to finish; ConfigManager's own handler (priority -100) runs after ours.
	 */
	@Subscribe
	public void onClientShutdown(ClientShutdown e)
	{
		FutureTask<Void> flushed = new FutureTask<>(progression::flush, null);
		clientThread.invoke(flushed);
		e.waitFor(flushed);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		String key = e.getKey();
		// per-account progress (saved in the RuneScape profile) is not a setting
		if (!GROUP.equals(e.getGroup()) || ProgressionService.isProgressKey(key))
			return;
		clientThread.invoke(() ->
		{
			session.onConfigChanged(key);
			if ("controllerMode".equals(key) && client.getGameState() == GameState.LOGGED_IN)
				tellControllerSetup();
		});
		refreshPanelSettings();
	}

	/**
	 * While skating the camera is detached from the player: any menu action on the game world is cancelled
	 * (Plugin Hub rule: no world interaction from a detached camera). Interface actions still go through.
	 */
	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked e)
	{
		if (session.isActive() && WorldActions.isWorldAction(e.getMenuAction()))
			e.consume();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (session.isActive() && e.getActor() == client.getLocalPlayer())
			// poison and venom get their own message: their damage still ends skating
			session.exit(ComfortHints.damageMessage(e.getHitsplat().getHitsplatType()));
	}

	private void set(String key, Object value)
	{
		configManager.setConfiguration(GROUP, key, value);
	}

	/** The first time Controller mode is on while logged in, the player is told how to set the controller up. */
	private void tellControllerSetup()
	{
		if (config.controllerMode() && !config.controllerSetupHint())
		{
			set("controllerSetupHint", true);
			skateChat.send(Text.get("ch.pad.setup"));
		}
	}

	/** Save the RuneSkate AntiMicroX profile: where to (a save dialog, EDT), then the file written (executor). */
	private void saveControllerProfile(Component from)
	{
		List<Filepath> picked = new Filepath.Chooser()
			.setIsSave()
			.setAcceptsFiles()
			.setDialogTitle("Save the RuneSkate controller profile")
			.addExtensionFilter("AntiMicroX profile", "amgp")
			.setDefaultExtension("amgp")
			.setFileName("RuneSkate.amgp")
			.showDialog(from);
		if (picked == null || picked.isEmpty())
			return;
		Filepath file = picked.get(0);
		executor.execute(() ->
		{
			try (InputStream in = GielinorSkatePlugin.class.getResourceAsStream("RuneSkate.amgp");
				OutputStream out = file.openOutputStream())
			{
				in.transferTo(out);
				SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(from, Text.get("pl.saved", file.getFileName()),
					"RuneSkate", JOptionPane.INFORMATION_MESSAGE));
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn(Text.get("pl.log.profile"), ex);
				SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(from,
					Text.get("pl.unsaved", ex.getMessage()), "RuneSkate", JOptionPane.WARNING_MESSAGE));
			}
		});
	}

	/** Hands the settings the panel shows (its toggles, keys, trick and controller controls) to Swing. */
	private void refreshPanelSettings()
	{
		SkatePanel p = panel;
		if (p == null)
			return;
		SwingUtilities.invokeLater(() ->
		{
			GielinorSkateConfig.TrickControls controls = config.trickControls();
			GielinorSkateConfig.ControllerPreset which = config.controllerPreset();
			String customCode = config.customControllerLayout();
			LayoutCode.Result saved = LayoutCode.decode(customCode);
			p.setController(PadPresets.resolve(which, customCode), PadPresets.customIsBroken(which, customCode)
				? Text.get("pl.broken") : which.toString(), saved.ok() ? saved.preset : null);
			p.setKeyNames(config.flickButton().toString().toLowerCase(), config.brakeKey().toString(),
				config.leanForwardKey().toString(), config.leanBackKey().toString());
			p.setSettings(config.toggleKey().toString(), ComfortHints.manualKeyLabel(config.manualKey().toString(),
				config.manualKey().getKeyCode(), controls.keyboard()), controls.mouse(), controls.keyboard(),
				config.mirrorFlicks(), config.showGrindEdges(), config.showControlsCard(), config.controllerMode(),
				ComfortHints.boardKeyLabel(config.boardKey().toString(), config.boardKey().getKeyCode(),
				controls.keyboard()));
			p.setShowGoals(config.showSessionGoals());
		});
	}

	@Provides
	GielinorSkateConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GielinorSkateConfig.class);
	}
}

package com.gielinorskate;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.*;

/**
 * Every RuneSkate chat line goes out through here: tagged "[RuneSkate]" in the highlight colour, so no line can be
 * mistaken for a real game message.
 */
@Singleton
public class SkateChat
{
	public static final String PREFIX = "[RuneSkate] ";

	private final ChatMessageManager chatMessageManager;

	@Inject
	SkateChat(ChatMessageManager chatMessageManager)
	{
		this.chatMessageManager = chatMessageManager;
	}

	/** Queues one branded line; null or empty lines are dropped. Safe from any thread. */
	public void send(String line)
	{
		if (line == null || line.isEmpty())
			return;
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(format(line))
			.build());
	}

	/** The line as sent: the highlighted tag, then the text in the normal colour. */
	static String format(String line)
	{
		return new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append(PREFIX)
			.append(ChatColorType.NORMAL)
			.append(line)
			.build();
	}
}

package com.gielinorskate;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * The plugin's bundled words and data tables, kept out of the code in .properties files under
 * resources/com/gielinorskate/text (read once, UTF-8). A missing key is a bug: it throws.
 */
public final class Text
{
	/** The bundled files, by name; each key lives in exactly one. */
	static final List<String> FILES = List.of("ui", "overlay", "session", "data");
	private static final Properties ALL = load();

	private Text()
	{
	}

	private static Properties load()
	{
		Properties all = new Properties();
		for (String name : FILES)
			try (Reader r = new InputStreamReader(Text.class.getResourceAsStream("text/" + name + ".properties"),
				StandardCharsets.UTF_8))
			{
				all.load(r);
			}
			catch (IOException | NullPointerException e)
			{
				throw new IllegalStateException("RuneSkate: text/" + name + ".properties could not be read", e);
			}
		return all;
	}

	/** The text under {@code key}, with each {N} replaced by args[N]. */
	public static String get(String key, Object... args)
	{
		String v = ALL.getProperty(key);
		if (v == null)
			throw new IllegalArgumentException("No text " + key);
		for (int i = 0; i < args.length; i++)
			v = v.replace("{" + i + "}", String.valueOf(args[i]));
		return v;
	}

	/** The lines of the text under {@code key}. */
	public static List<String> lines(String key)
	{
		return List.of(get(key).split("\n"));
	}

	/** The numbers (separated by commas and/or spaces) under {@code key}. */
	public static float[] floats(String key)
	{
		String[] parts = get(key).trim().split("[,\\s]+");
		float[] out = new float[parts.length];
		for (int i = 0; i < parts.length; i++)
			out[i] = Float.parseFloat(parts[i]);
		return out;
	}

	/** The whole numbers (separated by commas and/or spaces) under {@code key}. */
	public static int[] ints(String key)
	{
		String[] parts = get(key).trim().split("[,\\s]+");
		int[] out = new int[parts.length];
		for (int i = 0; i < parts.length; i++)
			out[i] = Integer.parseInt(parts[i]);
		return out;
	}

	/** Whether {@code key} is bundled. */
	static boolean has(String key)
	{
		return ALL.containsKey(key);
	}
}

package com.gielinorskate.camera;

import com.gielinorskate.physics.Angles;

/**
 * Turning the chase camera by hand on the board (the Tony Hawk's American Wasteland preset's right stick): the turn
 * is kept as an offset from where the chase camera would look, so the camera stays where the stick put it while it
 * is moved. After {@link #IDLE_SECONDS} without stick input the offset is let go and the chase camera eases back
 * behind the skater at its usual follow rate. Pure.
 */
public final class BoardOrbit
{
	/** Seconds without stick input before the camera goes back behind the skater. */
	public static final float IDLE_SECONDS = 1.5f;

	private float offset;
	private float idle = IDLE_SECONDS;

	/** The stick turned the camera by {@code radians} (clockwise). */
	public void turn(float radians)
	{
		if (radians == 0f)
			return;
		offset = Angles.wrap(offset + radians);
		idle = 0f;
	}

	/** A frame of {@code dt} seconds passed: once idle for {@link #IDLE_SECONDS} the offset goes. */
	public void update(float dt)
	{
		idle = Math.min(IDLE_SECONDS, idle + dt);
		if (idle >= IDLE_SECONDS)
			offset = 0f;
	}

	/** How far (radians, clockwise) the camera is turned from behind the skater by hand. */
	public float offset()
	{
		return offset;
	}

	/** Off the board (or a new session): no offset. */
	public void reset()
	{
		offset = 0f;
		idle = IDLE_SECONDS;
	}
}

package com.gielinorskate.camera;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import lombok.Getter;

/**
 * Pure chase-camera behaviour modelled on how Skate-style cameras feel: low, behind the direction of travel,
 * lagging through carves, ignoring spins, leading the skater at speed, rising less than the skater in the air,
 * dipping on landings (harder ones further, big airs with a short jolt) and holding still during bails. Units: local units, seconds, radians.
 */
public final class CameraRig
{
	/** Height of the look-at point above the skater's feet. */
	static final float FOCUS_HEIGHT = 70f;
	static final float MAX_LOOK_AHEAD = 96f;
	/**
	 * The yaw never turns faster than this (rad/s): one turn a second. The exponential follow at the far rate
	 * (4/s) turns faster than 2 PI only while more than 2 PI / 4 = 90 degrees behind, so ordinary turns, pivots
	 * (pivotRate 4.5 rad/s) and the 60-90 degree catch-up are unchanged; a half-turn swing (getting back on facing
	 * away from a wall after a bail) no longer whips round at 4 PI = 720 deg/s.
	 */
	static final float MAX_YAW_RATE = 2 * Angles.PI;
	/** Big airs also shake the focus a little, by up to this much (see updateJitter). */
	static final float JITTER_AMPLITUDE = 4f;
	/** Done after this; the remaining amplitude is 4 * e^(-18 * 0.4) < 0.003 units. */
	private static final float JITTER_SECONDS = 0.4f;

	/** Heading the camera looks along (radians, 0 = north). */
	@Getter
	private float yaw;
	private float leadX, leadY, x, y, height, dip;
	/** 1 when slow, smaller (camera further back) at speed. */
	@Getter
	private float zoomFactor = 1f;
	/** Skater height on the previous update, to measure the fall speed of a flight. */
	private float lastSkaterH;
	/** Vertical speed (u/s, up > 0) on the latest airborne update. */
	private float airVerticalSpeed;
	/** Seconds since a big-air landing started the jitter; past {@link #JITTER_SECONDS} when none. */
	private float jitterAge = Float.MAX_VALUE;
	private float jitterUp, jitterSide;

	/** Converts a heading (0 = north, clockwise) to RuneLite camera yaw: JAU14, 0 = north, counter-clockwise. */
	public static int yawJau14(float heading)
	{
		return Math.floorMod(Math.round(-heading * 8192f / Angles.PI), 16384);
	}

	public void reset(float x, float y, float h, float heading)
	{
		yaw = heading;
		this.x = x;
		this.y = y;
		height = h;
		leadX = 0f;
		leadY = 0f;
		dip = 0f;
		zoomFactor = 1f;
		lastSkaterH = h;
		airVerticalSpeed = 0f;
		jitterAge = Float.MAX_VALUE;
		jitterUp = 0f;
		jitterSide = 0f;
	}

	/**
	 * Landing dip (local units) for a landing at {@code landingSpeed} (downward u/s): from 8 at 500 u/s to 30 at
	 * 1700 u/s. A flat-ground ollie lands at about its pop speed, ollieImpulse = 820 u/s: 8 + 22 * (820 - 500) /
	 * 1200 = 13.9, the old fixed dip of 14; a drop off a ledge kicks harder.
	 */
	static float landingDip(float landingSpeed)
	{
		float u = (landingSpeed - 500f) / (1700f - 500f);
		return 8f + (30f - 8f) * Math.max(0f, Math.min(1f, u));
	}

	/**
	 * @param cameraHeading heading to sit behind ({@code SkatePhysics.getCameraHeading()}: the board, not the
	 *     roll direction, so it is followed at any speed, even turning in place)
	 * @param speed signed or unsigned speed; only its magnitude is used
	 * @param landedAirtime seconds in the air of a landing on this frame, 0 when none
	 */
	public void update(float skaterX, float skaterY, float h, float cameraHeading, float speed, SkaterState state,
		float landedAirtime, float dt)
	{
		float absSpeed = Math.abs(speed);
		boolean airborne = state == SkaterState.AIRBORNE;

		if (state != SkaterState.BAILED)
		{
			float error = Angles.wrap(cameraHeading - yaw);
			// follows at 3/s, 4/s while more than 60 degrees behind (a pivot or a sharp turn), 0.6/s in the air
			float rate = airborne ? 0.6f : Math.abs(error) > (float) Math.toRadians(60) ? 4f : 3f;
			float turn = error * blend(rate, dt);
			float maxTurn = MAX_YAW_RATE * dt;
			yaw = Angles.wrap(yaw + Math.max(-maxTurn, Math.min(maxTurn, turn)));
		}

		// leads by 0.18 s of travel, at most MAX_LOOK_AHEAD, easing at 4/s
		float lead = state == SkaterState.BAILED ? 0f : Math.min(MAX_LOOK_AHEAD, absSpeed * 0.18f);
		float targetLeadX = absSpeed > 1f ? (float) Math.sin(cameraHeading) * lead : 0f;
		float targetLeadY = absSpeed > 1f ? (float) Math.cos(cameraHeading) * lead : 0f;
		float leadBlend = blend(4f, dt);
		leadX += (targetLeadX - leadX) * leadBlend;
		leadY += (targetLeadY - leadY) * leadBlend;
		x = skaterX + leadX;
		y = skaterY + leadY;

		// the height follows at 12/s on the ground, 2.5/s in the air
		height += (h - height) * blend(airborne ? 2.5f : 12f, dt);
		if (airborne && dt > 0f)
			airVerticalSpeed = (h - lastSkaterH) / dt;
		lastSkaterH = h;
		// only landings after more than 0.25 s in the air dip the camera (not bumps or tiny hops)
		if (landedAirtime > 0.25f)
		{
			// the fall seen on the last airborne update, or the flat-ground guess from the airtime if larger: a
			// flight that starts and ends at the same height lands at gravity * airtime / 2, with gravity = 2000
			// u/s^2 (skate-tuning.json)
			float landingSpeed = Math.max(-airVerticalSpeed, landedAirtime * (2000f / 2f));
			dip = landingDip(landingSpeed);
			// the review's 0.8 s would shake every full ollie (2 * 820 / 2000 = 0.82 s in the air), so only flights
			// longer than 1 s (a drop, or a pop off a ramp or rail) shake the focus
			if (landedAirtime > 1f)
				jitterAge = 0f;
		}
		if (landedAirtime > 0f)
			airVerticalSpeed = 0f;
		dip -= dip * blend(6f, dt);
		updateJitter(dt);

		// pulls back up to 0.15 by 1500 u/s
		zoomFactor = 1f - 0.15f * Math.min(1f, absSpeed / 1500f);
	}

	/**
	 * A decaying jolt of the focus after a big air: up/down and across the view, at different frequencies per axis
	 * (11 Hz and 7 Hz) so it reads as a jolt rather than a sway. Decays at 18/s: 4 * e^(-18 * 0.25) = 0.04 units
	 * after a quarter second.
	 */
	private void updateJitter(float dt)
	{
		if (jitterAge >= JITTER_SECONDS)
		{
			jitterUp = 0f;
			jitterSide = 0f;
			return;
		}
		float amplitude = JITTER_AMPLITUDE * (float) Math.exp(-18f * jitterAge);
		jitterUp = amplitude * (float) Math.cos(2 * Math.PI * 11f * jitterAge);
		jitterSide = amplitude * (float) Math.sin(2 * Math.PI * 7f * jitterAge);
		jitterAge += dt;
	}

	private static float blend(float rate, float dt)
	{
		return 1f - (float) Math.exp(-rate * dt);
	}

	/** Turns the camera by hand (middle-button orbit on foot), radians clockwise. */
	public void orbit(float radians)
	{
		yaw = Angles.wrap(yaw + radians);
	}

	public float getFocusX()
	{
		// across the view: the camera looks along yaw (sin, cos), so its right is (cos, -sin)
		return x + jitterSide * (float) Math.cos(yaw);
	}

	public float getFocusY()
	{
		return y - jitterSide * (float) Math.sin(yaw);
	}

	/** Up-positive height of the look-at point. */
	public float getFocusHeight()
	{
		return height + FOCUS_HEIGHT - dip + jitterUp;
	}
}

package com.gielinorskate.camera;

import com.gielinorskate.physics.Angles;

/**
 * Which way the chase camera turns while on foot. Walking is camera-relative, so a camera that always swung
 * behind the body would spin round when walking toward it (S) and circle on a sidestep (A / D). It follows the
 * body only while the walk goes roughly away from it (within {@link #FOLLOW_CONE}: W and its diagonals, which
 * then steer like a turn); otherwise it holds still. Pure.
 */
public final class FootCamera
{
	/** The walk turns the camera only within this angle of where it looks (radians). */
	public static final float FOLLOW_CONE = (float) Math.toRadians(60);

	private FootCamera()
	{
	}

	/**
	 * The heading the camera should sit behind this frame.
	 *
	 * @param yaw where the camera looks now
	 * @param walkHeading the walker's body heading
	 * @param moving the walker is being moved (a direction key held)
	 */
	public static float targetHeading(float yaw, float walkHeading, boolean moving)
	{
		return moving && Angles.absDiff(walkHeading, yaw) <= FOLLOW_CONE + 1e-4f ? walkHeading : yaw;
	}
}

package com.gielinorskate.camera;

import com.gielinorskate.physics.SkaterState;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.gameval.VarClientID;

/** Applies {@link CameraRig} to the client's free camera. Call only on the client thread. */
@RequiredArgsConstructor
public final class SkateCamera
{
	private final Client client;
	private final CameraRig rig = new CameraRig();
	private int savedMode;
	/** The game's own zoom (fixed and resizable) and pitch target before skating, restored on exit. */
	private int savedZoomSmall, savedZoomBig, savedPitch;
	private boolean active;
	/** The chase zoom (wheel included), to save back to the config on exit. */
	@Getter
	private int baseZoom;
	private int lastZoom;
	/** Frames in a row the free camera would not stay on. */
	private int lostFrames;

	public void enter(float x, float y, float h, float heading, int zoom)
	{
		savedMode = client.getCameraMode();
		savedZoomSmall = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_SMALL);
		savedZoomBig = client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG);
		savedPitch = client.getCameraPitchTarget();
		active = true;
		client.setCameraMode(1); // the free camera
		client.setFreeCameraSpeed(0);
		client.setCameraPitchRelaxerEnabled(true);
		setBaseZoom(zoom);
		lastZoom = Integer.MIN_VALUE;
		lostFrames = 0;
		rig.reset(x, y, h, heading);
	}

	/** Mouse wheel while skating: positive notches zoom out (40 a notch), like the game's own wheel zoom. */
	public void adjustZoom(int notches)
	{
		setBaseZoom(baseZoom - notches * 40);
	}

	/** The chase zoom setting changed while skating; kept within 200-1400 (higher is closer), as the setting is. */
	public void setBaseZoom(int zoom)
	{
		baseZoom = Math.max(200, Math.min(1400, zoom));
	}

	/** Where the chase camera looks (radians, 0 = north, clockwise): on foot, W walks this way. */
	public float getYaw()
	{
		return rig.getYaw();
	}

	/** Turns the chase camera by hand (radians, clockwise); on foot it then holds there. */
	public void orbit(float radians)
	{
		rig.orbit(radians);
	}

	/**
	 * @param landedAirtime seconds in the air of a landing on this frame, 0 when none
	 * @param pitchJau14 camera pitch (JAU14, 16384 per turn; smaller is flatter)
	 * @return false once the free camera has stayed off for a second (the game or another plugin keeps it)
	 */
	public boolean update(float x, float y, float h, float cameraHeading, float speed, SkaterState state, float landedAirtime,
		float dt, int pitchJau14)
	{
		if (!active)
			return true;
		rig.update(x, y, h, cameraHeading, speed, state, landedAirtime, dt);
		// the game or another plugin can switch the free camera off: take it back, or wait a second for it
		if (client.getCameraMode() != 1)
			client.setCameraMode(1);
		if (client.getCameraMode() != 1)
			return ++lostFrames < 60;
		lostFrames = 0;

		client.setCameraFocalPointX(rig.getFocusX());
		client.setCameraFocalPointZ(rig.getFocusY());
		client.setCameraFocalPointY(-rig.getFocusHeight());
		client.setCameraYawTarget(CameraRig.yawJau14(rig.getYaw()));
		client.setCameraPitchTarget(pitchJau14);

		int zoom = Math.round(baseZoom * rig.getZoomFactor());
		// only re-run the zoom script when the zoom changes by more than 8
		if (Math.abs(zoom - lastZoom) > 8)
		{
			client.runScript(ScriptID.CAMERA_DO_ZOOM, zoom, zoom);
			lastZoom = zoom;
		}
		return true;
	}

	/**
	 * Puts the game's camera back as it was: mode, zoom and pitch target. The client has no getter for the free
	 * camera speed, so it gets the client default (12) back.
	 *
	 * @param pitchRelaxer whether the core Camera plugin's "Vertical camera" (relaxCameraPitch) is on
	 */
	public void exit(boolean pitchRelaxer)
	{
		if (!active)
			return;
		active = false;
		client.setCameraPitchRelaxerEnabled(pitchRelaxer);
		client.setFreeCameraSpeed(12);
		client.setCameraMode(savedMode);
		client.setCameraPitchTarget(savedPitch);
		if (savedZoomSmall > 0 && savedZoomBig > 0)
			client.runScript(ScriptID.CAMERA_DO_ZOOM, savedZoomSmall, savedZoomBig);
	}
}

package com.gielinorskate.controller;

import com.gielinorskate.Text;
import java.io.ByteArrayOutputStream;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.AccessLevel;
import lombok.AllArgsConstructor;

/**
 * A controller layout as a short text code to share: {@code RSK1:} then URL-safe base64 (no padding) of four bytes
 * per bound button: the button's id character, then the ids of its board, foot and air actions ({@link #SAME_AS_BOARD}
 * for no air action of its own). Reading a code is strict: a newer version, an unknown button or action, a button
 * twice, an action where it can't be bound, or a code over {@link #MAX_LENGTH} characters is refused with the reason.
 */
public final class LayoutCode
{
	public static final String PREFIX = "RSK";
	public static final int VERSION = 1;
	public static final int MAX_LENGTH = 512;
	/** The air byte of a button that does its board action in the air. */
	static final int SAME_AS_BOARD = 0xFF;

	private static final Pattern HEADER = Pattern.compile("RSK(\\d{1,3}):(.*)", Pattern.DOTALL);
	private static final Pattern BASE64URL = Pattern.compile("[A-Za-z0-9_-]*");

	/** A read code: the layout, or why it was refused. */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	public static final class Result
	{
		/** Null when refused. */
		public final PadPreset preset;
		/** Null when read. */
		public final String error;

		public boolean ok()
		{
			return preset != null;
		}
	}

	private LayoutCode()
	{
	}

	/** The code for {@code preset}. */
	public static String encode(PadPreset preset)
	{
		ByteArrayOutputStream bytes = new ByteArrayOutputStream();
		for (PadButton b : PadButton.values())
		{
			PadPreset.Binding binding = preset.binding(b);
			if (!binding.isNone())
			{
				bytes.write(b.id);
				bytes.write(binding.board.id);
				bytes.write(binding.foot.id);
				bytes.write(binding.air == null ? SAME_AS_BOARD : binding.air.id);
			}
		}
		return PREFIX + VERSION + ":" + Base64.getUrlEncoder().withoutPadding().encodeToString(bytes.toByteArray());
	}

	/** Reads {@code code} (surrounding spaces and line breaks are ignored). */
	public static Result decode(String code)
	{
		String c = code == null ? "" : code.trim();
		if (c.isEmpty())
			return refuse("empty");
		if (c.length() > MAX_LENGTH)
			return refuse("long", MAX_LENGTH);
		Matcher m = HEADER.matcher(c);
		if (!m.matches())
			return refuse("header", PREFIX + VERSION + ":");
		int version = Integer.parseInt(m.group(1));
		if (version != VERSION)
			return refuse(version > VERSION ? "newer" : "version", version);
		String body = m.group(2);
		if (!BASE64URL.matcher(body).matches())
			return refuse("chars");
		byte[] bytes;
		try
		{
			bytes = Base64.getUrlDecoder().decode(body);
			if (bytes.length % 4 != 0)
				throw new IllegalArgumentException();
		}
		catch (IllegalArgumentException e)
		{
			return refuse("missing");
		}
		PadPreset preset = new PadPreset();
		Set<PadButton> seen = EnumSet.noneOf(PadButton.class);
		for (int i = 0; i < bytes.length; i += 4)
		{
			PadButton button = PadButton.forId((char) (bytes[i] & 0xFF));
			if (button == null)
				return refuse("button");
			if (!seen.add(button))
				return refuse("twice", button.label);
			PadAction board = PadAction.forId(bytes[i + 1] & 0xFF);
			PadAction foot = PadAction.forId(bytes[i + 2] & 0xFF);
			int airId = bytes[i + 3] & 0xFF;
			PadAction air = PadAction.forId(airId);
			if (board == null || foot == null || airId != SAME_AS_BOARD && air == null)
				return refuse("action");
			preset = preset.with(button, new PadPreset.Binding(board, foot, air));
		}
		String problem = preset.problem();
		return problem != null ? refuse("problem", problem) : new Result(preset, null);
	}

	/** Refused, with the reason under "code." + why in text/overlay.properties. */
	private static Result refuse(String why, Object... args)
	{
		return new Result(null, Text.get("code." + why, args));
	}

	/**
	 * What changes going from {@code from} to {@code to}, one line per button and place ("LB, on the board: Hard
	 * tricks (Shift) to Brake"); empty when they are the same.
	 */
	public static List<String> changes(PadPreset from, PadPreset to)
	{
		List<String> out = new ArrayList<>();
		for (PadButton b : PadButton.values())
		{
			for (PadContext c : PadContext.values())
			{
				if (c == PadContext.AIR && from.binding(b).air == null && to.binding(b).air == null)
					// neither has an air action of its own: the board line says it
					continue;
				PadAction before = from.action(b, c);
				PadAction after = to.action(b, c);
				if (before != after)
					out.add(b.label + ", " + c.label.toLowerCase() + ": " + before.label + " to " + after.label);
			}
		}
		return out;
	}
}

package com.gielinorskate.controller;

import com.gielinorskate.Text;
import java.util.stream.Stream;

/**
 * Everything a pad button can do. A {@link PadPreset} binds each button to one action per {@link PadContext}. The
 * {@link #id} is what a layout code stores, so ids never change once released (names and labels may).
 */
public enum PadAction
{
	NONE,

	// ---- on the board
	/** Push: a new press pushes, held keeps pushing (W, or the old pad A / X). */
	PUSH,
	/** A push too; the board does not yet have its own mongo push. */
	MONGO_PUSH,
	/** A powerslide brake straight away (the brake key; with steer, a tight carve). */
	BRAKE,
	/** Hold to crouch and charge, let go to ollie (keyboard tricks' Space). */
	OLLIE,
	/** Grab with the left / front hand; the right stick aims it (Q). */
	GRAB_LEFT,
	/** Grab with the right / back hand (E). */
	GRAB_RIGHT,
	/** Shift: hard flips with a flick, a tight carve with steer, a brake held alone, a body flip with a lean. */
	HARD_MODIFIER,
	/** The lean keys, for grab-flips. */
	LEAN_FORWARD,
	LEAN_BACK,

	// ---- both
	/** Step off and carry the board, get on, or call it back (the board key). */
	BOARD_TOGGLE,
	/** Get up after a bail, or stop (R). */
	RESET,
	/** Stop skating (Esc). */
	STOP,
	/** Show or hide the controls card (H). */
	CONTROLS_CARD,

	// ---- on foot
	SPRINT,
	JUMP,
	DROP_PICKUP,
	/** Hold to turn the camera with the right stick (the middle-mouse drag). */
	CAMERA_ORBIT,

	// ---- button tricks (the Tony Hawk's American Wasteland preset; see com.gielinorskate.input.ButtonTricks)
	/** With a left stick / d-pad direction: a flip trick (kickflip, heelflip, ...); again mid-flip: a double. */
	FLIP_BUTTON,
	/** Held with a left stick / d-pad direction: a grab (melon, indy, ...), the same grabs as Q / E. */
	GRAB_BUTTON,
	/** Near a rail: held, the rail catches from further away. Rolling with no rail near: step off. */
	GRIND_BUTTON,
	/** The hard tricks modifier (as Shift), and in the air, held, a faster spin. */
	SPIN_ASSIST;

	/** Stored in layout codes; never reused or changed. */
	public final int id;
	public final String label;
	/** Can be bound on the board (and so in the air). */
	public final boolean onBoard;
	/** Can be bound on foot. */
	public final boolean onFoot;

	/** Its id, places and label, from text/overlay.properties ("pad.action." + name). */
	PadAction()
	{
		String[] f = Text.get("pad.action." + name()).split(",", 3);
		id = Integer.parseInt(f[0]);
		onBoard = f[1].contains("B");
		onFoot = f[1].contains("F");
		label = f[2];
	}

	/** True when a layout may bind this action in {@code context}. */
	public boolean allowedIn(PadContext context)
	{
		return context == PadContext.FOOT ? onFoot : onBoard;
	}

	/** The action with layout-code id {@code id}, or null. */
	public static PadAction forId(int id)
	{
		return Stream.of(values()).filter(a -> a.id == id).findFirst().orElse(null);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gielinorskate.controller;

import com.gielinorskate.Text;
import java.awt.event.KeyEvent;
import java.util.stream.Stream;

/**
 * A controller button and the pad key the universal AntiMicroX profile sends for it. The keys are ones keyboards
 * don't have or games rarely use (F13 to F24, and the navigation block), the same on every keyboard layout, so the
 * plugin can tell a pad button from a keyboard key. The profile never changes between presets: the plugin turns the
 * pad key into an action through the selected {@link PadPreset}.
 */
public enum PadButton
{
	A, B, X, Y, LB, RB, LT, RT, BACK, START, L3, R3,
	DPAD_UP(KeyEvent.VK_INSERT),
	DPAD_DOWN(KeyEvent.VK_DELETE),
	DPAD_LEFT(KeyEvent.VK_HOME),
	DPAD_RIGHT(KeyEvent.VK_END);

	/** The button's name, as players know it. */
	public final String label;
	/** Its one-character id in a layout code ({@link LayoutCode}); never changes once released. */
	public final char id;
	/** The Java key code the pad key arrives as. */
	public final int keyCode;
	/** The pad key's name ("F13", "Insert"). */
	public final String keyName;

	/** A button sent as function key F13 to F24 (its key name in text/overlay.properties). */
	PadButton()
	{
		this(0);
	}

	/** Its id, key name and label, from text/overlay.properties ("pad.button." + name). */
	PadButton(int keyCode)
	{
		String[] f = Text.get("pad.button." + name()).split(",", 3);
		id = f[0].charAt(0);
		keyName = f[1];
		label = f[2];
		this.keyCode = keyCode != 0 ? keyCode : KeyEvent.VK_F13 + Integer.parseInt(keyName.substring(1)) - 13;
	}

	/** The button whose pad key is {@code keyCode}, or null for any other key. */
	public static PadButton forKey(int keyCode)
	{
		return Stream.of(values()).filter(b -> b.keyCode == keyCode).findFirst().orElse(null);
	}

	/** The button with layout-code id {@code id}, or null. */
	public static PadButton forId(char id)
	{
		return Stream.of(values()).filter(b -> b.id == id).findFirst().orElse(null);
	}

	@Override
	public String toString()
	{
		return label;
	}
}

package com.gielinorskate.controller;

import lombok.AllArgsConstructor;

/** Where the skater is when a pad button is read: its binding can differ between them. */
@AllArgsConstructor
public enum PadContext
{
	/** On the board, on the ground (rolling, grinding, a manual or bailed). */
	BOARD("On the board"),
	/** On the board in the air. A binding with no air action uses its board action. */
	AIR("In the air"),
	/** Off the board, walking. */
	FOOT("On foot");

	public final String label;
}

package com.gielinorskate.controller;

import static com.gielinorskate.controller.PadAction.*;
import static com.gielinorskate.controller.PadButton.*;

import java.util.*;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import lombok.*;

/**
 * A controller layout: for each {@link PadButton}, the {@link PadAction} it does on the board, in the air and on
 * foot. Immutable; {@link #with} makes a changed copy. A button with no binding does nothing.
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@EqualsAndHashCode
@ToString
public final class PadPreset
{
	/** One button's actions. {@code air} null: in the air the button does its board action. */
	@EqualsAndHashCode
	public static final class Binding
	{
		public final PadAction board;
		public final PadAction foot;
		/** Null when the air action is the board one. */
		public final PadAction air;

		public Binding(PadAction board, PadAction foot, PadAction air)
		{
			this.board = Objects.requireNonNull(board);
			this.foot = Objects.requireNonNull(foot);
			this.air = air == board ? null : air;
		}

		public Binding(PadAction board, PadAction foot)
		{
			this(board, foot, null);
		}

		public PadAction get(PadContext context)
		{
			switch (context)
			{
				case FOOT:
					return foot;
				case AIR:
					return air != null ? air : board;
				default:
					return board;
			}
		}

		boolean isNone()
		{
			return board == NONE && foot == NONE && air == null;
		}

		/** A copy with {@code context}'s action set to {@code action}. */
		Binding with(PadContext context, PadAction action)
		{
			switch (context)
			{
				case FOOT:
					return new Binding(board, action, air);
				case AIR:
					return new Binding(board, foot, action);
				default:
					return new Binding(action, foot, air);
			}
		}

		@Override
		public String toString()
		{
			return board + " / " + foot + (air != null ? " / air " + air : "");
		}
	}

	private static final Binding EMPTY = new Binding(NONE, NONE);

	private static final PadPreset SKATE_3 = new PadPreset()
		.with(A, new Binding(PUSH, SPRINT))
		.with(X, new Binding(PUSH, JUMP))
		.with(B, new Binding(BRAKE, NONE))
		.with(Y, new Binding(BOARD_TOGGLE, BOARD_TOGGLE))
		// LB / RB were Shift: the trick modifier on the board, and Shift's sprint on foot
		.with(LB, new Binding(HARD_MODIFIER, SPRINT))
		.with(RB, new Binding(HARD_MODIFIER, SPRINT))
		// LT / RT were Q / E: grabs on the board, drop or pick up on foot
		.with(LT, new Binding(GRAB_LEFT, DROP_PICKUP))
		.with(RT, new Binding(GRAB_RIGHT, DROP_PICKUP))
		.with(BACK, new Binding(RESET, RESET))
		.with(START, new Binding(STOP, STOP))
		.with(DPAD_UP, new Binding(CONTROLS_CARD, CONTROLS_CARD));

	/**
	 * Tony Hawk's American Wasteland: A ollies (held, let go) and jumps on foot, X + a direction flips, B + a
	 * direction grabs (on foot it drops or picks up the board), Y grinds near a rail and otherwise steps off (on foot:
	 * back on), LB / RB are the hard tricks and spin faster in the air. The right stick turns the camera and a quick
	 * up-then-down on the left stick is a manual (see {@link #buttonTricks}).
	 */
	private static final PadPreset THAW = new PadPreset()
		.with(A, new Binding(OLLIE, JUMP))
		.with(X, new Binding(FLIP_BUTTON, NONE))
		.with(B, new Binding(GRAB_BUTTON, DROP_PICKUP))
		.with(Y, new Binding(GRIND_BUTTON, BOARD_TOGGLE))
		.with(LB, new Binding(SPIN_ASSIST, SPRINT))
		.with(RB, new Binding(SPIN_ASSIST, SPRINT))
		.with(BACK, new Binding(RESET, RESET))
		.with(START, new Binding(STOP, STOP))
		.with(DPAD_UP, new Binding(CONTROLS_CARD, CONTROLS_CARD));

	private final EnumMap<PadButton, Binding> bindings;

	/** An empty layout: every button does nothing. */
	public PadPreset()
	{
		this(new EnumMap<>(PadButton.class));
	}

	/** Skate 3: exactly the pad layout RuneSkate had before presets. */
	public static PadPreset skate3()
	{
		return SKATE_3;
	}

	/** Tony Hawk's American Wasteland: tricks on buttons, the right stick on the camera. */
	public static PadPreset thaw()
	{
		return THAW;
	}

	/**
	 * True when this layout does tricks with buttons (it binds a flip or grab button): the left stick and the d-pad
	 * then give the trick's direction, a quick up-then-down on the left stick is a manual, and the right stick turns
	 * the camera instead of flicking (flicks and the stick's manual tilt are off; mouse flicks still work).
	 */
	public boolean buttonTricks()
	{
		return bindings.values().stream().anyMatch(b -> Stream.of(b.board, b.foot, b.air)
			.anyMatch(a -> a == FLIP_BUTTON || a == GRAB_BUTTON));
	}

	/** The action {@code button} does in {@code context}; NONE when unbound. */
	public PadAction action(PadButton button, PadContext context)
	{
		return binding(button).get(context);
	}

	public Binding binding(PadButton button)
	{
		return bindings.getOrDefault(button, EMPTY);
	}

	/** A copy with {@code button} bound to {@code binding}. */
	public PadPreset with(PadButton button, Binding binding)
	{
		EnumMap<PadButton, Binding> copy = new EnumMap<>(bindings);
		copy.compute(button, (b, old) -> binding.isNone() ? null : binding);
		return new PadPreset(copy);
	}

	/** A copy with {@code button}'s action in {@code context} set to {@code action}. */
	public PadPreset with(PadButton button, PadContext context, PadAction action)
	{
		return with(button, binding(button).with(context, action));
	}

	/** The buttons that do {@code action} in {@code context}, in button order. */
	public List<PadButton> buttonsFor(PadAction action, PadContext context)
	{
		return Collections.unmodifiableList(Stream.of(PadButton.values()).filter(b -> action(b, context) == action)
			.collect(Collectors.toList()));
	}

	/**
	 * Why this layout can't be used (an action bound where it can't be, or one not built yet), or null when it
	 * is fine.
	 */
	public String problem()
	{
		for (Map.Entry<PadButton, Binding> e : bindings.entrySet())
		{
			Binding b = e.getValue();
			for (PadContext c : PadContext.values())
			{
				if (c == PadContext.AIR && b.air == null)
					continue;
				PadAction a = b.get(c);
				if (a != NONE && !a.allowedIn(c))
					return e.getKey().label + " can't do \"" + a.label + "\" " + c.label.toLowerCase();
			}
		}
		return null;
	}
}

package com.gielinorskate.controller;

import com.gielinorskate.GielinorSkateConfig.ControllerPreset;
import java.util.Objects;

/** The preset in use from the settings. */
public final class PadPresets
{
	private PadPresets()
	{
	}

	/** The layout of {@code preset}; Custom reads {@code customCode}, and a missing or broken one plays as Skate 3. */
	public static PadPreset resolve(ControllerPreset preset, String customCode)
	{
		if (preset == ControllerPreset.THAW)
			return PadPreset.thaw();
		LayoutCode.Result custom = preset == ControllerPreset.CUSTOM ? LayoutCode.decode(customCode) : null;
		return custom != null && custom.ok() ? custom.preset : PadPreset.skate3();
	}

	/** Remembers the last layout read, so a per-frame caller does not decode the same code again. */
	public static final class Cache
	{
		private ControllerPreset lastPreset;
		private String lastCode;
		private PadPreset last = PadPreset.skate3();

		public synchronized PadPreset get(ControllerPreset preset, String customCode)
		{
			if (preset != lastPreset || !Objects.equals(customCode, lastCode))
			{
				lastPreset = preset;
				lastCode = customCode;
				last = resolve(preset, customCode);
			}
			return last;
		}
	}

	/** True when Custom is chosen but its saved layout can't be read (it plays as Skate 3). */
	public static boolean customIsBroken(ControllerPreset preset, String customCode)
	{
		return preset == ControllerPreset.CUSTOM && !LayoutCode.decode(customCode).ok();
	}
}

package com.gielinorskate.controller;

import java.awt.event.KeyEvent;
import java.util.*;

/**
 * The "Test your pad" state: which pad buttons are down (from their pad keys), which arrow keys the left stick
 * holds, and how fast the right stick moves the mouse. It only watches: it never consumes or changes input. Fed
 * from the AWT thread and read by the painter on the same thread.
 */
public final class PadTester
{
	/** The right stick's speed decays to nothing this long (ms) after the cursor stops. */
	private static final long STICK_HOLD_MS = 150;
	/** Cursor speed (px/ms) drawn as a full tilt: AntiMicroX's full tilt in the profile. */
	public static final float FULL_TILT = 1.2f;

	/** Key codes of the pad keys and arrows held. */
	private final Set<Integer> held = new HashSet<>();
	private final Set<PadButton> seen = EnumSet.noneOf(PadButton.class);
	private boolean mouseKnown;
	private int lastX;
	private int lastY;
	private long lastMoveMs;
	private float vx;
	private float vy;

	/** A key went down or up; true when the tester shows it (a pad key or an arrow). */
	public synchronized boolean key(int keyCode, boolean pressed)
	{
		PadButton b = PadButton.forKey(keyCode);
		// the arrows are VK_LEFT, VK_UP, VK_RIGHT, VK_DOWN in a row
		if (b == null && (keyCode < KeyEvent.VK_LEFT || keyCode > KeyEvent.VK_DOWN))
			return false;
		if (!pressed)
			held.remove(keyCode);
		else if (held.add(keyCode) && b != null)
			seen.add(b);
		return true;
	}

	/**
	 * The cursor is at (x, y) on screen at {@code ms} (sampled a few times a second, or on each move): its motion
	 * is the right stick. A still cursor is a centred stick once {@link #STICK_HOLD_MS} has passed.
	 */
	public synchronized void mouse(int x, int y, long ms)
	{
		if (!mouseKnown)
		{
			mouseKnown = true;
			lastX = x;
			lastY = y;
			lastMoveMs = ms;
			return;
		}
		long dt = ms - lastMoveMs;
		if (x == lastX && y == lastY)
		{
			if (dt > STICK_HOLD_MS)
				vx = vy = 0;
			return;
		}
		if (dt > 0 && dt <= STICK_HOLD_MS)
		{
			vx = (x - lastX) / (float) dt;
			vy = (y - lastY) / (float) dt;
		}
		else
			// the first move after a pause: no speed to tell yet
			vx = vy = 0;
		lastX = x;
		lastY = y;
		lastMoveMs = ms;
	}

	/** Lets go of everything (the window lost focus, or the test closed). */
	public synchronized void reset()
	{
		held.clear();
		vx = vy = 0;
		mouseKnown = false;
	}

	public synchronized boolean isDown(PadButton b)
	{
		return held.contains(b.keyCode);
	}

	/** True once the button has been pressed since the tester opened. */
	public synchronized boolean wasSeen(PadButton b)
	{
		return seen.contains(b);
	}

	/** The left stick as the arrows it holds: x -1 / 0 / 1 (left / right), y -1 / 0 / 1 (up / down). */
	public synchronized int leftX()
	{
		return arrow(KeyEvent.VK_RIGHT) - arrow(KeyEvent.VK_LEFT);
	}

	public synchronized int leftY()
	{
		return arrow(KeyEvent.VK_DOWN) - arrow(KeyEvent.VK_UP);
	}

	private int arrow(int keyCode)
	{
		return held.contains(keyCode) ? 1 : 0;
	}

	/** The right stick's tilt from the cursor's speed, each axis clamped to -1..1 (y grows downward). */
	public synchronized float rightX()
	{
		return clamp(vx / FULL_TILT);
	}

	public synchronized float rightY()
	{
		return clamp(vy / FULL_TILT);
	}

	private static float clamp(float v)
	{
		return Math.max(-1f, Math.min(1f, v));
	}
}

package com.gielinorskate.feedback;

/**
 * Picks a joke chat line for a bail, at most one every 20 seconds. A wall bail and a bail that lost nothing get
 * their own lines; the rest rotate in order so the same joke never runs twice in a row. Pure.
 */
public final class BailLines
{
	public static final String WALL = "I can't reach that!";
	public static final String NOTHING_LOST = "Nothing interesting happens.";
	static final String[] ROTATION = {
		"Oh dear, you are bailed!",
		"Your board has been sent to Death's office.",
	};

	private float lastLineTime = -Float.MAX_VALUE;
	private int next;

	/**
	 * @param wall the bail ran into a blocker
	 * @param lostValue the combo value the bail threw away
	 * @return the line to post, or null while the cooldown runs
	 */
	public String onBail(float now, boolean wall, int lostValue)
	{
		if (now - lastLineTime < 20f)
			return null;
		lastLineTime = now;
		return wall ? WALL : lostValue <= 0 ? NOTHING_LOST : ROTATION[next++ % ROTATION.length];
	}
}

package com.gielinorskate.feedback;

import com.gielinorskate.Text;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;

/** The word shouted on landing a combo worth at least {@link #minValue} points. Pure. */
public enum Callout
{
	NICE,
	GZ,
	SPICY,
	/** Raid-loot purple. */
	PURPLE,
	PET_DROP;

	public final int minValue;
	public final String word;
	public final Color color;

	/** Its threshold and colour ("callout." + name) and word ("callout.word." + name) from text/overlay.properties. */
	Callout()
	{
		int[] v = Text.ints("callout." + name());
		minValue = v[0];
		color = new Color(v[1], v[2], v[3]);
		word = Text.get("callout.word." + name());
	}

	/** The biggest callout {@code value} earns, or null below {@link #NICE}. */
	public static Callout forValue(int value)
	{
		return Stream.of(values()).filter(c -> value >= c.minValue).reduce((lower, higher) -> higher).orElse(null);
	}

	/**
	 * Smaller lines under the callout word: "Clean" (only under a word: the HUD already says "Clean landing"),
	 * "xN Multi" from 10 distinct tricks, and "Max combo!" from 99 tricks in one combo.
	 */
	public static List<String> extras(Callout word, boolean clean, int multiplier, int trickCount)
	{
		List<String> lines = new ArrayList<>(3);
		if (word != null && clean)
			lines.add("Clean");
		if (multiplier >= 10)
			lines.add("x" + multiplier + " Multi");
		if (trickCount >= 99)
			lines.add("Max combo!");
		return lines;
	}

	/**
	 * Lines for the variety bonuses of a landed combo: "New trick +25%" ("3 new tricks +25%") for first landings
	 * this session, and "Long combo +1" for one longer than 8 s.
	 */
	public static List<String> varietyLines(int newTricks, boolean longCombo)
	{
		List<String> lines = new ArrayList<>(2);
		if (newTricks > 0)
			lines.add(newTricks == 1 ? "New trick +25%" : newTricks + " new tricks +25%");
		if (longCombo)
			lines.add("Long combo +1");
		return lines;
	}
}

package com.gielinorskate.feedback;

import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import net.runelite.api.SoundEffectID;
import net.runelite.api.gameval.SpotanimID;

/**
 * Sounds queued for a later frame: the level-up bells (ding, then dong 0.3 s later) and the session-goal chime,
 * which waits for the landing's own chime to finish. Pure.
 */
final class DelayedCues
{
	@AllArgsConstructor
	private static final class Pending
	{
		final SoundPicker.Cue cue;
		final float at;
	}

	private final List<Pending> pending = new ArrayList<>();

	/** The level-up bells, starting at {@code now}. */
	void levelUp(float now)
	{
		add(SoundEffectID.TOWN_CRIER_BELL_DING, now);
		add(SoundEffectID.TOWN_CRIER_BELL_DONG, now + 0.3f);
	}

	/**
	 * The session-goal chime (the combo-landed sound), 0.4 s after the landing's own (it would be throttled at the
	 * same time).
	 */
	void goalComplete(float now)
	{
		add(SoundPicker.COMBO_LANDED, now + 0.4f);
	}

	private void add(int id, float at)
	{
		pending.add(new Pending(new SoundPicker.Cue(id, 1f), at));
	}

	/** Removes and returns the cues due at {@code now}, in the order queued. */
	List<SoundPicker.Cue> due(float now)
	{
		List<SoundPicker.Cue> out = new ArrayList<>(2);
		pending.removeIf(p -> p.at <= now && out.add(p.cue));
		return out;
	}

	void clear()
	{
		pending.clear();
	}

	/** The level-up graphic over the skater: the bigger one for 99. */
	static int levelUpGraphic(int level)
	{
		return level >= 99 ? SpotanimID.LEVELUP_99_ANIM : SpotanimID.LEVELUP_ANIM;
	}
}

package com.gielinorskate.feedback;

import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.scoring.ComboScorer;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.gameval.SpotanimID;

/** Chooses which graphics (spotanims) a skate frame spawns at the skater. Pure. */
final class EffectPicker
{
	/** Spark bursts every 0.15 s while grinding; the first comes on contact. */
	private final Repeater sparks = new Repeater(0.15f, true);

	/**
	 * @param grinding the skater is on a rail this frame
	 * @param lastAirtime seconds in the air of the latest landing
	 * @param newResult a combo that resolved this frame, or null
	 */
	List<Integer> pick(List<SkateEvent> events, boolean grinding, float lastAirtime, ComboScorer.Result newResult,
		float dt)
	{
		List<Integer> ids = new ArrayList<>(2);
		// only landings after more than 0.4 s of air raise dust (not curb drops and bumps)
		if (events.contains(SkateEvent.LAND) && lastAirtime > 0.4f)
			ids.add(SpotanimID.EMOTE_DUSTSTAMP_SPOT);
		if (sparks.update(grinding, dt))
			ids.add(SpotanimID.WARGUILD_SPARKS_SPOTANIM);
		if (events.contains(SkateEvent.BAIL))
			ids.add(SpotanimID.SMOKEPUFF_LARGE);
		if (newResult != null && newResult.isLanded() && Callout.forValue(newResult.value) == Callout.PET_DROP)
			// the Party emote's confetti: a plain celebration for a huge combo (nothing that looks like a real drop)
			ids.add(SpotanimID.FX_EMOTE_PARTY01_ACTIVE);
		return ids;
	}
}

package com.gielinorskate.feedback;

import java.util.*;
import java.util.stream.Collectors;
import lombok.AllArgsConstructor;
import lombok.RequiredArgsConstructor;

/**
 * Live effects with an expiry time, capped at {@link #capacity}: adding to a full set evicts the oldest. Pure;
 * the caller despawns whatever comes back.
 */
@RequiredArgsConstructor
final class EffectSlots<T>
{
	@AllArgsConstructor
	private static final class Slot<T>
	{
		final T item;
		final float expiresAt;
	}

	private final int capacity;
	private final Deque<Slot<T>> slots = new ArrayDeque<>();

	/** Adds {@code item} living {@code lifetime} seconds; returns the evicted oldest item when full, else null. */
	T add(T item, float now, float lifetime)
	{
		T evicted = slots.size() >= capacity ? slots.pollFirst().item : null;
		slots.addLast(new Slot<>(item, now + lifetime));
		return evicted;
	}

	/** Removes and returns every item whose time is up. */
	List<T> expire(float now)
	{
		List<T> done = new ArrayList<>(2);
		slots.removeIf(s -> now >= s.expiresAt && done.add(s.item));
		return done;
	}

	/** Removes and returns everything. */
	List<T> clear()
	{
		List<T> all = slots.stream().map(s -> s.item).collect(Collectors.toList());
		slots.clear();
		return all;
	}

	int size()
	{
		return slots.size();
	}
}

package com.gielinorskate.feedback;

/**
 * Pure animation curves for the score HUD. Every function takes the seconds since its trigger (score-clock
 * time); a negative or very large age gives the resting value.
 */
public final class HudAnim
{
	/** The level banner every ten levels stays up for this long, fading over the last 0.8 s. */
	public static final float BANNER_SECONDS = 4f;

	private HudAnim()
	{
	}

	/** Scale of the newest trick line {@code age} seconds after it appeared: 1.35 to 1 over 0.12 s, easing out. */
	public static float popScale(float age)
	{
		return popScale(age, 0.12f);
	}

	/** Scale of a callout word: pops in like a trick line, but a little slower so the bigger word reads as a punch. */
	public static float calloutScale(float age)
	{
		return popScale(age, 0.18f);
	}

	private static float popScale(float age, float seconds)
	{
		return age < 0f || age >= seconds ? 1f : 1.35f + (1f - 1.35f) * easeOutBack(age / seconds);
	}

	/** Ring stroke multiplier {@code age} seconds after the multiplier rose: 1.4 down to 1. */
	public static float ringPulse(float age)
	{
		return 1f + 0.4f * ringFlash(age);
	}

	/** White flash strength on the ring, 1 down to 0 over 0.15 s, {@code age} seconds after the multiplier rose. */
	public static float ringFlash(float age)
	{
		return age < 0f || age >= 0.15f ? 0f : 1f - age / 0.15f;
	}

	/** The part of {@code value} shown {@code age} seconds after a landing (ease-out cubic over 0.3 s). */
	public static int countUp(int value, float age)
	{
		if (age >= 0.3f)
			return value;
		if (age <= 0f)
			return 0;
		float u = 1f - age / 0.3f;
		return Math.round(value * (1f - u * u * u));
	}

	/** Horizontal HUD offset (px) {@code age} seconds after a bail. */
	public static int shakeX(float age)
	{
		return shake(age, 25f, 0f);
	}

	/** Vertical HUD offset (px) {@code age} seconds after a bail. */
	public static int shakeY(float age)
	{
		return shake(age, 19f, (float) (Math.PI / 2));
	}

	/**
	 * A bail shakes the HUD cluster by up to 3 px for 0.2 s, at a different frequency (Hz) on each axis so the
	 * motion is a jitter rather than a line.
	 */
	private static int shake(float age, float hz, float phase)
	{
		return age < 0f || age >= 0.2f ? 0
			: Math.round(3 * (1f - age / 0.2f) * (float) Math.sin(2 * Math.PI * hz * age + phase));
	}

	/** How far (0..1 of its path) an XP drop has risen {@code age} seconds after the landing (ease-out over 1.2 s). */
	public static float xpDropRise(float age)
	{
		if (age <= 0f)
			return 0f;
		if (age >= 1.2f)
			return 1f;
		float u = 1f - age / 1.2f;
		return 1f - u * u;
	}

	/** Opacity 0..1 of an XP drop (up 1.2 s, fading over the last 0.4 s); 0 once it is done. */
	public static float xpDropAlpha(float age)
	{
		return fade(age, 1.2f, 0.4f);
	}

	/** Opacity 0..1 of a callout (up 1.6 s, fading over the last 0.4 s); 0 once it is done. */
	public static float calloutAlpha(float age)
	{
		return fade(age, 1.6f, 0.4f);
	}

	/** Opacity of the level banner ("Skating level 50!") {@code age} seconds after the level-up. */
	public static float bannerAlpha(float age)
	{
		return fade(age, BANNER_SECONDS, 0.8f);
	}

	/** Opacity of the "Goal complete" line (named on the HUD for 3 s) {@code age} seconds after a goal was done. */
	public static float goalFlashAlpha(float age)
	{
		return fade(age, 3f, 0.4f);
	}

	private static float fade(float age, float total, float fadeSeconds)
	{
		return age < 0f || age >= total ? 0f : age <= total - fadeSeconds ? 1f : (total - age) / fadeSeconds;
	}

	/** 0 at u = 0, 1 at u = 1, overshooting 1 a little in between (the usual 1.70158: about 10% overshoot). */
	static float easeOutBack(float u)
	{
		float t = u - 1f;
		return 1f + (1.70158f + 1f) * t * t * t + 1.70158f * t * t;
	}
}

package com.gielinorskate.feedback;

/** Fires every {@link #interval} seconds while a condition holds (grind tinks, grind sparks). Pure. */
final class Repeater
{
	private final float interval;
	private final boolean fireOnStart;
	private float elapsed;
	private boolean running;

	/** @param fireOnStart fire on the first active frame too, not only after the first interval */
	Repeater(float interval, boolean fireOnStart)
	{
		this.interval = interval;
		this.fireOnStart = fireOnStart;
	}

	/** True on the frames it fires: at most once a frame, so a long frame never bursts. */
	boolean update(boolean active, float dt)
	{
		if (!active)
		{
			running = false;
			return false;
		}
		if (!running)
		{
			running = true;
			elapsed = 0f;
			return fireOnStart;
		}
		elapsed += dt;
		if (elapsed >= interval)
		{
			// keep the remainder so the beat stays even, but never owe more than one
			elapsed = Math.min(elapsed - interval, interval);
			return true;
		}
		return false;
	}
}

package com.gielinorskate.feedback;

import com.gielinorskate.SkateChat;
import com.gielinorskate.GielinorSkateConfig;
import com.gielinorskate.physics.*;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.TrickEvent;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

/**
 * Sounds, particles and bail jokes for one skate session, driven once a frame by the session after it has
 * drained the physics events and fed the scorer. Each part follows its setting. Everything is client-side: it
 * plays local sounds, draws local objects and posts local chat lines. A failure here turns feedback off for the
 * session but never stops skating. Client thread.
 */
@Slf4j
@Singleton
public class SkateFeedback
{
	@Inject
	private Client client;
	@Inject
	private SkateChat skateChat;
	@Inject
	private GielinorSkateConfig config;
	@Inject
	private ComboScorer scorer;
	@Inject
	private SkateSounds sounds;
	@Inject
	private SpotEffects spots;
	private final SoundPicker soundPicker = new SoundPicker();
	private final EffectPicker effectPicker = new EffectPicker();
	private final BailLines bailLines = new BailLines();
	private final DelayedCues delayed = new DelayedCues();

	private int seenResults;
	private boolean failed;
	/** A level reached since the last frame, for its graphic over the skater; 0 when none. */
	private int pendingLevelUp;

	public void onSkateStart()
	{
		seenResults = scorer.resultSequence();
		failed = false;
		pendingLevelUp = 0;
		delayed.clear();
	}

	/**
	 * A Skating level was reached: next frame the level-up graphic shows over the skater (the 99 one at 99) and
	 * the bells ring, each following its setting.
	 */
	public void onLevelUp(int level, float now)
	{
		pendingLevelUp = level;
		delayed.levelUp(now);
	}

	/** A session goal was completed: the combo-landed chime, just after the landing's own. */
	public void onGoalComplete(float now)
	{
		delayed.goalComplete(now);
	}

	/**
	 * @param hitThisFrame the skater ran into a blocker this frame (read before the hit is cleared), which makes
	 *     a bail on this frame a wall bail
	 * @param now score-clock seconds
	 */
	public void onFrame(SkatePhysics physics, List<SkateEvent> events, List<TrickEvent> trickEvents,
		boolean hitThisFrame, float now, float dt)
	{
		if (failed)
			return;
		try
		{
			int sequence = scorer.resultSequence();
			ComboScorer.Result newResult = sequence != seenResults ? scorer.lastResult() : null;
			seenResults = sequence;
			boolean grinding = physics.getState() == SkaterState.GRINDING;

			// pickers run every frame (their repeat timers must see the whole grind), the output only when enabled
			// (both pickers return a fresh list)
			List<SoundPicker.Cue> cues = soundPicker.pick(events, trickEvents, grinding, physics.getLastLandingSpeed(),
				newResult, dt);
			cues.addAll(delayed.due(now));
			if (config.soundEffects())
				sounds.play(cues, now, config.soundVolume());

			List<Integer> graphics = effectPicker.pick(events, grinding, physics.getLastAirtime(), newResult, dt);
			if (pendingLevelUp > 0)
			{
				graphics.add(DelayedCues.levelUpGraphic(pendingLevelUp));
				pendingLevelUp = 0;
			}
			if (config.particleEffects())
			{
				for (int id : graphics)
					spots.spawn(id, physics.getX(), physics.getY(), physics.getH(), client.getTopLevelWorldView(), now);
				spots.update(now);
			}
			else if (spots.liveCount() > 0)
				spots.clear();

			if (newResult != null && newResult.isBailed() && config.funnyBailMessages())
			{
				String line = bailLines.onBail(now, hitThisFrame, newResult.value);
				if (line != null)
					skateChat.send(line);
			}
		}
		catch (RuntimeException e)
		{
			failed = true;
			log.warn("Skate feedback failed; sounds and effects are off until the next skate session", e);
			safely("clear skate effects", spots::clear);
		}
	}

	/** Removes any particles still showing. */
	public void onSkateEnd()
	{
		pendingLevelUp = 0;
		delayed.clear();
		safely("clear skate effects", spots::clear);
	}

	/** Runs {@code action}, logging a failure instead of passing it on. */
	private static void safely(String what, Runnable action)
	{
		try
		{
			action.run();
		}
		catch (RuntimeException e)
		{
			log.debug("Failed to " + what, e);
		}
	}
}

package com.gielinorskate.feedback;

import java.util.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Preferences;

/**
 * Plays {@link SoundPicker} cues through the client, following the player's sound-effect volume (muted means
 * silent) scaled by the plugin's volume setting. Each sound plays at most once per {@link #MIN_GAP_SECONDS}, so
 * bursts of events never stack one sound. Client thread.
 */
final class SkateSounds
{
	static final float MIN_GAP_SECONDS = 0.1f;

	@Inject
	private Client client;
	private final Map<Integer, Float> lastPlayed = new HashMap<>();

	/** @param volumePercent the plugin's "Sound volume" setting, 0..100 */
	void play(List<SoundPicker.Cue> cues, float now, int volumePercent)
	{
		if (cues.isEmpty() || volumePercent <= 0)
			return;
		Preferences prefs = client.getPreferences();
		int playerVolume = prefs.getSoundEffectVolume();
		if (playerVolume <= 0)
			return;
		for (SoundPicker.Cue cue : cues)
		{
			int volume = Math.round(playerVolume * cue.volume * Math.min(100, volumePercent) / 100f);
			if (volume <= 0 || !allow(cue.id, now))
				continue;
			// playSoundEffect(id, volume) uses the player's own volume unless it is muted, so set it for the one
			// sound and put it straight back, as the core Metronome plugin does
			prefs.setSoundEffectVolume(volume);
			try
			{
				client.playSoundEffect(cue.id, volume);
			}
			finally
			{
				prefs.setSoundEffectVolume(playerVolume);
			}
		}
	}

	/** True (and remembered) when {@code soundId} may play at {@code now}. */
	boolean allow(int soundId, float now)
	{
		Float last = lastPlayed.get(soundId);
		if (last != null && now - last < MIN_GAP_SECONDS)
			return false;
		lastPlayed.put(soundId, now);
		return true;
	}
}

package com.gielinorskate.feedback;

import static net.runelite.api.SoundEffectID.*;

import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.*;
import java.util.ArrayList;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.ToString;

/**
 * Chooses which game sounds a skate frame makes, and how loud relative to the player's sound-effect volume.
 * All IDs are the client's own sound effects (net.runelite.api.SoundEffectID; there is no gameval sound list
 * in the API). Pure.
 */
final class SoundPicker
{
	/** One sound to play: its ID and a volume fraction 0..1 of the player's sound-effect volume. */
	@AllArgsConstructor
	@ToString
	static final class Cue
	{
		final int id;
		final float volume;
	}

	static final int COMBO_LANDED = GE_COIN_TINKLE;

	/** Grind tinks every 0.25 s while grinding. */
	private final Repeater grindTinks = new Repeater(0.25f, false);

	/**
	 * @param grinding the skater is on a rail this frame
	 * @param landingSpeed downward speed of the latest landing (u/s)
	 * @param newResult a combo that resolved this frame, or null
	 */
	List<Cue> pick(List<SkateEvent> events, List<TrickEvent> trickEvents, boolean grinding, float landingSpeed,
		ComboScorer.Result newResult, float dt)
	{
		List<Cue> cues = new ArrayList<>(4);
		if (events.contains(SkateEvent.POP))
			cues.add(new Cue(UI_BOOP, 0.8f));
		for (TrickEvent e : trickEvents)
		{
			if (e.type == TrickEvent.Type.TRICK && isBig(e.trick))
				cues.add(new Cue(FIRE_WOOSH, 1f));
			else if (e.type == TrickEvent.Type.HOLD_START && e.trick != null && e.trick.kind == TrickKind.GRIND)
			{
				cues.add(new Cue(SMITH_ANVIL_TONK, 1f)); // grind lock
			}
		}
		if (events.contains(SkateEvent.LAND))
			// full volume at a landing speed of 1400 u/s down: a flat-ground ollie lands at about its pop speed,
			// ollieImpulse = 820 u/s (0.59 of full); a drop off a ledge lands harder
			cues.add(new Cue(ITEM_DROP, Math.max(0.3f, Math.min(1f, landingSpeed / 1400f))));
		if (grindTinks.update(grinding, dt))
			cues.add(new Cue(MINING_TINK, 0.5f));
		if (events.contains(SkateEvent.BAIL))
			cues.add(new Cue(MAGIC_SPLASH_BOING, 1f));
		if (newResult != null && newResult.isLanded())
			// a combo worth a "Gz!" callout gets the bigger chime
			cues.add(new Cue(newResult.value >= Callout.GZ.minValue ? GE_ADD_OFFER_DINGALING : COMBO_LANDED, 1f));
		return cues;
	}

	/** A full (360) board spin, a double flip, or a body flip: worth a woosh. */
	static boolean isBig(Trick trick)
	{
		return trick != null && (Math.abs(trick.yawTurns) >= 1f || Math.abs(trick.rollTurns) >= 2f
			|| trick.bodyFlipTurns != 0f);
	}
}

package com.gielinorskate.feedback;

import java.util.*;
import javax.inject.Inject;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;

/**
 * Client-side particle bursts: a game graphic (spotanim) drawn once as a RuneLiteObject at a point, then
 * removed. The graphic's model and animation come from its cache definition ({@link SpotanimDef}). At most
 * 8 are alive at once; the oldest makes way. Nothing here is seen by other players or the
 * server. Client thread.
 */
@Slf4j
final class SpotEffects
{
	/**
	 * Upper bound on a graphic's life: long enough for the level-99 fireworks to play out in full, short enough
	 * that a bad length in the cache cannot keep an object alive for long.
	 */
	static final float MAX_LIFE = 8f;
	/** Life of a graphic without an animation, or with one whose length is unknown. */
	private static final float DEFAULT_LIFE = 0.8f;
	/** A model may still be loading; give up on a graphic after this many tries. */
	private static final int MAX_LOAD_TRIES = 30;

	/** A graphic ready to draw. */
	@AllArgsConstructor
	private static final class Loaded
	{
		final Model model;
		final Animation animation;
		final float life;
	}

	@Inject
	private Client client;
	private final EffectSlots<RuneLiteObject> live = new EffectSlots<>(8);
	private final Map<Integer, Loaded> loaded = new HashMap<>();
	/** Load attempts per graphic still loading; a graphic at {@link #MAX_LOAD_TRIES} is never tried again. */
	private final Map<Integer, Integer> tries = new HashMap<>();

	/** Shows graphic {@code spotanimId} at local (x, y), height h (up-positive, as physics). */
	void spawn(int spotanimId, float x, float y, float h, WorldView wv, float now)
	{
		Loaded graphic = load(spotanimId);
		if (graphic == null)
			return;
		RuneLiteObject obj = client.createRuneLiteObject();
		obj.setModel(graphic.model);
		if (graphic.animation != null)
		{
			obj.setAnimation(graphic.animation);
			obj.setShouldLoop(false);
		}
		obj.setLocation(new LocalPoint(Math.round(x), Math.round(y), wv), wv.getPlane());
		// setLocation puts it on the tile's ground; a rail or a ledge can be higher (RuneLite z grows downward)
		obj.setZ(-Math.round(h));
		obj.setActive(true);
		RuneLiteObject evicted = live.add(obj, now, graphic.life);
		if (evicted != null)
			evicted.setActive(false);
	}

	/** Removes graphics whose time is up. */
	void update(float now)
	{
		live.expire(now).forEach(obj -> obj.setActive(false));
	}

	int liveCount()
	{
		return live.size();
	}

	void clear()
	{
		live.clear().forEach(obj -> obj.setActive(false));
	}

	private Loaded load(int spotanimId)
	{
		Loaded cached = loaded.get(spotanimId);
		if (cached != null)
			return cached;
		int attempt = tries.getOrDefault(spotanimId, 0);
		if (attempt >= MAX_LOAD_TRIES)
			return null;
		tries.put(spotanimId, attempt + 1);

		IndexDataBase config = client.getIndexConfig();
		SpotanimDef def = SpotanimDef.parse(config == null ? null : config.loadData(SpotanimDef.CONFIG_ARCHIVE, spotanimId));
		if (def == null)
		{
			tries.put(spotanimId, MAX_LOAD_TRIES);
			log.debug("Skate effect {}: no readable graphic definition", spotanimId);
			return null;
		}
		ModelData data = client.loadModelData(def.modelId);
		if (data == null)
		{
			return null; // still loading: try again next time
		}
		// copies first: the loaded model data may be shared with the game's own use of it
		if (def.recolorFrom != null)
		{
			data = data.shallowCopy().cloneColors();
			for (int i = 0; i < def.recolorFrom.length; i++)
				data.recolor(def.recolorFrom[i], def.recolorTo[i]);
		}
		if (def.resizeX != SpotanimDef.DEFAULT_RESIZE || def.resizeY != SpotanimDef.DEFAULT_RESIZE)
			data = data.shallowCopy().cloneVertices().scale(def.resizeX, def.resizeY, def.resizeX);
		// lit as the client lights a spotanim's model: its ambient and contrast on top of these bases, with this
		// light direction (as the game's own graphic definition does)
		Model model = data.light(64 + def.ambient, 850 + def.contrast, -30, -50, -30);
		if (model == null)
			return null;
		Animation animation = def.animationId >= 0 ? client.loadAnimation(def.animationId) : null;
		Loaded graphic = new Loaded(model, animation, animation == null ? DEFAULT_LIFE : animation.isMayaAnim()
			? lifeSeconds(true, animation.getDuration(), null) : lifeSeconds(false, 0, animation.getFrameLengths()));
		loaded.put(spotanimId, graphic);
		tries.remove(spotanimId);
		return graphic;
	}

	/**
	 * How long a graphic lives: the animation's own length (summed frame lengths, or a maya animation's duration,
	 * both in 20 ms client cycles), bounded to [0.3 s, {@link #MAX_LIFE}]; {@link #DEFAULT_LIFE} when
	 * the length is unknown. Pure.
	 */
	static float lifeSeconds(boolean maya, int mayaDuration, int[] frameLengths)
	{
		if (maya ? mayaDuration <= 0 : frameLengths == null || frameLengths.length == 0)
			return DEFAULT_LIFE;
		long cycles = maya ? mayaDuration : Arrays.stream(frameLengths).asLongStream().sum();
		return Math.max(0.3f, Math.min(MAX_LIFE, cycles * 0.02f));
	}
}

package com.gielinorskate.feedback;

import java.nio.BufferUnderflowException;
import java.nio.ByteBuffer;

/**
 * The parts of a spotanim (graphic) definition needed to draw one as a RuneLiteObject: the API has no spotanim
 * definition lookup, so this decodes the cache entry (config archive {@link #CONFIG_ARCHIVE}). Opcodes follow
 * RuneLite's cache SpotAnimLoader. Pure.
 */
final class SpotanimDef
{
	/** Config index group holding spotanim definitions (RuneLite cache ConfigType.SPOTANIM). */
	static final int CONFIG_ARCHIVE = 13;
	static final int DEFAULT_RESIZE = 128;

	int modelId = -1;
	int animationId = -1;
	int resizeX = DEFAULT_RESIZE;
	int resizeY = DEFAULT_RESIZE;
	int ambient;
	int contrast;
	short[] recolorFrom;
	short[] recolorTo;

	/** Decodes one definition; null for missing, truncated or unknown data (that graphic is then skipped). */
	static SpotanimDef parse(byte[] data)
	{
		if (data == null)
			return null;
		// big-endian reads; running off the end throws BufferUnderflowException
		ByteBuffer in = ByteBuffer.wrap(data);
		SpotanimDef def = new SpotanimDef();
		try
		{
			while (true)
			{
				switch (in.get() & 0xFF)
				{
					case 0:
						return def.modelId >= 0 ? def : null;
					case 1:
						def.modelId = u16(in);
						break;
					case 2:
						def.animationId = u16(in);
						break;
					case 3:
						def.modelId = in.getInt();
						break;
					case 4:
						def.resizeX = u16(in);
						break;
					case 5:
						def.resizeY = u16(in);
						break;
					case 6:
					case 42:
						in.getShort(); // rotation, full recolour
						break;
					case 7:
						def.ambient = in.get() & 0xFF;
						break;
					case 8:
						def.contrast = in.get() & 0xFF;
						break;
					case 9:
						while (in.get() != 0)
						{
							// skip the debug name up to its terminator
						}
						break;
					case 10:
						break; // not clickable
					case 40:
						int n = in.get() & 0xFF;
						def.recolorFrom = new short[n];
						def.recolorTo = new short[n];
						for (int i = 0; i < n; i++)
						{
							def.recolorFrom[i] = in.getShort();
							def.recolorTo[i] = in.getShort();
						}
						break;
					case 41:
						int retextures = in.get() & 0xFF;
						in.position(in.position() + 4 * retextures); // retextures: left as they are
						break;
					default:
						return null;
				}
			}
		}
		catch (BufferUnderflowException | IllegalArgumentException e)
		{
			return null;
		}
	}

	private static int u16(ByteBuffer in)
	{
		return in.getShort() & 0xFFFF;
	}
}

package com.gielinorskate.input;

/**
 * Tap / hold detection for the board key (F): a press is reported at once, then either a tap (released within
 * {@link #HOLD_MS}) or one hold (held for {@link #HOLD_MS}, reported while still held, or on release when no poll
 * saw it in time). Key repeats while held are ignored. Pure, with explicit times; synchronized because keys
 * arrive on the AWT thread and are polled on the client thread.
 */
public final class BoardKey
{
	/** Held this long (ms) it is a hold (acts like a press: a tap already calls a far board back). */
	public static final long HOLD_MS = 1000;

	/** What happened since the last {@link #poll}. */
	public static final class Edges
	{
		/** The key went down (not a repeat). */
		public boolean pressed;
		/** The key came up within {@link #HOLD_MS} of going down. */
		public boolean tapped;
		/** The key has been held {@link #HOLD_MS} (once per press). */
		public boolean held;
	}

	private boolean down;
	private long downAt;
	private boolean holdReported;
	private boolean pressPending;
	private boolean tapPending;
	private boolean holdPending;

	/** The key went down or up at {@code now}. */
	public void set(boolean down, long now)
	{
		if (down)
			press(now);
		else
			release(now);
	}

	public synchronized void press(long now)
	{
		if (down)
		{
			return; // a key repeat
		}
		down = true;
		downAt = now;
		holdReported = false;
		pressPending = true;
	}

	public synchronized void release(long now)
	{
		if (!down)
			return;
		down = false;
		if (!holdReported)
		{
			boolean held = now - downAt >= HOLD_MS;
			holdPending |= held;
			tapPending |= !held;
		}
	}

	/** Fills {@code out} with what happened since the last poll (a hold is reported once it is due). */
	public synchronized void poll(long now, Edges out)
	{
		if (down && !holdReported && now - downAt >= HOLD_MS)
			holdPending = true;
		holdReported |= holdPending;
		out.pressed = pressPending;
		out.tapped = tapPending;
		out.held = holdPending;
		pressPending = tapPending = holdPending = false;
	}

	/** Forgets everything (focus lost, skating toggled). */
	public synchronized void reset()
	{
		down = holdReported = pressPending = tapPending = holdPending = false;
	}
}

package com.gielinorskate.input;

import static com.gielinorskate.tricks.Gesture.Direction.*;

import com.gielinorskate.tricks.*;
import com.gielinorskate.tricks.Gesture.Direction;

/**
 * Button tricks (the Tony Hawk's American Wasteland preset): a flip or grab button with a direction held on the left
 * stick or the d-pad. Each flip is turned into the {@link Gesture} its flick (or trick key) would make, so physics,
 * {@link TrickCatalog}, scoring and the animations treat it exactly like that flick; a second press mid-flip is a
 * re-flick (a double, then a triple). Each grab is a hand and an aim for {@link Grabs#pick}, so it is the same grab,
 * with the same tweak, as Q / E aimed with the mouse. Pure.
 *
 * <p>Directions are in stick terms: up is the stick pushed away from the player. With the hard tricks modifier held
 * a flip is the hard version, as a Shift flick is (kickflip: hardflip, heelflip: inward heelflip, shove-it: bigspin).
 */
public final class ButtonTricks
{
	/** How long a flip or grab press waits for its direction (two d-pad buttons for a diagonal never come at once). */
	public static final long DIRECTION_WAIT_MS = 50;

	private ButtonTricks()
	{
	}

	/** The direction held (opposites cancel), or null when none. */
	public static Direction direction(boolean up, boolean down, boolean left, boolean right)
	{
		int v = (up ? 1 : 0) - (down ? 1 : 0);
		int h = (right ? 1 : 0) - (left ? 1 : 0);
		if (v > 0)
			return h < 0 ? UP_LEFT : h > 0 ? UP_RIGHT : UP;
		if (v < 0)
			return h < 0 ? DOWN_LEFT : h > 0 ? DOWN_RIGHT : DOWN;
		return h < 0 ? LEFT : h > 0 ? RIGHT : null;
	}

	/**
	 * The flick a flip button press stands for: left kickflip, right heelflip, up impossible (the Shift ollie), down
	 * pop shove-it, up-left / up-right varial kickflip / heelflip, down-left 360 flip, down-right hardflip (the Shift
	 * kickflip), none a kickflip.
	 *
	 * @param modified the hard tricks modifier is held as the trick fires
	 */
	public static Gesture flip(Direction d, boolean modified)
	{
		Direction flick = d == UP ? UP : d == DOWN ? LEFT : d == RIGHT || d == UP_RIGHT ? UP_RIGHT : UP_LEFT;
		float turn = d == UP_LEFT || d == UP_RIGHT ? KeyboardTricks.VARIAL_TURN
			: d == DOWN_LEFT ? KeyboardTricks.FULL_TURN : 0f;
		return new Gesture(flick, false, turn, modified || d == UP || d == DOWN_RIGHT);
	}

	/** The trick a flip button press does (as a fresh flip; mid-flip see {@link TrickCatalog#upgrade}). */
	public static Trick flipTrick(Direction d, boolean modified)
	{
		return TrickCatalog.forGesture(flip(d, modified));
	}

	/**
	 * The hand a grab button grabs with: the left (front) hand for melon, nosegrab, tailgrab, mute and the default
	 * indy; the right (back) hand for indy, crail and stalefish. With {@link #grabAim} it picks the grab.
	 */
	public static boolean grabLeftHand(Direction d)
	{
		return d != RIGHT && d != UP_LEFT && d != DOWN_LEFT && d != DOWN_RIGHT;
	}

	/**
	 * Where a grab button's grab is aimed: left melon, right indy, up nosegrab, down tailgrab, up-left crail, up-right
	 * mute, down-left stalefish, down-right indy, none the default indy. The aim never moves after the press.
	 */
	public static Grabs.Aim grabAim(Direction d)
	{
		return d == null ? null : d == LEFT || d == DOWN_LEFT ? Grabs.Aim.HEEL
			: d == RIGHT || d == UP_RIGHT || d == DOWN_RIGHT ? Grabs.Aim.TOE
			: d == UP || d == UP_LEFT ? Grabs.Aim.NOSE : Grabs.Aim.TAIL;
	}

	/** The grab a grab button press does (held past half a second it turns into its tweak, as always). */
	public static Trick grab(Direction d)
	{
		return Grabs.pick(grabLeftHand(d), grabAim(d));
	}

	/** The direction's name for the Trick Book and the controls card ("up-left"), or "no direction". */
	public static String directionName(Direction d)
	{
		return d == null ? "no direction" : d.name().toLowerCase().replace('_', '-');
	}
}

package com.gielinorskate.input;

/**
 * Controller mode's right stick, read from button-free mouse movement. AntiMicroX's "Mouse (Normal)" stick output
 * (cursor mode, the shipped profile) moves the cursor at a speed set by the tilt, so a still cursor means a centred
 * stick and the cursor path is the stick's motion added up over time:
 * <ul>
 * <li>a <b>stroke</b> starts with the first cursor move after the cursor has been still, and ends once it has not
 * moved for {@link #STOP_MS} (the stick is back at centre). The stroke's path goes to the same
 * {@link GestureRecognizer} as a right-drag, so flicks, their sensitivity and their near-miss hints are shared;</li>
 * <li>a stroke that stays slow (a small tilt, under {@link #FAST_SPEED}) and keeps going mostly up or down for
 * {@link #MANUAL_MS} is a <b>manual</b> (up) or a <b>nose manual</b> (down) instead. It is dropped from the
 * recogniser with no flick and no hint, and lasts until the stroke ends. A fast motion during a manual ends it and
 * starts a fresh stroke, so a flick pops out of the manual;</li>
 * <li>while a grab key is held the stick aims the grab ({@link #blockedMove}) and is never a flick, and that
 * motion stays blocked after the grab is let go until the cursor has been still.</li>
 * </ul>
 * Thread-safe: moves arrive on the AWT thread, ticks on the client thread. Times share the MouseEvent clock.
 */
final class ControllerStick
{
	/** The manual a held stick tilt asks for. */
	enum Manual
	{
		NONE,
		/** Small tilt up, held. */
		MANUAL,
		/** Small tilt down, held. */
		NOSE
	}

	/**
	 * No cursor move for this long means the stick is back at centre. AntiMicroX sends a move every 5 ms or so
	 * while tilted (a tiny tilt can take ~20 ms per pixel); a flick's pass through the dead zone takes ~10-30 ms.
	 */
	static final long STOP_MS = 80;
	/** A slow tilt held this long, without a fast motion, is a manual. */
	static final long MANUAL_MS = 250;
	/**
	 * Cursor speed, px/ms over {@link #SPEED_SPAN_MS}, from which a stroke counts as fast (a flick's wind-up or
	 * snap, never a manual). With the profile's speed 60 and quadratic curve, full tilt is ~1.2 px/ms and this is
	 * a bit over half tilt; flicks themselves must still reach the recogniser's own 0.5 px/ms.
	 */
	static final float FAST_SPEED = 0.35f;
	static final long SPEED_SPAN_MS = 24;
	/** A manual's net travel since the stroke began must be at least this, px, and mostly vertical. */
	static final float MANUAL_MIN_PX = 8f;
	/** Mostly vertical: |dy| at least this many times |dx|. */
	static final float MANUAL_VERTICAL_RATIO = 2f;
	private static final int HISTORY = 16;

	private final GestureRecognizer gesture;

	/** Flicks on (mouse tricks); manuals are read either way. */
	private boolean flicks = true;
	/** The cursor's latest position and move time; known once the first move arrives. */
	private boolean known;
	private int lastX;
	private int lastY;
	private long lastMoveMs;
	/** A stroke is in progress (the stick is off centre). */
	private boolean active;
	/** The recogniser was begun for this stroke (cleared once it is a manual). */
	private boolean feeding;
	/** A grab key went down: motion is blocked until the cursor has been still for STOP_MS. */
	private boolean blocked;
	/** The stroke has moved fast at some point: a flick, never a manual. */
	private boolean fast;
	private long strokeStartMs;
	private int strokeStartX;
	private int strokeStartY;
	private Manual manual = Manual.NONE;
	private final Samples history = new Samples(HISTORY);

	ControllerStick(GestureRecognizer gesture)
	{
		this.gesture = gesture;
	}

	/** Mouse tricks on or off: off, strokes are only read for manuals. */
	synchronized void setFlicks(boolean on)
	{
		flicks = on;
	}

	/** A button-free mouse move with no grab key held. */
	synchronized void move(int x, int y, long ms)
	{
		boolean resting = !known || ms - lastMoveMs >= STOP_MS;
		if (blocked)
		{
			if (!resting)
			{
				// still the motion that was going on when the grab key went down
				remember(x, y, ms);
				return;
			}
			blocked = false;
		}
		if (active && resting)
			endStroke();
		if (!active)
			startStroke(known ? lastX : x, known ? lastY : y, ms);
		remember(x, y, ms);
		// only samples of this stroke and its run of moves count; none older: not fast
		boolean fastNow = history.speed(x, y, ms, SPEED_SPAN_MS, HISTORY, strokeStartMs, 0f) >= FAST_SPEED;
		if (fastNow && manual != Manual.NONE)
		{
			// a flick out of the manual: the manual ends and a fresh stroke starts at the sample before this one
			manual = Manual.NONE;
			boolean before = history.count >= 2;
			int i = history.ago(1);
			startStroke(before ? (int) history.x[i] : lastX, before ? (int) history.y[i] : lastY,
				before ? history.ms[i] : ms);
		}
		fast |= fastNow;
		if (feeding)
			gesture.move(x, y, ms);
		checkManual(ms);
	}

	/** A button-free mouse move while a grab key is held: it aims the grab and is never a flick. */
	synchronized void blockedMove(int x, int y, long ms)
	{
		block(ms);
		remember(x, y, ms);
	}

	/** A grab key went down (or is held): the stroke in progress is dropped, and motion is blocked until still. */
	synchronized void block(long ms)
	{
		if (active)
		{
			if (feeding)
				gesture.cancel();
			active = false;
			feeding = false;
			manual = Manual.NONE;
		}
		blocked = true;
		if (!known || ms > lastMoveMs)
			lastMoveMs = ms;
	}

	/** Lets time pass with no move: the stroke ends once the cursor has been still for STOP_MS. */
	synchronized void tick(long now)
	{
		if (!active)
			return;
		if (now - lastMoveMs >= STOP_MS)
		{
			endStroke();
			return;
		}
		checkManual(now);
	}

	/**
	 * Forgets the stroke without touching the recogniser (skating toggled, focus lost, or a flick button press
	 * that starts a right-drag of its own).
	 */
	synchronized void reset()
	{
		active = false;
		feeding = false;
		blocked = false;
		manual = Manual.NONE;
		known = false;
		history.count = 0;
	}

	synchronized Manual manual()
	{
		return manual;
	}

	/** A stick stroke is in progress. */
	synchronized boolean isActive()
	{
		return active;
	}

	/**
	 * True while the recogniser's wind-up (crouch, charge) should not show: a stick stroke that has only been slow
	 * so far may still turn out to be a manual.
	 */
	synchronized boolean hidesWindUp()
	{
		return active && feeding && !fast;
	}

	private void startStroke(int x, int y, long ms)
	{
		active = true;
		fast = false;
		manual = Manual.NONE;
		strokeStartMs = ms;
		strokeStartX = x;
		strokeStartY = y;
		feeding = flicks;
		if (feeding)
			gesture.begin(x, y, ms);
	}

	private void endStroke()
	{
		if (feeding)
			gesture.end();
		active = false;
		feeding = false;
		manual = Manual.NONE;
	}

	private void checkManual(long now)
	{
		if (!active || fast || manual != Manual.NONE || now - strokeStartMs < MANUAL_MS)
			return;
		float dx = lastX - strokeStartX;
		float dy = lastY - strokeStartY;
		if (Math.abs(dy) < MANUAL_MIN_PX || Math.abs(dy) < MANUAL_VERTICAL_RATIO * Math.abs(dx))
			return;
		manual = dy < 0 ? Manual.MANUAL : Manual.NOSE;
		if (feeding)
		{
			gesture.cancel();
			feeding = false;
		}
	}

	private void remember(int x, int y, long ms)
	{
		known = true;
		lastX = x;
		lastY = y;
		lastMoveMs = ms;
		history.add(x, y, ms);
	}
}

