	public boolean forward;
	/** Held: walk toward the camera (S, or a lean back key in controller mode). */
	public boolean back;
	public boolean left;
	public boolean right;
	/** Held: Shift. */
	public boolean sprint;
	/** Edge: Space went down since the last drain. */
