	private final BoardKey boardKey = new BoardKey();
	/** The board key in use ({@link #effectiveBoardKey}) and as configured, so a trick-mode change re-checks it. */
	private volatile int boardKeyCode = VK_F, configuredBoardKey = VK_F;
	/**
	 * On foot (off the board): Space jumps instead of doing a trick or a manual, and Q / E drop or pick up the
	 * board. Every other key is read as on the board and turned into walking by {@link #drainFoot}.
	 */
	private volatile boolean onFoot;
	private volatile boolean spaceDown;
	/**
	 * Controller presets: each pad button sends its own pad key (see {@link PadButton}), and the preset turns it
	 * into an action by where the skater is. The buttons held, as bits by ordinal (written on the AWT thread only),
	 * are read by context when the input is drained, so a button held across a mount or dismount is not a new
	 * press but does what it does in the new place, as the old pad keys did.
	 */
	private volatile int padHeld;
	/**
	 * The action each held button was pressed as, null for the others (its release is paired with it: the board
	 * key, the ollie); written before {@link #padHeld}, so a drain sees it.
	 */
	private final PadAction[] padPressedAs = new PadAction[PadButton.values().length];
	/** The buttons whose pad keys are read: none outside controller mode, nor one on another key setting's key. */
	private volatile int padActive;
	private volatile PadPreset preset = PadPreset.skate3();
	/** In the air (set each frame): a button's air action applies. */
	private volatile boolean airborne;
	/** The skate mode (toggle) key when it has no modifiers, else VK_UNDEFINED: a pad key on it would toggle. */
	private volatile int plainToggleCode = VK_UNDEFINED;

	// ---- button tricks (a preset with a flip or grab button, see PadPreset.buttonTricks; controller mode only)
	/** The preset does tricks with buttons: the right stick turns the camera, the left stick gives directions. */
	private volatile boolean buttonTricks;
	/** The left stick's up / down (the real arrow keys in controller mode), for trick directions and manuals. */
	private volatile boolean stickUp, stickDown;
	/** The up-then-down (manual) and down-then-up (nose manual) gestures on the left stick. */
	private final StickManual stickManualGesture = new StickManual();
	/**
	 * The manual a stick gesture started: held by itself until the skater leaves the manual (a pop, slowing down,
	 * a bail) or does the other gesture; dropped when it does not start within {@link #MANUAL_START_MS}.
	 */
	private volatile StickManual.Kind manualLatch = StickManual.Kind.NONE;
	private volatile long manualLatchAt;
	/** The latched manual has started (physics is in it). */
	private volatile boolean manualLatchEntered;
	/** In a manual (set each frame). */
	private volatile boolean inManual;
	/** A rail is near (set each frame): the grind button grinds instead of stepping off. */
	private volatile boolean railNear;
	/** Guards the flip and grab presses waiting for their direction. */
	private final Object trickLock = new Object();
	/** A flip and a grab button press waiting {@link ButtonTricks#DIRECTION_WAIT_MS} for its direction, or null. */
	private PendingTrick pendingFlip, pendingGrab;
	/** The grab button's grab: the button holding it (-1 when none), its hand and its aim. */
	private volatile int padGrabButton = -1;
	private volatile boolean padGrabLeft;
	private volatile Grabs.Aim padGrabAim;
	/**
	 * D-pad buttons used as a trick direction while held (bits by ordinal): their own press (the controls card on
	 * d-pad up) waits for the release and is dropped when they were (AWT thread only).
	 */
	private int dpadUsed;

	/** A flip or grab button press and the direction held as it went down. */
	@AllArgsConstructor
	private static final class PendingTrick
	{
		final int button;
		final long pressMs;
		final Gesture.Direction atPress;
	}

	@Inject
	public InputController(GielinorSkateConfig config)
	{
		this(System::currentTimeMillis, config);
	}

	/** For tests: default keys and sensitivity unless {@link #configure} is called. */
	InputController(LongSupplier clock)
	{
		this(clock, null);
	}

	private InputController(LongSupplier clock, GielinorSkateConfig config)
	{
		this.clock = clock;
		this.config = config;
	}

	private static int bit(PadButton b)
	{
		return 1 << b.ordinal();
	}

	/** {@code code} is the key {@code key} (and a real key). */
	private static boolean is(int code, int key)
	{
		return code != VK_UNDEFINED && code == key;
	}

	/** True when {@code code} can be the manual key: a real, non-modifier key that no skate control uses. */
	public static boolean isValidManualKey(int code)
	{
		return !SKATE_KEYS.contains(code);
	}

	/**
	 * Like {@link #isValidManualKey(int)}; with keyboard tricks on, Space and the number keys are tricks, so they
	 * cannot be the manual key either.
	 */
	public static boolean isValidManualKey(int code, boolean keyboardTricks)
	{
		return isValidManualKey(code) && !(keyboardTricks && KeyboardTricks.isTrickKey(code));
	}

	/**
	 * The manual key in use: the configured one when valid, else Space, or C with keyboard tricks on (Space is the
	 * ollie then).
	 */
	public static int effectiveManualKey(int code, boolean keyboardTricks)
	{
		return isValidManualKey(code, keyboardTricks) ? code : keyboardTricks ? VK_C : VK_SPACE;
	}

	/** The brake key in use: none (VK_UNDEFINED) when it is on a skate key (W, Q, Esc, ...). */
	public static int effectiveBrakeKey(int code)
	{
		return isValidManualKey(code) ? code : VK_UNDEFINED;
	}

	/**
	 * Sets the manual key code (Space when it is not {@link #isValidManualKey valid}) and the flick sensitivity
	 * percent (read from the config on enable).
	 */
	void configure(int manualKeyCode, int flickSensitivity)
	{
		configuredManualKey = manualKeyCode;
		this.manualKeyCode = effectiveManualKey(manualKeyCode, keyboardTricks);
		gesture.setSensitivity(flickSensitivity);
		refreshPadKeys();
	}

	/** Sets the trick controls, the flick button and flick mirroring (read from the config on enable). */
	void configureTricks(GielinorSkateConfig.TrickControls controls, GielinorSkateConfig.FlickButton button,
		boolean mirror)
	{
		keyboardTricks = controls.keyboard();
		mouseTricks = controls.mouse();
		flickButton = button;
		mirrorFlicks = mirror;
		manualKeyCode = effectiveManualKey(configuredManualKey, keyboardTricks);
		setBoardKeyCode(effectiveBoardKey(configuredBoardKey, keyboardTricks));
		stick.setFlicks(mouseTricks);
		refreshPadKeys();
	}

	/** Re-reads the manual key and flick sensitivity from the config (a setting changed while skating). */
	public void reconfigure()
	{
		if (config != null)
			applyConfig();
	}

	/** Sets the lean forward / lean back key codes (read from the config on enable). */
	void configureLeanKeys(int forward, int back)
	{
		leanForwardCode = forward;
		leanBackCode = back;
		refreshPadKeys();
	}

	/** Sets controller mode and the brake key (read from the config on enable); see {@link #effectiveBrakeKey}. */
	void configureController(boolean on, int brake)
	{
		controllerMode = on;
		brakeCode = effectiveBrakeKey(brake);
		stick.reset();
		refreshPadKeys();
	}

	/**
	 * True when a pad key is read: it is none of {@code taken} (the other key settings in use), so it never changes
	 * what another control's key does. The pad keys are never skate controls or trick keys.
	 */
	public static boolean isPadKeyFree(int code, int... taken)
	{
		return IntStream.of(taken).noneMatch(t -> t == code);
	}

	/** Sets the controller preset (read from the config on enable). A change lets go of the buttons held. */
	void configurePreset(PadPreset p)
	{
		if (!p.equals(preset))
		{
			preset = p;
			buttonTricks = p.buttonTricks();
			releasePad();
		}
	}

	/** Controller mode with a button-trick preset. */
	private boolean buttonMode()
	{
		return controllerMode && buttonTricks;
	}

	/** Sets the skate mode (toggle) key, so a pad key never shares it; one with modifiers never clashes. */
	void configureToggleKey(int code, int modifiers)
	{
		plainToggleCode = modifiers == 0 ? code : VK_UNDEFINED;
		refreshPadKeys();
	}

	/**
	 * The pad keys read: only in controller mode (a keyboard player's keys are never pad keys), and each off when
	 * another key setting uses its key ({@link #isPadKeyFree}).
	 */
	private void refreshPadKeys()
	{
		int active = 0;
		for (PadButton b : PadButton.values())
		{
			if (controllerMode && isPadKeyFree(b.keyCode, manualKeyCode, brakeCode, leanForwardCode, leanBackCode,
				boardKeyCode, plainToggleCode))
				active |= bit(b);
		}
		// a button no longer read drops its held state: its release would no longer arrive, leaving it stuck down
		int dropped = padHeld & ~active;
		padHeld &= active;
		if (padGrabButton >= 0 && (dropped >> padGrabButton & 1) != 0)
			padGrabButton = -1;
		for (int i = 0; i < padPressedAs.length; i++)
		{
			if ((dropped >> i & 1) != 0)
				padPressedAs[i] = null;
		}
		padActive = active;
	}

	/** Lets go of every pad button without its release doing anything. */
	private void releasePad()
	{
		padHeld = dpadUsed = 0;
		Arrays.fill(padPressedAs, null);
		dropTrickButtons();
	}

	/** Lets go of the grab button's grab and of the flip and grab presses waiting for their direction. */
	private void dropTrickButtons()
	{
		padGrabButton = -1;
		synchronized (trickLock)
		{
			pendingFlip = pendingGrab = null;
		}
	}

	/** The board's context: in the air or on the ground. */
	private PadContext boardContext()
	{
		return airborne ? PadContext.AIR : PadContext.BOARD;
	}

	/** True when a held pad button does one of {@code actions} in {@code context}. */
	private boolean padDoes(PadContext context, PadAction... actions)
	{
		int held = padHeld;
		PadPreset p = preset;
		for (PadButton b : PadButton.values())
		{
			if ((held & bit(b)) != 0 && Arrays.asList(actions).contains(p.action(b, context)))
				return true;
		}
		return false;
	}

	/** Shift, or a pad button held as the hard tricks modifier. */
	private boolean shiftDown()
	{
		return shift || padDoes(boardContext(), HARD_MODIFIER, SPIN_ASSIST);
	}

	private boolean grabbingLeft()
	{
		return grabLeftKey || padDoes(boardContext(), GRAB_LEFT);
	}

	private boolean grabbingRight()
	{
		return grabRightKey || padDoes(boardContext(), GRAB_RIGHT);
	}

	private boolean grabbing()
	{
		return grabbingLeft() || grabbingRight();
	}

	/**
	 * The board key in use: the configured one when valid (a key the {@link #isValidManualKey manual key} could be,
	 * but never Space, the jump on foot), VK_UNDEFINED (off) when unset, else F, so it never takes over Esc, WASD,
	 * Shift, Space, Q / E, H, R or a trick key.
	 */
	public static int effectiveBoardKey(int code, boolean keyboardTricks)
	{
		return code == VK_UNDEFINED || isValidManualKey(code, keyboardTricks) && code != VK_SPACE ? code : VK_F;
	}

	/** Sets the board on/off key code (read from the config on enable); see {@link #effectiveBoardKey}. */
	void configureBoardKey(int code)
	{
		configuredBoardKey = code;
		setBoardKeyCode(effectiveBoardKey(code, keyboardTricks));
		refreshPadKeys();
	}

	/** A new board key code drops the old key's held state: its release would no longer match, leaving it stuck. */
	private void setBoardKeyCode(int code)
	{
		if (code != boardKeyCode)
			boardKey.reset();
		boardKeyCode = code;
	}

	/**
	 * Off the board (true) or on it. Switching drops the edges and held trick / manual keys of the other mode, so
	 * nothing pressed on foot fires on the board or the other way round.
	 */
	public void setOnFoot(boolean onFoot)
	{
		this.onFoot = onFoot;
		rolling = airborne = orbiting = manualKey = inManual = false;
		orbitPixels.set(0);
		jump.set(false);
		dropPickup.set(false);
		trickKeyHeld = VK_UNDEFINED;
		keyGestures.clear();
		dropStickManual();
		dropTrickButtons();
	}

	/** Lets go of the stick manual and any half-done gesture. */
	private void dropStickManual()
	{
		manualLatch = StickManual.Kind.NONE;
		manualLatchEntered = false;
		stickManualGesture.reset();
	}

	private void applyConfig()
	{
		configureBoardKey(config.boardKey().getKeyCode());
		configureToggleKey(config.toggleKey().getKeyCode(), config.toggleKey().getModifiers());
		configurePreset(PadPresets.resolve(config.controllerPreset(), config.customControllerLayout()));
		configureController(config.controllerMode(), config.brakeKey().getKeyCode());
		configureLeanKeys(config.leanForwardKey().getKeyCode(), config.leanBackKey().getKeyCode());
		configureTricks(config.trickControls(), config.flickButton(), config.mirrorFlicks());
		configure(config.manualKey().getKeyCode(), config.flickSensitivity());
	}

	public void setEnabled(boolean enabled)
	{
		if (enabled && config != null)
			// the manual key is matched by key code alone, so it still works with Shift (slide) held
			applyConfig();
		this.enabled = enabled;
		focusLost();
		setOnFoot(false);
		mouseKnown = railNear = controlsKeyDown = false;
		stick.setFlicks(mouseTricks);
		push.set(false);
		reset.set(false);
		exit.set(false);
		controlsToggle.set(false);
		plainClick.set(false);
		zoomNotches.set(0);
		while (gesture.poll() != null)
		{
			// drop any gesture left over from before skating was enabled
		}
	}

	/** Copies held state into `in` and ORs in pending edges. */
	public void drainInto(SkateInput in)
	{
		long now = clock.getAsLong();
		stick.tick(now);
		gesture.tick(now);
		resolveTricks(now, -1);
		if (manualLatch != StickManual.Kind.NONE && !manualLatchEntered && now - manualLatchAt > MANUAL_START_MS)
			// too slow to manual: no manual waiting to start later
			manualLatch = StickManual.Kind.NONE;
		in.steer = (right ? 1f : 0f) - (left ? 1f : 0f);
		boolean keyCharging = trickKeyHeld != VK_UNDEFINED;
		// a slow stick stroke may still become a manual: its wind-up shows only once it moves fast
		boolean windUpShown = !stick.hidesWindUp();
		PadContext board = boardContext();
		// a held trick key (or pad ollie button) winds up like a mouse wind-up: crouched for a regular pop,
		// charging either way
		boolean padCharging = !onFoot && padDoes(board, OLLIE);
		in.crouch = crouchKey || (windUpShown && gesture.isCrouching()) || (keyCharging && !trickKeyNollie)
			|| padCharging;
		in.charge = crouchKey || (windUpShown && gesture.isCharging()) || keyCharging || padCharging;
		// S key only: the mouse wind-up also crouches but must not pick a 5-0 on a grind
		in.leanBack = crouchKey;
		// the pad's push buttons push on the board (on foot they do their on-foot action instead); with button
		// tricks the left stick up pushes too (not in a stick manual, where it would nose manual)
		boolean pushDown = pushHeld || (!onFoot && (padDoes(board, PUSH, MONGO_PUSH)
			|| (buttonMode() && stickUp && manualLatch == StickManual.Kind.NONE)));
		// the brake key is only ever a brake (or a tight carve with steer): never Shift+W's front flip
		boolean brakeAsSlide = (brakeKey || padDoes(board, BRAKE)) && !pushDown;
		boolean shift = shiftDown();
		in.powerslide = shift || brakeAsSlide;
		boolean keysAlone = !pushDown && !left && !right;
		boolean alone = keysAlone && !gesture.isStrokeActive();
		if (!shift || !alone)
			// not Shift alone: the brake waits BRAKE_DELAY_MS from when it is alone again
			shiftAloneSince = now;
		boolean shiftBrakes = shift && now - shiftAloneSince >= BRAKE_DELAY_MS;
		// the brake key is not a trick modifier, so it needs no delay; in controller mode the right stick's
		// stroke in progress does not stop it braking (B is its own button, not a steer)
		in.brakeBlocked = !(shiftBrakes || (brakeAsSlide && (controllerMode ? keysAlone : alone)));
		in.pushPressed |= push.getAndSet(false);
		in.pushHeld = pushDown;
		in.resetRequested |= reset.getAndSet(false);
		boolean grabLeft = grabbingLeft();
		boolean grabRight = grabbingRight();
		// the grab button: its hand and aim were picked by the direction as it was pressed
		boolean padGrab = padGrabButton >= 0 && !onFoot && !grabLeft && !grabRight;
		in.grabLeft = padGrab ? padGrabLeft : grabLeft;
		in.grabRight = padGrab ? !padGrabLeft : grabRight;
		in.grabAim = padGrab ? padGrabAim : grabLeft || grabRight ? grabAim : null;
		in.grindHeld = !onFoot && heldAs(GRIND_BUTTON, GRIND_BUTTON);
		in.spinFast = !onFoot && airborne && padDoes(PadContext.AIR, SPIN_ASSIST);
		in.leanForwardKey = leanForward || padDoes(board, LEAN_FORWARD);
		in.leanBackKey = leanBack || padDoes(board, LEAN_BACK);
		in.controllerMode = controllerMode;
		// with button tricks the right stick is the camera: its manual tilt is off, the left stick's gesture manuals
		ControllerStick.Manual stickManual = controllerMode && !buttonTricks ? stick.manual()
			: ControllerStick.Manual.NONE;
		StickManual.Kind latched = onFoot ? StickManual.Kind.NONE : manualLatch;
		in.manualHeld = manualKey || stickManual != ControllerStick.Manual.NONE || latched != StickManual.Kind.NONE;
		in.noseManualHeld = stickManual == ControllerStick.Manual.NOSE || latched == StickManual.Kind.NOSE;
		Gesture g;
		while ((g = gesture.poll()) != null)
			// physics decides what a gesture does (pop when grounded, flip when airborne)
			in.gestures.add(mirrorFlicks ? KeyboardTricks.mirror(g) : g);
		while ((g = keyGestures.poll()) != null)
			in.gestures.add(g);
	}

	/**
	 * The on-foot reading of the held keys, and the jump and drop / pick-up edges since the last call. W / S
	 * (and Key Remapping's arrows) walk forward and back; in controller mode so do the lean keys (the left
	 * stick's real arrows).
	 */
	public void drainFoot(FootControls out)
	{
		out.forward = pushHeld || (controllerMode && leanForward);
		out.back = crouchKey || (controllerMode && leanBack);
		out.left = left;
		out.right = right;
		out.sprint = shift || padDoes(PadContext.FOOT, SPRINT);
		out.jumpPressed = jump.getAndSet(false);
		out.dropPickupPressed = dropPickup.getAndSet(false);
	}

	/** The board key's press, tap and hold since the last call. */
	public void pollBoardKey(BoardKey.Edges out)
	{
		boardKey.poll(clock.getAsLong(), out);
	}

	public boolean consumeExit()
	{
		return exit.getAndSet(false);
	}

	/** The latest near-miss flick since the last call (null when none, or with mouse flicks off). */
	public NearMiss consumeNearMiss()
	{
		NearMiss m = gesture.pollNearMiss();
		return mouseTricks ? m : null;
	}

	/**
	 * The flick stroke in progress, for the HUD's live flick visualizer; the latest flick is the newer of the last
	 * mouse flick (as the hand moved, before mirroring) and the last keyboard trick.
	 */
	public LiveStroke getLiveStroke()
	{
		LiveStroke s = gesture.live(clock.getAsLong(), GestureRecognizer.LIVE_TRAIL_MS);
		LiveStroke k = keyFlash;
		return k != null && (s.firedDirection == null || k.firedMs > s.firedMs)
			? s.withFired(k.firedDirection, k.firedNollie, k.firedMs) : s;
	}

	/** True once after a left click on the world while skating (not a flick, not on the sidebar or chatbox). */
	public boolean consumePlainClick()
	{
		return plainClick.getAndSet(false);
	}

	/** True once, the frame after H is pressed while skating: toggles the controls card. */
	public boolean consumeControlsToggle()
	{
		return controlsToggle.getAndSet(false);
	}

	public int drainZoomNotches()
	{
		return zoomNotches.getAndSet(0);
	}

	/** Sideways pixels the camera was dragged with the middle button on foot since the last call (right = +). */
	public int drainOrbitPixels()
	{
		return orbitPixels.getAndSet(0);
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent e)
	{
		if (enabled && !clickThrough(e))
		{
			// skate mode owns the camera distance (the side panel and chatbox still scroll); the game's own zoom would be overwritten anyway
			zoomNotches.addAndGet(e.getWheelRotation());
			e.consume();
		}
		return e;
	}

	/** Lets go of every held key and button. */
	@Override
	public void focusLost()
	{
		left = right = crouchKey = shift = pushHeld = grabLeftKey = grabRightKey = manualKey = false;
		leanForward = leanBack = brakeKey = spaceDown = stickUp = stickDown = false;
		grabAim = null;
		stick.reset();
		trickKeyHeld = VK_UNDEFINED;
		gesture.setModifier(false);
		gesture.end();
		releasePad();
		boardKey.reset();
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		if (enabled)
			e.consume();
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		onKey(e, true);
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		onKey(e, false);
	}

	private void onKey(KeyEvent e, boolean down)
	{
		int code = e.getKeyCode();
		if (enabled && (handleOffBoardKey(code, down) || handleTrickKey(code, down, e.isAltDown())
			|| handleKey(code, e.getKeyChar(), down)))
			e.consume();
	}

	/**
	 * The board on/off key (in either mode), the pad keys (in either mode), and Space on foot (a jump, never a
	 * trick or manual). Returns false for every other key.
	 */
	private boolean handleOffBoardKey(int code, boolean down)
	{
		if (is(code, boardKeyCode))
		{
			boardKey.set(down, clock.getAsLong());
			return true;
		}
		PadButton pad = PadButton.forKey(code);
		if (pad != null && (padActive & bit(pad)) != 0)
		{
			handlePad(pad, down);
			return true;
		}
		if (code != VK_SPACE)
			return false;
		// tracked in both modes, so a Space held across a mount or dismount is not a new press
		if (onFoot && down && !spaceDown)
			jump.set(true);
		spaceDown = down;
		return onFoot;
	}

	/**
	 * A pad button went down or up. Held actions (push held, sprint, brake, grabs, Shift, lean, the ollie wind-up)
	 * are read from the held buttons when drained; a press does the press of its action where the skater is now
	 * (push, jump, drop or pick up, the board key, reset, stop, the controls card), and its board action's grab
	 * aim or Shift timing starts in either place, as the old keys' did. The release is paired with the press.
	 */
	private void handlePad(PadButton b, boolean down)
	{
		long now = clock.getAsLong();
		int bit = bit(b);
		boolean wasDown = (padHeld & bit) != 0;
		PadPreset p = preset;
		PadAction boardAction = p.action(b, boardContext());
		boolean grab = boardAction == GRAB_LEFT || boardAction == GRAB_RIGHT;
		if (down)
		{
			if (wasDown)
			{
				// a key repeat while held: as Q / E did, a grab key repeat keeps the stick on aiming
				if (grab)
					grabDown(true, now);
				return;
			}
			boolean shiftBefore = shiftDown();
			boolean grabBefore = boardAction == GRAB_LEFT ? grabbingLeft() : grabbingRight();
			PadContext where = onFoot ? PadContext.FOOT : boardContext();
			PadAction action = p.action(b, where);
			if (action == GRIND_BUTTON && where == PadContext.BOARD && !railNear)
				// the grind button with no rail near, on the ground: step off (its release is the board key's)
				action = BOARD_TOGGLE;
			padPressedAs[b.ordinal()] = action;
			padHeld |= bit;
			if (grab)
				grabDown(grabBefore, now);
			else if (boardAction == HARD_MODIFIER || boardAction == SPIN_ASSIST)
			{
				if (!shiftBefore)
					shiftAloneSince = now;
				gesture.setModifier(true);
			}
			if (!(buttonMode() && isDpad(b) && dpadPressWaits(bit, action)))
			{
				trickPress(b, action, now);
				pressEdge(action, now);
			}
			return;
		}
		if (!wasDown)
			return;
		PadAction pressedAs = padPressedAs[b.ordinal()];
		padPressedAs[b.ordinal()] = null;
		padHeld &= ~bit;
		gesture.setModifier(shiftDown());
		if (buttonMode() && isDpad(b))
		{
			boolean used = (dpadUsed & bit) != 0;
			dpadUsed &= ~bit;
			if (!used && DPAD_RELEASE_ACTIONS.contains(pressedAs))
				// d-pad up alone, let go: the controls card (it was not a trick's direction)
				pressEdge(pressedAs, now);
		}
		if (pressedAs == FLIP_BUTTON || pressedAs == GRAB_BUTTON)
			trickRelease(b.ordinal(), now);
		if (pressedAs == BOARD_TOGGLE)
			boardKey.release(now);
		else if (pressedAs == OLLIE && !onFoot)
			// the held ollie button pops when let go, as the Space trick key does (Shift held: the hard version)
			fire(KeyboardTricks.gestureFor(VK_SPACE, false, shiftDown()), now);
	}

	private static boolean isDpad(PadButton b)
	{
		return (bit(b) & DPAD_BITS) != 0;
	}

	/**
	 * Button tricks: a d-pad press is also a trick direction. Pressed with another d-pad button (a diagonal) or with
	 * a flip or grab button held it is one, and its own press is dropped; a single press of its own waits for the
	 * release (see {@link #DPAD_RELEASE_ACTIONS}). True when the press waits.
	 */
	private boolean dpadPressWaits(int bit, PadAction action)
	{
		if ((padHeld & DPAD_BITS & ~bit) != 0 || heldAs(FLIP_BUTTON, GRAB_BUTTON))
			dpadUsed |= padHeld & DPAD_BITS;
		else
			dpadUsed &= ~bit;
		return DPAD_RELEASE_ACTIONS.contains(action);
	}

	/** A held button was pressed as {@code a} or {@code b}. */
	private boolean heldAs(PadAction a, PadAction b)
	{
		return Arrays.stream(padPressedAs).anyMatch(p -> p == a || p == b);
	}

	/**
	 * The direction for a button trick: the left stick (its arrow keys) and the d-pad together, so the d-pad gives
	 * the diagonals the four-way stick can't. Null when none.
	 */
	private Gesture.Direction trickDirection()
	{
		int held = padHeld;
		return ButtonTricks.direction(stickUp || (held & bit(PadButton.DPAD_UP)) != 0,
			stickDown || (held & bit(PadButton.DPAD_DOWN)) != 0, left || (held & bit(PadButton.DPAD_LEFT)) != 0,
			right || (held & bit(PadButton.DPAD_RIGHT)) != 0);
	}

	/** The direction held now, else the one held as {@code press} went down. */
	private Gesture.Direction trickDirection(PendingTrick press)
	{
		Gesture.Direction d = trickDirection();
		return d != null ? d : press.atPress;
	}

	/**
	 * A flip or grab button press: it waits up to {@link ButtonTricks#DIRECTION_WAIT_MS} for its direction (a
	 * diagonal held already goes at once); a second flip press while one waits fires the first.
	 */
	private void trickPress(PadButton b, PadAction action, long now)
	{
		if (action != FLIP_BUTTON && action != GRAB_BUTTON)
			return;
		dpadUsed |= padHeld & DPAD_BITS;
		Gesture.Direction d = trickDirection();
		synchronized (trickLock)
		{
			PendingTrick press = new PendingTrick(b.ordinal(), now, d);
			if (action == FLIP_BUTTON)
			{
				if (pendingFlip != null)
					fireFlip(pendingFlip, now);
				pendingFlip = press;
			}
			else
			{
				padGrabButton = -1;
				pendingGrab = press;
			}
			// the diagonals are the odd directions (they go round in 45 degree steps from UP)
			if (d != null && d.ordinal() % 2 == 1)
				resolveTricks(now, b.ordinal());
		}
	}

	/** A flip button let go before its direction wait fires now; a grab button let go lets go of its grab. */
	private void trickRelease(int button, long now)
	{
		synchronized (trickLock)
		{
			if (pendingFlip != null && pendingFlip.button == button)
			{
				fireFlip(pendingFlip, now);
				pendingFlip = null;
			}
			if (pendingGrab != null && pendingGrab.button == button)
				pendingGrab = null;
			if (padGrabButton == button)
				padGrabButton = -1;
		}
	}

	/** The press's direction wait is over, or it is {@code button}'s. */
	private static boolean due(PendingTrick p, long now, int button)
	{
		return p != null && (p.button == button || now - p.pressMs >= ButtonTricks.DIRECTION_WAIT_MS);
	}

	/**
	 * Fires the flip and starts the grab whose direction wait is over (or, for {@code button}, at once). Called
	 * when the input is drained, so the flip reaches physics as a flick or trick key would.
	 */
	private void resolveTricks(long now, int button)
	{
		synchronized (trickLock)
		{
			if (due(pendingFlip, now, button))
			{
				fireFlip(pendingFlip, now);
				pendingFlip = null;
			}
			if (due(pendingGrab, now, button))
			{
				Gesture.Direction d = trickDirection(pendingGrab);
				padGrabLeft = ButtonTricks.grabLeftHand(d);
				padGrabAim = ButtonTricks.grabAim(d);
				padGrabButton = pendingGrab.button;
				pendingGrab = null;
			}
		}
	}

	/** The flip of a flip button press: its direction now (or as pressed), the hard version with the modifier held. */
	private void fireFlip(PendingTrick press, long now)
	{
		fire(ButtonTricks.flip(trickDirection(press), shiftDown()), now);
	}

	/** A keyboard trick or button flip fires: it reaches physics with the next drain, and flashes on the HUD. */
	private void fire(Gesture g, long now)
	{
		keyGestures.add(g);
		keyFlash = LiveStroke.fired(g.direction, g.nollie, now);
	}

	/** What a pad button's new press does, for the action it was pressed as. */
	private void pressEdge(PadAction action, long now)
	{
		switch (action)
		{
			case PUSH:
			case MONGO_PUSH:
				push.set(true);
				break;
			case JUMP:
				jump.set(true);
				break;
			case DROP_PICKUP:
				dropPickup.set(true);
				break;
			case BOARD_TOGGLE:
				boardKey.press(now);
				break;
			case RESET:
				reset.set(true);
				break;
			case STOP:
				exit.set(true);
				break;
			case CONTROLS_CARD:
				controlsToggle.set(true);
				break;
			case CAMERA_ORBIT:
				orbitLastX = mouseX;
				break;
			default:
				break;
		}
	}

	/**
	 * Keyboard tricks: a trick key winds up while held and fires its trick when released, so holding it charges
	 * the pop as a held mouse wind-up does. Key repeats while held are ignored. Returns false when keyboard tricks
	 * are off or {@code code} is not a trick key (or is the manual key).
	 */
	private boolean handleTrickKey(int code, boolean down, boolean alt)
	{
		if (!keyboardTricks || code == manualKeyCode || !KeyboardTricks.isTrickKey(code))
			return false;
		if (down && trickKeyHeld != code)
		{
			trickKeyHeld = code;
			trickKeyNollie = alt;
		}
		else if (!down && trickKeyHeld == code)
		{
			trickKeyHeld = VK_UNDEFINED;
			// Shift as the trick fires picks the hard version, as with a mouse flick
			fire(KeyboardTricks.gestureFor(code, trickKeyNollie, shiftDown()), clock.getAsLong());
		}
		return true;
	}

	/**
	 * @param ch the key's char: CHAR_UNDEFINED for a real arrow key, but a letter for W/S that Key Remapping
	 * rewrote to an arrow (it changes only the key code)
	 */
	private boolean handleKey(int code, char ch, boolean down)
	{
		boolean arrow = code == VK_UP || code == VK_DOWN;
		boolean realArrow = arrow && ch == CHAR_UNDEFINED;
		if (controllerMode && realArrow)
			stickArrow(code == VK_UP, down);
		// the lean keys (grab-flips) also keep whatever else the key does: the default arrows still push / crouch;
		// W / S that Key Remapping rewrote to the arrows push and crouch only: a grab-flip needs the real arrow
		boolean lean = false;
		boolean remappedLetter = arrow && !realArrow;
		if (is(code, leanForwardCode) && !remappedLetter)
		{
			leanForward = down;
			lean = true;
		}
		if (is(code, leanBackCode) && !remappedLetter)
		{
			leanBack = down;
			lean = true;
		}
		if (is(code, manualKeyCode))
		{
			// consumed so the key (Space by default) does not reach the chatbox or the game
			manualKey = down;
			return true;
		}
		if (lean && controllerMode && realArrow)
			// controller mode: the left stick's up / down arrives as the real arrow keys and only leans, so it
			// never pushes or crouches (W / S, also as Key Remapping's arrows, still do)
			return true;
		if (is(code, brakeCode))
		{
			brakeKey = down;
			return true;
		}
		switch (code)
		{
			// Key Remapping (core RuneLite plugin) rewrites W/A/S/D to the arrow keys
			// before this listener runs, so each arrow is an alias for its WASD key.
			case VK_UP:
			case VK_W:
				if (down && !pushHeld)
					push.set(true);
				pushHeld = down;
				return true;
			case VK_LEFT:
			case VK_A:
				left = down;
				return true;
			case VK_RIGHT:
			case VK_D:
				right = down;
				return true;
			case VK_DOWN:
			case VK_S:
				crouchKey = down;
				return true;
			case VK_SHIFT:
				if (down && !shiftDown())
					shiftAloneSince = clock.getAsLong();
				shift = down;
				// also the trick modifier: a flick fired while Shift is held is a hardflip, impossible, ...
				gesture.setModifier(shiftDown());
				return true;
			case VK_R:
				if (down)
					reset.set(true);
				return true;
			case VK_H:
				if (down && !controlsKeyDown)
					controlsToggle.set(true);
				controlsKeyDown = down;
				return true;
			case VK_ESCAPE:
				if (down)
					exit.set(true);
				return true;
			case VK_Q:
			case VK_E:
				boolean leftHand = code == VK_Q;
				boolean held = leftHand ? grabLeftKey : grabRightKey;
				if (down)
				{
					if (!held && onFoot)
						dropPickup.set(true);
					grabDown(held, clock.getAsLong());
				}
				if (leftHand)
					grabLeftKey = down;
				else
					grabRightKey = down;
				return true;
			default:
				return lean;
		}
	}

	/**
	 * A grab key or button went down ({@code held}: a key repeat, or the other grab already held): a new grab's aim
	 * is measured from here, and the stick aims the grab now, so a stroke in progress is no flick (a repeat in a
	 * rolling grab past the aim window leaves a flick out of it alone).
	 */
	private void grabDown(boolean held, long now)
	{
		if (!held)
			startAim(now);
		if (!(held && stickFreeWhileGrabbing(now)))
			stick.block(now);
	}

	/**
	 * Sets the canvas areas (sidebar, chatbox) where presses and clicks pass through to the game while skating.
	 * Called on the client thread; read on the AWT thread.
	 */
	public void setClickThroughAreas(List<Rectangle> areas)
	{
		clickThroughAreas = areas;
	}

	private boolean clickThrough(MouseEvent e)
	{
		return clickThroughAreas.stream().anyMatch(r -> r.contains(e.getX(), e.getY()));
	}

	/**
	 * True when {@code button} is the configured flick button. Right also takes middle: the core Camera plugin's
	 * "Right click moves camera" re-sends a right press as a middle one (with "Middle-button menu" a middle press
	 * arrives as right instead).
	 */
	static boolean isFlickButton(GielinorSkateConfig.FlickButton setting, int button)
	{
		switch (setting)
		{
			case LEFT:
				return button == MouseEvent.BUTTON1;
			case MIDDLE:
				return button == MouseEvent.BUTTON2;
			default:
				return button == MouseEvent.BUTTON3 || button == MouseEvent.BUTTON2;
		}
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		if (!enabled || clickThrough(e))
			// the sidebar and chatbox stay usable; only world clicks are blocked while skating
			return e;
		// consuming the press stops the game from taking keyboard focus back (e.g. after using the sidebar)
		e.getComponent().requestFocusInWindow();
		if (onFoot && e.getButton() == MouseEvent.BUTTON2)
		{
			// on foot there are no flicks: the middle button orbits the camera, like the game's own
			orbiting = true;
			orbitLastX = e.getX();
		}
		else if (isFlickButton(flickButton, e.getButton()))
		{
			// a drag of its own: a stick stroke in progress must not end it
			stick.reset();
			if (mouseTricks)
				gesture.begin(e.getX(), e.getY(), e.getWhen());
		}
		else if (e.getButton() == MouseEvent.BUTTON1)
			plainClick.set(true);
		e.consume(); // no world interaction while skating
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (!enabled)
			return e;
		if (e.getButton() == MouseEvent.BUTTON2)
			orbiting = false;
		if (isFlickButton(flickButton, e.getButton()))
		{
			gesture.end();
			rebaseAim(e.getX(), e.getY());
		}
		return mouseClicked(e);
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		if (enabled && !clickThrough(e))
			e.consume();
		return e;
	}

	/** Whether the skater rolls on the ground (not in the air, on a rail or bailed); see {@link #rolling}. */
	public void setRolling(boolean rolling)
	{
		this.rolling = rolling;
	}

	/**
	 * Whether the skater is in a manual (set each frame). A stick manual holds until the manual it started ends (a
	 * pop, slowing down, a bail).
	 */
	public void setInManual(boolean manual)
	{
		inManual = manual;
		// (entered is only read with a latch, and set afresh with each new one)
		if (manual)
			manualLatchEntered = true;
		else if (manualLatchEntered)
			manualLatch = StickManual.Kind.NONE;
	}

	/** Whether a rail is near the skater (set each frame): the grind button grinds there instead of stepping off. */
	public void setRailNear(boolean near)
	{
		railNear = near;
	}

	/**
	 * The left stick's up or down (a real arrow key in controller mode). With button tricks, on the board, a new
	 * up pushes, and up-then-down (down-then-up) within {@link StickManual#WINDOW_MS} while rolling, or in a manual,
	 * is a manual (nose manual) that then holds by itself.
	 */
	private void stickArrow(boolean up, boolean down)
	{
		boolean was = up ? stickUp : stickDown;
		if (up)
			stickUp = down;
		else
			stickDown = down;
		if (!down || was || !buttonMode() || onFoot)
			return;
		long now = clock.getAsLong();
		StickManual.Kind k = up ? stickManualGesture.up(now) : stickManualGesture.down(now);
		if (k != StickManual.Kind.NONE && (rolling || inManual))
		{
			manualLatch = k;
			manualLatchAt = now;
			manualLatchEntered = inManual;
		}
		else if (up && manualLatch == StickManual.Kind.NONE)
			push.set(true);
	}

	/**
	 * Whether the skater is in the air on the board (set each frame): a pad button with an air action of its own
	 * does that there. A change re-reads the Shift a held button gives.
	 */
	public void setAirborne(boolean airborne)
	{
		if (airborne != this.airborne)
		{
			this.airborne = airborne;
			gesture.setModifier(shiftDown());
			if (airborne)
				// popped out of a stick manual (or off a ledge): it is over
				dropStickManual();
		}
	}

	/**
	 * A grab key held while rolling, past its aim window: the stick is free to flick (an ollie out of the rolling grab).
	 * In the air (or within the window) the stick only aims the grab, as always.
	 */
	private boolean stickFreeWhileGrabbing(long ms)
	{
		return rolling && ms - aimPressMs > AIM_MS;
	}

	/** A grab key went down: its aim is measured from where the mouse is now. */
	private void startAim(long now)
	{
		grabAim = null;
		aimPressMs = now;
		aimOriginPending = !mouseKnown;
		aimOriginX = mouseX;
		aimOriginY = mouseY;
	}

	/**
	 * Mouse movement with no button pressed: with a grab key held it aims the grab (a drag with the flick button
	 * is a flick instead, see {@link #mouseDragged}). Not consumed: the game still sees the mouse move.
	 */
	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		if (!enabled)
			return e;
		if (buttonMode())
		{
			// button tricks: the right stick turns the camera, on foot and on the board (no flicks)
			if (mouseKnown)
				orbitPixels.addAndGet(e.getX() - mouseX);
		}
		else if (onFoot && padDoes(PadContext.FOOT, CAMERA_ORBIT))
		{
			// a held camera button: the right stick's sideways motion orbits, like a middle-button drag
			orbitPixels.addAndGet(e.getX() - orbitLastX);
			orbitLastX = e.getX();
		}
		mouseX = e.getX();
		mouseY = e.getY();
		mouseKnown = true;
		if (controllerMode && !buttonTricks)
		{
			// the right stick: with a grab key held it only aims the grab (rolling, only within the aim window)
			if (grabbing() && !stickFreeWhileGrabbing(e.getWhen()))
				stick.blockedMove(mouseX, mouseY, e.getWhen());
			else
				stick.move(mouseX, mouseY, e.getWhen());
		}
		// too long after the press (re-centring the mouse with the key held): this press stays unaimed
		if (!grabbing() || grabAim != null || e.getWhen() - aimPressMs > AIM_MS)
			return e;
		if (aimOriginPending)
			rebaseAim(mouseX, mouseY);
		else
			grabAim = GrabAim.classify(mouseX - aimOriginX, mouseY - aimOriginY, mirrorFlicks);
		return e;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (enabled)
		{
			mouseX = e.getX();
			mouseY = e.getY();
			mouseKnown = true;
			if (orbiting)
			{
				if (onFoot)
					orbitPixels.addAndGet(e.getX() - orbitLastX);
				orbitLastX = e.getX();
			}
			else
			{
				gesture.move(e.getX(), e.getY(), e.getWhen());
				rebaseAim(e.getX(), e.getY());
			}
			e.consume();
		}
		return e;
	}

	/**
	 * A flick-button drag or release with a grab key held and not aimed yet: the aim is measured from here, so
	 * the flick's own movement never counts towards it (the aim is a move without a button).
	 */
	private void rebaseAim(int x, int y)
	{
		if (grabbing() && grabAim == null)
		{
			aimOriginPending = false;
			aimOriginX = x;
			aimOriginY = y;
		}
	}
}

package com.gielinorskate.input;

import static com.gielinorskate.tricks.Gesture.Direction.*;
import static java.awt.event.KeyEvent.*;

import com.gielinorskate.tricks.*;
import com.gielinorskate.tricks.Gesture.Direction;

/**
 * The "Keyboard" trick controls: each key stands for one mouse flick, turned into the same {@link Gesture} the
 * recognizer would produce, so physics and {@link TrickCatalog} treat both alike.
 *
 * <ul>
 * <li>Space: ollie. 1: kickflip, 2: heelflip, 3: pop shove-it, 4: FS pop shove-it.</li>
 * <li>5 / 6: varial kickflip / heelflip, 7 / 8: 360 flip / laser flip, 9 / 0: 360 / FS 360 shove-it.</li>
 * <li>Shift held: the hard version (impossible, hardflip, inward heelflip, bigspins), as with a Shift flick.</li>
 * <li>Alt held when the key goes down: the nollie version (the flick mirrored top to bottom).</li>
 * <li>The same key again mid-flip: double (then triple) kickflip / heelflip, as a mouse re-flick.</li>
 * </ul>
 * The number-pad digits work too. Pure.
 */
public final class KeyboardTricks
{
	/** Path turn, in degrees, standing in for a curved flick: a varial (60-150) and a full 360 (150+). */
	static final float VARIAL_TURN = 90f;
	static final float FULL_TURN = 180f;
	/** The regular flick of each digit key 0-9: its direction and path turn. */
	private static final Direction[] DIGIT_FLICK = {RIGHT, UP_LEFT, UP_RIGHT, LEFT, RIGHT, UP_LEFT, UP_RIGHT, UP_LEFT,
		UP_RIGHT, LEFT};
	private static final float[] DIGIT_TURN = {FULL_TURN, 0f, 0f, 0f, 0f, VARIAL_TURN, VARIAL_TURN, FULL_TURN,
		FULL_TURN, FULL_TURN};
	/** The trick keys in the order the side panel names them. */
	private static final int[] KEYS = {VK_SPACE, VK_1, VK_2, VK_3, VK_4, VK_5, VK_6, VK_7, VK_8, VK_9, VK_0};

	private KeyboardTricks()
	{
	}

	/** True when {@code code} does a trick in keyboard mode (so it cannot be the wheelie key then). */
	public static boolean isTrickKey(int code)
	{
		return gestureFor(code, false, false) != null;
	}

	/**
	 * The gesture for a trick key, or null when {@code code} is not one.
	 *
	 * @param nollie Alt was held as the key went down
	 * @param modified Shift is held as the trick fires
	 */
	public static Gesture gestureFor(int code, boolean nollie, boolean modified)
	{
		int digit = code >= VK_0 && code <= VK_9 ? code - VK_0
			: code >= VK_NUMPAD0 && code <= VK_NUMPAD9 ? code - VK_NUMPAD0 : -1;
		if (digit < 0 && code != VK_SPACE)
			return null;
		Direction d = digit < 0 ? UP : DIGIT_FLICK[digit];
		return new Gesture(nollie ? flipVertically(d) : d, nollie, digit < 0 ? 0f : DIGIT_TURN[digit], modified);
	}

	/** A nollie flick goes the other way vertically: up becomes down; left and right stay. */
	static Direction flipVertically(Direction d)
	{
		// the directions go round in 45 degree steps from UP, so this reflects the index about LEFT / RIGHT
		return Direction.values()[(12 - d.ordinal()) % 8];
	}

	/**
	 * The key label for a trick in keyboard mode ("1", "Shift+1", "Alt+Space", "1, 1" for a double), or null when no
	 * key does it (grabs, grinds, ...). Used by the side panel's trick list.
	 */
	public static String keyFor(Trick trick)
	{
		for (int code : KEYS)
		{
			String key = code == VK_SPACE ? "Space" : String.valueOf(code - VK_0);
			// plain, Alt, Shift, Shift+Alt
			for (int mods = 0; mods < 4; mods++)
			{
				boolean alt = (mods & 1) != 0;
				boolean shift = mods >= 2;
				if (TrickCatalog.forGesture(gestureFor(code, alt, shift)) == trick)
					return (shift ? "Shift+" : "") + (alt ? "Alt+" : "") + key;
			}
		}
		// a double or triple: the same key again mid-flip
		for (Trick from : Trick.values())
		{
			for (int code : KEYS)
			{
				if (TrickCatalog.upgrade(from, gestureFor(code, false, false)) == trick)
				{
					String first = keyFor(from);
					return first == null ? null : first + ", " + (code == VK_SPACE ? "Space" : code - VK_0);
				}
			}
		}
		return null;
	}

	/** The mirror image (left and right swapped) of a mouse flick, for the "Mirror flicks" setting. */
	public static Gesture mirror(Gesture g)
	{
		return new Gesture(mirror(g.direction), g.nollie, g.turnDegrees, g.modified);
	}

	static Direction mirror(Direction d)
	{
		// the directions go round in 45 degree steps from UP, so this reflects the index about UP / DOWN
		return Direction.values()[(8 - d.ordinal()) % 8];
	}
}

package com.gielinorskate.input;

import com.gielinorskate.tricks.Gesture.Direction;
import lombok.AllArgsConstructor;

/**
 * A read-only copy of the flick stroke in progress, for the HUD's live flick visualizer: where the mouse is
 * relative to where the flick button went down, the last moments of its path, the wind-up state and the latest
 * recognised flick. Copied under the recognizer's lock, so it can be read on any thread. Screen pixels, y down;
 * times on the input clock ({@link #nowMs} is "now" on it).
 */
@AllArgsConstructor
public final class LiveStroke
{
	/** The flick button is held. */
	public final boolean held;
	/** Where the button went down, and where the mouse is now. */
	public final float originX;
	public final float originY;
	public final float x;
	public final float y;
	/** The recent path, oldest first (the last {@link GestureRecognizer#LIVE_TRAIL_MS} or so). */
	public final float[] trailX;
	public final float[] trailY;
	public final long[] trailMs;
	/** Wound up (a pull down, or a push up for a nollie) and waiting for the flick. */
	public final boolean wound;
	public final boolean nollie;
	/** The wind-up's turnaround point; meaningful while {@link #wound}. */
	public final float extremeX;
	public final float extremeY;
	/** The latest flick (mouse or keyboard trick): its direction, nollie flag and time; null direction when none. */
	public final Direction firedDirection;
	public final boolean firedNollie;
	public final long firedMs;
	/** Wind-up plus flick distance at the current sensitivity: the ring's radius stands for this many pixels. */
	public final float reachPx;
	public final long nowMs;

	/** Just a fired flick (a keyboard trick or a button flip), for the visualizer's sector flash. */
	static LiveStroke fired(Direction direction, boolean nollie, long ms)
	{
		return new LiveStroke(false, 0, 0, 0, 0, new float[0], new float[0], new long[0], false, false, 0, 0, direction,
			nollie, ms, 1f, 0);
	}

	/** This stroke with a different latest flick (a keyboard trick that came after the last mouse flick). */
	public LiveStroke withFired(Direction direction, boolean nollie, long ms)
	{
		return new LiveStroke(held, originX, originY, x, y, trailX, trailY, trailMs, wound, this.nollie, extremeX,
			extremeY, direction, nollie, ms, reachPx, nowMs);
	}
}

package com.gielinorskate.input;

import com.gielinorskate.Text;
import java.util.List;

/** Why a mouse stroke that looked like a trick attempt did not become one (see {@link GestureRecognizer}). */
public enum NearMiss
{
	/** Wound up and moved toward a flick, but too slowly to count. */
	TOO_SLOW,
	/** Wound up, then let go after only a short flick. */
	TOO_SHORT,
	/** A sideways flick with no pull down (or push up) first. */
	NO_WIND_UP;

	/** The HUD hint. */
	public final String hint;
	/** The hint in controller mode, with drawn button tokens ("{RS}", see ControllerGlyphs). */
	public final String controllerHint;

	/** Both hints, from text/overlay.properties ("miss." + name: the HUD line, then the controller one). */
	NearMiss()
	{
		List<String> lines = Text.lines("miss." + name());
		hint = lines.get(0);
		controllerHint = lines.get(1);
	}
}

package com.gielinorskate.input;

/** The latest pointer samples (position and time) in a ring of fixed size. Not thread-safe: its owner locks. */
final class Samples
{
	final float[] x;
	final float[] y;
	final long[] ms;
	/** How many are kept (at most the ring's size). */
	int count;
	private int next;

	Samples(int size)
	{
		x = new float[size];
		y = new float[size];
		ms = new long[size];
	}

	void add(float px, float py, long pms)
	{
		x[next] = px;
		y[next] = py;
		ms[next] = pms;
		next = (next + 1) % ms.length;
		count = Math.min(ms.length, count + 1);
	}

	/** The ring index of the sample {@code k} before the newest. */
	int ago(int k)
	{
		return (next - 1 - k + ms.length) % ms.length;
	}

	/**
	 * Speed in px/ms to (px, py, pms) from the newest sample at least {@code spanMs} older (or else the oldest one of
	 * the newest {@code limit}, and none from before {@code notBefore}); {@code none} when there is no older sample.
	 * The current sample must already be added.
	 */
	float speed(float px, float py, long pms, long spanMs, int limit, long notBefore, float none)
	{
		int from = -1;
		for (int k = 1; k < Math.min(count, limit); k++)
		{
			int i = ago(k);
			if (ms[i] < notBefore)
				break;
			from = i;
			if (ms[i] <= pms - spanMs)
				break;
		}
		return from < 0 || ms[from] >= pms ? none : (float) (Math.hypot(px - x[from], py - y[from]) / (pms - ms[from]));
	}
}

package com.gielinorskate.input;

/**
 * The button-trick manual (the Tony Hawk's American Wasteland preset): a quick up-then-down on the left stick while
 * rolling is a manual, down-then-up a nose manual. The second half must come within {@link #WINDOW_MS} of the first.
 * The manual then holds by itself (see {@link InputController}) until the skater pops, lands it off or does the
 * other gesture. Pure, with explicit times; synchronized because the stick arrives on the AWT thread.
 */
public final class StickManual
{
	/** The up and the down (or the down and the up) must come within this many ms. */
	public static final long WINDOW_MS = 300;

	public enum Kind
	{
		NONE,
		MANUAL,
		NOSE
	}

	private long upAt = Long.MIN_VALUE;
	private long downAt = Long.MIN_VALUE;

	/**
	 * The stick went up at {@code now}: a nose manual when it went down within {@link #WINDOW_MS} before, else
	 * {@link Kind#NONE} (the up is remembered for a manual).
	 */
	public synchronized Kind up(long now)
	{
		Kind k = within(downAt, now) ? Kind.NOSE : Kind.NONE;
		downAt = Long.MIN_VALUE;
		upAt = k == Kind.NONE ? now : Long.MIN_VALUE;
		return k;
	}

	/** The stick went down at {@code now}: a manual when it went up within {@link #WINDOW_MS} before. */
	public synchronized Kind down(long now)
	{
		Kind k = within(upAt, now) ? Kind.MANUAL : Kind.NONE;
		upAt = Long.MIN_VALUE;
		downAt = k == Kind.NONE ? now : Long.MIN_VALUE;
		return k;
	}

	/** Forgets a half-done gesture (the skater left the ground, or the stick was let go of for good). */
	public synchronized void reset()
	{
		upAt = Long.MIN_VALUE;
		downAt = Long.MIN_VALUE;
	}

	private static boolean within(long at, long now)
	{
		return at != Long.MIN_VALUE && now - at <= WINDOW_MS && now >= at;
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.session.SkateSession;
import java.awt.*;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

/**
 * Comfort hints while skating, at the top centre of the 3D viewport: the idle-logout warning, "Edge of the
 * loaded area" near the invisible wall at the scene's edge, and a short "Stumble!" flash after a hard hit.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ComfortHintsOverlay extends Overlay
{
	/** The hints start this far below the viewport top, and wrap this far in from its sides. */
	private static final int TOP_MARGIN = 28;

	private final Client client;
	private final SkateSession session;

	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!session.isActive())
			return null;
		int vy = client.getViewportYOffset();
		int vw = client.getViewportWidth();
		int cx = client.getViewportXOffset() + vw / 2;
		int y = vy + TOP_MARGIN;

		g.setFont(FontManager.getRunescapeBoldFont());
		FontMetrics metrics = g.getFontMetrics();
		String idle = session.getIdleWarningText();
		if (idle != null)
		{
			for (String line : ControlsCardOverlay.wrap(idle, metrics, vw - 2 * TOP_MARGIN))
			{
				centred(g, line, cx, y, new Color(255, 190, 60), 1f);
				y += metrics.getHeight() + 4;
			}
		}
		centred(g, "Edge of the loaded area", cx, y, new Color(230, 230, 230), session.getEdgeHintAlpha());
		float stumble = session.getStumbleFlashAlpha();
		if (stumble > 0f)
		{
			// half again as big, 15% of the viewport height above its centre
			g.setFont(g.getFont().deriveFont(g.getFont().getSize2D() * 1.5f));
			centred(g, "Stumble!", cx, vy + Math.round(client.getViewportHeight() * 0.35f), new Color(255, 140, 60),
				stumble);
		}
		return null;
	}

	private static void centred(Graphics2D g, String text, int cx, int y, Color color, float alpha)
	{
		if (alpha > 0f)
			HudLayout.centred(g, text, cx, y, HudLayout.fade(color, alpha), HudLayout.fade(Color.BLACK, alpha), 1);
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.Text;
import com.gielinorskate.controller.*;
import com.gielinorskate.input.KeyboardTricks;
import com.gielinorskate.session.SkateSession;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.ui.*;
import java.awt.*;
import java.awt.font.FontRenderContext;
import java.awt.geom.RoundRectangle2D;
import java.util.*;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.*;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.*;

/**
 * The controls card, in the same visual style as {@link ScoreOverlay}: text over a translucent dark backing. One
 * card with the essential controls for the current mode (on the board or on foot; keys, flicks or pad buttons),
 * the core flicks drawn as arrows, and a pointer to the side panel's Trick Book for everything else. Shown by
 * itself until the player has pushed and jumped once; H shows and hides it ({@link ControlsCardTimer}, owned and
 * driven by {@link SkateSession}).
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ControlsCardOverlay extends Overlay
{
	private static final Color TITLE_COLOR = new Color(255, 215, 110);
	private static final Color SHADOW_COLOR = new Color(0, 0, 0, 140);
	/** Font sizes tried, largest first, until the card fits its region. */
	static final int MAX_FONT_SIZE = 16;
	static final int MIN_FONT_SIZE = 9;

	/**
	 * What the card shows: the settings its wording depends on. A value: cached by equality.
	 * {@code flickButton} is "right", "left" or "middle"; {@code controller}: the controls are named with drawn
	 * buttons of {@code preset}; {@code onFoot}: off the board, the walking controls; {@code boardKey}: the board
	 * on/off key (F by default).
	 */
	@EqualsAndHashCode
	@AllArgsConstructor
	public static final class Spec
	{
		final String manualKey;
		final boolean keyboardTricks;
		final boolean mouseTricks;
		final String flickButton;
		final boolean mirror;
		final boolean learned;
		final boolean controller;
		final boolean onFoot;
		final String boardKey;
		final PadPreset preset;
	}

	/**
	 * One line of content: text, or a row of {@link #cells} (several flick pictures with a word each on one line,
	 * never wrapped; its text is their words, for searching). A cell is a row with its picture as {@link #glyph}.
	 * A laid-out card's lines are rows too, the text ones wrapped.
	 */
	@AllArgsConstructor
	static final class Row
	{
		final String text;
		final Gesture glyph;
		final boolean title;
		final List<Row> cells;
	}

	/** A laid-out card: font, wrapped lines and the box size (padding included). */
	@AllArgsConstructor
	static final class Card
	{
		final Font font;
		final List<Row> lines;
		final int padding;
		final int lineGap;
		/** Width of a cell's picture column (a line height plus a gap). */
		final int glyphColumn;
		/** Space between the cells of a row of cells. */
		final int cellGap;
		final int width;
		final int height;
	}

	/** The card's bold sans-serif fonts, by size (MIN_FONT_SIZE..MAX_FONT_SIZE). */
	static final Font[] FONTS = new Font[MAX_FONT_SIZE + 1];

	static
	{
		for (int i = MIN_FONT_SIZE; i <= MAX_FONT_SIZE; i++)
			FONTS[i] = new Font(Font.SANS_SERIF, Font.BOLD, i);
	}

	private final Client client;
	private final SkateSession session;

	/** Fitted cards by spec and region size, so stepping on and off the board never lays out again (32 kept). */
	private final Map<List<Object>, Card> layouts = new LinkedHashMap<List<Object>, Card>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<List<Object>, Card> eldest)
		{
			return size() > 32;
		}
	};

	/**
	 * Loads the card's fonts' glyph data now. The first sans-serif font of a JVM is slow (font configuration,
	 * hundreds of ms), so the plugin calls this off the client thread at start-up rather than letting the first
	 * card shown stall a frame. Safe on any thread.
	 */
	public static void warmFonts()
	{
		FontRenderContext frc = new FontRenderContext(null, true, false);
		for (int i = MIN_FONT_SIZE; i <= MAX_FONT_SIZE; i++)
			FONTS[i].getStringBounds("Skating basics: push, jump 0123456789", frc);
	}

	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		float alpha = session.isActive() ? session.getControlsCardAlpha() : 0f;
		if (alpha <= 0f)
			return null;
		int[] region = region(HudLayout.of(client, HudLayout.NO_OBSTACLE));
		Spec spec = session.getControlsCardSpec();
		Card card = layouts.computeIfAbsent(Arrays.asList(spec, region[2], region[3]),
			k -> fit(g, rows(spec), region[2], region[3]));
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
		g.setFont(card.font);
		FontMetrics m = g.getFontMetrics();
		g.setColor(new Color(10, 12, 18, 180));
		g.fill(new RoundRectangle2D.Float(region[0], region[1], card.width, card.height, 10, 10));
		int top = region[1] + card.padding;
		for (Row line : card.lines)
		{
			int x = region[0] + card.padding;
			for (Row c : line.cells != null ? line.cells : Collections.singletonList(line))
			{
				if (c.glyph != null)
				{
					GestureGlyphPainter.paint(g, c.glyph, x, top, m.getHeight(), new Color(170, 180, 200),
						new Color(120, 200, 255));
					x += card.glyphColumn;
				}
				ControllerGlyphs.drawText(g, c.text, x, top + m.getAscent(), c.title ? TITLE_COLOR : Color.WHITE,
					SHADOW_COLOR, 1);
				x += ControllerGlyphs.width(c.text, m) + card.cellGap;
			}
			top += m.getHeight() + card.lineGap;
		}
		return null;
	}

	/**
	 * The card's region {x, y, maxWidth, maxHeight}: the top-left of the game viewport (so fixed mode never
	 * spills into the side panel), inset by a margin, down to 6 px above the tallest trick stack of
	 * {@link HudLayout}.
	 */
	static int[] region(HudLayout hud)
	{
		// 3% of the viewport height, 6..24 px
		int margin = Math.max(6, Math.min(24, Math.round(hud.vh * 0.03f)));
		int y = hud.vy + margin;
		return new int[]{hud.vx + margin, y, Math.max(0, hud.vw - 2 * margin),
			Math.max(0, Math.min(hud.vy + hud.vh - margin, hud.stackTopY - 6) - y)};
	}

	/**
	 * Lays the rows out at the largest font size from {@link #MAX_FONT_SIZE} down to {@link #MIN_FONT_SIZE} whose
	 * box, with lines word-wrapped to the width, fits maxW x maxH; the smallest size when none does.
	 */
	static Card fit(Graphics2D g, List<Row> content, int maxW, int maxH)
	{
		Card card = null;
		for (int size = MAX_FONT_SIZE; size >= MIN_FONT_SIZE && (card == null || card.width > maxW
			|| card.height > maxH); size--)
		{
			FontMetrics m = g.getFontMetrics(FONTS[size]);
			int padding = Math.max(4, Math.round(size * 0.55f));
			int lineGap = Math.max(1, size / 5);
			int glyphColumn = m.getHeight() + Math.max(3, size / 3);
			int cellGap = size * 2;
			List<Row> lines = new ArrayList<>();
			int textW = 0;
			for (Row row : content)
			{
				if (row.cells != null)
				{
					int w = -cellGap;
					for (Row c : row.cells)
						w += cellGap + glyphColumn + ControllerGlyphs.width(c.text, m);
					lines.add(row);
					textW = Math.max(textW, w);
					continue;
				}
				for (String piece : wrap(row.text, m, maxW - 2 * padding))
				{
					lines.add(new Row(piece, null, row.title, null));
					textW = Math.max(textW, ControllerGlyphs.width(piece, m));
				}
			}
			card = new Card(FONTS[size], lines, padding, lineGap, glyphColumn, cellGap, textW + padding * 2,
				(m.getHeight() + lineGap) * lines.size() - lineGap + padding * 2);
		}
		return card;
	}

	/**
	 * {@code line} broken at spaces into pieces no wider than maxW where possible (a single too-wide word stays
	 * whole). Glyph tokens ("{A}") hold no spaces, so they are never split.
	 */
	static List<String> wrap(String line, FontMetrics metrics, int maxW)
	{
		List<String> out = new ArrayList<>();
		String rest = line;
		while (ControllerGlyphs.width(rest, metrics) > maxW)
		{
			int cut = -1;
			for (int i = rest.indexOf(' '); i > 0; i = rest.indexOf(' ', i + 1))
			{
				if (ControllerGlyphs.width(rest.substring(0, i).trim(), metrics) > maxW)
					break;
				cut = i;
			}
			if (cut <= 0)
				break;
			out.add(rest.substring(0, cut).trim());
			rest = rest.substring(cut).trim();
		}
		out.add(rest);
		return out;
	}

	private static Row title(String text)
	{
		return new Row(text, null, true, null);
	}

	private static Row text(String text)
	{
		return new Row(text, null, false, null);
	}

	/** Each line of {@code text} as a text row. */
	private static void texts(List<Row> rows, String text)
	{
		for (String line : text.split("\n"))
			rows.add(text(line));
	}

	/** Every card's last lines: the Trick Book, and until the basics are learned how to put the card away. */
	private static List<Row> end(List<Row> rows, boolean learned)
	{
		rows.add(text(Text.get("card.book")));
		if (!learned)
			rows.add(title(Text.get("card.learn")));
		return rows;
	}

	/** The card's content for the spec: on foot, controller mode, or keys and mouse. Nine lines at most. */
	static List<Row> rows(Spec spec)
	{
		if (spec.onFoot)
			return onFootRows(spec);
		if (spec.controller)
			return spec.preset.buttonTricks() ? buttonTrickRows(spec) : controllerRows(spec);
		List<Row> rows = new ArrayList<>();
		rows.add(title(Text.get("card.hide", "H")));
		rows.add(text(Text.get("card.keys.basics")));
		if (spec.mouseTricks)
		{
			rows.add(title(Text.get("card.keys.mouse", spec.flickButton)));
			rows.add(coreFlicks(spec));
		}
		if (spec.keyboardTricks && spec.mouseTricks)
			// one line for both, so the card still fits a fixed-mode viewport
			rows.add(text(Text.get("card.keys.both")));
		else if (spec.keyboardTricks)
		{
			rows.add(title(Text.get("card.keys.trickTitle")));
			rows.add(text(Text.get("card.keys.tricks")));
		}
		rows.add(text(Text.get("card.keys.air", spec.manualKey)));
		rows.add(text(Text.get("card.keys.reset", spec.boardKey)));
		return end(rows, spec.learned);
	}

	/**
	 * The four flicks every skater needs first, side by side: ollie, kickflip, heelflip, shove-it. With mirrored
	 * flicks the pictures are mirrored and the tricks stay the same.
	 */
	private static Row coreFlicks(Spec spec)
	{
		List<Row> cells = new ArrayList<>();
		Direction[] dirs = {Direction.UP, Direction.UP_LEFT, Direction.UP_RIGHT, Direction.LEFT};
		String[] tricks = {"ollie", "kickflip", "heelflip", "shove-it"};
		for (int i = 0; i < dirs.length; i++)
		{
			Gesture g = new Gesture(dirs[i], false, 0f);
			cells.add(new Row(tricks[i], spec.mirror ? KeyboardTricks.mirror(g) : g, false, null));
		}
		return new Row(String.join("   ", tricks), null, false, cells);
	}

	/**
	 * Controller mode's card, with the preset's buttons drawn in (the universal profile: the left stick the arrows,
	 * the right stick the mouse, each button its own pad key). An action no button does is named by its keyboard
	 * key, which still works, or left out.
	 */
	static List<Row> controllerRows(Spec spec)
	{
		PadPreset p = spec.preset;
		PadContext b = PadContext.BOARD;
		String mod = PadWords.buttons(p, PadAction.HARD_MODIFIER, b, "/");
		String grabs = grabs(p, " / ", "Q / E");
		List<Row> rows = new ArrayList<>();
		rows.add(title(Text.get("card.hide", PadWords.or(p, PadAction.CONTROLS_CARD, b, "/", "H"))));
		List<String> basics = new ArrayList<>();
		basics.add(PadWords.or(p, PadAction.PUSH, b, " or ", "W") + ": push");
		basics.add("{LS} left/right: steer");
		addIf(basics, PadWords.buttons(p, PadAction.BRAKE, b, "/"), ": brake");
		addIf(basics, mod, ": Shift (hard tricks)");
		addIf(basics, PadWords.buttons(p, PadAction.OLLIE, b, "/"), " held, let go: ollie");
		rows.add(text(String.join("    ", basics)));
		if (spec.mouseTricks)
		{
			// with trick keys as well, they share the title so the card still fits a fixed-mode viewport
			rows.add(title(Text.get("card.pad.mouse") + (mod != null ? "  " + mod
				+ " held: harder" : "") + (spec.keyboardTricks ? ".  Keys too: Space, 1-0" : "")));
			rows.add(coreFlicks(spec));
		}
		else if (spec.keyboardTricks)
			rows.add(text(Text.get("card.pad.keys")));
		rows.add(text(Text.get("card.pad.air", grabs, mod != null ? " or " + mod : "")));
		rows.add(text(Text.get("card.pad.rail", grabs(p, "/", "Q/E"))));
		rows.add(text(Text.get("card.pad.reset", PadWords.or(p, PadAction.RESET, b, "/", "R"),
			PadWords.or(p, PadAction.BOARD_TOGGLE, b, "/", spec.boardKey), PadWords.or(p, PadAction.STOP, b, "/", "Esc"))));
		return end(rows, spec.learned);
	}

	/**
	 * Controller mode with a button-trick layout (Tony Hawk's American Wasteland): a direction on the left stick or
	 * the d-pad with the flip or grab button, the left stick's manual gesture, and the right stick on the camera.
	 */
	static List<Row> buttonTrickRows(Spec spec)
	{
		List<Row> rows = new ArrayList<>();
		List<String> lines = Text.lines("card.bt");
		for (int i = 0; i < lines.size(); i++)
			rows.add(new Row(PadWords.resolve(lines.get(i), spec.preset, spec.boardKey), null, i == 0 || i == 2, null));
		return end(rows, spec.learned);
	}

	/** The grab buttons, left hand then right ("{LT} / {RT}"), or the keys when the pad has neither. */
	private static String grabs(PadPreset p, String joiner, String fallback)
	{
		List<String> both = new ArrayList<>();
		addIf(both, PadWords.buttons(p, PadAction.GRAB_LEFT, PadContext.BOARD, joiner), "");
		addIf(both, PadWords.buttons(p, PadAction.GRAB_RIGHT, PadContext.BOARD, joiner), "");
		return both.isEmpty() ? fallback : String.join(joiner, both);
	}

	private static void addIf(List<String> out, String buttons, String what)
	{
		if (buttons != null)
			out.add(buttons + what);
	}

	/** Off the board: the walking controls (keys, or the pad's buttons drawn in). */
	static List<Row> onFootRows(Spec spec)
	{
		List<Row> rows = new ArrayList<>();
		PadPreset p = spec.controller ? spec.preset : null;
		PadContext f = PadContext.FOOT;
		String board = p != null ? PadWords.or(p, PadAction.BOARD_TOGGLE, f, "/", spec.boardKey) : spec.boardKey;
		rows.add(title(Text.get("card.foot.title", p != null ? PadWords.or(p, PadAction.CONTROLS_CARD, f, "/", "H")
			: "H")));
		if (p != null)
		{
			texts(rows, Text.get("card.foot.pad", PadWords.first(p, PadAction.SPRINT, f, "Shift"),
				PadWords.or(p, PadAction.JUMP, f, "/", "Space"), PadWords.or(p, PadAction.DROP_PICKUP, f, " / ", "Q / E")));
			String camera = PadWords.buttons(p, PadAction.CAMERA_ORBIT, f, "/");
			if (p.buttonTricks())
				rows.add(text("{RS}: turn the camera"));
			else if (camera != null)
				rows.add(text(Text.get("card.foot.orbit", camera)));
		}
		else
			texts(rows, Text.get("card.foot.keys"));
		texts(rows, Text.get("card.foot.end", board, p != null ? PadWords.or(p, PadAction.STOP, f, "/", "Esc") : "Esc"));
		return end(rows, true);
	}
}

package com.gielinorskate.overlay;

/**
 * Pure show/hide for the controls card. While the player has not yet learned the basics (pushed and jumped once),
 * starting to skate shows the card and keeps it up; 2 s after the first push-and-jump it fades over 1 s. H shows
 * it when hidden and hides it when shown. No client dependency.
 */
public final class ControlsCardTimer
{
	private boolean pushed;
	private boolean jumped;
	/** The card is up by itself (not by H), waiting for the basics. */
	private boolean autoShowing;
	/** When the auto-shown card starts fading (after the basics were learned), or -1. */
	private float fadeStart = -1f;
	/** Shown by H; overrides the auto-show. */
	private boolean manualOn;

	/**
	 * Call each time skating starts. {@code autoShow}: the "Show controls card" setting is on and the basics were
	 * not learned in an earlier session.
	 */
	public void onSkateStart(boolean autoShow)
	{
		manualOn = false;
		autoShowing = autoShow && !learnedBasics();
		if (autoShowing)
			fadeStart = -1f;
	}

	/** The skater pushed. */
	public void onPush(float now)
	{
		pushed = true;
		checkLearned(now);
	}

	/** The skater popped (an ollie or any flip). */
	public void onJump(float now)
	{
		jumped = true;
		checkLearned(now);
	}

	private void checkLearned(float now)
	{
		if (learnedBasics() && autoShowing && fadeStart < 0f)
			// lingers 2 s
			fadeStart = now + 2f;
	}

	/** True once the skater has both pushed and jumped (in this client session). */
	public boolean learnedBasics()
	{
		return pushed && jumped;
	}

	/** Treats the basics as learned already (an earlier session learned them). */
	public void markLearned()
	{
		pushed = true;
		jumped = true;
	}

	/** H pressed while skating: show the card when it is hidden, hide it when it is up (or fading). */
	public void toggle(float now)
	{
		manualOn = alpha(now) <= 0f;
		// H takes over from the auto-show for good this session
		autoShowing = false;
	}

	/** Opacity in [0, 1] at {@code now}; 0 means the card is not drawn. */
	public float alpha(float now)
	{
		if (manualOn || autoShowing && (fadeStart < 0f || now < fadeStart))
			return 1f;
		// fading over 1 s
		return autoShowing ? Math.max(0f, 1f - (now - fadeStart)) : 0f;
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.input.GestureRecognizer;
import com.gielinorskate.input.LiveStroke;
import com.gielinorskate.tricks.Gesture.Direction;

/**
 * Pure maths of the live flick visualizer inside the HUD ring: the mouse offset from where the flick button went
 * down, scaled so the ring's radius stands for a whole wind-up plus flick and clamped to the ring; a trail that
 * fades over {@link #TRAIL_MS}; and a wedge for the recognised flick direction that fades over 250 ms.
 */
public final class FlickVisualizer
{
	static final long TRAIL_MS = GestureRecognizer.LIVE_TRAIL_MS;

	/**
	 * Ring coordinates (relative to its centre, px, y down) of a mouse offset (dx, dy): scaled by radius / reachPx
	 * and clamped to the radius, keeping the direction.
	 */
	static float[] toRing(float dx, float dy, float reachPx, float radius)
	{
		float scale = radius / Math.max(1f, reachPx);
		float x = dx * scale;
		float y = dy * scale;
		float len = (float) Math.hypot(x, y);
		if (len > radius)
		{
			x *= radius / len;
			y *= radius / len;
		}
		return new float[]{x, y};
	}

	/** Opacity of a trail point {@code ageMs} old: 1 when new (or from the future), 0 at TRAIL_MS and older. */
	static float trailAlpha(long ageMs)
	{
		return ageMs < 0 ? 1f : Math.max(0f, 1f - ageMs / (float) TRAIL_MS);
	}

	/** Opacity of the direction wedge {@code ageMs} after a flick: fades from 1 to 0 over 250 ms. */
	static float flashAlpha(long ageMs)
	{
		return ageMs < 0 ? 0f : Math.max(0f, 1f - ageMs / 250f);
	}

	/**
	 * The wedge of a flick direction as {start, extent} in degrees for {@link java.awt.geom.Arc2D} (0 = right,
	 * counter-clockwise on screen). Matches the recognizer's sectors: up and down are 25 degrees either side of
	 * vertical, left and right 25 either side of horizontal, the diagonals the 40 degrees between.
	 */
	static double[] sector(Direction d)
	{
		double up = GestureRecognizer.OLLIE_SECTOR_DEG;
		double side = 90 - GestureRecognizer.HORIZONTAL_SECTOR_DEG;
		double diag = 90 - up - side;
		// by the directions' order: up, up-left, left, down-left, down, down-right, right, up-right
		double[][] sectors = {{90 - up, 2 * up}, {90 + up, diag}, {180 - side, 2 * side}, {180 + side, diag},
			{-90 - up, 2 * up}, {-side - diag, diag}, {-side, 2 * side}, {side, diag}};
		return sectors[d.ordinal()];
	}

	/** Whether there is anything to draw: the button is held, or a flick's wedge is still fading. */
	static boolean visible(LiveStroke s)
	{
		return s != null && (s.held || (s.firedDirection != null && flashAlpha(s.nowMs - s.firedMs) > 0f));
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.party.GhostLabel;
import com.gielinorskate.party.PartyGhostService;
import java.awt.*;
