import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.*;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.*;

/** Above each party ghost: the member's name, and their latest trick fading out over 1.5 s. */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class GhostLabelOverlay extends Overlay
{
	private final Client client;
	private final PartyGhostService ghosts;

	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		for (GhostLabel l : ghosts.getLabels())
		{
			Point p = Perspective.localToCanvas(client, l.x, l.y, l.z);
			if (p == null)
				continue;
			int y = p.getY();
			if (l.trick != null)
			{
				HudLayout.centred(g, l.trick, p.getX(), y, HudLayout.fade(new Color(255, 215, 64), l.trickAlpha),
					HudLayout.fade(Color.BLACK, l.trickAlpha), 1);
				y -= g.getFontMetrics().getHeight();
			}
			if (l.name != null)
				HudLayout.centred(g, l.name, p.getX(), y, Color.WHITE, Color.BLACK, 1);
		}
		return null;
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.session.SkateSession;
import com.gielinorskate.world.GrindSegment;
import java.awt.*;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.client.ui.overlay.*;

/**
 * "Show grindable edges": draws every grind segment of the current skate session as a yellow line at its
 * grindable top, and the rail a lock would catch right now brighter. Drawn only while skating with the setting on.
 */
@Singleton
public class GrindEdgesOverlay extends Overlay
{
	/** Local (x, y) plus up-positive absolute height to a canvas point, or null when off screen. */
	interface Projector
	{
		Point project(float x, float y, float h);
	}

	private final BooleanSupplier visible;
	private final Supplier<List<GrindSegment>> segments;
	private final Projector projector;
	private final Supplier<GrindSegment> predicted;

	@Inject
	GrindEdgesOverlay(Client client, SkateSession session)
	{
		// RuneLite heights are negative-up, so the absolute z of a top at height h is -h
		this(session::isShowingGrinds, session::getGrindSegments, (x, y, h) ->
		{
			net.runelite.api.Point p = Perspective.localToCanvas(client, Math.round(x), Math.round(y), Math.round(-h));
			return p == null ? null : new Point(p.getX(), p.getY());
		}, session::getPredictedGrind);
	}

	GrindEdgesOverlay(BooleanSupplier visible, Supplier<List<GrindSegment>> segments, Projector projector,
		Supplier<GrindSegment> predicted)
	{
		this.predicted = predicted;
		this.visible = visible;
		this.segments = segments;
		this.projector = projector;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!visible.getAsBoolean())
			return null;
		g.setColor(Color.YELLOW);
		g.setStroke(new BasicStroke(2f));
		for (GrindSegment s : segments.get())
			line(g, s);
		// the rail a lock would catch right now (while airborne): brighter and thicker
		GrindSegment target = predicted.get();
		if (target != null)
		{
			g.setColor(new Color(80, 255, 120));
			g.setStroke(new BasicStroke(4f));
			line(g, target);
		}
		return null;
	}

	/** The segment's top as a line, when both ends are on screen. */
	private void line(Graphics2D g, GrindSegment s)
	{
		Point a = projector.project(s.x0, s.y0, s.top0);
		Point b = a == null ? null : projector.project(s.x1, s.y1, s.top1);
		if (b != null)
			g.drawLine(a.x, a.y, b.x, b.y);
	}
}

package com.gielinorskate.overlay;

import java.awt.Color;
import java.awt.Graphics2D;
import net.runelite.api.Client;

/**
 * Score HUD layout anchors, relative to the 3D viewport rather than the canvas: the canvas corners hold
 * the minimap (top right, resizable mode) and the chatbox (bottom left/centre). Pure, apart from the shared text
 * drawing helpers of the overlays at the bottom.
 *
 * <p>The HUD is a single cluster in the lower-left of the viewport: a vertical stack of trick names
 * (newest at the bottom), a ring meter below it, the combo score to the right of the ring, and the
 * session total below the ring. Callout words ("Nice!") show centred in the upper viewport and XP drops float
 * up at its right, clear of the minimap.
 */
final class HudLayout
{
	/** No chatbox (or other widget) under the cluster. */
	static final int NO_OBSTACLE = Integer.MAX_VALUE;
	/** The session total and goal line font: this fraction of the ring radius, at least 11. */
	static final float TOTAL_FONT_FRACTION = 0.42f;
	/** Gap between the session total and the goal line under it (and between other stacked lines). */
	static final int LINE_GAP = 3;

	/** The viewport (the whole canvas when the client's is empty). */
	final int vx;
	final int vy;
	final int vw;
	final int vh;
	/** Ring centre, and its radius (scaled with viewport height and clamped to 22..48 px). */
	final int ringCenterX;
	final int ringCenterY;
	final int ringRadius;
	/** Left edge of the ring; the trick stack is left-aligned with it. */
	final int stackLeftX;
	/** Baseline of the newest (bottom) trick name line; older lines stack upward from here. */
	final int stackBaselineY;
	/** Left edge of the combo score number, vertically centred on the ring. */
	final int scoreLeftX;
	/** Baseline of the session total line below the ring cluster, left-aligned with the ring's left edge. */
	final int totalY;
	/** Top of the tallest trick stack (newest plus four older names); other HUD stays above this. */
	final int stackTopY;
	/** Bottom of the cluster's lowest text (the goal line under the session total). */
	final int clusterBottomY;
	/** Centre and baseline of the callout word ("Nice!"). */
	final int calloutCenterX;
	final int calloutBaselineY;
	/** Baseline of the level banner, centred on {@link #calloutCenterX}. */
	final int bannerBaselineY;
	/** Right edge and starting baseline of an XP drop, and how far it rises. */
	final int xpDropRightX;
	final int xpDropStartY;
	final int xpDropRise;

	/**
	 * From the client's viewport rectangle (the whole canvas when the viewport is empty), with the ring cluster
	 * (trick stack, ring, score, session total and goal line) lifted as one so its bottom stays 4 px above
	 * {@code obstacleTopY}, the top edge of the chatbox ({@link #NO_OBSTACLE} when there is none). It never rises
	 * past the viewport top. Nothing else moves.
	 */
	HudLayout(int vx, int vy, int vw, int vh, int canvasW, int canvasH, int obstacleTopY)
	{
		if (vw <= 0 || vh <= 0)
		{
			vx = 0;
			vy = 0;
			vw = canvasW;
			vh = canvasH;
		}
		this.vx = vx;
		this.vy = vy;
		this.vw = vw;
		this.vh = vh;
		int r = Math.max(22, Math.min(48, Math.round(vh * 0.045f)));
		ringRadius = r;
		// the ring's left edge 9% of the viewport width in, its centre 78% down
		ringCenterX = vx + Math.round(vw * 0.09f) + r;
		stackLeftX = ringCenterX - r;
		scoreLeftX = ringCenterX + r + Math.round(r * 0.6f);
		int centerY = vy + Math.round(vh * 0.78f);
		int baseline = centerY - r - Math.round(r * 0.35f);
		int total = centerY + r + Math.round(r * 0.55f);
		float totalFont = Math.max(11f, Math.round(r * TOTAL_FONT_FRACTION));
		// a line is 1.3 and a descent 0.3 of the font size (generous for the RuneScape fonts)
		int bottom = total + Math.round(totalFont * 1.3f) + LINE_GAP + Math.round(totalFont * 0.3f);
		// the full trick stack above its baseline: ScoreOverlay draws the newest name at 0.75 r and up to 4 older
		// names at 0.5 r, each a font height (~0.65 r) plus a 3 px gap: 0.75 + 4 * 0.65 = 3.35 r, plus 4 * 3 px
		int stackHeight = Math.round(r * 3.35f) + 12;
		// no lift without a chatbox: the difference is then hugely negative
		int lift = Math.max(0, Math.min(bottom + 4 - obstacleTopY, baseline - stackHeight - vy));
		ringCenterY = centerY - lift;
		stackBaselineY = baseline - lift;
		totalY = total - lift;
		clusterBottomY = bottom - lift;
		stackTopY = stackBaselineY - stackHeight;
		calloutCenterX = vx + vw / 2;
		calloutBaselineY = vy + Math.round(vh * 0.3f);
		bannerBaselineY = vy + Math.round(vh * 0.17f);
		// in resizable mode the viewport is the whole canvas and the minimap with its orbs (about 210 px wide)
		// covers the top right, so XP drops end left of it, where the game's own drops are; else 8 px in
		xpDropRightX = vx + vw - (vx <= 0 && vw >= canvasW ? 240 : 8);
		xpDropStartY = vy + Math.round(vh * 0.32f);
		xpDropRise = Math.round(vh * 0.18f);
	}

	/** The layout of the client's viewport now. */
	static HudLayout of(Client c, int obstacleTopY)
	{
		return new HudLayout(c.getViewportXOffset(), c.getViewportYOffset(), c.getViewportWidth(), c.getViewportHeight(),
			c.getCanvasWidth(), c.getCanvasHeight(), obstacleTopY);
	}

	/** Draws {@code s} at (x, y) over its shadow, {@code off} px down and right. */
	static void text(Graphics2D g, String s, int x, int y, Color color, Color shadow, int off)
	{
		g.setColor(shadow);
		g.drawString(s, x + off, y + off);
		g.setColor(color);
		g.drawString(s, x, y);
	}

	/** {@link #text} centred on {@code cx}, in the graphics' font. */
	static void centred(Graphics2D g, String s, int cx, int y, Color color, Color shadow, int off)
	{
		text(g, s, cx - g.getFontMetrics().stringWidth(s) / 2, y, color, shadow, off);
	}

	/** {@code c} with its alpha times {@code f}, clamped to 0..255. */
	static Color fade(Color c, float f)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), Math.max(0, Math.min(255, Math.round(c.getAlpha() * f))));
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.tricks.Trick;

/**
 * Pure elapsed-time tracker for the manual meter. {@link com.gielinorskate.physics.SkatePhysics} has no
 * getter for how long the current hold has run, so this times it from the outside using only its
 * existing state getters (which manual is currently held), sampled once per frame. Swapping between a
 * manual and a nose manual restarts it, matching the scorer's two separate holds. No client dependency.
 */
public final class ManualMeter
{
	/** The manual being timed, or null when none. */
	private Trick manual;
	private float startedAt;

	/**
	 * Call once per frame with the manual currently held (MANUAL or NOSE_MANUAL; null when not in a manual)
	 * and the clock's {@code now}.
	 */
	public void update(Trick current, float now)
	{
		if (current != manual)
		{
			manual = current;
			startedAt = now;
		}
	}

	/** "Manual 1.4s" / "Nose Manual 0.3s"-style label, or null when not currently in a manual. */
	public String text(float now)
	{
		return manual != null ? String.format("%s %.1fs", manual.displayName, Math.max(0f, now - startedAt)) : null;
	}
}

package com.gielinorskate.overlay;

import com.gielinorskate.feedback.Callout;
import com.gielinorskate.feedback.HudAnim;
import com.gielinorskate.input.LiveStroke;
import com.gielinorskate.progression.ProgressionService;
import com.gielinorskate.progression.SkateLevels;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.scoring.ScoreClock;
import com.gielinorskate.session.SkateSession;
import com.gielinorskate.ui.ControllerGlyphs;
import java.awt.*;
import java.awt.geom.*;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

/**
 * Score HUD, placed inside the 3D viewport ({@link HudLayout}) so the minimap and chatbox never cover
 * it. Drawn as a single cluster in the lower-left of the viewport: a vertical stack of trick names
 * (oldest on top, newest on the bottom in a larger bold font), a charging ring meter below it, the
 * current combo score beside the ring, and the session total underneath. A brief LANDED/BAILED flash
 * replaces the newest line and the score when a combo resolves.
 *
 * <p>Animated ({@link HudAnim}): new trick lines pop in, the ring pulses when the multiplier rises, a landed
 * score counts up and a bail shakes the cluster. A landed combo also gets an OSRS-style XP drop ("+1,234") and,
 * when big enough, a callout word ({@link Callout}). Text uses the RuneScape fonts. RuneLite restores the
 * graphics' hints, stroke, composite and transform after each overlay, so they are set freely here.
 */
@Singleton
@RequiredArgsConstructor(onConstructor_ = @Inject)
public class ScoreOverlay extends Overlay
{
	/** The landed/bailed flash; it fades over its last 0.4 s. */
	private static final float FLASH_SECONDS = 1.5f;
	/** How many older trick names (above the newest) are shown in the stack. */
	private static final int OLDER_TRICKS_SHOWN = 4;

	/** Flick visualizer: the trail and wedge of a regular flick, and of a nollie (push up first). */
	private static final Color FLICK_TINT = new Color(120, 200, 255);
	private static final Color NOLLIE_TINT = new Color(255, 170, 80);
	private static final Color SHADOW_COLOR = new Color(0, 0, 0, 140);
	private static final Color TOTAL_COLOR = new Color(190, 190, 190, 200);
	/** Ring stroke thickness, as a fraction of the ring radius. */
	private static final float RING_STROKE_FRACTION = 0.28f;
	/**
	 * Pop-in scales are snapped to multiples of 1/this. Java2D rasterises and caches glyphs per transform, so a
	 * new scale every frame re-rasterises the word every frame; snapped, the ~20 scales a pop passes through are
	 * cached after their first use. 1/40 is at most a 1.25% size error: under half a pixel on the biggest word.
	 */
	static final float SCALE_STEPS = 40f;

	private final Client client;
	private final ComboScorer scorer;
	private final SkateSession session;
	private final ScoreClock clock;
	private final ProgressionService progression;

	/** The fonts, derived again only when the ring radius (and so the viewport height) changes. */
	private int cachedRadius = -1;
	private Font newestFont;
	private Font olderFont;
	private Font scoreFont;
	private Font totalFont;
	private Font calloutFont;
	/** The callout's extra lines and the XP drop. */
	private Font smallFont;
	/** An older trick line's height plus the gap under it. */
	private int olderStep;

	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!session.isActive())
			return null;
		HudLayout layout = HudLayout.of(client, chatboxTop());
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		ensureFonts(g, layout.ringRadius);
		int x = layout.stackLeftX;

		float now = clock.now();
		LiveStroke live = session.getLiveStroke();
		boolean visualizer = FlickVisualizer.visible(live);
		drawCluster(g, layout, now, visualizer);
		if (visualizer)
			drawFlickVisualizer(g, layout, live);
		drawLandedExtras(g, layout, now);

		// the level banner every ten levels, above the callout words
		String banner = progression.getBannerText();
		if (banner != null)
		{
			float age = progression.getBannerAge();
			drawScaled(g, calloutFont, banner, layout.calloutCenterX, layout.bannerBaselineY, true,
				new Color(255, 200, 40), HudAnim.bannerAlpha(age), HudAnim.calloutScale(age));
		}

		// the session total, always drawn while skating, and the daily goal under it (gold when just completed)
		draw(g, totalFont, "Total " + String.format("%,d", scorer.sessionScore()), x, layout.totalY, TOTAL_COLOR, 1f);
		String goal = progression.getGoalLine();
		if (goal != null)
			draw(g, totalFont, goal, x, layout.totalY + g.getFontMetrics(totalFont).getHeight() + HudLayout.LINE_GAP,
				progression.isGoalFlashing() ? new Color(255, 200, 40, 230) : TOTAL_COLOR, 1f);

		// "Manual 1.4s" in a manual: a fixed gap above the stack's worst-case height, so it never overlaps the names
		String manual = session.getManualMeterText();
		if (manual != null)
			draw(g, olderFont, manual, x, layout.stackBaselineY - olderStep * (OLDER_TRICKS_SHOWN + 1),
				new Color(255, 205, 90, 230), 1f);

		// the near-miss flick hint ("Flick faster"): where the newest trick name goes when no combo shows, else
		// above the tallest stack and the manual meter; drawn last, as it leaves its composite set
		String hint = session.getTrickHintText();
		float hintAlpha = session.getTrickHintAlpha();
		if (hint != null && hintAlpha > 0f)
		{
			boolean idle = scorer.comboNames().isEmpty() && scorer.lastResultAge(now) >= FLASH_SECONDS;
			g.setFont(olderFont);
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(1f, hintAlpha)));
			// in controller mode the hint names the pad's buttons with drawn glyphs
			ControllerGlyphs.drawText(g, hint, x, layout.stackBaselineY - (idle ? 0 : olderStep
				* (OLDER_TRICKS_SHOWN + 2)), new Color(255, 225, 120), SHADOW_COLOR, 2);
		}
		return null;
	}

	/**
	 * Top edge of the chatbox on the canvas, from its widgets (overlays render on the client thread): the message
	 * area when shown, else the tab row (resizable with chat collapsed). In fixed mode both sit below the
	 * viewport, so the cluster stays put. {@link HudLayout#NO_OBSTACLE} when neither is shown.
	 */
	private int chatboxTop()
	{
		int top = HudLayout.NO_OBSTACLE;
		for (int id : new int[]{InterfaceID.Chatbox.CHATAREA, InterfaceID.Chatbox.CONTROLS})
		{
			Widget w = client.getWidget(id);
			Rectangle r = w == null || w.isHidden() ? null : w.getBounds();
			if (r != null && r.width > 0 && r.height > 0)
				top = Math.min(top, r.y);
		}
		return top;
	}

	private void ensureFonts(Graphics2D g, int r)
	{
		if (r == cachedRadius)
			return;
		cachedRadius = r;
		Font bold = FontManager.getRunescapeBoldFont();
		newestFont = bold.deriveFont((float) Math.round(r * 0.75f));
		// secondary lines are at least 12: the RuneScape fonts get hard to read below it
		olderFont = bold.deriveFont(Math.max(12f, Math.round(r * 0.5f)));
		scoreFont = bold.deriveFont((float) Math.round(r * 1.25f));
		totalFont = FontManager.getRunescapeFont().deriveFont(Math.max(11f, Math.round(r * HudLayout.TOTAL_FONT_FRACTION)));
		calloutFont = bold.deriveFont((float) Math.round(r * 1.6f));
		smallFont = bold.deriveFont(Math.max(12f, Math.round(r * 0.6f)));
		olderStep = g.getFontMetrics(olderFont).getHeight() + HudLayout.LINE_GAP;
	}

	private void drawCluster(Graphics2D g, HudLayout layout, float now, boolean visualizer)
	{
		ComboScorer.Result result = scorer.lastResult();
		float age = scorer.lastResultAge(now);
		boolean landed = result.isLanded() && age < FLASH_SECONDS;
		if (!landed && !(result.isBailed() && age < FLASH_SECONDS))
		{
			List<String> names = scorer.comboNames();
			if (!names.isEmpty())
			{
				drawStack(g, layout, names, names.get(names.size() - 1), Color.WHITE, 1f,
					HudAnim.popScale(now - scorer.newestNameTime()));
				drawRing(g, layout, scorer.multiplier(), 1f, now - scorer.multiplierRiseTime());
				drawScore(g, layout, String.valueOf(scorer.comboPoints() * scorer.multiplier()), Color.WHITE, false, 1f);
			}
			else if (visualizer)
				// idle, the cluster hidden: the ring alone shows while the flick visualizer draws in it
				drawRing(g, layout, 0, 1f, Float.MAX_VALUE);
			return;
		}

		float fade = Math.max(0f, Math.min(1f, (FLASH_SECONDS - age) / 0.4f));
		// the scorer has already reset: the finished combo shows with the result as its last line
		List<String> names = new ArrayList<>(scorer.lastComboNames());
		names.add("");
		// green or red
		Color color = landed ? new Color(90, 220, 110) : new Color(230, 70, 70);
		// a bail shakes the whole cluster for a moment
		int dx = landed ? 0 : HudAnim.shakeX(age);
		int dy = landed ? 0 : HudAnim.shakeY(age);
		g.translate(dx, dy);
		String reason = landed ? null : session.getBailReasonText();
		if (reason != null)
		{
			// "Bailed" moves up a line for the reason under it; one older name fewer keeps the stack's height
			g.translate(0, -olderStep);
			drawStack(g, layout, names.subList(Math.max(0, names.size() - OLDER_TRICKS_SHOWN), names.size()), "Bailed",
				color, fade, HudAnim.popScale(age));
			g.translate(0, olderStep);
			draw(g, olderFont, reason, layout.stackLeftX, layout.stackBaselineY, new Color(255, 170, 160), fade);
		}
		else
			drawStack(g, layout, names, landed ? result.clean ? "Clean landing" : "Landed" : "Bailed", color, fade,
				HudAnim.popScale(age));
		drawRing(g, layout, 0, fade, Float.MAX_VALUE);
		drawScore(g, layout, String.valueOf(landed ? HudAnim.countUp(result.value, age) : result.value), color, !landed,
			fade);
		g.translate(-dx, -dy);
	}

	/**
	 * The OSRS-style XP-drop text for a landed combo worth {@code comboValue} points: the Skating XP it actually
	 * awards ({@link SkateLevels#xpForCombo}), not the combo score (which keeps its own, unchanged, display).
	 */
	static String xpDropText(int comboValue)
	{
		return "+" + String.format("%,d", SkateLevels.xpForCombo(comboValue));
	}

	/**
	 * After a landing: the XP drop floating up at the right and, for a big enough combo, the callout word with
	 * its extra lines. Both show even once a new combo has started.
	 */
	private void drawLandedExtras(Graphics2D g, HudLayout layout, float now)
	{
		ComboScorer.Result result = scorer.lastResult();
		if (!result.isLanded() || result.value <= 0)
			return;
		float age = scorer.lastResultAge(now);
		String xp = xpDropText(result.value);
		draw(g, smallFont, xp, layout.xpDropRightX - g.getFontMetrics(smallFont).stringWidth(xp),
			layout.xpDropStartY - Math.round(layout.xpDropRise * HudAnim.xpDropRise(age)), Color.WHITE,
			HudAnim.xpDropAlpha(age));

		float alpha = HudAnim.calloutAlpha(age);
		if (alpha <= 0f)
			return;
		Callout word = Callout.forValue(result.value);
		List<String> extras = new ArrayList<>(Callout.extras(word, result.clean, scorer.lastResultMultiplier(),
			scorer.lastResultTrickCount()));
		ComboScorer.Summary summary = scorer.lastSummary();
		extras.addAll(Callout.varietyLines(summary.newTricks, summary.longCombo));
		int y = layout.calloutBaselineY;
		int step = g.getFontMetrics(smallFont).getHeight() + HudLayout.LINE_GAP;
		if (word != null)
		{
			drawScaled(g, calloutFont, word.word, layout.calloutCenterX, y, true, word.color, alpha,
				HudAnim.calloutScale(age));
			y += step;
		}
		for (String line : extras)
		{
			drawScaled(g, smallFont, line, layout.calloutCenterX, y, true, new Color(255, 230, 150), alpha, 1f);
			y += step;
		}
	}

	/** Draws text scaled by {@code scale} about (x, baseline): its left end there, or its centre when centred. */
	private static void drawScaled(Graphics2D g, Font font, String text, int x, int baseline, boolean centred,
		Color color, float fade, float scale)
	{
		int left = centred ? -g.getFontMetrics(font).stringWidth(text) / 2 : 0;
		AffineTransform saved = g.getTransform();
		g.translate(x, baseline);
		float snapped = quantiseScale(scale);
		g.scale(snapped, snapped);
		draw(g, font, text, left, 0, color, fade);
		g.setTransform(saved);
	}

	/**
	 * Draws the vertical trick stack: up to {@link #OLDER_TRICKS_SHOWN} older names above the newest
	 * line, oldest most transparent, with {@code newestLabel} (and {@code newestColor}) always last, popping in.
	 */
	private void drawStack(Graphics2D g, HudLayout layout, List<String> names, String newestLabel,
		Color newestColor, float fade, float newestScale)
	{
		// the newest trick itself is replaced by newestLabel during a flash, so only the names before it are older
		int last = names.size() - 1;
		int older = Math.min(OLDER_TRICKS_SHOWN, Math.max(0, last));
		for (int rank = 0; rank < older; rank++)
			// oldest the most transparent
			draw(g, olderFont, names.get(last - older + rank), layout.stackLeftX,
				layout.stackBaselineY - olderStep * (older - rank),
				HudLayout.fade(new Color(220, 220, 220, 170), (rank + 1f) / (older + 1f)), fade);
		drawScaled(g, newestFont, newestLabel, layout.stackLeftX, layout.stackBaselineY, false, newestColor, fade,
			newestScale);
	}

	/** @param riseAge seconds since the multiplier last rose: the charge arc pulses thicker and flashes white */
	private static void drawRing(Graphics2D g, HudLayout layout, int multiplier, float fade, float riseAge)
	{
		int r = layout.ringRadius;
		float stroke = r * RING_STROKE_FRACTION;
		double x = layout.ringCenterX - r + stroke / 2.0;
		double y = layout.ringCenterY - r + stroke / 2.0;
		double d = (r - stroke / 2.0) * 2;
		Ellipse2D disc = new Ellipse2D.Double(x, y, d, d);
		g.setColor(HudLayout.fade(new Color(20, 25, 35, 140), fade));
		g.fill(disc);
		g.setStroke(new BasicStroke(stroke, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(HudLayout.fade(new Color(150, 170, 200, 170), fade));
		g.draw(disc);

		// full at x10
		float charge = Math.min(multiplier, 10f) / 10f;
		if (charge > 0f)
		{
			float flash = HudAnim.ringFlash(riseAge);
			g.setStroke(new BasicStroke(stroke * HudAnim.ringPulse(riseAge), BasicStroke.CAP_ROUND,
				BasicStroke.JOIN_ROUND));
			// the charge blue (120, 170, 255, 200) flashed that far towards opaque white
			g.setColor(HudLayout.fade(new Color(Math.round(120 + 135 * flash), Math.round(170 + 85 * flash), 255,
				Math.round(200 + 55 * flash)), fade));
			g.draw(new Arc2D.Double(x, y, d, d, 90, -360 * charge, Arc2D.OPEN));
		}
	}

	private void drawScore(Graphics2D g, HudLayout layout, String text, Color color, boolean strikethrough,
		float fade)
	{
		FontMetrics metrics = g.getFontMetrics(scoreFont);
		int y = layout.ringCenterY + (metrics.getAscent() - metrics.getDescent()) / 2;
		draw(g, scoreFont, text, layout.scoreLeftX, y, color, fade);
		if (strikethrough)
		{
			// in the faded colour draw left set
			g.setStroke(new BasicStroke(Math.max(2f, scoreFont.getSize() * 0.08f)));
			int strikeY = y - metrics.getAscent() / 3;
			g.drawLine(layout.scoreLeftX, strikeY, layout.scoreLeftX + metrics.stringWidth(text), strikeY);
		}
	}

	/**
	 * The live flick visualizer inside the ring: the recognised direction's wedge flashing, the last 300 ms of the
	 * mouse path fading, the wind-up's turnaround point, and a dot where the mouse is (tinted for a nollie).
	 */
	private static void drawFlickVisualizer(Graphics2D g, HudLayout layout, LiveStroke live)
	{
		int cx = layout.ringCenterX;
		int cy = layout.ringCenterY;
		int r = layout.ringRadius;
		float inner = r * (1f - RING_STROKE_FRACTION / 2f);
		float flash = live.firedDirection == null ? 0f : FlickVisualizer.flashAlpha(live.nowMs - live.firedMs);
		if (flash > 0f)
		{
			double[] arc = FlickVisualizer.sector(live.firedDirection);
			g.setColor(HudLayout.fade(live.firedNollie ? NOLLIE_TINT : FLICK_TINT, 150 / 255f * flash));
			g.fill(new Arc2D.Double(cx - inner, cy - inner, 2 * inner, 2 * inner, arc[0], arc[1], Arc2D.PIE));
		}
		if (!live.held)
			return;
		g.setStroke(new BasicStroke(Math.max(1.5f, r * 0.08f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 1; i < live.trailMs.length; i++)
		{
			float a = FlickVisualizer.trailAlpha(live.nowMs - live.trailMs[i]);
			if (a > 0f)
			{
				float[] p = toRing(live, live.trailX[i - 1], live.trailY[i - 1], inner);
				float[] q = toRing(live, live.trailX[i], live.trailY[i], inner);
				g.setColor(HudLayout.fade(live.nollie ? NOLLIE_TINT : FLICK_TINT, 200 / 255f * a));
				g.draw(new Line2D.Float(cx + p[0], cy + p[1], cx + q[0], cy + q[1]));
			}
		}
		if (live.wound)
		{
			float[] e = toRing(live, live.extremeX, live.extremeY, inner);
			float er = Math.max(2f, r * 0.1f);
			g.setStroke(new BasicStroke(1f));
			g.setColor(new Color(255, 255, 255, 110));
			g.draw(new Ellipse2D.Float(cx + e[0] - er, cy + e[1] - er, 2 * er, 2 * er));
		}
		float[] d = toRing(live, live.x, live.y, inner);
		float dr = Math.max(2.5f, r * 0.13f);
		g.setColor(SHADOW_COLOR);
		g.fill(new Ellipse2D.Float(cx + d[0] - dr + 1, cy + d[1] - dr + 1, 2 * dr, 2 * dr));
		g.setColor(live.nollie ? NOLLIE_TINT : Color.WHITE);
		g.fill(new Ellipse2D.Float(cx + d[0] - dr, cy + d[1] - dr, 2 * dr, 2 * dr));
	}

	/** A mouse position of the stroke in ring coordinates. */
	private static float[] toRing(LiveStroke live, float x, float y, float inner)
	{
		return FlickVisualizer.toRing(x - live.originX, y - live.originY, live.reachPx, inner);
	}

	/** Text in {@code font}, faded by {@code fade} (0..1) with its shadow, so fading text leaves no shadow behind. */
	private static void draw(Graphics2D g, Font font, String text, int x, int y, Color color, float fade)
	{
		g.setFont(font);
		HudLayout.text(g, text, x, y, HudLayout.fade(color, fade), HudLayout.fade(SHADOW_COLOR, fade), 2);
	}

	/** {@code scale} snapped to the nearest multiple of 1/{@link #SCALE_STEPS} (1 stays exactly 1). */
	static float quantiseScale(float scale)
	{
		return Math.round(scale * SCALE_STEPS) / SCALE_STEPS;
	}
}

package com.gielinorskate.party;

/**
 * The local skater's front / back flip rate for the party, measured over physics time, and whether the flip
 * started, stopped or reversed this frame. That change goes out at once instead of waiting for the next
 * snapshot, so a ghost does not keep flipping for up to 0.6 s after the skater let go. Pure.
 */
final class BodyFlipMeter
{
	/**
	 * Rates at least this fast (rad/s) are a held flip: SkatePhysics turns a held flip at 2 pi / 0.55 = 11.4
	 * rad/s and eases a released one onto the whole turn at 3 rad/s, so 6 is safely between the two.
	 */
	static final float HELD_RATE = 6f;

	private float last = Float.NaN;
	private float rate;
	private int direction;
	private boolean changed;

	/**
	 * One render frame that ran {@code dt} seconds of physics steps (0 for none).
	 *
	 * @param angle the body flip angle (SkatePhysics.getBodyFlipAngle)
	 */
	void update(float angle, boolean airborne, float dt)
	{
		if (airborne && !Float.isNaN(last) && dt <= 0f)
		{
			// no physics step: nothing moved, keep the rate
			changed = false;
			return;
		}
		int before = direction;
		if (!airborne)
			// on the ground (or a rail) the angle is reset to 0, which is not a rotation
			rate = 0f;
		else if (!Float.isNaN(last))
			rate = (angle - last) / dt;
		last = angle;
		direction = directionOf(rate);
		changed = direction != before;
	}

	/** Rad/s, + = frontflip. */
	float rate()
	{
		return rate;
	}

	/** 1 while a frontflip is held, -1 a backflip, else 0. */
	int direction()
	{
		return direction;
	}

	/** {@link #direction} changed on the latest update. */
	boolean directionChanged()
	{
		return changed;
	}

	void reset()
	{
		last = Float.NaN;
		rate = 0f;
		direction = 0;
		changed = false;
	}

	static int directionOf(float rate)
	{
		return rate >= HELD_RATE ? 1 : rate <= -HELD_RATE ? -1 : 0;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.render.*;
import lombok.AllArgsConstructor;
import net.runelite.api.gameval.AnimationID;

/**
 * The OSRS animation a ghost's body plays under its procedural pose: the local skater's (the default skate poses),
 * on the ghost's own copy of the member's model, never on their character. Pure.
 */
@AllArgsConstructor
enum GhostAnim
{
	/** On foot standing: the member's own standing frame, as snapshotted. */
	NONE(-1, true),
	/** The riding stance (also grinds, manuals and the tumble). */
	STANCE(AnimationID.HUMAN_SKI_IDLE, true),
	WALK(AnimationID.HUMAN_WALK_F, true),
	RUN(AnimationID.HUMAN_RUNNING, true),
	/** Knocked down: lying (a loop), then getting up (paced by the get-up's progress). */
	LIE(AnimationID.HUMAN_KNOCKDOWN_LOOP_NODELAY, true),
	GET_UP(AnimationID.HUMAN_GETUP, false);

	private final int defaultId;
	/** Plays round and round at its own pace (else it is set by a progress). */
	final boolean loops;

	/** The animation ID: the member's own walk or run when known (their weapon's), else the game's; -1 for none. */
	int id(int memberWalk, int memberRun)
	{
		return this == WALK && memberWalk >= 0 ? memberWalk : this == RUN && memberRun >= 0 ? memberRun : defaultId;
	}

	/** What a ghost plays: on foot by its gait, on the board the stance, knocked down the lie-down and get-up. */
	static GhostAnim pick(boolean onFoot, FootBody.Gait gait, KnockdownPose.Stage knock)
	{
		return knock == KnockdownPose.Stage.LIE ? LIE : knock == KnockdownPose.Stage.GET_UP ? GET_UP
			: knock != null || !onFoot ? STANCE : gait == FootBody.Gait.WALK ? WALK : gait == FootBody.Gait.RUN ? RUN
			: NONE;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.Text;
import com.gielinorskate.render.*;
import java.util.Arrays;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.AnimationID;

/**
 * A party ghost's body, drawn as the local skater's is (the riding stance, walk and run, the lie-down and get-up,
 * with the procedural {@link BodyPose} on top) without ever touching the member's real character on this client:
 * its animations, frames and model are only read. Each draw takes the member's model as the client hands it out
 * and, only when that is provably the per-request buffer the client rebuilds on every request ({@link LayeredBody}),
 * draws our own {@link MeshSnapshot} of the member standing (taken once while their character stands in its plain
 * idle, again when their appearance changes) in it, with our OSRS animation applied by the client to that canvas
 * ({@code Client.applyTransformations}: it animates the model it is given, not an actor) and the pose deformed in.
 * Without that proof the member's model is drawn as is; any failure falls back for this ghost (the layer alone, or
 * the whole body: then the member's model is drawn plain). Client thread only; no allocation per frame.
 */
@Slf4j
@RequiredArgsConstructor
final class GhostBodyController extends RuneLiteObjectController
{
	/** The body as animated, no procedural pose (a far ghost's, see GhostDetail). */
	private static final BodyPose NEUTRAL = new BodyPose();

	private final Client client;
	private final BodyPose pose;
	private final MeshSnapshot snapshot = new MeshSnapshot();
	private final BufferProbe.Probe<Model> probe = new BufferProbe.Probe<>();
	/** Reads the drawn body's right hand while the board is carried. */
	final HandAnchor hand = new HandAnchor();
	private final AnimClock clock = new AnimClock();
	private final LayeredBody.Layer<Model> layer = this::applyLayer;
	private final BufferProbe.Source<Model> source = () ->
	{
		Player q = this.player;
		return q == null ? null : q.getModel();
	};
	Player player;

	/** The animation playing now and its frame (-1: none), set each frame by {@link #animate}. */
	private GhostAnim anim = GhostAnim.NONE;
	private int animId = -1;
	private Animation animation;
	/** Its frame lengths: a classic animation's own, or one tick per frame for a Maya one (AnimClock.tickFrames). */
	private int[] lengths;
	private int frame = -1;
	/** The procedural pose is drawn (the ghost is near enough, GhostDetail). */
	boolean full = true;
	/** The last draw had our animation on it (a lie-down or get-up then needs no procedural fall). */
	boolean layered;
	/** The OSRS layer failed once: this ghost plays none from then on. */
	private boolean layerFailed;
	/** A Maya animation failed once: this ghost plays only classic ones from then on (walk, run, the get-up). */
	private boolean mayaFailed;
	/** The body failed once: this ghost is drawn as the member's plain model from then on. */
	private boolean failed;

	void setPlayer(Player player)
	{
		if (player != this.player)
			snapshot.clear();
		this.player = player;
	}

	/**
	 * This frame's animation: {@code a} at {@code rate} times the game's pace for a looping one, else at
	 * {@code progress} (0..1) through it. Client thread, before the draw.
	 */
	void animate(GhostAnim a, float rate, float progress, float dt)
	{
		Player p = player;
		int id = p == null || layerFailed ? -1 : a.id(p.getWalkAnimation(), p.getRunAnimation());
		if (a != anim || id != animId)
		{
			anim = a;
			animId = id;
			animation = null;
			clock.reset();
		}
		if (id >= 0 && animation == null)
		{
			try
			{
				Animation loaded = client.loadAnimation(id);
				animation = loaded != null && loaded.isMayaAnim() && mayaFailed ? null : loaded;
				// a Maya (skeletal) animation's frame is the tick within its duration
				lengths = animation == null ? null : animation.isMayaAnim()
					? AnimClock.tickFrames(animation.getDuration()) : animation.getFrameLengths();
			}
			catch (RuntimeException ex)
			{
				failLayer(ex);
				return;
			}
		}
		frame = id < 0 || animation == null ? -1
			: a.loops ? clock.loop(lengths, rate, dt) : clock.seek(lengths, progress);
	}

	@Override
	public Model getModel()
	{
		Player p = player;
		if (p == null)
			return null;
		if (failed)
		{
			layered = false;
			return p.getModel();
		}
		try
		{
			return draw(p);
		}
		catch (RuntimeException ex)
		{
			failed = true;
			layered = false;
			log.warn(Text.get("gb.body"), ex);
			return p.getModel();
		}
	}

	private Model draw(Player p)
	{
		PlayerComposition c = p.getPlayerComposition();
		int idle = p.getIdlePoseAnimation();
		int npc = c == null ? -1 : c.getTransformedNpcId();
		int key = c == null ? 0 : key(c.getEquipmentIds(), c.getColors(), c.getGender(), npc, idle);
		boolean mayTake = c != null && mayTake(p.getAnimation(), p.getPoseAnimation(), idle, npc);
		boolean useLayer = !layerFailed && frame >= 0 && animation != null && layerable(idle);
		layered = false;
		Model m = LayeredBody.drawable(source, PuppetController.MESH, snapshot, key, mayTake, useLayer ? layer : null,
			full ? pose : NEUTRAL, probe);
		readHand(m);
		return m;
	}

	/** Our animation on the canvas (the snapshot in the proven per-request buffer); null when not applied. */
	private Model applyLayer(Model canvas)
	{
		Animation a = animation;
		int f = frame;
		if (a == null || f < 0 || layerFailed)
			return null;
		try
		{
			Model r = client.applyTransformations(canvas, a, f, null, 0);
			layered = r == canvas;
			return r;
		}
		catch (RuntimeException ex)
		{
			if (a.isMayaAnim())
			{
				// only the skeletal kind failed: the classic animations (walk, run, the get-up) still play
				mayaFailed = true;
				animation = null;
				frame = -1;
				log.warn(Text.get("gb.maya"), ex);
				return null;
			}
			failLayer(ex);
			return null;
		}
	}

	private void failLayer(RuntimeException ex)
	{
		layerFailed = true;
		animation = null;
		frame = -1;
		log.warn(Text.get("gb.anim"), ex);
	}

	/** Reads (never writes) the drawn body's hand; a failure stops the reading (the board then hangs at its spot). */
	private void readHand(Model m)
	{
		if (m == null || !hand.isActive())
			return;
		try
		{
			hand.sample(m.getVerticesX(), m.getVerticesY(), m.getVerticesZ(), m.getVerticesCount());
		}
		catch (RuntimeException ex)
		{
			hand.setActive(false);
			log.debug("Could not read a party ghost's hand", ex);
		}
	}

	// ---- when a ghost's copy of the member's model (MeshSnapshot) is taken and still fits

	/** A key for the member's appearance; equal appearances give equal keys. */
	static int key(int[] equipment, int[] colours, int gender, int npcTransform, int idlePose)
	{
		int h = Arrays.hashCode(equipment);
		h = 31 * h + Arrays.hashCode(colours);
		h = 31 * h + gender;
		h = 31 * h + npcTransform;
		return 31 * h + idlePose;
	}

	/**
	 * The real character stands in its plain idle (no action animation, its idle pose playing, not an NPC), so the
	 * frame it is drawn in now is a standing body to copy.
	 */
	static boolean mayTake(int animation, int poseAnimation, int idlePose, int npcTransform)
	{
		return animation == -1 && poseAnimation == idlePose && npcTransform == -1;
	}

	/**
	 * An OSRS animation goes on top of a snapshot taken in this idle pose: only the game's own standing frame, which
	 * is near the model's base pose (a weapon's stance would add its own arm swing to every animation).
	 */
	static boolean layerable(int idlePose)
	{
		return idlePose == AnimationID.HUMAN_READY;
	}
}

package com.gielinorskate.party;

import java.util.Arrays;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * One party member's clock as seen from here, from the send times their updates carry
 * ({@link GhostTrajectory#timeMs}): the offset floor (the smallest arrival minus send time over a recent window:
 * the two clocks' difference plus the quickest delivery), the jitter (how much later than that floor updates
 * usually arrive), and how far apart their updates go. From these, the playback delay: how far behind the floor a
 * ghost is drawn so the next update has nearly always arrived before it is needed. Pure; nothing allocated per
 * update.
 */
@Accessors(fluent = true)
final class GhostClockSync
{
	/** Updates remembered for the floor, jitter and gaps. */
	static final int WINDOW = 48;
	/** The floor and jitter come from updates that arrived within this many seconds. */
	static final float WINDOW_SECONDS = 20f;
	static final float MIN_DELAY = 0.25f;
	static final float MAX_DELAY = 1.2f;
	/** Before enough updates: the snapshot interval and a typical jitter. */
	static final float DEFAULT_GAP = GhostSendPolicy.SNAPSHOT_INTERVAL;
	static final float DEFAULT_JITTER = 0.1f;
	/** Added on top of the gap and jitter: a frame or two of slack. */
	static final float MARGIN = 0.04f;

	private final double[] offset = new double[WINDOW];
	private final float[] arrived = new float[WINDOW];
	private int offsetCount;
	private int offsetNext;
	private final float[] gaps = new float[WINDOW];
	private int gapCount;
	private int gapNext;
	private final float[] scratch = new float[WINDOW];

	private boolean unwrapped;
	private int lastRaw;
	private double lastUnwrapped;
	private double newest = Double.NEGATIVE_INFINITY;

	/** Our clock minus theirs, plus the quickest recent delivery: an update sent at s arrives at s + floor or later. */
	@Getter
	private double floor;
	/** How much later than the floor updates usually arrive, seconds. */
	@Getter
	private float jitter = DEFAULT_JITTER;
	/** How far apart (sender seconds) updates usually go while the skater moves. */
	@Getter
	private float gap = DEFAULT_GAP;

	/** Some update's send time has been seen. */
	boolean has()
	{
		return offsetCount > 0;
	}

	/**
	 * The sender's time in seconds of a send time on the wire ({@code raw}, ms modulo 2^18), unwrapped against the
	 * one before (they are never more than half the modulus apart: a member silent that long has gone).
	 */
	double unwrap(int raw)
	{
		if (!unwrapped)
		{
			unwrapped = true;
			lastRaw = raw;
			lastUnwrapped = raw / 1000.0;
			return lastUnwrapped;
		}
		int mod = GhostTrajectory.TIME_MOD;
		int diff = Math.floorMod(raw - lastRaw + mod / 2, mod) - mod / 2;
		lastRaw = raw;
		lastUnwrapped += diff / 1000.0;
		return lastUnwrapped;
	}

	/**
	 * An update sent at {@code sent} (sender seconds) arrived at {@code now} (ours). Returns false, taking nothing
	 * in, when it is so far off the floor that the sender's clock must have started again: then {@link #clear} and
	 * start over.
	 */
	boolean observe(float now, double sent)
	{
		double o = now - sent;
		// An arrival this far (seconds) off the floor is the sender's clock starting again (a restart), not delay.
		if (offsetCount > 0 && Math.abs(o - floor) > 5f)
			return false;
		offset[offsetNext] = o;
		arrived[offsetNext] = now;
		offsetNext = (offsetNext + 1) % WINDOW;
		offsetCount = Math.min(WINDOW, offsetCount + 1);

		double min = o;
		for (int i = 0; i < offsetCount; i++)
		{
			if (now - arrived[i] <= WINDOW_SECONDS)
				min = Math.min(min, offset[i]);
		}
		floor = min;
		int n = 0;
		for (int i = 0; i < offsetCount; i++)
		{
			if (now - arrived[i] <= WINDOW_SECONDS)
				scratch[n++] = (float) (offset[i] - floor);
		}
		// jitter percentile
		jitter = n < 4 ? Math.max(DEFAULT_JITTER, percentile(scratch, n, 1f)) : percentile(scratch, n, 0.9f);

		if (sent > newest)
		{
			// Gaps between updates longer than this are a standing skater's keep-alives, not motion: not counted.
			if (newest > Double.NEGATIVE_INFINITY && sent - newest <= 1.25f)
			{
				gaps[gapNext] = (float) (sent - newest);
				gapNext = (gapNext + 1) % WINDOW;
				gapCount = Math.min(WINDOW, gapCount + 1);
			}
			newest = sent;
		}
		if (gapCount >= 3)
		{
			System.arraycopy(gaps, 0, scratch, 0, gapCount);
			// The share of gaps and late arrivals the delay covers.
			gap = percentile(scratch, gapCount, 0.9f);
		}
		return true;
	}

	/** The {@code p} quantile of the first {@code n} (at least one) values of {@code v} (sorted in place). */
	private static float percentile(float[] v, int n, float p)
	{
		Arrays.sort(v, 0, n);
		return v[Math.min(n - 1, Math.max(0, (int) Math.ceil(p * n) - 1))];
	}

	/**
	 * Seconds behind the floor to draw at: the next update is due within a gap and arrives within the jitter,
	 * plus a little; within {@link #MIN_DELAY} and {@link #MAX_DELAY}.
	 */
	float delay()
	{
		return GhostCodec.clamp(gap + jitter + MARGIN, MIN_DELAY, MAX_DELAY);
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.*;
import com.gielinorskate.progression.*;
import com.gielinorskate.render.KnockdownPose;
import com.gielinorskate.tricks.*;
import java.util.List;

/**
 * Local skater state to and from the compact ints of {@link SkateGhostUpdate}. Positions, heights and
 * velocities round to whole local units (1/128 tile), the heading to 1/1000 rad and flip time to 1 ms.
 * Pure: no client dependency.
 */
public final class GhostCodec
{
	static final int EV_POP = 1;
	static final int EV_LAND = 1 << 1;
	static final int EV_BAIL = 1 << 2;
	static final int EV_RESET = 1 << 3;
	static final int EV_GRIND_LOCK = 1 << 4;
	static final int EV_GRIND_EXIT = 1 << 5;
	/** A trick: a pop, flip, upgrade, or a grab, manual or grind starting. */
	static final int EV_TRICK = 1 << 6;
	/** A front / back flip started, stopped or reversed (BodyFlipMeter): sent at once, not with the snapshot. */
	static final int EV_BODY_FLIP = 1 << 7;
	/** Got on or off the board, or dropped or picked it up: sent at once. Older versions ignore the bit. */
	static final int EV_BOARD_SWAP = 1 << 8;
	/** On foot, started or stopped walking or running: sent at once so the ghost does not walk on past a stop. */
	static final int EV_GAIT = 1 << 9;
	/** Knocked off: the knockdown started lying down or getting up (sent at once). Older versions ignore the bit. */
	static final int EV_KNOCK = 1 << 10;
	/**
	 * A push: never sent at once (it rides along with the next update, its time in the timeline), so the ghost's
	 * push kick plays when the member pushed.
	 */
	static final int EV_PUSH = 1 << 11;
	// bits 12 and 13 are sent by other builds of the plugin: unknown here, so their events are ignored
	/** Events that do not make an update go out at once. */
	static final int PASSIVE_EVENTS = EV_PUSH;
	/** The pop charge goes in this many steps (1..CHARGE_STEPS); below half a step it is not sent. */
	static final int CHARGE_STEPS = 9;
	private static final KnockdownPose.Stage[] KNOCK_STAGES = KnockdownPose.Stage.values();
	/** Added to a lying angle's quarter-turn count k on the wire (kd), so it is never negative. */
	private static final int KNOCK_K_OFFSET = 4;
	/**
	 * A dropped board further than this from its walker (absolute units, about a loaded scene's width), across or
	 * up, is not believed: the ghost is drawn carrying it.
	 */
	static final float MAX_BOARD_DISTANCE = 104 * 128f;


	private GhostCodec()
	{
	}

	/**
	 * The update for {@code f} (seq left 0 for the sender to fill in). {@code tr} is the flip turning the board
	 * now; with none, a TRICK event's own trick goes there so the label can name it, unless that trick is a board
	 * flip (already finished by the time a rate-limited event goes out: it must not be animated again). Body flips
	 * have no board rotation of their own, so they go (their event comes on landing).
	 */
	static SkateGhostUpdate encode(GhostState f, int events, Trick eventTrick)
	{
		SkateGhostUpdate m = new SkateGhostUpdate();
		m.w = f.world;
		m.p = f.plane;
		m.x = Math.round(f.x);
		m.y = Math.round(f.y);
		m.h = Math.round(f.h);
		m.hd = Math.round(Angles.wrap(f.heading) * 1000f);
		m.tw = Math.round(f.turnRate * 1000f);
		m.bf = Math.round(f.bodyFlip * 1000f);
		m.bw = Math.round(f.bodyFlipRate * 1000f);
		m.vx = Math.round(f.vx);
		m.vy = Math.round(f.vy);
		m.vh = Math.round(f.vh);
		m.st = name(f.state);
		m.hold = name(f.hold);
		m.ev = events;
		if (f.trick != null)
		{
			m.tr = f.trick.name();
			m.ft = Math.round(clamp(f.flipTime, 0f, f.trick.duration) * 1000f);
		}
		else if ((events & EV_TRICK) != 0 && eventTrick != null
			&& (eventTrick.kind != TrickKind.FLIP || eventTrick.duration <= 0f))
			m.tr = eventTrick.name();
		if (f.offBoard != null)
		{
			m.ob = f.offBoard.name();
			if (f.offBoard == BoardState.DROPPED)
			{
				m.bx = Math.round(f.boardX);
				m.by = Math.round(f.boardY);
				m.bh = Math.round(f.boardH);
				m.bd = Math.round(Angles.wrap(f.boardHeading) * 1000f);
				if (f.knockStage != null)
					m.kd = knockWire(f.knockStage, f.knockLie);
			}
		}
		else if (f.state == SkaterState.ROLLING || f.state == SkaterState.MANUAL || f.state == SkaterState.GRINDING)
		{
			int c = Math.round(clamp(f.charge, 0f, 1f) * CHARGE_STEPS);
			m.cr = c > 0 ? c : null;
		}
		return m;
	}

	/** The pop charge (0..1) of a received {@code cr}: 0 when missing or junk. */
	static float charge(Integer cr)
	{
		return cr == null || cr <= 0 ? 0f : Math.min(1f, cr / (float) CHARGE_STEPS);
	}

	/**
	 * {@code kd} for a knockdown in {@code stage} lying at {@code lie}: the stage (1 tumbling, 2 lying, 3 getting up)
	 * plus 10 times the lying angle's odd quarter turn ((2k + 1) PI / 2, k clamped to -4..5) as k + 4.
	 */
	static int knockWire(KnockdownPose.Stage stage, float lie)
	{
		int k = Math.round((lie - Angles.PI / 2) / Angles.PI);
		k = Math.max(-KNOCK_K_OFFSET, Math.min(9 - KNOCK_K_OFFSET, k));
		return stage.ordinal() + 1 + 10 * (k + KNOCK_K_OFFSET);
	}

	/** The knockdown stage of a received {@code kd}, or null when missing or junk. */
	static KnockdownPose.Stage knockStage(Integer kd)
	{
		if (kd == null || kd < 0 || kd > 99)
			return null;
		int i = kd % 10 - 1;
		return i >= 0 && i < KNOCK_STAGES.length ? KNOCK_STAGES[i] : null;
	}

	/** The lying angle of a received {@code kd}. */
	static float knockLie(Integer kd)
	{
		int k = kd == null ? 0 : Math.max(0, Math.min(99, kd)) / 10 - KNOCK_K_OFFSET;
		return (2 * k + 1) * Angles.PI / 2;
	}

	/**
	 * Decodes {@code m}; unknown names (another plugin version) become ROLLING / null. Off the board an unknown
	 * board state means on the board (as from an older version); a walker is only ever standing or in the air, with
	 * no trick; a dropped board with no position, or implausibly far from its walker, is drawn carried.
	 */
	static GhostState decode(SkateGhostUpdate m)
	{
		SkaterState state = named(SkaterState.values(), m.st, SkaterState.ROLLING);
		float heading = Angles.wrap(m.hd / 1000f);
		BoardState offBoard = named(BoardState.values(), m.ob, null);
		if (offBoard == null)
			return new GhostState(m.w, m.p, m.x, m.y, m.h, heading, m.vx, m.vy, m.vh, state,
				named(Trick.values(), m.hold, null), m.ev, named(Trick.values(), m.tr, null), Math.max(0, m.ft) / 1000f,
				m.seq, turnRate(m.tw), m.bf / 1000f, m.bw / 1000f, null, 0f, 0f, 0f, 0f, charge(m.cr), null, 0f);
		boolean dropped = offBoard == BoardState.DROPPED && m.bx != null && m.by != null && m.bh != null
			&& Math.hypot(m.bx - (double) m.x, m.by - (double) m.y) <= MAX_BOARD_DISTANCE
			&& Math.abs(m.bh - (double) m.h) <= MAX_BOARD_DISTANCE;
		KnockdownPose.Stage knock = dropped ? knockStage(m.kd) : null;
		boolean airborne = state == SkaterState.AIRBORNE;
		// knocked off: flying (AIRBORNE) or down (BAILED), the receiver timing the tumble itself; else a walker
		return new GhostState(m.w, m.p, m.x, m.y, m.h, heading, m.vx, m.vy, knock == null ? m.vh : 0f,
			airborne ? state : knock != null ? SkaterState.BAILED : SkaterState.ROLLING, null, m.ev, null, 0f, m.seq,
			knock == null ? turnRate(m.tw) : 0f, 0f, 0f, dropped ? offBoard : BoardState.CARRIED, dropped ? m.bx : 0f,
			dropped ? m.by : 0f, dropped ? m.bh : 0f, dropped && m.bd != null ? Angles.wrap(m.bd / 1000f) : 0f, 0f,
			knock, knock == null ? 0f : knockLie(m.kd));
	}

	/**
	 * A received turn rate (rad/s * 1000) in rad/s, bounded to what a real turn can be
	 * ({@link TurnRateMeter#MAX_RATE}). Missing from older versions' messages, it is 0: the ghost moves straight.
	 */
	static float turnRate(int tw)
	{
		return clamp(tw / 1000f, -TurnRateMeter.MAX_RATE, TurnRateMeter.MAX_RATE);
	}

	/** The EV_* bits of an on-foot frame: a jump goes as a pop, a landing as a landing (a fall is not sent). */
	static int footEventBits(List<FootEvent> events)
	{
		int bits = 0;
		for (FootEvent e : events)
			bits |= e == FootEvent.JUMP ? EV_POP : e == FootEvent.LAND ? EV_LAND : 0;
		return bits;
	}

	/** {@link #EV_BOARD_SWAP} when the board's state (null on the board) changed since the last frame, else 0. */
	static int swapBits(BoardState before, BoardState after)
	{
		return before == after ? 0 : EV_BOARD_SWAP;
	}

	/**
	 * Longest grip-and-wheels field a receiver reads; anything longer is junk. Room for two 10-character names and the
	 * dot, so every name another version may send still fits (an unknown one draws the part's default).
	 */
	static final int MAX_LOOK_WIRE = 21;

	/** The deck design as sent (dk): its wire name, or null (left out of the JSON) for the default deck. */
	static String deckWire(BoardLook look)
	{
		if (look == null)
			return null;
		String w = look.deck.wireName();
		return w.equals(BoardDesigns.bundled().defaultFor(DesignPart.DECK).wireName()) ? null : w;
	}

	/** The grip and wheels designs as sent (gw): "GRIP.WHEELS", each a wire name. */
	static String lookWire(BoardLook look)
	{
		return look.grip.wireName() + "." + look.wheels.wireName();
	}

	/**
	 * True if {@code m} may carry the grip and wheels: it names no trick (tr), places no dropped board (bx...) and
	 * has no pop charge (cr: a crouch is short, the designs wait for the next update), so even the busiest such
	 * update stays within the size of the busiest update without them.
	 */
	static boolean mayCarryLook(SkateGhostUpdate m)
	{
		return m.tr == null && m.bx == null && m.cr == null;
	}

	/**
	 * A party member's designs from an update: the deck from {@code dk} (every update), the grip and wheels from
	 * {@code gw} when it is there, else as before ({@code previous}; the defaults when null). Unknown or junk
	 * names are each part's default.
	 */
	static BoardLook decodeLook(String dk, String gw, BoardLook previous, BoardDesigns designs)
	{
		BoardLook before = previous != null ? previous : BoardLook.defaults(designs);
		BoardLook out = before.with(designs.fromWire(DesignPart.DECK, dk));
		if (gw == null)
			return out;
		if (gw.length() > MAX_LOOK_WIRE)
			return out.with(designs.defaultFor(DesignPart.GRIP)).with(designs.defaultFor(DesignPart.WHEELS));
		int dot = gw.indexOf('.');
		String grip = dot < 0 ? gw : gw.substring(0, dot);
		String wheels = dot < 0 ? null : gw.substring(dot + 1);
		return out.with(designs.fromWire(DesignPart.GRIP, grip.isEmpty() ? null : grip))
			.with(designs.fromWire(DesignPart.WHEELS, wheels == null || wheels.isEmpty() ? null : wheels));
	}

	/** The value named {@code name} (an enum name on the wire), or {@code fallback} when none or unknown. */
	private static <E extends Enum<E>> E named(E[] values, String name, E fallback)
	{
		for (E e : values)
		{
			if (e.name().equals(name))
				return e;
		}
		return fallback;
	}

	private static String name(Enum<?> e)
	{
		return e == null ? null : e.name();
	}

	/**
	 * The heading turn {@code t}'s own body turn has made at {@code progress} (a bigspin's 180 eased like the
	 * board, as SkatePhysics applies it); 0 for no trick.
	 */
	static float bodySpin(Trick t, float progress)
	{
		return t == null || t.bodyYawTurns == 0f ? 0f
			: t.bodyYawTurns * Angles.TWO_PI * SkatePhysics.flipEase(progress);
	}

	/** Horizontal velocity {vx, vy} of a skater moving at |speed| along {@code travelHeading}. */
	static float[] velocity(float speed, float travelHeading)
	{
		float s = Math.abs(speed);
		return new float[]{(float) Math.sin(travelHeading) * s, (float) Math.cos(travelHeading) * s};
	}

	/** The EV_* bits of one frame: its physics and trick events, plus locking onto or leaving a rail. */
	static int eventBits(List<SkateEvent> events, List<TrickEvent> trickEvents, SkaterState before,
		SkaterState after)
	{
		int bits = 0;
		for (SkateEvent e : events)
			bits |= e == SkateEvent.POP ? EV_POP : e == SkateEvent.LAND ? EV_LAND : e == SkateEvent.BAIL ? EV_BAIL
				: e == SkateEvent.RESET ? EV_RESET : e == SkateEvent.PUSH ? EV_PUSH : 0;
		if (eventTrick(trickEvents) != null)
			bits |= EV_TRICK;
		if (after == SkaterState.GRINDING && before != SkaterState.GRINDING)
			bits |= EV_GRIND_LOCK;
		else if (before == SkaterState.GRINDING && after != SkaterState.GRINDING)
			bits |= EV_GRIND_EXIT;
		return bits;
	}

	/** The latest TRICK or HOLD_START event's trick, or null. */
	static Trick eventTrick(List<TrickEvent> trickEvents)
	{
		Trick latest = null;
		for (TrickEvent e : trickEvents)
		{
			if ((e.type == TrickEvent.Type.TRICK || e.type == TrickEvent.Type.HOLD_START) && e.trick != null)
				latest = e.trick;
		}
		return latest;
	}

	/** Local coordinate of an absolute one, in a scene whose base tile is {@code base}. */
	static float toLocal(float absolute, int base)
	{
		return absolute - base * 128f;
	}

	static float clamp(float v, float lo, float hi)
	{
		return Math.max(lo, Math.min(hi, v));
	}
}

package com.gielinorskate.party;

import java.util.function.Consumer;

/**
 * Keeps party ghosts from ever ending local skating: the first exception out of a ghost frame is reported once,
 * the ghosts are cleaned up, and ghosts stay off until {@link #reset} at the start of the next skate session.
 * Not thread safe; client thread only.
 */
public final class GhostFailureGuard
{
	boolean disabled;

	/**
	 * Runs {@code frame} unless ghosts are disabled for this session. Never throws a RuntimeException.
	 *
	 * @param cleanup despawns every ghost; runs once, on the first failure
	 * @param report receives the first failure (to log it); runs once
	 */
	public void run(Runnable frame, Runnable cleanup, Consumer<RuntimeException> report)
	{
		if (disabled)
			return;
		try
		{
			frame.run();
		}
		catch (RuntimeException e)
		{
			disabled = true;
			report.accept(e);
			try
			{
				cleanup.run();
			}
			catch (RuntimeException ignored)
			{
				// already reported the cause; ghosts are off for the rest of the session either way
			}
		}
	}

	/** A new skate session: ghosts may run again. */
	public void reset()
	{
		disabled = false;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.progression.*;
import com.gielinorskate.tricks.Trick;
import java.util.*;
import net.runelite.client.party.messages.PartyMessage;

/**
 * The party-ghost logic without the client: decides what of the local skater goes to the party (through
 * {@link GhostSendPolicy}) and keeps one {@link GhostPredictor} per party member who is skating. The send side
 * may be called from the plugin's shutdown thread as well as the client thread, so every method is
 * synchronized (they are all short and uncontended). Times are seconds on one monotonic clock.
 */
final class GhostHub
{
	/** The party: in production RuneLite's PartyService, in tests a fake. */
	interface Link
	{
		boolean inParty();

		void send(PartyMessage message);
	}

	private final Link link;
	private final GhostSendPolicy policy;
	private final Map<Long, GhostPredictor> ghosts = new HashMap<>();
	private final Map<Long, GhostPredictor> ghostsView = Collections.unmodifiableMap(ghosts);

	/** The last update sent since sharing (re)started, or null. */
	private SkateGhostUpdate lastSent;
	/** Something was sent since the last stop: party members are showing a ghost of us. */
	private boolean live;
	private int pendingEvents;
	private Trick pendingTrick;
	/** The skater's recent positions and event times, for the timeline each update carries. */
	private final GhostTrail trail = new GhostTrail();
	private boolean closed;
	/** Seconds between updates carrying the grip and wheels (SkateGhostUpdate.gw) while they don't change. */
	static final float LOOK_REFRESH_SECONDS = 5f;

	private final BoardDesigns designs = BoardDesigns.bundled();
	/** The local board's designs: the deck goes in every update, the grip and wheels now and then. */
	private BoardLook localLook = BoardLook.defaults(designs);
	/** The grip and wheels changed (or sharing restarted) since they last went out. */
	private boolean lookPending = true;
	private float lookSentAt = Float.NEGATIVE_INFINITY;

	GhostHub(Link link, int seqSeed)
	{
		this.link = link;
		this.policy = new GhostSendPolicy(seqSeed);
	}

	/**
	 * A sequence start for a plugin run starting at {@code epochMillis}: 4 per second of wall time since 2023, so
	 * a restarted sender (which sends at most 2 a second) starts above every number it used before and its
	 * party members do not drop its updates as stale.
	 */
	static int seqSeed(long epochMillis)
	{
		// 2023-11-14 in epoch seconds: seeds count from here.
		long seconds = Math.max(0L, epochMillis / 1000L - 1_700_000_000L);
		// Seed growth per second of wall time. At least {@link GhostSendPolicy#MAX_PER_SECOND} (2); kept at the old
		// limit of 4 so a run after this change still starts above every number an earlier, faster run used.
		return (int) Math.min(Integer.MAX_VALUE / 2, seconds * 4);
	}

	/**
	 * One local skate frame. Full updates go out only while at least one other party member is skating (has a
	 * live ghost here, from their recent messages); otherwise only an announce every 5 s so they can find us.
	 *
	 * @param events GhostCodec.EV_* bits of this frame
	 * @param eventTrick the trick of this frame's TRICK event, or null
	 * @param inPvpArea the real character or the skater is in a PvP area (or anywhere else not to share)
	 * @param sharing the "Share my skater with my party" setting
	 */
	synchronized void onLocalFrame(GhostState frame, int events, Trick eventTrick, boolean inPvpArea,
		boolean sharing, float now)
	{
		if (closed)
			return;
		boolean inParty = link.inParty();
		if (inPvpArea || !sharing || !inParty)
		{
			stopSharing();
			if (live && !inParty)
				// left the party: nobody to tell (they see us part)
				live = false;
			else if (live && policy.hasToken(now))
				sendStop(now);
			return;
		}
		pendingEvents |= events;
		trail.record(frame, now);
		trail.noteEvents(events, now);
		if (eventTrick != null)
			pendingTrick = eventTrick;
		if (ghosts.isEmpty())
		{
			// nobody else is skating, so nobody draws our events: only the occasional "I'm skating" announce
			pendingEvents = 0;
			pendingTrick = null;
			if (!policy.shouldAnnounce(now))
				return;
		}
		SkateGhostUpdate update = GhostCodec.encode(frame, pendingEvents, pendingTrick);
		update.dk = GhostCodec.deckWire(localLook);
		if ((lookPending || now - lookSentAt >= LOOK_REFRESH_SECONDS) && GhostCodec.mayCarryLook(update))
			update.gw = GhostCodec.lookWire(localLook);
		// new designs are a change worth sending; their refresh alone is not
		boolean changed = !update.sameState(lastSent) || update.gw != null && lookPending;
		if (!ghosts.isEmpty() && !policy.shouldSend(now, changed, (pendingEvents & ~GhostCodec.PASSIVE_EVENTS) != 0))
			return;
		update.seq = policy.nextSeq();
		// the timeline in whatever room the update leaves under the size bound
		trail.fit(update, now);
		link.send(update);
		policy.recordSend(now);
		lastSent = update;
		trail.sent(now);
		if (update.gw != null)
		{
			lookPending = false;
			lookSentAt = now;
		}
		live = true;
		pendingEvents = 0;
		pendingTrick = null;
	}

	/**
	 * Skate mode ended at {@code now}: tell the party once. Not held back by the rate limit (it happens at most once
	 * per session, and an announce only goes out with a token left for its stop), but counted in it, so toggling
	 * skating quickly cannot go over it. {@code now} is NaN at plugin shutdown (not counted: nothing follows).
	 */
	synchronized void onLocalSkateEnd(float now)
	{
		if (live && link.inParty())
			sendStop(now);
		live = false;
		stopSharing();
	}

	private void stopSharing()
	{
		trail.clear();
		lastSent = null;
		pendingEvents = 0;
		pendingTrick = null;
		lookPending = true;
		policy.reset();
	}

	/** Plugin shutdown: the stop goes out now, then nothing more is sent until {@link #open}. */
	synchronized void close()
	{
		onLocalSkateEnd(Float.NaN);
		closed = true;
	}

	synchronized void open()
	{
		closed = false;
		policy.reset();
	}

	private void sendStop(float now)
	{
		link.send(new SkateGhostStop());
		if (!Float.isNaN(now))
			policy.recordSend(now);
		live = false;
	}

	/** The local board's designs, sent so party members draw them. */
	synchronized void setLocalLook(BoardLook look)
	{
		if (look != null && !look.equals(localLook))
		{
			localLook = look;
			lookPending = true;
		}
	}

	/** An update from another party member. */
	synchronized void onRemoteUpdate(long memberId, SkateGhostUpdate m, float now, GhostPredictor.Ground ground)
	{
		GhostPredictor predictor = ghosts.computeIfAbsent(memberId, id -> new GhostPredictor());
		if (predictor.accept(GhostCodec.decode(m), GhostTrajectory.decode(m.tj, m.ev, m.x, m.y, m.h, m.hd), now,
			ground))
		{
			predictor.deckWire = m.dk;
			if (m.gw != null)
				predictor.lookWire = m.gw;
			predictor.relook(designs);
		}
	}

	/** The member stopped skating or left the party. */
	synchronized void onMemberLeft(long memberId)
	{
		ghosts.remove(memberId);
	}

	/** Party left or changed, world hop, shutdown. */
	synchronized void clearGhosts()
	{
		ghosts.clear();
	}

	/** Drops ghosts that have been silent too long. */
	synchronized void prune(float now)
	{
		ghosts.values().removeIf(g -> g.expired(now));
	}

	/** Read-only view of the ghosts by member ID; client thread only. */
	Map<Long, GhostPredictor> ghosts()
	{
		return ghostsView;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.render.KnockdownPose;

/**
 * A knocked-off ghost's tumble, timed on this side from when each stage was first seen (updates carry only the
 * stage and the lying angle): a spin from upright onto the lying angle, lying there, then the body easing round to
 * the nearest whole turn (upright) through the get-up, as the sender's knockdown draws it. Pure.
 */
final class GhostKnockdown
{
	/** The sender's lie-down and get-up (session.Knockdown), seconds. */
	static final float LIE_SECONDS = 0.5f;
	static final float GET_UP_SECONDS = 0.4f;
	/** The tumble reaches its lying angle this long after being thrown off (a typical flight, MIN_SPIN_TIME up). */
	static final float SPIN_SECONDS = 0.35f;

	private GhostKnockdown()
	{
	}

	/** 0..1 through the lie-down or get-up {@code age} seconds into it; 0 tumbling. */
	static float progress(KnockdownPose.Stage stage, float age)
	{
		return stage == KnockdownPose.Stage.AIR ? 0f
			: GhostCodec.clamp(age / (stage == KnockdownPose.Stage.LIE ? LIE_SECONDS : GET_UP_SECONDS), 0f, 1f);
	}

	/** The body's tumble angle {@code age} seconds into {@code stage}, lying at {@code lie}. */
	static float angle(KnockdownPose.Stage stage, float lie, float age)
	{
		switch (stage)
		{
			case AIR:
				return lie * GhostCodec.clamp(age / SPIN_SECONDS, 0f, 1f);
			case LIE:
				return lie;
			default:
				float u = progress(stage, age);
				float s = u * u * (3f - 2f * u);
				float upright = Math.round(lie / Angles.TWO_PI) * Angles.TWO_PI;
				return lie + (upright - lie) * s;
		}
	}
}

