}

package com.gielinorskate.party;

import com.gielinorskate.physics.*;
import com.gielinorskate.progression.*;
import com.gielinorskate.render.KnockdownPose;
import com.gielinorskate.render.RenderPose;
import com.gielinorskate.tricks.Trick;
import lombok.Getter;
import lombok.experimental.Accessors;

/**
 * One party member's ghost: its updates played back on the member's own clock ({@link GhostTimeline}), the events
 * they carry counted as the playback reaches them, and the latest update with its arrival (for expiry and stale
 * updates). Positions are absolute (world tile * 128 + sub-tile); the returned {@link RenderPose} uses them as its
 * x and y. Pure: no client dependency.
 */
@Accessors(fluent = true)
final class GhostPredictor extends GhostTimeline
{
	/** A change of what is drawn larger than 3 tiles is a teleport (or a lost update): snap instead of sliding. */
	static final float SNAP_DISTANCE = 3 * 128f;
	/** The skater's gravity (skate-tuning.json "gravity", u/s^2). */
	static final float GRAVITY = 2000f;

	/** Height (up-positive) of the receiver's ground at an absolute (x, y), or NaN when unknown. */
	interface Ground
	{
		float heightAt(float x, float y);
	}

	/** The latest authoritative state, or null before the first. */
	@Getter
	private GhostState latest;
	private float latestTime;
	/** The trick (or grab, manual, grind) of the latest TRICK event, or null; see {@link #labelAge}. */
	@Getter
	private Trick labelTrick;
	private float labelTime;
	private float popTime = Float.NaN;
	/** The latest pop was off the nose. */
	@Getter
	private boolean popNollie;
	/** The member's board designs (from their updates; each part's default when unknown). */
	@Getter
	private BoardLook look = BoardLook.defaults(BoardDesigns.bundled());
	/** Pops, landings, bails and pushes played so far, so a renderer can tell new ones each frame. */
	@Getter
	private int popCount;
	@Getter
	private int landCount;
	@Getter
	private int bailCount;
	@Getter
	private int pushCount;
	/** When the current knockdown stage was first seen. */
	private float knockSince;
	/** The knockdown stage of the update last played. */
	private KnockdownPose.Stage playedKnock;
	/** The latest deck and grip-and-wheels fields (dk, gw), so the look can be worked out again. */
	String deckWire;
	String lookWire;

	/**
	 * Takes in a new authoritative state received at {@code now}, with its timeline {@code tj} (null when it did not
	 * fit: placed by its arrival). Returns false when it is stale (not newer than the last one accepted; with a
	 * timeline, its positions still fill in the timeline: they say where the member was), or when it has no timeline
	 * and none came before (nothing to place it on yet).
	 */
	boolean accept(GhostState s, GhostTrajectory tj, float now, Ground ground)
	{
		// An update with an old sequence number is stale, unless the member has been silent this long: then the
		// sender has restarted and counts again from a lower number.
		boolean newer = latest == null || s.seq > latest.seq || now - latestTime >= 2f;
		if (tj == null && !newer || !receive(s, tj, now, ground))
			return false;
		if (newer)
		{
			latest = s;
			latestTime = now;
		}
		return newer;
	}

	@Override
	void event(int bits, Trick trick, boolean nollie, float at)
	{
		if ((bits & GhostCodec.EV_TRICK) != 0 && trick != null)
		{
			labelTrick = trick;
			labelTime = at;
		}
		if ((bits & GhostCodec.EV_POP) != 0)
		{
			popTime = at;
			popNollie = nollie;
			popCount++;
		}
		landCount += (bits & GhostCodec.EV_LAND) != 0 ? 1 : 0;
		bailCount += (bits & GhostCodec.EV_BAIL) != 0 ? 1 : 0;
		pushCount += (bits & GhostCodec.EV_PUSH) != 0 ? 1 : 0;
	}

	@Override
	void keyChanged(GhostState key, float at)
	{
		if (key.knockStage != null && key.knockStage != playedKnock)
			knockSince = at;
		playedKnock = key.knockStage;
	}

	/** The front / back flip angle of the whole skater at {@code now}, radians, + = frontflip; raw (whole turns kept). */
	float bodyFlip(float now)
	{
		advance(now, lastGround);
		return bodyFlip();
	}

	/** The heading turn rate (rad/s) at {@code now}, 0 when bailed. A flip's own body turn is not included. */
	float turnRate(float now)
	{
		advance(now, lastGround);
		// the curve's own turn rate: smooth through the samples, so the carve lean is too
		return state() == SkaterState.BAILED ? 0f : oturn;
	}

	/** The look worked out again from the latest deck and grip-and-wheels fields. */
	void relook(BoardDesigns designs)
	{
		look = GhostCodec.decodeLook(deckWire, lookWire, look, designs);
	}

	/** The state being drawn: the update the playback has reached (its board, knockdown, hold...), else the latest. */
	GhostState current()
	{
		GhostState c = playing();
		return c != null ? c : latest;
	}

	/** No message for {@link #EXPIRY} seconds. */
	boolean expired(float now)
	{
		// No message for this long: the member is gone (keep-alives come every 10 s).
		return latest == null || now - latestTime > 15f;
	}

	/**
	 * The ghost's pose at {@code now} ({@code ground} may be null: no ground clamp or following). Position, height
	 * and heading from the timeline's curves; the board flip from when it started on the member's clock (so it starts
	 * at the pop on the path), the hold and pitch from the update being played.
	 */
	RenderPose pose(float now, Ground ground)
	{
		advance(now, ground);
		GhostState key = playing();
		SkaterState state = state();
		Trick hold = key == null ? null : key.hold;
		float roll = 0f;
		float yaw = 0f;
		float pitch = SkatePhysics.boardPitchFor(state, hold);
		Trick t = flipTrick();
		if (t != null)
		{
			float u = flipTime() / t.duration;
			float e = SkatePhysics.flipEase(u);
			roll = t.rollTurns * Angles.TWO_PI * e;
			pitch += t.pitchTurns * Angles.TWO_PI * e;
			// relative to the body, whose bigspin turn is in the played-back heading already
			yaw = t.yawTurns * Angles.TWO_PI * e - GhostCodec.bodySpin(t, u);
		}
		return new RenderPose(ox, oy, oh, ohd, ohd, roll, yaw, pitch, state, hold);
	}

	/** Seconds since {@link #labelTrick} was set. */
	float labelAge(float now)
	{
		return now - labelTime;
	}

	/** Seconds since the latest pop, or Float.MAX_VALUE when none was seen. */
	float sincePop(float now)
	{
		return Float.isNaN(popTime) ? Float.MAX_VALUE : now - popTime;
	}

	/** The pop charge (0..1) of the update drawn; 0 when none. */
	float charge()
	{
		GhostState s = current();
		return s == null ? 0f : s.charge;
	}

	/** Seconds since the current knockdown stage was first seen. */
	float knockStageAge(float now)
	{
		return Math.max(0f, now - knockSince);
	}

	/** Ground speed as played back, u/s (the curve's own; unsigned: the wire has no fakie). */
	float speed()
	{
		return (float) Math.hypot(ovx, ovy);
	}

	/** Vertical speed (up > 0) at {@code now}, as played back. */
	float verticalSpeed(float now)
	{
		advance(now, lastGround);
		return ovh;
	}

	/** A board flip (roll, shove-it or impossible) is still turning at {@code now}. */
	boolean flipping(float now)
	{
		advance(now, lastGround);
		return flipTrick() != null;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.*;
import com.gielinorskate.progression.BoardLook;
import com.gielinorskate.render.*;
import com.gielinorskate.tricks.Trick;
import java.util.*;
import java.util.function.LongFunction;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;

/**
 * Draws party ghosts: per visible ghost its own board (mesh included) and, when the member's real character is in the scene, a body
 * drawn from our own copy of that character's model (else a board-only ghost), animated as the local skater is
 * (GhostBodyController: the riding stance, walk and run, the knockdown, with the procedural pose on top) without
 * touching the character itself. Placement mirrors the local skater's renderer. The board
 * is the RuneSkate (baked) board at Normal detail in the member's designs, one object per part like the local
 * board; when it can't be built no ghost is drawn this session.
 * Client thread only.
 */
final class GhostRenderer
{
	/** A board further than this from where it was drawn (a call-back) appears instead of flying there. */
	static final float BOARD_MOVE_REACH = 2 * 128f;

	/** One drawn ghost, and what it is drawn from this frame. */
	private final class Ghost
	{
		/** The ghost's body pose: the body is deformed by it and the board reads its front / back flip, when drawn. */
		final BodyPose pose = new BodyPose();
		final GhostRig rig = new GhostRig();
		/** One object per board part, all placed and posed the same. */
		BoardController[] boards;
		/** The ghost's own board mesh (never shared: posing rewrites it), and its designs. */
		BakedBoardModel baked;
		BoardLook look;
		final GhostBodyController body = new GhostBodyController(client, pose);
		boolean bodyRegistered;
		final RidingBoard riding = new RidingBoard();
		float nextLookup;
		/** The board object is registered (it is not while it lies outside this scene). */
		boolean boardRegistered;
		/** This frame's placements, the ones drawn last frame, and the get-on / get-off blend between. */
		final Placement bodyT = new Placement();
		final Placement boardT = new Placement();
		final Placement drawnBody = new Placement();
		final Placement drawnBoard = new Placement();
		final SwapBlend swap = new SwapBlend();
		float swapTime;
		boolean drawnOnce;
		/** The board's state last drawn: null on the board. */
		BoardState lastOff;
		/** This frame's board flip pivot and whether the board turns with a flip (for a blended re-pose). */
		float pivotY;
		boolean flipAllowed;
		int feetZ;
		/** The last frame was a knockdown (its board eases between updates). */
		boolean knocked;
		/** Scratch: a sent board's local position. */
		final float[] boardAt = new float[2];
		/** This frame's distance from the camera's focus, for the detail budget. */
		float distance;

		// this frame: the member's ghost, its pose, local position, the update drawn and the scene
		GhostPredictor predictor;
		RenderPose p;
		int x;
		int y;
		GhostState latest;
		float now;
		float dt;
		WorldView wv;

		/** Builds the board in {@code look}'s designs; false when it can't be built. */
		boolean build(BoardLook look)
		{
			this.look = look;
			baked = BakedBoardModel.create(client, false, look);
			if (baked == null)
				return false;
			// at most one object per baked part
			boards = new BoardController[Math.max(1, Math.min(4, baked.partCount()))];
			for (int i = 0; i < boards.length; i++)
			{
				boards[i] = new BoardController(i);
				boards[i].setBoard(baked, pose);
			}
			return true;
		}

		/** Every part of the board in the same pose. */
		void poseBoard(float roll, float pitch, float pivot, boolean flip)
		{
			for (BoardController b : boards)
				b.setPose(roll, pitch, pivot, flip);
		}

		/** Off the board: the trick pose is rebuilt from scratch back on it, and the board is posed with no flip. */
		void offBoard(float roll, float pitch)
		{
			riding.offBoard();
			pose.boardLift = 0f;
			pivotY = BoardPlacement.boardFlipPivotY(0);
			flipAllowed = false;
			poseBoard(roll, pitch, pivotY, false);
		}

		/**
		 * Positions board and body, on the board or on foot, easing over 0.25 s when the member gets on or off, or
		 * drops or picks up the board nearby; returns the feet's z (RuneLite, down-negative).
		 */
		int place()
		{
			BoardState off = latest.offBoard;
			boolean boardVisible = true;
			boolean knock = latest.knockStage != null;
			if (knock)
				boardVisible = placeKnockdown();
			else if (off == null)
				placeOnBoard();
			else
				boardVisible = placeOnFoot();
			knocked = knock;
			// getting on or off eases from what was drawn; so does a board dropped or picked up within reach (a
			// knockdown starts where the bail is, as the local skater's does: no blend into it)
			if (knock)
				swap.cancel();
			else if (drawnOnce && (off == null) != (lastOff == null))
			{
				swap.begin(drawnBody, boardRegistered ? drawnBoard : null, off == null);
				swapTime = 0f;
			}
			else if (drawnOnce && off != lastOff && boardRegistered && boardVisible
				&& Math.hypot(boardT.x - drawnBoard.x, boardT.y - drawnBoard.y) <= BOARD_MOVE_REACH)
			{
				swap.begin(null, drawnBoard, false);
				swapTime = 0f;
			}
			lastOff = off;
			if (swap.isActive())
			{
				swapTime += dt;
				// Getting on or off, or a board dropped or picked up, eases over this long
				// (BoardSwap.TRANSITION_SECONDS).
				swap.apply(swapTime / 0.25f, bodyT, boardT);
				// the board turns between hand and wheels with the rest of the blend
				poseBoard(boardT.roll, boardT.pitch, pivotY, flipAllowed);
			}
			showBoard(boardVisible);
			// every part of the board in exactly the same place
			for (BoardController b : boards)
				put(b, boardT);
			put(body, bodyT);
			drawnBody.copyFrom(bodyT);
			drawnBoard.copyFrom(boardT);
			drawnOnce = true;
			return feetZ;
		}

		private void put(RuneLiteObjectController o, Placement at)
		{
			o.setWorldView(wv.getId());
			o.setLevel(wv.getPlane());
			o.setX(Math.round(at.x));
			o.setY(Math.round(at.y));
			o.setZ(Math.round(at.z));
			o.setOrientation(at.orientation());
		}

		/** Standing upright at the feet, facing {@code heading}, the hand reading the board while {@code carrying}. */
		private void stand(float heading, boolean carrying)
		{
			feetZ = -Math.round(p.h);
			bodyT.set(x, y, feetZ, Angles.toJau(heading), 0f, 0f);
			body.hand.setActive(carrying);
		}

		/** The sent board position in this scene's local units into {@link #boardAt}; whether it lies in the scene. */
		private boolean boardHere()
		{
			boardAt[0] = GhostCodec.toLocal(latest.boardX, wv.getBaseX());
			boardAt[1] = GhostCodec.toLocal(latest.boardY, wv.getBaseY());
			return GhostVisibility.inScene(boardAt[0], boardAt[1], wv.getSizeX(), wv.getSizeY());
		}

		/**
		 * On foot: upright, facing the way it walks (walking or running on our copy of the member's model, see
		 * {@link #animate}), with a jump tuck; the board in the right hand as the walk swings it (read off the drawn
		 * body), or lying where it was dropped (false when that is outside this scene: the board is not drawn).
		 */
		boolean placeOnFoot()
		{
			rig.updateOnFoot(predictor, p, now, dt, pose);
			boolean dropped = latest.offBoard == BoardState.DROPPED;
			stand(p.heading, !dropped);
			boolean visible = true;
			if (dropped)
			{
				visible = boardHere();
				boardT.set(Math.round(boardAt[0]), Math.round(boardAt[1]), -Math.round(latest.boardH),
					Angles.toJau(latest.boardHeading), 0f, 0f);
			}
			else
			{
				// in the hand as the walk or run swings it (the fixed spot until the hand is read)
				HandAnchor hand = body.hand;
				hand.step(dt);
				CarryPose.placeAt(x, y, p.h, p.heading, predictor.speed(), hand.x(), hand.y(), hand.z(), boardT);
			}
			offBoard(boardT.roll, boardT.pitch);
			return visible;
		}

		/**
		 * Knocked off: the body tumbling onto its lying angle, lying, and getting up (the OSRS lie-down and get-up when
		 * our animation shows, else the procedural fall), its lowest point on the ground, facing along the tumble; the
		 * board where it was sent, eased between updates (false when that is outside this scene).
		 */
		boolean placeKnockdown()
		{
			KnockdownPose.Stage stage = latest.knockStage;
			float age = predictor.knockStageAge(now);
			KnockdownPose k = new KnockdownPose(stage, GhostKnockdown.progress(stage, age), p.x, p.y, p.h, p.heading,
				GhostKnockdown.angle(stage, latest.knockLie, age), 0f, latest.boardX, latest.boardY, latest.boardH,
				latest.boardHeading, 0f, 0f);
			rig.knockdown(k, stage != KnockdownPose.Stage.AIR && body.layered, pose);
			stand(p.heading + Angles.PI / 2, false);
			bodyT.z = -Math.round(p.h + TumbleBody.groundOffset(pose.flip));
			boolean visible = boardHere();
			float bx = boardAt[0];
			float by = boardAt[1];
			float bz = -latest.boardH;
			if (knocked && drawnOnce && Math.hypot(bx - drawnBoard.x, by - drawnBoard.y) <= BOARD_MOVE_REACH)
			{
				// Seconds (time constant): a knocked-off ghost's board eases toward each new place instead of
				// jumping there.
				float f = 1f - (float) Math.exp(-dt / 0.08f);
				bx = drawnBoard.x + (bx - drawnBoard.x) * f;
				by = drawnBoard.y + (by - drawnBoard.y) * f;
				bz = drawnBoard.z + (bz - drawnBoard.z) * f;
			}
			boardT.set(Math.round(bx), Math.round(by), Math.round(bz), Angles.toJau(latest.boardHeading), 0f, 0f);
			offBoard(0f, 0f);
			return visible;
		}

		/**
		 * The body's OSRS animation this frame: the riding stance on the board, walk or run on foot (at the walker's
		 * pace), lying and getting up when knocked down.
		 */
		void animate()
		{
			KnockdownPose.Stage knock = latest.knockStage;
			boolean onFoot = latest.offBoard != null;
			FootBody.Gait gait = rig.gait();
			GhostAnim a = GhostAnim.pick(onFoot, gait, knock);
			float rate = a == GhostAnim.WALK || a == GhostAnim.RUN ? GaitPlayback.rate(gait, predictor.speed()) : 1f;
			float progress = knock == null ? 0f : GhostKnockdown.progress(knock, predictor.knockStageAge(now));
			body.animate(a, rate, progress, dt);
		}

		/** Shows or hides the board (hidden when it lies outside this scene). */
		void showBoard(boolean show)
		{
			if (show != boardRegistered)
			{
				boardRegistered = show;
				register(show, boards);
			}
		}

		void showBody(boolean show)
		{
			if (show != bodyRegistered)
			{
				bodyRegistered = show;
				register(show, body);
			}
		}

		/** On the board, placed as the local skater is. */
		void placeOnBoard()
		{
			// the body's lean, crouch, push, landing squash, bail fall and front / back flip; the board turns with the
			// skater's flip about the centre of mass (both read the pose when drawn)
			rig.update(predictor, p, now, dt, pose);
			body.hand.setActive(false);
			// manual and grind pitch ease in and out; an impossible's end-over-end pitch is drawn as predicted; a
			// rolling grab (a grab hold while ROLLING) keeps the board flat on the ground
			float holdPitchFor = SkatePhysics.boardPitchFor(p.state, p.hold);
			feetZ = riding.update(p, x, y, p.boardRoll, 0f, PoseSmoothing.popPitch(predictor.sincePop(now),
				predictor.popNollie()), holdPitchFor, p.boardPitch - holdPitchFor,
				p.state == SkaterState.ROLLING ? null : p.hold, 0f, pose, dt, boardT, bodyT);
			pivotY = BoardPlacement.boardFlipPivotY(riding.deckLift - riding.lift);
			flipAllowed = p.state != SkaterState.BAILED;
			poseBoard(riding.roll, riding.pitch, pivotY, flipAllowed);
		}

		/** Finds the member's real character in the scene now and then (each second); none: a board-only ghost. */
		void updateBody(String name)
		{
			if (now >= nextLookup)
			{
				nextLookup = now + 1f;
				Player found = null;
				for (Player pl : wv.players())
				{
					if (name != null && found == null && pl != null && GhostVisibility.sameName(pl.getName(), name))
						found = pl;
				}
				body.setPlayer(found);
			}
			showBody(body.player != null);
		}

		/** Takes the ghost out of the scene; true. */
		boolean remove()
		{
			showBoard(false);
			showBody(false);
			body.setPlayer(null);
			return true;
		}
	}

	private final Client client;
	private final Map<Long, Ghost> drawn = new HashMap<>();
	/** A board mesh could not be built (cache model unavailable): not retried every frame. */
	private boolean boardModelFailed;
	private volatile List<GhostLabel> labels = Collections.emptyList();

	GhostRenderer(Client client)
	{
		this.client = client;
	}

	/** This frame's labels, for the overlay. */
	List<GhostLabel> labels()
	{
		return labels;
	}

	/**
	 * Draws {@code ghosts} for this frame, or nothing when {@code show} is false.
	 *
	 * @param names display name of a party member by ID, or null
	 * @param ground the ground ghosts on this plane follow (null: none)
	 */
	void update(Map<Long, GhostPredictor> ghosts, LongFunction<String> names, boolean show, float now, float dt,
		GhostPredictor.Ground ground)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (!show || wv == null || ghosts.isEmpty() || boardModelFailed)
		{
			// keeps boardModelFailed: no retry every frame within the session
			removeAll();
			return;
		}
		List<GhostLabel> out = new ArrayList<>(ghosts.size());
		List<Ghost> seen = new ArrayList<>();
		for (Map.Entry<Long, GhostPredictor> e : ghosts.entrySet())
		{
			GhostPredictor predictor = e.getValue();
			if (!GhostVisibility.sameSpace(client.getWorld(), wv.getPlane(), predictor.current()))
				continue;
			RenderPose p = predictor.pose(now, ground);
			int lx = Math.round(GhostCodec.toLocal(p.x, wv.getBaseX()));
			int ly = Math.round(GhostCodec.toLocal(p.y, wv.getBaseY()));
			if (!GhostVisibility.inScene(lx, ly, wv.getSizeX(), wv.getSizeY()))
				continue;
			long id = e.getKey();
			Ghost g = drawn.get(id);
			if (g == null)
			{
				// each ghost has its own board mesh, built on spawn and dropped with the ghost: posing rewrites the
				// model data, so ghosts sharing one would draw each other's flips and pitch (the baked board's
				// merged templates are shared: a spawn only copies them)
				g = new Ghost();
				if (!g.build(predictor.look()))
				{
					boardModelFailed = true;
					continue;
				}
				g.nextLookup = now;
				g.showBoard(true);
				drawn.put(id, g);
			}
			seen.add(g);
			if (!g.look.equals(predictor.look()))
			{
				// the member picked other designs: only the colours change, lit again at the next pose
				g.look = predictor.look();
				g.baked.setLook(g.look);
				for (BoardController b : g.boards)
					b.repaint();
			}
			g.predictor = predictor;
			g.p = p;
			g.x = lx;
			g.y = ly;
			g.latest = predictor.current();
			g.now = now;
			g.dt = dt;
			g.wv = wv;
			String name = names.apply(id);
			int feetZ = g.place();
			g.updateBody(name);
			g.animate();
			// the focal point's Z is the scene's y (its Y is the height)
			g.distance = GhostVisibility.focusDistance(lx, ly, client.getCameraFocalPointX(),
				client.getCameraFocalPointZ());
			Trick trick = predictor.labelTrick();
			float alpha = trick == null ? 0f : GhostVisibility.labelAlpha(predictor.labelAge(now));
			// always one per drawn ghost; the label a little over a character's height above the feet
			out.add(new GhostLabel(id, lx, ly, feetZ - 240, name, alpha > 0f ? trick.displayName : null, alpha));
		}
		drawn.values().removeIf(g -> !seen.contains(g) && g.remove());
		// the nearest few get the full body (ties in order); the rest play the animation only
		seen.sort(Comparator.comparingDouble(g -> g.distance));
		for (int i = 0; i < seen.size(); i++)
			seen.get(i).body.full = GhostVisibility.full(i, seen.get(i).distance);
		labels = out;
	}

	private void register(boolean on, RuneLiteObjectController... objects)
	{
		for (RuneLiteObjectController o : objects)
		{
			if (on)
				client.registerRuneLiteObject(o);
			else
				client.removeRuneLiteObject(o);
		}
	}

	/** A player left the scene: no ghost may keep drawing its model. */
	void forgetPlayer(Player player)
	{
		for (Ghost g : drawn.values())
		{
			if (g.body.player == player)
			{
				g.body.setPlayer(null);
				g.nextLookup = 0f;
				g.showBody(false);
			}
		}
	}

	/**
	 * Skate end, scene lost, shutdown or ghost failure: removes every ghost, and a later session (or scene) gets
	 * a fresh try at building the board model.
	 */
	void despawnAll()
	{
		boardModelFailed = false;
		removeAll();
	}

	private void removeAll()
	{
		drawn.values().forEach(Ghost::remove);
		drawn.clear();
		labels = Collections.emptyList();
	}

	/**
	 * The ground of the loaded scene at absolute coordinates, from its tile heights (up-positive; NaN outside
	 * the scene). Client thread.
	 */
	static GhostPredictor.Ground sceneGround(Client client, WorldView wv)
	{
		int plane = wv.getPlane();
		// RuneLite heights grow downward
		return localGround(wv.getBaseX(), wv.getBaseY(), wv.getSizeX(), wv.getSizeY(),
			(lx, ly) -> -Perspective.getTileHeight(client, new LocalPoint(Math.round(lx), Math.round(ly), wv), plane));
	}

	/**
	 * The ground {@code local} gives at local coordinates of the scene based at ({@code baseX}, {@code baseY}),
	 * {@code sizeX} by {@code sizeY} tiles, at absolute coordinates; NaN outside it.
	 */
	static GhostPredictor.Ground localGround(int baseX, int baseY, int sizeX, int sizeY, GhostPredictor.Ground local)
	{
		return (x, y) ->
		{
			float lx = GhostCodec.toLocal(x, baseX);
			float ly = GhostCodec.toLocal(y, baseY);
			return GhostVisibility.inScene(lx, ly, sizeX, sizeY) ? local.heightAt(lx, ly) : Float.NaN;
		};
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.SkatePhysics;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.*;

/**
 * A light version of the local skater's procedural body for a party ghost: the same {@link SkaterPoseRig}, fed
 * from what the ghost's updates carry. Lean from the turn rate, the pop charge's crouch, a push kick when a push
 * is played back (GhostPredictor.pushCount), the air tuck after a pop, the
 * landing squash and the bail fall from the update's events, grabs, manual and grind pitch, and the front / back
 * flip; knocked down, the knockdown's body (KnockdownBody). Pure; one per ghost.
 */
final class GhostRig
{
	private final SkaterPoseRig rig = new SkaterPoseRig();
	private final SkaterPoseRig.Signals signals = new SkaterPoseRig.Signals();
	private final FootBody foot = new FootBody();
	private int pops;
	private int lands;
	private int bails;
	private int pushes;
	/** The last frame was a knockdown: the next one starts the rig from standing. */
	private boolean knocked;
	private SkaterState lastState;
	/** Vertical speed (up > 0) last seen in the air, for the landing squash. */
	private float airSpeed;

	/** One render frame: steps the rig from {@code ghost} as drawn ({@code pose}) and writes it to {@code out}. */
	void update(GhostPredictor ghost, RenderPose pose, float now, float dt, BodyPose out)
	{
		SkaterPoseRig.Signals s = signals;
		startAfresh();
		boolean first = lastState == null;
		// a ghost first drawn just after a pop still extends and tucks
		// Seconds: a pop this recent when the ghost is first drawn still counts (the rig extends for 0.12 s).
		boolean popped = first ? ghost.sincePop(now) <= 0.1f : ghost.popCount() != pops;

		s.state = pose.state;
		s.speed = ghost.speed();
		s.carveRate = ghost.turnRate(now);
		s.charge = pose.state == SkaterState.AIRBORNE ? 0f : ghost.charge();
		s.verticalSpeed = ghost.verticalSpeed(now);
		// the hold's pitch only: an impossible's pitch is the board's, not the body's
		s.boardPitch = SkatePhysics.boardPitchFor(pose.state, pose.hold);
		s.hold = pose.hold;
		s.flipping = ghost.flipping(now);
		s.popped = popped;
		s.rolledOff = !first && !popped && pose.state == SkaterState.AIRBORNE && lastState != SkaterState.AIRBORNE;
		s.landed = !first && ghost.landCount() != lands;
		s.bailed = !first && ghost.bailCount() != bails;
		s.landingSpeed = Math.abs(airSpeed);
		s.pushed = !first && ghost.pushCount() != pushes;
		s.proceduralPush = true;
		s.bodyFlipAngle = ghost.bodyFlip(now);
		s.onFoot = false;
		// the next step off starts from standing
		foot.reset();
		step(ghost, pose, dt, out);
	}

	/**
	 * One render frame of a ghost on foot: upright (the walk or run is the OSRS animation under it), a light tuck
	 * in a jump (a pop on the wire) and the landing squash, as the local walker's; the gait follows the speed.
	 */
	void updateOnFoot(GhostPredictor ghost, RenderPose pose, float now, float dt, BodyPose out)
	{
		startAfresh();
		boolean airborne = pose.state == SkaterState.AIRBORNE;
		// Seconds: a pop this recent when an on-foot ghost leaves the ground makes it a jump, not a fall.
		boolean jumping = ghost.popCount() != pops || ghost.sincePop(now) <= 0.5f;
		foot.fill(signals, ghost.speed(), airborne, jumping, ghost.verticalSpeed(now));
		step(ghost, pose, dt, out);
	}

	/** The walker's gait (from its speed), for the walk or run animation. */
	FootBody.Gait gait()
	{
		return foot.gait();
	}

	/**
	 * One frame knocked down: the knockdown's body (the tumble, or with an OSRS lie-down or get-up playing, the body
	 * as animated); the next skate or walk frame starts the rig from standing, as the local skater's does.
	 */
	void knockdown(KnockdownPose k, boolean animated, BodyPose out)
	{
		KnockdownBody.write(k, animated, out);
		knocked = true;
	}

	/** The rig stepped and written; the ghost's events so far kept (the next frame's new ones are past these). */
	private void step(GhostPredictor ghost, RenderPose pose, float dt, BodyPose out)
	{
		rig.update(signals, dt);
		rig.writeTo(out);
		if (pose.state == SkaterState.AIRBORNE)
			airSpeed = signals.verticalSpeed;
		lastState = pose.state;
		pops = ghost.popCount();
		lands = ghost.landCount();
		bails = ghost.bailCount();
		pushes = ghost.pushCount();
	}

	private void startAfresh()
	{
		if (knocked)
		{
			knocked = false;
			rig.reset();
			foot.reset();
			lastState = null;
		}
	}
}

package com.gielinorskate.party;

import java.util.Arrays;

/**
 * When the local skater's state goes to the party. While another party member is skating (an audience),
 * events go out as they happen, a state snapshot at most once per game tick (0.6 s) and only when something
 * changed, and a keep-alive after 10 s without any message. With no audience only an "I'm skating" announce
 * goes out, at most once every {@link #ANNOUNCE_INTERVAL} s, so other skaters can discover this one. Never more
 * than {@link #MAX_PER_SECOND} messages in any one-second window: a token bucket of 2 tokens in which each spent
 * token comes back exactly 1 s after it was spent, so even a burst of events cannot put more than 2 messages
 * into any second (events held back coalesce into the next message). Times are seconds on one monotonic clock.
 * Pure.
 */
final class GhostSendPolicy
{
	static final int MAX_PER_SECOND = 2;
	/** One game tick. */
	static final float SNAPSHOT_INTERVAL = 0.6f;
	/** Receivers expire a ghost after 15 s of silence, so an idle skater re-sends well before. */
	static final float KEEP_ALIVE = 10f;
	/** Without an audience: one announce per 5 s, well inside the receivers' 15 s ghost expiry. */
	static final float ANNOUNCE_INTERVAL = 5f;
	/** The limit's window, seconds. */
	static final float WINDOW = 1f;

	/** Times of the latest sends, oldest first once full (a ring of MAX_PER_SECOND). */
	private final float[] recent = new float[MAX_PER_SECOND];
	private int recentNext;
	/** When the latest update or stop went out (negative infinity when none since a reset). */
	private float lastSend = Float.NEGATIVE_INFINITY;
	private int seq;

	/** Sequence numbers start just above {@code seqStart}. */
	GhostSendPolicy(int seqStart)
	{
		seq = seqStart;
		// no sends yet
		Arrays.fill(recent, Float.NEGATIVE_INFINITY);
	}

	/** A message may go out at {@code now} without breaking the per-second limit. */
	boolean hasToken(float now)
	{
		return freeTokens(now) > 0;
	}

	/**
	 * Whether to send the current state now.
	 *
	 * @param changed the state differs from the last one sent
	 * @param event an event (pop, land, trick...) is waiting to go out
	 */
	boolean shouldSend(float now, boolean changed, boolean event)
	{
		float since = now - lastSend;
		return hasToken(now) && (event || since >= KEEP_ALIVE || changed && since >= SNAPSHOT_INTERVAL);
	}

	/**
	 * With nobody else skating: whether the cheap "I'm skating" announce is due. Only with every token free, so a
	 * stop right after it (skating toggled off) still fits in the limit.
	 */
	boolean shouldAnnounce(float now)
	{
		return freeTokens(now) == MAX_PER_SECOND && now - lastSend >= ANNOUNCE_INTERVAL;
	}

	/** How many messages may go out at {@code now} without breaking the per-second limit. */
	int freeTokens(float now)
	{
		int free = MAX_PER_SECOND;
		for (float r : recent)
			free -= now - r < WINDOW ? 1 : 0;
		return free;
	}

	/** Records a message (update or stop) sent at {@code now}. */
	void recordSend(float now)
	{
		recent[recentNext] = now;
		recentNext = (recentNext + 1) % MAX_PER_SECOND;
		lastSend = now;
	}

	/** Sharing (re)starts: the first snapshot may go out at once. The rate limit is kept. */
	void reset()
	{
		lastSend = Float.NEGATIVE_INFINITY;
	}

	/** The next sequence number; never repeats while the plugin runs. */
	int nextSeq()
	{
		return ++seq;
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.KnockdownPose;
import com.gielinorskate.tricks.Trick;
import lombok.AllArgsConstructor;

/**
 * A skater's state: the local skater's on one frame (ready to encode, events and seq 0) or a party member's decoded
 * from a {@link SkateGhostUpdate}. Positions are absolute (world tile * 128 + sub-tile). Pure value.
 */
@AllArgsConstructor
final class GhostState
{
	final int world;
	final int plane;
	final float x;
	final float y;
	/** Up-positive. */
	final float h;
	final float heading;
	final float vx;
	final float vy;
	final float vh;
	final SkaterState state;
	/** Current grab, manual or grind, or null. */
	final Trick hold;
	/** GhostCodec.EV_* bitmask (received only). */
	final int events;
	/** The flip turning the board (received: or the TRICK event's trick), or null. */
	final Trick trick;
	/** Seconds into the trick's nominal duration. */
	final float flipTime;
	final int seq;
	/** Heading turn rate, rad/s, + = clockwise from above (a flip's own body turn not included, TurnRateMeter). */
	final float turnRate;
	/** Front / back flip angle of the whole skater, radians, + = frontflip; 0 off the air. */
	final float bodyFlip;
	/** Its rate, rad/s: a held flip at least BodyFlipMeter.HELD_RATE, slower is easing onto a whole turn. */
	final float bodyFlipRate;
	/** Off the board (x / y / h are the walker's): the board CARRIED or DROPPED; null on the board. */
	final BoardState offBoard;
	/** A DROPPED board: absolute position, up-positive height, nose heading. */
	final float boardX;
	final float boardY;
	final float boardH;
	final float boardHeading;
	/** Pop charge 0..1 (the crouch before a pop); 0 when none, or from an older version. */
	final float charge;
	/**
	 * Knocked off the board: the knockdown's stage (x / y / h are the body's lowest point, the heading its facing,
	 * the board DROPPED); null otherwise, or from an older version.
	 */
	final KnockdownPose.Stage knockStage;
	/** The tumble angle the knocked-off body comes to lie at (radians, + tips the head toward the facing). */
	final float knockLie;
}

package com.gielinorskate.party;

import com.gielinorskate.physics.*;
import com.gielinorskate.render.PoseSmoothing;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import java.util.Arrays;

/**
 * A party member's ghost played back on the member's own clock: every received position (the updates' own and the
 * positions batched into them, {@link GhostTrajectory}) is kept in time order, and the ghost is drawn at the
 * playback time, a delay behind the member's clock ({@link GhostClockSync#delay}), between the positions on either
 * side of it instead of guessing ahead of the last one:
 * <ul>
 * <li>position and heading along cubic Hermite curves through them with their velocities and turn rates (sent ones,
 * else from their neighbours), so neither position nor velocity jumps at a sample;</li>
 * <li>in the air, height along the gravity parabola through the two samples (split at the pop or landing when that
 * falls between them); on the ground, the height above the receiver's ground follows the samples and the ground
 * under the ghost is added back, so slopes, steps and stairs look right here;</li>
 * <li>events (pops, landings, tricks...) and flips happen when the playback time reaches when they happened.</li>
 * </ul>
 * The playback clock runs at the speed of ours, within a few percent: it catches up or falls back gently to the
 * target delay, slows down when it is about to run past the last sample, and only past the last sample does the ghost
 * dead-reckon (for {@link #MAX_EXTRAPOLATION}, then it settles to a stop). Whatever changes what is drawn at once (late or
 * reordered samples, a resumed stream) is blended out ({@link #BLEND_TAU}), never jumped, unless it is a teleport.
 * Pure; nothing is allocated per frame. The subclass ({@link GhostPredictor}) hears the events as they are played.
 */
abstract class GhostTimeline
{
	/**
	 * Past the last sample, dead reckoning lasts this long (one lost update), then the ghost settles to a stop
	 * (SETTLE_TIME).
	 */
	static final float MAX_EXTRAPOLATION = 0.5f;
	/** Past MAX_EXTRAPOLATION, playback (and the ghost with it) slows to a stop within this much more member time. */
	static final float SETTLE_TIME = 0.3f;
	/** Playback speeds toward the target delay by this much per second of error... */
	static final float GAIN = 0.5f;
	/**
	 * ...but never more than this much slower or faster than our clock while it is near the target (an error under
	 * MAX_RATE_CHANGE / GAIN = 0.12 s: the usual jitter), so no speed change shows...
	 */
	static final float MAX_RATE_CHANGE = 0.06f;
	/** ...and never more than this much faster catching up after the buffer ran dry (a slight fast-forward). */
	static final float MAX_CATCH_UP = 0.25f;
	/**
	 * About to run past the last sample of a moving ghost: playback slows to this, and once dead reckoning is over
	 * it slows to a stop with the ghost (SETTLE_TIME), so when updates come again it carries on from about where the
	 * ghost was drawn and catches up, instead of the ghost sliding there.
	 */
	static final float UNDERRUN_RATE = 0.9f;
	/** The playback speed changes by at most this much per second (outside a dry buffer's slowdown). */
	static final float RATE_SLEW = 0.6f;
	/** A sample closer than this (seconds) to one already kept is the same one. */
	static final double SAME_TIME = 0.008;
	/** Neighbours further apart than this (seconds) say nothing about a sample's velocity. */
	static final double MAX_TANGENT_SPAN = 1.0;
	/** Events this late when received still play from their start, at most this far in. */
	static final float LATE_EVENT = 0.1f;

	private static final int CAP = 64;
	private static final int KEYS = 32;
	private static final int EVENTS = 48;
	private static final int MARKS = 16;
	private static final SkaterState[] STATES = SkaterState.values();
	private static final int AIR = SkaterState.AIRBORNE.ordinal();
	private static final int ROLL = SkaterState.ROLLING.ordinal();
	private static final int MANUAL = SkaterState.MANUAL.ordinal();
	private static final int BAIL = SkaterState.BAILED.ordinal();

	// samples, in time order
	final double[] t = new double[CAP];
	private final float[] x = new float[CAP];
	private final float[] y = new float[CAP];
	private final float[] h = new float[CAP];
	/** Unwrapped against the sample before. */
	private final float[] hd = new float[CAP];
	private final float[] vx = new float[CAP];
	private final float[] vy = new float[CAP];
	private final float[] vh = new float[CAP];
	private final float[] turn = new float[CAP];
	/** Height above the receiver's ground on the ground; NaN when unknown or not on the ground. */
	private final float[] clear = new float[CAP];
	/** The sample is an update's own: its velocity was sent. */
	private final boolean[] exact = new boolean[CAP];
	/** Its turn rate was sent and is the heading's (no bigspin turning the body as well). */
	private final boolean[] exactTurn = new boolean[CAP];
	private final byte[] st = new byte[CAP];
	private final Object[] samples = {t, x, y, h, hd, vx, vy, vh, turn, clear, exact, exactTurn, st};
	int n;
	private int seg;

	// updates (keys), in time order
	private final double[] kt = new double[KEYS];
	private final GhostState[] ks = new GhostState[KEYS];
	private final Object[] keys = {kt, ks};
	private int kn;
	private GhostState current;

	// events waiting to be played, in time order
	private final double[] et = new double[EVENTS];
	private final int[] eb = new int[EVENTS];
	private final Trick[] etr = new Trick[EVENTS];
	private final boolean[] enl = new boolean[EVENTS];
	private final Object[] events = {et, eb, etr, enl};
	private int en;

	// pops and landings (a ring), splitting the height curve between samples
	private final double[] mt = new double[MARKS];
	private final int[] mb = new int[MARKS];
	private int mNext;
	private int mCount;

	GhostClockSync sync = new GhostClockSync();
	double tp;
	private boolean started;
	private float lastNow;
	float rate = 1f;
	/** The last advance ran past the last sample, or was held back from it. */
	boolean dry;
	private boolean evaluated;

	/**
	 * Corrections still blending out (x, y, h, heading) and their velocities: the corrections are springs, so drawn
	 * velocity never jumps either.
	 */
	private final float[] off = new float[4];
	private final float[] offV = new float[4];

	// the raw curve at a time (scratch of evalRaw)
	private float rx;
	private float ry;
	private float rh;
	private float rhd;
	private float rvx;
	private float rvy;
	private float rvh;
	private float rturn;
	private int rstate;

	// what is drawn now (after advance): heading wrapped to (-PI, PI], turn rate the curve's own (smooth through the
	// samples)
	float ox;
	float oy;
	float oh;
	float ohd;
	float ovx;
	float ovy;
	float ovh;
	float oturn;
	private int ostate;
	/** The ground last given. */
	GhostPredictor.Ground lastGround;

	/** EV_* {@code bits} happened; {@code at} is our clock's time they were played at. */
	abstract void event(int bits, Trick trick, boolean nollie, float at);

	/** The drawn update changed to {@code key}, which was played at {@code at} (our clock). */
	abstract void keyChanged(GhostState key, float at);

	/**
	 * Takes in update {@code s}, received at {@code now}, with its timeline {@code tj}, or none (an update whose
	 * timeline did not fit: placed by its arrival, as early as it can have been sent). Returns false, taking nothing
	 * in, for an update without a timeline before any with one.
	 */
	boolean receive(GhostState s, GhostTrajectory tj, float now, GhostPredictor.Ground ground)
	{
		if (tj == null && !sync.has())
			return false;
		advance(now, ground);
		boolean had = n > 0 && evaluated;
		if (kn > 0 && (ks[kn - 1].world != s.world || ks[kn - 1].plane != s.plane))
		{
			// another world or plane: nothing to blend from
			clearBuffers();
			had = false;
		}
		double ts;
		if (tj != null)
		{
			ts = sync.unwrap(tj.timeMs);
			if (!sync.observe(now, ts))
			{
				// the sender started again: a new clock
				sync = new GhostClockSync();
				clearBuffers();
				started = false;
				ts = sync.unwrap(tj.timeMs);
				sync.observe(now, ts);
			}
		}
		else
		{
			ts = now - sync.floor();
			if (kn > 0)
				// never before (nor at the same time as) the update before it
				ts = Math.max(ts, kt[kn - 1] + 2 * SAME_TIME);
		}
		insertKey(ts, s);
		boolean bigspin = s.trick != null && s.trick.bodyYawTurns != 0f && s.trick.kind == TrickKind.FLIP;
		insertSample(ts, s.x, s.y, s.h, s.heading, s.vx, s.vy, s.vh, s.turnRate, true, !bigspin, s.state, ground);
		for (int i = 0; tj != null && i < tj.count; i++)
			insertSample(ts - tj.ago[i], tj.x[i], tj.y[i], tj.h[i], tj.heading[i], 0f, 0f, 0f, 0f, false, false,
				tj.state[i], ground);
		for (int bit = 0; bit < GhostTrajectory.EVENT_BITS; bit++)
		{
			int b = 1 << bit;
			if ((s.events & b) == 0)
				continue;
			double at = ts - (tj == null || Float.isNaN(tj.eventAgo[bit]) ? 0f : tj.eventAgo[bit]);
			insertEvent(at, b, b == GhostCodec.EV_TRICK ? (s.trick != null ? s.trick : s.hold) : null,
				b == GhostCodec.EV_POP && PoseSmoothing.isNollie(s.trick));
			if (b == GhostCodec.EV_POP || b == GhostCodec.EV_LAND)
			{
				mt[mNext] = at;
				mb[mNext] = b;
				mNext = (mNext + 1) % MARKS;
				mCount = Math.min(MARKS, mCount + 1);
			}
		}
		if (!started)
		{
			started = true;
			tp = target(now);
			lastNow = now;
		}
		evalRaw(tp, ground);
		if (had)
			// what was drawn a moment ago stays drawn, moving as it was: the difference settles out
			rebase();
		output();
		evaluated = true;
		return true;
	}

	/**
	 * The corrections that keep what is drawn (o*) where it is and moving and turning as it was over the curve as now
	 * evaluated (r*), so neither the position nor the velocity jumps; a correction further than a teleport is dropped
	 * (the ghost snaps).
	 */
	private void rebase()
	{
		off[0] = ox - rx;
		off[1] = oy - ry;
		off[2] = oh - rh;
		off[3] = Angles.wrap(ohd - rhd);
		offV[0] = ovx - rvx * rate;
		offV[1] = ovy - rvy * rate;
		// height eases in from rest: a landing's stop is real, and must not carry the ghost through the ground
		offV[2] = 0f;
		offV[3] = oturn + offV[3] - rturn * rate;
		if (Math.hypot(off[0], off[1]) > GhostPredictor.SNAP_DISTANCE
			|| Math.abs(off[2]) > GhostPredictor.SNAP_DISTANCE)
			clearOffsets();
	}

	/**
	 * Moves the playback time on to our clock's {@code now} (once per {@code now}), plays the events it passes and
	 * works out what is drawn.
	 */
	void advance(float now, GhostPredictor.Ground ground)
	{
		if (n == 0 || !started || evaluated && now == lastNow)
			return;
		float dt = Math.max(0f, now - lastNow);
		lastNow = now;
		double target = target(now);
		// Further than this (seconds) from the target, the playback time is set to it (after a long silence).
		if (Math.abs(target - tp) > 3f)
		{
			// a long silence or a new clock: on to the target, what was drawn blending into it
			tp = target;
			evalRaw(tp, ground);
			rebase();
			rate = 1f;
			dry = false;
		}
		else
		{
			float err = (float) (target - tp);
			// near the target a few percent either way; well behind it (after a dry buffer) a slight fast-forward
			float fast = Math.max(MAX_RATE_CHANGE, Math.min(MAX_CATCH_UP, (err - MAX_RATE_CHANGE / GAIN) * GAIN));
			float desired = 1f + GhostCodec.clamp(err * GAIN, -MAX_RATE_CHANGE, fast);
			// the speed itself changes gently (a new delay target is a step), so the ghost's velocity never jumps
			float step = RATE_SLEW * dt;
			rate += GhostCodec.clamp(desired - rate, -step, step);
			float cap = dryRate();
			dry = cap < Float.MAX_VALUE;
			rate = Math.min(rate, cap);
			tp += rate * dt;
		}
		settle(dt);
		int played = 0;
		for (; played < en && et[played] <= tp; played++)
			event(eb[played], etr[played], enl[played], now - (float) Math.min(LATE_EVENT, tp - et[played]));
		move(events, played, 0, en - played);
		en -= played;
		int k = keyIndex(tp);
		if (kn > 0 && ks[k] != current)
		{
			current = ks[k];
			keyChanged(current, now - (float) Math.min(LATE_EVENT, Math.max(0.0, tp - kt[k])));
		}
		evalRaw(tp, ground);
		output();
		evaluated = true;
		prune();
	}

	/**
	 * The fastest playback may run past the last sample of a moving ghost: easing from our clock's speed down to
	 * UNDERRUN_RATE over the dead reckoning, then to a stop over SETTLE_TIME (so the ghost glides to a halt where its
	 * dead reckoning took it, and carries on from there when updates come again); unlimited otherwise.
	 */
	private float dryRate()
	{
		float past = n == 0 ? -1f : (float) (tp - t[n - 1]);
		if (past < 0f || !moving(n - 1))
			return Float.MAX_VALUE;
		if (past < MAX_EXTRAPOLATION)
			return 1f - (1f - UNDERRUN_RATE) * past / MAX_EXTRAPOLATION;
		return UNDERRUN_RATE * Math.max(0f, 1f - (past - MAX_EXTRAPOLATION) / SETTLE_TIME);
	}

	private double target(float now)
	{
		return now - sync.floor() - sync.delay();
	}

	/**
	 * {@code dt} seconds of the corrections settling: each a critically damped spring ({@link #BLEND_TAU}), solved
	 * exactly, so a correction starts at the velocity it was given and comes to rest without overshoot.
	 */
	private void settle(float dt)
	{
		// Seconds (time constant) a correction of what is drawn fades out over.
		float w = 1f / 0.12f;
		float e = (float) Math.exp(-w * dt);
		for (int k = 0; k < 4; k++)
		{
			float a = offV[k] + w * off[k];
			off[k] = (off[k] + a * dt) * e;
			offV[k] = (offV[k] - w * a * dt) * e;
		}
	}

	private void output()
	{
		ox = rx + off[0];
		oy = ry + off[1];
		oh = rh + off[2];
		ohd = Angles.wrap(rhd + off[3]);
		// as drawn on our clock: the curve's velocity at the playback speed, plus the corrections'
		ovx = rvx * rate + offV[0];
		ovy = rvy * rate + offV[1];
		ovh = rvh * rate + offV[2];
		oturn = rturn * rate;
		ostate = rstate;
	}

	private void clearOffsets()
	{
		Arrays.fill(off, 0f);
		Arrays.fill(offV, 0f);
	}

	private void clearBuffers()
	{
		n = 0;
		kn = 0;
		en = 0;
		mCount = 0;
		seg = 0;
		current = null;
		evaluated = false;
		clearOffsets();
	}

	private boolean moving(int i)
	{
		// A ghost moving slower than this (u/s) on the ground is standing: it can be held without slowing playback.
		return st[i] == AIR || Math.hypot(velX(i), velY(i)) > 20f;
	}

	/** Moves entries {@code from}.. of every array in {@code columns} to start at {@code to}. */
	private static void move(Object[] columns, int from, int to, int count)
	{
		for (Object c : columns)
			System.arraycopy(c, from, c, to, count);
	}

	private void prune()
	{
		// Played samples are kept this long (seconds) for the curves' tangents.
		double old = tp - 2f;
		int drop = 0;
		while (n - drop > 2 && t[drop + 1] < old)
			drop++;
		shiftSamples(drop);
		if (n > 0 && Math.abs(hd[0]) > 32 * Angles.TWO_PI)
		{
			// a long carve's unwrapped headings back near zero (whole turns), before floats lose their precision
			float turns = Math.round(hd[0] / Angles.TWO_PI) * Angles.TWO_PI;
			for (int k = 0; k < n; k++)
				hd[k] -= turns;
			rhd -= turns;
		}
		int kd = 0;
		while (kn - kd > 1 && kt[kd + 1] < old)
			kd++;
		move(keys, kd, 0, kn - kd);
		kn -= kd;
	}

	private void shiftSamples(int drop)
	{
		if (drop > 0)
		{
			n -= drop;
			move(samples, drop, 0, n);
			seg = 0;
		}
	}

	/** A sample in time order; its headings, and the ones after it, unwrapped: each the short way from the one before. */
	private void insertSample(double time, float px, float py, float ph, float heading, float pvx, float pvy,
		float pvh, float pturn, boolean isExact, boolean isExactTurn, SkaterState state, GhostPredictor.Ground ground)
	{
		int j = n;
		while (j > 0 && t[j - 1] > time)
			j--;
		// the same time as a kept one: the update's own sample is better than a batched one
		int same = j > 0 && time - t[j - 1] < SAME_TIME ? j - 1 : j < n && t[j] - time < SAME_TIME ? j : -1;
		if (same >= 0)
		{
			if (!isExact || exact[same])
				return;
			j = same;
		}
		else
		{
			if (n == CAP)
			{
				if (j == 0)
					return;
				shiftSamples(1);
				j--;
			}
			move(samples, j, j + 1, n - j);
			n++;
			seg = 0;
		}
		t[j] = time;
		x[j] = px;
		y[j] = py;
		h[j] = ph;
		float ref = j > 0 ? hd[j - 1] : j + 1 < n ? hd[j + 1] : heading;
		hd[j] = ref + Angles.wrap(heading - ref);
		vx[j] = pvx;
		vy[j] = pvy;
		vh[j] = pvh;
		turn[j] = pturn;
		exact[j] = isExact;
		exactTurn[j] = isExactTurn;
		st[j] = (byte) state.ordinal();
		float g = ground != null && (st[j] == ROLL || st[j] == MANUAL) ? ground.heightAt(px, py) : Float.NaN;
		clear[j] = ph - g;
		for (int k = j + 1; k < n; k++)
			hd[k] = hd[k - 1] + Angles.wrap(hd[k] - hd[k - 1]);
	}

	private void insertKey(double time, GhostState s)
	{
		int j = kn;
		while (j > 0 && kt[j - 1] > time)
			j--;
		if (j > 0 && time - kt[j - 1] < SAME_TIME || kn == KEYS && j == 0)
			return;
		if (kn == KEYS)
		{
			move(keys, 1, 0, --kn);
			j--;
		}
		move(keys, j, j + 1, kn - j);
		kt[j] = time;
		ks[j] = s;
		kn++;
	}

	private void insertEvent(double time, int bits, Trick trick, boolean nollie)
	{
		if (en == EVENTS)
			return;
		int j = en;
		while (j > 0 && et[j - 1] > time)
			j--;
		move(events, j, j + 1, en - j);
		et[j] = time;
		eb[j] = bits;
		etr[j] = trick;
		enl[j] = nollie;
		en++;
	}

	private int keyIndex(double time)
	{
		int k = kn - 1;
		while (k > 0 && kt[k] > time)
			k--;
		return Math.max(0, k);
	}

	/** The velocity-like slope of {@code a} at sample {@code i} from its neighbours (exact for a parabola). */
	private float tangent(float[] a, int i)
	{
		boolean left = i > 0 && t[i] - t[i - 1] <= MAX_TANGENT_SPAN && !teleport(i - 1);
		boolean right = i + 1 < n && t[i + 1] - t[i] <= MAX_TANGENT_SPAN && !teleport(i);
		double s0 = left ? (a[i] - a[i - 1]) / (t[i] - t[i - 1]) : 0;
		double s1 = right ? (a[i + 1] - a[i]) / (t[i + 1] - t[i]) : 0;
		if (left && right)
		{
			double h0 = t[i] - t[i - 1];
			double h1 = t[i + 1] - t[i];
			return (float) ((h1 * s0 + h0 * s1) / (h0 + h1));
		}
		return (float) (s0 + s1);
	}

	/** Samples i and i + 1 are too far apart for the time between them. */
	private boolean teleport(int i)
	{
		double d = Math.hypot(x[i + 1] - x[i], y[i + 1] - y[i]);
		// A step faster than this (u/s) and longer than SNAP_DISTANCE between two samples is a teleport.
		return d > GhostPredictor.SNAP_DISTANCE && d > 4000f * (t[i + 1] - t[i]);
	}

	private float velX(int i)
	{
		return exact[i] ? vx[i] : tangent(x, i);
	}

	private float velY(int i)
	{
		return exact[i] ? vy[i] : tangent(y, i);
	}

	private float turnAt(int i)
	{
		return st[i] == BAIL ? 0f : exactTurn[i] ? turn[i] : tangent(hd, i);
	}

	/** The segment [i, i + 1] holding {@code time} (t[0] <= time < t[n - 1]). */
	private int segment(double time)
	{
		int i = Math.max(0, Math.min(seg, n - 2));
		if (t[i] > time)
			i = 0;
		while (i + 1 < n - 1 && t[i + 1] <= time)
			i++;
		seg = i;
		return i;
	}

	/** The curve at {@code time} into the r* scratch. */
	private void evalRaw(double time, GhostPredictor.Ground ground)
	{
		lastGround = ground;
		if (n == 0)
			return;
		if (time > t[0] && time >= t[n - 1])
		{
			extrapolate(n - 1, (float) (time - t[n - 1]), ground);
			return;
		}
		int i = time <= t[0] ? 0 : segment(time);
		int j = i + 1;
		if (time <= t[0] || teleport(i))
		{
			// held at the sample
			rx = x[i];
			ry = y[i];
			rh = h[i];
			rhd = hd[i];
			rvx = 0f;
			rvy = 0f;
			rvh = 0f;
			rturn = 0f;
			rstate = st[i];
			return;
		}
		float dt = (float) (t[j] - t[i]);
		float u = (float) ((time - t[i]) / (t[j] - t[i]));
		float mx0 = velX(i) * dt;
		float mx1 = velX(j) * dt;
		float my0 = velY(i) * dt;
		float my1 = velY(j) * dt;
		rx = along(x, i, mx0, mx1, u);
		ry = along(y, i, my0, my1, u);
		rvx = slope(x, i, mx0, mx1, u) / dt;
		rvy = slope(y, i, my0, my1, u) / dt;
		float mh0 = turnAt(i) * dt;
		float mh1 = turnAt(j) * dt;
		rhd = along(hd, i, mh0, mh1, u);
		rturn = st[i] == BAIL ? 0f
			: GhostCodec.clamp(slope(hd, i, mh0, mh1, u) / dt, -TurnRateMeter.MAX_RATE, TurnRateMeter.MAX_RATE);
		rstate = st[i];
		boolean airI = st[i] == AIR;
		boolean airJ = st[j] == AIR;
		if (airI && airJ)
			parabola(t[i], h[i], t[j], h[j], time);
		else if (airI || airJ)
		{
			// landing between the two: the arc ends at the landing, on the ground there, then the ground; a pop: the
			// ground until it, then the arc from the ground there
			double at = crossing(airI ? i : j, airI ? j : i, airI ? 1 : -1);
			int g = airI ? j : i;
			if (airI ? time >= at : time < at)
				onGround(g, ground);
			else
			{
				float gh = h[g];
				if (ground != null && !Float.isNaN(clear[g]))
				{
					// the ground under the ghost then
					float uu = (float) ((at - t[i]) / dt);
					float g0 = ground.heightAt(hermite(x[i], mx0, x[j], mx1, uu), hermite(y[i], my0, y[j], my1, uu));
					gh = Float.isNaN(g0) ? h[g] : g0 + clear[g];
				}
				if (airI)
					parabola(t[i], h[i], at, gh, time);
				else
					parabola(at, gh, t[j], h[j], time);
			}
		}
		else
		{
			float g = ground != null && !Float.isNaN(clear[i]) && !Float.isNaN(clear[j]) ? ground.heightAt(rx, ry)
				: Float.NaN;
			if (!Float.isNaN(g))
			{
				// above the ground here, as far above it as the samples were above theirs
				rh = g + clear[i] + (clear[j] - clear[i]) * u;
				rvh = (float) ((h[j] - h[i]) / (t[j] - t[i]));
			}
			else
			{
				float m0 = heightSlope(i) * dt;
				float m1 = heightSlope(j) * dt;
				rh = along(h, i, m0, m1, u);
				rvh = slope(h, i, m0, m1, u) / dt;
			}
			return;
		}
		if (rstate == AIR && ground != null)
		{
			float g = ground.heightAt(rx, ry);
			if (!Float.isNaN(g) && rh < g)
				rh = g;
		}
	}

	private float heightSlope(int i)
	{
		return exact[i] && st[i] == AIR ? vh[i] : tangent(h, i);
	}

	/** Sample {@code i}'s height on the ground at (rx, ry): above the ground here as it was there, else as sent. */
	private void onGround(int i, GhostPredictor.Ground ground)
	{
		rh = h[i];
		rvh = 0f;
		rstate = st[i];
		float g = ground != null && !Float.isNaN(clear[i]) ? ground.heightAt(rx, ry) : Float.NaN;
		if (!Float.isNaN(g))
			rh = g + clear[i];
	}

	/**
	 * When the ghost crossed between air sample {@code a} and ground sample {@code g}: going forward in time
	 * ({@code dir} 1) the landing, back (-1) the pop. The event's own time, else where the arc through {@code a}
	 * meets {@code g}'s height (the update with the event was lost, or a roll off a ledge).
	 */
	private double crossing(int a, int g, int dir)
	{
		int bit = dir > 0 ? GhostCodec.EV_LAND : GhostCodec.EV_POP;
		double from = t[Math.min(a, g)];
		double to = t[Math.max(a, g)];
		double best = Double.NaN;
		for (int k = 0; k < mCount; k++)
		{
			if (mb[k] == bit && mt[k] >= from && mt[k] <= to && (Double.isNaN(best) || mt[k] > best))
				best = mt[k];
		}
		if (!Double.isNaN(best))
			return best;
		// the vertical speed at a, along the time direction
		float v = Float.NaN;
		int b = a - dir;
		if (exact[a])
			v = dir * vh[a];
		else if (b >= 0 && b < n && st[b] == AIR)
		{
			float span = (float) Math.abs(t[a] - t[b]);
			v = (h[a] - h[b]) / span - GhostPredictor.GRAVITY / 2f * span;
		}
		double gr = GhostPredictor.GRAVITY;
		double disc = (double) v * v + 2 * gr * (h[a] - h[g]);
		if (Float.isNaN(v) || disc < 0)
			return t[g];
		return Math.max(from, Math.min(to, t[a] + dir * (v + Math.sqrt(disc)) / gr));
	}

	/**
	 * {@code a} from sample i on to sample i + 1 along the Hermite curve with end slopes m0, m1 (per segment) at
	 * {@code u}: relative to a[i], as world coordinates are large and their float sums would round.
	 */
	private static float along(float[] a, int i, float m0, float m1, float u)
	{
		return a[i] + hermite(0f, m0, a[i + 1] - a[i], m1, u);
	}

	/** The rate of change of {@link #along} per segment. */
	private static float slope(float[] a, int i, float m0, float m1, float u)
	{
		float u2 = u * u;
		return (3 * u2 - 4 * u + 1) * m0 + (-6 * u2 + 6 * u) * (a[i + 1] - a[i]) + (3 * u2 - 2 * u) * m1;
	}

	private static float hermite(float p0, float m0, float p1, float m1, float u)
	{
		float u2 = u * u;
		float u3 = u2 * u;
		return (2 * u3 - 3 * u2 + 1) * p0 + (u3 - 2 * u2 + u) * m0 + (-2 * u3 + 3 * u2) * p1 + (u3 - u2) * m1;
	}

	/** The gravity parabola through (t0, h0) and (t1, h1) at {@code time}. */
	private void parabola(double t0, float h0, double t1, float h1, double time)
	{
		double span = Math.max(1e-4, t1 - t0);
		double s = Math.max(0.0, Math.min(span, time - t0));
		float g = GhostPredictor.GRAVITY;
		rh = (float) (h0 + (h1 - h0) * s / span + g / 2.0 * s * (span - s));
		rvh = (float) ((h1 - h0) / span + g / 2.0 * (span - 2 * s));
		rstate = AIR;
	}

	/** Dead reckoning from the last sample {@code i}, {@code past} seconds after it (at most as far as playback goes). */
	private void extrapolate(int i, float past, GhostPredictor.Ground ground)
	{
		// the playback itself slows to a stop past the dead reckoning (dryRate): the ghost goes where its clock goes
		float dt = Math.min(past, MAX_EXTRAPOLATION + SETTLE_TIME);
		float svx = velX(i);
		float svy = velY(i);
		float w = turnAt(i);
		int state = st[i];
		boolean carving = state == ROLL || state == MANUAL;
		rx = x[i] + svx * dt;
		ry = y[i] + svy * dt;
		rvx = svx;
		rvy = svy;
		if (carving && Math.abs(w) > 1e-3f)
		{
			// the velocity turns with the heading: along the arc, not its tangent
			double theta = Math.atan2(svx, svy);
			double speed = Math.hypot(svx, svy);
			double r = speed / w;
			rx = x[i] + (float) (r * (Math.cos(theta) - Math.cos(theta + w * dt)));
			ry = y[i] + (float) (r * (Math.sin(theta + w * dt) - Math.sin(theta)));
			rvx = (float) (Math.sin(theta + w * dt) * speed);
			rvy = (float) (Math.cos(theta + w * dt) * speed);
		}
		rhd = hd[i] + w * dt;
		rstate = state;
		float svh = heightSlope(i);
		rh = h[i] + svh * dt;
		rvh = svh;
		if (state == AIR)
		{
			rh -= GhostPredictor.GRAVITY / 2f * dt * dt;
			rvh -= GhostPredictor.GRAVITY * dt;
			float g = ground == null ? Float.NaN : ground.heightAt(rx, ry);
			if (!Float.isNaN(g) && rh < g)
			{
				rh = g;
				rvh = 0f;
			}
		}
		else if (carving)
			onGround(i, ground);
		rturn = GhostCodec.clamp(w, -TurnRateMeter.MAX_RATE, TurnRateMeter.MAX_RATE);
	}

	SkaterState state()
	{
		return STATES[ostate];
	}

	/** The update being played: the latest one sent at or before the playback time. */
	GhostState playing()
	{
		return current != null ? current : kn > 0 ? ks[0] : null;
	}

	/** The board flip playing at the playback time, or null. */
	Trick flipTrick()
	{
		int f = flipIndex();
		return f < 0 ? null : ks[f].trick;
	}

	/** Seconds into {@link #flipTrick} at the playback time. */
	float flipTime()
	{
		int f = flipIndex();
		return f < 0 ? 0f : (float) (tp - flipStart(f));
	}

	/** The update of the latest board flip started (on the member's clock) and still turning at the playback time. */
	private int flipIndex()
	{
		int best = -1;
		for (int k = 0; k < kn; k++)
		{
			Trick f = ks[k].trick;
			double start = flipStart(k);
			if (f != null && f.kind == TrickKind.FLIP && f.duration > 0f && start <= tp && tp < start + f.duration
				&& (best < 0 || start > flipStart(best)))
				best = k;
		}
		return best;
	}

	/** When update {@code k}'s flip started. */
	private double flipStart(int k)
	{
		return kt[k] - ks[k].flipTime;
	}

	/**
	 * The front / back flip angle at the playback time (raw, whole turns kept): between two updates in the air along
	 * the curve through both angles and rates, else on from the update being played.
	 */
	float bodyFlip()
	{
		int k = keyIndex(tp);
		GhostState a = ks[k];
		if (kn == 0 || a.state != SkaterState.AIRBORNE)
			return 0f;
		float since = (float) Math.max(0.0, tp - kt[k]);
		if (k + 1 < kn && ks[k + 1].state == SkaterState.AIRBORNE && kt[k] <= tp)
		{
			GhostState b = ks[k + 1];
			float span = (float) (kt[k + 1] - kt[k]);
			return hermite(a.bodyFlip, a.bodyFlipRate * span, b.bodyFlip, b.bodyFlipRate * span, since / span);
		}
		// A body flip goes on from the update being played for at most this long (one lost or rate-limited update).
		float dt = Math.min(1.2f, since);
		float angle = a.bodyFlip;
		float w = a.bodyFlipRate;
		if (Math.abs(w) >= BodyFlipMeter.HELD_RATE)
			angle += w * dt;
		else if (w != 0f)
		{
			float r = BodyFlip.residual(angle);
			angle -= Math.copySign(Math.min(Math.abs(r), Math.abs(w) * dt), r);
		}
		return angle;
	}
}

package com.gielinorskate.party;

import java.util.Arrays;

/**
 * Sender side of the timeline: the local skater's position every {@link #SPACING} seconds and when each event
 * last happened, so each update can carry the few positions since the update before it and its events' times
 * ({@link GhostTrajectory}). Updates go every 0.6 s while moving, so receivers get about 6-7 positions a second
 * without one message more. Pure; no allocation per frame.
 */
final class GhostTrail
{
	/** Positions per update at most (0.6 s of them). */
	static final int MAX_SAMPLES = 4;
	/** A position this close (seconds) to the update's own, or to the update before, adds nothing. */
	private static final float MIN_GAP = 0.05f;
	private static final int CAPACITY = 8;

	private final float[] t = new float[CAPACITY];
	private final GhostState[] frames = new GhostState[CAPACITY];
	/** Ring: the newest is at next - 1. */
	private int count;
	private int next;
	private float lastRecord = Float.NEGATIVE_INFINITY;
	private float lastSent = Float.NEGATIVE_INFINITY;
	private final float[] eventTime = new float[GhostTrajectory.EVENT_BITS];

	/** Scratch for one encode, newest first. */
	private final GhostTrajectory out = new GhostTrajectory(MAX_SAMPLES);
	private final float[] eventAgo = new float[GhostTrajectory.EVENT_BITS];

	GhostTrail()
	{
		Arrays.fill(eventTime, Float.NaN);
	}

	/** One local frame at {@code now}: kept when a spacing has passed since the last kept one. */
	void record(GhostState f, float now)
	{
		// Seconds between recorded positions.
		if (now - lastRecord < 0.15f && count > 0)
			return;
		lastRecord = now;
		t[next] = now;
		frames[next] = f;
		next = (next + 1) % CAPACITY;
		count = Math.min(CAPACITY, count + 1);
	}

	/** This frame's EV_* {@code bits} happened at {@code now}. */
	void noteEvents(int bits, float now)
	{
		for (int bit = 0; bit < GhostTrajectory.EVENT_BITS && bits != 0; bit++)
		{
			if ((bits & (1 << bit)) != 0)
				eventTime[bit] = now;
		}
	}

	/**
	 * The timeline for update {@code m} going out at {@code now}: its events' times when {@code withEvents}, and
	 * at most {@code maxSamples} positions since the update before (same world and plane, no teleport), newest
	 * first.
	 */
	String encode(SkateGhostUpdate m, float now, int maxSamples, boolean withEvents)
	{
		int n = 0;
		float refX = m.x;
		float refY = m.y;
		int limit = Math.min(maxSamples, MAX_SAMPLES);
		for (int k = 0; k < count && n < limit; k++)
		{
			int i = Math.floorMod(next - 1 - k, CAPACITY);
			GhostState f = frames[i];
			float age = now - t[i];
			if (age < MIN_GAP)
				continue;
			// Positions older than this never go.
			// One step of the chain longer than this (units) is a teleport: the chain stops before it.
			if (age > 1.0f || t[i] <= lastSent + MIN_GAP || f.world != m.w || f.plane != m.p
				|| Math.hypot(f.x - refX, f.y - refY) > 1024f)
				break;
			out.ago[n] = age;
			out.x[n] = f.x;
			out.y[n] = f.y;
			out.h[n] = f.h;
			out.heading[n] = f.heading;
			out.state[n] = f.state;
			refX = f.x;
			refY = f.y;
			n++;
		}
		for (int bit = 0; bit < GhostTrajectory.EVENT_BITS; bit++)
		{
			float e = eventTime[bit];
			eventAgo[bit] = Float.isNaN(e) ? 0f : Math.max(0f, now - e);
		}
		out.timeMs = GhostTrajectory.timeMs(now);
		out.eventAgo = withEvents ? eventAgo : null;
		out.count = n;
		return out.encode(m.ev, m.x, m.y, m.h, m.hd);
	}

	/**
	 * Fits the timeline into {@code m} going out at {@code now}: as many positions as fit under
	 * {@link GhostWire#MAX_UPDATE_CHARS} with everything else the update has, then without positions, then without
	 * the event times; none at all when not even the send time fits (receivers then place it by its arrival).
	 */
	void fit(SkateGhostUpdate m, float now)
	{
		for (int n = MAX_SAMPLES; n >= -1; n--)
		{
			m.tj = n >= 0 ? encode(m, now, n, true) : encode(m, now, 0, false);
			if (GhostWire.jsonLength(m) <= GhostWire.MAX_UPDATE_CHARS)
				return;
		}
		m.tj = null;
	}

	/** An update went out at {@code now}: the next one carries only positions after it. */
	void sent(float now)
	{
		lastSent = now;
	}

	/** Sharing (re)starts: nothing recorded before carries over. */
	void clear()
	{
		count = 0;
		next = 0;
		lastRecord = Float.NEGATIVE_INFINITY;
		lastSent = Float.NEGATIVE_INFINITY;
		Arrays.fill(eventTime, Float.NaN);
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import java.util.Arrays;

/**
 * An update's timeline ({@link SkateGhostUpdate#tj}): the sender's send time, how long before it each of the
 * update's events happened, and up to {@link #MAX_SAMPLES} earlier positions of the skater (newest first), so
 * receivers can play the skater back on its own clock and between updates instead of guessing. Text, in
 * {@link GhostWire}'s alphabet:
 * <ol>
 * <li>a header character: bit 0 the event times are there, bits 1..3 the sample count, bits 4..5 the format
 * version (0; another version is ignored as a whole);</li>
 * <li>the send time: milliseconds of the sender's monotonic clock modulo 2^18 (about 262 s), 3 characters;</li>
 * <li>with bit 0: per set bit of the update's ev, lowest first, how long before the send time it happened, in
 * {@link #TICK}s;</li>
 * <li>per sample, newest first, each relative to the one before it (the first to the update's own x / y / h /
 * hd): time back in TICKs, x, y and h in whole units, heading in {@link #HEADING_UNIT}s the short way round,
 * and the state's code ({@link #STATE_CODES}).</li>
 * </ol>
 * Each delta is taken from the value the receiver will rebuild, so rounding never adds up along the chain. Pure.
 */
final class GhostTrajectory
{
	static final int TIME_DIGITS = 3;
	static final int TIME_MOD = 1 << (6 * TIME_DIGITS);
	/** Seconds per unit of event and sample times. */
	static final float TICK = 0.01f;
	/** Radians per unit of a sample's heading. */
	static final float HEADING_UNIT = 0.01f;
	/** EV_* bits that can carry a time (ev's low bits). */
	static final int EVENT_BITS = 16;
	/** A sample's state on the wire; never reordered (a code past the end reads as ROLLING). */
	static final SkaterState[] STATE_CODES = {SkaterState.ROLLING, SkaterState.AIRBORNE, SkaterState.BAILED,
		SkaterState.MANUAL, SkaterState.GRINDING};
	private static final int VERSION = 0;

	/** The sender's send time, ms modulo {@link #TIME_MOD}. */
	int timeMs;
	/** Per EV bit, seconds before the send time it happened; NaN when not sent (sending: null for none). */
	float[] eventAgo;
	int count;
	/** Per sample (newest first): seconds before the send time, absolute position, heading and state. */
	final float[] ago;
	final float[] x;
	final float[] y;
	final float[] h;
	final float[] heading;
	final SkaterState[] state;

	/** Room for {@code capacity} samples. */
	GhostTrajectory(int capacity)
	{
		ago = new float[capacity];
		x = new float[capacity];
		y = new float[capacity];
		h = new float[capacity];
		heading = new float[capacity];
		state = new SkaterState[capacity];
	}

	/** The send time on the wire for {@code now} seconds of the sender's clock. */
	static int timeMs(float now)
	{
		return (int) Math.floorMod(Math.round((double) now * 1000.0), (long) TIME_MOD);
	}

	/**
	 * The timeline text: the send time; with the event times (by EV bit), the times of {@code ev}'s
	 * events; then the first {@code count} samples (newest first) relative to the update's own position
	 * ({@code refX}, {@code refY}, {@code refH}, heading {@code refHd} / 1000).
	 */
	String encode(int ev, int refX, int refY, int refH, int refHd)
	{
		// max samples
		int n = Math.max(0, Math.min(7, count));
		StringBuilder sb = new StringBuilder(8 + n * 8);
		int header = (eventAgo != null ? 1 : 0) | n << 1 | VERSION << 4;
		sb.append(GhostWire.ALPHABET.charAt(header));
		GhostWire.putFixed(sb, Math.floorMod(timeMs, TIME_MOD), TIME_DIGITS);
		if (eventAgo != null)
		{
			for (int bit = 0; bit < EVENT_BITS; bit++)
			{
				if ((ev & (1 << bit)) != 0)
				{
					float a = eventAgo[bit];
					int ticks = Float.isNaN(a) ? 0 : Math.round(a / TICK);
					// Event times further back than this (a minute) are clamped.
					GhostWire.putUnsigned(sb, Math.max(0, Math.min(6000, ticks)));
				}
			}
		}
		int prevTicks = 0;
		int px = refX;
		int py = refY;
		int ph = refH;
		float pHeading = refHd / 1000f;
		for (int i = 0; i < n; i++)
		{
			int ticks = Math.max(prevTicks, Math.round(ago[i] / TICK));
			GhostWire.putUnsigned(sb, ticks - prevTicks);
			prevTicks = ticks;
			int ix = Math.round(x[i]);
			int iy = Math.round(y[i]);
			int ih = Math.round(h[i]);
			GhostWire.putSigned(sb, ix - px);
			GhostWire.putSigned(sb, iy - py);
			GhostWire.putSigned(sb, ih - ph);
			px = ix;
			py = iy;
			ph = ih;
			int dHeading = Math.round(Angles.wrap(heading[i] - pHeading) / HEADING_UNIT);
			GhostWire.putSigned(sb, dHeading);
			pHeading += dHeading * HEADING_UNIT;
			GhostWire.putUnsigned(sb, Math.max(0, Arrays.asList(STATE_CODES).indexOf(state[i])));
		}
		return sb.toString();
	}

	/**
	 * The timeline of an update with events {@code ev} at ({@code refX}, {@code refY}, {@code refH}, {@code refHd}),
	 * or null when {@code tj} is missing, junk or of another format version.
	 */
	static GhostTrajectory decode(String tj, int ev, int refX, int refY, int refH, int refHd)
	{
		if (tj == null || tj.isEmpty() || tj.length() > GhostWire.MAX_UPDATE_CHARS)
			return null;
		GhostWire.Reader r = new GhostWire.Reader(tj);
		int header = r.fixed(1);
		if (!r.ok() || header >> 4 != VERSION)
			return null;
		int n = (header >> 1) & 7;
		int time = r.fixed(TIME_DIGITS);
		float[] eventAgo = new float[EVENT_BITS];
		Arrays.fill(eventAgo, Float.NaN);
		if ((header & 1) != 0)
		{
			for (int bit = 0; bit < EVENT_BITS; bit++)
			{
				if ((ev & (1 << bit)) != 0)
					eventAgo[bit] = r.unsigned() * TICK;
			}
		}
		GhostTrajectory out = new GhostTrajectory(n);
		out.timeMs = time;
		out.eventAgo = eventAgo;
		out.count = n;
		int ticks = 0;
		int px = refX;
		int py = refY;
		int ph = refH;
		float pHeading = refHd / 1000f;
		for (int i = 0; i < n; i++)
		{
			ticks += r.unsigned();
			px += r.signed();
			py += r.signed();
			ph += r.signed();
			pHeading += r.signed() * HEADING_UNIT;
			int c = r.unsigned();
			out.ago[i] = ticks * TICK;
			out.x[i] = px;
			out.y[i] = py;
			out.h[i] = ph;
			out.heading[i] = Angles.wrap(pHeading);
			out.state[i] = c >= 0 && c < STATE_CODES.length ? STATE_CODES[c] : SkaterState.ROLLING;
		}
		return r.ok() ? out : null;
	}
}

package com.gielinorskate.party;

import java.util.Locale;

/** Pure gating and placement rules for drawing party ghosts. */
final class GhostVisibility
{
	/** The trick label is fully shown this long... */
	static final float LABEL_HOLD = 1f;

	private GhostVisibility()
	{
	}

	/**
	 * Ghosts are drawn only while this client is skating with "Show party skaters" on, outside PvP areas (the
	 * real character or the skater) and outside instances (two instances' coordinates can coincide).
	 */
	static boolean showGhosts(boolean localSkating, boolean showSetting, boolean localInPvpArea,
		boolean localInstanced)
	{
		return localSkating && showSetting && !localInPvpArea && !localInstanced;
	}

	/** The ghost is on this client's world and plane. */
	static boolean sameSpace(int localWorld, int localPlane, GhostState s)
	{
		return s != null && s.world == localWorld && s.plane == localPlane;
	}

	/** A local position lies inside a loaded scene of {@code sizeX} x {@code sizeY} tiles. */
	static boolean inScene(float localX, float localY, int sizeX, int sizeY)
	{
		return localX >= 0f && localY >= 0f && localX < sizeX * 128f && localY < sizeY * 128f;
	}

	/** Opacity of a trick label {@code age} seconds after the trick. */
	static float labelAlpha(float age)
	{
		if (age < LABEL_HOLD)
			return 1f;
		// ...then fades out, gone 1.5 s after the trick.
		return Math.max(0f, 1f - (age - LABEL_HOLD) / 0.5f);
	}

	/** A scene player's name and a party member's display name are the same player. */
	static boolean sameName(String playerName, String memberName)
	{
		return playerName != null && memberName != null && normalise(playerName).equals(normalise(memberName));
	}

	private static String normalise(String name)
	{
		return name.replace(' ', ' ').replace('_', ' ').replace('-', ' ').trim().toLowerCase(Locale.ROOT);
	}

	// ---- the per-ghost body budget: only the nearest MAX_FULL ghosts within FULL_RANGE get the full body (the
	// procedural pose on top of the OSRS animation, about 0.3 ms a frame for a 5,000-vertex character); the rest
	// play the animation only

	static final int MAX_FULL = 4;
	/** Local units: 32 tiles, about where a body's lean and crouch stop being readable. */
	static final float FULL_RANGE = 32 * 128f;

	/**
	 * A ghost's ground distance from the camera's focal point. The client's focal point keeps the scene's y in its
	 * Z ({@code getCameraFocalPointZ}); its Y is the height, so measuring against Y put every ghost ~50 tiles away.
	 */
	static float focusDistance(float x, float y, float focalX, float focalZ)
	{
		return (float) Math.hypot(x - focalX, y - focalZ);
	}

	/** The ghost {@code rank}-th nearest (0 the nearest) at {@code distance} gets the full body. */
	static boolean full(int rank, float distance)
	{
		return rank < MAX_FULL && distance <= FULL_RANGE;
	}
}

package com.gielinorskate.party;

import java.util.Arrays;

/**
 * Compact text for ghost updates: variable-length numbers in a 64-character alphabet that JSON (and Gson's HTML
 * escaping) leaves alone, and the exact length of an update's JSON as RuneLite's party client sends it, so the
 * sender can fit the optional timeline into the size bound. Pure.
 */
final class GhostWire
{
	/** Indices 0..31 end a number, 32..63 carry 5 more bits of it. None of them is escaped in JSON. */
	static final String ALPHABET = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ-_";
	/**
	 * The biggest update, in characters of JSON (GhostWireFormatTest): the busiest update without a timeline
	 * measures at most this already, and the timeline only goes in the room left under it.
	 */
	static final int MAX_UPDATE_CHARS = 284;
	private static final int[] VALUE = new int[128];

	static
	{
		Arrays.fill(VALUE, -1);
		for (int i = 0; i < ALPHABET.length(); i++)
			VALUE[ALPHABET.charAt(i)] = i;
	}

	private GhostWire()
	{
	}

	/** Appends {@code v} (0 or more): low 5-bit groups first, each but the last as a continuation character. */
	static void putUnsigned(StringBuilder sb, int v)
	{
		int u = Math.max(0, v);
		while (u >= 32)
		{
			sb.append(ALPHABET.charAt(32 + (u & 31)));
			u >>>= 5;
		}
		sb.append(ALPHABET.charAt(u));
	}

	/** Appends {@code v} zigzagged, so small negative numbers are short too. */
	static void putSigned(StringBuilder sb, int v)
	{
		putUnsigned(sb, (v << 1) ^ (v >> 31));
	}

	/** Appends the low {@code 6 * digits} bits of {@code v} in exactly {@code digits} characters, high first. */
	static void putFixed(StringBuilder sb, int v, int digits)
	{
		for (int i = digits - 1; i >= 0; i--)
			sb.append(ALPHABET.charAt((v >>> (6 * i)) & 63));
	}

	/** Reads what the put methods wrote; on junk it stops and says so ({@link #ok}), never throws. */
	static final class Reader
	{
		private final String s;
		private int pos;
		private boolean ok = true;

		Reader(String s)
		{
			this.s = s == null ? "" : s;
		}

		boolean ok()
		{
			return ok;
		}

		private int digit()
		{
			if (!ok || pos >= s.length())
			{
				ok = false;
				return 0;
			}
			char c = s.charAt(pos++);
			int v = c < 128 ? VALUE[c] : -1;
			if (v < 0)
			{
				ok = false;
				return 0;
			}
			return v;
		}

		int unsigned()
		{
			long v = 0;
			// A number never takes more characters than this (35 bits): anything longer is junk.
			for (int i = 0; i < 7; i++)
			{
				int d = digit();
				if (!ok)
					return 0;
				v |= (long) (d & 31) << (5 * i);
				if (d < 32)
				{
					if (v > Integer.MAX_VALUE)
					{
						ok = false;
						return 0;
					}
					return (int) v;
				}
			}
			ok = false;
			return 0;
		}

		int signed()
		{
			int u = unsigned();
			return (u >>> 1) ^ -(u & 1);
		}

		int fixed(int digits)
		{
			int v = 0;
			for (int i = 0; i < digits; i++)
				v = (v << 6) | digit();
			return ok ? v : 0;
		}
	}

	/** The JSON {@code "type":"SkateGhostUpdate"} RuneLite's party client puts first, and the braces. */
	private static final int FRAME = "{\"type\":\"SkateGhostUpdate\"}".length();

	/**
	 * Exactly how long {@code m}'s JSON is as RuneLite's party client writes it (Gson with HTML escaping, nulls left
	 * out, the member left out): GhostWireTest checks this against Gson itself.
	 */
	static int jsonLength(SkateGhostUpdate m)
	{
		return FRAME + num("w", m.w) + num("p", m.p) + num("x", m.x) + num("y", m.y) + num("h", m.h) + num("hd", m.hd)
			+ num("tw", m.tw) + num("vx", m.vx) + num("vy", m.vy) + num("vh", m.vh) + num("bf", m.bf)
			+ num("bw", m.bw) + num("ev", m.ev) + num("ft", m.ft) + num("seq", m.seq) + str("st", m.st)
			+ str("hold", m.hold) + str("tr", m.tr) + str("dk", m.dk) + str("gw", m.gw) + str("ob", m.ob) + str("tj", m.tj)
			+ num("bx", m.bx) + num("by", m.by) + num("bh", m.bh) + num("bd", m.bd) + num("cr", m.cr)
			+ num("kd", m.kd);
	}

	/** {@code ,"name":v}, or nothing for null. */
	private static int num(String name, Integer v)
	{
		return v == null ? 0 : 4 + name.length() + digits(v);
	}

	private static int str(String name, String v)
	{
		return v == null ? 0 : 6 + name.length() + v.chars().map(c -> escaped((char) c)).sum();
	}

	/** Characters Gson writes for {@code c} in a string. */
	private static int escaped(char c)
	{
		return "\"\\\t\b\n\r\f".indexOf(c) >= 0 ? 2 : c < 0x20 || "<>&='\u2028\u2029".indexOf(c) >= 0 ? 6 : 1;
	}

	static int digits(int v)
	{
		return Integer.toString(v).length();
	}
}

package com.gielinorskate.party;

import com.gielinorskate.GielinorSkateConfig;
import com.gielinorskate.physics.*;
import com.gielinorskate.progression.*;
import com.gielinorskate.render.*;
import com.gielinorskate.scoring.ScoreClock;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.*;
import java.util.function.LongConsumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.WorldView;
import net.runelite.api.events.PlayerDespawned;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PartyChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.events.UserPart;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.party.messages.PartyMessage;

/**
 * Shares the local skater with the player's RuneLite party and receives the party's skaters, only through
 * RuneLite's own {@link PartyService}. Party messages arrive on the party websocket's thread (WSClient posts
 * them to the event bus from OkHttp's listener), so every handler here hops to the client thread before
 * touching ghosts or the client. Registered on the event bus by the plugin.
 */
@Slf4j
@Singleton
public class PartyGhostService
{
	private final Client client;
	private final ClientThread clientThread;
	private final PartyService party;
	private final GielinorSkateConfig config;
	private final ScoreClock clock;
	private final GhostHub hub;
	private final GhostRenderer renderer;
	/** Client thread. */
	private final TurnRateMeter turnMeter = new TurnRateMeter();
	private final BodyFlipMeter bodyFlipMeter = new BodyFlipMeter();
	/** The board's state last frame (null on the board) and the walker's gait, for the at-once events. Client thread. */
	private BoardState lastOffBoard;
	private FootBody.Gait lastGait = FootBody.Gait.IDLE;
	/** The knockdown stage last shared (null when not knocked down): a new one goes out at once. */
	private KnockdownPose.Stage lastKnockStage;
	/** The latest skate frame was somewhere nothing is shared from (PvP area, instance; false when not skating). */
	@Getter
	private volatile boolean sendBlocked;
	/** The local skater's collision world as a ghost ground (absolute coordinates), and the scene it covers. */
	private GhostPredictor.Ground collisionGround;
	private int collisionBaseX;
	private int collisionBaseY;
	private int collisionPlane;

	@Inject
	PartyGhostService(Client client, ClientThread clientThread, PartyService party, GielinorSkateConfig config,
		ScoreClock clock)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.party = party;
		this.config = config;
		this.clock = clock;
		this.renderer = new GhostRenderer(client);
		this.hub = new GhostHub(new GhostHub.Link()
		{
			@Override
			public boolean inParty()
			{
				return party.isInParty();
			}

			@Override
			public void send(PartyMessage message)
			{
				try
				{
					party.send(message);
				}
				catch (RuntimeException e)
				{
					// a party hiccup must never end the skate session
					log.debug("Failed to send party ghost message", e);
				}
			}
		}, GhostHub.seqSeed(System.currentTimeMillis()));
	}

	/** Plugin start: sending may begin. */
	public void startUp()
	{
		hub.open();
	}

	/**
	 * Plugin shutdown, before the message types are unregistered: tells the party we stopped (from this thread,
	 * so it goes out while the types are still registered) and sends nothing afterwards.
	 */
	public void shutDown()
	{
		hub.close();
		clientThread.invoke(() ->
		{
			hub.clearGhosts();
			renderer.despawnAll();
		});
	}

	/**
	 * One local skate frame, client thread: shares the skater when allowed and draws the party's ghosts.
	 *
	 * @param stateBefore the skater's state before this frame's physics steps
	 * @param inPvpArea the real character or the skater is in a PvP area
	 * @param physicsDt seconds of physics steps this frame ran (0 when none)
	 */
	public void onSkateFrame(SkatePhysics physics, List<SkateEvent> events, List<TrickEvent> trickEvents,
		SkaterState stateBefore, boolean inPvpArea, float frameDt, float physicsDt)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
			return;
		Trick flip = physics.getFlipTrick();
		float turnRate = turnMeter.update(physics.getHeading(), flip, physics.getFlipProgress(), physicsDt);
		bodyFlipMeter.update(physics.getBodyFlipAngle(), physics.getState() == SkaterState.AIRBORNE, physicsDt);
		float[] v = GhostCodec.velocity(physics.getSpeed(), physics.getTravelHeading());
		lastGait = FootBody.Gait.IDLE;
		share(wv, new GhostState(client.getWorld(), wv.getPlane(), physics.getX() + wv.getBaseX() * 128f,
			physics.getY() + wv.getBaseY() * 128f, physics.getH(), physics.getHeading(), v[0], v[1],
			physics.getVerticalVelocity(), physics.getState(), sharedHold(physics), 0, flip,
			flip == null ? 0f : physics.getFlipProgress() * flip.duration, 0, turnRate, physics.getBodyFlipAngle(),
			bodyFlipMeter.rate(), null, 0f, 0f, 0f, 0f, physics.getPopCharge(), null, 0f),
			GhostCodec.eventBits(events, trickEvents, stateBefore, physics.getState())
			| (bodyFlipMeter.directionChanged() ? GhostCodec.EV_BODY_FLIP : 0), GhostCodec.eventTrick(trickEvents),
			inPvpArea, frameDt);
	}

	/**
	 * One frame knocked off the board, client thread: shares the body (its lowest point, facing and flight, the stage
	 * and the angle it comes to lie at; receivers time the tumble, lie-down and get-up themselves) and the board where
	 * it is, under the same rules and limits as skating, and draws the party's ghosts. A new stage goes out at once.
	 *
	 * @param k the knockdown as stepped (not blended between steps)
	 * @param vx the body's velocity, u/s
	 * @param events this frame's skate events (the bail on the frame it starts)
	 * @param stateBefore the skater's state before this frame's physics steps
	 * @param inPvpArea the real character or the skater is in a PvP area
	 * @param physicsDt seconds of steps this frame ran (0 when none)
	 */
	public void onKnockdownFrame(KnockdownPose k, float vx, float vy, boolean airborne, float lieAngle,
		List<SkateEvent> events, List<TrickEvent> trickEvents, SkaterState stateBefore, boolean inPvpArea,
		float frameDt, float physicsDt)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
			return;
		turnMeter.update(k.facing, null, 0f, physicsDt);
		bodyFlipMeter.update(0f, false, physicsDt);
		float baseX = wv.getBaseX() * 128f;
		float baseY = wv.getBaseY() * 128f;
		lastGait = FootBody.Gait.IDLE;
		// no vertical speed, angle or progress goes: the update stays small
		share(wv, new GhostState(client.getWorld(), wv.getPlane(), k.bodyX + baseX, k.bodyY + baseY, k.bodyH, k.facing,
			vx, vy, 0f, airborne ? SkaterState.AIRBORNE : SkaterState.BAILED, null, 0, null, 0f, 0, 0f, 0f, 0f,
			BoardState.DROPPED, k.boardX + baseX, k.boardY + baseY, k.boardH, k.boardYaw, 0f, k.stage, lieAngle),
			GhostCodec.eventBits(events, trickEvents, stateBefore, SkaterState.BAILED),
			GhostCodec.eventTrick(trickEvents), inPvpArea, frameDt);
	}

	/**
	 * One local frame on foot, client thread: shares the walker (feet, heading, velocity, in the air or not) and its
	 * board, carried or where it lies, under the same rules and limits as skating, and draws the party's ghosts.
	 *
	 * @param pose the walker and board as stepped (not blended between steps)
	 * @param vx the walker's velocity, u/s
	 * @param events this frame's walker events
	 * @param inPvpArea the real character or the walker is in a PvP area
	 * @param physicsDt seconds of walker steps this frame ran (0 when none)
	 */
	public void onFootFrame(OffBoardPose pose, float vx, float vy, List<FootEvent> events, boolean inPvpArea,
		float frameDt, float physicsDt)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null)
			return;
		float turnRate = turnMeter.update(pose.walkerHeading, null, 0f, physicsDt);
		bodyFlipMeter.update(0f, false, physicsDt);
		float baseX = wv.getBaseX() * 128f;
		float baseY = wv.getBaseY() * 128f;
		// starting or stopping goes out at once, so a ghost does not walk on past where the walker stopped
		FootBody.Gait gait = FootBody.gait(lastGait, pose.walkerSpeed, pose.airborne);
		int bits = GhostCodec.footEventBits(events) | (gait != lastGait ? GhostCodec.EV_GAIT : 0);
		lastGait = gait;
		share(wv, new GhostState(client.getWorld(), wv.getPlane(), pose.walkerX + baseX, pose.walkerY + baseY,
			pose.walkerH, pose.walkerHeading, vx, vy, pose.airborne ? pose.verticalSpeed : 0f,
			pose.airborne ? SkaterState.AIRBORNE : SkaterState.ROLLING, null, 0, null, 0f, 0, turnRate, 0f, 0f,
			pose.board, pose.boardX + baseX, pose.boardY + baseY, pose.boardH, pose.boardHeading, 0f, null, 0f), bits,
			null, inPvpArea, frameDt);
	}

	/**
	 * The hold sent to the party: the grab, manual or grind held, else a rolling grab (sent as a grab hold while
	 * ROLLING, the existing field, so the ghost crouches and grabs its board on the ground; it never makes a label,
	 * which needs a trick event).
	 */
	static Trick sharedHold(SkatePhysics physics)
	{
		Trick hold = physics.getActiveHold();
		return hold != null ? hold : physics.getGroundGrab();
	}

	/** Shares {@code frame} (local coordinates made absolute) under the rules and limits, and draws the ghosts. */
	private void share(WorldView wv, GhostState frame, int bits, Trick eventTrick, boolean inPvpArea, float frameDt)
	{
		float now = clock.now();
		// getting on or off (or dropping or picking up the board) and a new knockdown stage since the last frame go
		// out at once, with this frame
		bits |= GhostCodec.swapBits(lastOffBoard, frame.offBoard)
			| (frame.knockStage != null && frame.knockStage != lastKnockStage ? GhostCodec.EV_KNOCK : 0);
		lastOffBoard = frame.offBoard;
		lastKnockStage = frame.knockStage;
		// pruned first: whether anyone else is still skating decides how much we send
		hub.prune(now);
		// instance coordinates of two different instances can coincide, so nothing is shared from one
		sendBlocked = inPvpArea || wv.isInstance();
		hub.onLocalFrame(frame, bits, eventTrick, sendBlocked, config.shareWithParty(), now);
		boolean show = GhostVisibility.showGhosts(true, config.showPartySkaters(), inPvpArea, wv.isInstance());
		renderer.update(hub.ghosts(), this::memberName, show, now, frameDt, ground(wv.getPlane()));
	}

	/** The local board's designs, shown to party members. */
	public void setLocalLook(BoardLook look)
	{
		hub.setLocalLook(look);
	}

	/** Local skate mode ended, client thread. */
	public void onSkateEnd()
	{
		sendBlocked = false;
		collisionGround = null;
		turnMeter.reset();
		bodyFlipMeter.reset();
		lastOffBoard = null;
		lastGait = FootBody.Gait.IDLE;
		lastKnockStage = null;
		onGhostFailure();
	}

	/**
	 * A ghost frame threw, client thread: hide every ghost and tell the party we stopped sharing. Ghosts stay off
	 * for the rest of this skate session (the caller stops calling {@link #onSkateFrame}).
	 */
	public void onGhostFailure()
	{
		try
		{
			hub.onLocalSkateEnd(clock.now());
		}
		finally
		{
			renderer.despawnAll();
		}
	}

	/** World hop or logout: the ghosts' worlds and scenes no longer apply. Client thread. */
	public void onSceneLost()
	{
		hub.clearGhosts();
		renderer.despawnAll();
	}

	/** Client thread (PlayerDespawned is posted there). */
	@Subscribe
	public void onPlayerDespawned(PlayerDespawned e)
	{
		renderer.forgetPlayer(e.getPlayer());
	}

	/** Runs {@code action} on the client thread for a message from another member (our own are ignored). */
	private void fromOther(PartyMemberMessage m, LongConsumer action)
	{
		long id = m.getMemberId();
		if (id != localMemberId())
			clientThread.invoke(() -> action.accept(id));
	}

	@Subscribe
	public void onSkateGhostUpdate(SkateGhostUpdate m)
	{
		fromOther(m, id -> hub.onRemoteUpdate(id, m, clock.now(), ground(m.p)));
	}

	@Subscribe
	public void onSkateGhostStop(SkateGhostStop m)
	{
		fromOther(m, hub::onMemberLeft);
	}

	@Subscribe
	public void onUserPart(UserPart e)
	{
		long id = e.getMemberId();
		clientThread.invoke(() -> hub.onMemberLeft(id));
	}

	@Subscribe
	public void onPartyChanged(PartyChanged e)
	{
		clientThread.invoke(hub::clearGhosts);
	}

	/**
	 * The ground for a ghost on {@code plane}, or null when that is not this client's plane: the local skater's
	 * collision world (terrain plus platform and box tops, so a played-back ghost follows steps, stairs and ledges
	 * as the local skater would) while it covers this scene, else the scene's tile heights. Client thread.
	 */
	private GhostPredictor.Ground ground(int plane)
	{
		WorldView wv = client.getTopLevelWorldView();
		if (wv == null || wv.getPlane() != plane)
			return null;
		return collisionGround != null && collisionBaseX == wv.getBaseX() && collisionBaseY == wv.getBaseY()
			&& collisionPlane == plane ? collisionGround : GhostRenderer.sceneGround(client, wv);
	}

	/**
	 * The local skater's collision world for this skate session, built for the scene based at ({@code baseX},
	 * {@code baseY}) on {@code plane}, {@code sizeTiles} tiles across; null when there is none. Client thread.
	 */
	public void setCollisionWorld(CollisionWorld world, int baseX, int baseY, int plane, int sizeTiles)
	{
		collisionBaseX = baseX;
		collisionBaseY = baseY;
		collisionPlane = plane;
		collisionGround = world == null ? null : collisionGround(world, baseX, baseY, sizeTiles);
	}

	/** {@code world}'s ground at absolute coordinates; NaN off its grid (it would clamp to its edge). */
	static GhostPredictor.Ground collisionGround(CollisionWorld world, int baseX, int baseY, int sizeTiles)
	{
		return GhostRenderer.localGround(baseX, baseY, sizeTiles, sizeTiles, world::groundHeight);
	}

	/** This frame's ghost labels, for the overlay. */
	public List<GhostLabel> getLabels()
	{
		return renderer.labels();
	}

	/** This client's party member ID, or 0 when not in a party. */
	private long localMemberId()
	{
		PartyMember local = party.getLocalMember();
		return local == null ? 0L : local.getMemberId();
	}

	/** A party member's display name, or null. */
	public String memberName(long memberId)
	{
		PartyMember m = party.getMemberById(memberId);
		return m == null ? null : m.getDisplayName();
	}
}

package com.gielinorskate.party;

import net.runelite.client.party.messages.PartyMemberMessage;

/** The sender stopped skating (or stopped sharing): its party members remove its ghost. */
public class SkateGhostStop extends PartyMemberMessage
{
}

package com.gielinorskate.party;

import java.util.Objects;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * One skater state for the sender's RuneLite party, Gson-serialised by RuneLite's party client. Only skate-pose
 * data plus world and plane: no names, account or inventory data (the member is identified by the party itself).
 * Short field names keep the JSON small; see {@link GhostCodec} for the units.
 */
public class SkateGhostUpdate extends PartyMemberMessage
{
	/** World number. */
	int w;
	/** Plane. */
	int p;
	/** Absolute position: world tile * 128 + sub-tile (local units). */
	int x;
	int y;
	/** Up-positive height, local units. */
	int h;
	/** Heading * 1000 (radians, 0 = north, clockwise). */
	int hd;
	/** Heading turn rate * 1000 (rad/s, + = clockwise), so receivers carve smoothly between updates. */
	int tw;
	/** Velocity, local units per second (vh up-positive). */
	int vx;
	int vy;
	int vh;
	/**
	 * SkaterState name. Enums go by name, not ordinal, so members on plugin versions with more (or reordered)
	 * states or tricks never see the wrong one: an unknown name is ignored on decode.
	 */
	String st;
	/** Held trick (grab, manual, grind) name, or null (left out of the JSON). */
	String hold;
	/** Front / back flip angle of the whole skater * 1000 (radians, + = frontflip), and its rate * 1000. */
	int bf;
	int bw;
	/** Bitmask of GhostCodec.EV_* events since the previous update, 0 when none. */
	int ev;
	/** Flip in progress (or, on a TRICK event with no flip, the event's trick) name, or null. */
	String tr;
	/** Flip time into tr's nominal duration * 1000. */
	int ft;
	/** Increasing per sender, so stale or out-of-order updates are dropped. */
	int seq;
	/**
	 * The sender's deck design (progression.BoardDesign wire name: the id without DECK_; the old ladder's decks
	 * keep their old names, so older versions still draw them), or null (left out) for the default deck. In every
	 * update. Receivers check it against their own designs: an unknown name draws the default deck.
	 */
	String dk;
	/**
	 * The sender's grip and wheels designs as "GRIP.WHEELS" wire names, or null
	 * (left out). Not in every update:
	 * it rides along when the designs change and every few seconds after (GhostHub.LOOK_REFRESH_SECONDS), never
	 * with a trick name (tr) or a dropped board's place (bx...), so the biggest updates stay as small as before. Receivers keep the last ones they got
	 * (the defaults before any, and from older versions, which never send it). Not part of {@link #sameState}.
	 */
	String gw;
	/**
	 * Off the board: the board's state (BoardState name, CARRIED or DROPPED), and x / y / h / hd then describe the
	 * walker. Null (left out of the JSON) on the board: older plugin versions never send it and ignore it, so to
	 * them a walker is a skater standing on its board.
	 */
	String ob;
	/** A DROPPED board: absolute position, up-positive height and nose heading * 1000; null (left out) otherwise. */
	Integer bx;
	Integer by;
	Integer bh;
	Integer bd;

	/**
	 * Pop charge in ninths (1..9) while crouching to pop on the board, else null (left out): the ghost crouches with
	 * it. Older versions never send it and ignore it.
	 */
	Integer cr;
	/**
	 * Knocked off the board: the stage (1 tumbling, 2 lying, 3 getting up) plus 10 times the lying angle's code
	 * (GhostCodec.knockWire), with x / y / h / hd the body (its lowest point and facing), vx / vy its flight and ob /
	 * bx... the board DROPPED where it is; null (left out) otherwise. Older versions ignore it and draw a walker by
	 * its dropped board.
	 */
	Integer kd;

	/**
	 * The timeline (GhostTrajectory): the sender's send time, when each event in ev happened, and its last few
	 * positions, as compact text; null (left out) when there is no room for it: receivers then place the update by
	 * its arrival. Not part of {@link #sameState}.
	 */
	String tj;

	/** True when everything but seq and ev is equal: nothing changed worth a snapshot. */
	boolean sameState(SkateGhostUpdate o)
	{
		return o != null && w == o.w && p == o.p && x == o.x && y == o.y && h == o.h && hd == o.hd && tw == o.tw && vx == o.vx
			&& vy == o.vy && vh == o.vh && Objects.equals(st, o.st) && Objects.equals(hold, o.hold)
			&& Objects.equals(tr, o.tr) && ft == o.ft && bf == o.bf && bw == o.bw && Objects.equals(dk, o.dk)
			&& Objects.equals(ob, o.ob) && Objects.equals(bx, o.bx) && Objects.equals(by, o.by)
			&& Objects.equals(bh, o.bh) && Objects.equals(bd, o.bd)
			&& Objects.equals(cr, o.cr) && Objects.equals(kd, o.kd);
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.tricks.Trick;

/**
 * The local skater's heading turn rate for the party: what carving and air spins turn, measured over short
 * windows of physics time, so render frames without a physics step (or with two) don't make it jitter. The part of a flip's
 * own body turn (a bigspin's 180) is left out: receivers animate that from the trick table. Heading snaps (a
 * reset, a rail lock) are not turns. Pure.
 */
final class TurnRateMeter
{
	/**
	 * Faster than any real turn: a Shift tight carve is carveRate 2.6 * tightCarveMult 2.2 = 5.7 rad/s at
	 * standstill, and air spins are slower than that.
	 */
	static final float MAX_RATE = 10f;

	private float lastHeading = Float.NaN;
	private Trick lastTrick;
	private float lastBodySpin;
	private float turned;
	private float elapsed;
	private float rate;

	/**
	 * One render frame that ran {@code dt} seconds of physics steps (0 when it ran none: the heading can't have
	 * changed, and counting render time instead would make the rate jitter with the frame rate); returns the
	 * turn rate (rad/s, + = clockwise from above).
	 *
	 * @param flipTrick the flip turning the board now, or null
	 * @param flipProgress its progress 0..1
	 */
	float update(float heading, Trick flipTrick, float flipProgress, float dt)
	{
		float bodySpin = GhostCodec.bodySpin(flipTrick, flipProgress);
		float delta = Angles.wrap(heading - lastHeading) - (bodySpin - (flipTrick == lastTrick ? lastBodySpin : 0f));
		boolean first = Float.isNaN(lastHeading) || dt <= 0f;
		lastHeading = heading;
		lastTrick = flipTrick;
		lastBodySpin = bodySpin;
		if (first)
			return rate;
		// A frame's turn above MAX_RATE times this (or times the frame, when longer) is a snap: one long frame of
		// several physics steps can't be told from a jump below it.
		if (Math.abs(delta) > MAX_RATE * Math.max(dt, 0.05f))
		{
			turned = 0f;
			elapsed = 0f;
			rate = 0f;
			return rate;
		}
		turned += delta;
		elapsed += dt;
		// a little slack: five 0.02 s steps summed in float fall just short of 0.1
		// The rate is the mean over windows this long: five 0.02 s physics steps.
		if (elapsed >= 0.1f - 1e-4f)
		{
			rate = GhostCodec.clamp(turned / elapsed, -MAX_RATE, MAX_RATE);
			turned = 0f;
			elapsed = 0f;
		}
		return rate;
	}

	void reset()
	{
		lastHeading = Float.NaN;
		lastTrick = null;
		turned = 0f;
		elapsed = 0f;
		rate = 0f;
	}
}

package com.gielinorskate.physics;

/** Heading convention: 0 = north (+y), PI/2 = east (+x). */
public final class Angles
{
	public static final float PI = (float) Math.PI;
	public static final float TWO_PI = 2 * PI;

	private Angles()
	{
	}

	/** Wraps to (-PI, PI]. */
	public static float wrap(float a)
	{
		a = a % TWO_PI;
		if (a <= -PI)
			a += TWO_PI;
		else if (a > PI)
			a -= TWO_PI;
		return a;
	}

	/** Smallest absolute difference between two angles, in [0, PI]. */
	public static float absDiff(float a, float b)
	{
		return Math.abs(wrap(a - b));
	}

	/** Turns {@code from} toward {@code to} by at most {@code maxStep} radians the short way round, without overshooting. */
	static float turnToward(float from, float to, float maxStep)
	{
		float diff = wrap(to - from);
		return wrap(Math.abs(diff) <= maxStep ? to : from + Math.copySign(maxStep, diff));
	}

	/** Converts a heading to OSRS orientation units (0 = south, 512 = west, 1024 = north, 1536 = east). */
	public static int toJau(float heading)
	{
		return Math.floorMod(Math.round(1024 + heading * 1024 / PI), 2048);
	}

	public static float fromJau(int jau)
	{
		return wrap((jau - 1024) * PI / 1024);
	}
}

package com.gielinorskate.physics;

import com.gielinorskate.Text;

/** Why the skater bailed, shown under "Bailed" on the HUD (the text bundled under bail.NAME). */
public enum BailReason
{
	/** Landed with the board too far across the direction of travel. */
	SIDEWAYS,
	/** Touched down before a board flip was far enough along to catch. */
	FLIP_NOT_CAUGHT,
	/** Touched down more than 40 degrees off a whole front or back flip. */
	BODY_FLIP,
	/** A hard, head-on hit. */
	WALL;

	public final String text = Text.get("bail." + name());

	/**
	 * The reason a landing bails, or null when it does not: sideways first (the landing angle is checked
	 * before the flips), then an uncaught board flip, then an unfinished body flip.
	 */
	public static BailReason forLanding(boolean sideways, boolean flipUncaught, boolean bodyFlipOff)
	{
		return sideways ? SIDEWAYS : flipUncaught ? FLIP_NOT_CAUGHT : bodyFlipOff ? BODY_FLIP : null;
	}
}

package com.gielinorskate.physics;

import java.util.Random;
import lombok.Getter;

/**
 * The board flying off on its own after a bail: thrown with (most of) the skater's velocity, a random spin and
 * flip, bouncing off walls and the ground as a {@link ThrownBody}, then sliding to rest flat, wheels down. Always
 * at rest within {@link #REST_TIMEOUT} seconds. Units: local units, seconds, radians; yaw 0 = north, clockwise.
 */
public final class BoardBounce extends ThrownBody
{
	/** Landing faster than this (u/s down) bounces, keeping BOUNCE of it. */
	static final float BOUNCE_MIN = 150f;
	static final float BOUNCE = 0.4f;
	/** A bounce keeps this share of the speed along the ground and of the spins. */
	static final float BOUNCE_KEEP = 0.7f;
	/** However it bounced, it lies still this many seconds after the throw. */
	public static final float REST_TIMEOUT = 1.6f;


	/** Where the nose points (0 = north, clockwise). */
	@Getter
	private float yaw;
	private float yawRate;
	/** Flip about the long axis, raw (0 at rest). */
	@Getter
	private float roll;
	private float rollRate;
	/** End over end, raw (0 at rest). */
	@Getter
	private float pitch;
	private float pitchRate;
	private boolean resting;
	private float age;

	public BoardBounce(CollisionWorld world, float gravity)
	{
		// radius 10; slides at 2500 u/s^2 on the ground; a bounce off a wall keeps half the speed into it
		super(world, gravity, 10f, 2500f, 0.5f);
	}

	/** Throws the board from (x, y, h) with the skater's velocity (vx, vy), nose along {@code heading}. */
	public void start(float x, float y, float h, float vx, float vy, float heading, Random random)
	{
		this.x = finite(x);
		this.y = finite(y);
		this.h = finite(h);
		float sx = finite(vx);
		float sy = finite(vy);
		float s = (float) Math.hypot(sx, sy);
		float scale = s > MAX_SPEED ? MAX_SPEED / s : 1f;
		// a little sideways, so the board and the body part ways; it flies off with 0.7 of the skater's velocity
		float side = (random.nextFloat() - 0.5f) * 0.3f;
		this.vx = (sx + sy * side) * scale * 0.7f;
		this.vy = (sy - sx * side) * scale * 0.7f;
		// pops 280 off the ground plus up to 200; spins 3 rad/s about the vertical plus up to 6, flips 10 about the
		// long axis plus up to 10 and tumbles end over end 1 plus up to 3 (small), each either way
		vh = 280f + 200f * random.nextFloat();
		yaw = Angles.wrap(finite(heading));
		yawRate = sign(random) * (3f + 6f * random.nextFloat());
		roll = 0f;
		rollRate = sign(random) * (10f + 10f * random.nextFloat());
		pitch = 0f;
		pitchRate = sign(random) * (1f + 3f * random.nextFloat());
		grounded = false;
		resting = false;
		age = 0f;
	}

	private static float sign(Random random)
	{
		return random.nextBoolean() ? 1f : -1f;
	}

	public void step(float dt)
	{
		if (resting || !(dt > 0f))
			return;
		age += dt;
		if (age >= REST_TIMEOUT)
		{
			restNow();
			return;
		}
		stepMotion(dt);

		yaw = Angles.wrap(yaw + yawRate * dt);
		if (!grounded)
		{
			roll += rollRate * dt;
			pitch += pitchRate * dt;
			return;
		}
		// flat on the ground, wheels down: the nearest whole turn of the flip; settles at 15/s
		float k = 1f - (float) Math.exp(-15f * dt);
		yawRate -= yawRate * k;
		float flat = Math.round(roll / Angles.TWO_PI) * Angles.TWO_PI;
		roll += (flat - roll) * k;
		float level = Math.round(pitch / Angles.TWO_PI) * Angles.TWO_PI;
		pitch += (level - pitch) * k;
		if (vx == 0f && vy == 0f && Math.abs(flat - roll) < 0.01f && Math.abs(level - pitch) < 0.01f)
			restNow();
	}

	@Override
	void land()
	{
		if (vh < -BOUNCE_MIN)
		{
			vh = -vh * BOUNCE;
			vx *= BOUNCE_KEEP;
			vy *= BOUNCE_KEEP;
			yawRate *= BOUNCE_KEEP;
			rollRate *= 0.5f;
			pitchRate *= 0.5f;
		}
		else
		{
			vh = 0f;
			grounded = true;
		}
	}

	@Override
	void bouncedBack()
	{
		yawRate = -yawRate;
	}

	/** Puts the board down flat where it is, at once (the skater is standing up and needs to know where it lies). */
	public void restNow()
	{
		h = finite(world.groundHeight(x, y));
		vx = 0f;
		vy = 0f;
		vh = 0f;
		roll = 0f;
		pitch = 0f;
		yawRate = 0f;
		rollRate = 0f;
		pitchRate = 0f;
		grounded = true;
		resting = true;
	}

	public boolean isAtRest()
	{
		return resting;
	}
}

