package com.gielinorskate.progression;

import java.util.Arrays;
import java.util.List;

/**
 * The logged-in account's Skate XP, kept in its RuneScape profile config. Gains are saved after a quiet spell
 * ({@link #SAVE_DELAY_SECONDS}), at least every {@link #MAX_UNSAVED_SECONDS} during a long streak, and at once
 * on {@link #flush()} (skating stops, logout, account change, plugin stop): never on every frame. Values go back
 * to the profile they were loaded from, so a gain is never written into the next account's profile. Pure apart
 * from its {@link ProfileStore}; client thread.
 */
public final class Progression
{
	/** Saved key of the XP (profile config); never renamed. */
	static final String XP_KEY = "skateXp";
	/**
	 * Saved keys of the chosen designs' ids (profile config) by part: grip, deck, wheels; never renamed. skateDeck
	 * held the old ladder deck's name, which is still a deck design id.
	 */
	static final List<String> DESIGN_KEYS = Arrays.asList("skateGrip", "skateDeck", "skateWheels");
	/** Seconds after the latest gain before it is saved. */
	public static final float SAVE_DELAY_SECONDS = 5f;
	/** Seconds a gain may stay unsaved while new ones keep coming. */
	public static final float MAX_UNSAVED_SECONDS = 30f;

	private final ProfileStore store;
	private final BoardDesigns designs = BoardDesigns.bundled();
	/** The profile the values came from (and are saved to); null when none. */
	private String profile;
	private int xp;
	/** The chosen designs' saved ids by part (null before one was chosen). */
	private final String[] designIds = new String[DesignPart.values().length];
	private boolean dirty;
	private float firstUnsaved;
	private float lastGain;

	public Progression(ProfileStore store)
	{
		this.store = store;
	}

	/** Saves what is pending for the previous account, then loads the current one's. */
	public void load()
	{
		flush();
		profile = store.profile();
		xp = profile == null ? 0 : SkateLevels.parseXp(store.get(profile, XP_KEY));
		for (DesignPart p : DesignPart.values())
			designIds[p.ordinal()] = profile == null ? null : store.get(profile, DESIGN_KEYS.get(p.ordinal()));
		dirty = false;
	}

	/** The account the values belong to, or null. */
	public String profile()
	{
		return profile;
	}

	public int xp()
	{
		return xp;
	}

	public int level()
	{
		return SkateLevels.level(xp);
	}

	/**
	 * Adds XP gained at score-clock time {@code now}.
	 *
	 * @return the level-up it caused (several levels at once give one, with the final level), or null
	 */
	public LevelUp addXp(int amount, float now)
	{
		int before = level();
		int after = SkateLevels.add(xp, amount);
		if (after == xp)
			return null;
		xp = after;
		if (!dirty)
		{
			dirty = true;
			firstUnsaved = now;
		}
		lastGain = now;
		return level() > before ? new LevelUp(before, level()) : null;
	}

	/**
	 * The board's designs in use: each part's chosen design, or its default when none was chosen, the saved id is
	 * unknown (an old deck name no longer on the ladder, CLASSIC included) or it is locked at the current level.
	 */
	public BoardLook look()
	{
		BoardDesign[] d = new BoardDesign[designIds.length];
		for (DesignPart p : DesignPart.values())
			d[p.ordinal()] = designs.usable(p, designIds[p.ordinal()], level());
		return new BoardLook(d[0], d[1], d[2]);
	}

	/** Chooses a design for its part (saved at once); false, and nothing changes, when it is still locked. */
	public boolean select(BoardDesign design)
	{
		if (design == null || designs.byId(design.id) == null || !design.isUnlocked(level()))
			return false;
		designIds[design.part.ordinal()] = design.id;
		if (profile != null)
			store.set(profile, DESIGN_KEYS.get(design.part.ordinal()), design.id);
		return true;
	}

	/** Saves pending gains once they have been quiet long enough (or waited too long). Call now and then. */
	public void tick(float now)
	{
		if (dirty && (now - lastGain >= SAVE_DELAY_SECONDS || now - firstUnsaved >= MAX_UNSAVED_SECONDS))
			flush();
	}

	/** Saves pending gains now. */
	public void flush()
	{
		if (dirty && profile != null)
			store.set(profile, XP_KEY, Integer.toString(xp));
		dirty = false;
	}
}

package com.gielinorskate.progression;

import com.gielinorskate.*;
import com.gielinorskate.feedback.HudAnim;
import com.gielinorskate.feedback.SkateFeedback;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.scoring.ScoreClock;
import com.gielinorskate.ui.ProgressState;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.*;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.RequiredArgsConstructor;
import net.runelite.client.Notifier;
import net.runelite.client.config.ConfigManager;

/**
 * Skate progression for the logged-in account: XP from landed combos, level-ups (chat line in the game's wording,
 * graphic and bells through {@link SkateFeedback}, a RuneLite notification, a HUD banner every ten levels), the
 * board designs, the daily goals, and the side panel's "Skating" section. Client thread.
 */
@Singleton
public class ProgressionService
{
	@Inject
	private SkateChat skateChat;
	private final Notifier notifier;
	private final GielinorSkateConfig config;
	private final SkateFeedback feedback;
	private final ScoreClock clock;
	private final Progression progression;
	private final DailyGoals daily;
	private final Random random = new Random();
	/** The goal last completed (for the HUD's "Goal complete" line), and when. */
	private String goalFlashText;
	private float goalFlashAt = Float.NEGATIVE_INFINITY;

	/** The level banner showing (every ten levels), and when it started. */
	private String bannerText;
	private float bannerAt = Float.NEGATIVE_INFINITY;

	/** Who gets the panel's progress section when it changes (the panel, through invokeLater), and what it got last. */
	private Consumer<ProgressState> listener;
	private ProgressState lastState;
	/** Who recolours the board when the designs in use change (the session). */
	private Consumer<BoardLook> lookListener;

	@Inject
	ProgressionService(ConfigManager configManager, Notifier notifier, GielinorSkateConfig config,
		SkateFeedback feedback, ScoreClock clock)
	{
		this.notifier = notifier;
		this.config = config;
		this.feedback = feedback;
		this.clock = clock;
		ProfileStore store = new ConfigProfileStore(configManager);
		progression = new Progression(store);
		daily = new DailyGoals(store);
	}

	/** The current UTC day: the daily goals turn over at UTC midnight. */
	private static LocalDate today()
	{
		return LocalDate.now(ZoneOffset.UTC);
	}

	/** True for the per-account progress keys saved in the RuneScape profile (they are not settings). */
	public static boolean isProgressKey(String key)
	{
		return Progression.XP_KEY.equals(key) || Progression.DESIGN_KEYS.contains(key) || DailyGoals.DAY_KEY.equals(key)
			|| DailyGoals.STATE_KEY.equals(key);
	}

	/**
	 * The account (RuneScape profile) changed or the plugin started: save the old one's XP, load the new one's XP
	 * and its goals for the day.
	 */
	public void load()
	{
		BoardLook before = progression.look();
		progression.load();
		daily.load(today(), random);
		goalFlashText = null;
		lookMaybeChanged(before);
	}

	/** Saves pending XP when it's due (debounced). Called every game tick. */
	public void tick()
	{
		progression.tick(clock.now());
	}

	/** Saves pending XP now (skating stopped, logout, plugin stop). */
	public void flush()
	{
		progression.flush();
	}

	/** Skating started: the day's goals carry on (new ones only once the UTC day has turned). */
	public void startSession()
	{
		daily.startSession(today(), random);
		goalFlashText = null;
		publish();
	}

	/** A combo landed: its XP, then any session goals it completed (each worth bonus XP). */
	public void onComboLanded(ComboScorer.Summary combo)
	{
		addXp(SkateLevels.xpForCombo(combo.value));
		for (SessionGoals.Goal g : daily.onLanded(combo, today(), random))
		{
			float now = clock.now();
			skateChat.send(Text.get("ps.daily", String.format("%,d", SessionGoals.BONUS_XP), g.type.text));
			feedback.onGoalComplete(now);
			goalFlashText = "Goal complete: " + g.type.text;
			goalFlashAt = now;
			addXp(SessionGoals.BONUS_XP);
		}
		publish();
	}

	/** The HUD's goal line ("Goal: Land 5 different flips 3/5"), or null when hidden or there are none. */
	public String getGoalLine()
	{
		SessionGoals goals = daily.goals();
		if (!config.showSessionGoals() || goals.goals().isEmpty())
			return null;
		SessionGoals.Goal g = goals.current();
		return isGoalFlashing() ? goalFlashText : g == null ? "All daily goals done!"
			: "Goal: " + g.type.text + " (" + g.progressText() + ")";
	}

	/** True while the goal line names a just-completed goal (drawn highlighted). */
	public boolean isGoalFlashing()
	{
		return goalFlashText != null && HudAnim.goalFlashAlpha(clock.now() - goalFlashAt) > 0f;
	}

	/** Adds Skate XP, with the level-up fanfare when a level is reached. */
	private void addXp(int amount)
	{
		float now = clock.now();
		BoardLook lookBefore = progression.look();
		LevelUp up = progression.addXp(amount, now);
		if (up != null)
		{
			String message = up.message();
			skateChat.send(message);
			feedback.onLevelUp(up.to, now);
			// follows the player's RuneLite notification settings (and this setting's own overrides)
			notifier.notify(config.levelUpNotification(), message);
			if (up.banner() != null)
			{
				bannerText = up.banner();
				bannerAt = now;
			}
			// the chat drops a null line
			skateChat.send(unlockMessage(BoardDesigns.bundled().unlockedBetween(up.from, up.to)));
		}
		lookMaybeChanged(lookBefore);
	}

	/**
	 * "New board design unlocked: Rune deck. Pick it in the RuneSkate side panel.", or for several "New board designs
	 * unlocked: Bandos, Armadyl, Guthix, Zamorak and Saradomin grip, deck and wheels. Pick them ...": designs of one
	 * name and level go together, and names of one level with the same parts too. Null for none.
	 */
	static String unlockMessage(List<BoardDesign> unlocked)
	{
		if (unlocked.isEmpty())
			return null;
		// each name (keyed "level:name") with its parts, in order of first appearance
		Map<String, EnumSet<DesignPart>> parts = new LinkedHashMap<>();
		for (BoardDesign d : unlocked)
			parts.computeIfAbsent(d.unlock + ":" + d.name, k -> EnumSet.noneOf(DesignPart.class)).add(d.part);
		// names of one level and the same parts share one phrase, keyed "level:their parts' words"
		Map<String, List<String>> groups = new LinkedHashMap<>();
		parts.forEach((key, set) -> groups.computeIfAbsent(key.substring(0, key.indexOf(':')) + ":"
			+ andList(set.stream().map(p -> p.key).collect(Collectors.toList())), k -> new ArrayList<>())
			.add(key.substring(key.indexOf(':') + 1)));
		return Text.get("ps.unlock." + (unlocked.size() == 1), groups.entrySet().stream()
			.map(g -> andList(g.getValue()) + " " + g.getKey().substring(g.getKey().indexOf(':') + 1))
			.collect(Collectors.joining("; ")));
	}

	/** "a", "a and b", "a, b and c". */
	static String andList(List<String> items)
	{
		int last = items.size() - 1;
		return last < 1 ? String.join("", items) : String.join(", ", items.subList(0, last)) + " and " + items.get(last);
	}

	/** The board's designs in use: the chosen ones, or each part's default while none is chosen (or it is locked). */
	public BoardLook look()
	{
		return progression.look();
	}

	/** The panel picked a design: saved for this account and put on the board (a locked one is ignored). */
	public void selectDesign(BoardDesign design)
	{
		BoardLook before = progression.look();
		progression.select(design);
		lookMaybeChanged(before);
	}

	/** Who recolours the board when the designs in use change. */
	public void setLookListener(Consumer<BoardLook> listener)
	{
		lookListener = listener;
	}

	/** Tells the look listener when the look differs from {@code before}, and the panel when its state changed. */
	private void lookMaybeChanged(BoardLook before)
	{
		BoardLook now = progression.look();
		Consumer<BoardLook> l = lookListener;
		if (!now.equals(before) && l != null)
			l.accept(now);
		publish();
	}

	/** The loaded account's Skate XP (0 when none is loaded). */
	public int xp()
	{
		return progression.xp();
	}

	/** The RuneScape profile the XP was loaded from, or null. */
	public String profile()
	{
		return progression.profile();
	}

	/** The level banner ("Skating level 50!") if one is showing, else null. */
	public String getBannerText()
	{
		return getBannerAge() < HudAnim.BANNER_SECONDS ? bannerText : null;
	}

	/** Seconds since the banner started. */
	public float getBannerAge()
	{
		return clock.now() - bannerAt;
	}

	/** Who gets the panel's progress section when it changes (the panel, through invokeLater). */
	public void setListener(Consumer<ProgressState> listener)
	{
		this.listener = listener;
		lastState = null;
	}

	/** Sends the panel its progress state if it changed. */
	private void publish()
	{
		int xp = progression.xp();
		ProgressState s = new ProgressState(progression.level(), xp, SkateLevels.xpToNext(xp), SkateLevels.progress(xp),
			progression.look(), daily.goals().goals().stream().map(g -> new ProgressState.GoalView(g.type.text,
			g.progressText(), g.isDone())).collect(Collectors.toList()));
		Consumer<ProgressState> l = listener;
		if (l != null && !s.equals(lastState))
		{
			lastState = s;
			l.accept(s);
		}
	}

	/** The plugin's config group in the logged-in account's RuneScape profile. */
	@RequiredArgsConstructor
	public static final class ConfigProfileStore implements ProfileStore
	{
		private final ConfigManager configManager;

		@Override
		public String profile()
		{
			return configManager.getRSProfileKey();
		}

		@Override
		public String get(String profile, String key)
		{
			return configManager.getConfiguration(GielinorSkateConfig.GROUP, profile, key);
		}

		@Override
		public void set(String profile, String key, String value)
		{
			if (profile.equals(configManager.getRSProfileKey()))
				configManager.setRSProfileConfiguration(GielinorSkateConfig.GROUP, key, value);
			else
				// the account changed before the save: into the profile the value was loaded from
				configManager.setConfiguration(GielinorSkateConfig.GROUP, profile, key, value);
		}
	}
}

package com.gielinorskate.progression;

import com.gielinorskate.Text;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import com.gielinorskate.ui.TrickGuide;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;

/**
 * Three goals picked at random from a pool ("Land 5 different flips"), counted from the combos that land; they
 * last the UTC day per account ({@link DailyGoals}). Completing one is worth {@link #BONUS_XP} Skating XP. Pure.
 */
public final class SessionGoals
{
	public static final int GOALS_PER_SESSION = 3;
	public static final int BONUS_XP = 2_000;

	/** The pool. Each goal counts something from landed combos up to its target (wording: sg. in the bundled text). */
	public enum Type
	{
		DIFFERENT_FLIPS(5),
		GRIND_SECONDS(10),
		BIG_COMBO(20_000),
		BODY_FLIP(1),
		SHIFT_TRICKS(3),
		TOTAL_POINTS(50_000),
		MANUAL_SECONDS(5),
		SPIN_360(1),
		CLEAN_LANDINGS(5),
		MULTIPLIER(5),
		DIFFERENT_GRINDS(3),
		GRABS(3);

		public final String text;
		public final int target;

		Type(int target)
		{
			this.target = target;
			text = Text.get("sg." + name());
		}
	}

	/** One goal of this session and how far it has got (uncapped, as saved by {@link DailyGoals}). */
	public static final class Goal
	{
		public final Type type;
		float progress;
		boolean done;
		/** Tricks already counted, for the "different" goals. */
		final Set<Trick> seen = EnumSet.noneOf(Trick.class);

		Goal(Type type, float progress, boolean done, Set<Trick> seen)
		{
			this.type = type;
			this.progress = progress;
			this.done = done;
			this.seen.addAll(seen);
		}

		public boolean isDone()
		{
			return done;
		}

		/** "3/5", "4.2/10 s", "12,300/20,000"; "Done" once complete. */
		public String progressText()
		{
			if (done)
				return "Done";
			float p = Math.min(progress, type.target);
			switch (type)
			{
				case GRIND_SECONDS:
				case MANUAL_SECONDS:
					return String.format("%.1f/%d s", Math.floor(p * 10f) / 10f, type.target);
				case BIG_COMBO:
				case TOTAL_POINTS:
					return String.format("%,d/%,d", (int) p, type.target);
				default:
					return (int) p + "/" + type.target;
			}
		}
	}

	/** Shift tricks (Shift held as the flick fires), as the trick guide groups them. */
	static final Set<Trick> SHIFT = Arrays.stream(Trick.values())
		.filter(t -> TrickGuide.entry(t).group == TrickGuide.Group.SHIFT).collect(Collectors.toSet());

	private final List<Goal> goals = new ArrayList<>(GOALS_PER_SESSION);

	/** A new session: three different goals from the pool. */
	public void start(Random random)
	{
		List<Type> pool = new ArrayList<>(Arrays.asList(Type.values()));
		Collections.shuffle(pool, random);
		start(pool.subList(0, GOALS_PER_SESSION));
	}

	/** A new session with these goals. */
	public void start(List<Type> types)
	{
		restore(types.stream().map(t -> new Goal(t, 0f, false, Collections.emptySet())).collect(Collectors.toList()));
	}

	/** Goals restored from saved state. */
	void restore(List<Goal> restored)
	{
		goals.clear();
		goals.addAll(restored);
	}

	public List<Goal> goals()
	{
		return Collections.unmodifiableList(goals);
	}

	/** The first goal not yet done, or null when all are (or there are none). */
	public Goal current()
	{
		return goals.stream().filter(g -> !g.done).findFirst().orElse(null);
	}

	/** Counts a landed combo; returns the goals it completed. */
	public List<Goal> onLanded(ComboScorer.Summary combo)
	{
		List<Goal> completed = new ArrayList<>(1);
		for (Goal g : goals)
		{
			if (!g.done)
			{
				count(g, combo);
				if (g.progress >= g.type.target)
				{
					g.done = true;
					completed.add(g);
				}
			}
		}
		return completed;
	}

	private static void count(Goal g, ComboScorer.Summary combo)
	{
		switch (g.type)
		{
			case DIFFERENT_FLIPS:
				g.progress = seen(g, combo, t -> t.kind == TrickKind.FLIP && t.bodyFlipTurns == 0f);
				break;
			case DIFFERENT_GRINDS:
				g.progress = seen(g, combo, t -> t.kind == TrickKind.GRIND);
				break;
			case GRIND_SECONDS:
				g.progress += combo.grindSeconds;
				break;
			case MANUAL_SECONDS:
				g.progress += combo.manualSeconds;
				break;
			case BIG_COMBO:
				g.progress = Math.max(g.progress, combo.value);
				break;
			case TOTAL_POINTS:
				g.progress += combo.value;
				break;
			case BODY_FLIP:
				g.progress += combo.tricks.stream().filter(t -> t.bodyFlipTurns != 0f).count();
				break;
			case SHIFT_TRICKS:
				g.progress += combo.tricks.stream().filter(SHIFT::contains).count();
				break;
			case GRABS:
				g.progress += combo.tricks.stream().filter(t -> t.kind == TrickKind.GRAB).count();
				break;
			case SPIN_360:
				g.progress = combo.maxSpinHalfTurns >= 2 ? 1 : g.progress;
				break;
			case CLEAN_LANDINGS:
				g.progress += combo.clean ? 1 : 0;
				break;
			default:
				g.progress = Math.max(g.progress, combo.multiplier);
				break;
		}
	}

	/** Adds the combo's tricks passing {@code test} to the goal's seen ones; how many it has seen. */
	private static int seen(Goal g, ComboScorer.Summary combo, Predicate<Trick> test)
	{
		combo.tricks.stream().filter(test).forEach(g.seen::add);
		return g.seen.size();
	}
}

package com.gielinorskate.progression;

import net.runelite.api.Experience;

/** Skate XP: earned from landed combos, levelled on the game's own XP table (1 to 99, no virtual levels). Pure. */
public final class SkateLevels
{
	/** XP for a landed combo is its value divided by this (a 20k combo is 2,000 XP). Tuning constant. */
	public static final int COMBO_VALUE_PER_XP = 10;
	public static final int MAX_LEVEL = 99;
	/** As the game's skills. */
	public static final int MAX_XP = 200_000_000;

	/** XP for landing a combo worth {@code value}. */
	public static int xpForCombo(int value)
	{
		return Math.max(0, value / COMBO_VALUE_PER_XP);
	}

	public static int level(int xp)
	{
		return Math.min(MAX_LEVEL, Experience.getLevelForXp(Math.max(0, Math.min(MAX_XP, xp))));
	}

	/** XP at which {@code level} starts. */
	public static int xpForLevel(int level)
	{
		return level <= 1 ? 0 : Experience.getXpForLevel(Math.min(MAX_LEVEL, level));
	}

	/** XP still needed for the next level; 0 at 99. */
	public static int xpToNext(int xp)
	{
		int level = level(xp);
		return level >= MAX_LEVEL ? 0 : xpForLevel(level + 1) - xp;
	}

	/** How far through the current level, 0..1 (1 at 99). */
	public static float progress(int xp)
	{
		int level = level(xp);
		if (level >= MAX_LEVEL)
			return 1f;
		int start = xpForLevel(level);
		return (xp - start) / (float) (xpForLevel(level + 1) - start);
	}

	/** {@code xp} plus a gain, clamped to 0..{@link #MAX_XP}; negative gains are ignored. */
	public static int add(int xp, int gain)
	{
		return (int) Math.min(MAX_XP, (long) xp + Math.max(0, gain));
	}

	/** Saved XP text to a value; anything missing, unreadable or negative is 0. */
	public static int parseXp(String saved)
	{
		try
		{
			return (int) Math.max(0, Math.min(MAX_XP, Long.parseLong(saved.trim())));
		}
		catch (RuntimeException e)
		{
			return 0;
		}
	}
}

package com.gielinorskate.render;

import java.util.Arrays;

/**
 * Plays a classic (frame-based) OSRS animation on our own copy of a model: which frame is showing after each
 * render frame at some multiple of the game's pace, looping, or the frame a progress through it falls on. Frame
 * lengths are client ticks (20 ms). Pure; no allocation.
 */
public final class AnimClock
{
	/** Client ticks per second. */
	static final float TICKS_PER_SECOND = 50f;

	int frame;
	/** Client ticks owed to the animation that did not yet make a whole frame. */
	float ticks;

	/** Back to the first frame. */
	public void reset()
	{
		frame = 0;
		ticks = 0f;
	}

	/**
	 * Advances {@code dt} seconds at {@code rate} times the game's pace, looping; returns the frame now, or -1 when
	 * there are no frames.
	 */
	public int loop(int[] lengths, float rate, float dt)
	{
		if (lengths == null || lengths.length == 0)
		{
			reset();
			return -1;
		}
		if (frame >= lengths.length)
			reset();
		if (dt > 0f && rate > 0f)
			ticks += rate * dt * TICKS_PER_SECOND;
		run(lengths);
		return frame;
	}

	/**
	 * Steps on through the whole frames the ticks owed make, at most one cycle: a long hitch skips at most one cycle
	 * and forgets the rest. True if any frame was stepped.
	 */
	boolean run(int[] lengths)
	{
		boolean moved = false;
		for (int i = 0; i < lengths.length && ticks >= Math.max(1, lengths[frame]); i++)
		{
			ticks -= Math.max(1, lengths[frame]);
			frame = (frame + 1) % lengths.length;
			moved = true;
		}
		if (ticks >= Math.max(1, lengths[frame]))
			ticks = 0f;
		return moved;
	}

	/**
	 * Frame lengths for a Maya (skeletal) animation, whose "frame" is the client tick within its {@code duration}:
	 * one tick each, so {@link #loop} and {@link #seek} give the tick. Allocated once per animation, not per frame.
	 */
	public static int[] tickFrames(int duration)
	{
		int[] t = new int[Math.max(0, duration)];
		Arrays.fill(t, 1);
		return t;
	}

	/** The frame {@code progress} (0..1) of the way through; -1 when there are no frames. */
	public int seek(int[] lengths, float progress)
	{
		int f = frameAt(progress, lengths);
		frame = Math.max(0, f);
		ticks = 0f;
		return f;
	}

	/**
	 * The frame {@code progress} (0..1, clamped) of the way through an animation with these frame lengths (client
	 * ticks; zero counts as one), or -1 when there is nothing to pick: plays an animation at a chosen pace by picking
	 * its frame from how far through a window of our own we are (the get-up after a knockdown is squeezed into its
	 * time, whatever the animation's own length).
	 */
	public static int frameAt(float progress, int[] frameLengths)
	{
		if (frameLengths == null || frameLengths.length == 0 || Float.isNaN(progress))
			return -1;
		long total = 0;
		for (int len : frameLengths)
			total += Math.max(1, len);
		double at = Math.max(0f, Math.min(1f, progress)) * total;
		for (int i = 0; i < frameLengths.length; i++)
		{
			at -= Math.max(1, frameLengths[i]);
			if (at < 0)
				return i;
		}
		return frameLengths.length - 1;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.physics.SkaterState;
import java.util.List;

/** Pure decision logic for which skater animation to play. No client dependency. */
public final class AnimationPicker
{
	public static final float PUSH_SECONDS = 0.45f;

	public enum Action
	{
		NONE,
		PUSH,
		JUMP,
		BAIL
	}

	private AnimationPicker()
	{
	}

	public static Action pick(SkaterState state, List<SkateEvent> events, Action current, float actionTimeLeft)
	{
		if (events.contains(SkateEvent.BAIL))
			return Action.BAIL;
		if (events.contains(SkateEvent.POP) || events.contains(SkateEvent.ROLL_OFF))
			return Action.JUMP;
		if (events.contains(SkateEvent.LAND) || events.contains(SkateEvent.RESET))
			return Action.NONE;
		if (events.contains(SkateEvent.PUSH) && state == SkaterState.ROLLING)
			return Action.PUSH;
		if (current == Action.PUSH && actionTimeLeft <= 0f)
			return Action.NONE;
		return current;
	}
}

package com.gielinorskate.render;

/**
 * Finds one arm of a player mesh by its shape: OSRS models carry no bone or vertex-group data through the API,
 * so the arm is "what sticks out sideways past the chest, from the shoulder down". Puppet model space: y down
 * with the soles at 0, the body facing -z, left hand +x, right hand -x (see {@link MeshDeformer}).
 *
 * <p>The shoulder sits 0.75 of the model's height up, a little inside (0.8 of) the widest point of the chest band
 * there (0.06 of the height either side), that half-width kept within 0.07 and 0.16 of the height. A vertex belongs
 * to the arm by a smooth weight (never a hard cut, so moving the arm can never tear the mesh): 0 inside 0.66 of the
 * shoulder half-width, 1 past 0.78, faded out over 0.06 of the height above the shoulder (the head) and 0.12 below the
 * hips (the legs). The hand is the end of the arm: the arm vertices at least 0.92 of the furthest arm vertex's
 * distance from the shoulder. Models shorter than 60 units are not a body. Pure, allocation-free; one instance per
 * user (client thread only).
 */
final class ArmLocator
{
	/** The centre line is measured on vertices lower than this fraction of the hip height (below the hands). */
	static final float LOWER_LEGS = 0.6f;

	/** Results of the latest {@link #locate}: the shoulder joint and the hand, model space. */
	final float[] shoulder = new float[3];
	final float[] hand = new float[3];
	/** Distance from the shoulder to the furthest arm vertex. */
	float armLength;
	/** The arm vertex furthest from the shoulder. */
	int handIndex;
	/** The located arm's side: +1 the model's +x side (the left hand), -1 the right. */
	float side;
	private float cx;
	private float halfWidth;
	private float height;
	private float hip;

	/**
	 * Finds the arm on {@code side} (+1 the model's +x side, the left hand; -1 the right) among the first {@code n}
	 * vertices. False when the mesh does not look like a body with an arm there.
	 */
	boolean locate(float[] xs, float[] ys, float[] zs, int n, float side)
	{
		this.side = side < 0f ? -1f : 1f;
		if (n <= 0 || xs == null || ys == null || zs == null || xs.length < n || ys.length < n || zs.length < n)
			return false;
		float top = 0f;
		for (int i = 0; i < n; i++)
			top = Math.min(top, ys[i]);
		height = -top;
		if (!(height >= 60f) || Float.isInfinite(height))
			return false;
		hip = MeshDeformer.hipHeight(top);
		// the centre line from the lower legs (the arms can swing anywhere, the hands hang down to the hips; the
		// legs stand either side of it)
		float minX = Float.MAX_VALUE;
		float maxX = -Float.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			if (ys[i] > -LOWER_LEGS * hip)
			{
				minX = Math.min(minX, xs[i]);
				maxX = Math.max(maxX, xs[i]);
			}
		}
		cx = minX <= maxX ? (minX + maxX) / 2f : 0f;
		float shoulderY = -0.75f * height;
		float widest = 0f;
		float sumZ = 0f;
		int count = 0;
		for (int i = 0; i < n; i++)
		{
			if (Math.abs(ys[i] - shoulderY) <= 0.06f * height)
			{
				widest = Math.max(widest, (xs[i] - cx) * this.side);
				sumZ += zs[i];
				count++;
			}
		}
		if (count == 0)
			return false;
		halfWidth = Math.max(0.07f * height, Math.min(0.16f * height, widest));
		shoulder[0] = cx + this.side * 0.8f * halfWidth;
		shoulder[1] = shoulderY;
		shoulder[2] = sumZ / count;

		float far = 0f;
		int farIndex = -1;
		for (int i = 0; i < n; i++)
		{
			float d = weight(xs[i], ys[i]) >= 0.5f ? distance(xs[i], ys[i], zs[i]) : 0f;
			if (d > far)
			{
				far = d;
				farIndex = i;
			}
		}
		if (farIndex < 0 || far < 0.1f * height || Float.isInfinite(far))
			return false;
		int hn = 0;
		hand[0] = 0f;
		hand[1] = 0f;
		hand[2] = 0f;
		for (int i = 0; i < n; i++)
		{
			if (weight(xs[i], ys[i]) >= 0.5f && distance(xs[i], ys[i], zs[i]) >= 0.92f * far)
			{
				hand[0] += xs[i];
				hand[1] += ys[i];
				hand[2] += zs[i];
				hn++;
			}
		}
		for (int k = 0; k < 3; k++)
			hand[k] /= hn;
		armLength = far;
		handIndex = farIndex;
		return true;
	}

	/** 0..1: how much the vertex at (x, y) is the located arm (valid after a successful {@link #locate}). */
	float weight(float x, float y)
	{
		float out = PushCycle.smoothstep(0.66f * halfWidth, 0.78f * halfWidth, (x - cx) * side);
		// fades out above the shoulder (y smaller) and below the hips (y larger)
		return out <= 0f ? 0f : out * PushCycle.smoothstep(shoulder[1] - 0.06f * height, shoulder[1], y)
			* (1f - PushCycle.smoothstep(-hip, -hip + 0.12f * height, y));
	}

	private float distance(float x, float y, float z)
	{
		float dx = x - shoulder[0];
		float dy = y - shoulder[1];
		float dz = z - shoulder[2];
		return (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import lombok.AllArgsConstructor;

/**
 * The baked board v3 (board_v3_high.txt and board_v3_low.txt, written by tools/blend_to_board_baked.py): up to four
 * parts (grip, deck, wheels, hardware), each an indexed mesh drawn as its own model, all in the one board model
 * space (as {@link BoardGeometry}: long axis z, y negative up, wheels on y = 0, mid-deck top at y = -16), so posing
 * every part with the same transform puts them together as one board. Each part's image texture was baked into a
 * colour at every triangle corner. Format, one record per line ('#' comments and blank lines skipped):
 * <pre>
 * part NAME                        starts a part: grip, deck, wheels or hardware, each at most once
 * v X Y Z                          a vertex of the current part
 * t A B C RRGGBB RRGGBB RRGGBB [UA VA UB VB UC VC]
 *                                  a triangle of the current part: 0-based indices into the part's own vertices,
 *                                  the sRGB colour at each corner and, on a design face, each corner's UV in the
 *                                  part's design image (v up)
 * </pre>
 * The colours are the default designs; every design of a part is a colour file over the same triangles
 * ({@link DesignColours}), sampled at those UVs.
 * Within a part, vertices must be numbered in first-use order over its triangles (the merged runtime model numbers
 * them so). High detail fills each part's budget (about 6000 triangles); low detail (about 1500 for grip and deck)
 * is for the "Normal" board detail setting and for party ghosts.
 */
public final class BakedBoardGeometry
{
	public static final int GRIP = 0;
	public static final int DECK = 1;
	public static final int WHEELS = 2;
	public static final int HARDWARE = 3;
	static final String[] PART_NAMES = {"grip", "deck", "wheels", "hardware"};

	private BakedBoardGeometry()
	{
	}

	/** One part of the board. {@link #of} makes one in code (tests, tools): the arrays are used as they are. */
	@AllArgsConstructor(staticName = "of")
	public static final class Mesh
	{
		/** {@link #GRIP} ... {@link #HARDWARE}. */
		public final int part;
		/** 3 floats (x, y, z) per vertex. */
		public final float[] vertices;
		/** 3 vertex indices per face. */
		public final int[] faces;
		/** 0xRRGGBB per face corner, 3 per face in the order of {@link #faces}. */
		public final int[] cornerRgb;
		/**
		 * Each corner's design-image UV (u, v; v up), 6 per face; NaN on faces without a design (wheel hubs,
		 * hardware). Null when the part has none.
		 */
		public final float[] cornerUv;

		public int vertexCount()
		{
			return vertices.length / 3;
		}

		public int faceCount()
		{
			return faces.length / 3;
		}
	}

	/** Parsed variants by detail (high true); null for one that isn't bundled. */
	private static final Map<Boolean, Mesh[]> CACHE = new HashMap<>();

	/**
	 * The bundled board's parts in high or low detail, parsed once; null if that variant isn't bundled. Shared: never
	 * modify them.
	 */
	public static Mesh[] sharedBoard(boolean high)
	{
		synchronized (CACHE)
		{
			if (!CACHE.containsKey(high))
			{
				InputStream in = BakedBoardGeometry.class.getResourceAsStream(
					"/com/gielinorskate/board_v3_" + (high ? "high" : "low") + ".txt");
				try (Reader r = in == null ? null : new InputStreamReader(in, StandardCharsets.UTF_8))
				{
					CACHE.put(high, r == null ? null : parse(r));
				}
				catch (IOException e)
				{
					throw new UncheckedIOException(e);
				}
			}
			return CACHE.get(high);
		}
	}

	/** The parts, in file order. Throws IllegalArgumentException on a malformed board. */
	public static Mesh[] parse(Reader reader) throws IOException
	{
		List<Mesh> parts = new ArrayList<>();
		boolean[] seen = new boolean[PART_NAMES.length];
		PartBuilder cur = null;
		BufferedReader br = new BufferedReader(reader);
		String line;
		int lineNo = 0;
		while ((line = br.readLine()) != null)
		{
			lineNo++;
			String[] p = line.trim().split("\\s+");
			if (p[0].isEmpty() || p[0].charAt(0) == '#')
				continue;
			if (p[0].equals("part"))
			{
				check(p.length == 2, lineNo, "a part needs one name");
				int part = Arrays.asList(PART_NAMES).indexOf(p[1]);
				check(part >= 0 && !seen[part], lineNo, "unknown or repeated part " + p[1]);
				seen[part] = true;
				if (cur != null)
					parts.add(cur.build());
				cur = new PartBuilder(part);
			}
			else
			{
				check(cur != null && (p[0].equals("v") || p[0].equals("t")), lineNo, Text.get("board3.record"));
				if (p[0].equals("v"))
					cur.vertex(p, lineNo);
				else
					cur.triangle(p, lineNo);
			}
		}
		check(cur != null, lineNo, "no parts");
		parts.add(cur.build());
		return parts.toArray(new Mesh[0]);
	}

	private static final class PartBuilder
	{
		private final int part;
		private float[] verts = new float[3 * 1024];
		private int[] faces = new int[3 * 1024];
		private int[] rgb = new int[3 * 1024];
		private float[] uv = new float[6 * 1024];
		private boolean anyUv;
		private int vCount;
		private int fCount;
		private int nextUnused;

		PartBuilder(int part)
		{
			this.part = part;
		}

		void vertex(String[] p, int lineNo)
		{
			check(p.length == 4, lineNo, "a vertex needs 3 coordinates");
			if (vCount * 3 + 3 > verts.length)
				verts = Arrays.copyOf(verts, verts.length * 2);
			for (int i = 0; i < 3; i++)
				verts[vCount * 3 + i] = finite(p[1 + i], lineNo);
			vCount++;
		}

		void triangle(String[] p, int lineNo)
		{
			check(p.length == 7 || p.length == 13, lineNo, Text.get("board3.triangleSize"));
			if (fCount * 3 + 3 > faces.length)
			{
				faces = Arrays.copyOf(faces, faces.length * 2);
				rgb = Arrays.copyOf(rgb, rgb.length * 2);
				uv = Arrays.copyOf(uv, uv.length * 2);
			}
			anyUv |= p.length == 13;
			for (int i = 0; i < 6; i++)
				uv[fCount * 6 + i] = p.length == 13 ? finite(p[7 + i], lineNo) : Float.NaN;
			for (int i = 0; i < 3; i++)
			{
				int v = Integer.parseInt(p[1 + i]);
				check(v >= 0 && v < vCount && v <= nextUnused, lineNo,
					Text.get("board3.vertexOrder", v));
				if (v == nextUnused)
					nextUnused++;
				faces[fCount * 3 + i] = v;
				check(p[4 + i].length() == 6, lineNo, "colour " + p[4 + i] + " is not RRGGBB");
				rgb[fCount * 3 + i] = Integer.parseInt(p[4 + i], 16);
			}
			int a = faces[fCount * 3];
			int b = faces[fCount * 3 + 1];
			int c = faces[fCount * 3 + 2];
			check(a != b && b != c && a != c, lineNo, "a triangle uses a vertex twice");
			fCount++;
		}

		Mesh build()
		{
			check(fCount > 0 && nextUnused == vCount, -1, Text.get("board3.partEmpty", PART_NAMES[part]));
			return new Mesh(part, Arrays.copyOf(verts, vCount * 3), Arrays.copyOf(faces, fCount * 3),
				Arrays.copyOf(rgb, fCount * 3), anyUv ? Arrays.copyOf(uv, fCount * 6) : null);
		}
	}

	/** A finite number (NumberFormatException, an IllegalArgumentException, when it is no number). */
	private static float finite(String s, int lineNo)
	{
		float c = Float.parseFloat(s);
		check(Float.isFinite(c), lineNo, s + " is not finite");
		return c;
	}

	private static void check(boolean ok, int lineNo, String msg)
	{
		if (!ok)
			throw new IllegalArgumentException("board v3 line " + lineNo + ": " + msg);
	}

	/** Every corner's colour (0xRRGGBB) as packed HSL at {@code brightness}, in corner order. */
	public static short[] cornerHsl(int[] cornerRgb, double brightness)
	{
		short[] out = new short[cornerRgb.length];
		// boards repeat colours a lot: convert each distinct colour once
		Map<Integer, Short> seen = new HashMap<>();
		for (int i = 0; i < out.length; i++)
			out[i] = seen.computeIfAbsent(cornerRgb[i], rgb -> (short) OsrsColor.rgbToHsl(rgb, brightness));
		return out;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.progression.*;
import java.util.*;
import lombok.AllArgsConstructor;
import net.runelite.api.*;

/**
 * The baked board (see {@link BakedBoardGeometry}): image textures shown as a colour at every triangle corner, one
 * model per part (grip, deck, wheels, hardware) so each part has the renderers' whole per-model budget. Every part
 * is posed with the same board transform ({@link BoardPlacement#poseInto}) and drawn by its own
 * {@link BoardController} placed exactly like the others, so together they are one board.
 *
 * <p>Each part is built from merged single-triangle cache models, welded: before
 * merging, each triangle's corners are moved to integer positions that name the part vertex they stand for, and the
 * client's merge joins corners at equal positions, so the merged model has exactly the part's shared vertices (the
 * lighting is then smooth across smooth surfaces, like any game model). The real positions are written after.
 *
 * <p>Colours: the client lights a model by scaling each corner's lightness by a light intensity
 * (lightness * intensity / 128, kept within 2..126) and keeps one colour per face before lighting. So every face
 * is given the same probe colour (lightness {@link #PROBE_LIGHTNESS}), the model is lit, the intensity at each
 * corner is read back from the lit probe, and the corner is rewritten as its baked colour lit by that intensity.
 * The rewrite is in place on the freshly lit model's colour arrays, allocation free.
 *
 * <p>Designs ({@link #setLook}): the grip, deck and wheels parts take their design's corner colours
 * ({@link DesignColours}) over the same geometry, so changing designs only swaps each part's baked colours and drops
 * its lit model: the next pose lights it again with the new colours. Nothing is merged again.
 */
@AllArgsConstructor
public final class BakedBoardModel
{
	/** Per-model vertex and face limits of the client's renderers (6500 in the GPU and software renderers). */
	static final int MAX_VERTICES = 6500;
	/** Probe colour lightness: half of 128, so lit intensities up to 252 read back unclipped. */
	static final int PROBE_LIGHTNESS = 64;
	static final short PROBE = (short) OsrsColor.pack(0, 0, PROBE_LIGHTNESS);
	/**
	 * Lighting: brighter ambient (100) and a softer contrast (1000) than the game default (64, 768), so the image
	 * keeps most of its brightness: the grip top lands near 85% and the underside near 70% instead of 60% and 40%.
	 */
	private static final int AMBIENT = 100;
	private static final int CONTRAST = 1000;

	private final Part[] parts;
	private final boolean high;
	private final double brightness;
	private BoardLook look;

	/** One part's model data and its last lit model. */
	private static final class Part
	{
		final ModelData data;
		final BakedBoardGeometry.Mesh mesh;
		final float[] base;
		final float[] posed;
		/** Each corner's baked colour (the part's design), packed HSL; shared, never modified. */
		short[] cornerHsl;
		Model lit;
		float roll;
		float pitch;
		float flip;
		float pivotY;

		Part(ModelData data, BakedBoardGeometry.Mesh mesh, float[] base, short[] cornerHsl)
		{
			this.data = data;
			this.mesh = mesh;
			this.base = base;
			this.posed = new float[base.length];
			this.cornerHsl = cornerHsl;
		}
	}

	/**
	 * The baked board in high or low detail (low for the "Normal" board detail setting and for party ghosts), or
	 * null if it isn't bundled or a cache model can't be loaded or merged. Client thread. The first call per client
	 * and detail merges the parts' templates (thousands of cache models: a noticeable hitch once). In {@code look}'s
	 * designs (null: the geometry's own colours, the default designs). Each call makes its own model data (a party
	 * ghost's board poses on its own); the merged templates are shared.
	 */
	public static BakedBoardModel create(Client client, boolean high, BoardLook look)
	{
		double brightness = client.getTextureProvider() != null ? client.getTextureProvider().getBrightness()
			: OsrsColor.DEFAULT_BRIGHTNESS;
		BakedBoardGeometry.Mesh[] meshes = BakedBoardGeometry.sharedBoard(high);
		if (meshes == null || !fitsRenderers(meshes))
			return null;
		if (templateClient != client)
		{
			TEMPLATES.clear();
			templateClient = client;
		}
		Part[] parts = new Part[meshes.length];
		for (int i = 0; i < meshes.length; i++)
		{
			BakedBoardGeometry.Mesh mesh = meshes[i];
			ModelData template = TEMPLATES.computeIfAbsent(mesh, m -> mergeTemplate(client, m));
			if (template == null)
				return null;
			ModelData data = template.shallowCopy().cloneVertices().cloneColors();
			Arrays.fill(data.getFaceColors(), 0, mesh.faceCount(), PROBE);
			parts[i] = new Part(data, mesh, mesh.vertices, partHsl(mesh, look, high, brightness));
			writeVertices(data, mesh.vertices);
		}
		return new BakedBoardModel(parts, high, brightness, look);
	}

	/**
	 * Draws the board in {@code look}'s designs: each design part whose colours change gets them and is lit again
	 * at its next pose (its controller must be told to draw again). Nothing else is touched. Client thread.
	 *
	 * @return true if any part's colours changed
	 */
	public boolean setLook(BoardLook look)
	{
		if (look == null || look.equals(this.look))
			return false;
		this.look = look;
		boolean changed = false;
		for (Part p : parts)
		{
			short[] hsl = partHsl(p.mesh, look, high, brightness);
			if (hsl != p.cornerHsl)
			{
				p.cornerHsl = hsl;
				// the lit model carries the old colours: the next pose lights it again with these
				p.lit = null;
				changed = true;
			}
		}
		return changed;
	}

	/** The designs drawn (null: the geometry's own colours). */
	public BoardLook look()
	{
		return look;
	}

	/** The design {@code look} puts on a mesh's part, or null for a part without designs (hardware). */
	static BoardDesign designFor(BakedBoardGeometry.Mesh mesh, BoardLook look)
	{
		for (DesignPart p : DesignPart.values())
		{
			if (look != null && p.index == mesh.part)
				return look.get(p);
		}
		return null;
	}

	/** Design colours as HSL by "ID.detail@brightness". */
	static final Map<String, short[]> HSL_CACHE = new HashMap<>();
	/** The geometry's own colours as HSL, by (mesh, brightness). */
	private static final Map<List<Object>, short[]> OWN_HSL = new HashMap<>();

	/**
	 * A part's corner colours in {@code look}'s design as packed HSL: the design's colour file, or the geometry's
	 * own colours for hardware, a null look or a missing file. Converted once per design, detail and brightness
	 * and shared (never modify it), so switching back and forth costs nothing.
	 */
	static short[] partHsl(BakedBoardGeometry.Mesh mesh, BoardLook look, boolean high, double brightness)
	{
		BoardDesign d = designFor(mesh, look);
		int[] rgb = d == null ? null : DesignColours.colours(d.id, high, mesh);
		synchronized (HSL_CACHE)
		{
			return rgb == null
				? OWN_HSL.computeIfAbsent(List.of(mesh, brightness), k -> BakedBoardGeometry.cornerHsl(mesh.cornerRgb, brightness))
				: HSL_CACHE.computeIfAbsent(d.id + (high ? ".high@" : ".low@") + brightness,
				k -> BakedBoardGeometry.cornerHsl(rgb, brightness));
		}
	}

	/** True if every part fits one model of the client's renderers. */
	static boolean fitsRenderers(BakedBoardGeometry.Mesh[] meshes)
	{
		return meshes.length > 0
			&& Arrays.stream(meshes).allMatch(m -> m.vertexCount() <= MAX_VERTICES && m.faceCount() <= MAX_VERTICES);
	}

	private static Client templateClient;
	private static final Map<BakedBoardGeometry.Mesh, ModelData> TEMPLATES = new IdentityHashMap<>();

	/** One model with the part's faces and exactly its (shared) vertices. Null if the merge didn't weld as planned. */
	private static ModelData mergeTemplate(Client client, BakedBoardGeometry.Mesh mesh)
	{
		int faces = mesh.faceCount();
		int[] f = mesh.faces;
		ModelData[] parts = new ModelData[faces];
		for (int i = 0; i < faces; i++)
		{
			// a cache model consisting of one triangle
			ModelData p = client.loadModelData(823);
			if (p == null || p.getVerticesCount() != 3 || p.getFaceCount() != 1)
				return null;
			p = p.cloneColors().cloneVertices();
			int[] corner = {p.getFaceIndices1()[0], p.getFaceIndices2()[0], p.getFaceIndices3()[0]};
			for (int k = 0; k < 3; k++)
			{
				// position = the part vertex's key; the merge welds equal (integer) positions
				int v = f[i * 3 + k];
				p.getVerticesX()[corner[k]] = weldKeyX(v);
				p.getVerticesY()[corner[k]] = weldKeyY(v);
				p.getVerticesZ()[corner[k]] = 0;
			}
			parts[i] = p;
		}
		ModelData merged = client.mergeModels(parts);
		if (merged == null || merged.getFaceCount() != faces || merged.getVerticesCount() != mesh.vertexCount())
			return null;
		merged.cloneVertices().cloneColors();
		for (int i = 0; i < faces; i++)
		{
			merged.getFaceIndices1()[i] = f[i * 3];
			merged.getFaceIndices2()[i] = f[i * 3 + 1];
			merged.getFaceIndices3()[i] = f[i * 3 + 2];
		}
		return merged;
	}

	/** Distinct small integer positions per vertex (x, y within +-128 so they stay well inside model bounds). */
	static int weldKeyX(int v)
	{
		return v % 256 - 128;
	}

	static int weldKeyY(int v)
	{
		return v / 256 - 128;
	}

	/** How many models (parts) the board is drawn as. */
	public int partCount()
	{
		return parts.length;
	}

	/**
	 * Part {@code part} (0 .. {@link #partCount()} - 1) of the board, lit, rotated by roll (around its long axis) and
	 * pitch (about the contact truck), then turned by {@code flip} about the skater's centre of mass at
	 * {@code pivotY}. Client thread.
	 */
	public Model pose(int part, float roll, float pitch, float flip, float pivotY)
	{
		Part p = parts[part];
		if (p.lit != null && !needsRelight(p.roll, p.pitch, p.flip, p.pivotY, roll, pitch, flip, pivotY))
			return p.lit;
		writeVertices(p.data, BoardPlacement.poseInto(p.base, roll, pitch, flip, pivotY, p.posed));
		Model m = p.data.light(AMBIENT, CONTRAST, ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
		if (m != null)
		{
			shade(m.getFaceColors1(), m.getFaceColors2(), m.getFaceColors3(), p.cornerHsl);
			p.lit = m;
			p.roll = roll;
			p.pitch = pitch;
			p.flip = flip;
			p.pivotY = pivotY;
		}
		return m;
	}

	/**
	 * True when a pose moved far enough from the one last lit ({@code lit*}) to light the model again: 0.003 rad
	 * moves the tail by about 0.1 units, well under a pixel at any zoom (0.25 units for the pivot).
	 */
	static boolean needsRelight(float litRoll, float litPitch, float litFlip, float litPivotY,
		float roll, float pitch, float flip, float pivotY)
	{
		return Math.abs(roll - litRoll) > 0.003f || Math.abs(pitch - litPitch) > 0.003f
			|| Math.abs(flip - litFlip) > 0.003f || Math.abs(pivotY - litPivotY) > 0.25f;
	}

	/**
	 * Rewrites lit probe colours as the baked corner colours lit the same: each corner's intensity is read back
	 * from its lit probe (lightness = 64 * intensity / 128, so intensity is about 2 * lightness + 1). Faces the
	 * client drew flat (colour 3 is -1) get their one intensity at all three corners; hidden faces (-2) are left.
	 */
	static void shade(int[] c1, int[] c2, int[] c3, short[] cornerHsl)
	{
		int faces = Math.min(cornerHsl.length / 3, c3.length);
		for (int i = 0; i < c3.length; i++)
		{
			int third = c3[i];
			if (i < faces && third != -2)
			{
				int i1 = intensity(c1[i]);
				c1[i] = OsrsColor.light(cornerHsl[i * 3] & 0xffff, i1);
				c2[i] = OsrsColor.light(cornerHsl[i * 3 + 1] & 0xffff, third == -1 ? i1 : intensity(c2[i]));
				c3[i] = OsrsColor.light(cornerHsl[i * 3 + 2] & 0xffff, third == -1 ? i1 : intensity(third));
			}
		}
	}

	/** The light intensity (128 = unchanged) that lit the probe colour to {@code litProbe}. */
	static int intensity(int litProbe)
	{
		return (litProbe & 127) * 128 / PROBE_LIGHTNESS + 1;
	}

	private static void writeVertices(ModelData data, float[] v)
	{
		float[] vx = data.getVerticesX();
		float[] vy = data.getVerticesY();
		float[] vz = data.getVerticesZ();
		for (int i = 0; i < v.length / 3; i++)
		{
			vx[i] = v[i * 3];
			vy[i] = v[i * 3 + 1];
			vz[i] = v[i * 3 + 2];
		}
	}
}

package com.gielinorskate.render;

import lombok.RequiredArgsConstructor;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObjectController;

/**
 * Draws one part of the board (one object per part of the baked board). The board's roll and pitch are set each
 * frame by {@link SkaterRenderer}; the body flip angle is read from the shared {@link BodyPose} when the client draws,
 * the same moment the puppet reads it, so the board and the flipping skater can never be a frame apart (the pose rig
 * runs after the renderer in a frame). The mesh is rebuilt only when something changed. Client thread only.
 */
@RequiredArgsConstructor
public final class BoardController extends RuneLiteObjectController
{
	private final int part;
	private BakedBoardModel boardModel;
	private BodyPose body;
	private Model model;
	private float roll;
	private float pitch;
	private float pivotY;
	private boolean flipAllowed;
	private boolean dirty = true;
	private float builtFlip;

	public void setBoard(BakedBoardModel boardModel, BodyPose body)
	{
		this.boardModel = boardModel;
		this.body = body;
		dirty = true;
	}

	/** The board's colours changed: rebuild the model when next drawn. */
	public void repaint()
	{
		dirty = true;
	}

	/**
	 * @param flipPivotY the skater's centre of mass in board model space
	 * @param flipAllowed false when the skater cannot flip with the board (bailed, or not deformable)
	 */
	public void setPose(float roll, float pitch, float flipPivotY, boolean flipAllowed)
	{
		dirty |= roll != this.roll || pitch != this.pitch || flipPivotY != pivotY || flipAllowed != this.flipAllowed;
		this.roll = roll;
		this.pitch = pitch;
		this.pivotY = flipPivotY;
		this.flipAllowed = flipAllowed;
	}

	@Override
	public Model getModel()
	{
		float flip = flipAllowed && body != null ? body.flip : 0f;
		// a flip change of 0.002 rad (0.1 units at the 61-unit pivot radius) rebuilds the mesh
		if (boardModel != null && (dirty || Math.abs(flip - builtFlip) > 0.002f))
		{
			model = boardModel.pose(part, roll, pitch, flip, pivotY);
			builtFlip = flip;
			dirty = false;
		}
		return model;
	}
}

package com.gielinorskate.render;

/** Board model space: long axis = z, y negative = up, wheels rest on y = 0. Pure. */
public final class BoardGeometry
{
	/** Height of the deck top the feet stand on. */
	public static final float BOARD_TOP = 16f;

	private BoardGeometry()
	{
	}

	/** Rotates by roll (around z) then pitch (around x). Returns a new array. */
	public static float[] rotate(float[] tris, float roll, float pitch)
	{
		return rotateInto(tris, roll, pitch, new float[tris.length]);
	}

	/** As {@link #rotate}, writing into {@code out} (at least {@code tris.length} long; may not be {@code tris}). Returns {@code out}. */
	static float[] rotateInto(float[] tris, float roll, float pitch, float[] out)
	{
		float cr = (float) Math.cos(roll);
		float sr = (float) Math.sin(roll);
		float cp = (float) Math.cos(pitch);
		float sp = (float) Math.sin(pitch);
		for (int i = 0; i < tris.length; i += 3)
		{
			float x = tris[i];
			float y = tris[i + 1];
			float z = tris[i + 2];
			float y1 = x * sr + y * cr;
			out[i] = x * cr - y * sr;
			out[i + 1] = y1 * cp - z * sp;
			out[i + 2] = y1 * sp + z * cp;
		}
		return out;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;

/**
 * Pure placement maths for a pitched or sliding board, in board model space (long axis z, y negative =
 * up, wheels resting on y = 0). A pitched board turns about the axle of the truck that stays down (the
 * tail truck for nose-up manuals and 5-0s, the nose truck for nose manuals and nosegrinds), so the
 * contact wheels stay on the ground or rail instead of sinking 30 * sin(pitch) into it as they would
 * turning about the board's centre.
 */
public final class BoardPlacement
{
	/** Distance of each truck's axle from the board's centre along z. */
	static final float TRUCK_Z = 30f;
	/** Axle height: wheel centre, one wheel radius (4.5) above the ground. */
	static final float AXLE_Y = -4.5f;
	/** Gap between the deck surface and the soles so feet never sink into the board (the crouch animation already lowers the body). */
	public static final int FOOT_CLEARANCE = 4;

	private BoardPlacement()
	{
	}

	/** z of the pivot axle: the tail truck (-z) when the nose is up, the nose truck when it is down. */
	static float pivotZ(float pitch)
	{
		return pitch > 0f ? -TRUCK_Z : pitch < 0f ? TRUCK_Z : 0f;
	}

	/** Rolls {@code tris} about the long axis, then pitches it about the contact truck's axle. Returns a new array. */
	public static float[] pose(float[] tris, float roll, float pitch)
	{
		return poseInto(tris, roll, pitch, 0f, 0f, new float[tris.length]);
	}

	/**
	 * Rolls and pitches {@code tris} like {@link #pose(float[], float, float)}, then turns the whole board by
	 * {@code flip} radians about the skater's centre of mass at board-model height {@code pivotY} (a front or back
	 * flip of skater and board together), writing into {@code out} (which may be {@code tris}). The rotation has the
	 * sense of the pitch: positive raises the +z end. Returns {@code out}.
	 */
	static float[] poseInto(float[] tris, float roll, float pitch, float flip, float pivotY, float[] out)
	{
		BoardGeometry.rotateInto(tris, roll, 0f, out);
		float pz = pivotZ(pitch);
		float cp = (float) Math.cos(pitch);
		float sp = (float) Math.sin(pitch);
		float c = (float) Math.cos(flip);
		float s = (float) Math.sin(flip);
		for (int i = 0; i < tris.length && (pitch != 0f || flip != 0f); i += 3)
		{
			if (pitch != 0f)
			{
				float y = out[i + 1] - AXLE_Y;
				float z = out[i + 2] - pz;
				out[i + 1] = y * cp - z * sp + AXLE_Y;
				out[i + 2] = y * sp + z * cp + pz;
			}
			if (flip != 0f)
			{
				float y = out[i + 1] - pivotY;
				float z = out[i + 2];
				out[i + 1] = y * c - z * s + pivotY;
				out[i + 2] = y * s + z * c;
			}
		}
		return out;
	}

	/**
	 * Where a grabbing hand goes, into {@code out} (x, y, z): the grab's point on the board ({@link GrabPose}) at
	 * {@code along} (+ toward the nose), {@code across} (- toward the toe edge) and board-model height {@code boardY},
	 * turned with the board's drawn roll and pitch (the tweak, a flip in progress), in the puppet's model space before
	 * the front/back flip (which turns body and board together, so it is applied after the reach). Puppet space: x
	 * along the board (+ toward the nose), y down with the soles at 0, z out of
	 * the back (the toe edge on the chest side, -z). The board's own model space is (board x, y, board z) = (puppet
	 * z, y, -puppet x), with the soles BOARD_TOP + FOOT_CLEARANCE + {@code deckLift} (how far the pitched deck lifts
	 * them) above the board's origin. Allocation-free.
	 */
	static void grabTarget(float along, float across, float boardY, float roll, float pitch, float deckLift,
		float[] out)
	{
		out[0] = across;
		out[1] = boardY;
		out[2] = -along;
		poseInto(out, roll, pitch, 0f, 0f, out);
		float x = out[0];
		out[0] = -out[2];
		out[1] += BoardGeometry.BOARD_TOP + FOOT_CLEARANCE + deckLift;
		out[2] = x;
	}

	/**
	 * The flip pivot in the puppet's model space (y down, soles at 0): the skater's centre of mass, 45 units above the deck
	 * top, which is {@link #FOOT_CLEARANCE} below the soles.
	 */
	public static float puppetFlipPivotY()
	{
		return FOOT_CLEARANCE - 45f;
	}

	/**
	 * The same pivot in the board's model space. The renderer draws the puppet's soles BOARD_TOP +
	 * FOOT_CLEARANCE + {@code deckLift} above the board's origin (both share the slide drop and the charge
	 * dip), so the puppet's y maps to board y - (BOARD_TOP + FOOT_CLEARANCE + deckLift).
	 */
	public static float boardFlipPivotY(float deckLift)
	{
		return -(BoardGeometry.BOARD_TOP + FOOT_CLEARANCE + deckLift) + puppetFlipPivotY();
	}

	/** How far (up-positive units) the centre of the deck top rises when pitched about the contact truck. */
	public static float deckLift(float pitch)
	{
		if (pitch == 0f)
			return 0f;
		float pz = pivotZ(pitch);
		float y = -BoardGeometry.BOARD_TOP - AXLE_Y;
		float z = -pz;
		float pitchedY = y * (float) Math.cos(pitch) - z * (float) Math.sin(pitch) + AXLE_Y;
		return -BoardGeometry.BOARD_TOP - pitchedY;
	}

	/**
	 * Whole units a grab draws the board above its physics place: the rig's knees-up ({@link BodyPose#feetLift}),
	 * which the feet fold up to ({@link BodyPose#boardLift}); 0 in a bail or for anything not finite. Render only.
	 */
	public static int grabLift(float feetLift, boolean bailed)
	{
		if (bailed || !(feetLift > 0f) || Float.isInfinite(feetLift))
			return 0;
		// never further than 40 above its physics place
		return Math.round(Math.min(feetLift, 40f));
	}


	/**
	 * Units to lower the board and skater: 13 in a slide or crooked-family grind (physics puts the wheels on the rail
	 * top, but the deck sits on it: the deck underside is at y = -16 + 3 = -13), else 0.
	 */
	public static float slideDrop(SkaterState state, Trick hold)
	{
		if (state != SkaterState.GRINDING || hold == null)
			return 0f;
		switch (hold)
		{
			case BOARDSLIDE:
			case NOSESLIDE:
			case TAILSLIDE:
			case LIPSLIDE:
			case CROOKED:
			case SMITH:
			case FEEBLE:
				return 13f;
			default:
				return 0f;
		}
	}
}

package com.gielinorskate.render;

/**
 * The procedural body pose layered on the skater's stance animation, in the puppet's model space (x
 * along the board, y down, z out of the back: the body faces -z). Written by {@link SkaterPoseRig} on the
 * client thread each frame and read by {@link PuppetController} when the client draws the puppet.
 */
public final class BodyPose
{
	private static final float EPSILON = 1e-4f;

	/** Radians about the board's long axis (through the feet); negative leans the head toward the chest. */
	public float roll;
	/** Radians about the contact truck, the same sense as the board's pitch. */
	public float pitch;
	/** Model x of the pitch pivot (the contact truck). */
	public float pivotX;
	/** Leg length factor: below 1 bends the knees (squash), above 1 extends them (stretch). */
	public float legScale = 1f;
	/** Radians the upper body folds forward at the hips (toward the chest). */
	public float torsoBend;
	/** Radians the upper body tips at the hips along the board, the pitch sense: positive tips the head toward +x. */
	public float torsoLean;

	/** 0..1: how much the push leg follows the foot target below instead of the plain crouch. */
	public float legWeight;
	/** The side of the body's centre plane (sign of model x) the push leg is on: -1 or +1. */
	public float legSide = -1f;
	/** Push-foot target, model space offset from where the foot rests (y down: positive is below the soles). */
	public float footX;
	public float footY;
	public float footZ;

	/**
	 * Radians the whole body turns about the centre of mass (a front or back flip), the pitch sense: positive
	 * tips the head toward +x. Raw, not wrapped, so it never snaps at a full turn.
	 */
	public float flip;
	/** Model y of the flip pivot (the centre of mass), y down. */
	public float flipPivotY;

	/** 0..1: how far the grabbing arm has reached for the board (0: the arm as animated). */
	public float armWeight;
	/** The grabbing arm's side of the body (sign of model x): +1 the left hand, -1 the right. */
	public float armSide = -1f;
	/** The grab point: units along the board (+ toward the nose), across it (- the toe edge), board-model height. */
	public float grabAlong;
	public float grabAcross;
	public float grabBoardY;

	/**
	 * The board as drawn this frame (written by the renderer, not the rig): roll, pitch and the deck lift a pitch
	 * gives the soles. The grabbing hand goes to the grab point on the board as it is actually drawn.
	 */
	public float boardRoll;
	public float boardPitch;
	public float deckLift;
	/**
	 * Units the board is drawn above its physics place this frame (a grab's {@link #feetLift}, rounded; written by
	 * the renderer, not the rig): the feet fold up to it and the hand aims at the board there.
	 */
	public float boardLift;

	/**
	 * 0..1: how far the knees fold up toward the chest in a grab (the thighs swing forward, the shins back, the feet
	 * stay flat) instead of the plain squash; the arms also go with the upper body rather than the legs. 0 everywhere
	 * else.
	 */
	public float kneeFold;
	/** Units the rig wants the feet (and the board under them) pulled up toward the hips: a grab's knees-up. */
	public float feetLift;

	public void neutral()
	{
		roll = 0f;
		pitch = 0f;
		pivotX = 0f;
		legScale = 1f;
		torsoBend = 0f;
		torsoLean = 0f;
		legWeight = 0f;
		legSide = -1f;
		footX = 0f;
		footY = 0f;
		footZ = 0f;
		flip = 0f;
		flipPivotY = 0f;
		armWeight = 0f;
		armSide = -1f;
		grabAlong = 0f;
		grabAcross = 0f;
		grabBoardY = 0f;
		boardRoll = 0f;
		boardPitch = 0f;
		deckLift = 0f;
		boardLift = 0f;
		kneeFold = 0f;
		feetLift = 0f;
	}

	/** True when the pose would not visibly change the mesh. */
	public boolean isNeutral()
	{
		return Math.abs(roll) < EPSILON && Math.abs(pitch) < EPSILON && Math.abs(legScale - 1f) < EPSILON
			&& Math.abs(torsoBend) < EPSILON && Math.abs(torsoLean) < EPSILON && legWeight < EPSILON
			&& Math.abs(flip) < EPSILON && armWeight < EPSILON && kneeFold < EPSILON && boardLift < EPSILON;
	}
}

package com.gielinorskate.render;

/**
 * Decides, every frame, whether the model the client hands out may be deformed in place, and does it.
 * Pure (generic over the model type) so the safety logic is unit-tested without a client.
 *
 * <p>A model may be edited only when it is a buffer the client rebuilds on every request (the shared
 * animation buffer of an animated actor): then the edit lasts until the next rebuild and never reaches the
 * cached base model it was built from. The cached base model itself (returned when nothing is animating)
 * must never be edited, since edits there would persist and pile up frame after frame.
 *
 * <p>Test: take the model, add {@link #SENTINEL} to its vertex 0 x, request the model again. If the
 * second request overwrote the sentinel and returned the same object, the buffer is rebuilt per request
 * (proved for this frame), so the second result is deformed. Otherwise the sentinel is put back at once
 * (nothing else ran in between: same thread, no draw) and the second result is drawn as is.
 */
public final class BufferProbe
{
	/** Added to vertex 0's x as the probe: no rebuild of a real model lands exactly on it. */
	static final float SENTINEL = 1031f;

	public interface Source<M>
	{
		M get();
	}

	public interface Mesh<M>
	{
		int count(M m);

		float[] xs(M m);

		float[] ys(M m);

		float[] zs(M m);

		/** Called after {@code m} was deformed (to refresh bounds). */
		void deformed(M m);
	}

	private BufferProbe()
	{
	}

	/** The result of {@link #prove}: the model to draw. */
	public static final class Probe<M>
	{
		M drawn;
	}

	/** The model to draw this frame, deformed by {@code pose} when that is provably safe; {@code probe} is scratch. */
	static <M> M drawable(Source<M> source, Mesh<M> mesh, BodyPose pose, Probe<M> probe)
	{
		if (pose.isNeutral())
			return source.get();
		if (!prove(source, mesh, probe))
			return probe.drawn;
		M b = probe.drawn;
		MeshDeformer.deform(mesh.xs(b), mesh.ys(b), mesh.zs(b), mesh.count(b), pose);
		mesh.deformed(b);
		return b;
	}

	/**
	 * Requests the model twice with the probe in between. True when the second model is provably the buffer the
	 * client rebuilds on every request (the same object, the probe overwritten) with vertex arrays covering its
	 * count: then {@code out.drawn} may be edited in place for this frame. Otherwise {@code out.drawn} is the model
	 * to draw as is (null when there is none) and nothing was left changed.
	 */
	static <M> boolean prove(Source<M> source, Mesh<M> mesh, Probe<M> out)
	{
		M a = source.get();
		out.drawn = a;
		if (a == null)
			return false;
		int n = mesh.count(a);
		float[] ax = mesh.xs(a);
		if (n <= 0 || ax == null || ax.length < n || !Float.isFinite(ax[0]))
			return false;
		float orig = ax[0];
		float mark = orig + SENTINEL;
		ax[0] = mark;
		M b;
		try
		{
			b = source.get();
		}
		catch (RuntimeException ex)
		{
			if (ax[0] == mark)
				ax[0] = orig;
			throw ex;
		}
		boolean rebuilt = ax[0] != mark;
		if (!rebuilt)
			// a persistent model: undo the probe before anything can see it
			ax[0] = orig;
		out.drawn = b != null ? b : a;
		if (!rebuilt || b != a)
			return false;
		int m = mesh.count(b);
		float[] xs = mesh.xs(b);
		float[] ys = mesh.ys(b);
		float[] zs = mesh.zs(b);
		return m > 0 && xs != null && ys != null && zs != null && xs.length >= m && ys.length >= m && zs.length >= m;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.FootPhysics;

/**
 * The carried board: held by its middle in the right hand at hip height (the hand anchor), turned nearly on its
 * edge with the deck facing out and the wheels toward the leg, its length along the walk and tilted, the more so
 * the faster the walk. Pure placement maths for the board object.
 */
public final class CarryPose
{
	/** The hand anchor: units to the right of the body's centre line. */
	static final float HAND_SIDE = 30f;
	/** The hand anchor: units above the soles (hip height of a 200-unit character, MeshDeformer.hipHeight). */
	static final float HAND_HEIGHT = 85f;
	/** Board-model y of the held point, the middle of the board between the wheels' bottoms and the deck top. */
	static final float HELD_Y = -9f;

	private CarryPose()
	{
	}

	/**
	 * The board's tilt along the walk at {@code speed} u/s, in 12 steps from standing to a sprint (about 0.02 rad
	 * each): the board's mesh is rebuilt whenever its pose changes, so a speed that wobbles every frame (a ghost's dead
	 * reckoning) must not move it.
	 */
	public static float pitch(float speed)
	{
		float stepped = Math.round(PushCycle.clamp01(speed / FootPhysics.SPRINT_SPEED) * 12) / 12f;
		// 0.12 rad standing, 0.35 at a sprint
		return 0.12f + (0.35f - 0.12f) * stepped;
	}

	/**
	 * Where the board object goes so its middle is in a hand at ({@code mx}, {@code my}, {@code mz}) in the model
	 * space of a walker body drawn facing {@code heading} with its soles at ({@code x}, {@code y}, up-positive
	 * {@code h}): y down, the body facing -z, its right hand on the -x side ({@link HandAnchor}). The board rolls a
	 * little short of on its edge, deck out to the right.
	 */
	public static void placeAt(float x, float y, float h, float heading, float speed, float mx, float my, float mz,
		Placement out)
	{
		int jau = Angles.toJau(heading);
		hold(x, y, h, jau, mx, my, mz, jau, -(Angles.PI / 2 - 0.15f), pitch(speed), out);
	}

	/**
	 * Where the board object goes so its held point (the middle, board-model y {@link #HELD_Y}), rolled and pitched
	 * and turned to {@code boardJau}, is at puppet point ({@code mx}, {@code my}, {@code mz}) of a body with its soles
	 * at ({@code x}, {@code y}, up-positive {@code h}) facing {@code bodyJau}.
	 */
	static void hold(float x, float y, float h, int bodyJau, float mx, float my, float mz, int boardJau, float roll,
		float pitch, Placement out)
	{
		float[] c = BoardPlacement.pose(new float[]{0f, HELD_Y, 0f}, roll, pitch);
		// RuneLite's model-to-local rotation (see MeshDeformer), for the held point and the hand alike
		double tb = boardJau * Math.PI / 1024.0;
		float cb = (float) Math.cos(tb);
		float sb = (float) Math.sin(tb);
		double th = bodyJau * Math.PI / 1024.0;
		float ch = (float) Math.cos(th);
		float sh = (float) Math.sin(th);
		out.set(x + mx * ch + mz * sh - (c[0] * cb + c[2] * sb), y + mz * ch - mx * sh - (c[2] * cb - c[0] * sb),
			-h + my - c[1], boardJau, roll, pitch);
	}

	/**
	 * How far (0 in the hand .. 1 under the feet) the board has come down in a jump onto the carried board, by the
	 * vertical speed: in the hand on the way up, put under the feet on the way down, so the landing is on it.
	 */
	public static float mountDrop(float verticalSpeed)
	{
		// all the way down under the feet falling at 0.6 of the mount jump's take-off speed
		return PushCycle.smoothstep(0f, 0.6f * FootPhysics.MOUNT_JUMP_VH, -verticalSpeed);
	}

	/** The board flat under the feet of a walker with soles at up-positive {@code h}, nose along {@code heading}. */
	public static void underFeet(float x, float y, float h, float heading, Placement out)
	{
		out.set(x, y, -(h - BoardGeometry.BOARD_TOP - BoardPlacement.FOOT_CLEARANCE), Angles.toJau(heading), 0f, 0f);
	}
}

package com.gielinorskate.render;

/**
 * A critically damped spring (x'' = -2w x' - w^2 (x - target)), stepped with its exact solution so the
 * motion does not depend on the frame rate and never overshoots a fixed target. Kicks (velocity impulses)
 * give a dip that springs back. Pure.
 */
final class CriticalSpring
{
	float value;
	float velocity;

	/** Moves toward {@code target}; {@code omega} (1/s) sets the speed: about 4 / omega seconds to settle. */
	void step(float target, float omega, float dt)
	{
		if (dt <= 0f)
			return;
		float y = value - target;
		float e = (float) Math.exp(-omega * dt);
		// exact: y(t) = (y0 + (v0 + w y0) t) e^-wt, v(t) = (v0 - w (v0 + w y0) t) e^-wt
		float tmp = (velocity + omega * y) * dt;
		value = target + (y + tmp) * e;
		velocity = (velocity - omega * tmp) * e;
	}

	/** Adds a velocity impulse. */
	void kick(float dv)
	{
		velocity += dv;
	}

	void reset(float v)
	{
		value = v;
		velocity = 0f;
	}

	/**
	 * The kick that makes a spring at rest on its target peak {@code peak} away from it: the response
	 * v0 t e^-wt peaks at t = 1/w with v0 / (w e).
	 */
	static float kickForPeak(float peak, float omega)
	{
		return peak * omega * (float) Math.E;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.util.*;
import lombok.extern.slf4j.Slf4j;

/**
 * A board design's corner colours (designs/ID.high.rgb and ID.low.rgb, written by tools/blend_to_board_baked.py):
 * a design is only colours over the shared geometry of {@link BakedBoardGeometry}, in its triangle order. Format
 * (big-endian; documented with the writer in tools/designs.py):
 * <pre>
 * 0   "RSKC"
 * 4   version (1), part (0 grip, 1 deck, 2 wheels), 2 bytes reserved
 * 8   int32 triangle count N
 * 12  N * 9 bytes: corners A, B, C of each triangle, R G B each
 * </pre>
 * Files are read once and kept (they are shared: never modify the arrays).
 */
@Slf4j
public final class DesignColours
{
	private static final String DIR = "/com/gielinorskate/designs/";
	private static final int VERSION = 1;
	private static final byte[] MAGIC = {'R', 'S', 'K', 'C'};
	/** "ID.high" -> colours, or a zero-length array for a file that is missing or broken. */
	static final Map<String, int[]> CACHE = new HashMap<>();

	private DesignColours()
	{
	}

	/** The colour file of {@code part} (0 grip, 1 deck, 2 wheels) holding these corner colours (3 per triangle). */
	public static byte[] pack(int part, int[] rgb)
	{
		if (rgb.length % 3 != 0)
			throw new IllegalArgumentException(Text.get("designs.whole"));
		ByteBuffer b = ByteBuffer.allocate(12 + rgb.length * 3).put(MAGIC).put((byte) VERSION).put((byte) part)
			.putShort((short) 0).putInt(rgb.length / 3);
		for (int c : rgb)
			b.put((byte) (c >> 16)).put((byte) (c >> 8)).put((byte) c);
		return b.array();
	}

	/** The colour file's corner colours; IllegalArgumentException unless it is a valid file for {@code part}. */
	public static int[] parse(byte[] data, int part)
	{
		if (data.length < 12 || !Arrays.equals(Arrays.copyOf(data, 4), MAGIC))
			throw new IllegalArgumentException("not a design colour file");
		if (data[4] != VERSION || data[5] != part)
			throw new IllegalArgumentException(Text.get("designs.version", data[4], data[5]));
		int n = ByteBuffer.wrap(data).getInt(8);
		if (n < 0 || data.length != 12 + 9L * n)
			throw new IllegalArgumentException(Text.get("designs.size", n));
		int[] out = new int[n * 3];
		for (int i = 0; i < out.length; i++)
		{
			int o = 12 + i * 3;
			out[i] = (data[o] & 255) << 16 | (data[o + 1] & 255) << 8 | (data[o + 2] & 255);
		}
		return out;
	}

	/**
	 * Design {@code id}'s corner colours for {@code mesh} (its part, at high or low detail), or null when there is
	 * no such file or it doesn't fit the mesh (the mesh's own colours are drawn then).
	 */
	public static int[] colours(String id, boolean high, BakedBoardGeometry.Mesh mesh)
	{
		String key = id + (high ? ".high" : ".low");
		int[] c;
		synchronized (CACHE)
		{
			c = CACHE.get(key);
			if (c == null)
			{
				c = load(key, mesh.part);
				CACHE.put(key, c);
			}
		}
		return c.length == mesh.cornerRgb.length ? c : null;
	}

	private static int[] load(String key, int part)
	{
		try (InputStream in = DesignColours.class.getResourceAsStream(DIR + key + ".rgb"))
		{
			return in == null ? new int[0] : parse(in.readAllBytes(), part);
		}
		catch (IOException | IllegalArgumentException e)
		{
			log.warn("RuneSkate: design colours {} could not be read", key, e);
			return new int[0];
		}
	}
}

package com.gielinorskate.render;

/**
 * Whether the puppet's last draw had a model, handed from the puppet (which fetches the player's model at
 * draw time anyway) to {@link SkaterAnimator}'s {@link PoseGuard}, so the animator need not build the animated
 * model a third time each frame. A report is used once; with none since the last check (the puppet was not
 * drawn) the animator fetches the model itself. Client thread only.
 */
public final class DrawnModelReport
{
	private boolean fresh;
	private boolean hadModel;

	/** The puppet drew; {@code hasModel} is whether it had a model to draw. */
	void report(boolean hasModel)
	{
		hadModel = hasModel;
		fresh = true;
	}

	/** True when a draw was reported since the last {@link #take()} or {@link #clear()}. */
	boolean isFresh()
	{
		return fresh;
	}

	/** The latest report, consuming it. Only meaningful when {@link #isFresh()}. */
	boolean take()
	{
		fresh = false;
		return hadModel;
	}

	/** Forgets any report (a new session starts). */
	void clear()
	{
		fresh = false;
		hadModel = false;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.FootPhysics;
import com.gielinorskate.physics.SkaterState;

/**
 * The walker's body: which OSRS pose animation fits its speed (idle, walk or run, with hysteresis so the
 * 0.1 s speed-up never flickers between them), and the {@link SkaterPoseRig} signals for an on-foot frame (a
 * jump's take-off, tuck and landing; a fall barely bends the knees). Pure; one per walker (local or ghost).
 */
public final class FootBody
{
	public enum Gait
	{
		IDLE,
		WALK,
		RUN
	}

	/** u/s: standing starts walking above this, walking stops below WALK_TO_IDLE. */
	static final float IDLE_TO_WALK = 40f;
	static final float WALK_TO_IDLE = 20f;
	/**
	 * u/s: walking breaks into a run above this (between the walk, 320, and the sprint, 853), a run slows below
	 * RUN_TO_WALK (still above the walk, so a steady walk never runs).
	 */
	static final float WALK_TO_RUN = 1.25f * FootPhysics.WALK_SPEED;
	static final float RUN_TO_WALK = 1.1f * FootPhysics.WALK_SPEED;

	private Gait gait = Gait.IDLE;
	private boolean wasAirborne;
	/** Vertical speed last seen in the air, for the landing squash. */
	private float airSpeed;

	/** The gait at {@code speed} u/s coming from {@code current}; in the air the body stands for the tuck. */
	public static Gait gait(Gait current, float speed, boolean airborne)
	{
		if (airborne)
			return Gait.IDLE;
		switch (current)
		{
			case RUN:
				return speed >= RUN_TO_WALK ? Gait.RUN : speed >= WALK_TO_IDLE ? Gait.WALK : Gait.IDLE;
			case WALK:
				return speed > WALK_TO_RUN ? Gait.RUN : speed >= WALK_TO_IDLE ? Gait.WALK : Gait.IDLE;
			default:
				return speed > WALK_TO_RUN ? Gait.RUN : speed > IDLE_TO_WALK ? Gait.WALK : Gait.IDLE;
		}
	}

	public Gait gait()
	{
		return gait;
	}

	/**
	 * One on-foot frame into {@code s} (every field set), and the gait updated.
	 *
	 * @param jumping the flight is a jump (not a fall)
	 * @param verticalSpeed up-positive u/s
	 */
	public void fill(SkaterPoseRig.Signals s, float speed, boolean airborne, boolean jumping, float verticalSpeed)
	{
		gait = gait(gait, speed, airborne);
		boolean tookOff = airborne && !wasAirborne;
		boolean landed = !airborne && wasAirborne;
		s.state = airborne ? SkaterState.AIRBORNE : SkaterState.ROLLING;
		s.onFoot = true;
		s.speed = 0f;
		s.carveRate = 0f;
		s.charge = 0f;
		s.verticalSpeed = airborne ? verticalSpeed : 0f;
		s.boardPitch = 0f;
		s.hold = null;
		s.grabHand = 0;
		s.flipping = false;
		s.popped = tookOff && jumping;
		s.rolledOff = tookOff && !jumping;
		s.landed = landed;
		s.bailed = false;
		s.landingSpeed = landed ? Math.abs(airSpeed) : 0f;
		s.pushed = false;
		s.proceduralPush = false;
		s.bodyFlipAngle = 0f;
		if (airborne)
			airSpeed = verticalSpeed;
		wasAirborne = airborne;
	}

	public void reset()
	{
		gait = Gait.IDLE;
		wasAirborne = false;
		airSpeed = 0f;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.FootPhysics;

/**
 * Plays the walker's OSRS walk or run pose animation faster than the game does, so its feet keep up with the
 * walker's (faster than OSRS) speed: the game advances the pose animation at its own rate, and this adds the
 * missing frames on top ({@code Actor.setPoseAnimationFrame}). Frame lengths are client ticks (20 ms). Pure.
 */
public final class GaitPlayback
{

	/** The frame stepped, and the extra client ticks owed to the animation that did not yet make a whole frame. */
	private final AnimClock clock = new AnimClock();

	/**
	 * How many times the game's speed the gait animation should play at for a walker at {@code speed} u/s: the
	 * walk against the game's walk, the run against the game's run. Never below 1 (frames are only ever added).
	 */
	public static float rate(FootBody.Gait gait, float speed)
	{
		float r = gait == FootBody.Gait.IDLE ? 1f
			: speed / (gait == FootBody.Gait.WALK ? FootPhysics.GAME_WALK_SPEED : FootPhysics.GAME_RUN_SPEED);
		return r > 1f ? Math.min(3f, r) : 1f;
	}

	/**
	 * One frame of {@code dt} seconds at {@code rate} with the animation at {@code frame}: the frame to jump to, or
	 * -1 to leave the animation alone (nothing owed yet, or an animation this cannot step).
	 */
	public int advance(int frame, int[] frameLengths, float rate, float dt)
	{
		if (frameLengths == null || frame < 0 || frame >= frameLengths.length || !(dt > 0f))
		{
			reset();
			return -1;
		}
		clock.frame = frame;
		clock.ticks += Math.max(0f, rate - 1f) * dt * AnimClock.TICKS_PER_SECOND;
		return clock.run(frameLengths) ? clock.frame : -1;
	}

	/** Forgets the time owed (a new animation). */
	public void reset()
	{
		clock.reset();
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;
import com.gielinorskate.tricks.Grabs;
import com.gielinorskate.tricks.Trick;
import java.util.EnumMap;
import java.util.Map;

/**
 * Each grab's own pose: the body reaches for its part of the board (the upper body tipping along the board toward
 * the nose or tail, and rolling toward the toe or heel side), and the board tweaks toward the hand (pitch lifting the
 * grabbed end, see {@link #boardPitch}; roll, toe edge up > 0, the opposite of a carve's lean into the turn). A tweak holds the same pose
 * 1.6 times further. Zero for anything that is not a grab. Pure; shared with party ghosts.
 */
public final class GrabPose
{
	/** Board-model height (y up negative) of the deck's edge, where a hand grabs the side of the board. */
	static final float EDGE_Y = -14f;
	/**
	 * Per grab: its pose and where on the board the hand holds (the columns are described in text/data.properties,
	 * under grabpose).
	 */
	private static final Map<Trick, float[]> POSES = new EnumMap<>(Trick.class);

	static
	{
		for (String g : Text.get("grabpose.grabs").split(" "))
			POSES.put(Trick.valueOf(g), Text.floats("grabpose." + g));
	}

	private GrabPose()
	{
	}

	/** Radians the upper body tips along the board, + toward the nose (BodyPose.torsoLean for regular stance). */
	public static float torsoLean(Trick grab)
	{
		return value(grab, 0);
	}

	/** Radians of body roll, BodyPose's sense: negative leans the head toward the chest (the toe side). */
	public static float bodyRoll(Trick grab)
	{
		return value(grab, 1);
	}

	/**
	 * Extra board pitch, radians, in the drawn board's sense (BoardPlacement.pose: + turns the board's +z end up).
	 * Each grab lifts the end its hand holds: a spot toward the nose ({@link #grabAlong} > 0) sits at board -z for
	 * regular stance (GrabReach), so nose-end grabs pitch negative and tail-end grabs positive. (They were the other
	 * way round, which dipped the grabbed end away from the hand.)
	 */
	public static float boardPitch(Trick grab)
	{
		return value(grab, 2);
	}

	/** Extra board roll, radians, toe edge up > 0. */
	public static float boardRoll(Trick grab)
	{
		return value(grab, 3);
	}

	/** The grab point's distance along the board, + toward the nose (0 for anything that is not a grab). */
	public static float grabAlong(Trick grab)
	{
		return at(grab, 4, 0f);
	}

	/** The grab point's distance across the board, - toward the toe edge (the chest side), + the heel edge. */
	public static float grabAcross(Trick grab)
	{
		return at(grab, 5, 0f);
	}

	/** The grab point's board-model height (y down; the deck top is at -16). */
	public static float grabBoardY(Trick grab)
	{
		return at(grab, 6, EDGE_Y);
	}

	/** True for a grab (or its tweak): the hand reaches for the board. */
	public static boolean reaches(Trick t)
	{
		return POSES.containsKey(plain(t));
	}

	/**
	 * The hand a grab is usually done with when the grabbing key is not known (a party ghost): the front (left) hand
	 * for a melon, mute and nosegrab, the back (right) hand for the rest.
	 */
	public static boolean usualLeftHand(Trick grab)
	{
		Trick g = plain(grab);
		return g == Trick.MELON || g == Trick.MUTE || g == Trick.NOSEGRAB;
	}

	/**
	 * Whether the left (front) hand holds {@code grab}: each grab's own hand (front for a melon, mute and nosegrab, back
	 * for an indy, stalefish and crail, and their tweaks), whichever key picked it, so the hand never reaches across the
	 * body. (The grab keys pick an Indy with Q, the left hand, and a Melon with E when not aimed; drawn with that hand
	 * the arm crossed in front of the crotch to the middle of the board.) A tailgrab is held with the key's hand
	 * ({@code keyHand} +1 left, -1 right; 0 not known: the back hand).
	 */
	public static boolean leftHand(Trick grab, int keyHand)
	{
		return plain(grab) == Trick.TAILGRAB && keyHand != 0 ? keyHand > 0 : usualLeftHand(grab);
	}

	/** The grab a tweak is of, or {@code grab} itself. */
	private static Trick plain(Trick grab)
	{
		Trick plain = Grabs.untweaked(grab);
		return plain != null ? plain : grab;
	}

	private static float value(Trick grab, int i)
	{
		return (Grabs.untweaked(grab) != null ? 1.6f : 1f) * at(grab, i, 0f);
	}

	/** Entry {@code i} of the grab's (or its plain grab's) row, {@code none} for anything that is not a grab. */
	private static float at(Trick grab, int i, float none)
	{
		float[] p = POSES.get(plain(grab));
		return p == null ? none : p[i];
	}
}

package com.gielinorskate.render;

import lombok.Getter;

/**
 * Where the walker's right hand is, read off the puppet's animated mesh each time it is drawn, so the carried
 * board follows the hand through the walk and run cycles instead of hanging at a fixed spot beside the body. Model
 * space of the puppet (y down, soles at 0, facing -z, the right hand on the -x side). Eased lightly toward each new
 * reading (time constant 0.025 s, so the board keeps up with the swing); with no reading (the mesh does not look like
 * a body, or nothing was drawn for 10 frames) it eases back to the fixed anchor {@link CarryPose#HAND_SIDE} /
 * {@link CarryPose#HAND_HEIGHT}. Pure; client thread only.
 */
public final class HandAnchor
{
	/** The latest reading is in its {@code hand}. */
	private final ArmLocator arm = new ArmLocator();
	private boolean haveRead;
	private int framesSinceRead = Integer.MAX_VALUE;
	/** Reads the hand only while active (on foot, board carried): the scan costs a few passes over the mesh. */
	@Getter
	private boolean active;
	private boolean placed;
	private float x;
	private float y;
	private float z;

	public void setActive(boolean active)
	{
		if (active && !this.active)
			reset();
		this.active = active;
	}

	/** The puppet's mesh as drawn now (first {@code n} vertices). */
	public void sample(float[] xs, float[] ys, float[] zs, int n)
	{
		if (active)
		{
			// the right hand: the model's -x side
			haveRead = arm.locate(xs, ys, zs, n, -1f) && plausible(arm.hand);
			framesSinceRead = haveRead ? 0 : framesSinceRead;
		}
	}

	/** One frame: eases the anchor toward the latest reading, or the fixed anchor without one. */
	public void step(float dt)
	{
		if (framesSinceRead < Integer.MAX_VALUE)
			framesSinceRead++;
		boolean useRead = haveRead && framesSinceRead <= 10;
		float tx = useRead ? arm.hand[0] : -CarryPose.HAND_SIDE;
		float ty = useRead ? arm.hand[1] : -CarryPose.HAND_HEIGHT;
		float tz = useRead ? arm.hand[2] : 0f;
		x = placed ? PoseSmoothing.approach(x, tx, dt, 0.025f) : tx;
		y = placed ? PoseSmoothing.approach(y, ty, dt, 0.025f) : ty;
		z = placed ? PoseSmoothing.approach(z, tz, dt, 0.025f) : tz;
		placed = true;
	}

	/** Forgets the readings: the next step starts at the fixed anchor (or a reading taken since). */
	public void reset()
	{
		haveRead = false;
		framesSinceRead = Integer.MAX_VALUE;
		placed = false;
	}

	/** The hand, puppet model space. */
	public float x()
	{
		return x;
	}

	public float y()
	{
		return y;
	}

	public float z()
	{
		return z;
	}

	/** Above the soles, the right hand on the right, and no further than 160 units from the origin on any axis. */
	private static boolean plausible(float[] p)
	{
		for (float v : p)
		{
			if (!(Math.abs(v) <= 160f))
				return false;
		}
		return p[1] < 0f && p[0] < 0f;
	}
}

package com.gielinorskate.render;

/**
 * The player's own idle pose while the animator replaces it with skate poses, so exiting gives back the right
 * one. The game can set a new idle pose while skating (a weapon wielded from the inventory): any pose found on the
 * player that is not the one last written here came from the game, and becomes the pose given back. Pure.
 */
final class IdlePoseTracker
{
	private static final int NONE = Integer.MIN_VALUE;

	private int saved;
	private int written = NONE;

	/** Skating starts with the player's idle pose {@code current}. */
	void start(int current)
	{
		saved = current;
		written = NONE;
	}

	/** The animator set the player's idle pose to {@code pose}. */
	void wrote(int pose)
	{
		written = pose;
	}

	/**
	 * The player's idle pose is {@code current} now (read before writing).
	 *
	 * @return true when the game changed it since the last write
	 */
	boolean observe(int current)
	{
		if (written != NONE && current == written)
			return false;
		boolean changed = written != NONE;
		saved = current;
		written = NONE;
		return changed;
	}

	/** The player's own idle pose, to give back on exit (and to stand in on foot). */
	int restorePose()
	{
		return saved;
	}
}

package com.gielinorskate.render;

/**
 * The knocked-off skater's procedural body: the whole-body tumble about the centre of mass (the body flip's
 * rotation) with a sideways roll and tucked knees in the air; lying flat at the tumble's angle; the knees bending
 * as it rises. With an OSRS lie-down or get-up animation playing, the body is left as animated. Pure.
 */
public final class KnockdownBody
{
	private KnockdownBody()
	{
	}

	/**
	 * @param animated an OSRS animation draws this stage (the lie-down or get-up), not the procedural pose. In the air
	 * the knees tuck 0.25 (1 - legScale) and the upper body folds 0.3; the knees bend 0.3 through the middle of a
	 * procedural get-up.
	 */
	public static void write(KnockdownPose k, boolean animated, BodyPose out)
	{
		out.neutral();
		if (animated && k.stage != KnockdownPose.Stage.AIR)
			return;
		out.flip = k.bodyAngle;
		out.flipPivotY = BoardPlacement.puppetFlipPivotY();
		if (k.stage == KnockdownPose.Stage.AIR)
		{
			out.roll = k.bodyRoll;
			out.legScale = 1f - 0.25f;
			out.torsoBend = 0.3f;
		}
		else if (k.stage == KnockdownPose.Stage.GET_UP)
			out.legScale = 1f - 0.3f * (float) Math.sin(Math.PI * Math.max(0f, Math.min(1f, k.progress)));
	}
}

package com.gielinorskate.render;

import lombok.AllArgsConstructor;

/**
 * The knocked-off skater and its board as drawn this frame (the session's knockdown, snapshotted per fixed step and
 * blended between steps). Immutable and pure.
 */
@AllArgsConstructor
public final class KnockdownPose
{
	public enum Stage
	{
		/** Thrown off and tumbling. */
		AIR,
		/** Down, after the impact. */
		LIE,
		/** Getting up. */
		GET_UP
	}

	public final Stage stage;
	/** 0..1 through the lie-down or get-up. */
	public final float progress;
	/** The body's lowest point (its feet when upright). */
	public final float bodyX;
	public final float bodyY;
	public final float bodyH;
	/** Where the body faces (0 = north, clockwise): the tumble turns it about the side axis of this. */
	public final float facing;
	/** Tumble about the side axis, raw: + tips the head toward the facing. */
	public final float bodyAngle;
	/** Sideways roll. */
	public final float bodyRoll;
	/** The board: where its wheels are, its nose, its flip (roll) and end-over-end (pitch), raw. */
	public final float boardX;
	public final float boardY;
	public final float boardH;
	public final float boardYaw;
	public final float boardRoll;
	public final float boardPitch;

	/**
	 * {@code alpha} (0..1, clamped) of the way from {@code a} (the older step) to {@code b}; the stage and progress
	 * are {@code b}'s. Not blended (b itself) without an a, or across a jump of more than
	 * {@link RenderPose#MAX_LERP_DISTANCE}.
	 */
	public static KnockdownPose lerp(KnockdownPose a, KnockdownPose b, float alpha)
	{
		if (a == null
			|| Math.hypot(b.bodyX - a.bodyX, b.bodyY - a.bodyY) > RenderPose.MAX_LERP_DISTANCE
			|| Math.abs(b.bodyH - a.bodyH) > RenderPose.MAX_LERP_DISTANCE
			|| Math.hypot(b.boardX - a.boardX, b.boardY - a.boardY) > RenderPose.MAX_LERP_DISTANCE)
			return b;
		float t = PushCycle.clamp01(alpha);
		return new KnockdownPose(b.stage, b.progress,
			RenderPose.mix(a.bodyX, b.bodyX, t), RenderPose.mix(a.bodyY, b.bodyY, t), RenderPose.mix(a.bodyH, b.bodyH, t),
			RenderPose.mixAngle(a.facing, b.facing, t),
			RenderPose.mix(a.bodyAngle, b.bodyAngle, t), RenderPose.mix(a.bodyRoll, b.bodyRoll, t),
			RenderPose.mix(a.boardX, b.boardX, t), RenderPose.mix(a.boardY, b.boardY, t), RenderPose.mix(a.boardH, b.boardH, t),
			RenderPose.mixAngle(a.boardYaw, b.boardYaw, t),
			RenderPose.mix(a.boardRoll, b.boardRoll, t), RenderPose.mix(a.boardPitch, b.boardPitch, t));
	}

	/** How far up the board is drawn above its wheels' height when flipped by {@code roll}: its deck upside down. */
	public static float boardLift(float roll)
	{
		return BoardGeometry.BOARD_TOP * (1f - (float) Math.cos(roll)) / 2f;
	}
}

package com.gielinorskate.render;

/**
 * A party ghost's body, drawn without ever touching the member's real character: the member's model is requested
 * from the client, and only when {@link BufferProbe} proves this frame that it is the per-request buffer the client
 * rebuilds on every request (so nothing written to it lasts past the draw, nor reaches the member's own model) is it
 * used as a canvas. Our {@link MeshSnapshot} of the member's standing frame is copied over it, an OSRS animation
 * of our choosing ({@link Layer}: the client animating that canvas, never the member's character) goes on top, then
 * the procedural {@link BodyPose}. Without a matching snapshot the frame is only deformed, as before; without the
 * proof it is drawn as is. Pure (generic over the model type), so the safety logic is tested without a client.
 */
public final class LayeredBody
{
	/** A model's vertices and faces. */
	public interface Mesh<M> extends BufferProbe.Mesh<M>
	{
		int faces(M m);
	}

	/**
	 * Animates the canvas in place; returns it (the same object, animated), or null when nothing was applied (the
	 * canvas may then be half written: it is overwritten again).
	 */
	public interface Layer<M>
	{
		M apply(M canvas);
	}

	private LayeredBody()
	{
	}

	/**
	 * The model to draw this frame.
	 *
	 * @param key the member's appearance now: a snapshot taken under another key is not used
	 * @param mayTake the member's character stands in its plain idle now: a missing or stale snapshot may be taken
	 * @param layer the OSRS animation on top of the snapshot, or null for none
	 */
	public static <M> M drawable(BufferProbe.Source<M> source, Mesh<M> mesh, MeshSnapshot snap, int key,
		boolean mayTake, Layer<M> layer, BodyPose pose, BufferProbe.Probe<M> probe)
	{
		if (!BufferProbe.prove(source, mesh, probe))
			return probe.drawn;
		M b = probe.drawn;
		int n = mesh.count(b);
		int faces = mesh.faces(b);
		float[] xs = mesh.xs(b);
		float[] ys = mesh.ys(b);
		float[] zs = mesh.zs(b);
		if (snap.matches(n, faces, key))
			snap.copyInto(xs, ys, zs);
		else if (mayTake)
			snap.take(xs, ys, zs, n, faces, key);
		else
		{
			// no snapshot of this appearance yet: the live frame, deformed (no layer: it would double the animation)
			deform(mesh, b, pose);
			return b;
		}
		if (layer != null)
		{
			M l = layer.apply(b);
			if (mesh.count(b) != n || mesh.xs(b) != xs || mesh.ys(b) != ys || mesh.zs(b) != zs)
				// the canvas is no longer the mesh we copied into: drawn as the client left it
				return b;
			if (l != b)
				// not animated in place: the plain snapshot (the canvas may have been half written)
				snap.copyInto(xs, ys, zs);
		}
		deform(mesh, b, pose);
		return b;
	}

	private static <M> void deform(Mesh<M> mesh, M b, BodyPose pose)
	{
		if (!pose.isNeutral())
			MeshDeformer.deform(mesh.xs(b), mesh.ys(b), mesh.zs(b), mesh.count(b), pose);
		mesh.deformed(b);
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;

/**
 * Physics snaps the skater onto a rail in one step (up to the grind snap distance sideways and down).
 * This draws that lock as a short slide instead: on the frame the pose enters GRINDING, the drawn
 * position and heading start from the last drawn pose and ease onto the rail over {@link #DURATION}.
 * Pure; feed it every frame's pose.
 */
public final class LockBlend
{
	static final float DURATION = 0.09f;

	private RenderPose last;
	private boolean active;
	private float elapsed;
	private float offX;
	private float offY;
	private float offH;
	private float offHeading;

	/** Forgets the last drawn pose (a new session). */
	public void reset()
	{
		last = null;
		active = false;
	}

	/** The pose to draw this frame. */
	public RenderPose apply(RenderPose pose, float dt)
	{
		if (last != null && pose.state == SkaterState.GRINDING && last.state != SkaterState.GRINDING)
		{
			offX = last.x - pose.x;
			offY = last.y - pose.y;
			offH = last.h - pose.h;
			offHeading = Angles.wrap(last.heading - pose.heading);
			elapsed = 0f;
			active = true;
		}
		else if (active)
			elapsed += dt;

		active &= elapsed < DURATION;
		float u = elapsed / DURATION;
		float k = 1f - u * u * (3f - 2f * u);
		RenderPose out = !active ? pose : new RenderPose(pose.x + offX * k, pose.y + offY * k, pose.h + offH * k,
			Angles.wrap(pose.heading + offHeading * k), pose.cameraHeading, pose.boardRoll, pose.boardYaw,
			pose.boardPitch, pose.state, pose.hold);
		last = out;
		return out;
	}
}

package com.gielinorskate.render;

/**
 * Applies a {@link BodyPose} to a player mesh's vertex arrays in place. Pure and allocation-free.
 *
 * <p>Puppet model space: x along the board (the puppet is drawn turned 90 degrees from the board), y down
 * with the soles at y = 0, z out of the back (actors face -z). How it maps onto the board's own model
 * space follows from RuneLite's {@code Perspective.modelToCanvas} (model x -> local x, model z -> local y,
 * {@code x' = x cos + z sin}, {@code z' = z cos - x sin}) and the puppet being drawn 512 orientation units
 * past the board: board x = puppet z, board z = -puppet x. So the same physical roll as the board's
 * {@code BoardGeometry.rotate} roll is the (z, y) rotation below, and the same pitch as
 * {@code BoardPlacement.pose} is the (x, y) rotation below.
 *
 * <p>Order per vertex: knees bend (legs squash below the hips, the upper body drops rigidly; in a grab the knees
 * fold up toward the chest instead and the feet rise to the lifted board), the torso folds forward at the hips,
 * then the whole body pitches about the contact truck and rolls about the board's long axis through the feet; in
 * a grab the hand then reaches for the board and the free arm swings out; last, a front or back flip turns the
 * whole body about the centre of mass ({@link BodyPose#flip}), the same rotation {@link BoardPlacement#pose} gives
 * the board.
 */
public final class MeshDeformer
{
	/** Foot height (ankle above the sole) as a fraction of the hip height: below it the foot stays flat on the board. */
	private static final float FOOT_FRACTION = 0.1f;
	/** Units below the hip line over which the push leg (or a grab's knee fold) blends in, per unit of hip height. */
	private static final float LEG_BLEND = 0.25f;
	/** Units either side of the knee over which the shin's extra bend blends in. */
	private static final float KNEE_BAND = 8f;
	/** Scratch (z, y) of a leg point being bent (client thread only). */
	private static final float[] ZY = new float[2];

	private MeshDeformer()
	{
	}

	/**
	 * Hip height (positive units above the soles) of a mesh whose highest vertex is at {@code topY} (a model height
	 * of 200 when the mesh has no vertex above the soles).
	 */
	static float hipHeight(float topY)
	{
		return Math.max(50f, Math.min(120f, 0.45f * (topY < 0f ? -topY : 200f)));
	}

	/** Deforms the first {@code n} vertices of {@code xs, ys, zs} by {@code pose}. */
	public static void deform(float[] xs, float[] ys, float[] zs, int n, BodyPose pose)
	{
		float top = 0f;
		for (int i = 0; i < n; i++)
			top = Math.min(top, ys[i]);
		float hip = hipHeight(top);
		Body body = Body.set(pose, hip, pose.legWeight > 1e-4f ? Leg.solve(xs, ys, zs, n, hip, pose) : null);
		if (body.folding)
		{
			// the knees fold about the mean z of the lower legs (below the hanging hands)
			float sum = 0f;
			int count = 0;
			for (int i = 0; i < n; i++)
			{
				if (ys[i] > -ArmLocator.LOWER_LEGS * hip)
				{
					sum += zs[i];
					count++;
				}
			}
			body.hz = count == 0 ? 0f : sum / count;
		}
		// a grab: both arms' weights and shoulders from the mesh as animated, before anything moves
		boolean grabbing = pose.armWeight > 1e-4f || pose.kneeFold > 1e-4f;
		Arm arm = grabbing ? Arm.find(Arm.GRAB, xs, ys, zs, n, pose.armSide) : null;
		Arm free = arm != null ? Arm.find(Arm.FREE, xs, ys, zs, n, -pose.armSide) : null;
		// in a grab the arms go with the upper body, never squashed down with the legs: a hand hanging below the hip
		// line stayed at the crotch while the chest folded forward
		float hold = arm == null ? 0f : Math.max(PushCycle.clamp01(pose.armWeight), PushCycle.clamp01(pose.kneeFold));
		for (int i = 0; i < n; i++)
		{
			float rigid = arm == null ? 0f : hold * (free == null ? arm.weights[i] : Math.max(arm.weights[i], free.weights[i]));
			body.apply(xs[i], ys[i], zs[i], rigid);
			xs[i] = body.x;
			ys[i] = body.y;
			zs[i] = body.z;
		}
		// the hand reaches for the board where it is drawn, the other arm swings out for balance (before the flip,
		// which turns body and board together)
		if (arm != null && pose.armWeight > 1e-4f)
		{
			// a lifted board is that much nearer the hips: the opposite of the deck lift
			float[] t = arm.target;
			BoardPlacement.grabTarget(pose.grabAlong, pose.grabAcross, pose.grabBoardY, pose.boardRoll,
				pose.boardPitch, pose.deckLift - pose.boardLift, t);
			arm.reach(xs, ys, zs, n, body, t[0], t[1], t[2], PushCycle.clamp01(pose.armWeight), true);
			if (free != null)
				free.balance(xs, ys, zs, n, body, PushCycle.clamp01(pose.armWeight));
		}
		if (Math.abs(pose.flip) > 1e-6f)
		{
			// the whole body turns about the centre of mass with the board (BoardPlacement.pose's flip)
			float cf = (float) Math.cos(pose.flip);
			float sf = (float) Math.sin(pose.flip);
			for (int i = 0; i < n; i++)
			{
				float ry = ys[i] - pose.flipPivotY;
				float fx = xs[i] * cf - ry * sf;
				ys[i] = xs[i] * sf + ry * cf + pose.flipPivotY;
				xs[i] = fx;
			}
		}
	}

	/**
	 * Turns {@link #ZY} by {@code angle} times the smoothstep of its y over {@code pivot} +- {@code band}, about
	 * the height {@code pivot}.
	 */
	private static void bend(float angle, float pivot, float band)
	{
		float t = angle * PushCycle.smoothstep(pivot - band, pivot + band, ZY[1]);
		ZY[1] -= pivot;
		turn((float) Math.cos(t), (float) Math.sin(t));
		ZY[1] += pivot;
	}

	/** Turns {@link #ZY} by the angle of cosine {@code c} and sine {@code s}. */
	private static void turn(float c, float s)
	{
		float z = ZY[0] * c - ZY[1] * s;
		ZY[1] = ZY[0] * s + ZY[1] * c;
		ZY[0] = z;
	}

	/**
	 * The whole-body part of the pose for one point, flip excluded: the knees (or the push leg), the torso fold and
	 * lean above the hips, then the pitch about the contact truck and the roll about the board's long axis. One
	 * reused instance (client thread only).
	 */
	private static final class Body
	{
		private static final Body SCRATCH = new Body();

		float hip;
		float s;
		float hipY;
		float cb;
		float sb;
		float cl;
		float sl;
		float cp;
		float sp;
		float cr;
		float sr;
		float px;
		Leg leg;
		/** A grab's knee fold (or a lifted board): the legs reach from the hips to the feet at -lift. */
		boolean folding;
		float fold;
		/** Hip-to-sole distance over the hip height. */
		float k;
		/** The leg's length factor, when the fold alone cannot reach (k above 1 or below the tightest fold). */
		float len;
		/** The thigh's angle from straight down (the shin turns back by the same), with its cos and sin. */
		float knee;
		float ck;
		float sk;
		/** Model z the legs fold about. */
		float hz;
		/** Units the soles are lifted (with the board): the pitch and roll turn about them there. */
		float lift;
		/** Output of {@link #apply}. */
		float x;
		float y;
		float z;

		static Body set(BodyPose pose, float hip, Leg leg)
		{
			Body b = SCRATCH;
			b.hip = hip;
			b.s = pose.legScale;
			b.hipY = -hip * pose.legScale;
			// the torso folds toward the chest (-z): the roll rotation by -bend
			b.cb = (float) Math.cos(-pose.torsoBend);
			b.sb = (float) Math.sin(-pose.torsoBend);
			b.cl = (float) Math.cos(pose.torsoLean);
			b.sl = (float) Math.sin(pose.torsoLean);
			b.cp = (float) Math.cos(pose.pitch);
			b.sp = (float) Math.sin(pose.pitch);
			b.cr = (float) Math.cos(pose.roll);
			b.sr = (float) Math.sin(pose.roll);
			b.px = pose.pivotX;
			b.leg = leg;
			b.lift = Float.isNaN(pose.boardLift) ? 0f : Math.max(0f, Math.min(hip, pose.boardLift));
			b.fold = PushCycle.clamp01(pose.kneeFold);
			b.folding = b.fold > 1e-4f || b.lift > 1e-4f;
			b.hz = 0f;
			// the hips to the soles: the folded thigh and shin (to the ankle) plus the flat foot below it
			b.k = (hip * pose.legScale - b.lift) / hip;
			b.len = 1f;
			float c = 1f;
			if (b.k >= 1f)
				b.len = b.k;
			else
			{
				c = (b.k - FOOT_FRACTION) / (1f - FOOT_FRACTION);
				// the knees never fold tighter than cos 0.15 of the thigh's angle from straight down; the legs
				// shorten instead
				if (!(c >= 0.15f))
				{
					c = 0.15f;
					b.len = Math.max(0f, b.k) / ((1f - FOOT_FRACTION) * 0.15f + FOOT_FRACTION);
				}
			}
			b.knee = (float) Math.acos(c);
			b.ck = c;
			b.sk = (float) Math.sin(b.knee);
			return b;
		}

		/**
		 * Poses one point; {@code rigid} (0..1) moves it with the upper body even below the hip line (a grab's arms,
		 * whose hands hang lower than the hips).
		 */
		void apply(float x, float y, float z, float rigid)
		{
			// height above the hips (negative), the same before and after the knees bend
			float dy = y + hip;
			if (y > -hip)
			{
				float w = leg == null ? 0f : leg.weight(x, y);
				float lx = x;
				float ly;
				float lz = z;
				if (w > 0f)
				{
					leg.move(x, y, z, w);
					lx = leg.x;
					ly = leg.y;
					lz = leg.z;
				}
				else if (folding)
				{
					foldLeg(z, dy);
					ly = this.y;
					lz = this.z;
				}
				else
					ly = y * s;
				torso(x, dy, z, 1f);
				x = lx + (this.x - lx) * rigid;
				y = ly + (this.y - ly) * rigid;
				z = lz + (this.z - lz) * rigid;
			}
			else
			{
				// the fold and lean fade in over 30 units above the hips, so there is no crease at the hip line
				float w = Math.min(1f, -dy / 30f);
				torso(x, dy, z, w + (1f - w) * rigid);
				x = this.x;
				y = this.y;
				z = this.z;
			}
			// about the soles: lifted with the board in a grab, so the feet stay on it
			y += lift;
			float dx = x - px;
			x = dx * cp - y * sp + px;
			y = dx * sp + y * cp;
			this.x = x;
			this.y = z * sr + y * cr - lift;
			this.z = z * cr - y * sr;
		}

		/**
		 * The upper body's fold and roll (not its lean along the board, nor the pitch) of the direction (dx, dy, dz),
		 * into {@code out}.
		 */
		void turnDirection(float dx, float dy, float dz, float[] out)
		{
			float bz = dz * cb - dy * sb;
			float by = dz * sb + dy * cb;
			out[0] = dx;
			out[1] = bz * sr + by * cr;
			out[2] = bz * cr - by * sr;
		}

		/** The torso's fold and lean about the hips by weight {@code w}; {@code dy} is the height above the hips (y down). */
		private void torso(float x, float dy, float z, float w)
		{
			float bz = z * cb - dy * sb;
			float by = z * sb + dy * cb;
			z += (bz - z) * w;
			dy += (by - dy) * w;
			float lx = x * cl - dy * sl;
			float ly = x * sl + dy * cl;
			this.x = x + (lx - x) * w;
			this.y = dy + (ly - dy) * w + hipY;
			this.z = z;
		}

		/**
		 * A grab's legs for a point {@code rest} below the hips: squashed straight down to the feet at hip * k below
		 * the hips, and by {@link #fold} with the knees folded up toward the chest instead: the thigh swings forward by
		 * the knee angle, the shin back by the same, the foot stays flat; the sole lands on the same spot either way.
		 * The fold fades in below the hips (no crease at the hip line). Writes y and z.
		 */
		private void foldLeg(float z, float rest)
		{
			float squash = hipY + rest * k;
			float a = fold * PushCycle.smoothstep(0f, LEG_BLEND * hip, rest);
			if (a <= 0f)
			{
				this.y = squash;
				this.z = z;
				return;
			}
			ZY[0] = z - hz;
			ZY[1] = rest * len;
			float ankleY = (1f - FOOT_FRACTION) * hip * len;
			// the foot turns forward about the ankle (flat again once the shin has turned back; over 4 units either
			// side of it), the shin back about the knee (halfway from the hip to the ankle, so the shin brings the foot
			// back under the hip) by twice the knee angle, and the whole leg forward about the hip
			bend(knee, ankleY, 4f);
			bend(-2f * knee, 0.5f * ankleY, KNEE_BAND);
			turn(ck, sk);
			this.y = squash + (hipY + ZY[1] - squash) * a;
			this.z = z + (hz + ZY[0] - z) * a;
		}
	}

	/**
	 * A grab's arms ({@link ArmLocator}): the grabbing one turns about the shoulder so the hand points at the grab
	 * point on the board ({@link BoardPlacement#grabTarget}), stretching (capped) to reach it; the free one swings out
	 * for balance. Each vertex follows by its arm weight times the pose's arm weight, so the arm eases in and out and
	 * never tears from the shoulder. At arm weight 0 it is exactly the plain body. Two reused instances (client thread
	 * only).
	 */
	private static final class Arm
	{
		static final Arm GRAB = new Arm();
		static final Arm FREE = new Arm();

		final ArmLocator locator = new ArmLocator();
		final float[] target = new float[3];
		/** Each vertex's arm weight, from the mesh before it moved; grown, never shrunk. */
		float[] weights = new float[0];

		/** The arm on {@code side}, found into {@code a}, or null when the mesh has no arm there. */
		static Arm find(Arm a, float[] xs, float[] ys, float[] zs, int n, float side)
		{
			if (!a.locator.locate(xs, ys, zs, n, side))
				return null;
			if (a.weights.length < n)
				a.weights = new float[n];
			for (int i = 0; i < n; i++)
				a.weights[i] = a.locator.weight(xs[i], ys[i]);
			return a;
		}

		/**
		 * Swings the (already posed) free arm out for balance, by {@code weight}: out an arm's length in the upper
		 * body's frame, folded and rolled with it (not tipped with a nose or tail grab's lean, which would point it at
		 * the ground): out along the board on its own side (0.8), a little up (0.1) and back (0.35, against the fold,
		 * so it ends a little above level).
		 */
		void balance(float[] xs, float[] ys, float[] zs, int n, Body body, float weight)
		{
			float[] sh = locator.shoulder;
			body.apply(sh[0], sh[1], sh[2], 1f);
			float ox = body.x;
			float oy = body.y;
			float oz = body.z;
			float l = locator.armLength;
			body.turnDirection(locator.side * 0.8f * l, -0.1f * l, 0.35f * l, target);
			reach(xs, ys, zs, n, body, ox + target[0], oy + target[1], oz + target[2], weight, false);
		}

		/**
		 * Turns this (already posed) arm's vertices about the shoulder so the hand points at (tx, ty, tz), each vertex
		 * by its arm weight times {@code weight}; with {@code stretch} the arm stretches by the distance ratio, at most
		 * 1.6 (blocky models hide a lot) and shortening to 0.7 at least when the board is nearer than the hand.
		 */
		void reach(float[] xs, float[] ys, float[] zs, int n, Body body, float tx, float ty, float tz, float weight,
			boolean stretch)
		{
			// the shoulder goes where the body put the arm's root
			float[] sh = locator.shoulder;
			body.apply(sh[0], sh[1], sh[2], 1f);
			float ox = body.x;
			float oy = body.y;
			float oz = body.z;
			int h = locator.handIndex;
			float ux = xs[h] - ox;
			float uy = ys[h] - oy;
			float uz = zs[h] - oz;
			tx -= ox;
			ty -= oy;
			tz -= oz;
			float lu = (float) Math.sqrt(ux * ux + uy * uy + uz * uz);
			float lt = (float) Math.sqrt(tx * tx + ty * ty + tz * tz);
			if (!(lu > 1f) || !(lt > 1f) || Float.isInfinite(lu) || Float.isInfinite(lt))
				return;
			// axis u x t, angle between them
			float kx = uy * tz - uz * ty;
			float ky = uz * tx - ux * tz;
			float kz = ux * ty - uy * tx;
			float kl = (float) Math.sqrt(kx * kx + ky * ky + kz * kz);
			float dot = ux * tx + uy * ty + uz * tz;
			// (anti)parallel: no turn, or straight back about any axis across the arm
			boolean flat = kl < 1e-4f * lu * lt;
			boolean alongZ = flat && Math.abs(uz) > 0.9f * lu;
			float angle = flat && dot > 0f ? 0f : (float) Math.atan2(kl, dot);
			kx = flat ? alongZ ? 1f : 0f : kx / kl;
			ky = flat ? 0f : ky / kl;
			kz = flat ? alongZ ? 0f : 1f : kz / kl;
			float s = stretch ? Math.max(0.7f, Math.min(1.6f, lt / lu)) : 1f;
			for (int i = 0; i < n; i++)
			{
				float a = weights[i] * weight;
				if (a <= 0f)
					continue;
				float vx = xs[i] - ox;
				float vy = ys[i] - oy;
				float vz = zs[i] - oz;
				// Rodrigues: v cos + (k x v) sin + k (k . v)(1 - cos), by this vertex's share of the turn
				float c = (float) Math.cos(angle * a);
				float sn = (float) Math.sin(angle * a);
				float kd = (kx * vx + ky * vy + kz * vz) * (1f - c);
				float scale = 1f + (s - 1f) * a;
				xs[i] = ox + (vx * c + (ky * vz - kz * vy) * sn + kx * kd) * scale;
				ys[i] = oy + (vy * c + (kz * vx - kx * vz) * sn + ky * kd) * scale;
				zs[i] = oz + (vz * c + (kx * vy - ky * vx) * sn + kz * kd) * scale;
			}
		}
	}

	/**
	 * The push leg: every vertex below the hips on the {@link BodyPose#legSide} side of the body's centre
	 * plane. Two-bone IK with the knee halfway down: the knee bends forward (toward the chest, -z) when the
	 * target is nearer than the leg is long, the leg stretches (at most 1.3: blocky models hide 30%) when it is
	 * further; the leg then swings about the hip in the board plane to point at the target, and shears sideways
	 * toward it. Each vertex follows by its weight, which fades in below the hip line and over 4 units past the
	 * centre plane (the crotch), so the leg never tears from the body; at weight 0 it is exactly the plain crouch.
	 */
	private static final class Leg
	{
		private static final Leg SCRATCH = new Leg();

		float hip;
		float s;
		float side;
		float cx;
		float hx;
		float hz;
		float weight;
		float stretch;
		float knee;
		float swing;
		float footZ;
		/** Output of {@link #move}. */
		float x;
		float y;
		float z;

		/** The solved leg, or null if no vertex is on the push side. Reuses one instance (client thread only). */
		static Leg solve(float[] xs, float[] ys, float[] zs, int n, float hip, BodyPose pose)
		{
			float minX = Float.MAX_VALUE;
			float maxX = -Float.MAX_VALUE;
			for (int i = 0; i < n; i++)
			{
				if (ys[i] > -hip)
				{
					minX = Math.min(minX, xs[i]);
					maxX = Math.max(maxX, xs[i]);
				}
			}
			Leg l = SCRATCH;
			l.side = pose.legSide < 0f ? -1f : 1f;
			l.cx = (minX + maxX) / 2f;
			float sx = 0f;
			float sz = 0f;
			int count = 0;
			for (int i = 0; i < n; i++)
			{
				if (ys[i] > -hip && (xs[i] - l.cx) * l.side > 0f)
				{
					sx += xs[i];
					sz += zs[i];
					count++;
				}
			}
			if (count == 0)
				return null;
			l.hip = hip;
			l.s = pose.legScale;
			l.hx = sx / count;
			l.hz = sz / count;
			l.weight = Math.min(1f, pose.legWeight);
			l.footZ = pose.footZ;
			// from the (crouched) hip to the target, y down; the leg is hip long
			float dx = pose.footX;
			float dy = pose.footY + hip * l.s;
			float d = (float) Math.hypot(dx, dy);
			l.stretch = d >= hip ? Math.min(1.3f, d / hip) : 1f;
			l.knee = d >= hip ? 0f : (float) Math.acos(Math.max(0f, d / hip));
			l.swing = (float) Math.atan2(dx, dy);
			return l;
		}

		float weight(float vx, float vy)
		{
			float below = PushCycle.smoothstep(0f, LEG_BLEND * hip, vy + hip);
			float across = PushCycle.smoothstep(0f, 4f, (vx - cx) * side);
			return weight * below * across;
		}

		void move(float vx, float vy, float vz, float w)
		{
			float len = s + (stretch - s) * w;
			float b = knee * w;
			float rest = vy + hip;
			ZY[0] = vz - hz;
			ZY[1] = rest * len;
			// the shin turns back about the knee by 2b, then the whole leg forward about the hip by b
			bend(-2f * b, 0.5f * hip * len, KNEE_BAND);
			turn((float) Math.cos(b), (float) Math.sin(b));
			float ux = vx - hx;
			float uy = ZY[1];
			// swing in the board plane about the hip
			float c = (float) Math.cos(swing * w);
			float sn = (float) Math.sin(swing * w);
			x = hx + ux * c + uy * sn;
			y = -hip * s - ux * sn + uy * c;
			z = hz + (ZY[0] + footZ * w * rest / hip);
		}
	}
}

package com.gielinorskate.render;

/**
 * Our own copy of a party member's character mesh (vertex positions only), taken once from a frame the client
 * rebuilt for us and drawn from afterwards, so a ghost's body never follows what the member's real character is
 * doing on this client. Valid for the vertex and face count and appearance key it was taken with. Pure; arrays grow
 * only when a bigger mesh is taken (no allocation per frame).
 */
public final class MeshSnapshot
{
	float[] xs = new float[0];
	private float[] ys = new float[0];
	private float[] zs = new float[0];
	/** Vertices taken; -1 when none (not valid). */
	int count = -1;
	private int faces;
	private int key;

	/** Whether this snapshot was taken from a mesh of {@code count} vertices and {@code faces} faces under {@code key}. */
	public boolean matches(int count, int faces, int key)
	{
		return this.count >= 0 && this.count == count && this.faces == faces && this.key == key;
	}

	/** Copies the first {@code count} vertices. */
	public void take(float[] x, float[] y, float[] z, int count, int faces, int key)
	{
		if (xs.length < count)
		{
			xs = new float[count];
			ys = new float[count];
			zs = new float[count];
		}
		System.arraycopy(x, 0, xs, 0, count);
		System.arraycopy(y, 0, ys, 0, count);
		System.arraycopy(z, 0, zs, 0, count);
		this.count = count;
		this.faces = faces;
		this.key = key;
	}

	/** Writes the snapshot's vertices over the first {@link #count} of these arrays. */
	public void copyInto(float[] x, float[] y, float[] z)
	{
		System.arraycopy(xs, 0, x, 0, count);
		System.arraycopy(ys, 0, y, 0, count);
		System.arraycopy(zs, 0, z, 0, count);
	}

	public void clear()
	{
		count = -1;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.*;
import lombok.AllArgsConstructor;

/**
 * Everything drawn of the on-foot side of a session, one snapshot per frame: the mode, where the board is, the
 * walker, and the mount / dismount blend. Immutable and pure; the walker fields can be blended between two
 * fixed steps ({@link #lerp}). While ON_BOARD the walker fields hold the skater's position (so a dismount blend
 * starts from it) and the board fields are unused.
 */
@AllArgsConstructor
public final class OffBoardPose
{
	public final SkateMode mode;
	/** CARRIED or DROPPED; CARRIED while ON_BOARD. */
	public final BoardState board;
	/** The dropped board: where it lies (feet height of the ground there) and which way its nose points. */
	public final float boardX;
	public final float boardY;
	public final float boardH;
	public final float boardHeading;
	/** The walker's feet. */
	public final float walkerX;
	public final float walkerY;
	public final float walkerH;
	/** Where the body faces (0 = north, clockwise). */
	public final float walkerHeading;
	/** Horizontal speed (u/s): idle / walk / run animation by speed (walk FootPhysics.WALK_SPEED). */
	public final float walkerSpeed;
	/** In the air: a jump or a fall. */
	public final boolean airborne;
	/** The flight is a jump (not a fall); meaningful while airborne. */
	public final boolean jumping;
	/** Up-positive vertical speed (u/s) in the air; 0 on the ground. */
	public final float verticalSpeed;
	/** The latest mount or dismount, and how far through its blend (0..1, 1 when done). */
	public final BoardTransition transition;
	public final float transitionProgress;
	/** The flight is a jump that lands on the carried board (the mount hop): the board comes down under the feet. */
	public final boolean mountJump;

	/**
	 * The walker {@code alpha} (0..1, clamped) of the way from {@code a} (the older step) to {@code b}; every
	 * other field comes from {@code b}. A different mode, or a jump of more than {@link RenderPose#MAX_LERP_DISTANCE},
	 * is not blended.
	 */
	public static OffBoardPose lerp(OffBoardPose a, OffBoardPose b, float alpha)
	{
		if (a == null || a.mode != b.mode
			|| Math.hypot(b.walkerX - a.walkerX, b.walkerY - a.walkerY) > RenderPose.MAX_LERP_DISTANCE
			|| Math.abs(b.walkerH - a.walkerH) > RenderPose.MAX_LERP_DISTANCE)
			return b;
		float t = PushCycle.clamp01(alpha);
		return new OffBoardPose(b.mode, b.board, b.boardX, b.boardY, b.boardH, b.boardHeading,
			RenderPose.mix(a.walkerX, b.walkerX, t), RenderPose.mix(a.walkerY, b.walkerY, t),
			RenderPose.mix(a.walkerH, b.walkerH, t), RenderPose.mixAngle(a.walkerHeading, b.walkerHeading, t),
			b.walkerSpeed, b.airborne, b.jumping, b.verticalSpeed, b.transition,
			b.transitionProgress, b.mountJump);
	}
}

package com.gielinorskate.render;

/**
 * Pure conversions between sRGB and the client's packed 16-bit HSL (6 bits hue, 3 saturation, 7 lightness).
 * {@link #hslToRgb} is the client's colour palette (the same table the GPU shader reproduces); {@link #rgbToHsl}
 * finds the packed colour whose palette entry is nearest the given RGB.
 */
public final class OsrsColor
{
	/** The client's default brightness setting, used when the real one isn't known. */
	public static final double DEFAULT_BRIGHTNESS = 0.8;

	private OsrsColor()
	{
	}

	public static int hue(int hsl)
	{
		return (hsl >> 10) & 63;
	}

	public static int saturation(int hsl)
	{
		return (hsl >> 7) & 7;
	}

	public static int lightness(int hsl)
	{
		return hsl & 127;
	}

	public static int pack(int hue, int saturation, int lightness)
	{
		return (hue & 63) << 10 | (saturation & 7) << 7 | (lightness & 127);
	}

	/** The palette's 0xRRGGBB for a packed HSL colour at a brightness (the client's 0.6 to 0.9; lower is brighter). */
	public static int hslToRgb(int hsl, double brightness)
	{
		double h = hue(hsl) / 64.0 + 0.0078125;
		double s = saturation(hsl) / 8.0 + 0.0625;
		double l = lightness(hsl) / 128.0;
		double q = l < 0.5 ? l * (1.0 + s) : l + s - l * s;
		double p = 2.0 * l - q;
		double tr = h + 1.0 / 3.0;
		double tb = h - 1.0 / 3.0;
		int rgb = channel(p, q, tr > 1.0 ? tr - 1.0 : tr, brightness) << 16 | channel(p, q, h, brightness) << 8
			| channel(p, q, tb < 0.0 ? tb + 1.0 : tb, brightness);
		return rgb == 0 ? 1 : rgb;
	}

	/** As the client: the channel at hue {@code t} quantised to 8 bits, then brightness-adjusted (c^brightness). */
	private static int channel(double p, double q, double t, double brightness)
	{
		double c = 6.0 * t < 1.0 ? p + (q - p) * 6.0 * t : 2.0 * t < 1.0 ? q
			: 3.0 * t < 2.0 ? p + (q - p) * (2.0 / 3.0 - t) * 6.0 : p;
		return Math.min(255, (int) (Math.pow((int) (c * 256.0) / 256.0, brightness) * 256.0));
	}

	/**
	 * The packed HSL colour whose palette entry is nearest {@code rgb} (squared RGB distance): an analytic first
	 * guess, then a hill-climb over neighbours (hue +-1, saturation +-1, lightness +-2) to a local best.
	 */
	public static int rgbToHsl(int rgb, double brightness)
	{
		double inv = 1.0 / brightness;
		double r = Math.pow(((rgb >> 16) & 255) / 256.0, inv);
		double g = Math.pow(((rgb >> 8) & 255) / 256.0, inv);
		double b = Math.pow((rgb & 255) / 256.0, inv);
		double max = Math.max(r, Math.max(g, b));
		double min = Math.min(r, Math.min(g, b));
		double l = (max + min) / 2.0;
		double h = 0.0;
		double s = 0.0;
		if (max > min)
		{
			double d = max - min;
			s = l < 0.5 ? d / (max + min) : d / (2.0 - max - min);
			if (max == r)
				h = (g - b) / d / 6.0;
			else if (max == g)
				h = ((b - r) / d + 2.0) / 6.0;
			else
				h = ((r - g) / d + 4.0) / 6.0;
			if (h < 0.0)
				h += 1.0;
		}
		// hill-climb from the guess: the best of its neighbours, until none is better
		int best = pack((int) Math.floor(h * 64.0), Math.max(0, Math.min(7, (int) Math.floor(s * 8.0))),
			Math.max(0, Math.min(127, (int) Math.round(l * 128.0))));
		long bestError = distance(rgb, hslToRgb(best, brightness));
		for (int step = 0; step < 64; step++)
		{
			int centre = best;
			for (int dh = -1; dh <= 1; dh++)
			{
				for (int ds = -1; ds <= 1; ds++)
				{
					int sat = saturation(centre) + ds;
					if (sat < 0 || sat > 7)
						continue;
					for (int dl = -2; dl <= 2; dl++)
					{
						int lum = lightness(centre) + dl;
						if (lum < 0 || lum > 127)
							continue;
						int candidate = pack(hue(centre) + dh, sat, lum);
						long e = distance(rgb, hslToRgb(candidate, brightness));
						if (e < bestError)
						{
							bestError = e;
							best = candidate;
						}
					}
				}
			}
			if (best == centre)
				break;
		}
		return best;
	}

	/** Squared distance between two 0xRRGGBB colours. */
	static long distance(int a, int b)
	{
		long dr = ((a >> 16) & 255) - ((b >> 16) & 255);
		long dg = ((a >> 8) & 255) - ((b >> 8) & 255);
		long db = (a & 255) - (b & 255);
		return dr * dr + dg * dg + db * db;
	}

	/**
	 * A packed colour's lightness scaled by a light intensity, as the client lights a model: lightness * intensity
	 * / 128, kept within 2..126. {@code intensity} 128 leaves the colour as it is.
	 */
	public static int light(int hsl, int intensity)
	{
		return (hsl & 0xff80) | Math.max(2, Math.min(126, (hsl & 127) * intensity >> 7));
	}
}

package com.gielinorskate.render;

/**
 * Where one puppet object is drawn: local x / y, RuneLite z (grows downward), orientation in JAU (kept as a float
 * so it can be blended), and for a board its roll and pitch. Mutable and reused; {@link #valid} is false until
 * something was set.
 */
public final class Placement
{
	public float x;
	public float y;
	public float z;
	public float jau;
	public float roll;
	public float pitch;
	public boolean valid;

	public void set(float x, float y, float z, float jau, float roll, float pitch)
	{
		this.x = x;
		this.y = y;
		this.z = z;
		this.jau = jau;
		this.roll = roll;
		this.pitch = pitch;
		this.valid = true;
	}

	public void copyFrom(Placement o)
	{
		set(o.x, o.y, o.z, o.jau, o.roll, o.pitch);
		valid = o.valid;
	}

	public void invalidate()
	{
		valid = false;
	}

	/** The orientation as RuneLite takes it: rounded and wrapped to 0..2047. */
	public int orientation()
	{
		return Math.round(jau) & 2047;
	}
}

package com.gielinorskate.render;

/**
 * Detects when an animation leaves the player with no model (some animations don't work on player
 * models), which would make the skater invisible. Pure: feed it one sample per frame.
 */
final class PoseGuard
{

	private int missingFrames;

	/** @return true when the current animations should be reverted to the defaults */
	boolean frame(boolean hasModel)
	{
		missingFrames = hasModel ? 0 : missingFrames + 1;
		if (missingFrames >= 3)
		{
			missingFrames = 0;
			return true;
		}
		return false;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.tricks.Trick;

/** Pure easing curves for the drawn board pose, so nothing visibly jumps in one frame. */
public final class PoseSmoothing
{
	/** Peak nose-up pitch of the pop, in radians. */
	static final float POP_PITCH = 0.45f;
	/** Seconds for the pop pitch to rise to its peak. */
	static final float POP_RISE = 0.05f;
	/** Seconds for the pop pitch to ease back to flat after the peak. */
	static final float POP_FALL = 0.2f;
	/** Time constant (seconds) of the carve lean, manual/grind pitch, slide drop and charge dip smoothing. */
	public static final float POSE_TAU = 0.08f;
	/** A grab's board tweak snaps in faster than the other board poses: 94% of the way in 0.1 s. */
	public static final float GRAB_TAU = 0.035f;

	private PoseSmoothing()
	{
	}

	/**
	 * Pop pitch {@code since} seconds after the pop: rises to {@link #POP_PITCH} over {@link #POP_RISE}
	 * (ease-out), then eases back to 0 over {@link #POP_FALL} (smoothstep). A nollie pops off the nose,
	 * so its pitch is the same nose-down.
	 */
	public static float popPitch(float since, boolean nollie)
	{
		float u = (since - POP_RISE) / POP_FALL;
		float pitch = since <= 0f || since >= POP_RISE + POP_FALL ? 0f : since < POP_RISE
			? POP_PITCH * (float) Math.sin(Math.PI / 2 * since / POP_RISE) : POP_PITCH * (1f - u * u * (3f - 2f * u));
		return nollie ? -pitch : pitch;
	}

	/** True for the tricks popped off the nose (Nollie, Nollie Kickflip, ...). */
	public static boolean isNollie(Trick trick)
	{
		return trick != null && trick.name().startsWith("NOLLIE");
	}

	/**
	 * Exponential smoothing toward {@code target}: closes 1 - exp(-dt / tau) of the gap, so the result
	 * does not depend on the frame rate and never overshoots.
	 */
	public static float approach(float current, float target, float dt, float tau)
	{
		return dt <= 0f ? current : current + (target - current) * (1f - (float) Math.exp(-dt / tau));
	}

	static final float STUMBLE_TIME = 0.35f;

	/**
	 * Extra board roll {@code since} seconds after a stumble: a sine shaking side to side that dies away
	 * linearly, 0 at the start and from STUMBLE_TIME on.
	 */
	public static float stumbleWobble(float since)
	{
		float u = since / STUMBLE_TIME;
		// 0.22 rad at most, 2.5 shakes
		return since > 0f && since < STUMBLE_TIME ? 0.22f * (1f - u) * (float) Math.sin(2 * Math.PI * 2.5f * u) : 0f;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;

/**
 * Draws the local player's current (animated) model at the controller's position, with the procedural
 * {@link BodyPose} applied to its vertices when {@link BufferProbe} proves this frame that the model is the client's
 * per-request animation buffer (so the edit never reaches the cached base model). Otherwise, or after any exception
 * (which switches deformation off for this puppet), the plain model is drawn. Client thread only; no allocation per
 * frame.
 */
@Slf4j
public final class PuppetController extends RuneLiteObjectController
{
	/** The client's model as a mesh (party ghost bodies read it too). */
	public static final LayeredBody.Mesh<Model> MESH = new LayeredBody.Mesh<Model>()
	{
		@Override
		public int faces(Model m)
		{
			return m.getFaceCount();
		}

		@Override
		public int count(Model m)
		{
			return m.getVerticesCount();
		}

		@Override
		public float[] xs(Model m)
		{
			return m.getVerticesX();
		}

		@Override
		public float[] ys(Model m)
		{
			return m.getVerticesY();
		}

		@Override
		public float[] zs(Model m)
		{
			return m.getVerticesZ();
		}

		@Override
		public void deformed(Model m)
		{
			m.calculateBoundsCylinder();
		}
	};

	private final BufferProbe.Source<Model> source;
	private final BufferProbe.Probe<Model> probe = new BufferProbe.Probe<>();
	private final BodyPose pose;
	private boolean disabled;
	/** Reads the drawn mesh's right hand for the carried board; null after a failure. */
	private HandAnchor hand;
	/** Told whether each draw had a model (null: none). */
	@Setter
	private DrawnModelReport drawnReport;

	public PuppetController(Client client, BodyPose pose, HandAnchor hand)
	{
		this.source = () ->
		{
			Player p = client.getLocalPlayer();
			return p == null ? null : p.getModel();
		};
		this.pose = pose;
		this.hand = hand;
	}

	/** False once deformation failed and was switched off: the skater then cannot flip with the board. */
	public boolean canDeform()
	{
		return !disabled;
	}

	@Override
	public Model getModel()
	{
		Model m;
		if (disabled)
			m = source.get();
		else
		{
			try
			{
				m = BufferProbe.drawable(source, MESH, pose, probe);
			}
			catch (RuntimeException ex)
			{
				disabled = true;
				log.warn(Text.get("puppet.deformFailed"), ex);
				m = source.get();
			}
		}
		// reads (never writes) the drawn mesh's hand; a failure stops the reading: the board then hangs at its fixed spot
		if (hand != null && m != null && hand.isActive())
		{
			try
			{
				hand.sample(m.getVerticesX(), m.getVerticesY(), m.getVerticesZ(), m.getVerticesCount());
			}
			catch (RuntimeException ex)
			{
				hand = null;
				log.warn(Text.get("puppet.handFailed"), ex);
			}
		}
		if (drawnReport != null)
			drawnReport.report(m != null);
		return m;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;

/**
 * One procedural foot push, as a function of its phase (0..1 over {@link #DURATION} seconds). Pure and
 * allocation-free. Values are in travel terms; {@link SkaterPoseRig} maps them onto the puppet's model space
 * for the current stance and riding direction.
 *
 * <ol>
 * <li>lift (0 .. {@link #LIFT_END}): the rear foot comes up off the deck and out to the toe side;</li>
 * <li>reach ({@link #LIFT_END} .. {@link #PLANT_START}): it swings down to the ground beside the board while
 * the front knee bends to lower the body;</li>
 * <li>plant ({@link #PLANT_START} .. {@link #PLANT_END}): on the ground, it sweeps backward along the
 * board's travel axis (the push itself);</li>
 * <li>recover ({@link #PLANT_END} .. {@link #RECOVER_END}): it lifts off the ground and swings forward;</li>
 * <li>return ({@link #RECOVER_END} .. {@link #SETTLED}): it sets back down on the deck where it started.</li>
 * </ol>
 * Every channel eases between keyframes with smoothstep, so nothing jumps and each segment is monotonic.
 */
final class PushCycle
{
	/** One unhurried kick; physics pushes faster (every ~0.4 s) but only every other push shows a kick. */
	static final float DURATION = 0.70f;

	static final float LIFT_END = 0.14f;
	static final float PLANT_START = 0.30f;
	static final float PLANT_END = 0.62f;
	static final float RECOVER_END = 0.80f;
	/** The foot is back at rest on the deck; the rear-leg override fades out after this. */
	static final float SETTLED = 0.94f;

	/** The ground below the soles (y down): the deck top is BOARD_TOP up, the soles FOOT_CLEARANCE above it. */
	static final float GROUND_DEPTH = BoardGeometry.BOARD_TOP + BoardPlacement.FOOT_CLEARANCE;
	/** Front-knee bend (1 - legScale) while the foot is down. */
	static final float PLANT_SQUASH = 0.12f;

	/**
	 * Keyframes: the rear foot sweeps 50 units backward on the ground and plants 17 units out to the toe side (the
	 * deck is 13 wide each side of its centre line); the upper body leans 0.14 rad toward the direction of travel
	 * while the foot is down. BACK, SIDE (at KEYS) and LEAN (at BODY_KEYS) are bundled under push.back, push.side and
	 * push.lean (text/data.properties).
	 */
	private static final float[] KEYS = {0f, LIFT_END, PLANT_START, PLANT_END, RECOVER_END, SETTLED, 1f};
	private static final float[] BACK = Text.floats("push.back");
	private static final float[] FOOT_Y = {0f, -10f, GROUND_DEPTH, GROUND_DEPTH, -8f, 0f, 0f};
	private static final float[] SIDE = Text.floats("push.side");

	private static final float[] BODY_KEYS = {0f, 0.12f, PLANT_START, 0.60f, 0.84f, 1f};
	private static final float[] SQUASH = {0f, 0f, PLANT_SQUASH, PLANT_SQUASH, 0f, 0f};
	private static final float[] LEAN = Text.floats("push.lean");

	/** One sample of the cycle. */
	static final class Sample
	{
		/** Units the rear foot is behind its resting spot along the travel axis (negative = ahead). */
		float back;
		/** Rear-foot height, y down: 0 on the deck, {@link #GROUND_DEPTH} on the ground, negative lifted. */
		float footY;
		/** Units the rear foot is out to the toe side (the chest side) of its resting spot. */
		float side;
		/** 0..1: how much the rear leg follows the foot target instead of the plain crouch. */
		float legWeight;
		/** Extra knee bend (1 - legScale) from the front leg. */
		float squash;
		/** Radians the upper body leans toward the direction of travel. */
		float lean;
	}

	private PushCycle()
	{
	}

	/** Samples the cycle at {@code phase}; outside 0..1 the skater stands normally (all zero, as at phase 0). */
	static void sample(float phase, Sample out)
	{
		float p = phase > 0f && phase < 1f ? phase : 0f;
		out.back = keyed(KEYS, BACK, p);
		out.footY = keyed(KEYS, FOOT_Y, p);
		out.side = keyed(KEYS, SIDE, p);
		// the rear-leg override fades in over phase 0.08 at the start, and out once the foot is back at rest (so the
		// fade itself moves nothing but the knee-bend versus squash difference)
		out.legWeight = smoothstep(0f, 0.08f, p) * (1f - smoothstep(SETTLED, 1f, p));
		out.squash = keyed(BODY_KEYS, SQUASH, p);
		out.lean = keyed(BODY_KEYS, LEAN, p);
	}

	/** Smoothstep-eased interpolation between keyframes ({@code keys} ascending from 0 to 1). */
	static float keyed(float[] keys, float[] values, float phase)
	{
		for (int i = 1; i < keys.length; i++)
		{
			if (phase <= keys[i])
			{
				float u = smoothstep(keys[i - 1], keys[i], phase);
				return values[i - 1] + (values[i] - values[i - 1]) * u;
			}
		}
		return values[values.length - 1];
	}

	/** {@code v} clamped to 0..1; NaN is 0. */
	static float clamp01(float v)
	{
		return v > 0f ? Math.min(1f, v) : 0f;
	}

	/** 0 at or below {@code a}, 1 at or above {@code b}, 3u^2 - 2u^3 between. */
	static float smoothstep(float a, float b, float x)
	{
		if (x <= a)
			return 0f;
		if (x >= b)
			return 1f;
		float u = (x - a) / (b - a);
		return u * u * (3f - 2f * u);
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.*;
import com.gielinorskate.tricks.Trick;
import lombok.AllArgsConstructor;

/**
 * An immutable snapshot of everything the renderer and camera draw from physics, so a frame can be drawn
 * between two fixed physics steps ({@link #lerp}). Pure: no client dependency.
 */
@AllArgsConstructor
public final class RenderPose
{
	/**
	 * A snapshot pair further apart than this is a teleport, not motion: drawn without blending. The
	 * fastest physics step is maxSpeed 2600 * 0.02 s = 52 units, so this only catches real jumps.
	 */
	static final float MAX_LERP_DISTANCE = 96f;
	/**
	 * Board roll/yaw changes larger than this between two steps are a snap (e.g. a shove-it's half turn
	 * cleared on landing), not rotation. The fastest real flip step: a double kickflip (2 turns in 0.5 s)
	 * with an ease-out curve peaking at 2x the mean rate is 2 * 4 PI / 0.5 * 0.02 s = 1.0 rad.
	 */
	static final float MAX_ANGLE_STEP = 1.5f;

	public final float x;
	public final float y;
	/** Up-positive height. */
	public final float h;
	public final float heading;
	public final float cameraHeading;
	public final float boardRoll;
	public final float boardYaw;
	public final float boardPitch;
	public final SkaterState state;
	/** Current grab, manual or grind, or null. */
	public final Trick hold;

	public static RenderPose of(SkatePhysics p)
	{
		return new RenderPose(p.getX(), p.getY(), p.getH(), p.getHeading(), p.getCameraHeading(), p.getBoardRoll(),
			p.getBoardYawOffset(), p.getBoardPitch(), p.getState(), p.getActiveHold());
	}

	/**
	 * The pose {@code alpha} (0..1, clamped) of the way from {@code a} (the older step) to {@code b}.
	 * Returns {@code b} itself when the two are not one continuous motion: locking onto a rail (the grind
	 * lock has its own blend), entering or leaving a bail (which includes the reset), or a teleport.
	 * Headings take the short way round. Board roll and yaw are blended as raw values (a double flip
	 * goes past one turn), except that a completed flip snapping back to zero blends the short way, and
	 * a snap larger than {@link #MAX_ANGLE_STEP} is not blended. State and hold come from {@code b}.
	 */
	public static RenderPose lerp(RenderPose a, RenderPose b, float alpha)
	{
		if (!continuous(a, b))
			return b;
		float t = PushCycle.clamp01(alpha);
		return new RenderPose(
			mix(a.x, b.x, t),
			mix(a.y, b.y, t),
			mix(a.h, b.h, t),
			mixAngle(a.heading, b.heading, t),
			mixAngle(a.cameraHeading, b.cameraHeading, t),
			mixBoardAngle(a.boardRoll, b.boardRoll, t),
			mixBoardAngle(a.boardYaw, b.boardYaw, t),
			mix(a.boardPitch, b.boardPitch, t),
			b.state,
			b.hold);
	}

	private static boolean continuous(RenderPose a, RenderPose b)
	{
		if (b.state == SkaterState.GRINDING && a.state != SkaterState.GRINDING)
			return false;
		if ((a.state == SkaterState.BAILED) != (b.state == SkaterState.BAILED))
			return false;
		return Math.hypot(b.x - a.x, b.y - a.y) <= MAX_LERP_DISTANCE && Math.abs(b.h - a.h) <= MAX_LERP_DISTANCE;
	}

	private static float mixBoardAngle(float a, float b, float t)
	{
		float raw = b - a;
		if (Math.abs(raw) <= MAX_ANGLE_STEP)
			return a + raw * t;
		float shortWay = Angles.wrap(raw);
		if (Math.abs(shortWay) <= MAX_ANGLE_STEP)
			return a + shortWay * t;
		return b;
	}

	static float mix(float a, float b, float t)
	{
		return a + (b - a) * t;
	}

	/** {@code t} of the way from heading {@code a} to {@code b}, the short way round. */
	static float mixAngle(float a, float b, float t)
	{
		return Angles.wrap(a + Angles.wrap(b - a) * t);
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;

/**
 * The board under a riding skater, eased frame to frame: its trick roll and pitch, the grab's tweak and lift, the
 * slide's drop, and where board and body go. Shared by the local skater and party ghosts. Client thread.
 */
public final class RidingBoard
{
	/** The board's roll and pitch as drawn (NaN: rebuilt from scratch next frame). */
	public float roll = Float.NaN;
	public float pitch = Float.NaN;
	/** This frame's deck lift (a pitched board raises the middle of the deck) and grab lift. */
	public int deckLift;
	public int lift;
	private float holdPitch;
	/** A grab's board pitch and roll tweak (GrabPose), snapped in and out (PoseSmoothing.GRAB_TAU). */
	private float grabPitch;
	private float grabRoll;
	private float slideDrop;

	/** Back to a board at rest, rebuilt from scratch next frame. */
	public void reset()
	{
		offBoard();
		holdPitch = 0f;
		grabPitch = 0f;
		grabRoll = 0f;
		slideDrop = 0f;
	}

	/** Off the board: back on it, its trick pose is rebuilt from scratch. */
	public void offBoard()
	{
		roll = Float.NaN;
		pitch = Float.NaN;
	}

	/**
	 * One frame riding {@code p} at local ({@code x}, {@code y}): the roll is {@code baseRoll} plus the grab's tweak
	 * plus {@code wobble} (half a turn when bailed); the pitch is {@code popPitch} plus the hold pitch (easing to
	 * {@code holdTarget}), the grab's tweak (from {@code grab}) and {@code extraPitch}. A change under 0.01 (the gap
	 * between deck and soles) keeps the last pose. The board and body placements go to {@code board} and
	 * {@code body}, the board lowered by the slide's drop plus {@code dip}; {@code pose} is told the board as drawn
	 * (a grabbing hand goes to it) and its grab lift read from it. Returns the feet's z (RuneLite, down-negative).
	 */
	public int update(RenderPose p, int x, int y, float baseRoll, float wobble, float popPitch, float holdTarget,
		float extraPitch, Trick grab, float dip, BodyPose pose, float dt, Placement board, Placement body)
	{
		boolean bailed = p.state == SkaterState.BAILED;
		holdPitch = PoseSmoothing.approach(holdPitch, holdTarget, dt, PoseSmoothing.POSE_TAU);
		grabPitch = PoseSmoothing.approach(grabPitch, GrabPose.boardPitch(grab), dt, PoseSmoothing.GRAB_TAU);
		grabRoll = PoseSmoothing.approach(grabRoll, GrabPose.boardRoll(grab), dt, PoseSmoothing.GRAB_TAU);
		float r = bailed ? Angles.PI : baseRoll + grabRoll + wobble;
		float pt = popPitch + holdPitch + grabPitch + extraPitch;
		if (!(Math.abs(r - roll) <= 0.01f && Math.abs(pt - pitch) <= 0.01f))
		{
			roll = r;
			pitch = pt;
		}
		// slides: the deck, not the wheels, sits on the rail (RuneLite z grows downward)
		slideDrop = PoseSmoothing.approach(slideDrop, BoardPlacement.slideDrop(p.state, p.hold), dt,
			PoseSmoothing.POSE_TAU);
		int lower = Math.round(slideDrop + dip);
		// a pitched board turns about its contact truck, which raises the middle of the deck under the feet
		deckLift = Math.round(BoardPlacement.deckLift(pitch));
		// a grab pulls the board up toward the hips with the knees (the body stays put, the feet fold up to it)
		lift = BoardPlacement.grabLift(pose.feetLift, bailed);
		int z = -Math.round(p.h);
		int top = (int) BoardGeometry.BOARD_TOP;
		// a front or back flip turns the board with the skater about the skater's centre of mass (JAU per radian:
		// a relative turn, no south offset)
		int yawOffsetJau = Math.round(p.boardYaw * (1024f / Angles.PI));
		board.set(x, y, bailed ? z - top : z + lower - lift, (Angles.toJau(p.heading) + yawOffsetJau) & 2047, roll,
			pitch);
		// regular stance: the body faces 90 degrees clockwise from the board's nose; a bail keeps the body where the
		// skater is (the fall animation moves it)
		int feetZ = bailed ? z : z - top - BoardPlacement.FOOT_CLEARANCE - deckLift + lower;
		body.set(x, y, feetZ, Angles.toJau(p.heading + Angles.PI / 2), 0f, 0f);
		pose.boardRoll = roll;
		pose.boardPitch = pitch;
		pose.deckLift = deckLift;
		pose.boardLift = lift;
		return feetZ;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.Text;
import com.gielinorskate.physics.*;
import com.gielinorskate.render.AnimationPicker.Action;
import java.util.*;
import lombok.Getter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.gameval.AnimationID;

/**
 * Drives the hidden local player's animations from physics state, and the procedural body pose layered on
 * top of them ({@link SkaterPoseRig} into {@link #getBodyPose()}, which the puppet applies to the mesh).
 * The stance animation stays on all the time and every move is procedural, so nothing cuts. Client thread only.
 */
@Slf4j
@RequiredArgsConstructor
public final class SkaterAnimator
{
	private static final int NO_ANIMATION = -1;
	/**
	 * The riding stance, also while grinding and in a manual. Crouching, pushing, the pop, the air tuck and the bail
	 * fall are procedural ({@link SkaterPoseRig}) on it: OSRS animations cannot blend, so switching cut hard
	 * (HUMAN_CRATE_SQUAT made the skater vanish, the walk cycle looked like walking on the board).
	 */
	private static final int STANCE = AnimationID.HUMAN_SKI_IDLE;

	private final Client client;
	private final PoseGuard guard = new PoseGuard();
	private final SkaterPoseRig rig = new SkaterPoseRig();
	private final SkaterPoseRig.Signals signals = new SkaterPoseRig.Signals();
	/** The procedural pose for the puppet, updated every frame. */
	@Getter
	private final BodyPose bodyPose = new BodyPose();
	/**
	 * Handed to the puppet, which reports whether each draw had a model: spares fetching the animated model again for
	 * the guard.
	 */
	@Getter
	private final DrawnModelReport drawnReport = new DrawnModelReport();
	private final FootBody footBody = new FootBody();
	/** False once a walk or run animation left the player with no model: on foot stands in the idle pose. */
	private boolean footGaitAnimations = true;
	/** Plays the walk or run animation as much faster as the walker is faster than the game's walk or run. */
	private final GaitPlayback gaitPlayback = new GaitPlayback();
	/** Classic animations' definitions (frame lengths) by id, loaded once; null for one that can't be stepped. */
	private final Map<Integer, Animation> classic = new HashMap<>();
	/** False once stepping the gait animation threw: it plays at the game's speed from then on. */
	private boolean gaitSpeedUp = true;
	private float lastHeading = Float.NaN;
	private String warning;

	private boolean started;
	/** The player's own idle pose, given back on exit; follows the game's changes while skating. */
	private final IdlePoseTracker ownIdlePose = new IdlePoseTracker();
	private Action currentAction = Action.NONE;
	private float actionTimeLeft;
	private int lastIdlePose = Integer.MIN_VALUE;
	/** The last frame was on foot: the idle pose is a walk / run / own idle, which the board must replace. */
	private boolean idleFromFoot;
	/** The knockdown's lie-down and get-up animations play (false once one left the skater with no model). */
	private boolean knockdownAnimations = true;
	/** The knockdown animation playing now, or NO_ANIMATION. */
	private int knockAnimation = NO_ANIMATION;

	public void start()
	{
		resetBody();
		drawnReport.clear();
		Player p = client.getLocalPlayer();
		if (p == null)
			return;
		ownIdlePose.start(p.getIdlePoseAnimation());
		footGaitAnimations = true;
		knockdownAnimations = true;
		knockAnimation = NO_ANIMATION;
		setIdlePose(p, STANCE);
		started = true;
		noAction();
		lastIdlePose = Integer.MIN_VALUE;
		idleFromFoot = false;
	}

	/** @param pose the (interpolated) pose drawn this frame */
	public void update(RenderPose pose, SkatePhysics physics, List<SkateEvent> events, float dt)
	{
		Player p = client.getLocalPlayer();
		if (p == null)
			return;
		noteGameIdlePose(p);
		// carve rate from the drawn (interpolated) heading, so it is smooth between physics steps; a reset
		// teleports the heading, which is not a carve
		float rate = 0f;
		if (!Float.isNaN(lastHeading) && dt > 0f && !events.contains(SkateEvent.RESET))
			rate = Angles.wrap(pose.heading - lastHeading) / dt;
		lastHeading = pose.heading;
		SkaterPoseRig.Signals s = signals;
		s.state = pose.state;
		s.speed = physics.getSpeed();
		s.carveRate = rate;
		s.charge = physics.getPopCharge();
		s.verticalSpeed = physics.getVerticalVelocity();
		s.boardPitch = pose.boardPitch;
		// rolling with a grab key held the body grabs the board on the ground (pose only, the physics' ground grab)
		s.hold = pose.hold != null ? pose.hold : physics.getGroundGrab();
		s.flipping = pose.boardRoll != 0f || pose.boardYaw != 0f;
		s.popped = events.contains(SkateEvent.POP);
		s.rolledOff = events.contains(SkateEvent.ROLL_OFF);
		s.landed = events.contains(SkateEvent.LAND);
		s.bailed = events.contains(SkateEvent.BAIL);
		s.landingSpeed = physics.getLastLandingSpeed();
		s.pushed = events.contains(SkateEvent.PUSH);
		s.proceduralPush = true;
		// front/back flips: the body turns head over heels by the physics body-flip angle (0 when upright)
		s.bodyFlipAngle = physics.getBodyFlipAngle();
		s.onFoot = false;
		// the grabbing hand: Q the left, E the right
		s.grabHand = physics.isGrabLeftHand() ? 1 : -1;
		rig.update(s, dt);
		rig.writeTo(bodyPose);
		// the next step off starts from standing
		footBody.reset();
		SkaterState st = physics.getState();
		// just got on: back to the stance at once, even airborne (a jump-mount off an edge), where the idle pose is
		// otherwise left alone and the walk or run legs would keep cycling until the landing
		if (idleFromFoot || (st == SkaterState.ROLLING || st == SkaterState.MANUAL || st == SkaterState.GRINDING)
			&& lastIdlePose != STANCE)
		{
			idleFromFoot = false;
			setIdlePose(p, STANCE);
		}

		actionTimeLeft = Math.max(0f, actionTimeLeft - dt);
		Action next = AnimationPicker.pick(st, events, currentAction, actionTimeLeft);
		if (next != currentAction)
		{
			currentAction = next;
			actionTimeLeft = next == Action.PUSH ? AnimationPicker.PUSH_SECONDS : 0f;
			play(p, NO_ANIMATION);
		}

		if (guard.frame(hasModel(p)))
		{
			// an animation that doesn't work on player models makes the skater vanish: fall back to the stance
			setIdlePose(p, STANCE);
			p.setAnimation(NO_ANIMATION);
			noAction();
			warning = Text.get("skanim.poseVanished");
		}
	}

	/**
	 * On foot: the player's own OSRS idle, walk or run pose animation by the walker's speed (the real character
	 * stands still, so its idle pose is what plays: the walk cycles in place while the puppet moves), no action
	 * animation, and the procedural body for jumps (a tuck, then the landing squash).
	 */
	public void updateOnFoot(OffBoardPose pose, float dt)
	{
		Player p = client.getLocalPlayer();
		if (p == null)
			return;
		if (currentAction != Action.NONE)
		{
			noAction();
			play(p, NO_ANIMATION);
		}
		noteGameIdlePose(p);
		idleFromFoot = true;
		footBody.fill(signals, pose.walkerSpeed, pose.airborne, pose.jumping, pose.verticalSpeed);
		FootBody.Gait gait = footBody.gait();
		// the player's own pose animation for the gait (the idle one if the game has none for it)
		int run = gait == FootBody.Gait.RUN ? p.getRunAnimation() : -1;
		int walk = gait != FootBody.Gait.IDLE ? p.getWalkAnimation() : -1;
		int idlePose = !footGaitAnimations ? realIdlePose(p) : run >= 0 ? run : walk >= 0 ? walk : realIdlePose(p);
		if (idlePose != lastIdlePose)
		{
			setIdlePose(p, idlePose);
			gaitPlayback.reset();
		}
		float rate = GaitPlayback.rate(gait, pose.walkerSpeed);
		if (footGaitAnimations && gait != FootBody.Gait.IDLE && gaitSpeedUp && rate > 1f)
		{
			// the walker is faster than the game's walk and run, so the gait animation is stepped on by the frames
			// the game's own playback leaves out, keeping the feet from sliding. Only a classic (frame-based)
			// animation that is the one playing now is touched; anything unexpected leaves it at the game's speed.
			try
			{
				Animation a = classic(idlePose);
				int frame = a == null || p.getPoseAnimation() != idlePose ? -1
					: gaitPlayback.advance(p.getPoseAnimationFrame(), a.getFrameLengths(), rate, dt);
				if (frame >= 0)
					p.setPoseAnimationFrame(frame);
			}
			catch (RuntimeException ex)
			{
				gaitSpeedUp = false;
				log.warn(Text.get("skanim.gaitSpeedFailed"), ex);
			}
		}
		rig.update(signals, dt);
		rig.writeTo(bodyPose);
		// getting back on is no carve
		lastHeading = Float.NaN;

		if (guard.frame(hasModel(p)))
		{
			// a walk or run animation that leaves no model: stand in the player's own idle for the session
			footGaitAnimations = false;
			setIdlePose(p, realIdlePose(p));
			warning = Text.get("skanim.walkVanished");
		}
	}

	/**
	 * Knocked off the board: the tumble in the air is procedural (the whole body turned about its centre of mass);
	 * once down the OSRS lie-down loop plays (the no-delay knockdown loop lies down from its first frame: the cut to it
	 * comes at the impact, where the smoke and the camera kick hide it), then the get-up animation squeezed into the
	 * get-up's time (each falls back to the procedural pose for the session when one leaves the skater with no
	 * model). Animations go on the hidden local player only, as every skate animation does.
	 */
	public void updateKnockdown(KnockdownPose k, float dt)
	{
		Player p = client.getLocalPlayer();
		if (p == null)
			return;
		noteGameIdlePose(p);
		noAction();
		int want = !knockdownAnimations ? NO_ANIMATION : k.stage == KnockdownPose.Stage.LIE
			? AnimationID.HUMAN_KNOCKDOWN_LOOP_NODELAY : k.stage == KnockdownPose.Stage.GET_UP ? AnimationID.HUMAN_GETUP
			: NO_ANIMATION;
		if (want != knockAnimation)
		{
			knockAnimation = want;
			play(p, want);
		}
		if (want != NO_ANIMATION && k.stage == KnockdownPose.Stage.GET_UP)
			scrub(p, want, k.progress);
		KnockdownBody.write(k, want != NO_ANIMATION, bodyPose);
		// carving starts afresh once back on
		lastHeading = Float.NaN;

		if (guard.frame(hasModel(p)))
		{
			knockdownAnimations = false;
			knockAnimation = NO_ANIMATION;
			p.setAnimation(NO_ANIMATION);
			warning = Text.get("skanim.knockdownVanished");
		}
	}

	/** The knockdown is over (standing, or back on the board with R): its animation stops, the body starts afresh. */
	public void endKnockdown()
	{
		Player p = client.getLocalPlayer();
		if (p != null && knockAnimation != NO_ANIMATION)
			play(p, NO_ANIMATION);
		knockAnimation = NO_ANIMATION;
		noAction();
		resetBody();
	}

	/** Shows the frame of a classic animation {@code progress} of the way through it (left alone otherwise). */
	private void scrub(Player p, int animationId, float progress)
	{
		try
		{
			Animation a = classic(animationId);
			int frame = a == null || p.getAnimation() != animationId ? -1
				: AnimClock.frameAt(progress, a.getFrameLengths());
			if (frame >= 0)
				p.setAnimationFrame(frame);
		}
		catch (RuntimeException ex)
		{
			classic.put(animationId, null);
			log.debug(Text.get("skanim.paceFailed"), ex);
		}
	}

	/** {@code id}'s definition, loaded once; null when it is no classic (frame-based) animation. */
	private Animation classic(int id)
	{
		if (!classic.containsKey(id))
		{
			Animation a = id >= 0 ? client.loadAnimation(id) : null;
			classic.put(id, a != null && !a.isMayaAnim() ? a : null);
		}
		return classic.get(id);
	}

	/** Plays {@code id} (NO_ANIMATION: none) from its first frame. */
	private static void play(Player p, int id)
	{
		p.setAnimation(id);
		p.setAnimationFrame(0);
	}

	private void noAction()
	{
		currentAction = Action.NONE;
		actionTimeLeft = 0f;
	}

	/** The idle pose the player had before skating (the skate stance replaced it). */
	private int realIdlePose(Player p)
	{
		return started ? ownIdlePose.restorePose() : p.getIdlePoseAnimation();
	}

	/** Sets the player's idle pose, noting it was ours. */
	private void setIdlePose(Player p, int pose)
	{
		p.setIdlePoseAnimation(pose);
		ownIdlePose.wrote(pose);
		lastIdlePose = pose;
	}

	/**
	 * The game may have set a new idle pose (a weapon wielded while skating): it becomes the one given back on
	 * exit, and ours is written again.
	 */
	private void noteGameIdlePose(Player p)
	{
		if (started && ownIdlePose.observe(p.getIdlePoseAnimation()))
			lastIdlePose = Integer.MIN_VALUE;
	}

	/** A message for the player if the animator had to recover, else null. Clears it. */
	public String takeWarning()
	{
		String w = warning;
		warning = null;
		return w;
	}

	public void stop()
	{
		Player p = client.getLocalPlayer();
		if (started && p != null)
		{
			noteGameIdlePose(p);
			setIdlePose(p, ownIdlePose.restorePose());
			p.setAnimation(NO_ANIMATION);
		}
		started = false;
		resetBody();
		knockAnimation = NO_ANIMATION;
		noAction();
		lastIdlePose = Integer.MIN_VALUE;
	}

	/**
	 * Whether the player has a model, for the guard: the puppet's latest draw when it reported one since the last
	 * check (the model it fetched anyway), else a fetch of our own.
	 */
	private boolean hasModel(Player p)
	{
		return drawnReport.isFresh() ? drawnReport.take() : p.getModel() != null;
	}

	private void resetBody()
	{
		rig.reset();
		bodyPose.neutral();
		footBody.reset();
		lastHeading = Float.NaN;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import java.util.ArrayList;
import java.util.List;

/**
 * Procedural body motion on top of a constant stance animation (OSRS animations cannot blend, so every
 * animation switch is a hard cut; these channels move continuously instead). Pure: feed it one
 * {@link Signals} sample per frame and read the result with {@link #writeTo}. Every channel is a
 * {@link CriticalSpring}, so nothing jumps in one frame whatever the frame rate.
 *
 * <ul>
 * <li>lean into carves: roll toward the inside of the turn, from the centripetal acceleration
 * speed * turn rate (a Shift tight carve turns faster, so it leans further);</li>
 * <li>crouch: knees bend with the pop charge, a little on rails;</li>
 * <li>pop: a quick extension, then a tuck (deeper during flips and grabs), extending again when falling
 * toward the ground;</li>
 * <li>landing: a compression kick scaled by the landing speed that springs back in about 0.25 s;</li>
 * <li>manuals and pitched grinds: the body tips with the board about the contact truck; a balance sway
 * on rails and in manuals;</li>
 * <li>grabs: the body tucks and folds over the board and the grabbing hand reaches for its part of it
 * ({@link GrabPose}, the arm moved by {@link MeshDeformer}); rolling with a grab held (a grab hold while ROLLING, the
 * physics' ground grab) it is a low crouch with the hand down on the board, which stays on the ground;</li>
 * <li>bail: a continuous fall onto the chest and a smooth get-up.</li>
 * </ul>
 *
 * <p>Spring speeds (omega, 1/s) are about 4 / omega seconds to settle; "90% in t" is 3.9 / omega.
 */
public final class SkaterPoseRig
{
	/** Mutable per-frame input, reused to avoid allocations. */
	public static final class Signals
	{
		public SkaterState state = SkaterState.ROLLING;
		/** Signed ground speed (negative riding fakie), u/s. */
		public float speed;
		/** Heading change rate, rad/s, clockwise > 0. */
		public float carveRate;
		/** Pop charge 0..1. */
		public float charge;
		/** Vertical speed in the air, u/s, up > 0. */
		public float verticalSpeed;
		/** Board pitch, radians (nose up > 0). */
		public float boardPitch;
		public Trick hold;
		/** The board is mid flip or shove-it. */
		public boolean flipping;
		/** Events of this frame. */
		public boolean popped;
		public boolean rolledOff;
		public boolean landed;
		public boolean bailed;
		/** Downward speed at this frame's landing, u/s. */
		public float landingSpeed;
		/** A push (SkateEvent.PUSH) this frame. */
		public boolean pushed;
		/** Push procedurally (no push animation is playing). */
		public boolean proceduralPush = true;
		/**
		 * Front/back flip of skater and board about the centre of mass, radians, + = front flip (head toward
		 * the nose). Raw, not wrapped.
		 */
		public float bodyFlipAngle;
		/**
		 * Walking, not skating (FootBody fills the rest): a jump tucks lightly, a fall
		 * barely bends the knees.
		 */
		public boolean onFoot;
		/**
		 * The grab key's hand: +1 the left (Q), -1 the right (E), 0 not known (a party ghost). Each grab is drawn
		 * with its own hand ({@link GrabPose#leftHand}); only a tailgrab, either hand's, follows the key.
		 */
		public int grabHand;
	}

	static final float MAX_LEAN = 0.5f;

	/** Crouch amounts: 1 - legScale. Negative extends the legs. */
	static final float CHARGE_CROUCH = 0.3f;
	static final float MIN_CROUCH = -0.2f;
	static final float MAX_CROUCH = 0.5f;

	/**
	 * The landing compression's own spring: peaks 1 / 14 = 0.07 s after touchdown and is back to 30% of
	 * the peak by 0.25 s ((1 + 3.5) e^-3.5 / e^-1 = 0.29 of it).
	 */
	static final float LANDING_OMEGA = 14f;

	static final float SWAY_OMEGA = 6f;

	/**
	 * The body snaps into (and out of) a grab like Skate 3: 90% of the way in 3.9 / omega = 0.086 s. Also the knees'
	 * speed while a grab is held or let go in the air. (It was 12, a third of a second, with the knees on the slower
	 * crouch spring, so the hand only met the board once the body had caught up.) The hand slides between grab points
	 * (an aim renaming the grab) as fast.
	 */
	static final float GRAB_OMEGA = 45f;
	/**
	 * The body's roll toward the toe or heel edge and the knees' tuck in a grab: a touch softer (90% in 0.11 s), so a
	 * swap to the other edge's grab or a tuck straight off the pop's extension (the biggest swings) stay smooth.
	 */
	static final float GRAB_ROLL_OMEGA = 36f;
	/** Below this arm weight the hand counts as let go: a new grab's spot (or hand) is taken at once. */
	static final float ARM_LET_GO = 0.05f;

	private static final float TWO_PI = (float) (2 * Math.PI);

	/** Every spring, for {@link #reset}. */
	private final List<CriticalSpring> springs = new ArrayList<>();
	private final CriticalSpring lean = spring();
	private final CriticalSpring pitch = spring();
	private final CriticalSpring crouch = spring();
	private final CriticalSpring impact = spring();
	private final CriticalSpring grindSway = spring();
	private final CriticalSpring manualSway = spring();
	private final CriticalSpring tumble = spring();
	/** The grab's reach along the board (+ toward the nose) and its body roll (see GrabPose). */
	private final CriticalSpring grabLean = spring();
	private final CriticalSpring grabRoll = spring();
	/** The grabbing arm: how far it has reached (0..1), where on the board it holds, and the extra fold. */
	private final CriticalSpring arm = spring();
	private final CriticalSpring armAlong = spring();
	private final CriticalSpring armAcross = spring();
	/** The grab point's board-model height: slides too (an edge grab renamed to a tip grab), never jumps. */
	private final CriticalSpring armBoardY = spring();
	private final CriticalSpring grabBend = spring();
	/** The knees folding up toward the chest in a grab (0..1), and with them the feet and board pulled up. */
	private final CriticalSpring kneeFold = spring();
	/** The feet and board pulled up (0..1): an air grab's only; a rolling grab keeps the board on the ground. */
	private final CriticalSpring liftFold = spring();
	/** What a flip reset snapped away, easing back to 0. */
	private final CriticalSpring flipCatchUp = spring();
	private float armSide = -1f;
	private SkaterState lastState = SkaterState.ROLLING;
	private float airTime;
	private boolean poppedFlight;
	private float clock;
	private float pivotX;
	/** Phase of the current push cycle; 1 or more when none is playing. */
	private float pushPhase = 1f;
	private int pushCyclesStarted;
	/**
	 * Model x of the travel direction, latched at the start of each push. The puppet is drawn at heading + 90
	 * degrees (regular stance only); with RuneLite's model-to-local rotation (MeshDeformer) at that orientation,
	 * model +x maps onto the heading (the board's nose): the body faces -z (to the right of travel) and its left
	 * (front) foot is the +x one.
	 */
	private float pushTravelX = 1f;
	/** 1 while a push plays normally, easing to 0 when it is cancelled. */
	private float pushFade = 1f;
	private final PushCycle.Sample push = new PushCycle.Sample();
	private float flipAngle;
	private float lastFlipInput;

	private CriticalSpring spring()
	{
		CriticalSpring s = new CriticalSpring();
		springs.add(s);
		return s;
	}

	public void reset()
	{
		springs.forEach(s -> s.reset(0f));
		armBoardY.reset(GrabPose.EDGE_Y);
		armSide = -1f;
		lastState = SkaterState.ROLLING;
		airTime = 0f;
		poppedFlight = false;
		clock = 0f;
		pivotX = 0f;
		pushPhase = 1f;
		pushTravelX = 1f;
		pushFade = 1f;
		flipAngle = 0f;
		lastFlipInput = 0f;
	}

	public void update(Signals s, float dt)
	{
		if (dt <= 0f)
			return;
		clock = (clock + dt) % 1000f;
		SkaterState st = s.state;
		boolean grounded = st == SkaterState.ROLLING || st == SkaterState.MANUAL;
		boolean inAir = st == SkaterState.AIRBORNE;

		if (s.popped || s.rolledOff)
		{
			airTime = 0f;
			poppedFlight = s.popped;
		}
		else if (inAir)
			airTime += dt;

		lean.step(grounded ? leanFor(s.speed, s.carveRate) : 0f, 9f, dt);

		if (s.boardPitch != 0f)
			pivotX = -BoardPlacement.pivotZ(s.boardPitch);
		boolean pitched = st == SkaterState.MANUAL || st == SkaterState.GRINDING;
		// the body tips by 0.7 of the board's manual or grind pitch
		pitch.step(pitched ? 0.7f * s.boardPitch : 0f, 10f, dt);

		if (s.landed)
			impact.kick(CriticalSpring.kickForPeak(landingCompression(s.landingSpeed), LANDING_OMEGA));
		if (st == SkaterState.GRINDING && lastState == SkaterState.AIRBORNE)
			// locking onto a rail
			impact.kick(CriticalSpring.kickForPeak(0.1f, LANDING_OMEGA));
		impact.step(0f, LANDING_OMEGA, dt);
		if (s.popped)
			// the legs snap straight from a deep charge crouch
			crouch.kick(-8f);
		// a grab tucks (and untucks when let go in the air) as fast as the arm reaches; landing keeps its own speed
		// (about 0.2 s to settle, quick enough for the pop extension to read)
		boolean grabSnap = inAir && (GrabPose.reaches(s.hold) || arm.value > ARM_LET_GO);
		if (inAir && GrabPose.reaches(s.hold) && crouch.velocity < 0f)
			// grabbing while the pop still kicks the legs straight: tuck from where they are, not after the kick
			crouch.velocity = 0f;
		crouch.step(crouchTarget(s, airTime, poppedFlight), grabSnap ? GRAB_ROLL_OMEGA : 20f, dt);
		crouch.value = Math.max(MIN_CROUCH, Math.min(MAX_CROUCH, crouch.value));

		// a balance sway on rails and in manuals
		grindSway.step(st == SkaterState.GRINDING ? 0.05f : 0f, SWAY_OMEGA, dt);
		manualSway.step(st == SkaterState.MANUAL ? 0.035f : 0f, SWAY_OMEGA, dt);

		if (s.bailed)
			tumble.kick(2f);
		boolean tumbling = st == SkaterState.BAILED;
		// the fall (1.35 rad onto the chest), and the get-up
		tumble.step(tumbling ? 1.35f : 0f, tumbling ? 6f : 7f, dt);
		Trick grab = inAir ? s.hold : rollingGrab(s);
		grabLean.step(GrabPose.torsoLean(grab), GRAB_OMEGA, dt);
		grabRoll.step(GrabPose.bodyRoll(grab), GRAB_ROLL_OMEGA, dt);
		// rolling, a tailgrab is the back hand's whichever key: the front hand cannot reach the tail on the ground
		updateArm(grab, inAir, inAir ? s.grabHand : 0, dt);
		updatePush(s, dt);
		updateFlip(s.bodyFlipAngle, s.landed || s.bailed, dt);
		lastState = st;
	}

	/** The rolling grab: a grab held while ROLLING on the board (the physics' ground grab), else null. */
	static Trick rollingGrab(Signals s)
	{
		return s.state == SkaterState.ROLLING && !s.onFoot && GrabPose.reaches(s.hold) ? s.hold : null;
	}

	/**
	 * The grabbing hand reaches for its spot on the board while a grab is held (in the air, or rolling) and lets go
	 * after. A new grab with the other hand first lets the old arm go back, so an arm never jumps across the body. Only
	 * an air grab ({@code inAir}) pulls the feet and board up.
	 */
	private void updateArm(Trick grab, boolean inAir, int hand, float dt)
	{
		boolean reaching = GrabPose.reaches(grab);
		// each grab's own hand (GrabPose.leftHand), so the arm never crosses the body to the board's middle
		float side = GrabPose.leftHand(grab, hand) ? 1f : -1f;
		boolean letGo = arm.value < ARM_LET_GO;
		if (reaching && side != armSide && letGo)
			armSide = side;
		if (reaching && side == armSide)
		{
			if (letGo)
			{
				// a fresh grab: straight for its own spot, not from wherever the last one held
				armAlong.reset(GrabPose.grabAlong(grab));
				armAcross.reset(GrabPose.grabAcross(grab));
				armBoardY.reset(GrabPose.grabBoardY(grab));
			}
			armAlong.step(GrabPose.grabAlong(grab), GRAB_OMEGA, dt);
			armAcross.step(GrabPose.grabAcross(grab), GRAB_OMEGA, dt);
			armBoardY.step(GrabPose.grabBoardY(grab), GRAB_OMEGA, dt);
		}
		// the arm reaches for the board (and lets go): 90% of the way in 0.08 s
		arm.step(reaching && side == armSide ? 1f : 0f, 48f, dt);
		arm.value = PushCycle.clamp01(arm.value);
		// a grab folds the upper body 0.45 rad further over the board; a rolling grab 0.75 (the board is lower)
		grabBend.step(reaching ? inAir ? 0.45f : 0.75f : 0f, GRAB_OMEGA, dt);
		// the knees come up with the tuck's speed
		kneeFold.step(reaching ? 1f : 0f, GRAB_ROLL_OMEGA, dt);
		kneeFold.value = PushCycle.clamp01(kneeFold.value);
		// in the air the same spring as the knees (the lift follows them exactly); landing into a rolling grab eases
		// the board back down to the ground a little slower (90% in 0.2 s) while the knees stay folded
		liftFold.step(reaching && inAir ? 1f : 0f, reaching && !inAir ? 18f : GRAB_ROLL_OMEGA, dt);
		liftFold.value = PushCycle.clamp01(liftFold.value);
	}

	/**
	 * A kick plays on a PUSH while rolling, unless one is already playing: pushes that land mid-kick are not
	 * queued, so holding W (physics pushes every ~0.4 s) shows one longer stride about every other push instead
	 * of a kick on every push. Both ends of a kick are the plain stance, so starting a new one never jumps.
	 * Leaving the ground (or a push animation) cancels the kick: it fades out (time constant 0.08 s) instead of
	 * snapping back.
	 */
	private void updatePush(Signals s, float dt)
	{
		boolean canPush = s.state == SkaterState.ROLLING && s.proceduralPush;
		if (s.pushed && canPush && pushPhase >= 1f)
		{
			pushTravelX = s.speed < 0f ? -1f : 1f;
			pushPhase = 0f;
			pushFade = 1f;
			pushCyclesStarted++;
		}
		if (pushPhase >= 1f)
			return;
		pushPhase += dt / PushCycle.DURATION;
		if (!canPush)
		{
			pushFade *= (float) Math.exp(-dt / 0.08f);
			if (pushFade < 0.01f)
				pushPhase = 1f;
		}
		pushPhase = Math.min(1f, pushPhase);
	}

	/** Kicks started since creation or reset (for tests). */
	int pushCyclesStarted()
	{
		return pushCyclesStarted;
	}

	/**
	 * Passes the body flip angle through raw (whole turns never show), except that a jump which is not
	 * whole turns (e.g. a bail mid-flip resetting it to 0) is caught and eased out: a change faster than 60 rad/s
	 * (after taking out whole turns; a double flip in 0.5 s at twice its mean rate turns 4 PI / 0.5 * 2 = 50 rad/s),
	 * or on a landing or bail frame any change bigger than 0.05 rad.
	 */
	private void updateFlip(float input, boolean touchdown, float dt)
	{
		float delta = input - lastFlipInput;
		float turns = Math.round(delta / TWO_PI) * TWO_PI;
		float rest = delta - turns;
		if (Math.abs(rest) > 60f * dt || (touchdown && Math.abs(rest) > 0.05f))
		{
			// keep the drawn angle where it was: rest is wrapped to (-PI, PI], so this is the short way back
			flipCatchUp.value -= rest;
		}
		lastFlipInput = input;
		flipCatchUp.step(0f, 14f, dt);
		flipAngle = input + flipCatchUp.value;
	}

	/** Writes the current pose. */
	public void writeTo(BodyPose out)
	{
		// lean (into the turn) and sway, minus the tumble: falling onto the chest is a negative roll
		out.roll = lean.value + grindSway.value * sway(clock) - tumble.value + grabRoll.value;
		out.pitch = pitch.value + manualSway.value * sway(clock * 1.3f + 0.4f);
		out.pivotX = pivotX;
		PushCycle.sample(pushPhase, push);
		float f = pushFade;
		float c = Math.max(MIN_CROUCH, Math.min(MAX_CROUCH, crouch.value + impact.value + f * push.squash));
		out.legScale = 1f - c;
		// the upper body folds 0.9 rad per unit of crouch
		out.torsoBend = 0.9f * Math.max(0f, c) + grabBend.value;
		// the rear leg is the one on the trailing side; it plants behind, out to the toe (chest, -z) side
		out.torsoLean = f * push.lean * pushTravelX + grabLean.value;
		out.legWeight = f * push.legWeight;
		out.legSide = -pushTravelX;
		out.footX = -pushTravelX * push.back;
		out.footY = push.footY;
		out.footZ = -push.side;
		// + = front flip: the head goes toward the nose, model +x for regular stance
		out.flip = flipAngle;
		out.flipPivotY = BoardPlacement.puppetFlipPivotY();
		out.armWeight = arm.value;
		out.armSide = armSide;
		out.grabAlong = armAlong.value;
		out.grabAcross = armAcross.value;
		out.grabBoardY = armBoardY.value;
		out.kneeFold = kneeFold.value;
		// a grab pulls the feet and the board up 20 units toward the hips (the render pose only, physics keeps its
		// place): with the knees folded up toward the chest this keeps the board near the hands instead of the hands
		// going down to the board under the crotch
		out.feetLift = 20f * liftFold.value;
	}

	/**
	 * Body roll for a carve: 0.6 of the physical lean atan(v w / g) toward the centre of the turn (the full angle
	 * looked like falling over; g the game gravity, SkateTuning.gravity's default 2000), capped at {@link #MAX_LEAN}.
	 * Carve rates above 8 rad/s are heading snaps (a reset or rail lock), not carving. A clockwise (right) carve rolls
	 * negative, the same sense as the board's steer lean; riding fakie (v < 0) the turn's centre is on the other side.
	 */
	static float leanFor(float speed, float carveRate)
	{
		float w = Math.max(-8f, Math.min(8f, carveRate));
		float angle = 0.6f * (float) Math.atan(speed * w / 2000f);
		return -Math.max(-MAX_LEAN, Math.min(MAX_LEAN, angle));
	}

	/**
	 * Peak landing compression for a landing at {@code speed} u/s downward: a full-charge ollie lands at about its
	 * take-off speed (ollieImpulse 820 u/s).
	 */
	static float landingCompression(float speed)
	{
		// 0.22 for that ollie, within 0.04 and 0.3
		float c = 0.22f * Math.abs(speed) / 820f;
		return Math.max(0.04f, Math.min(0.3f, c));
	}

	/** Where the knees want to be this frame (before the landing kick): 1 - legScale, negative extends the legs. */
	static float crouchTarget(Signals s, float airTime, boolean poppedFlight)
	{
		switch (s.state)
		{
			case ROLLING:
			case MANUAL:
				// a rolling grab: low enough (with the grab's fold and knees forward) for the hand to reach the
				// board on the ground, which is not lifted
				return rollingGrab(s) != null ? MAX_CROUCH : CHARGE_CROUCH * PushCycle.clamp01(s.charge);
			case GRINDING:
				// a little crouch on rails
				return 0.14f + CHARGE_CROUCH * 0.5f * PushCycle.clamp01(s.charge);
			case BAILED:
				return 0.25f;
			case AIRBORNE:
				boolean trick = s.flipping || (s.hold != null && s.hold.kind == TrickKind.GRAB)
					|| Math.abs(s.bodyFlipAngle) > 0.01f;
				if (GrabPose.reaches(s.hold) && !s.onFoot)
					// a grab pulls the knees up deeper than a flip's tuck, so the hand can reach the board; straight off
					// the pop it tucks at once: the pop's leg extension would hold it back 0.12 s
					return 0.48f;
				if (poppedFlight && airTime < 0.12f)
					// the legs extend just after the pop
					return -0.18f;
				if (!s.onFoot && trick)
					// a flip or grab tucks deeper
					return 0.38f;
				if (s.verticalSpeed < -350f)
					// falling fast with no trick going: the legs reach for the ground (nearly straight)
					return 0.05f;
				// on foot a jump tucks 0.2 and a fall barely (0.05); on the board 0.26 after a pop, 0.1 off an edge
				return s.onFoot ? poppedFlight ? 0.2f : 0.05f : poppedFlight ? 0.26f : 0.1f;
			default:
				return 0f;
		}
	}

	/** A smooth, non-repeating-looking balance wobble in about -1..1. */
	static float sway(float t)
	{
		return ((float) Math.sin(TWO_PI * 0.8f * t) + 0.5f * (float) Math.sin(TWO_PI * 1.9f * t + 1.3f)) / 1.5f;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.*;
import com.gielinorskate.progression.BoardDesigns;
import com.gielinorskate.progression.BoardLook;
import java.util.*;
import lombok.Setter;
import net.runelite.api.*;

/** Positions the puppet and board from physics state each frame. Client thread only. */
public final class SkaterRenderer
{
	/** Further than this (a call-back) the board appears in the hand instead of flying there. */
	static final float BOARD_MOVE_REACH = 2 * 128f;

	private final Client client;
	private PuppetController puppet;
	/**
	 * One object per part of the board drawn (the baked board has up to four), all placed identically each frame;
	 * the first {@link #boardCount} are in use (none when not spawned).
	 */
	private final BoardController[] boards = new BoardController[4];
	private int boardCount;
	/** The board model drawn now; null when not spawned. */
	private BakedBoardModel poser;
	private int worldViewId;
	private int plane;
	/**
	 * The baked (RuneSkate) board in high (true) and in low ("Normal") detail, each built on first use and kept. A
	 * detail that failed to build (null) isn't tried again.
	 */
	private final Map<Boolean, BakedBoardModel> baked = new HashMap<>();
	private boolean highDetail = true;
	/** The chosen designs, for the next board built and applied to the current one. */
	private BoardLook look = BoardLook.defaults(BoardDesigns.bundled());
	/** The procedural body pose the puppet draws with (neutral until set). */
	@Setter
	private BodyPose bodyPose = new BodyPose();
	/** Told by the puppet whether each draw had a model (null until set). */
	@Setter
	private DrawnModelReport drawnReport;
	private final RidingBoard riding = new RidingBoard();
	/** Seconds since the last pop (large when none recently). */
	private float sincePop;
	/** Seconds since the last stumble (large when none recently): the board wobbles for a moment. */
	private float sinceStumble = Float.MAX_VALUE;
	private boolean popNollie;
	private float lean;
	private float chargeDip;
	/** The board objects are registered. */
	private boolean boardShown;

	/** This frame's body and board placements, and the ones drawn last frame (a blend starts from those). */
	private final Placement bodyTarget = new Placement();
	private final Placement boardTarget = new Placement();
	private final Placement drawnBody = new Placement();
	private final Placement drawnBoard = new Placement();
	private final Placement feetBoard = new Placement();
	/** The walker's right hand read off the drawn mesh: the carried board follows it through the walk cycle. */
	private final HandAnchor hand = new HandAnchor();
	private final SwapBlend swap = new SwapBlend();
	private final SwapBlend boardMove = new SwapBlend();
	private float boardMoveTime;
	private BoardTransition transition = BoardTransition.NONE;
	private float transitionProgress = 1f;
	private BoardTransition lastTransition = BoardTransition.NONE;
	private float lastProgress = 1f;
	/** The board's state last drawn on foot; null on the board. */
	private BoardState lastBoardState;

	public SkaterRenderer(Client client)
	{
		this.client = client;
	}

	/**
	 * Draws the board in {@code look}'s designs, now if skating (only the colours change: the parts are lit again
	 * at their next pose) and on every board built after. Client thread.
	 */
	public void setLook(BoardLook look)
	{
		this.look = look;
		for (BakedBoardModel m : baked.values())
		{
			if (m != null)
				m.setLook(look);
		}
		for (int i = 0; i < boardCount; i++)
			boards[i].repaint();
	}

	/**
	 * The baked board's detail for the local skater: high (each part fills the renderers' per-model budget) or
	 * normal (the low variant party ghosts use too). Applied now if the baked board is drawn. Client thread.
	 */
	public void setBoardDetail(boolean high)
	{
		if (high == highDetail)
			return;
		highDetail = high;
		BakedBoardModel m = boardCount > 0 ? bakedModel() : null;
		if (m != null)
			// a detail that can't be built leaves the board drawn as it was
			setPoser(m);
	}

	/** The baked board at the chosen detail, built on first use; null if it can't be built. */
	private BakedBoardModel bakedModel()
	{
		if (!baked.containsKey(highDetail))
			baked.put(highDetail, BakedBoardModel.create(client, highDetail, look));
		BakedBoardModel m = baked.get(highDetail);
		if (m != null)
			m.setLook(look);
		return m;
	}

	/**
	 * Draws the board with {@code poser}: one object per part, the extra ones created, placed where the board was
	 * last drawn and shown (or hidden and dropped) to match.
	 */
	private void setPoser(BakedBoardModel poser)
	{
		this.poser = poser;
		int n = poser.partCount();
		for (int i = 0; i < boards.length; i++)
		{
			if (i < n && boards[i] == null)
			{
				boards[i] = new BoardController(i);
				boards[i].setWorldView(worldViewId);
				boards[i].setLevel(plane);
				if (drawnBoard.valid)
					place(boards[i], drawnBoard);
			}
			if (i < n)
				boards[i].setBoard(poser, bodyPose);
			if (boardShown && i < n != i < boardCount)
				show(boards[i], i < n);
			if (i >= n)
				boards[i] = null;
		}
		boardCount = n;
	}

	private static void place(RuneLiteObjectController c, Placement p)
	{
		c.setX(Math.round(p.x));
		c.setY(Math.round(p.y));
		c.setZ(Math.round(p.z));
		c.setOrientation(p.orientation());
	}

	private void show(RuneLiteObjectController c, boolean show)
	{
		if (show)
			client.registerRuneLiteObject(c);
		else
			client.removeRuneLiteObject(c);
	}

	/** Spawns the puppet and board; false (nothing spawned) when the board can't be built. */
	public boolean spawn(WorldView wv, int plane)
	{
		BakedBoardModel model = bakedModel();
		if (model == null)
			return false;
		hand.setActive(false);
		puppet = new PuppetController(client, bodyPose, hand);
		puppet.setDrawnReport(drawnReport);
		puppet.setWorldView(wv.getId());
		puppet.setLevel(plane);
		worldViewId = wv.getId();
		this.plane = plane;
		Arrays.fill(boards, null);
		boardCount = 0;
		boardShown = false;
		riding.reset();
		sincePop = Float.MAX_VALUE;
		sinceStumble = Float.MAX_VALUE;
		popNollie = false;
		lean = 0f;
		chargeDip = 0f;
		drawnBody.invalidate();
		drawnBoard.invalidate();
		swap.cancel();
		boardMove.cancel();
		transition = BoardTransition.NONE;
		transitionProgress = 1f;
		lastTransition = BoardTransition.NONE;
		lastProgress = 1f;
		lastBoardState = null;
		setPoser(model);
		client.registerRuneLiteObject(puppet);
		showBoard(true);
		return true;
	}

	/**
	 * Draws {@code p}, the (possibly interpolated) pose of this frame.
	 *
	 * @param nolliePop a pop on this frame was a nollie (popped off the nose)
	 */
	public void update(RenderPose p, float steer, boolean crouching, List<SkateEvent> events, boolean nolliePop, float dt)
	{
		if (puppet == null)
			return;
		showBoard(true);
		boolean popped = events.contains(SkateEvent.POP);
		sincePop = popped ? 0f : sincePop + dt;
		popNollie = popped ? nolliePop : popNollie;
		sinceStumble = events.contains(SkateEvent.STUMBLE) ? 0f : sinceStumble + dt;

		boolean bailed = p.state == SkaterState.BAILED;

		// trick board pose: carve lean (0.15 rad per unit of steer) only while rolling on the ground, plus the
		// physics-driven flip roll / nose-pop pitch / manual-and-grind pitch; the mesh is rebuilt only when roll or
		// pitch actually changes by more than 0.01 rad or the body flip turns (read by the board when drawn).
		// Lean and hold pitch ease in and out; the pop pitch follows its own rise-and-fall curve.
		boolean carving = p.state == SkaterState.ROLLING;
		lean = PoseSmoothing.approach(lean, carving ? -steer * 0.15f : 0f, dt, PoseSmoothing.POSE_TAU);
		boolean charging = crouching && (p.state == SkaterState.ROLLING || p.state == SkaterState.MANUAL);
		// the board (and skater) dip 4 units while crouched to charge a pop
		chargeDip = PoseSmoothing.approach(chargeDip, charging ? 4f : 0f, dt,
			PoseSmoothing.POSE_TAU);
		// a stumble off a wall wobbles the board for a moment
		riding.update(p, Math.round(p.x), Math.round(p.y), lean + p.boardRoll,
			PoseSmoothing.stumbleWobble(sinceStumble), PoseSmoothing.popPitch(sincePop, popNollie), p.boardPitch, 0f,
			p.hold, chargeDip, bodyPose, dt, boardTarget, bodyTarget);
		// just got on: eased over from the walker and the carried board (no blend otherwise)
		lastBoardState = null;
		hand.setActive(false);
		boardMove.cancel();
		blendSwap();
		// the skater's centre of mass is that much lower against a lifted board
		finish(riding.roll, riding.pitch, riding.deckLift - riding.lift, riding.lift, !bailed && puppet.canDeform());
	}

	/**
	 * The latest mount or dismount and how far through it is (0..1), read by both {@link #update} and
	 * {@link #updateOnFoot}: a new one is blended from what was drawn just before.
	 */
	public void setTransition(BoardTransition transition, float progress)
	{
		this.transition = transition;
		this.transitionProgress = progress;
	}

	/**
	 * On foot: the puppet stands at the walker facing the way it walks (its OSRS walk, run and idle animations are
	 * the animator's); the board is in the right hand while carried (CarryPose) and lies flat where it was left when
	 * dropped. Getting off eases the body down and round and the board up into the hand; dropping or picking up
	 * the board nearby moves it there over the same 0.25 s.
	 */
	public void updateOnFoot(OffBoardPose p, float dt)
	{
		if (puppet == null)
			return;
		setTransition(p.transition, p.transitionProgress);
		showBoard(true);
		bodyTarget.set(Math.round(p.walkerX), Math.round(p.walkerY), -Math.round(p.walkerH),
			Angles.toJau(p.walkerHeading), 0f, 0f);
		hand.setActive(p.board != BoardState.DROPPED);
		if (p.board == BoardState.DROPPED)
			boardTarget.set(Math.round(p.boardX), Math.round(p.boardY), -Math.round(p.boardH),
				Angles.toJau(p.boardHeading), 0f, 0f);
		else
		{
			// in the hand as the walk or run animation swings it (the fixed spot until the hand is read)
			hand.step(dt);
			CarryPose.placeAt(p.walkerX, p.walkerY, p.walkerH, p.walkerHeading, p.walkerSpeed, hand.x(), hand.y(),
				hand.z(), boardTarget);
			// the hop onto the board: it comes out of the hand and under the feet on the way down
			float k = p.mountJump && p.airborne ? CarryPose.mountDrop(p.verticalSpeed) : 0f;
			if (k > 0f)
			{
				CarryPose.underFeet(p.walkerX, p.walkerY, p.walkerH, p.walkerHeading, feetBoard);
				SwapBlend.lerp(boardTarget, feetBoard, k);
				boardTarget.copyFrom(feetBoard);
			}
		}
		blendSwap();
		// on foot, the board dropped or picked up within reach moves between hand and ground instead of jumping
		if (lastBoardState != null && p.board != lastBoardState && !swap.isActive() && drawnBoard.valid
			&& Math.hypot(boardTarget.x - drawnBoard.x, boardTarget.y - drawnBoard.y) <= BOARD_MOVE_REACH)
		{
			boardMove.begin(null, drawnBoard, false);
			boardMoveTime = 0f;
		}
		lastBoardState = p.board;
		if (boardMove.isActive())
		{
			boardMoveTime += dt;
			// over 0.25 s (BoardSwap.TRANSITION_SECONDS)
			boardMove.apply(boardMoveTime / 0.25f, null, boardTarget);
		}
		finishOffBoard();
	}

	/**
	 * Knocked off the board: the body where the knockdown puts it, facing along its tumble (the tumble itself, the
	 * lie-down and the get-up are the body pose's, written by the animator first: its flip angle decides how far the
	 * body comes down so its lowest point stays on the ground), and the board on its own, spinning and flipping
	 * until it rests. A mount or dismount blend in progress is dropped; getting back on with R blends from here.
	 */
	public void updateKnockdown(KnockdownPose k)
	{
		if (puppet == null)
			return;
		showBoard(true);
		stopBlends();
		float down = TumbleBody.groundOffset(bodyPose.flip);
		bodyTarget.set(Math.round(k.bodyX), Math.round(k.bodyY), -Math.round(k.bodyH + down),
			Angles.toJau(k.facing + Angles.PI / 2), 0f, 0f);
		boardTarget.set(Math.round(k.boardX), Math.round(k.boardY),
			-Math.round(k.boardH + KnockdownPose.boardLift(k.boardRoll)), Angles.toJau(k.boardYaw), k.boardRoll,
			k.boardPitch);
		finishOffBoard();
	}

	/** A knockdown: no blend runs, and a mount or dismount after it is new. */
	private void stopBlends()
	{
		hand.setActive(false);
		boardMove.cancel();
		swap.cancel();
		lastBoardState = null;
		lastTransition = transition;
		lastProgress = transitionProgress;
	}

	/** A new mount or dismount starts easing from the last drawn placements; one in progress eases on. */
	private void blendSwap()
	{
		if (SwapBlend.starts(lastTransition, lastProgress, transition, transitionProgress))
		{
			swap.begin(drawnBody, drawnBoard, transition == BoardTransition.MOUNT);
			boardMove.cancel();
		}
		lastTransition = transition;
		lastProgress = transitionProgress;
		swap.apply(transitionProgress, bodyTarget, boardTarget);
	}

	/** Off the board: back on it, its trick pose is rebuilt from scratch. */
	private void finishOffBoard()
	{
		riding.offBoard();
		finish(0f, 0f, 0, 0, false);
	}

	/**
	 * Poses every board part, tells the body the board as drawn ({@code roll}, {@code pitch}, the deck lift and the
	 * grab's lift: a grabbing hand goes to it), moves the body and board to this frame's placements and remembers
	 * them for the next blend.
	 */
	private void finish(float roll, float pitch, int pivotLift, int lift, boolean flip)
	{
		for (int i = 0; i < boardCount; i++)
		{
			boards[i].setPose(boardTarget.roll, boardTarget.pitch, BoardPlacement.boardFlipPivotY(pivotLift), flip);
			// every part of the board in exactly the same place
			place(boards[i], boardTarget);
		}
		bodyPose.boardRoll = roll;
		bodyPose.boardPitch = pitch;
		bodyPose.deckLift = pivotLift + lift;
		bodyPose.boardLift = lift;
		place(puppet, bodyTarget);
		drawnBody.copyFrom(bodyTarget);
		drawnBoard.copyFrom(boardTarget);
	}

	/** Shows or hides the board objects. */
	private void showBoard(boolean show)
	{
		if (show != boardShown && boardCount > 0)
		{
			boardShown = show;
			for (int i = 0; i < boardCount; i++)
				show(boards[i], show);
		}
	}

	public void despawn()
	{
		if (puppet != null)
			client.removeRuneLiteObject(puppet);
		showBoard(false);
		puppet = null;
		Arrays.fill(boards, null);
		boardCount = 0;
		poser = null;
	}
}

package com.gielinorskate.render;

import com.gielinorskate.physics.BoardTransition;
import lombok.Getter;

/**
 * Getting on or off the board without a snap: when a mount or dismount starts, the body and board placements
 * drawn just before are kept, and for the transition's 0.25 s (BoardSwap.TRANSITION_SECONDS) each frame's
 * placements are drawn eased from those toward where they now belong (a live target, so a walker or a rolling
 * skater keeps moving). Getting on also hops the body up a little in the middle, so stepping onto a dropped
 * board reads as a step up onto it. The same blend moves a board alone (dropped or picked up). Pure.
 */
public final class SwapBlend
{

	private final Placement fromBody = new Placement();
	private final Placement fromBoard = new Placement();
	private boolean hop;
	@Getter
	private boolean active;

	/** A transition {@code t} at {@code progress} is new since the last frame's ({@code lastT}, {@code lastProgress}). */
	public static boolean starts(BoardTransition lastT, float lastProgress, BoardTransition t, float progress)
	{
		return t != BoardTransition.NONE && progress < 1f && (t != lastT || progress < lastProgress);
	}

	/**
	 * Starts a blend from what was drawn last: either placement may be null or not valid (nothing drawn), and
	 * that object is then not blended. With neither, there is no blend.
	 *
	 * @param hop the body hops (getting on)
	 */
	public void begin(Placement body, Placement board, boolean hop)
	{
		fromBody.invalidate();
		fromBoard.invalidate();
		if (body != null)
			fromBody.copyFrom(body);
		if (board != null)
			fromBoard.copyFrom(board);
		this.hop = hop;
		active = fromBody.valid || fromBoard.valid;
	}

	public void cancel()
	{
		active = false;
	}

	/**
	 * Blends {@code body} and {@code board} (this frame's targets, overwritten in place) from the start, at
	 * {@code progress} 0..1 of the transition. At 1 the targets are left as they are and the blend ends.
	 */
	public void apply(float progress, Placement body, Placement board)
	{
		active &= progress < 1f;
		if (!active)
			return;
		float w = ease(progress);
		if (fromBody.valid && body != null)
		{
			lerp(fromBody, body, w);
			// up 16 units at the middle of a mount (RuneLite z grows downward)
			body.z -= hop ? 16f * 4f * w * (1f - w) : 0f;
		}
		if (fromBoard.valid && board != null)
			lerp(fromBoard, board, w);
	}

	/** Smoothstep of {@code t} clamped to 0..1: starts and ends at rest. */
	public static float ease(float t)
	{
		return PushCycle.smoothstep(0f, 1f, t);
	}

	/** {@code t} of the way from orientation {@code a} to {@code b} (JAU) the short way round, in 0..2048. */
	public static float lerpJau(float a, float b, float t)
	{
		float d = (b - a) % 2048f;
		d += d > 1024f ? -2048f : d <= -1024f ? 2048f : 0f;
		float r = (a + d * t) % 2048f;
		return r < 0f ? r + 2048f : r;
	}

	/** {@code to} becomes {@code w} of the way from {@code from} to it. */
	public static void lerp(Placement from, Placement to, float w)
	{
		to.set(RenderPose.mix(from.x, to.x, w), RenderPose.mix(from.y, to.y, w), RenderPose.mix(from.z, to.z, w),
			lerpJau(from.jau, to.jau, w), RenderPose.mix(from.roll, to.roll, w), RenderPose.mix(from.pitch, to.pitch, w));
	}
}

package com.gielinorskate.scoring;

import static com.gielinorskate.tricks.TrickKind.*;

import com.gielinorskate.tricks.*;
import java.util.*;
import java.util.stream.Collectors;
import javax.inject.Singleton;
import lombok.*;
import lombok.experimental.Accessors;

/**
 * Pure combo/score bookkeeping, fed by {@link TrickEvent}s drained from the physics layer.
 * Holds no RuneLite dependencies so it can be unit tested directly.
 */
@Singleton
@Accessors(fluent = true)
public class ComboScorer
{
	/** Per-repeat decay applied to a trick's points, floored at {@link #DECAY_FLOOR}. */
	public static final float DECAY_PER_REPEAT = 0.75f;
	public static final float DECAY_FLOOR = 0.25f;
	/**
	 * Holds shorter than this are dropped (a tap of the manual key or a grab key is not a trick). Was
	 * 0.25 s while manuals came from a still mouse wind-up and flicks cut stray ones short; on the
	 * manual key a deliberate manual-to-pop is often only 0.2 s, i.e. 10 steps of 0.02 s.
	 */
	public static final float MIN_HOLD_SECONDS = 0.15f;
	/** Fraction added to a combo that lands clean (board lined up within 15 degrees, flip finished). */
	public static final float CLEAN_BONUS = 0.1f;
	/** Variety: fraction added to a trick's points the first time it lands in a skate session (by decay key). */
	public static final float FIRST_LANDING_BONUS = 0.25f;
	/** Variety: a combo lasting longer than this (first trick or hold start to landing) gets one more multiplier. */
	public static final float LONG_COMBO_SECONDS = 8f;

	/** What a landed combo held, for progression (session goals, XP). Immutable. */
	@AllArgsConstructor
	public static final class Summary
	{
		/** A summary of nothing (before any landing). */
		public static final Summary NONE = new Summary(Collections.emptyList(), 0f, 0f, 0, 0, 0, false, 0, false);

		/** The combo's tricks in order (spins on their own are left out). */
		public final List<Trick> tricks;
		/** Seconds of grinding and of manuals in the combo. */
		public final float grindSeconds;
		public final float manualSeconds;
		/** Biggest spin in the combo, in half turns either way (2 = a 360). */
		public final int maxSpinHalfTurns;
		/** The landed value (same as {@link Result#value}) and multiplier, bonuses included. */
		public final int value;
		public final int multiplier;
		public final boolean clean;
		/** Tricks landed for the first time this session (each got {@link #FIRST_LANDING_BONUS}). */
		public final int newTricks;
		/** Lasted longer than {@link #LONG_COMBO_SECONDS} (got one more multiplier). */
		public final boolean longCombo;
	}

	/** Resolution of a finished combo, surfaced to the HUD. */
	@AllArgsConstructor(access = AccessLevel.PRIVATE)
	@EqualsAndHashCode
	@ToString
	public static final class Result
	{
		public enum Kind
		{
			NONE,
			LANDED,
			BAILED
		}

		public static final Result NONE = new Result(Kind.NONE, 0, false);

		public final Kind kind;
		public final int value;
		/** A combo landed clean (see {@link ComboScorer#CLEAN_BONUS}); its value already includes the bonus. */
		public final boolean clean;

		public static Result landed(int value)
		{
			return new Result(Kind.LANDED, value, false);
		}

		/** A clean landing ({@link TrickEvent#clean}); {@code value} includes the bonus. */
		public static Result landedClean(int value)
		{
			return new Result(Kind.LANDED, value, true);
		}

		/** @param lostValue the combo value that was lost (shown struck through) */
		public static Result bailed(int lostValue)
		{
			return new Result(Kind.BAILED, lostValue, false);
		}

		public boolean isLanded()
		{
			return kind == Kind.LANDED;
		}

		public boolean isBailed()
		{
			return kind == Kind.BAILED;
		}
	}

	/**
	 * One scored trick. {@code key} identifies it for repetition decay and the distinct-trick multiplier: the
	 * trick's enum name, plus "/n" for a spun trick of n half turns either way ("OLLIE/1" for a BS or FS 180
	 * Ollie), or "SPIN/n" for a spin with no trick of its own. Fakie or not, and the spin direction, do not
	 * change the key.
	 */
	@AllArgsConstructor
	private static final class Entry
	{
		/** Null for a spin on its own. */
		final Trick trick;
		final boolean fakie;
		final String key;
		final String name;
		final int points;
		/** Seconds held, for a grab, manual or grind; 0 otherwise. */
		final float seconds;
		/** Half turns of spin either way (0 when none). */
		final int spinHalfTurns;
	}

	private final List<Entry> comboEntries = new ArrayList<>();
	private final Map<String, Integer> sessionRepeatCounts = new HashMap<>();
	/**
	 * Index of the current air's main trick (its pop, or the last board flip started in it), which a SPIN
	 * renames; -1 when there is none (a roll-off, or the air ended in a manual or grind).
	 */
	private int airMain = -1;

	/**
	 * Decay keys landed so far this skate session, for {@link #FIRST_LANDING_BONUS}; null until
	 * {@link #startSession()} (the variety bonuses only apply inside a skate session).
	 */
	private Set<String> landedKeys;
	/** Score-clock time the combo in progress began (its first trick, or its first hold's start); NaN when none. */
	private float comboStart = Float.NaN;
	/** What the combo that last landed held; {@link Summary#NONE} before any landing. Bails leave it as it was. */
	@Getter
	private Summary lastSummary = Summary.NONE;

	@Getter
	private int sessionScore;
	@Getter
	private Result lastResult = Result.NONE;
	/** Trick names of the combo that last landed or bailed, kept for the HUD's result flash. */
	@Getter
	private List<String> lastComboNames = Collections.emptyList();
	private float lastResultTime = -Float.MAX_VALUE;
	private float lastEventTime = -Float.MAX_VALUE;
	/** Distinct tricks (the multiplier) and every trick entry of the combo that last landed or bailed (for callouts). */
	@Getter
	private int lastResultMultiplier;
	@Getter
	private int lastResultTrickCount;
	/** Bumped on every landing or bail that produced a {@link #lastResult()}, so readers can spot a new one. */
	@Getter
	private int resultSequence;
	/** Score-clock time the newest trick line last appeared or was renamed, for the HUD's pop-in; -Float.MAX_VALUE before any. */
	@Getter
	private float newestNameTime = -Float.MAX_VALUE;
	/** Score-clock time the multiplier last went up, for the HUD ring's pulse; -Float.MAX_VALUE before any. */
	@Getter
	private float multiplierRiseTime = -Float.MAX_VALUE;

	/** Scores one event; a LANDED event with {@link TrickEvent#clean} adds {@link #CLEAN_BONUS} to the landed combo. */
	public void accept(TrickEvent e, float now)
	{
		int sizeBefore = comboEntries.size();
		String newestBefore = sizeBefore == 0 ? null : comboEntries.get(sizeBefore - 1).name;
		int multiplierBefore = multiplier();
		apply(e, now);
		int size = comboEntries.size();
		if (size > 0 && (size != sizeBefore || !comboEntries.get(size - 1).name.equals(newestBefore)))
			newestNameTime = now;
		if (size > 0 && multiplier() > multiplierBefore)
			multiplierRiseTime = now;
	}

	private void apply(TrickEvent e, float now)
	{
		Trick t = e.trick;
		switch (e.type)
		{
			case TRICK:
				// a re-flick upgrade replaces the last entry of the flip it upgrades
				int index = put(e.upgradedFrom == null ? -1
						: comboEntries.stream().map(x -> x.trick).collect(Collectors.toList()).lastIndexOf(e.upgradedFrom),
					t, e.fakie, t.name(), e.displayName(), t.points, 0f, 0);
				// a pop or a board flip (not a front or back flip of the body) is the trick a spin in the same air renames
				if ((t.kind == POP || t.kind == FLIP) && t.bodyFlipTurns == 0f)
					airMain = index;
				markStart(now);
				break;
			case SPIN:
				int amount = Math.abs(e.spinHalfTurns);
				if (amount > 0)
				{
					// a landed spin renames the air's main trick ("FS 180 Kickflip") and adds SpinNames.bonus, decayed
					// by the spun trick's own key; with no trick in that air it is an entry of its own ("BS 360")
					Entry main = airMain >= 0 && airMain < comboEntries.size() ? comboEntries.get(airMain) : null;
					if (main != null && main.trick != null)
					{
						String spun = SpinNames.name(main.trick.displayName, e.spinHalfTurns);
						put(airMain, main.trick, main.fakie, main.trick.name() + "/" + amount,
							main.fakie ? "Fakie " + spun : spun, main.trick.points + SpinNames.bonus(amount), 0f, amount);
					}
					else
						put(-1, null, false, "SPIN/" + amount, SpinNames.label(e.spinHalfTurns), SpinNames.bonus(amount),
							0f, amount);
					airMain = -1;
				}
				if (!comboEntries.isEmpty())
					markStart(now);
				break;
			case HOLD_START:
				if (t != null && (t.kind == MANUAL || t.kind == GRIND))
				{
					airMain = -1; // back on the ground or a rail: the air is over
				}
				break;
			case HOLD_END:
				if (e.seconds >= MIN_HOLD_SECONDS)
				{
					put(-1, t, false, t.name(), t.displayName, Math.round(t.points * e.seconds), e.seconds, 0);
					markStart(now - e.seconds);
				}
				break;
			case LANDED:
				resolveLanded(now, now, e.clean);
				return;
			case BAILED:
				finish(Result.bailed(comboPoints() * multiplier()), now);
				return;
		}
		lastEventTime = now;
	}

	/**
	 * Puts a new entry, its points decayed by the repeats of its key this session, at index {@code i} (undoing the
	 * replaced entry's repeat count) or, when {@code i} is negative, at the end. Returns its
	 * index.
	 */
	private int put(int i, Trick trick, boolean fakie, String key, String name, int basePoints, float seconds,
		int spinHalfTurns)
	{
		if (i >= 0)
		{
			Entry old = comboEntries.get(i);
			sessionRepeatCounts.computeIfPresent(old.key, (k, n) -> n > 1 ? n - 1 : null);
		}
		int n = sessionRepeatCounts.getOrDefault(key, 0);
		sessionRepeatCounts.put(key, n + 1);
		float decay = (float) Math.max(DECAY_FLOOR, Math.pow(DECAY_PER_REPEAT, n));
		Entry entry = new Entry(trick, fakie, key, name, Math.round(basePoints * decay), seconds, spinHalfTurns);
		if (i < 0)
		{
			comboEntries.add(entry);
			return comboEntries.size() - 1;
		}
		comboEntries.set(i, entry);
		return i;
	}

	/**
	 * A new skate session: from now on the variety bonuses apply, and every trick counts as new again for
	 * {@link #FIRST_LANDING_BONUS}.
	 */
	public void startSession()
	{
		landedKeys = new HashSet<>();
	}

	private void markStart(float t)
	{
		if (Float.isNaN(comboStart) || t < comboStart)
			comboStart = t;
	}

	/**
	 * Lands the combo in progress now, without waiting for the roll-out (stepping off the board banks it). Not
	 * clean. Nothing happens when there is no combo.
	 */
	public void bankCombo(float now)
	{
		resolveLanded(now, lastEventTime, false);
	}

	public void update(float now, boolean rollingWithoutHold)
	{
		// half a second of rolling without a new trick or hold ends a combo as a landing
		if (rollingWithoutHold && now - lastEventTime >= 0.5f)
			// the combo ended with its last trick, not after the roll-out wait
			resolveLanded(now, lastEventTime, false);
	}

	/**
	 * @param now when the result shows
	 * @param end when the combo ended, for {@link #LONG_COMBO_SECONDS}
	 */
	private void resolveLanded(float now, float end, boolean clean)
	{
		if (comboEntries.isEmpty())
			// a plain drop off a curb (roll-off, then land) has nothing to score or show
			return;
		int points = 0;
		int newTricks = 0;
		int spin = 0;
		float grind = 0f;
		float manual = 0f;
		List<Trick> tricks = new ArrayList<>();
		Set<String> fresh = new HashSet<>();
		for (Entry entry : comboEntries)
		{
			points += entry.points;
			// variety: each trick's first landing this session scores a quarter more (the first entry of its key)
			if (landedKeys != null && !landedKeys.contains(entry.key) && fresh.add(entry.key))
			{
				points += Math.round(entry.points * FIRST_LANDING_BONUS);
				newTricks++;
			}
			spin = Math.max(spin, entry.spinHalfTurns);
			if (entry.trick != null)
			{
				tricks.add(entry.trick);
				grind += entry.trick.kind == GRIND ? entry.seconds : 0f;
				manual += entry.trick.kind == MANUAL ? entry.seconds : 0f;
			}
		}
		boolean longCombo = landedKeys != null && !Float.isNaN(comboStart) && end - comboStart > LONG_COMBO_SECONDS;
		int multiplier = multiplier() + (longCombo ? 1 : 0);
		int value = points * multiplier;
		if (clean)
			value = Math.round(value * (1f + CLEAN_BONUS));
		if (landedKeys != null)
			landedKeys.addAll(fresh);
		sessionScore += value;
		lastSummary = new Summary(Collections.unmodifiableList(tricks), grind, manual, spin, value, multiplier, clean,
			newTricks, longCombo);
		finish(clean ? Result.landedClean(value) : Result.landed(value), now);
	}

	/** Shows {@code result} for the combo in progress and clears it. */
	private void finish(Result result, float now)
	{
		lastResultMultiplier = multiplier();
		lastResultTrickCount = comboEntries.size();
		resultSequence++;
		lastComboNames = comboNames();
		lastResult = result;
		lastResultTime = now;
		abandonCombo();
	}

	/** Drops the combo in progress without scoring it or showing a result (e.g. leaving skate mode mid-air). */
	public void abandonCombo()
	{
		comboEntries.clear();
		airMain = -1;
		lastEventTime = -Float.MAX_VALUE;
		comboStart = Float.NaN;
	}

	/** The last 6 trick names of the combo in progress. */
	public List<String> comboNames()
	{
		int size = comboEntries.size();
		return Collections.unmodifiableList(comboEntries.subList(Math.max(0, size - 6), size).stream()
			.map(e -> e.name).collect(Collectors.toList()));
	}

	public int comboPoints()
	{
		return comboEntries.stream().mapToInt(e -> e.points).sum();
	}

	/** Distinct trick keys in the combo in progress. */
	public int multiplier()
	{
		return (int) comboEntries.stream().map(e -> e.key).distinct().count();
	}

	public float lastResultAge(float now)
	{
		return now - lastResultTime;
	}
}

package com.gielinorskate.scoring;

import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Score timing in seconds since this clock was created (plugin start), shared by the session and
 * the HUD. Counting from a recent origin keeps float seconds precise: raw System.nanoTime() / 1e9
 * as a float only resolves 0.25 s steps after ~24 days of uptime (2^21 s; float has a 24-bit
 * mantissa), while 2^21 s of plugin uptime would be needed here for the same loss.
 */
@Singleton
public class ScoreClock
{
	private final LongSupplier nanos;
	private final long startNanos;

	@Inject
	public ScoreClock()
	{
		this(System::nanoTime);
	}

	ScoreClock(LongSupplier nanos)
	{
		this.nanos = nanos;
		this.startNanos = nanos.getAsLong();
	}

	public float now()
	{
		return (nanos.getAsLong() - startNanos) / 1_000_000_000f;
	}
}

package com.gielinorskate.session;

import com.gielinorskate.GielinorSkateConfig.AfterBail;

/** What a bail does. Pure. */
final class BailRules
{
	private BailRules()
	{
	}

	/**
	 * A bail knocks the skater off the board ({@link Knockdown}) with "Get knocked off", the default; otherwise ("Hop
	 * straight back on") it is the quick fall and straight back on.
	 */
	static boolean knocksOff(AfterBail setting)
	{
		return setting != AfterBail.HOP_BACK_ON;
	}
}

package com.gielinorskate.session;

import com.gielinorskate.physics.*;
import com.gielinorskate.world.GridCollisionWorld;
import lombok.Getter;

/**
 * On board or on foot, and where the board is: the rules for getting off, getting on, dropping, picking up,
 * calling the board back and jump-mounting. Pure: the session applies the physics side of each
 * {@link Action}. Client thread only.
 */
@Getter
public final class BoardSwap
{
	/** The board can be stepped on or picked up from within 1.5 tiles. */
	public static final float PICKUP_RADIUS = 1.5f * GridCollisionWorld.TILE;
	/** A jump starting or landing within a tile of the dropped board lands on it. */
	public static final float JUMP_MOUNT_RADIUS = GridCollisionWorld.TILE;
	/** Mount and dismount blends last this long (drawn by the renderer). */
	public static final float TRANSITION_SECONDS = 0.25f;

	/** What the session must do. */
	public enum Action
	{
		NONE,
		/** Step off the board and pick it up (now ON_FOOT, CARRIED). */
		DISMOUNT,
		/** Drop the carried board under the feet and hop on (now ON_BOARD, rolling on at the walker's speed). */
		MOUNT_CARRIED,
		/** Step onto the dropped board where it lies (now ON_BOARD, speed 0). */
		MOUNT_DROPPED,
		/** A jump landed on the board (now ON_BOARD, rolling at {@link #jumpMountSpeed}). */
		JUMP_MOUNT,
		/** The far dropped board came back to hand (now CARRIED). */
		CALL_BACK,
		/** The carried board was put down at the feet (now DROPPED). */
		DROP,
		/** The dropped board was picked up (now CARRIED). */
		PICK_UP
	}

	private SkateMode mode = SkateMode.ON_BOARD;
	private BoardState board = BoardState.CARRIED;
	private float boardX;
	private float boardY;
	private float boardH;
	private float boardHeading;
	private BoardTransition transition = BoardTransition.NONE;
	private float transitionAge;

	/** A new session: on the board. */
	public void reset()
	{
		set(SkateMode.ON_BOARD, BoardState.CARRIED, BoardTransition.NONE);
	}

	/** Now in {@code mode} with the board {@code board}, starting the blend {@code t}. */
	private void set(SkateMode mode, BoardState board, BoardTransition t)
	{
		this.mode = mode;
		this.board = board;
		transition = t;
		transitionAge = 0f;
	}

	/** The board is put down at (x, y, h), its nose along {@code heading}. */
	private void drop(float x, float y, float h, float heading)
	{
		board = BoardState.DROPPED;
		boardX = x;
		boardY = y;
		boardH = h;
		boardHeading = heading;
	}

	/** Advances the transition blend. */
	public void tick(float dt)
	{
		if (transition != BoardTransition.NONE)
			transitionAge += dt;
	}

	/**
	 * The board key went down.
	 *
	 * On foot a single press always gets the board back: stepped on when the dropped board is within reach,
	 * called back to hand (CARRIED) when it is further away, even mid-jump.
	 *
	 * @param grounded on the ground: on the board rolling or in a manual, on foot not in a jump or fall (the board
	 * is never stepped on or off in the air)
	 * @param wx walker (or skater) position
	 */
	public Action onBoardKeyPressed(boolean grounded, float wx, float wy)
	{
		if (mode == SkateMode.ON_FOOT && board == BoardState.DROPPED && !inReach(wx, wy))
		{
			board = BoardState.CARRIED;
			return Action.CALL_BACK;
		}
		if (!grounded)
			return Action.NONE;
		if (mode == SkateMode.ON_BOARD)
		{
			set(SkateMode.ON_FOOT, BoardState.CARRIED, BoardTransition.DISMOUNT);
			return Action.DISMOUNT;
		}
		Action a = board == BoardState.CARRIED ? Action.MOUNT_CARRIED : Action.MOUNT_DROPPED;
		remount();
		return a;
	}

	/**
	 * The board key was held {@link com.gielinorskate.input.BoardKey#HOLD_MS}: no longer needed (a tap calls the
	 * board back), but a hold that started mid-jump next to the board still gets it back to hand.
	 */
	public Action onBoardKeyHeld()
	{
		if (mode == SkateMode.ON_FOOT && board == BoardState.DROPPED)
		{
			board = BoardState.CARRIED;
			return Action.CALL_BACK;
		}
		return Action.NONE;
	}

	/**
	 * Q or E on foot: drops the carried board at the feet, or picks the dropped one up when within reach.
	 *
	 * @param wh ground height at the feet, where a dropped board lies
	 */
	public Action onDropPickup(float wx, float wy, float wh, float heading)
	{
		if (mode != SkateMode.ON_FOOT)
			return Action.NONE;
		if (board == BoardState.CARRIED)
		{
			drop(wx, wy, wh, heading);
			return Action.DROP;
		}
		if (inReach(wx, wy))
		{
			board = BoardState.CARRIED;
			return Action.PICK_UP;
		}
		return Action.NONE;
	}

	/**
	 * A jump (not a fall) landed on foot. It lands on the board when it started or landed within
	 * {@link #JUMP_MOUNT_RADIUS} of the dropped board, or when it took off sprinting with the board carried.
	 *
	 * @param startX take-off point, NaN for a fall
	 */
	public Action onLanded(float startX, float startY, float landX, float landY, boolean jumpedSprinting)
	{
		if (mode != SkateMode.ON_FOOT || Float.isNaN(startX) || Float.isNaN(startY))
			return Action.NONE;
		boolean mounts = board == BoardState.CARRIED
			? jumpedSprinting
			: within(startX, startY, JUMP_MOUNT_RADIUS) || within(landX, landY, JUMP_MOUNT_RADIUS);
		if (!mounts)
			return Action.NONE;
		remount();
		return Action.JUMP_MOUNT;
	}

	/** A sprinting jump-mount lands rolling at least this fraction of the push top speed (Skate 3's run-and-jump-on). */
	public static final float SPRINT_MOUNT_FRACTION = 0.65f;
	/** A walking jump-mount lands rolling at least this fraction of the push top speed. */
	public static final float MOVING_MOUNT_FRACTION = 0.35f;
	/** Slower than this (u/s) a jump-mount is a standing hop on: it gets no boost. */
	public static final float MOVING_SPEED = 40f;

	/**
	 * The speed a jump-mount rolls away at: the jump's horizontal speed, raised to a good share of the push top
	 * speed when moving ({@link #SPRINT_MOUNT_FRACTION} from a sprint, else {@link #MOVING_MOUNT_FRACTION}): the
	 * jump on is the push. Never more than the push top speed.
	 *
	 * @param sprinted sprinting as the jump took off
	 */
	public static float jumpMountSpeed(float horizontalSpeed, boolean sprinted, float maxPushSpeed)
	{
		float v = Math.max(0f, horizontalSpeed);
		if (v >= MOVING_SPEED)
			v = Math.max(v, (sprinted ? SPRINT_MOUNT_FRACTION : MOVING_MOUNT_FRACTION) * maxPushSpeed);
		return Math.min(v, maxPushSpeed);
	}

	/** The speed stepping onto the carried board rolls away at: the walker's own, up to the push top speed. */
	public static float stepOnSpeed(float horizontalSpeed, float maxPushSpeed)
	{
		return Math.max(0f, Math.min(horizontalSpeed, maxPushSpeed));
	}

	/**
	 * Whether a jump taking off now at (wx, wy) is one {@link #onLanded} will put on the board (sprinting with the
	 * board carried, or from within {@link #JUMP_MOUNT_RADIUS} of the dropped board): it gets the bigger mount hop.
	 */
	public boolean willJumpMount(boolean sprinting, float wx, float wy)
	{
		return mode == SkateMode.ON_FOOT && (board == BoardState.CARRIED ? sprinting : within(wx, wy, JUMP_MOUNT_RADIUS));
	}

	/**
	 * A bail knocked the skater off: on foot, with the board lying where it came to rest, without a mount or
	 * dismount blend (the knockdown drew the way there).
	 */
	public void knockedOff(float bx, float by, float bh, float heading)
	{
		set(SkateMode.ON_FOOT, BoardState.DROPPED, BoardTransition.NONE);
		drop(bx, by, bh, heading);
	}

	/** Back on the board (R during a knockdown: blended from where the body lies). */
	public void remount()
	{
		set(SkateMode.ON_BOARD, BoardState.CARRIED, BoardTransition.MOUNT);
	}

	/** The dropped board is within {@link #PICKUP_RADIUS} of (x, y). */
	public boolean inReach(float x, float y)
	{
		return board == BoardState.DROPPED && within(x, y, PICKUP_RADIUS);
	}

	private boolean within(float x, float y, float r)
	{
		return Math.hypot(x - boardX, y - boardY) <= r;
	}

	/** 0 at the start of the latest mount or dismount, 1 once it is over (and when there was none). */
	public float getTransitionProgress()
	{
		return transition == BoardTransition.NONE ? 1f : Math.min(1f, transitionAge / TRANSITION_SECONDS);
	}
}

package com.gielinorskate.session;

import java.awt.Rectangle;
import java.util.*;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InterfaceID.ToplevelOsrsStretch;
import net.runelite.api.gameval.InterfaceID.ToplevelPreEoc;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;

/**
 * The canvas areas where clicks pass through to the game while skating: the side panel (its tab stones and the
 * open panel) and the chatbox. World clicks stay blocked (no world interaction from the detached camera), so a
 * transparent resizable chatbox whose clicks fall through to the world is left out apart from its tab row.
 * Client thread only.
 */
final class ClickThroughAreas
{
	/** Fixed mode: tab stones, the panel area and the chatbox. */
	private static final int[] FIXED = {
		InterfaceID.Toplevel.SIDE_TOP, InterfaceID.Toplevel.SIDE_BOTTOM, InterfaceID.Toplevel.SIDE,
	};

	/** Resizable classic: tab stones and each tab's panel (only the open one is not hidden). */
	private static final int[] STRETCH = {
		ToplevelOsrsStretch.SIDE_TOP, ToplevelOsrsStretch.SIDE_BOTTOM,
		ToplevelOsrsStretch.SIDE0, ToplevelOsrsStretch.SIDE1,
		ToplevelOsrsStretch.SIDE2, ToplevelOsrsStretch.SIDE3,
		ToplevelOsrsStretch.SIDE4, ToplevelOsrsStretch.SIDE5,
		ToplevelOsrsStretch.SIDE6, ToplevelOsrsStretch.SIDE7,
		ToplevelOsrsStretch.SIDE8, ToplevelOsrsStretch.SIDE9,
		ToplevelOsrsStretch.SIDE10, ToplevelOsrsStretch.SIDE11,
		ToplevelOsrsStretch.SIDE12, ToplevelOsrsStretch.SIDE13,
	};

	/** Resizable modern: the stone bar and each tab's panel (only the open one is not hidden). */
	private static final int[] PRE_EOC = {
		ToplevelPreEoc.SIDE_STATIC, ToplevelPreEoc.SIDE_MOVABLE,
		ToplevelPreEoc.SIDE0, ToplevelPreEoc.SIDE1,
		ToplevelPreEoc.SIDE2, ToplevelPreEoc.SIDE3,
		ToplevelPreEoc.SIDE4, ToplevelPreEoc.SIDE5,
		ToplevelPreEoc.SIDE6, ToplevelPreEoc.SIDE7,
		ToplevelPreEoc.SIDE8, ToplevelPreEoc.SIDE9,
		ToplevelPreEoc.SIDE10, ToplevelPreEoc.SIDE11,
		ToplevelPreEoc.SIDE12, ToplevelPreEoc.SIDE13,
	};

	private ClickThroughAreas()
	{
	}

	static List<Rectangle> collect(Client client)
	{
		List<Rectangle> out = new ArrayList<>();
		boolean resized = client.isResized();
		add(client, out, resized ? STRETCH : FIXED);
		if (resized)
			add(client, out, PRE_EOC);
		// the chat tab buttons are always solid; the message area only when its clicks don't fall through
		add(client, out, InterfaceID.Chatbox.CONTROLS);
		boolean transparent = resized && client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY) == 1;
		if (!transparent || client.getVarbitValue(VarbitID.TRANSPARENT_CHATBOX_BLOCKCLICK) == 1)
			add(client, out, InterfaceID.Chatbox.CHATAREA);
		return out.isEmpty() ? Collections.emptyList() : out;
	}

	/** Adds the bounds of each of these widgets that is shown. */
	private static void add(Client client, List<Rectangle> out, int... ids)
	{
		for (int id : ids)
		{
			Widget w = client.getWidget(id);
			Rectangle r = w == null || w.isHidden() ? null : w.getBounds();
			if (r != null && r.width > 0 && r.height > 0)
				out.add(r);
		}
	}
}

package com.gielinorskate.session;

import com.gielinorskate.Text;
import com.gielinorskate.controller.PadButton;
import com.gielinorskate.input.InputController;
import com.gielinorskate.input.KeyboardTricks;
import java.awt.event.KeyEvent;
import java.util.*;
import lombok.Getter;
import net.runelite.api.HitsplatID;

/** Pure timing and wording for the comfort hints: idle-logout warning, loaded-area edge, stumble flash. */
public final class ComfortHints
{
	/** The first-run welcome, said once ever (the hidden seenIntro setting remembers it). */
	public static String welcome(String toggleKey)
	{
		return Text.get("ch.welcome", toggleKey);
	}

	/**
	 * The manual key's name for the controls card: the configured one when usable, else its stand-in (C with
	 * keyboard tricks on, Space otherwise; see {@link InputController#effectiveManualKey}).
	 */
	public static String manualKeyLabel(String configuredName, int code, boolean keyboardTricks)
	{
		return InputController.isValidManualKey(code, keyboardTricks) ? configuredName : keyboardTricks ? "C" : "Space";
	}

	/** Why the configured manual key is not used, for chat; null when it is used as set. */
	public static String manualKeyNote(String configuredName, int code, boolean keyboardTricks)
	{
		if (InputController.isValidManualKey(code, keyboardTricks))
			return null;
		String standIn = manualKeyLabel(configuredName, code, keyboardTricks);
		return Text.get("ch.manual." + (keyboardTricks && KeyboardTricks.isTrickKey(code) ? "tricks" : "clash"),
			configuredName, standIn);
	}

	/** The board on/off key's name in use: the configured one, or F when it is not usable (see {@link InputController#effectiveBoardKey}). */
	public static String boardKeyLabel(String configuredName, int code, boolean keyboardTricks)
	{
		return InputController.effectiveBoardKey(code, keyboardTricks) == code ? configuredName : "F";
	}

	/** Why the configured board key is not used, for chat; null when it is used as set (or unset). */
	public static String boardKeyNote(String configuredName, int code, boolean keyboardTricks)
	{
		if (InputController.effectiveBoardKey(code, keyboardTricks) == code)
			return null;
		return Text.get("ch.board." + (keyboardTricks && KeyboardTricks.isTrickKey(code) ? "tricks" : "control"),
			configuredName);
	}

	/**
	 * The board on/off key set to the same key as other settings ({@code others}: setting name to key code, in
	 * order): the board key wins, so the others never see that key. One note naming every clashing setting, for
	 * chat; null when none clash or the board key is unset. Keys match by key code, as the input does.
	 */
	public static String boardKeyClashNote(String boardKeyName, int boardCode, Map<String, Integer> others)
	{
		if (boardCode == KeyEvent.VK_UNDEFINED)
			return null;
		List<String> clashes = new ArrayList<>();
		others.forEach((name, code) ->
		{
			if (code != null && code == boardCode)
				clashes.add(name);
		});
		if (clashes.isEmpty())
			return null;
		// "a", "a and b", "a, b and c"
		int last = clashes.size() - 1;
		String names = last == 0 ? clashes.get(0)
			: String.join(", ", clashes.subList(0, last)) + " and " + clashes.get(last);
		return Text.get("ch.clash", boardKeyName, names);
	}

	/**
	 * In Controller mode, a key setting on a pad key wins over the pad button that sends it (see
	 * {@link InputController#isPadKeyFree}), for chat: one note per such setting. {@code taken}: the key settings
	 * in use, name to key code, in order.
	 */
	public static List<String> padKeyNotes(Map<String, Integer> taken)
	{
		List<String> out = new ArrayList<>();
		for (Map.Entry<String, Integer> e : taken.entrySet())
		{
			PadButton b = e.getValue() == null ? null : PadButton.forKey(e.getValue());
			if (b != null)
				out.add(Text.get("ch.padkey", e.getKey(), b.keyName, b.label));
		}
		return out;
	}

	/** Warn this many client ticks (20 ms) before the idle logout: one minute. */
	static final int IDLE_WARN_BEFORE_TICKS = 3000;
	private static final int TICKS_PER_MINUTE = 3000;
	/** The edge hint shows within EDGE_HINT_TILES of the loaded area's edge, fully from EDGE_HINT_FULL_TILES. */
	static final float EDGE_HINT_TILES = 6f;
	static final float EDGE_HINT_FULL_TILES = 3f;
	/** Starting closer than this to the edge suggests a more central spot. */
	static final float ROOM_TIP_TILES = 20f;
	/** "Stumble!" shows fully for STUMBLE_HOLD seconds, then fades over STUMBLE_FADE. */
	static final float STUMBLE_HOLD = 0.5f;
	static final float STUMBLE_FADE = 0.3f;

	private ComfortHints()
	{
	}

	/**
	 * Watches the game's idle time. Skate keys and right-drags are consumed, so the game does not count them as
	 * activity; this only warns, it never keeps the player logged in.
	 */
	public static final class IdleWarning
	{
		@Getter
		private boolean warning;

		/**
		 * @param idleTicks client ticks since the last input the game saw (keyboard and mouse, whichever is less)
		 * @param timeoutTicks the client's idle logout timeout in client ticks
		 * @return true once, when the idle time first comes within a minute of the logout
		 */
		public boolean update(int idleTicks, int timeoutTicks)
		{
			boolean near = idleTicks > timeoutTicks - IDLE_WARN_BEFORE_TICKS;
			boolean crossed = near && !warning;
			warning = near;
			return crossed;
		}

		public void reset()
		{
			warning = false;
		}
	}

	/** Whole minutes of idle time. */
	static int idleMinutes(int idleTicks)
	{
		return idleTicks / TICKS_PER_MINUTE;
	}

	/** The chat and HUD wording of the idle warning. */
	static String idleMessage(int idleTicks)
	{
		int minutes = idleMinutes(idleTicks);
		return Text.get("ch.idle", minutes, minutes == 1 ? "" : "s");
	}

	/** Opacity of the "Edge of the loaded area" hint at {@code tiles} from the edge. */
	public static float edgeHintAlpha(float tiles)
	{
		return !(tiles < EDGE_HINT_TILES) ? 0f : tiles <= EDGE_HINT_FULL_TILES ? 1f
			: (EDGE_HINT_TILES - tiles) / (EDGE_HINT_TILES - EDGE_HINT_FULL_TILES);
	}

	/** True when skating starts this close to the edge of the loaded area (in tiles). */
	static boolean needsRoomTip(float tiles)
	{
		return tiles < ROOM_TIP_TILES;
	}

	/** Opacity of the "Stumble!" flash {@code since} seconds after the stumble. */
	public static float stumbleFlashAlpha(float since)
	{
		return since < 0f || since >= STUMBLE_HOLD + STUMBLE_FADE ? 0f
			: since <= STUMBLE_HOLD ? 1f : 1f - (since - STUMBLE_HOLD) / STUMBLE_FADE;
	}

	/** Why damage of this hitsplat type ended skating. */
	public static String damageMessage(int hitsplatType)
	{
		return Text.get("ch.dmg." + (hitsplatType == HitsplatID.POISON ? "poison"
			: hitsplatType == HitsplatID.VENOM ? "venom" : "hit"));
	}
}

package com.gielinorskate.session;

import com.gielinorskate.physics.*;
import java.util.Random;
import lombok.Getter;

/**
 * A bail that knocks the skater off the board: the body is thrown and tumbles ({@link TumbleBody}) while the board
 * flies off on its own ({@link BoardBounce}); after the impact the skater lies still for {@link #LIE_SECONDS}, then
 * gets up over {@link #GET_UP_SECONDS} and is on foot. Short by design: never more than {@link #MAX_TUMBLE} plus those
 * from the bail to standing, however far the fall. Pure: the session steps it, feeds it the keys and acts on its
 * {@link Outcome}s. Client thread only.
 * <p>
 * Keys: R skips the rest and puts the skater straight back on the board; during the lie-down a new move key or a
 * jump skips to the get-up, and the board key ends it at once to get the board back.
 */
public final class Knockdown
{
	/** The flight is cut short (the lie-down starts) after this, even mid-fall. */
	public static final float MAX_TUMBLE = 0.8f;
	/** Lying still after the impact. */
	public static final float LIE_SECONDS = 0.5f;
	/** Getting back up. */
	public static final float GET_UP_SECONDS = 0.4f;


	public enum Phase
	{
		/** Thrown off, in the air. */
		TUMBLE,
		/** Down after the impact (still skidding to a stop at first). */
		LIE,
		/** Getting up where the body lies. */
		GET_UP,
		/** Over: standing (or skipped). */
		DONE
	}

	/** What a key did. */
	public enum Outcome
	{
		NONE,
		/** R: back on the board where the body lies. */
		BACK_ON_BOARD,
		/** The board key while down: stand now and get the board back (step on it nearby, else call it). */
		RECLAIM
	}

	@Getter
	private final TumbleBody body;
	@Getter
	private final BoardBounce board;
	@Getter
	private Phase phase = Phase.DONE;
	private float phaseTime;
	private boolean impactPending;
	/** A move key was held at the last input (a key held through the bail must be pressed again to skip). */
	private boolean moveWasHeld = true;
	/** The lying angle the get-up starts from. */
	private float getUpFrom;

	public Knockdown(CollisionWorld world, float gravity, float radius)
	{
		body = new TumbleBody(world, gravity, radius);
		board = new BoardBounce(world, gravity);
	}

	/**
	 * Knocks the skater at (x, y, h), moving at (vx, vy) and facing {@code heading}, off the board.
	 *
	 * @param wall a wall bail, the wall's outward normal (nx, ny)
	 */
	public void start(float x, float y, float h, float vx, float vy, float heading, boolean wall, float nx, float ny,
		Random random)
	{
		body.start(x, y, h, vx, vy, heading, wall, nx, ny, random.nextFloat() * 2f - 1f);
		board.start(x, y, h, vx, vy, heading, random);
		phase = Phase.TUMBLE;
		phaseTime = 0f;
		impactPending = false;
		moveWasHeld = true;
	}

	/** One fixed step of the body, the board and the phase timing. */
	public void step(float dt)
	{
		if (phase == Phase.DONE || !(dt > 0f))
			return;
		body.step(dt);
		board.step(dt);
		impactPending |= body.takeImpact();
		phaseTime += dt;
		switch (phase)
		{
			case TUMBLE:
				if (body.hasLanded() || phaseTime >= MAX_TUMBLE)
					enter(Phase.LIE);
				break;
			case LIE:
				if (phaseTime >= LIE_SECONDS)
					startGetUp();
				break;
			case GET_UP:
				if (phaseTime >= GET_UP_SECONDS)
					finish();
				break;
			default:
				break;
		}
	}

	/**
	 * This frame's keys.
	 *
	 * @param reset R went down
	 * @param moveHeld a move key (W, A, S, D) is held now: a new press skips the lie-down
	 * @param jumpPressed Space went down
	 * @param boardPressed the board key went down
	 */
	public Outcome input(boolean reset, boolean moveHeld, boolean jumpPressed, boolean boardPressed)
	{
		boolean movePressed = moveHeld && !moveWasHeld;
		moveWasHeld = moveHeld;
		if (phase == Phase.DONE)
			return Outcome.NONE;
		if (reset)
		{
			finish();
			return Outcome.BACK_ON_BOARD;
		}
		if (phase == Phase.LIE || phase == Phase.GET_UP)
		{
			if (boardPressed)
			{
				finish();
				return Outcome.RECLAIM;
			}
			if (phase == Phase.LIE && (movePressed || jumpPressed))
				startGetUp();
		}
		return Outcome.NONE;
	}

	private void enter(Phase p)
	{
		phase = p;
		phaseTime = 0f;
	}

	private void startGetUp()
	{
		body.stop();
		getUpFrom = body.getAngle();
		enter(Phase.GET_UP);
	}

	private void finish()
	{
		body.stop();
		if (!board.isAtRest())
			board.restNow();
		enter(Phase.DONE);
	}

	/** True once, at the body's first touchdown (sounds, smoke, the camera kick). */
	public boolean takeImpact()
	{
		boolean i = impactPending;
		impactPending = false;
		return i;
	}

	public boolean isDone()
	{
		return phase == Phase.DONE;
	}

	/** 0..1 through the current lie-down or get-up (0 in the air, 1 when done). */
	public float getPhaseProgress()
	{
		return phase == Phase.LIE ? Math.min(1f, phaseTime / LIE_SECONDS)
			: phase == Phase.GET_UP ? Math.min(1f, phaseTime / GET_UP_SECONDS) : phase == Phase.DONE ? 1f : 0f;
	}

	/**
	 * The body's tumble angle as drawn: the body sim's in the air and lying, easing (smoothstep) from the lying
	 * angle to the nearest whole turn, upright, through the get-up.
	 */
	public float bodyAngle()
	{
		if (phase == Phase.GET_UP || phase == Phase.DONE)
		{
			float from = phase == Phase.GET_UP ? getUpFrom : body.getAngle();
			float upright = Math.round(from / Angles.TWO_PI) * Angles.TWO_PI;
			if (phase == Phase.DONE)
				return upright;
			float u = getPhaseProgress();
			float s = u * u * (3f - 2f * u);
			return from + (upright - from) * s;
		}
		return body.getAngle();
	}

	/** Where the skater faces once up: toward the board (the body's facing when the board is right there). */
	public float standHeading()
	{
		float dx = board.getX() - body.getX();
		float dy = board.getY() - body.getY();
		return Math.hypot(dx, dy) < 1f ? body.getFacing() : Angles.wrap((float) Math.atan2(dx, dy));
	}
}

package com.gielinorskate.session;

import com.gielinorskate.Text;
import java.util.*;
import net.runelite.api.WorldType;

/**
 * Where skating is allowed. Two tiers:
 * <ul>
 * <li>Always blocked (no setting changes this): instances, PvP minigames (Last Man Standing, Castle Wars,
 * Soul Wars, Clan Wars, the PvP Arena), the Deadman Wilderness and the PvP minigame world types.</li>
 * <li>Blocked unless "Allow skating in PvP areas" is on: the Wilderness and PvP worlds. Other players are
 * hidden while skating there.</li>
 * </ul>
 * Combat always blocks.
 */
public final class SafetyRules
{
	/** World types that only exist for a PvP minigame; never skate there. */
	private static final Set<WorldType> MINIGAME_WORLD_TYPES =
		EnumSet.of(WorldType.PVP_ARENA, WorldType.LAST_MAN_STANDING, WorldType.BOUNTY);

	/** Open-world PvP world types; covered by the "Allow skating in PvP areas" opt-in. */
	private static final Set<WorldType> OPT_IN_PVP_WORLD_TYPES =
		EnumSet.of(WorldType.PVP, WorldType.HIGH_RISK, WorldType.DEADMAN);

	/**
	 * Map regions of PvP minigames, region id = (worldX >> 6) << 8 | (worldY >> 6). Source: RuneLite's own
	 * Discord plugin, runelite-client/src/main/java/net/runelite/client/plugins/discord/DiscordGameEventType.java
	 * (MG_CASTLE_WARS, MG_SOUL_WARS, MG_CLAN_WARS, MG_EMIRS_ARENA, MG_LAST_MAN_STANDING_*), fetched 2026-10-04.
	 * Listed under sr.regions in the bundled text.
	 */
	private static final int[] MINIGAME_REGIONS = Text.ints("sr.regions");

	private SafetyRules()
	{
	}

	/** The game's region id of a world tile. */
	public static int regionId(int worldX, int worldY)
	{
		return (worldX >> 6) << 8 | (worldY >> 6);
	}

	public static boolean isBlockedMinigameRegion(int regionId)
	{
		return Arrays.stream(MINIGAME_REGIONS).anyMatch(r -> r == regionId);
	}

	/** PvP, High Risk and Deadman worlds: skating there needs the PvP-areas opt-in. */
	public static boolean isOptInPvpWorld(Collection<WorldType> types)
	{
		return types.stream().anyMatch(OPT_IN_PVP_WORLD_TYPES::contains);
	}

	/**
	 * In an open-world PvP area: the Wilderness varbit, or PVP_AREA_CLIENT (1 anywhere the player can be attacked
	 * by other players, e.g. the Wilderness and the dangerous parts of PvP worlds).
	 */
	public static boolean inPvpArea(boolean insideWildernessVarbit, boolean pvpAreaVarbit)
	{
		return insideWildernessVarbit || pvpAreaVarbit;
	}

	/**
	 * Returns why skating can never start here, whatever the settings, or null.
	 *
	 * @param instance the top-level world view is an instance
	 * @param lastManStandingInGame the BR_INGAME varbit is set
	 * @param deadmanWilderness the DEADMAN_INWILDERNESS varbit is set
	 * @param regionId the real character's region (see {@link #regionId})
	 */
	public static String alwaysBlockedReason(boolean instance, boolean lastManStandingInGame,
		boolean deadmanWilderness, Collection<WorldType> worldTypes, int regionId)
	{
		if (instance)
			return Text.get("sr.instance");
		if (lastManStandingInGame || deadmanWilderness || isBlockedMinigameRegion(regionId))
			return Text.get("sr.minigame");
		for (WorldType t : worldTypes)
		{
			if (MINIGAME_WORLD_TYPES.contains(t))
				return Text.get("sr.world." + t);
		}
		return null;
	}

	/**
	 * Returns a chat message explaining why skate mode can't start, or null if it can.
	 *
	 * @param inWilderness in an open-world PvP area (see {@link #inPvpArea})
	 * @param allowPvpAreas the player opted in to skating in the Wilderness and on PvP worlds (other players are
	 *     hidden there while skating, see {@link #hideOtherPlayers}); combat always blocks
	 */
	public static String blockReason(boolean inWilderness, boolean pvpWorld, boolean inCombat, boolean allowPvpAreas)
	{
		if (inCombat)
			return Text.get("sr.combat");
		if ((inWilderness || pvpWorld) && !allowPvpAreas)
			return Text.get("sr.pvp." + inWilderness);
		return null;
	}

	/**
	 * Checked every frame against the skater's own tile (the real character never moves, the skater does):
	 * returns why skating must end now, or null.
	 */
	public static String skaterAreaBlockReason(int worldX, int worldY, boolean allowPvpAreas)
	{
		if (isBlockedMinigameRegion(regionId(worldX, worldY)))
			return Text.get("sr.ended.minigame");
		if (!allowPvpAreas && isWildernessTile(worldX, worldY))
			return Text.get("sr.ended.wild");
		return null;
	}

	/**
	 * While skating in a PvP area, other players are not drawn at all, so the free skate camera can never be
	 * used to spot other players.
	 */
	public static boolean hideOtherPlayers(boolean inWilderness, boolean pvpWorld)
	{
		return inWilderness || pvpWorld;
	}

	/**
	 * Approximate Wilderness bounds in world tiles (surface north of the ditch, and the Wilderness dungeons), used
	 * to hide other players when the skater rolls into the Wilderness while the real character stays outside it.
	 */
	public static boolean isWildernessTile(int worldX, int worldY)
	{
		boolean inX = worldX >= 2944 && worldX <= 3391;
		boolean surface = worldY >= 3520 && worldY <= 3967;
		boolean dungeons = worldY >= 9920 && worldY <= 10431;
		return inX && (surface || dungeons);
	}
}

package com.gielinorskate.session;

import com.gielinorskate.scoring.ComboScorer;

/**
 * Best landed combo and tricks landed since the client started, for the side panel. Fed the scorer's latest result
 * every frame; a result counts once (by the scorer's result sequence number). Pure.
 */
public final class SessionStats
{
	/** The scorer starts at sequence 0 with no result. */
	private int seenSequence;
	private int bestCombo;
	private int tricksLanded;

	/** Takes in the scorer's latest result if it is new; returns true when the stats changed. */
	public boolean update(int resultSequence, ComboScorer.Result result, int trickCount)
	{
		if (resultSequence == seenSequence)
			return false;
		seenSequence = resultSequence;
		if (result == null || !result.isLanded())
			return false;
		bestCombo = Math.max(bestCombo, result.value);
		tricksLanded += trickCount;
		return true;
	}

	public int bestCombo()
	{
		return bestCombo;
	}

	public int tricksLanded()
	{
		return tricksLanded;
	}
}

package com.gielinorskate.session;

import java.util.Set;

/** What a setting changed while skating does: applied now, applied next session, or nothing to do. */
final class SettingsApply
{
	enum Kind
	{
		/** Re-applied to the running session. */
		LIVE,
		/** Read only when skating starts: the player is told it applies next time. */
		NEXT_SESSION,
		/** Read every frame (or not ours to handle): nothing to do or say. */
		ALREADY_LIVE
	}

	private static final Set<String> LIVE = Set.of("cameraZoom", "flickSensitivity", "manualKey", "trickControls",
		"flickButton", "mirrorFlicks", "controllerMode", "brakeKey", "leanForwardKey", "leanBackKey", "boardKey",
		"controllerPreset", "customControllerLayout");
	private static final Set<String> NEXT_SESSION = Set.of("speedScale", "popScale", "forgivingCollisions",
		"passThroughVegetation");

	private SettingsApply()
	{
	}

	static Kind classify(String key)
	{
		return LIVE.contains(key) ? Kind.LIVE : NEXT_SESSION.contains(key) ? Kind.NEXT_SESSION : Kind.ALREADY_LIVE;
	}
}

