package com.gielinorskate.tricks;

import static com.gielinorskate.tricks.Trick.*;

import java.util.Arrays;
import java.util.List;

/**
 * Which grab a grab key picks, and its tweak. Pure.
 *
 * <p>A grab key held in the air grabs with one hand: Q the left (front) hand, E the right (back) hand. The way
 * the mouse (or right stick) moved just after the press aims it at a part of the board; with no aim Q is an
 * Indy and E a Melon, as before directional grabs. Held past {@link #TWEAK_SECONDS} a grab turns into its
 * tweak once.
 */
public final class Grabs
{
	/** Seconds after the grab key press during which an aim still picks the grab. */
	public static final float AIM_SECONDS = 0.15f;
	/** A grab held longer than this (seconds) turns into its tweak. */
	public static final float TWEAK_SECONDS = 0.5f;
	/** Each plain grab, and at the same index its tweak. */
	private static final List<Trick> PLAIN = Arrays.asList(MELON, INDY, MUTE, STALEFISH, NOSEGRAB, TAILGRAB, CRAIL);
	private static final List<Trick> TWEAKS = Arrays.asList(METHOD, TWEAKED_INDY, JAPAN, TWEAKED_STALEFISH, NOSEBONE,
		TAILBONE, CRAIL_TWEAK);

	/** The part of the board a grab is aimed at, relative to the board and the rider's stance. */
	public enum Aim
	{
		/** Toward the nose (mouse up). */
		NOSE,
		/** Toward the tail (mouse down). */
		TAIL,
		/** Toward the toe (chest) side. */
		TOE,
		/** Toward the heel (back) side. */
		HEEL
	}

	private Grabs()
	{
	}

	/** The grab for the left hand (Q) when {@code left}, else the right hand (E), aimed at {@code aim} (null: none). */
	public static Trick pick(boolean left, Aim aim)
	{
		if (aim == null)
			return left ? INDY : MELON;
		switch (aim)
		{
			case NOSE:
				return left ? NOSEGRAB : CRAIL;
			case TOE:
				return left ? MUTE : INDY;
			case HEEL:
				return left ? MELON : STALEFISH;
			default:
				return TAILGRAB;
		}
	}

	/** The tweak of {@code grab}, or null when it has none (a tweak already, or not a grab). */
	public static Trick tweaked(Trick grab)
	{
		return swap(grab, PLAIN, TWEAKS);
	}

	/** True for the tweaked form of a grab. */
	public static boolean isTweaked(Trick t)
	{
		return TWEAKS.contains(t);
	}

	/** The plain grab {@code t} is the tweak of, or null when it is not a tweak. */
	public static Trick untweaked(Trick t)
	{
		return swap(t, TWEAKS, PLAIN);
	}

	private static Trick swap(Trick t, List<Trick> from, List<Trick> to)
	{
		int i = from.indexOf(t);
		return i < 0 ? null : to.get(i);
	}
}

package com.gielinorskate.tricks;

/**
 * Names a body spin (the skater's heading change from take-off to landing) in 180-degree steps.
 *
 * <p>Rounding: a spin counts as n half turns once it reaches n * 180 - 30 degrees, so 150 is a 180,
 * 330 a 360 and 510 a 540 (anything short of that is the step below). Over-rotation within the landing
 * tolerance still counts as the step reached.
 *
 * <p>Direction: heading is clockwise from above, and the skater rides regular (left foot forward, facing
 * the right of the board's nose). A clockwise spin (heading increasing, + half turns) turns the back to
 * the direction of travel first: <b>Backside</b>. Counter-clockwise (-) is <b>Frontside</b>. The label
 * follows the rotation relative to the stance, so it is the same riding fakie (a fakie trick keeps its
 * "Fakie" prefix in front: "Fakie BS 180 Ollie").
 */
public final class SpinNames
{
	/** Bonus points per 180 degrees of spin. */
	public static final int POINTS_PER_HALF_TURN = 150;

	private SpinNames()
	{
	}

	/** Signed number of half turns in {@code spinRadians}: + = clockwise from above (backside). */
	public static int halfTurns(float spinRadians)
	{
		// a hair of tolerance so exactly 150 / 330 degrees given in float radians still count
		double deg = Math.abs(Math.toDegrees(spinRadians)) + 1e-3;
		int n = (int) Math.floor((deg + 30) / 180.0); // a spin 30 degrees short of the next 180 still counts as it
		return spinRadians < 0 ? -n : n;
	}

	/** "BS 180", "FS 540", ... or "" for no spin. */
	public static String label(int halfTurns)
	{
		return halfTurns == 0 ? "" : (halfTurns > 0 ? "BS " : "FS ") + Math.abs(halfTurns) * 180;
	}

	/** The spin label in front of {@code base} ("FS 180 Kickflip"), the label alone for an empty base. */
	public static String name(String base, int halfTurns)
	{
		String label = label(halfTurns);
		return label.isEmpty() ? base : base.isEmpty() ? label : label + " " + base;
	}

	/** Spin bonus points: {@link #POINTS_PER_HALF_TURN} per half turn either way. */
	public static int bonus(int halfTurns)
	{
		return POINTS_PER_HALF_TURN * Math.abs(halfTurns);
	}
}

package com.gielinorskate.tricks;

import com.gielinorskate.Text;

/**
 * Catalog of every trick the skater can perform. {@code rollTurns} and {@code yawTurns} are the
 * board's rotation around its long axis and the vertical axis respectively, in full turns
 * (1.0 = 360 degrees); {@code duration} is the number of seconds the board takes to complete that
 * rotation, or 0 for holds (grabs, manuals, grinds) that don't rotate the board on their own. Entries without a
 * kind are FLIPs. Each constant's display name, kind, points and turns are bundled under trick.NAME
 * (text/data.properties).
 */
public enum Trick
{
	OLLIE,
	NOLLIE,
	KICKFLIP,
	HEELFLIP,
	POP_SHOVE_IT,
	FS_POP_SHOVE_IT,
	SHOVE_IT_360,
	FS_SHOVE_IT_360,
	VARIAL_KICKFLIP,
	VARIAL_HEELFLIP,
	TRE_FLIP,
	LASER_FLIP,
	DOUBLE_KICKFLIP,
	DOUBLE_HEELFLIP,
	NOLLIE_KICKFLIP,
	NOLLIE_HEELFLIP,
	// nollie forms of the shove-its and the 360 flip: 50 more than the regular trick, like the other nollies
	NOLLIE_SHOVE_IT,
	NOLLIE_FS_SHOVE_IT,
	NOLLIE_TRE_FLIP,
	INDY,
	MELON,
	// directional grabs (a grab key held while the mouse moves; see Grabs) and their tweaks: a grab held past
	// 0.5 s turns into its tweak, worth half as much again per second
	MUTE,
	STALEFISH,
	NOSEGRAB,
	TAILGRAB,
	CRAIL,
	METHOD,
	TWEAKED_INDY,
	JAPAN,
	TWEAKED_STALEFISH,
	NOSEBONE,
	TAILBONE,
	CRAIL_TWEAK,
	MANUAL,
	NOSE_MANUAL,
	FIFTY_FIFTY,
	FIVE_O,
	NOSEGRIND,
	BOARDSLIDE,
	CROOKED,
	// slide and crooked variations (W / S while locking or mid-grind) and the lipslide (board turned past
	// square to the approach): each a little harder to hold than the plain one, so worth a little more
	NOSESLIDE,
	TAILSLIDE,
	SMITH,
	FEEBLE,
	LIPSLIDE,
	// Shift held as the flick fires. (Party ghosts send tricks by name: renaming a constant breaks the wire.)
	// Impossible: the board wraps end over end around the back foot (pitch, nose up and over)
	IMPOSSIBLE,
	// hardflip = kickflip + frontside shove; inward heelflip = heelflip + backside shove
	HARDFLIP,
	INWARD_HEELFLIP,
	// bigspin: a 360 shove-it with the body turning 180 the same way (applied by physics over the duration)
	BIGSPIN,
	FS_BIGSPIN,
	NOLLIE_HARDFLIP,
	NOLLIE_INWARD_HEELFLIP,
	// a re-flick during a double
	TRIPLE_KICKFLIP,
	TRIPLE_HEELFLIP,
	// body flips (Shift + W / Shift + S in the air): the whole skater turns end over end, scored on landing
	FRONTFLIP,
	BACKFLIP,
	DOUBLE_FRONTFLIP,
	DOUBLE_BACKFLIP;

	public final String displayName;
	public final TrickKind kind;
	/** Flat points for POP/FLIP; points per second for GRAB/MANUAL/GRIND. */
	public final int points;
	/** Board flips around its long axis; + = kickflip direction. */
	public final float rollTurns;
	/** Board spins around the vertical axis; + = backside/clockwise from above. */
	public final float yawTurns;
	/** Seconds to complete the board rotation (0 for holds). */
	public final float duration;
	/** Board flips end over end (around its width); + = nose up and over (impossible). */
	public final float pitchTurns;
	/**
	 * Turns of the skater's own body (heading) that are part of the trick, applied by the physics over its
	 * duration; + = clockwise from above. A bigspin's body 180. The board's {@link #yawTurns} are its turn in
	 * the world, so relative to the turning body it turns yawTurns - bodyYawTurns.
	 */
	public final float bodyYawTurns;
	/**
	 * Whole-body flips of a body-flip trick (skater and board about the centre of mass); + = frontflip
	 * (forward pitch). 0 for every board trick. A body flip has no board rotation or duration of its own.
	 */
	public final float bodyFlipTurns;

	Trick()
	{
		// display name|kind|points|rollTurns|yawTurns|duration|pitchTurns|bodyYawTurns|bodyFlipTurns
		String[] p = Text.get("trick." + name()).split("\\|");
		displayName = p[0];
		kind = TrickKind.valueOf(p[1]);
		points = Integer.parseInt(p[2]);
		rollTurns = Float.parseFloat(p[3]);
		yawTurns = Float.parseFloat(p[4]);
		duration = Float.parseFloat(p[5]);
		pitchTurns = Float.parseFloat(p[6]);
		bodyYawTurns = Float.parseFloat(p[7]);
		bodyFlipTurns = Float.parseFloat(p[8]);
	}
}

package com.gielinorskate.tricks;

import static com.gielinorskate.tricks.Trick.*;

import com.gielinorskate.tricks.Gesture.Direction;

/** Maps a recognized {@link Gesture} to the {@link Trick} it performs. */
public final class TrickCatalog
{
	private TrickCatalog()
	{
	}

	/** Returns the trick for a fresh gesture, or null when nothing matches. */
	public static Trick forGesture(Gesture g)
	{
		Trick hard = g.modified ? modifiedTrick(g) : null;
		if (hard != null)
			return hard;
		// a curve of 150 degrees or more makes the 360 forms, 60 or more the varials
		boolean full = g.turnDegrees >= 150f;
		if (g.nollie)
		{
			switch (g.direction)
			{
				case DOWN:
					return NOLLIE;
				case DOWN_LEFT:
					return full ? NOLLIE_TRE_FLIP : NOLLIE_KICKFLIP;
				case DOWN_RIGHT:
					return NOLLIE_HEELFLIP;
				case LEFT:
					return NOLLIE_SHOVE_IT;
				case RIGHT:
					return NOLLIE_FS_SHOVE_IT;
				default:
					return null;
			}
		}
		boolean varial = g.turnDegrees >= 60f;
		switch (g.direction)
		{
			case UP:
				return OLLIE;
			case UP_LEFT:
				return full ? TRE_FLIP : varial ? VARIAL_KICKFLIP : KICKFLIP;
			case UP_RIGHT:
				return full ? LASER_FLIP : varial ? VARIAL_HEELFLIP : HEELFLIP;
			case LEFT:
				return full ? SHOVE_IT_360 : POP_SHOVE_IT;
			case RIGHT:
				return full ? FS_SHOVE_IT_360 : FS_POP_SHOVE_IT;
			default:
				return null;
		}
	}

	/**
	 * The Shift form of a flick, whatever its curve: ollie -> impossible, kickflip family -> hardflip, heelflip
	 * family -> inward heelflip, shove-its -> bigspins, and the nollie kickflip / heelflip -> nollie hardflip /
	 * nollie inward heelflip. Null when the flick has no Shift form (it is then the plain trick).
	 */
	private static Trick modifiedTrick(Gesture g)
	{
		switch (g.direction)
		{
			case DOWN_LEFT:
				return g.nollie ? NOLLIE_HARDFLIP : null;
			case DOWN_RIGHT:
				return g.nollie ? NOLLIE_INWARD_HEELFLIP : null;
			case UP:
				return g.nollie ? null : IMPOSSIBLE;
			case UP_LEFT:
				return g.nollie ? null : HARDFLIP;
			case UP_RIGHT:
				return g.nollie ? null : INWARD_HEELFLIP;
			case LEFT:
				return g.nollie ? null : BIGSPIN;
			case RIGHT:
				return g.nollie ? null : FS_BIGSPIN;
			default:
				return null;
		}
	}

	/** Returns the upgraded trick for a quick re-flick following {@code current}, or null. */
	public static Trick upgrade(Trick current, Gesture g)
	{
		boolean kick = g.direction == Direction.UP_LEFT;
		boolean heel = g.direction == Direction.UP_RIGHT;
		if (current == null)
			return null;
		switch (current)
		{
			case KICKFLIP:
				return kick ? DOUBLE_KICKFLIP : null;
			case HEELFLIP:
				return heel ? DOUBLE_HEELFLIP : null;
			case DOUBLE_KICKFLIP:
				return kick ? TRIPLE_KICKFLIP : null;
			case DOUBLE_HEELFLIP:
				return heel ? TRIPLE_HEELFLIP : null;
			default:
				return null;
		}
	}
}

package com.gielinorskate.tricks;

import lombok.*;

/** A trick-related occurrence drained from {@code SkatePhysics} for scoring/UI/sound. */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
@EqualsAndHashCode
@ToString
public final class TrickEvent
{
	public enum Type
	{
		TRICK,
		HOLD_START,
		HOLD_END,
		LANDED,
		BAILED,
		/**
		 * The air just landed had a body spin of {@link #spinHalfTurns} half turns (see {@link SpinNames}).
		 * Emitted before that landing's LANDED (or, landing into a manual, before its HOLD_START); the scorer
		 * renames the air's trick ("BS 180 Kickflip") or adds the spin on its own ("FS 540"). Trick is null.
		 */
		SPIN
	}

	public final Type type;
	/** Null for LANDED/BAILED. */
	public final Trick trick;
	/** Hold length in seconds for HOLD_END, else 0. */
	public final float seconds;
	/**
	 * For a TRICK that upgrades the flip in progress (e.g. KICKFLIP -> DOUBLE_KICKFLIP): the trick it
	 * replaces, which the scorer swaps out instead of counting both. Null otherwise.
	 */
	public final Trick upgradedFrom;
	/** For a TRICK: popped while riding fakie (backwards), so it is named "Fakie ...". */
	public final boolean fakie;
	/**
	 * For a LANDED: the landing was clean (board within 15 degrees of the travel, flip finished), which earns
	 * the scorer's clean bonus. Carried on the event so it describes this landing, not whatever the physics
	 * state is when the frame's events are read. False otherwise.
	 */
	public final boolean clean;
	/** For a SPIN: signed half turns, + = clockwise from above (backside for the regular stance). 0 otherwise. */
	public final int spinHalfTurns;

	private static TrickEvent of(Type type, Trick trick, float seconds)
	{
		return new TrickEvent(type, trick, seconds, null, false, false, 0);
	}

	public static TrickEvent trick(Trick trick)
	{
		return trick(trick, false);
	}

	/** A TRICK event; {@code fakie} when it was popped riding backwards. */
	public static TrickEvent trick(Trick trick, boolean fakie)
	{
		return upgrade(trick, null, fakie);
	}

	public static TrickEvent holdStart(Trick trick)
	{
		return of(Type.HOLD_START, trick, 0f);
	}

	public static TrickEvent holdEnd(Trick trick, float seconds)
	{
		return of(Type.HOLD_END, trick, seconds);
	}

	/** A TRICK event for {@code trick} that replaces the flip {@code from} already in progress. */
	public static TrickEvent upgrade(Trick trick, Trick from)
	{
		return upgrade(trick, from, false);
	}

	/** As {@link #upgrade(Trick, Trick)}, for a flip popped riding fakie when {@code fakie}. */
	public static TrickEvent upgrade(Trick trick, Trick from, boolean fakie)
	{
		return new TrickEvent(Type.TRICK, trick, 0f, from, fakie, false, 0);
	}

	/** A LANDED event for a landing that was not clean. */
	public static TrickEvent landed()
	{
		return landed(false);
	}

	/** A LANDED event; {@code clean} when the landing was clean. */
	public static TrickEvent landed(boolean clean)
	{
		return new TrickEvent(Type.LANDED, null, 0f, null, false, clean, 0);
	}

	public static TrickEvent bailed()
	{
		return of(Type.BAILED, null, 0f);
	}

	/** A SPIN event of {@code halfTurns} signed half turns (+ = clockwise from above). */
	public static TrickEvent spin(int halfTurns)
	{
		return new TrickEvent(Type.SPIN, null, 0f, null, false, false, halfTurns);
	}

	/** The name shown for this event's trick: "Fakie " + the trick's name when popped fakie. */
	public String displayName()
	{
		return trick == null ? "" : fakie ? "Fakie " + trick.displayName : trick.displayName;
	}
}

