package com.gielinorskate.ui;

import com.gielinorskate.ui.ControllerGlyphs.Glyph;
import java.awt.*;
import javax.swing.Icon;

/** A row of controller glyphs as a Swing icon, for the side panel. */
public final class ControllerGlyphIcon implements Icon
{
	private final Glyph[] glyphs;
	private final int height;
	private final int gap;

	public ControllerGlyphIcon(int height, Glyph... glyphs)
	{
		this.glyphs = glyphs;
		this.height = height;
		gap = Math.max(1, height / 6);
	}

	@Override
	public void paintIcon(Component c, Graphics g, int x, int y)
	{
		for (Glyph glyph : glyphs)
		{
			ControllerGlyphs.paint((Graphics2D) g, glyph, x, y, height);
			x += ControllerGlyphs.glyphWidth(glyph, height) + gap;
		}
	}

	@Override
	public int getIconWidth()
	{
		int w = -gap;
		for (Glyph glyph : glyphs)
			w += ControllerGlyphs.glyphWidth(glyph, height) + gap;
		return Math.max(0, w);
	}

	@Override
	public int getIconHeight()
	{
		return height;
	}
}

package com.gielinorskate.ui;

import com.gielinorskate.Text;
import java.awt.*;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.util.*;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Xbox-style controller button prompts, drawn in code (no image assets, no logos): coloured circles with A / B / X /
 * Y, pills for the bumpers, triggers and Back, a stick icon (with L3 / R3 for a click), and a d-pad with one arm lit.
 * Text can carry them as tokens ("{A}: push"), measured and drawn inline by {@link #width} and {@link #drawText}.
 * Pure apart from drawing.
 */
public final class ControllerGlyphs
{
	public enum Glyph
	{
		A, B, X, Y, LB, RB, LT, RT, BACK,
		/** Start / Menu. */
		START, LS, RS,
		/** Clicking the left / right stick in. */
		L3, R3,
		/** D-pad up, down, left and right: the d-pad with that arm lit (the only glyphs with no letters). */
		DUP, DDOWN, DLEFT, DRIGHT;

		/** The letters drawn on it. */
		public final String label;
		/** Its plain name ("A", "LT", "right stick"). */
		final String spoken;
		/** Face buttons only: fill and letter colours. */
		final Color fill;
		final Color letter;

		Glyph()
		{
			// glyph.NAME: "letters|plain name", and for a face button "|fill|letter" colours as hex RGB
			String[] f = Text.get("glyph." + name()).split("\\|");
			label = f[0];
			spoken = f[1];
			fill = f.length > 2 ? new Color(Integer.parseInt(f[2], 16)) : null;
			letter = f.length > 2 ? new Color(Integer.parseInt(f[3], 16)) : null;
		}

		boolean isPill()
		{
			return this == LB || this == RB || this == LT || this == RT || this == BACK || this == START;
		}
	}

	private static final Pattern TOKEN = Pattern.compile("\\{("
		+ Arrays.stream(Glyph.values()).map(Enum::name).collect(Collectors.joining("|")) + ")\\}");
	/** A grey: the d-pad's arms and a stick's cap. */
	private static final Color ARM = new Color(96, 102, 116);
	private static final Color OUTLINE = new Color(0, 0, 0, 150);
	/** Space either side of an inline glyph, as a fraction of the line height. */
	private static final float GAP = 0.12f;

	private ControllerGlyphs()
	{
	}

	/** The text split into its plain pieces (String) and glyphs (Glyph), in order; no empty strings. */
	public static List<Object> split(String text)
	{
		List<Object> out = new ArrayList<>();
		Matcher m = TOKEN.matcher(text);
		int at = 0;
		while (m.find())
		{
			if (m.start() > at)
				out.add(text.substring(at, m.start()));
			out.add(Glyph.valueOf(m.group(1)));
			at = m.end();
		}
		if (at < text.length())
			out.add(text.substring(at));
		return out;
	}

	/** The token for a glyph in text: "{A}". */
	public static String token(Glyph g)
	{
		return "{" + g.name() + "}";
	}

	/** The text with each glyph spelt out ("A", "LT", "right stick"), for places that can only show plain text. */
	public static String plain(String text)
	{
		return split(text).stream().map(p -> p instanceof Glyph ? ((Glyph) p).spoken : (String) p)
			.collect(Collectors.joining());
	}

	/** True when the text has any glyph token. */
	public static boolean hasGlyphs(String text)
	{
		return TOKEN.matcher(text).find();
	}

	/** Width of a glyph drawn {@code h} px tall, without the gaps around it. */
	public static int glyphWidth(Glyph g, int h)
	{
		return g.isPill() ? Math.round(h * (g == Glyph.START ? 2.15f : g == Glyph.BACK ? 2.0f : 1.45f)) : h;
	}

	/** Width of the text as {@link #drawText} draws it: plain pieces in the font, glyphs one line tall. */
	public static int width(String text, FontMetrics metrics)
	{
		int h = metrics.getHeight();
		int gap = Math.max(1, Math.round(h * GAP));
		int w = 0;
		for (Object piece : split(text))
			w += piece instanceof Glyph ? glyphWidth((Glyph) piece, h) + 2 * gap : metrics.stringWidth((String) piece);
		return w;
	}

	/**
	 * Draws the text at (x, baseline) in the graphics' font: plain pieces with a drop shadow (when {@code shadow}
	 * is not null) then {@code color}, glyphs one line tall in their own colours. Plain text is drawn exactly as
	 * two drawString calls would.
	 */
	public static void drawText(Graphics2D graphics, String text, int x, int baseline, Color color, Color shadow,
		int shadowOffset)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int h = metrics.getHeight();
		int gap = Math.max(1, Math.round(h * GAP));
		int top = baseline - metrics.getAscent();
		int cx = x;
		for (Object piece : split(text))
		{
			if (piece instanceof Glyph)
			{
				Glyph g = (Glyph) piece;
				paint(graphics, g, cx + gap, top, h);
				cx += glyphWidth(g, h) + 2 * gap;
				continue;
			}
			String s = (String) piece;
			if (shadow != null)
			{
				graphics.setColor(shadow);
				graphics.drawString(s, cx + shadowOffset, baseline + shadowOffset);
			}
			graphics.setColor(color);
			graphics.drawString(s, cx, baseline);
			cx += metrics.stringWidth(s);
		}
	}

	/** Paints one glyph in the box (x, top, its width, h). Leaves the graphics' colour, font and hints as found. */
	public static void paint(Graphics2D graphics, Glyph g, int x, int top, int h)
	{
		Color oldColor = graphics.getColor();
		Font oldFont = graphics.getFont();
		Stroke oldStroke = graphics.getStroke();
		Object oldAa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		try
		{
			float pad = Math.max(1f, h * 0.06f);
			float size = h - 2 * pad;
			float y = top + pad;
			float left = x + pad;
			graphics.setStroke(new BasicStroke(Math.max(1f, h / 14f)));
			if (g.fill != null)
			{
				// a face button
				Ellipse2D circle = new Ellipse2D.Float(left, y, size, size);
				graphics.setColor(g.fill);
				graphics.fill(circle);
				graphics.setColor(OUTLINE);
				graphics.draw(circle);
				label(graphics, g.label, g.letter, left, y, size, size, 0.62f);
			}
			else if (g.isPill())
			{
				float w = glyphWidth(g, h) - 2 * pad;
				float ph = size * 0.8f;
				RoundRectangle2D pill = new RoundRectangle2D.Float(left, y + (size - ph) / 2f, w, ph, ph, ph);
				graphics.setColor(new Color(58, 62, 72));
				graphics.fill(pill);
				graphics.setColor(new Color(150, 156, 170));
				graphics.draw(pill);
				label(graphics, g.label, Color.WHITE, left, y + (size - ph) / 2f, w, ph,
					g == Glyph.BACK || g == Glyph.START ? 0.5f : 0.62f);
			}
			else if (g.label.isEmpty())
			{
				// the d-pad: a cross of grey arms, the one pressed lit white
				float arm = size / 3f;
				graphics.setColor(ARM);
				graphics.fill(new RoundRectangle2D.Float(left, y + arm, size, arm, arm / 3f, arm / 3f));
				graphics.fill(new RoundRectangle2D.Float(left + arm, y, arm, size, arm / 3f, arm / 3f));
				graphics.setColor(Color.WHITE);
				float lit = arm * 1.1f;
				boolean upDown = g == Glyph.DUP || g == Glyph.DDOWN;
				float lx = upDown ? left + arm : g == Glyph.DLEFT ? left : left + size - lit;
				float ly = !upDown ? y + arm : g == Glyph.DUP ? y : y + size - lit;
				graphics.fill(new RoundRectangle2D.Float(lx, ly, upDown ? arm : lit, upDown ? lit : arm, arm / 3f,
					arm / 3f));
			}
			else
			{
				// a stick: a dark well, a lighter cap and its letter
				Ellipse2D well = new Ellipse2D.Float(left, y, size, size);
				graphics.setColor(new Color(48, 52, 60));
				graphics.fill(well);
				float cap = size * 0.72f;
				float off = (size - cap) / 2f;
				graphics.setColor(ARM);
				graphics.fill(new Ellipse2D.Float(left + off, y + off, cap, cap));
				graphics.setColor(OUTLINE);
				graphics.draw(well);
				label(graphics, g.label, Color.WHITE, left, y, size, size, 0.55f);
			}
		}
		finally
		{
			graphics.setColor(oldColor);
			graphics.setFont(oldFont);
			graphics.setStroke(oldStroke);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				oldAa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : oldAa);
		}
	}

	/** Centres bold text of {@code scale} x the box height in the box. */
	private static void label(Graphics2D graphics, String text, Color color, float x, float y, float w, float h,
		float scale)
	{
		graphics.setFont(graphics.getFont().deriveFont(Font.BOLD, Math.max(6f, h * scale)));
		FontMetrics m = graphics.getFontMetrics();
		graphics.setColor(color);
		graphics.drawString(text, Math.round(x + (w - m.stringWidth(text)) / 2f),
			Math.round(y + (h - m.getHeight()) / 2f + m.getAscent()));
	}
}

package com.gielinorskate.ui;

import static com.gielinorskate.ui.Widgets.*;

import com.gielinorskate.Text;
import com.gielinorskate.controller.*;
import java.awt.*;
import java.awt.datatransfer.*;
import java.io.IOException;
import java.util.*;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * "Customise controller": each pad button's action on the board and on foot, starting from a preset, saved as the
 * Custom preset; and layout codes to share (copy, and paste with a preview of what changes). Shown in place of the
 * side panel's content with a Back button. Swing only: every method runs on the EDT.
 */
class ControllerLayoutView extends JPanel
{
	private static final Color OK_COLOR = new Color(120, 200, 120);
	private static final Color ERROR_COLOR = new Color(255, 150, 120);

	private final Consumer<String> onSave;
	private final JComboBox<String> startFrom = new JComboBox<>(Text.lines("layout.from").toArray(new String[0]));
	private final Map<PadButton, JComboBox<PadAction>> board = new EnumMap<>(PadButton.class);
	private final Map<PadButton, JComboBox<PadAction>> foot = new EnumMap<>(PadButton.class);
	final JLabel status = left(new JLabel());
	/** The layout in the editor, including any air actions (kept, not edited here). */
	PadPreset editing = PadPreset.skate3();
	/** The saved Custom layout, for "Your saved layout"; null when there is none. */
	private PadPreset saved;
	/** True while the editor is being filled in, so the combos' events don't count as edits. */
	private boolean loading;

	/** @param onSave the layout code to save as the Custom preset (and select it) */
	ControllerLayoutView(Runnable onBack, Consumer<String> onSave)
	{
		this.onSave = onSave;
		subView(this, "Customise controller", "layout:back", onBack);
		JPanel body = column();
		body.add(wrapped(Text.get("layout.intro"), CONTENT_WIDTH));

		JPanel from = left(dark(new JPanel(new BorderLayout(4, 0))));
		from.setBorder(new EmptyBorder(6, 0, 4, 0));
		from.add(small("Start from"), BorderLayout.WEST);
		startFrom.setName("layout:startFrom");
		startFrom.setFocusable(false);
		from.add(startFrom, BorderLayout.CENTER);
		from.add(button("Load", "layout:load", e -> loadStart()), BorderLayout.EAST);
		body.add(stretch(from));

		for (PadButton b : PadButton.values())
			body.add(buttonRows(b));

		JPanel actions = left(dark(new JPanel(new GridLayout(0, 1, 0, 3))));
		actions.setBorder(new EmptyBorder(8, 0, 4, 0));
		actions.add(button("Save as my Custom preset", "layout:save", e -> save()));
		actions.add(button("Copy layout code", "layout:copy", e -> copy()));
		actions.add(button("Paste layout code...", "layout:paste", e -> paste()));
		body.add(stretch(actions));
		status.setFont(SMALL_FONT);
		body.add(status);
		add(body, BorderLayout.CENTER);
	}

	/** Shows the editor on {@code current} (the preset in use); {@code saved} is the stored Custom one, or null. */
	void showFor(PadPreset current, PadPreset saved)
	{
		this.saved = saved;
		load(current);
		setStatus(null, null);
	}

	/** Sets {@code button}'s action in {@code context} as the player would. */
	void choose(PadButton button, PadContext context, PadAction action)
	{
		(context == PadContext.FOOT ? foot : board).get(button).setSelectedItem(action);
	}

	/** Its layout code. */
	String code()
	{
		return LayoutCode.encode(editing);
	}

	void save()
	{
		onSave.accept(code());
		saved = editing;
		setStatus(Text.get("layout.saved"), OK_COLOR);
	}

	/**
	 * Reads a pasted code: null and the editor unchanged when it is refused (the reason shown), else the changes
	 * it would make (empty when none).
	 */
	List<String> preview(String code)
	{
		LayoutCode.Result r = LayoutCode.decode(code);
		if (!r.ok())
		{
			setStatus(r.error, ERROR_COLOR);
			return null;
		}
		return LayoutCode.changes(editing, r.preset);
	}

	/** Uses a pasted code (already previewed): into the editor and saved. */
	void apply(String code)
	{
		LayoutCode.Result r = LayoutCode.decode(code);
		if (r.ok())
		{
			load(r.preset);
			save();
		}
	}

	private void loadStart()
	{
		int i = startFrom.getSelectedIndex();
		if (i == 1 && saved == null)
		{
			setStatus("You have no saved layout yet.", ERROR_COLOR);
			return;
		}
		load(i == 0 ? PadPreset.skate3() : i == 1 ? saved : i == 3 ? PadPreset.thaw() : new PadPreset());
		setStatus("Loaded. Save to use it.", OK_COLOR);
	}

	private void load(PadPreset p)
	{
		loading = true;
		try
		{
			editing = p;
			for (PadButton b : PadButton.values())
			{
				board.get(b).setSelectedItem(p.action(b, PadContext.BOARD));
				foot.get(b).setSelectedItem(p.action(b, PadContext.FOOT));
			}
		}
		finally
		{
			loading = false;
		}
	}

	private void copy()
	{
		String c = code();
		try
		{
			Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(c), null);
			setStatus("Copied: " + c, OK_COLOR);
		}
		catch (IllegalStateException e)
		{
			setStatus(Text.get("layout.busy", c), ERROR_COLOR);
		}
	}

	private void paste()
	{
		String clip = "";
		try
		{
			Object data = Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
			if (data instanceof String && ((String) data).trim().startsWith(LayoutCode.PREFIX))
				clip = ((String) data).trim();
		}
		catch (IllegalStateException | UnsupportedFlavorException | IOException e)
		{
			// nothing usable on the clipboard: an empty box to paste into
		}
		Object typed = JOptionPane.showInputDialog(this, Text.get("layout.paste", LayoutCode.PREFIX + LayoutCode.VERSION),
			"Paste layout code", JOptionPane.PLAIN_MESSAGE, null, null, clip);
		if (!(typed instanceof String))
			return;
		String code = (String) typed;
		List<String> changes = preview(code);
		if (changes == null)
			return;
		if (changes.isEmpty())
		{
			setStatus(Text.get("layout.same"), OK_COLOR);
			return;
		}
		// at most 20 changes are listed
		StringBuilder msg = new StringBuilder("This layout changes:\n");
		changes.stream().limit(20).forEach(c -> msg.append("  ").append(c).append('\n'));
		if (changes.size() > 20)
			msg.append("... and ").append(changes.size() - 20).append(" more\n");
		if (JOptionPane.showConfirmDialog(this, msg + "\nUse it as your Custom preset?", "Paste layout code",
			JOptionPane.YES_NO_OPTION) == JOptionPane.YES_OPTION)
			apply(code);
	}

	private JPanel buttonRows(PadButton b)
	{
		JPanel p = new JPanel(new GridLayout(0, 1, 0, 1));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		p.setBorder(new EmptyBorder(3, 4, 3, 4));
		JLabel name = label(b.label + "  (" + b.keyName + ")", SMALL_FONT, Color.WHITE);
		name.setIcon(new ControllerGlyphIcon(16, PadWords.glyph(b)));
		name.setIconTextGap(6);
		p.add(name);
		p.add(choice(b, PadContext.BOARD, board));
		p.add(choice(b, PadContext.FOOT, foot));
		JPanel wrap = left(dark(new JPanel(new BorderLayout())));
		wrap.setBorder(new EmptyBorder(0, 0, 3, 0));
		wrap.add(p);
		return stretch(wrap);
	}

	private JPanel choice(PadButton b, PadContext context, Map<PadButton, JComboBox<PadAction>> into)
	{
		JComboBox<PadAction> box = new JComboBox<>(Arrays.stream(PadAction.values()).filter(a -> a.allowedIn(context))
			.toArray(PadAction[]::new));
		box.setName("layout:" + b.name() + ":" + context.name());
		box.setFocusable(false);
		box.setFont(SMALL_FONT);
		box.setRenderer(new DefaultListCellRenderer()
		{
			@Override
			public Component getListCellRendererComponent(JList<?> list, Object value, int index, boolean selected,
				boolean focus)
			{
				return super.getListCellRendererComponent(list, value == PadAction.NONE ? "-" : value, index, selected,
					focus);
			}
		});
		box.addActionListener(e ->
		{
			if (!loading && box.getSelectedItem() instanceof PadAction)
			{
				editing = editing.with(b, context, (PadAction) box.getSelectedItem());
				setStatus("Not saved yet.", null);
			}
		});
		into.put(b, box);
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		JLabel where = small(context == PadContext.FOOT ? "Foot" : "Board");
		where.setPreferredSize(new Dimension(34, where.getPreferredSize().height));
		row.add(where, BorderLayout.WEST);
		row.add(box, BorderLayout.CENTER);
		return row;
	}

	private void setStatus(String text, Color color)
	{
		status.setText(text == null ? "" : html(esc(text), CONTENT_WIDTH - 10));
		status.setForeground(color != null ? color : ColorScheme.LIGHT_GRAY_COLOR);
	}
}

package com.gielinorskate.ui;

import static com.gielinorskate.ui.Widgets.*;

import com.gielinorskate.Text;
import com.gielinorskate.controller.PadButton;
import com.gielinorskate.controller.PadTester;
import java.awt.*;
import java.awt.event.KeyEvent;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import java.util.Arrays;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import javax.swing.*;
import net.runelite.client.input.KeyListener;
import net.runelite.client.ui.ColorScheme;

/**
 * "Controller setup": where to get AntiMicroX, a button that saves the universal RuneSkate profile, the steps
 * (with Steam Input as another way), and "Test your pad": a drawn controller whose buttons light up as their pad keys
 * arrive and whose sticks show the arrows and the mouse. The test only watches, while this view is open (skating
 * or not): it registers a key listener with the client (which sees keys while the game canvas has focus and never
 * consumes them) and samples the cursor a few times a second. Swing only: every method runs on the EDT.
 */
class ControllerSetupView extends JPanel implements KeyListener
{
	/** Height of the drawn controller, and of its buttons, px. */
	private static final int H = 150;
	private static final int G = 18;
	/** A button's tick once it has been seen. */
	private static final Color SEEN_COLOR = new Color(0, 200, 50);

	private final PadTester tester = new PadTester();
	private final JComponent diagram = new JComponent()
	{
		@Override
		protected void paintComponent(Graphics g)
		{
			paintPad((Graphics2D) g.create());
		}
	};
	private final JLabel modeNote = left(new JLabel());
	/** Samples the cursor for the right stick, every 33 ms. */
	private final Timer sampler = new Timer(33, e -> sample());
	private final Supplier<SkatePanel.ControllerActions> actions;
	boolean listening;

	ControllerSetupView(Runnable onBack, Supplier<SkatePanel.ControllerActions> actions)
	{
		this.actions = actions;
		subView(this, "Controller setup", "setup:back", onBack);
		JPanel body = column();
		body.add(heading("1. Get AntiMicroX"));
		body.add(text(Text.get("setup.get")));
		body.add(stretch(button("Get AntiMicroX (opens GitHub)", "setup:antimicrox", e -> actions.get().openReleases())));
		body.add(heading("2. Load the RuneSkate profile"));
		body.add(text(Text.get("setup.load")));
		JButton save = stretch(button("Save RuneSkate profile...", "setup:saveProfile", null));
		save.addActionListener(e -> actions.get().saveProfile(save));
		body.add(save);
		body.add(heading("3. Turn it on"));
		body.add(text(Text.get("setup.on")));
		modeNote.setFont(SMALL_FONT);
		body.add(modeNote);
		body.add(heading("Steam Input instead"));
		body.add(text(steamText()));
		body.add(heading("Test your pad"));
		body.add(text(Text.get("setup.test")));
		Dimension d = new Dimension(CONTENT_WIDTH, H);
		diagram.setPreferredSize(d);
		diagram.setMinimumSize(d);
		diagram.setMaximumSize(d);
		body.add(left(diagram));
		add(body, BorderLayout.CENTER);
	}

	/** The Steam Input mapping: one key per button, no macros. */
	static String steamText()
	{
		return Text.get("setup.steam", Arrays.stream(PadButton.values()).map(b -> b.label + " " + b.keyName)
			.collect(Collectors.joining(", ")));
	}

	/** The view is shown: the pad test starts listening. {@code controllerMode}: whether the setting is on. */
	void opened(boolean controllerMode)
	{
		modeNote.setText(controllerMode ? "" : html(Text.get("setup.off"), CONTENT_WIDTH - 10));
		if (!listening)
		{
			listening = true;
			tester.reset();
			actions.get().watchKeys(this, true);
			sampler.start();
		}
	}

	/** The view is hidden (Back, or the plugin stops): the pad test stops listening. */
	void closed()
	{
		if (listening)
		{
			listening = false;
			actions.get().watchKeys(this, false);
			sampler.stop();
			tester.reset();
		}
	}

	/** The pad test's state (tests). */
	PadTester tester()
	{
		return tester;
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		SwingUtilities.invokeLater(() -> watch(e.getKeyCode(), true));
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		SwingUtilities.invokeLater(() -> watch(e.getKeyCode(), false));
	}

	/** A key pressed or released in the game window: shown on the pad test (the event itself is never consumed). */
	void watch(int keyCode, boolean down)
	{
		if (listening && tester.key(keyCode, down))
			diagram.repaint();
	}

	private void sample()
	{
		if (GraphicsEnvironment.isHeadless())
			return;
		Window window = SwingUtilities.getWindowAncestor(this);
		if (window != null && !window.isFocused())
			// another program has the keyboard: releases would not arrive here
			tester.reset();
		PointerInfo p = MouseInfo.getPointerInfo();
		if (p != null)
			tester.mouse(p.getLocation().x, p.getLocation().y, System.currentTimeMillis());
		diagram.repaint();
	}

	private static JComponent text(String s)
	{
		return wrapped(s, CONTENT_WIDTH);
	}

	/** A controller drawn from above: shoulders, the two sticks, the d-pad, Back / Start, the face buttons. */
	private void paintPad(Graphics2D g)
	{
		int w = CONTENT_WIDTH;
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(ColorScheme.DARKER_GRAY_COLOR);
			g.fill(new RoundRectangle2D.Float(2, 26, w - 4, H - 30, 40, 40));
			int cx = w / 2;
			padButton(g, PadButton.LT, 8, 2);
			padButton(g, PadButton.LB, 40, 2);
			padButton(g, PadButton.RB, w - 40 - glyphW(PadButton.RB), 2);
			padButton(g, PadButton.RT, w - 8 - glyphW(PadButton.RT), 2);
			padButton(g, PadButton.BACK, cx - 6 - glyphW(PadButton.BACK), 36);
			padButton(g, PadButton.START, cx + 6, 36);
			stick(g, 40, 64, tester.leftX(), tester.leftY(), PadButton.L3);
			stick(g, w - 70, 114, tester.rightX(), tester.rightY(), PadButton.R3);
			// d-pad: a cross of four round (66, 106)
			padButton(g, PadButton.DPAD_UP, 66, 106 - G);
			padButton(g, PadButton.DPAD_DOWN, 66, 106 + G);
			padButton(g, PadButton.DPAD_LEFT, 66 - G, 106);
			padButton(g, PadButton.DPAD_RIGHT, 66 + G, 106);
			// face buttons: a diamond round (w - 42, 60)
			padButton(g, PadButton.Y, w - 42, 60 - G);
			padButton(g, PadButton.A, w - 42, 60 + G);
			padButton(g, PadButton.X, w - 42 - G, 60);
			padButton(g, PadButton.B, w - 42 + G, 60);
		}
		finally
		{
			g.dispose();
		}
	}

	private static int glyphW(PadButton b)
	{
		return ControllerGlyphs.glyphWidth(PadWords.glyph(b), G);
	}

	/** One button: bright while held, dim otherwise, with a green dot once it has been seen. */
	private void padButton(Graphics2D g, PadButton b, int x, int y)
	{
		Composite old = g.getComposite();
		boolean down = tester.isDown(b);
		if (!down)
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.35f));
		ControllerGlyphs.paint(g, PadWords.glyph(b), x, y, G);
		g.setComposite(old);
		if (down)
		{
			g.setColor(Color.WHITE);
			g.setStroke(new BasicStroke(2f));
			g.draw(new Ellipse2D.Float(x - 2, y - 2, glyphW(b) + 4, G + 4));
		}
		else if (tester.wasSeen(b))
		{
			g.setColor(SEEN_COLOR);
			g.fill(new Ellipse2D.Float(x + glyphW(b) - 5, y + G - 5, 6, 6));
		}
	}

	/** A stick well with its knob pushed (x, y in -1..1); clicking it in (L3 / R3) lights the knob. */
	private void stick(Graphics2D g, int x, int y, float tx, float ty, PadButton click)
	{
		int r = 20;
		Ellipse2D well = new Ellipse2D.Float(x - r, y - r, 2 * r, 2 * r);
		g.setColor(new Color(48, 52, 60));
		g.fill(well);
		g.setColor(new Color(150, 156, 170));
		g.draw(well);
		int k = 9;
		float kx = x + tx * (r - k);
		float ky = y + ty * (r - k);
		boolean moved = tx != 0 || ty != 0;
		g.setColor(tester.isDown(click) ? Color.WHITE : moved ? new Color(120, 200, 255) : new Color(96, 102, 116));
		g.fill(new Ellipse2D.Float(kx - k, ky - k, 2 * k, 2 * k));
		g.setColor(Color.BLACK);
		g.setFont(SMALL_FONT);
		String label = click == PadButton.L3 ? "L" : "R";
		g.drawString(label, kx - g.getFontMetrics().stringWidth(label) / 2f, ky + 4);
		if (tester.wasSeen(click))
		{
			g.setColor(SEEN_COLOR);
			g.fill(new Ellipse2D.Float(x + r - 6, y + r - 6, 6, 6));
		}
	}
}

package com.gielinorskate.ui;

import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.util.*;
import javax.imageio.ImageIO;
import lombok.extern.slf4j.Slf4j;

/**
 * The board designs' thumbnails (designs/thumbs/ID.png, drawn by the bake at about in-game size), and their greyed "locked" look. Loaded once each. EDT only.
 */
@Slf4j
final class DesignThumbs
{
	private static final String DIR = "/com/gielinorskate/designs/thumbs/";
	/** A locked design's picture: grey, at this opacity. */
	private static final float LOCKED_ALPHA = 0.45f;

	private final Map<String, BufferedImage> plain = new HashMap<>();
	private final Map<String, BufferedImage> locked = new HashMap<>();

	/** The design's thumbnail, or a 1x1 transparent image if it is missing. */
	BufferedImage get(String id)
	{
		return plain.computeIfAbsent(id, DesignThumbs::load);
	}

	/** The design's thumbnail greyed out, for a locked design. */
	BufferedImage locked(String id)
	{
		return locked.computeIfAbsent(id, k -> grey(get(k)));
	}

	/** How many thumbnails are kept, plain and locked (tests). */
	int size()
	{
		return plain.size() + locked.size();
	}

	private static BufferedImage load(String id)
	{
		try (InputStream in = DesignThumbs.class.getResourceAsStream(DIR + id + ".png"))
		{
			BufferedImage img = in == null ? null : ImageIO.read(in);
			if (img != null)
				return img;
		}
		catch (IOException e)
		{
			log.debug("RuneSkate: no thumbnail for design {}", id, e);
		}
		return new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
	}

	/** {@code src} in grey (its luminance) at {@link #LOCKED_ALPHA} of its opacity. */
	static BufferedImage grey(BufferedImage src)
	{
		BufferedImage out = new BufferedImage(src.getWidth(), src.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < src.getHeight(); y++)
		{
			for (int x = 0; x < src.getWidth(); x++)
			{
				int argb = src.getRGB(x, y);
				// luminance from red, green and blue
				int l = ((argb >> 16 & 255) * 299 + (argb >> 8 & 255) * 587 + (argb & 255) * 114) / 1000;
				out.setRGB(x, y, Math.round((argb >>> 24) * LOCKED_ALPHA) << 24 | l << 16 | l << 8 | l);
			}
		}
		return out;
	}
}

package com.gielinorskate.ui;

import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import lombok.AllArgsConstructor;

/**
 * The geometry of a small picture of a mouse flick, in a unit box (x right, y down, both 0..1): a thin wind-up
 * stroke (pull down, or push up for a nollie) into a hook, then the thick flick with an arrowhead. A flick with
 * path turn bends: a little for a varial (60+ degrees), a lot for a 360 (150+), the thresholds of
 * {@link com.gielinorskate.tricks.TrickCatalog}. Pure; drawn by {@link GestureGlyphPainter}.
 */
@AllArgsConstructor
public final class GestureGlyph
{
	/** Length of the flick in box units. */
	private static final float FLICK_LENGTH = 0.42f;

	/** Wind-up stroke start and end (the hook, where the flick starts). */
	public final float[] windUpStart;
	public final float[] hook;
	/** Quadratic flick: start = {@link #hook}, control point (equal to the midpoint when straight), end. */
	public final float[] control;
	public final float[] flickEnd;
	/** Arrowhead: the two side tips (the point is {@link #flickEnd}). */
	public final float[] arrowLeft;
	public final float[] arrowRight;
	/** The flick bends (a varial or 360). */
	public final boolean curved;
	/** Shift held: drawn with a small Shift mark. */
	public final boolean shift;

	/** Unit vector of a flick direction in screen terms (y down); the directions go anticlockwise from up. */
	static float[] vector(Direction d)
	{
		double a = Math.toRadians(45 * d.ordinal());
		return new float[]{(float) -Math.sin(a), (float) -Math.cos(a)};
	}

	public static GestureGlyph of(Gesture g)
	{
		float[] dir = vector(g.direction);
		// the hook sits opposite the flick so the whole picture fits the box: a flick up starts low, and so on
		float hx = clamp(0.5f - dir[0] * FLICK_LENGTH / 2f);
		float hy = clamp(0.5f - dir[1] * FLICK_LENGTH / 2f);
		// wind-up (0.34 long): pulled down into the hook (it starts above it), or pushed up for a nollie (starts
		// below); drawn slanted from the side away from the flick, so it never hides under an up or down flick
		float side = dir[0] > 0.01f ? -1f : 1f;
		float[] windUpStart = {clamp(hx + side * 0.34f * 0.45f), clamp(hy + (g.nollie ? 0.34f : -0.34f))};
		float[] end = {clamp(hx + dir[0] * FLICK_LENGTH), clamp(hy + dir[1] * FLICK_LENGTH)};

		boolean curved = g.turnDegrees >= 60f;
		// the control point's sideways offset, as a fraction of the flick length: a 360, a varial, straight
		float bend = g.turnDegrees >= 150f ? 0.75f : curved ? 0.35f : 0f;
		// bend to the flick's left for a leftward flick, its right otherwise (perpendicular (dy, -dx) is left)
		float bendSign = dir[0] < -0.01f ? 1f : -1f;
		float len = (float) Math.hypot(end[0] - hx, end[1] - hy) * bend * bendSign;
		float[] control = {clamp((hx + end[0]) / 2f + dir[1] * len), clamp((hy + end[1]) / 2f - dir[0] * len)};

		// arrowhead along the curve's end tangent (control -> end), sides 0.14 long opening 28 degrees from it
		double tx = end[0] - control[0];
		double ty = end[1] - control[1];
		double back = Math.hypot(tx, ty) < 1e-6 ? Math.atan2(-dir[1], -dir[0]) : Math.atan2(-ty, -tx);
		double spread = Math.toRadians(28);
		return new GestureGlyph(windUpStart, new float[]{hx, hy}, control, end, tip(end, back + spread),
			tip(end, back - spread), curved, g.modified);
	}

	private static float[] tip(float[] end, double angle)
	{
		return new float[]{(float) (end[0] + 0.14 * Math.cos(angle)), (float) (end[1] + 0.14 * Math.sin(angle))};
	}

	private static float clamp(float v)
	{
		return Math.max(0.04f, Math.min(0.96f, v));
	}
}

package com.gielinorskate.ui;

import com.gielinorskate.tricks.Gesture;
import java.awt.*;
import java.awt.geom.*;

/**
 * Draws a {@link GestureGlyph} into a square: the side panel's trick list and the controls card's flick page share
 * it. Restores the stroke, colour and antialiasing it changes.
 */
public final class GestureGlyphPainter
{
	private GestureGlyphPainter()
	{
	}

	/**
	 * Paints the flick for {@code g} into the {@code size} x {@code size} square at (x, y).
	 *
	 * @param windUp colour of the thin wind-up stroke
	 * @param flick colour of the flick and its arrowhead (and the Shift mark)
	 */
	public static void paint(Graphics2D graphics, Gesture g, int x, int y, int size, Color windUp, Color flick)
	{
		GestureGlyph glyph = GestureGlyph.of(g);
		Stroke oldStroke = graphics.getStroke();
		Color oldColor = graphics.getColor();
		Object oldAa = graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		try
		{
			// the glyph's unit box onto the square
			AffineTransform box = new AffineTransform(size, 0, 0, size, x, y);
			float thin = Math.max(1f, size / 14f);

			graphics.setColor(windUp);
			graphics.setStroke(new BasicStroke(thin, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			graphics.draw(box.createTransformedShape(new Line2D.Float(glyph.windUpStart[0], glyph.windUpStart[1],
				glyph.hook[0], glyph.hook[1])));

			graphics.setColor(flick);
			graphics.setStroke(new BasicStroke(Math.max(1.5f, size / 8f), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			Path2D path = new Path2D.Float();
			path.moveTo(glyph.hook[0], glyph.hook[1]);
			path.quadTo(glyph.control[0], glyph.control[1], glyph.flickEnd[0], glyph.flickEnd[1]);
			// the arrowhead
			path.moveTo(glyph.arrowLeft[0], glyph.arrowLeft[1]);
			path.lineTo(glyph.flickEnd[0], glyph.flickEnd[1]);
			path.lineTo(glyph.arrowRight[0], glyph.arrowRight[1]);
			graphics.draw(box.createTransformedShape(path));

			if (glyph.shift)
			{
				// a small Shift-key arrow in the top-left corner, 0.28 of the square
				float[] xs = {0.5f, 1f, 0.72f, 0.72f, 0.28f, 0.28f, 0f};
				float[] ys = {0f, 0.55f, 0.55f, 1f, 1f, 0.55f, 0.55f};
				Path2D mark = new Path2D.Float();
				mark.moveTo(xs[0] * 0.28f, 0);
				for (int i = 1; i < xs.length; i++)
					mark.lineTo(xs[i] * 0.28f, ys[i] * 0.28f);
				mark.closePath();
				graphics.setStroke(new BasicStroke(thin));
				graphics.draw(box.createTransformedShape(mark));
			}
		}
		finally
		{
			graphics.setStroke(oldStroke);
			graphics.setColor(oldColor);
			graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
				oldAa == null ? RenderingHints.VALUE_ANTIALIAS_DEFAULT : oldAa);
		}
	}
}

package com.gielinorskate.ui;

import com.gielinorskate.Text;
import com.gielinorskate.controller.*;
import com.gielinorskate.ui.ControllerGlyphs.Glyph;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Words for the pad's buttons under a preset, as glyph tokens ("{A} or {X}"), so the controls card, the Trick Book
 * and the side panel name the buttons the player's layout actually uses. Pure.
 */
public final class PadWords
{
	private static final Pattern PLACEHOLDER = Pattern.compile("\\{@(\\w+)\\}");
	/** What each action does, by name; "NAME.foot" for its on-foot wording where that differs. */
	private static final Map<String, String> DOES = TrickGuide.table(Text.lines("pad.does"));
	/** The action placeholders but the modifier's, by name (see {@link #placeholder}). */
	private static final Map<String, String> PLACES = TrickGuide.table(Text.lines("pad.places"));

	private PadWords()
	{
	}

	/** The drawn glyph for a pad button: the same name, the d-pad's shortened ("DPAD_UP" is "DUP"). */
	public static Glyph glyph(PadButton b)
	{
		return Glyph.valueOf(b.name().replace("DPAD_", "D"));
	}

	/** A button's token: "{A}". */
	public static String token(PadButton b)
	{
		return ControllerGlyphs.token(glyph(b));
	}

	private static String tokens(List<PadButton> bs, String joiner)
	{
		return bs.stream().map(PadWords::token).collect(Collectors.joining(joiner));
	}

	/** The buttons doing {@code action} in {@code context}, joined by {@code joiner}; null when none does. */
	public static String buttons(PadPreset p, PadAction action, PadContext context, String joiner)
	{
		return or(p, action, context, joiner, null);
	}

	/** As {@link #buttons}, or {@code fallback} (the keyboard key, which still works) when no button does it. */
	public static String or(PadPreset p, PadAction action, PadContext context, String joiner, String fallback)
	{
		List<PadButton> bs = p.buttonsFor(action, context);
		return bs.isEmpty() ? fallback : tokens(bs, joiner);
	}

	/** The first button doing {@code action} in {@code context}, or {@code fallback}. */
	public static String first(PadPreset p, PadAction action, PadContext context, String fallback)
	{
		List<PadButton> bs = p.buttonsFor(action, context);
		return bs.isEmpty() ? fallback : token(bs.get(0));
	}

	/**
	 * Fills in the action placeholders of a text with the preset's buttons: {@code {@push}} (push, "or"),
	 * {@code {@pushFirst}}, {@code {@brake}}, {@code {@mod}} (the hard tricks modifier, "or"), {@code {@modSlash}},
	 * {@code {@grabL}}, {@code {@grabR}}, {@code {@grabs}} ("{LT} / {RT}"), {@code {@reset}}, {@code {@card}},
	 * {@code {@stop}}, {@code {@board}}, and on foot {@code {@sprint}}, {@code {@jump}}, {@code {@drop}}. An action
	 * no button does is named by its keyboard key ({@code boardKey} for the board key).
	 */
	public static String resolve(String text, PadPreset p, String boardKey)
	{
		Matcher m = PLACEHOLDER.matcher(text);
		StringBuffer out = new StringBuffer();
		while (m.find())
			m.appendReplacement(out, Matcher.quoteReplacement(placeholder(m.group(1), p, boardKey)));
		m.appendTail(out);
		return out.toString();
	}

	private static String placeholder(String name, PadPreset p, String boardKey)
	{
		if (name.startsWith("mod"))
			return modifier(p, name.equals("mod") ? " or " : "/");
		if (name.equals("grabs"))
			return placeholder("grabL", p, boardKey) + " / " + placeholder("grabR", p, boardKey);
		String row = PLACES.get(name);
		if (row == null)
			throw new IllegalArgumentException("no pad placeholder " + name);
		// action|context|joiner (none: the first button only)|the key, when no button does it (none: the board key)
		String[] f = row.split("\\|");
		PadAction a = PadAction.valueOf(f[0]);
		PadContext c = PadContext.valueOf(f[1]);
		String key = f.length > 3 ? f[3] : boardKey;
		return f[2].isEmpty() ? first(p, a, c, key) : or(p, a, c, f[2], key);
	}

	/**
	 * The hard tricks buttons: the modifier, and the spin assist, which is the modifier too ("{LB} or {RB}"), or
	 * Shift when the pad has neither.
	 */
	private static String modifier(PadPreset p, String joiner)
	{
		List<PadButton> bs = Arrays.stream(PadButton.values()).filter(b -> p.action(b, PadContext.BOARD)
			== PadAction.HARD_MODIFIER || p.action(b, PadContext.BOARD) == PadAction.SPIN_ASSIST)
			.collect(Collectors.toList());
		return bs.isEmpty() ? "Shift" : tokens(bs, joiner);
	}

	/** What an action does, for the pad layout lists (board wording; on-foot wording with {@code onFoot}). */
	static String describe(PadAction a, boolean onFoot)
	{
		String foot = onFoot ? DOES.get(a.name() + ".foot") : null;
		return foot != null ? foot : DOES.getOrDefault(a.name(), a.label);
	}

	/**
	 * The preset's buttons, each with what it does ("Push (tap or hold). On foot: sprint (hold)"), buttons that do
	 * exactly the same grouped ("{LB} {RB}"), in button order; unbound buttons are left out.
	 */
	public static Map<String, String> layout(PadPreset p)
	{
		Map<PadPreset.Binding, List<PadButton>> groups = new LinkedHashMap<>();
		for (PadButton b : PadButton.values())
		{
			PadPreset.Binding binding = p.binding(b);
			if (binding.board != PadAction.NONE || binding.foot != PadAction.NONE || binding.air != null)
				groups.computeIfAbsent(binding, k -> new ArrayList<>()).add(b);
		}
		Map<String, String> out = new LinkedHashMap<>();
		groups.forEach((binding, bs) -> out.put(tokens(bs, " "), describe(binding)));
		return out;
	}

	/** One binding in words. */
	static String describe(PadPreset.Binding b)
	{
		List<String> parts = new ArrayList<>();
		if (b.board != PadAction.NONE)
			parts.add(describe(b.board, false));
		if (b.air != null)
		{
			String air = describe(b.air, false);
			parts.add("In the air: " + (air.isEmpty() ? air : Character.toLowerCase(air.charAt(0)) + air.substring(1)));
		}
		if (b.foot != PadAction.NONE && b.foot != b.board)
			parts.add("On foot: " + describe(b.foot, true));
		return String.join(". ", parts);
	}
}

package com.gielinorskate.ui;

import lombok.AllArgsConstructor;
import lombok.EqualsAndHashCode;

/** What the side panel shows that comes from the client thread: skating or not, the last refusal, the stats. */
@AllArgsConstructor
@EqualsAndHashCode
public final class PanelState
{
	public final boolean active;
	/** Why skating could not start last time (cleared when it starts), or null. */
	public final String refusal;
	public final int total;
	public final int bestCombo;
	public final int tricksLanded;
}

package com.gielinorskate.ui;

import com.gielinorskate.progression.BoardLook;
import java.util.List;
import lombok.AllArgsConstructor;
import lombok.EqualsAndHashCode;

/**
 * What the side panel's "Skating" section shows: level, XP, the board designs in use and the session goals. Made on
 * the client thread, shown on the EDT.
 */
@AllArgsConstructor
@EqualsAndHashCode
public final class ProgressState
{
	public final int level;
	public final int xp;
	/** XP still needed for the next level; 0 at 99. */
	public final int xpToNext;
	/** Through the current level, 0..1. */
	public final float progress;
	/** The board designs in use. */
	public final BoardLook look;
	/** This session's goals (empty before the first session). */
	public final List<GoalView> goals;

	/** One session goal as the panel shows it. */
	@AllArgsConstructor
	@EqualsAndHashCode
	public static final class GoalView
	{
		public final String text;
		/** "3/5", or "Done". */
		public final String progress;
		public final boolean done;
	}
}

package com.gielinorskate.ui;

import static com.gielinorskate.ui.Widgets.*;

import com.gielinorskate.Text;
import com.gielinorskate.controller.PadPreset;
import com.gielinorskate.progression.*;
import com.gielinorskate.ui.ControllerGlyphs.Glyph;
import java.awt.*;
import java.awt.event.*;
import java.util.List;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.input.KeyListener;
import net.runelite.client.ui.*;
import net.runelite.client.ui.components.ProgressBar;
import net.runelite.client.util.LinkBrowser;

/**
 * The sidebar panel: a Start / Stop button (with the reason when skating can't start), the Open Trick Book button,
 * the basics, the Skating level with its XP bar, the session goals, the board designs (grip, deck and wheels
 * pickers), session stats and two display toggles. The Trick Book ({@link TrickBookView}, every move), Customise
 * controller ({@link ControllerLayoutView}) and Controller setup ({@link ControllerSetupView}, with the pad test)
 * each replace this content while open, with a Back button.
 * Swing only: every method runs on the EDT. It talks to the plugin through the callbacks it is given, and is fed
 * client-thread data through {@link #update}.
 */
public class SkatePanel extends PluginPanel
{
	/** The project's optional Ko-fi page, opened by the button at the top of the panel. */
	static final String SUPPORT_URL = "https://ko-fi.com/runeskate_project";
	/** The support button's text and outline. */
	private static final Color SUPPORT_COLOR = new Color(255, 200, 40);

	private final JButton startStop = button("Start skating", null, null);
	/** What the controller views ask of the plugin; nothing until it sets them. */
	private ControllerActions controllerActions = new ControllerActions()
	{
	};
	/** The panel's own content, swapped out for a sub-view (the Trick Book, ...) while one is open. */
	private final JPanel content = column();
	/** Back from a sub-view to the panel's content. */
	private final Runnable back = () -> show(content);
	final TrickBookView book = new TrickBookView(back);
	private final ControllerLayoutView layoutView = new ControllerLayoutView(back,
		code -> controllerActions.saveCustomLayout(code));
	private final ControllerSetupView setupView = new ControllerSetupView(back, () -> controllerActions);
	/** What is shown: {@link #content}, or a sub-view in its place. */
	JComponent view = content;
	/** The settings the basics and the Trick Book are worded for, with the controller preset in use. */
	private TrickBook.Settings settings = new TrickBook.Settings("Ctrl+K", "F", "Space", "right", false, true, false,
		false, "B", "Up", "Down", PadPreset.skate3(), "Skate 3");
	/** The saved Custom layout (null when none). */
	private PadPreset savedCustom;
	private final JLabel refusal = label(null, null, new Color(255, 150, 120));
	private final JLabel stats = greyLabel(null);
	private final JLabel skillLine = greyLabel(null);
	private final ProgressBar xpBar = new ProgressBar();
	/** The Board section: the preview strip, then a thumbnail grid per part. */
	private final JPanel boardSection = column();
	private final JLabel goalsHeading = heading("Daily goals");
	private final JLabel goalsText = greyLabel(null);
	private final Consumer<BoardDesign> onDesign;
	private final BoardDesigns designs;
	private final DesignThumbs thumbs = new DesignThumbs();
	/** The level and designs the Board section was last built for. */
	private int designLevel = -1;
	private BoardLook lookInUse;
	private final JCheckBox grindEdges = new JCheckBox("Show grindable edges");
	private final JCheckBox controlsCard = new JCheckBox("Show controls card");
	private final JLabel basics = greyLabel(null);
	/** Controller mode's basics: one row per pad control, its buttons drawn in front. */
	private final JPanel padBasics = column();

	/**
	 * @param onStartStop runs when Start / Stop is pressed (the plugin hops to the client thread)
	 * @param setOption sets a boolean setting by key ("showGrindEdges", "showControlsCard")
	 * @param onDesign runs when an unlocked design is picked (the plugin hops to the client thread)
	 */
	public SkatePanel(Runnable onStartStop, BiConsumer<String, Boolean> setOption, Consumer<BoardDesign> onDesign)
	{
		this(onStartStop, setOption, onDesign, BoardDesigns.bundled());
	}

	/** As above, over {@code designs} (tests). */
	SkatePanel(Runnable onStartStop, BiConsumer<String, Boolean> setOption, Consumer<BoardDesign> onDesign,
		BoardDesigns designs)
	{
		this.onDesign = onDesign;
		this.designs = designs;
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(8, 8, 8, 8));
		dark(this);

		// an optional support link at the very top, picked out in yellow; nothing in the plugin depends on it
		content.add(supportRow());
		content.add(label("RuneSkate", FontManager.getRunescapeBoldFont(), Color.WHITE));
		startStop.addActionListener(e -> onStartStop.run());
		stretch(startStop, 32);
		content.add(left(startStop));
		content.add(refusal);
		JButton openBook = button("Open Trick Book", "trickBook:open", e -> openTrickBook());
		openBook.setToolTipText(Text.get("panel.bookTip"));
		content.add(row(openBook, 6, 34));
		JPanel pad = left(dark(new JPanel(new GridLayout(1, 2, 4, 0))));
		pad.setBorder(new EmptyBorder(4, 0, 0, 0));
		pad.add(padButton("Customise controller", "controller:customise", Text.get("panel.layoutTip"),
			e -> openLayout()));
		pad.add(padButton("Controller setup", "controller:setup", Text.get("panel.setupTip"), e -> openSetup()));
		stretch(pad, 30);
		content.add(pad);

		// the board designer sits near the top, where players look for it
		content.add(heading("Board"));
		content.add(boardSection);

		content.add(heading("The basics"));
		content.add(basics);
		content.add(padBasics);

		content.add(heading("Skating"));
		content.add(skillLine);
		stretch(xpBar, 16);
		xpBar.setPreferredSize(new Dimension(TEXT_WIDTH, 16));
		xpBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		// the green of the game's skill progress bars
		xpBar.setForeground(new Color(0, 160, 50));
		content.add(left(xpBar));

		content.add(goalsHeading);
		content.add(goalsText);

		content.add(heading("This session"));
		content.add(stats);

		content.add(heading("Show"));
		for (JCheckBox box : new JCheckBox[]{grindEdges, controlsCard})
		{
			box.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			box.setFocusable(false);
			content.add(left(dark(box)));
		}
		grindEdges.addActionListener(e -> setOption.accept("showGrindEdges", grindEdges.isSelected()));
		controlsCard.addActionListener(e -> setOption.accept("showControlsCard", controlsCard.isSelected()));

		add(content, BorderLayout.NORTH);
		update(new PanelState(false, null, 0, 0, 0));
		updateProgress(new ProgressState(1, 0, 83, 0f, BoardLook.defaults(designs), List.of()));
		rebuild();
	}

	/** What the controller sub-views ask of the plugin (they run on the EDT). */
	public interface ControllerActions
	{
		/** Save {@code code} as the Custom layout and select the Custom preset. */
		default void saveCustomLayout(String code)
		{
		}

		/** Open the AntiMicroX releases page. */
		default void openReleases()
		{
		}

		/** Save the RuneSkate profile where the player picks. */
		default void saveProfile(Component from)
		{
		}

		/** Start ({@code on}) or stop sending the game window's key events to {@code l}. */
		default void watchKeys(KeyListener l, boolean on)
		{
		}
	}

	public void setControllerActions(ControllerActions actions)
	{
		controllerActions = actions;
	}

	/** Shows {@code v} in place of what is shown now: the panel's content or a sub-view. */
	private void show(JComponent v)
	{
		if (view != v)
		{
			// the pad test stops listening when its view goes
			setupView.closed();
			remove(view);
			add(v, BorderLayout.NORTH);
			view = v;
		}
		revalidate();
		repaint();
		v.scrollRectToVisible(new Rectangle(0, 0, 1, 1));
	}

	/** Shows the Trick Book in place of the panel's content, worded for the current settings. */
	void openTrickBook()
	{
		book.showFor(settings);
		show(book);
	}

	/** Customise controller, starting from the preset in use. */
	void openLayout()
	{
		layoutView.showFor(settings.preset, savedCustom);
		show(layoutView);
	}

	/** Controller setup; its pad test listens while it is open. */
	void openSetup()
	{
		show(setupView);
		setupView.opened(settings.controller);
	}

	ControllerLayoutView layoutView()
	{
		return layoutView;
	}

	ControllerSetupView setupView()
	{
		return setupView;
	}

	/** The plugin stops: the pad test stops listening. */
	public void dispose()
	{
		setupView.closed();
	}

	/**
	 * The controller preset in use and its name ("Skate 3", "Custom"), and the saved Custom layout (null when none):
	 * the basics, the Trick Book and Customise controller name its buttons.
	 */
	public void setController(PadPreset preset, String presetName, PadPreset savedCustom)
	{
		this.savedCustom = savedCustom;
		apply(settings.withPreset(preset).withPresetName(presetName));
	}

	/**
	 * The other key names the Trick Book is worded with.
	 *
	 * @param flickButton "right", "left" or "middle"
	 * @param brakeKey the extra brake key's name ("Not set" when none)
	 */
	public void setKeyNames(String flickButton, String brakeKey, String leanForwardKey, String leanBackKey)
	{
		apply(settings.withFlickButton(flickButton).withBrakeKey(brakeKey).withLeanForwardKey(leanForwardKey)
			.withLeanBackKey(leanBackKey));
	}

	/**
	 * The current settings the panel's wording and toggles depend on. {@code controller}: controller mode names the
	 * pad's buttons, drawn; {@code boardKey}: the board on/off key's name, for the on-foot basics.
	 */
	public void setSettings(String toggleKey, String manualKey, boolean mouseTricks, boolean keyboardTricks,
		boolean mirror, boolean showGrindEdges, boolean showControlsCard, boolean controller, String boardKey)
	{
		grindEdges.setSelected(showGrindEdges);
		controlsCard.setSelected(showControlsCard);
		apply(settings.withToggleKey(toggleKey).withBoardKey(boardKey).withManualKey(manualKey).withMirror(mirror)
			.withMouseTricks(mouseTricks).withKeyboardTricks(keyboardTricks).withController(controller));
	}

	/** Rewords the basics (and the Trick Book while it is open) when the settings change. */
	private void apply(TrickBook.Settings s)
	{
		if (!s.equals(settings))
		{
			settings = s;
			rebuild();
		}
	}

	/** The Ko-fi button in its row: yellow text and outline, a dark yellow fill under the mouse. */
	private static JPanel supportRow()
	{
		JButton support = button("Support RuneSkate on Ko-fi", "support:kofi", e -> LinkBrowser.browse(SUPPORT_URL));
		support.setToolTipText(SUPPORT_URL);
		support.setForeground(SUPPORT_COLOR);
		support.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		support.setContentAreaFilled(false);
		support.setOpaque(true);
		support.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(SUPPORT_COLOR, 2),
			new EmptyBorder(4, 6, 4, 6)));
		support.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				support.setBackground(new Color(90, 72, 20));
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				support.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			}
		});
		JPanel row = row(support, 0, 38);
		row.setBorder(new EmptyBorder(0, 0, 8, 0));
		return row;
	}

	/** {@code c} filling a full-width row {@code height} px tall, {@code gap} px under what is above. */
	private static JPanel row(JComponent c, int gap, int height)
	{
		JPanel row = left(dark(new JPanel(new BorderLayout())));
		row.setBorder(new EmptyBorder(gap, 0, 0, 0));
		row.add(c);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return row;
	}

	private static JButton padButton(String text, String name, String tip, ActionListener l)
	{
		JButton b = button(text, name, l);
		b.setFont(SMALL_FONT);
		b.setMargin(new Insets(2, 2, 2, 2));
		b.setToolTipText(tip);
		return b;
	}

	/** Client-thread data, handed over with SwingUtilities.invokeLater. */
	public void update(PanelState s)
	{
		boolean refused = s.refusal != null && !s.active;
		startStop.setText(s.active ? "Stop skating" : "Start skating");
		refusal.setText(refused ? html(esc(s.refusal)) : "");
		refusal.setVisible(refused);
		stats.setText(html(String.format(Text.get("panel.stats"), s.total, s.bestCombo, s.tricksLanded)));
	}

	/** The account's Skating level and XP, handed over with SwingUtilities.invokeLater. */
	public void updateProgress(ProgressState s)
	{
		boolean maxed = s.xpToNext <= 0;
		skillLine.setText(html(Text.get("panel.level" + (maxed ? ".max" : ""), s.level, String.format("%,d", s.xp),
			String.format("%,d", s.xpToNext), s.level + 1)));
		xpBar.setMaximumValue(1000);
		xpBar.setValue(Math.round(Math.max(0f, Math.min(1f, s.progress)) * 1000));
		xpBar.setLeftLabel("Lvl " + s.level);
		xpBar.setRightLabel(maxed ? "" : "Lvl " + (s.level + 1));
		xpBar.setCenterLabel(Math.round(s.progress * 100) + "%");
		goalsText.setText(html(goalsHtml(s.goals)));
		if (s.level != designLevel || !s.look.equals(lookInUse))
		{
			designLevel = s.level;
			lookInUse = s.look;
			rebuildBoard();
		}
	}

	/** Each goal on its own line: done ones ticked in green, the rest with their progress. */
	static String goalsHtml(List<ProgressState.GoalView> goals)
	{
		if (goals.isEmpty())
			return Text.get("panel.noGoals", String.format("%,d", SessionGoals.BONUS_XP));
		return goals.stream().map(g -> g.done ? "<font color='#00c832'>&#10004; " + esc(g.text) + "</font>"
			: "&#9744; " + esc(g.text) + " <font color='#c8a85a'>" + esc(g.progress) + "</font>")
			.collect(Collectors.joining("<br>"));
	}

	/** Shows or hides the session goals ("Show session goals"). */
	public void setShowGoals(boolean show)
	{
		goalsHeading.setVisible(show);
		goalsText.setVisible(show);
	}

	/**
	 * The Board section: a strip with the designs in use, then for grip, deck and wheels a grid of thumbnails with
	 * names. A pick applies at once; locked designs are greyed with their level; the one in use is highlighted.
	 */
	private void rebuildBoard()
	{
		boardSection.removeAll();
		JPanel strip = left(dark(new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0))));
		strip.setName("board:preview");
		for (DesignPart part : DesignPart.values())
		{
			BoardDesign d = lookInUse.get(part);
			JLabel l = new JLabel(new ImageIcon(thumbs.get(d.id)));
			l.setToolTipText(part.label + ": " + d.name);
			strip.add(l);
		}
		stretch(strip, 44);
		boardSection.add(strip);
		JLabel riding = left(new JLabel(html("<font color='#c8c8c8'>" + esc(lookInUse.grip.name) + " grip, "
			+ esc(lookInUse.deck.name) + " deck, " + esc(lookInUse.wheels.name) + " wheels</font>")));
		riding.setFont(SMALL_FONT);
		riding.setBorder(new EmptyBorder(2, 0, 2, 0));
		boardSection.add(riding);
		for (DesignPart part : DesignPart.values())
		{
			JLabel sub = small(part.label);
			sub.setBorder(new EmptyBorder(6, 0, 2, 0));
			boardSection.add(sub);
			JPanel grid = left(dark(new JPanel(new GridLayout(0, part == DesignPart.WHEELS ? 3 : 2, 3, 3))));
			for (BoardDesign d : designs.of(part))
				grid.add(designButton(d));
			boardSection.add(grid);
		}
		boardSection.revalidate();
		boardSection.repaint();
	}

	/** One design's cell: its picture over its name, greyed with "Level N" while locked, highlighted when in use. */
	private JButton designButton(BoardDesign d)
	{
		boolean locked = !d.isUnlocked(designLevel);
		boolean inUse = d.id.equals(lookInUse.get(d.part).id);
		String color = inUse ? "#ff981f" : locked ? "#8a8a8a" : "#dcdcdc";
		JButton b = tile("<font color='" + color + "'>" + esc(d.name) + "</font>"
			+ (locked ? "<br><font color='#8a8a8a'>Level " + d.unlock + "</font>" : ""), "design:" + d.id,
			BorderFactory.createLineBorder(inUse ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR, 1),
			e -> onDesign.accept(d));
		b.setIcon(new ImageIcon(locked ? thumbs.locked(d.id) : thumbs.get(d.id)));
		b.setVerticalTextPosition(SwingConstants.BOTTOM);
		b.setHorizontalTextPosition(SwingConstants.CENTER);
		b.setIconTextGap(1);
		// disabled buttons draw their icon greyed by the look and feel: the locked picture is greyed already
		b.setDisabledIcon(b.getIcon());
		b.setEnabled(!locked);
		b.setSelected(inUse);
		// the design's name goes in last: nothing is filled in after it
		b.setToolTipText(Text.get("panel.design." + (locked ? "locked" : inUse ? "inUse" : "pick"), d.part.key, d.unlock,
			d.name));
		if (inUse)
			b.setBackground(ColorScheme.DARKER_GRAY_HOVER_COLOR);
		return b;
	}

	/** A Board section cell: centred small text in {@code edge}. */
	private static JButton tile(String text, String name, javax.swing.border.Border edge, ActionListener l)
	{
		JButton b = button("<html><center>" + text + "</center></html>", name, l);
		b.setFont(SMALL_FONT);
		b.setMargin(new Insets(2, 1, 2, 1));
		b.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		b.setBorder(BorderFactory.createCompoundBorder(edge, new EmptyBorder(2, 1, 2, 1)));
		return b;
	}

	private void rebuild()
	{
		TrickBook.Settings s = settings;
		startStop.setToolTipText(Text.get("panel.startTip", s.toggleKey));
		basics.setText(html(Text.get("panel.basics." + (s.mouseTricks ? "mouse" : "keys"), esc(s.toggleKey),
			esc(s.boardKey))));
		basics.setVisible(!s.controller);
		padBasics.setVisible(s.controller);
		padBasics.removeAll();
		if (s.controller)
		{
			padBasics.add(greyLabel(html(esc(Text.get("panel.preset", s.toggleKey, s.presetName)))));
			List<String> sticks = Text.lines("panel.sticks" + (s.mouseTricks ? ".mouse" : ""));
			padRow("{LS}", sticks.get(0));
			padRow("{RS}", sticks.get(1));
			PadWords.layout(s.preset).forEach(this::padRow);
		}
		padBasics.revalidate();
		if (view == book)
			book.showFor(s);
	}

	/** One controller basics row: the buttons (glyph tokens), then what they do. */
	private void padRow(String buttons, String does)
	{
		JLabel l = greyLabel(html(esc(ControllerGlyphs.plain(does)), TEXT_WIDTH - 50));
		l.setIcon(new ControllerGlyphIcon(18, glyphsOf(buttons)));
		l.setIconTextGap(6);
		l.setBorder(new EmptyBorder(1, 0, 1, 0));
		padBasics.add(l);
	}

	/** The distinct glyphs in a line, in order, at most two. */
	static Glyph[] glyphsOf(String text)
	{
		return ControllerGlyphs.split(text).stream().filter(p -> p instanceof Glyph).distinct().limit(2)
			.toArray(Glyph[]::new);
	}
}

package com.gielinorskate.ui;

import static com.gielinorskate.ui.ControllerGlyphs.plain;

import com.gielinorskate.Text;
import com.gielinorskate.camera.BoardOrbit;
import com.gielinorskate.controller.PadPreset;
import com.gielinorskate.input.ButtonTricks;
import com.gielinorskate.input.KeyboardTricks;
import com.gielinorskate.progression.*;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.*;
import com.gielinorskate.tricks.Gesture.Direction;
import java.util.*;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import lombok.*;

/**
 * The Trick Book's content: every move, grouped into sections, worded for the player's settings (keys, flick
 * button, mirrored flicks, keyboard tricks, controller mode). Built from the sources of truth, so it cannot drift:
 * the {@link Trick} catalogue through {@link TrickGuide} (flicks, "how" lines, points), {@link KeyboardTricks}
 * (keys), {@link Grabs} (aims and tweaks), {@link SpinNames}, the scoring and progression constants and the
 * board designs' level ladder (designs.json). Pure.
 */
public final class TrickBook
{
	/** The settings the wording depends on. A value. */
	@AllArgsConstructor
	@EqualsAndHashCode
	@With
	public static final class Settings
	{
		final String toggleKey;
		final String boardKey;
		final String manualKey;
		/** "right", "left" or "middle". */
		final String flickButton;
		final boolean mirror;
		final boolean mouseTricks;
		final boolean keyboardTricks;
		final boolean controller;
		/** The extra brake key's name, or null / "Not set" when there is none. */
		final String brakeKey;
		final String leanForwardKey;
		final String leanBackKey;
		/** The controller layout whose buttons the book names (and lists in its Controller section). */
		final PadPreset preset;
		/** The preset's name ("Skate 3", "Custom"). */
		final String presetName;
	}

	/** One move or fact: a name, what to do, and optionally its points, flick picture, key and pad buttons. */
	@AllArgsConstructor
	public static final class Entry
	{
		/** The catalogue trick this entry is, or null (a control, a spin, a rule). */
		public final Trick trick;
		public final String name;
		/** What to do, plain text. */
		public final String detail;
		/** "300", "200/s", "+150"; null when it scores nothing by itself. */
		public final String points;
		/** The flick to draw (already mirrored), or null. */
		public final Gesture gesture;
		/** Its keyboard-mode key ("1", "Shift+2"), or null. */
		public final String key;
		/** The pad buttons as glyph tokens ("{LT}"), to draw, or null. */
		public final String pad;
	}

	/** A titled group of entries, with an optional intro line and an optional table (first row: headers). */
	@AllArgsConstructor
	public static final class Section
	{
		public final String title;
		/** A line under the title, or null. */
		public final String intro;
		public final List<Entry> entries;
		/** Rows of cells, the first the headers; empty when the section has no table. */
		public final List<List<String>> table;

		Section(String title, String intro, List<Entry> entries)
		{
			this(title, intro, entries, List.of());
		}
	}

	private TrickBook()
	{
	}

	/** The whole book for {@code s}, in reading order. */
	public static List<Section> build(Settings s)
	{
		// the wording is bundled under book.*
		boolean bt = buttons(s);
		return List.of(basics(s),
			new Section("Flip tricks", Text.get("book.flips." + (bt ? "bt" : s.controller ? "pad" : s.mouseTricks
				? "mouse" : "keys"), pad(s, "{@flip}"), s.flickButton), group(s, TrickGuide.Group.FLIPS)),
			new Section("Hard flips (Shift)", Text.get("book.shift", s.controller ? pad(s, "{@mod}") : "Shift"),
				group(s, TrickGuide.Group.SHIFT)),
			spins(s),
			grabs(s),
			new Section("Manuals", Text.get("book.manuals"), tricks(s, t -> t.kind == TrickKind.MANUAL)),
			new Section("Grinds", Text.get("book.grinds" + (bt ? ".bt" : ""), pad(s, "{@grind}")),
				tricks(s, t -> t.kind == TrickKind.GRIND)),
			offTheBoard(s),
			controller(s),
			scoring());
	}

	/** Controller mode with a button-trick layout (Tony Hawk's American Wasteland): tricks on buttons. */
	private static boolean buttons(Settings s)
	{
		return s.controller && s.preset.buttonTricks();
	}

	private static Entry control(String name, String detail)
	{
		return new Entry(null, name, detail, null, null, null, null);
	}

	/**
	 * A control, worded with keys, or with pad buttons in controller mode ({@code pad}'s action placeholders filled
	 * in from the preset, see {@link PadWords#resolve}).
	 */
	private static Entry control(Settings s, String name, String keys, String pad)
	{
		if (s.controller)
		{
			String text = PadWords.resolve(pad, s.preset, s.boardKey);
			return new Entry(null, name, plain(text), null, null, null, text);
		}
		return control(name, keys);
	}

	/**
	 * The controls in a bundled list, one a line: "name|keys|pad", with the button tricks' pad wording after a
	 * fourth "|"; "name|detail" for one worded the same everywhere.
	 */
	private static List<Entry> controls(Settings s, String list)
	{
		List<Entry> e = new ArrayList<>();
		for (String line : list.split("\n"))
		{
			String[] f = line.split("\\|");
			e.add(f.length < 3 ? control(f[0], f[1]) : control(s, f[0], f[1], f[buttons(s) && f.length > 3 ? 3 : 2]));
		}
		return e;
	}

	/** The preset's buttons in a pad text, spelt out. */
	private static String pad(Settings s, String text)
	{
		return plain(PadWords.resolve(text, s.preset, s.boardKey));
	}

	/** "Up arrow" for the arrow keys, the key's own name otherwise. */
	static String keyName(String key)
	{
		return key.matches("Up|Down|Left|Right") ? key + " arrow" : key;
	}

	private static Section basics(Settings s)
	{
		String brake = s.brakeKey == null || s.brakeKey.trim().isEmpty() || "Not set".equalsIgnoreCase(s.brakeKey.trim())
			? "" : ", or " + s.brakeKey;
		List<Entry> e = controls(s, Text.get("book.basics", s.toggleKey, brake));
		e.add(trick(s, Trick.OLLIE));
		e.add(trick(s, Trick.NOLLIE));
		e.addAll(controls(s, Text.get("book.basics2")));
		return new Section("Basics", null, e);
	}

	/** A catalogue trick's entry, worded for the settings. */
	static Entry trick(Settings s, Trick t)
	{
		TrickGuide.Entry g = TrickGuide.entry(t);
		// with button tricks the flick pictures would mislead (the right stick turns the camera)
		Gesture gesture = g.gesture == null || !s.mouseTricks || buttons(s) ? null
			: s.mirror ? KeyboardTricks.mirror(g.gesture) : g.gesture;
		String key = s.keyboardTricks ? g.key : null;
		String pad = null;
		String detail = g.how;
		if (s.controller)
		{
			String how = TrickGuide.controllerHow(t, g.gesture, s.preset);
			detail = plain(how);
			pad = ControllerGlyphs.hasGlyphs(how) ? how : null;
		}
		if (!s.mouseTricks && !buttons(s) && (g.gesture != null || key != null))
		{
			// a flick trick (or a double) without flicks: its key is the way to do it
			detail = key != null ? "Press " + key : "";
			pad = null;
		}
		if (t.kind == TrickKind.MANUAL)
			detail = detail.replace("the wheelie key", s.manualKey);
		if (gesture != null && s.mirror)
			detail = detail.replace(ButtonTricks.directionName(g.gesture.direction),
				ButtonTricks.directionName(gesture.direction));
		return new Entry(t, t.displayName, detail, g.points(), gesture, key, pad);
	}

	/** The entries of the catalogue tricks {@code which} picks, in catalogue order. */
	private static List<Entry> tricks(Settings s, Predicate<Trick> which)
	{
		return Arrays.stream(Trick.values()).filter(which).map(t -> trick(s, t)).collect(Collectors.toList());
	}

	private static List<Entry> group(Settings s, TrickGuide.Group group)
	{
		return tricks(s, t -> TrickGuide.entry(t).group == group);
	}

	private static Section spins(Settings s)
	{
		String how = Text.get("book.spins." + (buttons(s) ? "bt" : s.controller ? "pad" : "keys"), pad(s, "{@mod}"));
		List<Entry> e = new ArrayList<>();
		for (int n = 1; n <= 4; n++)
			e.add(new Entry(null, SpinNames.label(n) + " / " + SpinNames.label(-n), how, "+" + SpinNames.bonus(n),
				null, null, null));
		e.addAll(tricks(s, t -> t.bodyFlipTurns != 0f));
		return new Section("Spins & body flips", Text.get("book.spins"), e);
	}

	private static Section grabs(Settings s)
	{
		List<Entry> e = tricks(s, t -> t.kind == TrickKind.GRAB);
		List<List<String>> table = new ArrayList<>();
		if (buttons(s))
		{
			// with the grab button and a direction
			String b = pad(s, "{@grabBtn}");
			table.add(List.of("Direction", b + " grab"));
			table.add(List.of("None", ButtonTricks.grab(null).displayName));
			for (Direction d : TrickGuide.BUTTON_DIRECTIONS)
			{
				String name = ButtonTricks.directionName(d);
				table.add(List.of(Character.toUpperCase(name.charAt(0)) + name.substring(1),
					ButtonTricks.grab(d).displayName));
			}
			return new Section("Grabs", Text.get("book.grabs.bt", b, Grabs.TWEAK_SECONDS, pad(s, "{@mod}")), e, table);
		}
		String q = s.controller ? pad(s, "{@grabL}") : "Q";
		String e2 = s.controller ? pad(s, "{@grabR}") : "E";
		String toe = s.mirror ? "Left" : "Right";
		String heel = s.mirror ? "Right" : "Left";
		table.add(List.of(s.controller ? "Aim (stick)" : "Aim (mouse)", q + " (left)", e2 + " (right)"));
		Object[][] aims = {{"None", null}, {"Up (nose)", Grabs.Aim.NOSE}, {"Down (tail)", Grabs.Aim.TAIL},
			{toe + " (toe)", Grabs.Aim.TOE}, {heel + " (heel)", Grabs.Aim.HEEL}};
		for (Object[] a : aims)
		{
			Grabs.Aim aim = (Grabs.Aim) a[1];
			table.add(List.of((String) a[0], Grabs.pick(true, aim).displayName, Grabs.pick(false, aim).displayName));
		}
		return new Section("Grabs", Text.get("book.grabs." + (s.controller ? "pad" : "mouse"), q, e2,
			Grabs.TWEAK_SECONDS, pad(s, "{@mod}"), keyName(s.leanForwardKey), keyName(s.leanBackKey)), e, table);
	}

	private static Section offTheBoard(Settings s)
	{
		List<Entry> e = controls(s, Text.get("book.off", s.boardKey));
		e.add(buttons(s) ? control(s, "Turn the camera", "Middle mouse drag", "{RS}")
			: control("Turn the camera", "Middle mouse drag"));
		return new Section("Off the board", "No tricks or points on foot.", e);
	}

	/**
	 * The pad layout of the controller preset (universal AntiMicroX profile), shown whether or not controller mode
	 * is on: the sticks, then each bound button with what it does.
	 */
	private static Section controller(Settings s)
	{
		List<Entry> e = new ArrayList<>();
		String[] sticks = Text.get("book.sticks" + (buttons(s) ? ".bt" : ""), BoardOrbit.IDLE_SECONDS).split("\n");
		e.add(pad("{LS}", sticks[0]));
		e.add(pad("{RS}", sticks[1]));
		PadWords.layout(s.preset).forEach((buttons, does) -> e.add(pad(buttons, does)));
		return new Section("Controller", Text.get("book.controller", s.presetName), e);
	}

	/** A pad layout line: its buttons named, then what they do. */
	private static Entry pad(String tokens, String detail)
	{
		String names = ControllerGlyphs.split(tokens).stream().filter(p -> p instanceof ControllerGlyphs.Glyph)
			.map(p -> ((ControllerGlyphs.Glyph) p).spoken).collect(Collectors.joining(" / "));
		return new Entry(null, names, detail, null, null, null, tokens);
	}

	private static String percent(float fraction)
	{
		return Math.round(fraction * 100f) + "%";
	}

	private static Section scoring()
	{
		// the design ladder goes in last: nothing is filled in after it
		return new Section("Scoring & levels", null, controls(null, Text.get("book.scoring",
			percent(1f - ComboScorer.DECAY_PER_REPEAT), percent(ComboScorer.DECAY_FLOOR),
			percent(ComboScorer.FIRST_LANDING_BONUS), Math.round(ComboScorer.LONG_COMBO_SECONDS),
			percent(ComboScorer.CLEAN_BONUS), SkateLevels.COMBO_VALUE_PER_XP, SkateLevels.MAX_LEVEL,
			SessionGoals.GOALS_PER_SESSION, String.format("%,d", SessionGoals.BONUS_XP),
			designLadder(BoardDesigns.bundled()))));
	}

	/** "Level 1: RuneSkate, Classic black, ... Level 99: Torva": each design name once, at its level, in order. */
	static String designLadder(BoardDesigns designs)
	{
		Map<Integer, Set<String>> ladder = new TreeMap<>();
		for (BoardDesign d : designs.all())
			ladder.computeIfAbsent(d.unlock, k -> new LinkedHashSet<>()).add(d.name);
		return ladder.entrySet().stream().map(rung -> "Level " + rung.getKey() + ": " + String.join(", ", rung.getValue()))
			.collect(Collectors.joining(". "));
	}
}

package com.gielinorskate.ui;

import static com.gielinorskate.ui.Widgets.*;

import java.awt.*;
import java.util.List;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;

/**
 * The Trick Book: {@link TrickBook}'s sections as plain Swing components (labels, and non-editable wrapped text
 * areas for the longer lines; no HTML), shown in place of the side panel's content with a Back button. Built when
 * opened, and again only when the settings it is worded for change. Swing only: every method runs on the EDT.
 */
class TrickBookView extends JPanel
{
	private static final Color POINTS_COLOR = new Color(200, 168, 90);
	/** A flick picture's size, px. */
	private static final int GLYPH_SIZE = 26;
	/** An entry row's inner padding each side. */
	private static final int ROW_PAD = 4;
	private static final int ICON_GAP = 6;

	private final JPanel body = column();
	/** The settings the body was last built for; null before the first build. */
	private TrickBook.Settings builtFor;

	TrickBookView(Runnable onBack)
	{
		subView(this, "Trick Book", "trickBook:back", onBack);
		add(body, BorderLayout.CENTER);
	}

	/** Shows the book worded for {@code s}, building it if it was built for other settings (or never). */
	void showFor(TrickBook.Settings s)
	{
		if (!s.equals(builtFor))
		{
			builtFor = s;
			body.removeAll();
			for (TrickBook.Section section : TrickBook.build(s))
			{
				body.add(heading(section.title));
				if (section.intro != null)
					body.add(wrapped(section.intro, CONTENT_WIDTH));
				if (!section.table.isEmpty())
					body.add(table(section.table));
				for (TrickBook.Entry e : section.entries)
					body.add(row(e));
			}
			body.revalidate();
			body.repaint();
		}
		scrollRectToVisible(new Rectangle(0, 0, 1, 1));
	}

	private static JComponent table(List<List<String>> rows)
	{
		JPanel t = left(new JPanel(new GridLayout(0, rows.get(0).size(), 4, 1)));
		t.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		t.setBorder(new EmptyBorder(4, 4, 4, 4));
		for (List<String> row : rows)
		{
			for (String cell : row)
				// the first row is the headers
				t.add(label(cell, SMALL_FONT, row == rows.get(0) ? POINTS_COLOR
					: ColorScheme.LIGHT_GRAY_COLOR));
		}
		return stretch(t);
	}

	private static JComponent row(TrickBook.Entry e)
	{
		JPanel row = left(new JPanel(new BorderLayout(ICON_GAP, 0)));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			new EmptyBorder(ROW_PAD, ROW_PAD, ROW_PAD, ROW_PAD)));

		JComponent icon = null;
		if (e.gesture != null)
		{
			icon = new JComponent()
			{
				@Override
				protected void paintComponent(Graphics g)
				{
					// the wind-up grey, the flick light blue
					GestureGlyphPainter.paint((Graphics2D) g, e.gesture, 0, 0, GLYPH_SIZE, new Color(150, 155, 165),
						new Color(120, 200, 255));
				}
			};
			Dimension d = new Dimension(GLYPH_SIZE, GLYPH_SIZE);
			icon.setPreferredSize(d);
			icon.setMinimumSize(d);
			icon.setMaximumSize(d);
		}
		else if (e.pad != null && ControllerGlyphs.hasGlyphs(e.pad))
		{
			icon = new JLabel(new ControllerGlyphIcon(18, SkatePanel.glyphsOf(e.pad)));
			icon.setAlignmentY(Component.TOP_ALIGNMENT);
		}
		int textWidth = CONTENT_WIDTH - 2 * ROW_PAD;
		if (icon != null)
		{
			JPanel west = new JPanel(new BorderLayout());
			west.setOpaque(false);
			west.add(icon, BorderLayout.NORTH);
			row.add(west, BorderLayout.WEST);
			textWidth -= icon.getPreferredSize().width + ICON_GAP;
		}

		JPanel text = column();
		text.setOpaque(false);
		JPanel nameLine = left(new JPanel(new BorderLayout(6, 0)));
		nameLine.setOpaque(false);
		nameLine.add(label(e.name, SMALL_FONT, Color.WHITE), BorderLayout.CENTER);
		if (e.points != null)
			nameLine.add(label(e.points, SMALL_FONT, POINTS_COLOR), BorderLayout.EAST);
		text.add(stretch(nameLine));
		String detail = e.detail;
		if (e.key != null && !detail.equals("Press " + e.key))
			detail = detail.isEmpty() ? "Key: " + e.key : detail + "\nKey: " + e.key;
		if (!detail.isEmpty())
			text.add(wrapped(detail, textWidth));
		row.add(text, BorderLayout.CENTER);
		return stretch(row);
	}
}

package com.gielinorskate.ui;

import com.gielinorskate.Text;
import com.gielinorskate.controller.PadPreset;
import com.gielinorskate.input.ButtonTricks;
import com.gielinorskate.input.KeyboardTricks;
import com.gielinorskate.tricks.*;
import com.gielinorskate.tricks.Gesture.Direction;
import java.util.*;
import lombok.AllArgsConstructor;

/**
 * How to do each trick, for the Trick Book ({@link TrickBook}): its group, the mouse flick that does it (found by
 * asking {@link TrickCatalog}, so it can never drift from the real mapping), a plain-language "how" line and its
 * points. Pure.
 */
public final class TrickGuide
{
	public enum Group
	{
		BASICS,
		FLIPS,
		/** Shift tricks. */
		SHIFT,
		AIR,
		/** Grinds and manuals. */
		GRINDS
	}

	/** One trick's entry. */
	@AllArgsConstructor
	public static final class Entry
	{
		public final Trick trick;
		public final Group group;
		/** The flick that does it, or null when it is not a single flick (grabs, grinds, doubles, ...). */
		public final Gesture gesture;
		/** "Pull down, flick up-left" and the like. */
		public final String how;
		/** Its keyboard-mode key ("1", "Shift+2"), or null. */
		public final String key;

		/** "300" for a flip; "200/s" for a hold, which scores per second. */
		public String points()
		{
			boolean hold = trick.kind == TrickKind.GRAB || trick.kind == TrickKind.MANUAL
				|| trick.kind == TrickKind.GRIND;
			return trick.points + (hold ? "/s" : "");
		}
	}

	/** Said of a trick the button layout has no button for. */
	static final String NOT_ON_BUTTONS = Text.get("guide.none");
	/** The fixed "how" lines by trick (mouse and keys; controller; button tricks) and the d-pad diagonals' words. */
	private static final Map<String, String> HOW = table(Text.lines("guide.how"));
	private static final Map<String, String> PAD_HOW = table(Text.lines("guide.padHow"));
	private static final Map<String, String> BUTTON_HOW = table(Text.lines("guide.buttonHow"));
	private static final Map<String, String> DIAGONALS = table(Text.lines("guide.diagonals"));

	/** The order the Trick Book names a trick's direction in: the stick's own first, then the d-pad's diagonals. */
	static final Direction[] BUTTON_DIRECTIONS = {Direction.LEFT, Direction.RIGHT, Direction.UP,
		Direction.DOWN, Direction.UP_LEFT, Direction.UP_RIGHT, Direction.DOWN_LEFT, Direction.DOWN_RIGHT};

	private TrickGuide()
	{
	}

	/** A bundled table, one "NAME|text" a line, by name. */
	static Map<String, String> table(List<String> lines)
	{
		Map<String, String> m = new HashMap<>();
		for (String line : lines)
		{
			int i = line.indexOf('|');
			m.put(line.substring(0, i), line.substring(i + 1));
		}
		return m;
	}

	public static Entry entry(Trick t)
	{
		Gesture g = gestureFor(t);
		return new Entry(t, groupOf(t, g), g, how(t, g), KeyboardTricks.keyFor(t));
	}

	static Group groupOf(Trick t, Gesture g)
	{
		switch (t.kind)
		{
			case POP:
				return Group.BASICS;
			case GRAB:
				return Group.AIR;
			case MANUAL:
			case GRIND:
				return Group.GRINDS;
			default:
				return t.bodyFlipTurns != 0f ? Group.AIR : g != null && g.modified ? Group.SHIFT : Group.FLIPS;
		}
	}

	/**
	 * The simplest flick that does {@code t}: plain before Shift, regular before nollie, straight before curved
	 * (path turns tried: straight, a varial curve, a full 360 curl). Null when no single flick does it.
	 */
	public static Gesture gestureFor(Trick t)
	{
		for (boolean modified : new boolean[]{false, true})
		{
			for (boolean nollie : new boolean[]{false, true})
			{
				for (float turn : new float[]{0f, 90f, 180f})
				{
					for (Direction d : Direction.values())
					{
						Gesture g = new Gesture(d, nollie, turn, modified);
						if (TrickCatalog.forGesture(g) == t)
							return g;
					}
				}
			}
		}
		return null;
	}

	/**
	 * The "how" line in controller mode, with drawn-button tokens (see {@link ControllerGlyphs}) naming the buttons
	 * of {@code preset} (an action it has no button for keeps its key). With the stick layouts the right stick
	 * flicks, the grab buttons grab (Q / E), the stick aims grabs and holds manuals, push is W, and the modifier
	 * (Shift) or a grab with the left stick up / down flips. S stays a key (there is no S on the pad).
	 */
	public static String controllerHow(Trick t, Gesture g, PadPreset preset)
	{
		return PadWords.resolve(preset.buttonTricks() ? buttonHowTemplate(t) : controllerHowTemplate(t, g), preset,
			"F");
	}

	/** A button trick's direction: "{LS} left", or for a diagonal the d-pad's two buttons. */
	static String buttonDirection(Direction d)
	{
		return DIAGONALS.getOrDefault(d.name(), "{LS} " + ButtonTricks.directionName(d));
	}

	/** The "how" line with button tricks (see {@link ButtonTricks}), with action placeholders. */
	private static String buttonHowTemplate(Trick t)
	{
		String fixed = BUTTON_HOW.get(t.name());
		if (fixed != null)
			return fixed;
		if (t.kind == TrickKind.GRAB && !Grabs.isTweaked(t))
		{
			for (Direction d : BUTTON_DIRECTIONS)
			{
				if (ButtonTricks.grab(d) == t)
					return "Hold {@grabBtn} + " + buttonDirection(d) + " in the air"
						+ (ButtonTricks.grab(null) == t ? " (or no direction)" : "");
			}
			return NOT_ON_BUTTONS;
		}
		if (t.kind == TrickKind.FLIP && t.bodyFlipTurns == 0f)
		{
			for (boolean hard : new boolean[]{false, true})
			{
				for (Direction d : BUTTON_DIRECTIONS)
				{
					if (ButtonTricks.flipTrick(d, hard) == t)
						return (hard ? "Hold {@mod}: " : "") + "{@flip} + " + buttonDirection(d)
							+ (!hard && ButtonTricks.flipTrick(null, false) == t ? " (or no direction)" : "");
				}
			}
			return NOT_ON_BUTTONS;
		}
		if (t.kind == TrickKind.POP)
			return NOT_ON_BUTTONS;
		// tweaks, body flips and grinds: as with the stick, the left stick up being W
		return controllerHowTemplate(t, null).replace("{@pushFirst}", "{LS} up");
	}

	private static String controllerHowTemplate(Trick t, Gesture g)
	{
		if (g != null)
		{
			String how = how(t, g);
			return "{RS} " + Character.toLowerCase(how.charAt(0)) + how.substring(1);
		}
		String fixed = PAD_HOW.get(t.name());
		return fixed != null ? fixed : how(t, null).replaceAll("\\bQ\\b", "{@grabL}").replaceAll("\\bE\\b", "{@grabR}")
			.replace("moving the mouse", "aiming {RS}").replace("holding W", "holding {@pushFirst}");
	}

	static String how(Trick t, Gesture g)
	{
		if (g != null)
		{
			// a varial curves the flick (60+ degrees of path turn), a 360 curls it (150+), as in TrickCatalog
			String s = (g.modified ? "Hold Shift: " : "") + (g.nollie ? "push up, " : "pull down, ")
				+ "flick " + ButtonTricks.directionName(g.direction)
				+ (g.turnDegrees >= 150f ? ", curling all the way round" : g.turnDegrees >= 60f ? ", curving it" : "");
			return Character.toUpperCase(s.charAt(0)) + s.substring(1);
		}
		if (Grabs.isTweaked(t))
			return "Hold a " + Grabs.untweaked(t).displayName + " for over half a second";
		return HOW.getOrDefault(t.name(), "");
	}
}

package com.gielinorskate.ui;

import java.awt.*;
import java.awt.event.ActionListener;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.*;

/** The side panel's shared Swing pieces: headings, wrapped text, buttons and the sub-views' Back bar. EDT only. */
final class Widgets
{
	/** Wrap width of the panel's HTML labels, px. */
	static final int TEXT_WIDTH = PluginPanel.PANEL_WIDTH - 40;
	/** Width of the side panel's content (the panel's 8 px border each side). */
	static final int CONTENT_WIDTH = PluginPanel.PANEL_WIDTH - 16;
	static final Font SMALL_FONT = FontManager.getRunescapeSmallFont();

	private Widgets()
	{
	}

	/** An orange section heading. */
	static JLabel heading(String text)
	{
		JLabel l = label(text, FontManager.getRunescapeBoldFont(), ColorScheme.BRAND_ORANGE);
		l.setBorder(new EmptyBorder(10, 0, 3, 0));
		return l;
	}

	/** A left-aligned label in {@code font} (the default one when null) and {@code color}. */
	static JLabel label(String text, Font font, Color color)
	{
		JLabel l = left(new JLabel(text));
		if (font != null)
			l.setFont(font);
		l.setForeground(color);
		return l;
	}

	/** A light grey label in the default font. */
	static JLabel greyLabel(String text)
	{
		return label(text, null, ColorScheme.LIGHT_GRAY_COLOR);
	}

	/** A light grey label in the small font. */
	static JLabel small(String text)
	{
		return label(text, SMALL_FONT, ColorScheme.LIGHT_GRAY_COLOR);
	}

	static String html(String body)
	{
		return html(body, TEXT_WIDTH);
	}

	static String html(String body, int width)
	{
		return "<html><div style='width:" + width + "px'>" + body + "</div></html>";
	}

	static String esc(String s)
	{
		return s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	static <T extends JComponent> T left(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		return c;
	}

	/** {@code c} on the panel's background. */
	static <T extends JComponent> T dark(T c)
	{
		c.setBackground(ColorScheme.DARK_GRAY_COLOR);
		return c;
	}

	/** A left-aligned panel on the panel's background stacking its children top to bottom. */
	static JPanel column()
	{
		JPanel p = left(dark(new JPanel()));
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		return p;
	}

	/** {@code c} as tall as it likes and as wide as the panel lets it be. */
	static <T extends JComponent> T stretch(T c)
	{
		return stretch(c, c.getPreferredSize().height);
	}

	/** {@code c} at most {@code height} px tall and as wide as the panel lets it be. */
	static <T extends JComponent> T stretch(T c, int height)
	{
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return c;
	}

	/** A button that never takes the keyboard focus from the game; {@code l} may be null. */
	static JButton button(String text, String name, ActionListener l)
	{
		JButton b = new JButton(text);
		b.setName(name);
		b.setFocusable(false);
		if (l != null)
			b.addActionListener(l);
		return b;
	}

	/** Lays out a sub-view: a Back button ({@code backName}) and the title on top, the body added after. */
	static void subView(JPanel view, String title, String backName, Runnable onBack)
	{
		view.setLayout(new BorderLayout());
		dark(view);
		JPanel top = dark(new JPanel(new BorderLayout(8, 0)));
		top.add(button("Back", backName, e -> onBack.run()), BorderLayout.WEST);
		top.add(label(title, FontManager.getRunescapeBoldFont(), Color.WHITE), BorderLayout.CENTER);
		view.add(top, BorderLayout.NORTH);
	}

	/** Plain small text wrapped at word breaks to {@code width}, sized for that width up front. */
	static JTextArea wrapped(String text, int width)
	{
		JTextArea a = left(new JTextArea(text));
		a.setLineWrap(true);
		a.setWrapStyleWord(true);
		a.setEditable(false);
		a.setFocusable(false);
		a.setOpaque(false);
		a.setHighlighter(null);
		a.setBorder(null);
		a.setFont(SMALL_FONT);
		a.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		// the wrapped height for this width, so the panel lays out right the first time
		a.setSize(width, Short.MAX_VALUE);
		int h = a.getPreferredSize().height;
		a.setPreferredSize(new Dimension(width, h));
		a.setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		return a;
	}
}

package com.gielinorskate.world;

import static com.gielinorskate.world.GridCollisionWorld.tile;

import com.gielinorskate.physics.Contact;
import java.util.*;

/**
 * Tight per-object collision boxes: oriented rectangles with an absolute top height and a kind, indexed per
 * tile for constant-time lookups. Pure; no client dependency. Immutable once built; query from one thread.
 * <p>
 * A box is a row {cx, cy, hx, hy, cos, sin, top, kind, flags}: centred at (cx, cy) with half extents hx along
 * its u axis (cos, sin, a unit vector) and hy along its v axis (-sin, cos). Each box is registered
 * (compressed-sparse-row index) in every tile its axis-aligned bounds, grown by the skater radius
 * {@link #SKATER_R}, overlap, so a query for a skater of radius up to {@link #SKATER_R} reads only the list of
 * the tile it stands on.
 * <ul>
 * <li>{@link #SOLID}: collides on its sides; tall things (rocks, trees, walls).</li>
 * <li>{@link #LOW}: collides on its sides; you can land on top when {@link #LANDABLE} (crates, platforms).
 * Rolling into one is blocked by its raised ground, not by {@link #blockTop}.</li>
 * <li>{@link #PASS}: never collides (plants, open doors).</li>
 * </ul>
 */
public final class BlockerSet
{
	/** Skater/board radius in local units. */
	public static final float SKATER_R = 12f;
	public static final byte SOLID = 0;
	public static final byte LOW = 1;
	public static final byte PASS = 2;
	/** groundHeight is raised to the top inside the box (not its skater margin). */
	public static final int LANDABLE = 1;
	/** The box's top edges are grindable ledges. */
	public static final int LEDGES = 2;

	final float[][] boxes;
	final int size;
	/** Per tile (index tx * size + ty) the boxes registered in it, in box order. */
	final float[][][] tileBoxes;
	/** Scratch normal for {@link #depth}; queries run on the client thread only, so one is shared. */
	private final float[] scratchN = new float[2];

	BlockerSet(List<float[]> boxes, int size)
	{
		this.boxes = boxes.toArray(new float[0][]);
		this.size = Math.max(0, size);
		List<List<float[]>> tiles = new ArrayList<>();
		for (int t = 0; t < this.size * this.size; t++)
			tiles.add(new ArrayList<>());
		for (float[] b : boxes)
		{
			float ac = Math.abs(b[4]);
			float as = Math.abs(b[5]);
			// the box's bounds plus the skater radius, clipped to the grid
			float ex = ac * b[2] + as * b[3] + SKATER_R;
			float ey = as * b[2] + ac * b[3] + SKATER_R;
			for (int tx = Math.max(0, tile(b[0] - ex)); tx <= Math.min(this.size - 1, tile(b[0] + ex)); tx++)
			{
				for (int ty = Math.max(0, tile(b[1] - ey)); ty <= Math.min(this.size - 1, tile(b[1] + ey)); ty++)
					tiles.get(tx * this.size + ty).add(b);
			}
		}
		tileBoxes = tiles.stream().map(l -> l.toArray(new float[0][])).toArray(float[][][]::new);
	}

	public static BlockerSet empty()
	{
		return new BlockerSet(Collections.emptyList(), 0);
	}

	/**
	 * Deepest overlap of a circle of radius r at (x, y) with any non-PASS box whose top is above
	 * feetH + maxStep; see {@link com.gielinorskate.physics.CollisionWorld#contact}.
	 */
	public boolean contact(float x, float y, float r, float feetH, float maxStep, Contact out)
	{
		float spill = Math.max(0f, r - SKATER_R);
		boolean hit = false;
		float best = 0f;
		for (int tx = Math.max(0, tile(x - spill)); tx <= Math.min(size - 1, tile(x + spill)); tx++)
		{
			for (int ty = Math.max(0, tile(y - spill)); ty <= Math.min(size - 1, tile(y + spill)); ty++)
			{
				for (float[] b : tileBoxes[tx * size + ty])
				{
					if (b[7] == PASS || b[6] <= feetH + maxStep)
						continue;
					float d = depth(b, x, y, r, scratchN);
					if (d > 0f && (!hit || d > best))
					{
						hit = true;
						best = d;
						out.set(scratchN[0], scratchN[1], d, b[6]);
					}
				}
			}
		}
		return hit;
	}

	/** Highest top of a {@link #LANDABLE} non-PASS box containing (x, y), or -infinity. */
	public float landTop(float x, float y)
	{
		float best = Float.NEGATIVE_INFINITY;
		int t = tileIndex(x, y);
		if (t < 0)
			return best;
		for (float[] b : tileBoxes[t])
		{
			if (b[7] != PASS && ((int) b[8] & LANDABLE) != 0 && b[6] > best && Math.abs(u(b, x, y)) <= b[2]
				&& Math.abs(v(b, x, y)) <= b[3])
				best = b[6];
		}
		return best;
	}

	/**
	 * Highest top of a {@link #SOLID} box the skater (radius {@code r}, capped at the {@link #SKATER_R} the
	 * tile index is grown by) would push into when moving from (x0, y0) to (x1, y1), or -infinity. A move counts
	 * when its end is more deeply inside a box than its start, or when it starts outside a box and its midpoint is
	 * inside (so a fast step cannot skip a thin box): a skater already overlapping a box can always slide along it
	 * or move out of it, never further in (least-penetration escape).
	 */
	public float blockTop(float x0, float y0, float x1, float y1, float r)
	{
		r = Math.min(r, SKATER_R);
		float best = Float.NEGATIVE_INFINITY;
		float[] n = scratchN;
		for (int pass = 0; pass < 2; pass++)
		{
			float px = pass == 0 ? x1 : (x0 + x1) / 2f;
			float py = pass == 0 ? y1 : (y0 + y1) / 2f;
			int t = tileIndex(px, py);
			if (t < 0)
				continue;
			for (float[] b : tileBoxes[t])
			{
				if (b[7] != SOLID || b[6] <= best)
					continue;
				float d = depth(b, px, py, r, n);
				if (d <= 0f)
					continue;
				float d0 = depth(b, x0, y0, r, n);
				// the midpoint only catches a step over a thin box from outside it, so only a move whose path
				// crosses the box itself counts: one that grazes past a corner within the skater radius, its end
				// clear, is not stepping over anything (it used to block, and with no contact at the clear end to
				// slide along the skater stopped dead against the corner). From inside, only where the move
				// ends matters (crossing the middle of a box on the way out is fine). The 1e-3 is how much the
				// penetration must grow to count as going deeper.
				if (pass == 0 ? d > Math.max(0f, d0) + 1e-3f : d0 <= 0f && crossesBox(b, x0, y0, x1, y1))
					best = b[6];
			}
		}
		return best;
	}

	/** Box b's u coordinate of (x, y). */
	private static float u(float[] b, float x, float y)
	{
		return (x - b[0]) * b[4] + (y - b[1]) * b[5];
	}

	/** Box b's v coordinate of (x, y). */
	private static float v(float[] b, float x, float y)
	{
		return -(x - b[0]) * b[5] + (y - b[1]) * b[4];
	}

	/**
	 * Penetration of a circle of radius r at (x, y) into box b (positive = overlapping), with the push-out
	 * normal in n. Outside the box: r minus the distance to it. Inside: r plus the distance to the nearest
	 * face, along that face's normal.
	 */
	private static float depth(float[] b, float x, float y, float r, float[] n)
	{
		float c = b[4];
		float s = b[5];
		float lu = u(b, x, y);
		float lv = v(b, x, y);
		float du = lu - Math.max(-b[2], Math.min(b[2], lu));
		float dv = lv - Math.max(-b[3], Math.min(b[3], lv));
		if (du != 0f || dv != 0f)
		{
			float d = (float) Math.sqrt(du * du + dv * dv);
			float nu = du / d;
			float nv = dv / d;
			n[0] = nu * c - nv * s;
			n[1] = nu * s + nv * c;
			return r - d;
		}
		float eu = b[2] - Math.abs(lu);
		float ev = b[3] - Math.abs(lv);
		if (eu < ev)
		{
			float su = lu < 0f ? -1f : 1f;
			n[0] = su * c;
			n[1] = su * s;
			return r + eu;
		}
		float sv = lv < 0f ? -1f : 1f;
		n[0] = -sv * s;
		n[1] = sv * c;
		return r + ev;
	}

	/** True when the segment (x0, y0)-(x1, y1) passes through box b itself (no skater radius): a slab clip. */
	private static boolean crossesBox(float[] b, float x0, float y0, float x1, float y1)
	{
		float u0 = u(b, x0, y0);
		float v0 = v(b, x0, y0);
		float[] range = {0f, 1f};
		return clip(u0, u(b, x1, y1) - u0, b[2], range) && clip(v0, v(b, x1, y1) - v0, b[3], range);
	}

	/** Narrows range {tMin, tMax} to where p + t * d lies within [-h, h]; false when that is empty. */
	private static boolean clip(float p, float d, float h, float[] range)
	{
		if (Math.abs(d) < 1e-9f)
			return Math.abs(p) <= h;
		float ta = (-h - p) / d;
		float tb = (h - p) / d;
		range[0] = Math.max(range[0], Math.min(ta, tb));
		range[1] = Math.min(range[1], Math.max(ta, tb));
		return range[0] <= range[1];
	}

	/** Index of the tile holding (x, y), or -1 off the grid. */
	private int tileIndex(float x, float y)
	{
		int tx = tile(x);
		int ty = tile(y);
		return tx < 0 || ty < 0 || tx >= size || ty >= size ? -1 : tx * size + ty;
	}

	/** The four corners of box b into out = {x0, y0, .. x3, y3}: -u-v, +u-v, +u+v, -u+v (counter-clockwise). */
	static void corners(float[] b, float[] out)
	{
		float ux = b[4] * b[2];
		float uy = b[5] * b[2];
		float vx = -b[5] * b[3];
		float vy = b[4] * b[3];
		for (int k = 0; k < 4; k++)
		{
			float su = k == 1 || k == 2 ? 1f : -1f;
			float sv = k < 2 ? -1f : 1f;
			out[2 * k] = b[0] + su * ux + sv * vx;
			out[2 * k + 1] = b[1] + su * uy + sv * vy;
		}
	}
}

package com.gielinorskate.world;

import com.gielinorskate.physics.CollisionWorld;
import com.gielinorskate.physics.Contact;
import java.util.ArrayList;
import java.util.List;

/**
 * A square grid of tiles with corner heights, edge walls (with their own heights), full-tile
 * blockers/platforms and tight per-object boxes ({@link BlockerSet}). North = +y.
 * <p>
 * A FULL tile marked {@link #markShaped shaped} collides only through the boxes added for its objects;
 * an unshaped one (water, or a test world) still blocks or rises as a whole tile. Boxes are re-indexed
 * lazily after any change; use from one thread.
 * <p>
 * Sides are bits 1 &lt;&lt; i for i = 0..3: north, east, south, west, each with its neighbour offset
 * ({@link #DX}, {@link #DY}); the opposite side is i + 2.
 */
public final class GridCollisionWorld implements CollisionWorld
{
	public static final int TILE = 128;
	public static final int WALL_N = 1;
	public static final int WALL_E = 2;
	public static final int WALL_S = 4;
	public static final int WALL_W = 8;
	public static final int FULL = 16;
	/** Full tiles at or below this height are platforms you can land on rather than walls. */
	public static final float PLATFORM_MAX_HEIGHT = 120f;
	/**
	 * Wall blockers this tall (fences, low walls, rails) are grindable along their edge. The maximum
	 * (was 100) is set by a fully charged ollie: peak 820^2 / (2 * 2000) = 168, and GrindMap locks on
	 * down to BELOW_TOP 16 under the top, so tops up to 168 + 16 = 184 are reachable. With coarse 0.02 s
	 * physics steps the semi-implicit peak is about 8 lower (160), i.e. 176; 180 is the frame-rate-ideal edge.
	 * Taller walls still block like any wall: grind extraction never changes collision.
	 */
	public static final float GRIND_WALL_MIN = 16f;
	public static final float GRIND_WALL_MAX = 180f;
	private static final int[] DX = {0, 1, 0, -1};
	private static final int[] DY = {1, 0, -1, 0};

	private final int size;
	/**
	 * Each tile's own four corner heights, SW, SE, NW, NE, set per tile by {@link #setTileCorners}: the terrain
	 * need not be continuous (a bridge deck over a river keeps its edge corners at deck height).
	 */
	final float[][][] tileCorners;
	private final int[][] flags;
	/** Height of the full-tile blocker or platform (FULL tiles). */
	private final float[][] heights;
	/** Height of the tile's wall edges, kept apart from {@link #heights} so a tree on a fence tile doesn't raise the fence. */
	private final float[][] wallHeights;
	/** FULL tiles whose collision comes from object boxes (or nothing, e.g. plants) rather than the whole tile. */
	private final boolean[][] shaped;
	private GrindMap grinds = new GrindMap();
	/** Extra grind segments from outside the collision flags (e.g. objects named like fences or benches). */
	final List<GrindSegment> added = new ArrayList<>();
	/** Object boxes as BlockerSet rows, with the top as the height above the terrain at the centre. */
	private final List<float[]> pendingBoxes = new ArrayList<>();
	private BlockerSet objects = BlockerSet.empty();
	private BlockerSet walls = BlockerSet.empty();
	private boolean blockersDirty = true;
	/** Scratch for {@link #contact}'s wall query (client thread only, so one is shared). */
	private final Contact scratchWall = new Contact();
	/** Edges of the loaded (unblocked) area on both axes, local units; unlimited until set. */
	private float loadedLo = Float.NEGATIVE_INFINITY;
	private float loadedHi = Float.POSITIVE_INFINITY;

	public GridCollisionWorld(int size)
	{
		this.size = size;
		tileCorners = new float[size][size][4];
		flags = new int[size][size];
		heights = new float[size][size];
		wallHeights = new float[size][size];
		shaped = new boolean[size][size];
	}

	/**
	 * Adds a tight object box centred at (cx, cy), half extents hx along (cos, sin) and hy across, whose top
	 * is {@code height} above the terrain under its centre; kind and flags as in {@link BlockerSet}. Does not
	 * by itself change how the FULL tile under it collides: see {@link #markShaped}.
	 */
	public void addBlocker(float cx, float cy, float hx, float hy, float cos, float sin, float height, byte kind, int flags)
	{
		pendingBoxes.add(new float[]{cx, cy, hx, hy, cos, sin, height, kind, flags});
		blockersDirty = true;
	}

	/** {@link #addBlocker} for an oriented box {cx, cy, hx, hy, cos, sin} from {@link ObjectShapes#box}. */
	private void addBlocker(float[] b, float height, byte kind, int flags)
	{
		addBlocker(b[0], b[1], b[2], b[3], b[4], b[5], height, kind, flags);
	}

	/**
	 * Sets the loaded area: tiles [lo, hi) on both axes. The client blocks every tile outside it (tile 0 and
	 * tiles size - 5 and up of its collision maps), which is the edge {@link #edgeDistance} measures to.
	 */
	public void setLoadedTiles(int lo, int hi)
	{
		loadedLo = lo * (float) TILE;
		loadedHi = hi * (float) TILE;
	}

	@Override
	public float edgeDistance(float x, float y)
	{
		return Math.min(Math.min(x - loadedLo, loadedHi - x), Math.min(y - loadedLo, loadedHi - y));
	}

	/**
	 * Marks FULL tile (tx, ty) as shaped by object boxes: it no longer blocks (or rises, as a platform) as a
	 * whole tile; only the boxes added for its objects collide. Unmarked FULL tiles (water, test worlds) keep
	 * whole-tile collision.
	 */
	public void markShaped(int tx, int ty)
	{
		shaped[tx][ty] = true;
		blockersDirty = true;
	}

	/**
	 * Adds the box of a blocking object at local (originX, originY) whose model slice at skater height
	 * ({@link ObjectShapes#sliceExtents}) has extents {@code slice} = {minX, maxX, minZ, maxZ}, drawn with
	 * the given orientation (JAU), {@code height} tall. Its kind follows {@link ObjectShapes#classify}; a LOW
	 * box is landable, and its top edges are grind ledges only when {@code ledges} (not for a rock:
	 * {@link ObjectNames}). Returns the kind.
	 */
	public byte addObjectBlocker(float originX, float originY, float[] slice, int orientation, float height, boolean passByName,
		boolean ledges)
	{
		byte kind = ObjectShapes.classify(passByName, height, ObjectShapes.minSide(slice));
		addBlocker(ObjectShapes.box(originX, originY, slice, orientation, 0f), height, kind,
			kind == BlockerSet.LOW ? BlockerSet.LANDABLE | (ledges ? BlockerSet.LEDGES : 0) : 0);
		return kind;
	}

	/**
	 * Adds the box of a name-grindable object (bench, fence piece, crate) with model extents {@code ext}:
	 * its thin side is inflated to 12 either side (plus the 12 skater radius = 24 of reach) so it cannot be
	 * slipped through, its top is the rail top ({@code height} above the terrain under its centre) and it is
	 * always landable, so a missed grind lands on the object instead of inside it. LOW up to 120 tall, SOLID
	 * above.
	 */
	public void addGrindableBlocker(float originX, float originY, float[] ext, int orientation, float height)
	{
		addBlocker(ObjectShapes.box(originX, originY, ext, orientation, 12f), height,
			height <= PLATFORM_MAX_HEIGHT ? BlockerSet.LOW : BlockerSet.SOLID, BlockerSet.LANDABLE);
	}

	/** A FULL tile with no usable model: a centred 96 x 96 box 400 tall. */
	public void addFallbackBlocker(int tx, int ty)
	{
		addBlocker((tx + 0.5f) * TILE, (ty + 0.5f) * TILE, 48f, 48f, 1f, 0f, 400f, BlockerSet.SOLID, 0);
		markShaped(tx, ty);
	}

	/**
	 * Removes the wall on the given sides ({@link #WALL_N}/E/S/W bits) of tile (tx, ty) for a wall object that
	 * is ridden through (vegetation drawn as a wall, an open door). The game flags a wall on both tiles it
	 * separates, so the mirrored side of the neighbour across each edge is cleared too; the neighbour's other
	 * walls stay.
	 */
	public void openWallEdges(int tx, int ty, int sides)
	{
		flags[tx][ty] &= ~(sides & 15);
		for (int i = 0; i < 4; i++)
		{
			int nx = tx + DX[i];
			int ny = ty + DY[i];
			if ((sides & 1 << i) != 0 && inBounds(nx, ny))
				flags[nx][ny] &= ~(1 << (i + 2) % 4);
		}
		blockersDirty = true;
	}

	/** Sets the height of tile (tx, ty)'s wall edges alone (setTile sets it to the tile's blocker height). */
	public void setWallHeight(int tx, int ty, float h)
	{
		wallHeights[tx][ty] = h;
		blockersDirty = true;
	}

	/**
	 * Object boxes, including whole-tile boxes for unshaped FULL tiles (LOW without {@link BlockerSet#LANDABLE}
	 * for platforms, whose ground rise stays whole-tile). Built on first use after a change.
	 */
	public BlockerSet getBlockers()
	{
		ensureBlockers();
		return objects;
	}

	/**
	 * Re-indexes the boxes; call after the corner heights, tiles and boxes are set (done lazily otherwise).
	 * Wall edges collide as boxes 4 thick (2 either side of the tile edge).
	 */
	public void rebuildBlockers()
	{
		List<float[]> ob = new ArrayList<>();
		for (float[] b : pendingBoxes)
		{
			float[] abs = b.clone();
			abs[6] += terrainHeight(b[0], b[1]);
			ob.add(abs);
		}
		List<float[]> wb = new ArrayList<>();
		float half = TILE / 2f;
		for (int tx = 0; tx < size; tx++)
		{
			for (int ty = 0; ty < size; ty++)
			{
				int f = flags[tx][ty];
				if ((f & FULL) != 0 && !shaped[tx][ty])
				{
					float cx = (tx + 0.5f) * TILE;
					float cy = (ty + 0.5f) * TILE;
					ob.add(new float[]{cx, cy, half, half, 1f, 0f, terrainHeight(cx, cy) + heights[tx][ty],
						heights[tx][ty] <= PLATFORM_MAX_HEIGHT ? BlockerSet.LOW : BlockerSet.SOLID, 0});
				}
				for (int i = 0; i < 4; i++)
				{
					if ((f & 1 << i) != 0)
					{
						GrindSegment e = edge(tx, ty, 1 << i, wallHeights[tx][ty]);
						boolean alongX = e.y0 == e.y1;
						wb.add(new float[]{(e.x0 + e.x1) / 2f, (e.y0 + e.y1) / 2f, half, 2f, alongX ? 1f : 0f,
							alongX ? 0f : 1f, e.top, BlockerSet.SOLID, 0});
					}
				}
			}
		}
		objects = new BlockerSet(ob, size);
		walls = new BlockerSet(wb, size);
		blockersDirty = false;
	}

	private void ensureBlockers()
	{
		if (blockersDirty)
			rebuildBlockers();
	}

	/**
	 * Deepest contact with an object box (including whole-tile boxes of unshaped FULL tiles) or a wall edge
	 * box; see {@link CollisionWorld#contact}. A skater inside a box gets the least-penetration way out.
	 */
	@Override
	public boolean contact(float x, float y, float r, float feetH, float maxStep, Contact out)
	{
		ensureBlockers();
		boolean hit = objects.contact(x, y, r, feetH, maxStep, out);
		Contact wall = scratchWall;
		if (walls.contact(x, y, r, feetH, maxStep, wall) && (!hit || wall.depth > out.depth))
		{
			out.set(wall.nx, wall.ny, wall.depth, wall.top);
			hit = true;
		}
		return hit;
	}

	/** Grindable edges extracted by {@link #rebuildGrinds()}; empty until then. */
	public GrindMap getGrinds()
	{
		return grinds;
	}

	/**
	 * Adds a grind along one side ({@link #WALL_N}/E/S/W) of tile (tx, ty) at that side's mean corner
	 * ground height plus {@code above}. Set the corner heights first.
	 */
	public void addEdgeGrind(int tx, int ty, int side, float above)
	{
		added.add(edge(tx, ty, side, above));
	}

	/**
	 * Adds the grinds of a scene object at local (originX, originY) whose model has horizontal extents
	 * {@code ext} = {minX, maxX, minZ, maxZ} and the given orientation (JAU): a centreline rail for a long
	 * object, the perimeter of its own bounds for a square-ish one (see {@link ObjectShapes}). The top
	 * at each end of a segment is the terrain there (platform tops ignored) plus {@code above}, so a handrail
	 * on a slope follows it instead of floating at one end and clipping at the other.
	 */
	public void addObjectGrind(float originX, float originY, float[] ext, int orientation, float above)
	{
		for (GrindSegment s : ObjectShapes.segments(originX, originY, ext, orientation))
			added.add(new GrindSegment(s.x0, s.y0, s.x1, s.y1,
				terrainHeight(s.x0, s.y0) + above, terrainHeight(s.x1, s.y1) + above));
	}

	/**
	 * Re-extracts the grind map from the current tiles (call once after the grid is filled):
	 * <ul>
	 * <li>each wall edge whose wall height is in [{@link #GRIND_WALL_MIN}, {@link #GRIND_WALL_MAX}]
	 * becomes a rail along that edge, at the edge's mean corner ground height plus the wall height;</li>
	 * <li>each (unshaped) platform tile edge that borders an in-bounds non-platform tile becomes a ledge at
	 * the platform top (mean edge corner height plus the platform height). Scene-border edges are skipped.</li>
	 * <li>the four top edges of every object box flagged {@link BlockerSet#LEDGES} (LOW crates, planters).</li>
	 * <li>every segment added with {@link #addEdgeGrind} or {@link #addObjectGrind} (name-based grindables from
	 * the scene).</li>
	 * </ul>
	 * Collinear neighbours are then merged; the same edge flagged on both neighbouring tiles collapses to
	 * one segment (or stays two if their tops differ by more than the merge tolerance).
	 */
	public void rebuildGrinds()
	{
		GrindMap m = new GrindMap();
		for (int tx = 0; tx < size; tx++)
		{
			for (int ty = 0; ty < size; ty++)
			{
				float bh = wallHeights[tx][ty];
				boolean grindWall = bh >= GRIND_WALL_MIN && bh <= GRIND_WALL_MAX;
				boolean platform = isPlatform(tx, ty);
				for (int i = 0; i < 4; i++)
				{
					if (grindWall && (flags[tx][ty] & 1 << i) != 0)
						m.add(edge(tx, ty, 1 << i, bh));
				}
				for (int i = 0; platform && i < 4; i++)
				{
					int nx = tx + DX[i];
					int ny = ty + DY[i];
					if (inBounds(nx, ny) && !isPlatform(nx, ny))
						m.add(edge(tx, ty, 1 << i, heights[tx][ty]));
				}
			}
		}
		float[] c = new float[8];
		for (float[] b : getBlockers().boxes)
		{
			if (((int) b[8] & BlockerSet.LEDGES) != 0 && b[7] != BlockerSet.PASS)
			{
				BlockerSet.corners(b, c);
				for (int k = 0; k < 4; k++)
				{
					int j = (k + 1) % 4;
					m.add(new GrindSegment(c[2 * k], c[2 * k + 1], c[2 * j], c[2 * j + 1], b[6]));
				}
			}
		}
		added.forEach(m::add);
		m.merge();
		grinds = m;
	}

	/**
	 * Segment along one side of a tile, `above` the ground at each of that side's two corners, so it slopes
	 * with a hill (its mean top is the old flat height, used for the wall box). North and south run west to
	 * east, east and west run south to north.
	 */
	private GrindSegment edge(int tx, int ty, int side, float above)
	{
		int ax = side == WALL_E ? tx + 1 : tx;
		int ay = side == WALL_N ? ty + 1 : ty;
		int bx = side == WALL_W ? tx : tx + 1;
		int by = side == WALL_S ? ty : ty + 1;
		return new GrindSegment(ax * TILE, ay * TILE, bx * TILE, by * TILE, corner(tx, ty, ax, ay) + above,
			corner(tx, ty, bx, by) + above);
	}

	public int size()
	{
		return size;
	}

	/**
	 * Sets tile (tx, ty)'s own corner heights without touching its neighbours, for terrain that is not
	 * continuous across the tile edge (a bridge deck beside the river bed under it).
	 */
	public void setTileCorners(int tx, int ty, float sw, float se, float nw, float ne)
	{
		tileCorners[tx][ty] = new float[]{sw, se, nw, ne};
		blockersDirty = true;
	}

	/** Tile (tx, ty)'s own height at grid corner (cx, cy), one of its four corners. */
	private float corner(int tx, int ty, int cx, int cy)
	{
		return tileCorners[tx][ty][(cy > ty ? 2 : 0) + (cx > tx ? 1 : 0)];
	}

	/** Sets a tile's flags and its blocker height, which is also its wall height until {@link #setWallHeight}. */
	public void setTile(int tx, int ty, int tileFlags, float blockerHeight)
	{
		flags[tx][ty] = tileFlags;
		heights[tx][ty] = blockerHeight;
		wallHeights[tx][ty] = blockerHeight;
		blockersDirty = true;
	}

	/**
	 * Terrain, raised by an unshaped platform tile over the whole tile, or by a {@link BlockerSet#LANDABLE}
	 * object box only inside the box itself.
	 */
	@Override
	public float groundHeight(float x, float y)
	{
		float ground = terrainHeight(x, y);
		int tx = tile(clampLocal(x));
		int ty = tile(clampLocal(y));
		if (isPlatform(tx, ty))
			ground += heights[tx][ty];
		ensureBlockers();
		return Math.max(ground, objects.landTop(x, y));
	}

	/** Terrain height from the tile's own corner heights alone (no platform tops), clamped to the grid. */
	@Override
	public float terrainHeight(float x, float y)
	{
		float cx = clampLocal(x);
		float cy = clampLocal(y);
		int tx = (int) (cx / TILE);
		int ty = (int) (cy / TILE);
		float fx = (cx - tx * TILE) / TILE;
		float fy = (cy - ty * TILE) / TILE;
		float[] c = tileCorners[tx][ty];
		float south = c[0] * (1 - fx) + c[1] * fx;
		float north = c[2] * (1 - fx) + c[3] * fx;
		return south * (1 - fy) + north * fy;
	}

	private float clampLocal(float v)
	{
		return Math.max(0f, Math.min(size * TILE - 0.001f, v));
	}

	/** {@link #blockerTop(float, float, float, float, float)} with the full {@link BlockerSet#SKATER_R}. */
	@Override
	public float blockerTop(float x0, float y0, float x1, float y1)
	{
		return blockerTop(x0, y0, x1, y1, BlockerSet.SKATER_R);
	}

	/**
	 * Tall object boxes (and unshaped tall FULL tiles) the move pushes the skater (radius {@code r}, at most
	 * {@link BlockerSet#SKATER_R}) into, see {@link BlockerSet#blockTop}: a skater already inside one can
	 * always move out or along it but never deeper (least-penetration escape). Wall edges are exact tile
	 * edge crossings. LOW boxes and platforms block through their raised {@link #groundHeight} instead.
	 */
	@Override
	public float blockerTop(float x0, float y0, float x1, float y1, float r)
	{
		int ax = tile(x0);
		int ay = tile(y0);
		int bx = tile(x1);
		int by = tile(y1);
		if (!inBounds(bx, by))
			return Float.POSITIVE_INFINITY;

		ensureBlockers();
		float top = objects.blockTop(x0, y0, x1, y1, r);
		if (!inBounds(ax, ay) || ax == bx && ay == by)
			return top;
		float g = groundHeight(x1, y1);
		if (ax != bx && ay != by)
		{
			// Diagonal move a -> b. There are two routes through the corner:
			// via (bx,ay) [cross x-edge a->(bx,ay), then y-edge (bx,ay)->b]
			// via (ax,by) [cross y-edge a->(ax,by), then x-edge (ax,by)->b]
			// Each route is blocked by the max of its two edge blockers (boxes on the
			// corner tiles are covered by the box check above); the move
			// is only blocked if BOTH routes are blocked (min of the two routes).
			float route1 = inBounds(bx, ay)
				? Math.max(edgeTop(ax, ay, bx, ay, g), edgeTop(bx, ay, bx, by, g)) : Float.POSITIVE_INFINITY;
			float route2 = inBounds(ax, by)
				? Math.max(edgeTop(ax, ay, ax, by, g), edgeTop(ax, by, bx, by, g)) : Float.POSITIVE_INFINITY;
			return Math.max(top, Math.min(route1, route2));
		}
		return Math.max(top, edgeTop(ax, ay, bx, by, g));
	}

	/**
	 * Top of the wall blocker (if any) on the shared edge between two orthogonally adjacent tiles, standing on
	 * ground {@code g} where the move ends.
	 */
	private float edgeTop(int fromX, int fromY, int toX, int toY, float g)
	{
		int i = toX > fromX ? 1 : toX < fromX ? 3 : toY > fromY ? 0 : 2;
		return Math.max((flags[fromX][fromY] & 1 << i) != 0 ? g + wallHeights[fromX][fromY] : Float.NEGATIVE_INFINITY,
			(flags[toX][toY] & 1 << (i + 2) % 4) != 0 ? g + wallHeights[toX][toY] : Float.NEGATIVE_INFINITY);
	}

	private boolean isPlatform(int tx, int ty)
	{
		return (flags[tx][ty] & FULL) != 0 && !shaped[tx][ty] && heights[tx][ty] <= PLATFORM_MAX_HEIGHT;
	}

	private boolean inBounds(int tx, int ty)
	{
		return tx >= 0 && ty >= 0 && tx < size && ty < size;
	}

	static int tile(float v)
	{
		return (int) Math.floor(v / TILE);
	}
}

package com.gielinorskate.world;

import static com.gielinorskate.world.GridCollisionWorld.tile;

import java.util.*;
import lombok.AllArgsConstructor;

/** Every grindable edge in the loaded scene. Pure data; no client dependency. */
public final class GrindMap
{
	/**
	 * Horizontal distance from the segment within which the skater snaps on (was 28). 44 is about a
	 * third of a tile: at 500 u/s a 0.02 s step moves 10 units, so a skater crossing a rail at the
	 * 80-degree approach limit spends (2 * 44) / (500 * sin 80) = 0.18 s, about 9 steps, inside the
	 * catch band instead of about 5.
	 */
	public static final float SNAP_DISTANCE = 44f;
	/**
	 * The snap distance while the grind button is held (the Tony Hawk's American Wasteland preset's Y): a rail
	 * catches from further to the side. Never used without the button, so grinding is never harder than without it.
	 */
	public static final float ASSIST_SNAP_DISTANCE = 72f;
	/** The tile buckets reach this far, so every segment within either snap distance is in a point's tile list. */
	private static final float BUCKET_REACH = Math.max(SNAP_DISTANCE, ASSIST_SNAP_DISTANCE);
	/** Rolling into a rail (and a pop coming back down onto the rail it left): this far below the top... */
	public static final float BELOW_TOP = 16f;
	/** ...or this far above it. */
	public static final float ABOVE_TOP = 48f;
	/**
	 * Largest angle between travel and the segment's line (either direction along it); was 80 (60 before
	 * that). 18% of the review's attempts were rejected at 80-85 degrees; physics redirects the velocity
	 * along the rail on lock (taking the direction from the steer when the travel is nearly square to it).
	 * Strictly below 90 so a skater crossing a rail exactly square-on still clears it.
	 */
	public static final float MAX_APPROACH = (float) Math.toRadians(88);
	/**
	 * A lock needs at least this much rail left in the travel direction (review P5): the closest point is
	 * clamped to the segment, so a skater flying past the end it is heading for would otherwise lock for
	 * one step and hop straight off again.
	 */
	public static final float MIN_RAIL_AHEAD = 32f;
	/**
	 * Below this |cos| between travel and the rail (about 78 degrees and steeper) the travel does not say
	 * which way along the rail to go; physics picks it from the steer (see {@link #enoughAhead}).
	 */
	public static final float AMBIGUOUS_ALONG = 0.2f;
	/** Collinear touching segments whose tops differ by at most this merge into one. */
	private static final float MERGE_TOP_TOLERANCE = 4f;

	/** A lock-on candidate: the segment and the clamped parameter of the closest point on it. */
	@AllArgsConstructor
	public static final class Hit
	{
		public final GrindSegment segment;
		public final float t;
	}

	private final List<GrindSegment> segments = new ArrayList<>();
	/**
	 * Per-tile buckets for the lock-on and connection queries (review extra 7: the old linear scan ran every
	 * air step): each segment is listed on every tile its bounds, grown by {@link #BUCKET_REACH}, touch, so
	 * every segment within either snap distance of a point is in that point's tile list. Built lazily, dropped on
	 * any change.
	 */
	private Map<Long, List<GrindSegment>> buckets;

	public void add(GrindSegment s)
	{
		segments.add(s);
		buckets = null;
	}

	private static long key(int a, int b)
	{
		return ((long) a << 32) ^ (b & 0xffffffffL);
	}

	/** Segments that may lie within {@link #BUCKET_REACH} of the tile (tx, ty). */
	private List<GrindSegment> near(int tx, int ty)
	{
		if (buckets == null)
		{
			buckets = new HashMap<>();
			for (GrindSegment s : segments)
			{
				for (int x = tile(Math.min(s.x0, s.x1) - BUCKET_REACH); x <= tile(Math.max(s.x0, s.x1) + BUCKET_REACH); x++)
				{
					for (int y = tile(Math.min(s.y0, s.y1) - BUCKET_REACH); y <= tile(Math.max(s.y0, s.y1) + BUCKET_REACH); y++)
						buckets.computeIfAbsent(key(x, y), k -> new ArrayList<>()).add(s);
				}
			}
		}
		return buckets.getOrDefault(key(tx, ty), Collections.emptyList());
	}

	public List<GrindSegment> segments()
	{
		return Collections.unmodifiableList(segments);
	}

	/**
	 * Joins collinear segments that touch or overlap and lie on the same height line: a flat or sloped run,
	 * extended, passes within {@link #MERGE_TOP_TOLERANCE} of both ends of the next piece. Identical duplicates
	 * collapse to one. Segments are bucketed by their line (angle in 0.001 rad bins, offset in 0.5 unit bins),
	 * sorted along it and swept, so this is O(n log n). A merged run keeps the height line (top and slope) of
	 * its first segment.
	 */
	public void merge()
	{
		Map<Long, List<GrindSegment>> lines = new LinkedHashMap<>();
		for (GrindSegment s : segments)
		{
			float[] u = axis(s);
			if (s.length() > 0f)
				lines.computeIfAbsent(key(Math.round(lineAngle(s) / 0.001f), Math.round((u[1] * s.x0 - u[0] * s.y0) / 0.5f)),
					k -> new ArrayList<>()).add(s);
		}

		segments.clear();
		buckets = null;
		for (List<GrindSegment> line : lines.values())
		{
			GrindSegment ref = line.get(0);
			float[] u = axis(ref);
			float base = u[0] * ref.x0 + u[1] * ref.y0;
			List<float[]> runs = new ArrayList<>();
			// sweep the pieces in order along the line: one joins the first run that it touches (a gap of at most
			// 1 unit) and whose height line, extended, passes within the tolerance of both of its ends
			line.stream().map(s -> span(s, u)).sorted((p, q) -> Float.compare(p[0], q[0])).forEach(sp ->
			{
				float[] into = runs.stream().filter(r -> sp[0] <= r[1] + 1f
					&& Math.abs(r[2] + r[3] * (sp[0] - r[0]) - sp[2]) <= MERGE_TOP_TOLERANCE
					&& Math.abs(r[2] + r[3] * (sp[1] - r[0]) - (sp[2] + sp[3] * (sp[1] - sp[0]))) <= MERGE_TOP_TOLERANCE)
					.findFirst().orElse(null);
				if (into == null)
					runs.add(sp);
				else
					into[1] = Math.max(into[1], sp[1]);
			});
			for (float[] r : runs)
				segments.add(new GrindSegment(ref.x0 + u[0] * (r[0] - base), ref.y0 + u[1] * (r[0] - base),
					ref.x0 + u[0] * (r[1] - base), ref.y0 + u[1] * (r[1] - base), r[2], r[2] + r[3] * (r[1] - r[0])));
		}
	}

	/** Segment s as a span {lo, hi, top at lo, rise per unit} along the line direction u. */
	private static float[] span(GrindSegment s, float[] u)
	{
		float s0 = u[0] * s.x0 + u[1] * s.y0;
		float s1 = u[0] * s.x1 + u[1] * s.y1;
		float lo = Math.min(s0, s1);
		float hi = Math.max(s0, s1);
		float topLo = s0 <= s1 ? s.top0 : s.top1;
		return new float[]{lo, hi, topLo, hi > lo ? ((s0 <= s1 ? s.top1 : s.top0) - topLo) / (hi - lo) : 0f};
	}

	/**
	 * The closest segment within {@code snap} horizontally, with h in [top - {@link #BELOW_TOP}, top +
	 * {@link #ABOVE_TOP}] and travel within {@link #MAX_APPROACH} of its line in either direction, skipping
	 * {@code exclude} (may be null); null if none qualifies.
	 */
	public Hit nearest(float x, float y, float h, float travelHeading, GrindSegment exclude, float snap)
	{
		return query(x, y, h, travelHeading, BELOW_TOP, ABOVE_TOP, exclude, null, snap);
	}

	/**
	 * True when a rail lies within {@code radius} horizontally of (x, y) with its top from {@link #BELOW_TOP} below
	 * {@code h} to {@code above} over it, whichever way it runs: there is a rail to grind near the skater.
	 */
	public boolean railWithin(float x, float y, float h, float radius, float above)
	{
		int span = (int) Math.ceil(Math.max(0f, radius - BUCKET_REACH) / GridCollisionWorld.TILE);
		for (int i = -span; i <= span; i++)
		{
			for (int j = -span; j <= span; j++)
			{
				for (GrindSegment s : near(tile(x) + i, tile(y) + j))
				{
					float t = s.project(x, y);
					float top = s.topAt(t);
					if (s.length() > 0f && top >= h - BELOW_TOP && top <= h + above
						&& Math.hypot(x - s.xAt(t), y - s.yAt(t)) <= radius)
						return true;
				}
			}
		}
		return false;
	}

	/** {@link #nearestInAir(float, float, float, float, float, GrindSegment, GrindSegment, float)} at {@link #SNAP_DISTANCE}. */
	public Hit nearestInAir(float x, float y, float h, float vh, float travelHeading, GrindSegment exclude,
		GrindSegment excludeRising)
	{
		return nearestInAir(x, y, h, vh, travelHeading, exclude, excludeRising, SNAP_DISTANCE);
	}

	/**
	 * Lock-on query for an airborne skater with vertical speed {@code vh} (the grind magnet, review P3): h in
	 * [top - 32, top + 90] while rising (vh &gt; 0; the review suggested 40 below, 32 keeps the band a little
	 * tighter under the rail; 90 above, was 48, so a high pop crossing a low rail still catches it), else in
	 * [top - 28, top + 160] so coming down from a big pop over a rail catches it. Skips {@code exclude} always
	 * and {@code excludeRising} (the rail just popped off) while rising; once falling that rail only catches in
	 * the plain [top - {@link #BELOW_TOP}, top + {@link #ABOVE_TOP}] window, so a hop along it lands back on it
	 * instead of snapping down from the top of the hop (review P1). Both may be null. As {@link #nearest}
	 * otherwise, including {@link #MIN_RAIL_AHEAD}.
	 */
	public Hit nearestInAir(float x, float y, float h, float vh, float travelHeading, GrindSegment exclude,
		GrindSegment excludeRising, float snap)
	{
		if (vh > 0f)
			return query(x, y, h, travelHeading, 32f, 90f, exclude, excludeRising, snap);
		Hit hit = query(x, y, h, travelHeading, 28f, 160f, exclude, excludeRising, snap);
		if (excludeRising == null || excludeRising == exclude)
			return hit;
		Hit back = query(x, y, h, travelHeading, BELOW_TOP, ABOVE_TOP, exclude, null, snap);
		if (back == null || back.segment != excludeRising)
			return hit;
		return hit == null || back.segment.distance(x, y, back.t) < hit.segment.distance(x, y, hit.t) ? back : hit;
	}

	/** Closest qualifying segment for a height window [top - below, top + above]; see {@link #nearest}. */
	private Hit query(float x, float y, float h, float travelHeading, float below, float above, GrindSegment exclude,
		GrindSegment exclude2, float snap)
	{
		Hit best = null;
		float bestDist = Float.POSITIVE_INFINITY;
		for (GrindSegment s : near(tile(x), tile(y)))
		{
			if (s == exclude || s == exclude2 || s.length() <= 0f)
				continue;
			float t = s.project(x, y);
			float top = s.topAt(t);
			float d = s.distance(x, y, t);
			if (h >= top - below && h <= top + above && d <= snap && d < bestDist
				&& s.lineAngle(travelHeading) <= MAX_APPROACH + 1e-4f && enoughAhead(s, t, travelHeading))
			{
				best = new Hit(s, t);
				bestDist = d;
			}
		}
		return best;
	}

	/**
	 * True when at least {@link #MIN_RAIL_AHEAD} of {@code s} lies ahead of parameter {@code t} for a skater
	 * travelling along {@code travelHeading}. When the travel is nearly square to the rail
	 * ({@link #AMBIGUOUS_ALONG}) either way along it will do, since the steer picks the direction.
	 */
	public static boolean enoughAhead(GrindSegment s, float t, float travelHeading)
	{
		float along = (float) Math.cos(travelHeading - s.heading());
		float ahead = Math.abs(along) < AMBIGUOUS_ALONG ? Math.max(t, 1f - t) : along > 0f ? 1f - t : t;
		return ahead * s.length() >= MIN_RAIL_AHEAD;
	}

	/**
	 * The segment a grind arriving at (x, y) at height {@code top}, travelling along (dirX, dirY), carries
	 * on to: one end within 24 of (x, y), its top at that end within 24 of {@code top} (the height where the
	 * grind arrives, so sloped pieces compare where they meet) and its direction away from that end within 75
	 * degrees of the travel direction. Skips {@code exclude} (the current segment). The straightest candidate
	 * wins, then the closest; null if none.
	 */
	public GrindSegment connectedAt(float x, float y, float top, float dirX, float dirY, GrindSegment exclude)
	{
		float dl = (float) Math.hypot(dirX, dirY);
		if (dl <= 0f)
			return null;
		float ux = dirX / dl;
		float uy = dirY / dl;
		float minCos = (float) Math.cos((float) Math.toRadians(75)) - 1e-4f;
		GrindSegment best = null;
		float bestCos = Float.NEGATIVE_INFINITY;
		float bestDist = Float.POSITIVE_INFINITY;
		for (GrindSegment s : near(tile(x), tile(y)))
		{
			float d0 = (float) Math.hypot(s.x0 - x, s.y0 - y);
			float d1 = (float) Math.hypot(s.x1 - x, s.y1 - y);
			boolean fromStart = d0 <= d1;
			float d = fromStart ? d0 : d1;
			float cos = ((s.x1 - s.x0) * ux + (s.y1 - s.y0) * uy) * (fromStart ? 1f : -1f) / s.length();
			// heights compared where the pieces meet, so a sloped rail runs on into a flat one at its high end
			if (s != exclude && s.length() > 0f && d <= 24f && Math.abs((fromStart ? s.top0 : s.top1) - top) <= 24f && cos >= minCos
				&& (cos > bestCos + 1e-4f || cos > bestCos - 1e-4f && d < bestDist))
			{
				best = s;
				bestCos = cos;
				bestDist = d;
			}
		}
		return best;
	}

	/**
	 * Unit vector {sin, cos} of the segment's line direction folded into [0, PI), so both orientations of a
	 * segment share a bucket, with float noise (e.g. cos(PI/2)) snapped to an exact 0 so axis-aligned merges
	 * keep exact coordinates.
	 */
	private static float[] axis(GrindSegment s)
	{
		float a = lineAngle(s);
		float sin = (float) Math.sin(a);
		float cos = (float) Math.cos(a);
		return new float[]{Math.abs(sin) < 1e-6f ? 0f : sin, Math.abs(cos) < 1e-6f ? 0f : cos};
	}

	/** Line direction folded into [0, PI). */
	private static float lineAngle(GrindSegment s)
	{
		float a = s.heading();
		if (a < 0f)
			a += (float) Math.PI;
		return a >= (float) Math.PI - 1e-4f ? a - (float) Math.PI : a;
	}
}

package com.gielinorskate.world;

import com.gielinorskate.physics.Angles;

/**
 * A straight grindable edge (rail, fence top, ledge lip). Absolute local coordinates; the top (up-positive) is
 * {@link #top0} at end 0 and {@link #top1} at end 1, interpolated in between, so a handrail can follow a slope.
 */
public final class GrindSegment
{
	public final float x0;
	public final float y0;
	public final float x1;
	public final float y1;
	/** Absolute height of the grindable top at end 0 and end 1, up-positive. */
	public final float top0;
	public final float top1;
	/** Mean of {@link #top0} and {@link #top1} (the top of a flat segment). */
	public final float top;

	/** A flat segment at {@code top}. */
	public GrindSegment(float x0, float y0, float x1, float y1, float top)
	{
		this(x0, y0, x1, y1, top, top);
	}

	public GrindSegment(float x0, float y0, float x1, float y1, float top0, float top1)
	{
		this.x0 = x0;
		this.y0 = y0;
		this.x1 = x1;
		this.y1 = y1;
		this.top0 = top0;
		this.top1 = top1;
		top = (top0 + top1) / 2f;
	}

	public float length()
	{
		return (float) Math.hypot(x1 - x0, y1 - y0);
	}

	/** Height of the top at parameter t (0 = end 0, 1 = end 1). */
	public float topAt(float t)
	{
		return top0 + (top1 - top0) * t;
	}

	/** Rise of the top per unit moved from end 0 toward end 1 (0 for a flat or zero-length segment). */
	public float slope()
	{
		float len = length();
		return len > 0f ? (top1 - top0) / len : 0f;
	}

	/** Parameter of the closest point on the segment to (x, y), clamped to [0, 1]. */
	public float project(float x, float y)
	{
		float dx = x1 - x0;
		float dy = y1 - y0;
		float len2 = dx * dx + dy * dy;
		if (len2 <= 0f)
			return 0f;
		return Math.max(0f, Math.min(1f, ((x - x0) * dx + (y - y0) * dy) / len2));
	}

	/** Horizontal distance from (x, y) to the point at parameter t. */
	float distance(float x, float y, float t)
	{
		return (float) Math.hypot(x - xAt(t), y - yAt(t));
	}

	public float xAt(float t)
	{
		return x0 + (x1 - x0) * t;
	}

	public float yAt(float t)
	{
		return y0 + (y1 - y0) * t;
	}

	/** Heading from end 0 to end 1 (0 = north, clockwise), radians. */
	public float heading()
	{
		return (float) Math.atan2(x1 - x0, y1 - y0);
	}

	/** Angle in [0, PI/2] between a heading and this segment's line, ignoring which way along it. */
	public float lineAngle(float heading)
	{
		float a = Angles.absDiff(heading, heading());
		return Math.min(a, Angles.PI - a);
	}
}

package com.gielinorskate.world;

import com.gielinorskate.Text;
import java.util.*;
import java.util.function.Predicate;
import java.util.function.UnaryOperator;

/**
 * Decides from a scene object's (impostor-resolved) name and actions what it is to the skater. Pure; no client
 * dependency.
 * <p>
 * <b>Grindable</b> ({@link #looksGrindable}): something a skater would grind (fences, rails, benches, tables,
 * crates, low walls...). Matching is per whole word (the name is split on anything that is not a letter),
 * case-insensitive in {@link Locale#ROOT}, and accepts a simple plural ("fences", "benches"), so "Trellis" does
 * not hit "rail" and "Tablet" does not hit "table". Any excluded word (stairs, steps, ladders, doors, trees,
 * bushes, rocks) vetoes the name: "If it looks like it should be grindable you should be able to grind on it.
 * Not stairs." Height is not checked here; the caller limits model height separately
 * ({@link GridCollisionWorld#GRIND_WALL_MIN}..{@link GridCollisionWorld#GRIND_WALL_MAX}), which is what keeps
 * tall walls and city gates out.
 * <p>
 * <b>Ridden through</b> ({@link #passThrough}): vegetation (plants, flowers, bushes, crops, grass, vines...), and
 * doors or gates standing open. Vegetation is a case-insensitive substring match on {@link #VEGETATION_STEMS}, so
 * compounds such as "Rosebush", "Shrubbery" or "Sunflowers" match as well as "Tea bush". A name containing any of
 * {@link #SOLID_PARTS} never matches, whatever its plant word. The choices:
 * <ul>
 * <li>trees and hedges stay solid ("Bushy tree", "Rose hedge"), except tree roots, which are low and were
 * already ridden through ("Tree roots", "Treeroot");</li>
 * <li>furniture and structures made of or holding plants stay solid: planters, pots ("Plant pot", "Potted
 * plant", "Flowerpot"), vases, stalls, tables, desks, chairs, shelves, barrels, crates, statues, signs,
 * trellises and anything called a wall, fence, door or gate ("Ivy-covered wall");</li>
 * <li>words that merely contain a stem stay solid: "Haystack", "Weedkiller", "Rosewood", "Infernal",
 * "Ravine", "Divine", "Vinegar", "Herblore", "Herbiboar", "Ambush", "Corner", "Street", "Shayzien"
 * (a vegetable never reads as a table).</li>
 * </ul>
 * <b>Rocks</b> on the ground. Scattered decorative rocks, pebbles and stones flag their tile as blocked like any
 * object, so the builder used to cut them a box: 25..120 tall with a 40+ footprint made them
 * {@link BlockerSet#LOW}, a step too high to roll over whose four top edges were grind ledges. Now:
 * <ul>
 * <li>a <b>small decorative rock</b> is ridden straight through: a rock by name ({@link #isRockName}), nothing
 * to do on it (no menu action at all, so mining rocks with "Mine", agility rocks with "Climb" and anything
 * searchable stay solid), at most 80 tall (about the skater's knee) and at most 192 (one and a half tiles)
 * across;</li>
 * <li>any other rock still collides as before (a big boulder blocks, a low wide one can be landed on), but no
 * rock's box edges are grind ledges: rocks are not rails (name-grinding already leaves them out).</li>
 * </ul>
 */
public final class ObjectNames
{
	private static final Set<String> GRIND_WORDS = words("grind");

	private static final Set<String> NOT_GRIND_WORDS = words("notgrind");

	/** Lower-case plant stems, matched anywhere in the name. */
	private static final String[] VEGETATION_STEMS = Text.get("on.veg").split(" ");

	/** Lower-case parts that keep a name solid even with a plant stem in it (see the class doc). */
	private static final String[] SOLID_PARTS = Text.get("on.solidparts").split(" ");

	/** Whole words that keep a name solid ("pot" alone, so "Potato" still matches). */
	private static final Set<String> SOLID_WORDS = words("solid");

	/** Whole words naming a rock (simple plurals included). */
	private static final Set<String> ROCK_WORDS = words("rock");

	/** Whole words that make a rock name something built (or a rail): never a decorative rock. */
	private static final Set<String> STRUCTURE_WORDS = words("structure");

	private ObjectNames()
	{
	}

	/** The space-separated words bundled under on.{@code key}. */
	private static Set<String> words(String key)
	{
		return Set.of(Text.get("on." + key).split(" "));
	}

	/**
	 * True when a whole word of the name (lower case, split on anything that is not a letter) is a {@code hit}
	 * and none is a {@code veto}; false for a null name.
	 */
	private static boolean hasWord(String name, Predicate<String> hit, Predicate<String> veto)
	{
		if (name == null)
			return false;
		String[] words = name.toLowerCase(Locale.ROOT).split("[^a-z]+");
		return Arrays.stream(words).noneMatch(veto) && Arrays.stream(words).anyMatch(hit);
	}

	/** The word itself or a simple plural of it ("-s", "-es") is in the set. */
	private static boolean matches(Set<String> set, String word)
	{
		return set.contains(word) || word.endsWith("es") && set.contains(word.substring(0, word.length() - 2))
			|| word.endsWith("s") && set.contains(word.substring(0, word.length() - 1));
	}

	public static boolean looksGrindable(String name)
	{
		return hasWord(name, w -> matches(GRIND_WORDS, w), w -> matches(NOT_GRIND_WORDS, w));
	}

	/** The name is vegetation: it contains a plant stem and nothing that keeps it solid. */
	public static boolean passByName(String name)
	{
		if (name == null)
			return false;
		// "vegetable" holds "table": take it out before looking for furniture
		String n = name.toLowerCase(Locale.ROOT).replace("vegetable", "veg plant");
		// tree roots are low tangles, not trunks: "Tree roots" and "Treeroot" stay ridden through
		return Arrays.stream(VEGETATION_STEMS).anyMatch(n::contains)
			&& Arrays.stream(SOLID_PARTS).noneMatch(p -> n.contains(p) && !("tree".equals(p) && n.contains("root")))
			&& Arrays.stream(n.split("[^a-z]+")).noneMatch(SOLID_WORDS::contains);
	}

	/** A door or gate that currently offers "Close", i.e. stands open. */
	public static boolean isOpenDoor(String name, String[] actions)
	{
		if (name == null || actions == null)
			return false;
		String n = name.toLowerCase(Locale.ROOT);
		return (n.contains("door") || n.contains("gate")) && Arrays.stream(actions).anyMatch("close"::equalsIgnoreCase);
	}

	/**
	 * Ridden through: an open door/gate always; vegetation only when {@code passVegetation} (the "Pass
	 * through vegetation" setting) is on, otherwise it collides like any other object.
	 */
	public static boolean passThrough(String name, String[] actions, boolean passVegetation)
	{
		return isOpenDoor(name, actions) || passVegetation && passByName(name);
	}

	/**
	 * The definition to read the name/actions from: the current impostor when the object has impostors
	 * (varbit-driven objects; may be null when it currently shows nothing), else the definition itself.
	 */
	public static <T> T resolve(T def, Predicate<T> hasImpostors, UnaryOperator<T> impostor)
	{
		return def == null || !hasImpostors.test(def) ? def : impostor.apply(def);
	}

	/** The name is a rock, pebble, stone or boulder (whole words), and not something built from stone. */
	public static boolean isRockName(String name)
	{
		return hasWord(name, ROCK_WORDS::contains, STRUCTURE_WORDS::contains);
	}

	/**
	 * A small decorative rock, ridden through (see the class doc): a rock by name with no menu action (Mine,
	 * Prospect, Climb, Search...), its model at most 80 tall and its footprint {@code ext} = {minX, maxX, minZ,
	 * maxZ} (model units; null when there is no model, which never counts) at most 192 on its longer side.
	 */
	public static boolean isSmallDecorativeRock(String name, String[] actions, float height, float[] ext)
	{
		return ext != null && isRockName(name)
			&& (actions == null || Arrays.stream(actions).allMatch(a -> a == null || a.trim().isEmpty()))
			&& height <= 80f && Math.max(ext[1] - ext[0], ext[3] - ext[2]) <= 192f;
	}
}

package com.gielinorskate.world;

import java.util.ArrayList;
import java.util.List;

/**
 * What a scene object's model footprint becomes for the skater. Pure; no client dependency.
 * <p>
 * Blockers: a {@link BlockerSet#SOLID} box, a {@link BlockerSet#LOW} box you can land on, or
 * {@link BlockerSet#PASS} clutter you ride straight through ({@link #classify}), cut from the model slice at
 * skater height ({@link #sliceExtents}).
 * <p>
 * Grinds: model space x maps to local x and model z to local y, rotated by the object's orientation in JAU
 * (0..2047, 2048 = a full turn) the way the client draws it: x' = x cos + z sin, y' = z cos - x sin.
 * <ul>
 * <li>A long object (shorter extent below 0.75 of the longer, e.g. a fence or railing) gives one rail along
 * its long axis through the middle of the model, as long as that extent: fences are drawn through the middle
 * of their tile, not on its edges.</li>
 * <li>A square-ish object (extents within 25% of each other: bench, crate, table) gives the four edges of its
 * rotated bounding rectangle, so ledges sit on the object's real edges rather than the tile's.</li>
 * </ul>
 */
public final class ObjectShapes
{
	/** Vertices up to this height (local units above the model base) make the footprint: the skater's height. */
	public static final float SLICE_HEIGHT = 90f;

	private ObjectShapes()
	{
	}

	/**
	 * Kind of a blocker cut from a model: PASS when {@code passByName} (plants, open doors), for anything
	 * that can be stepped over (height 24 or lower: the physics max step up) and for thin slices (posts, stalks:
	 * shorter side under 30); LOW for up to 120 tall (as full-tile platforms) with a shorter side of at least 40
	 * to stand on; SOLID otherwise.
	 */
	public static byte classify(boolean passByName, float height, float sliceMinSide)
	{
		return passByName || height <= 24f || sliceMinSide < 30f ? BlockerSet.PASS
			: height <= GridCollisionWorld.PLATFORM_MAX_HEIGHT && sliceMinSide >= 40f ? BlockerSet.LOW : BlockerSet.SOLID;
	}

	/**
	 * {minX, maxX, minZ, maxZ} of the first {@code count} model vertices at most {@code maxHeight} above the
	 * base (RuneLite model y is negative-up, so height = -y), or null when none are that low.
	 */
	public static float[] sliceExtents(float[] xs, float[] ys, float[] zs, int count, float maxHeight)
	{
		float[] e = {Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY};
		boolean any = false;
		for (int i = 0; i < count; i++)
		{
			if (-ys[i] <= maxHeight)
			{
				any = true;
				e[0] = Math.min(e[0], xs[i]);
				e[1] = Math.max(e[1], xs[i]);
				e[2] = Math.min(e[2], zs[i]);
				e[3] = Math.max(e[3], zs[i]);
			}
		}
		return any ? e : null;
	}

	/** Shorter side of extents {minX, maxX, minZ, maxZ}. */
	public static float minSide(float[] ext)
	{
		return Math.min(ext[1] - ext[0], ext[3] - ext[2]);
	}

	/**
	 * Oriented box {cx, cy, hx, hy, cos, sin} for extents {minX, maxX, minZ, maxZ} of an object at local
	 * (originX, originY) drawn with the given orientation (JAU), using the grind rotation, so the model x axis
	 * (hx) runs along (cos, -sin) of the angle. Half extents below {@code minHalf} are inflated to it.
	 */
	public static float[] box(float originX, float originY, float[] ext, int orientation, float minHalf)
	{
		float[] c = centre(originX, originY, ext, orientation);
		float a = radians(orientation);
		return new float[]{c[0], c[1], Math.max(minHalf, (ext[1] - ext[0]) / 2f), Math.max(minHalf, (ext[3] - ext[2]) / 2f),
			(float) Math.cos(a), (float) -Math.sin(a)};
	}

	/** Local (x, y) of the centre of the extents, for an object at (originX, originY). */
	public static float[] centre(float originX, float originY, float[] ext, int orientation)
	{
		return toLocal(originX, originY, (ext[0] + ext[1]) / 2f, (ext[2] + ext[3]) / 2f, orientation);
	}

	/**
	 * The grind segments (top 0, the caller sets it) of an object at local (originX, originY) whose model has
	 * extents {@code ext} = {minX, maxX, minZ, maxZ}.
	 */
	public static List<GrindSegment> segments(float originX, float originY, float[] ext, int orientation)
	{
		float lenX = ext[1] - ext[0];
		float lenZ = ext[3] - ext[2];
		float longer = Math.max(lenX, lenZ);
		float cx = (ext[0] + ext[1]) / 2f;
		float cz = (ext[2] + ext[3]) / 2f;
		// model-space points {x, z, x, z, ...} joined in order
		float[] p = longer <= 0f ? new float[0]
			: Math.min(lenX, lenZ) >= 0.75f * longer
			? new float[]{ext[0], ext[2], ext[1], ext[2], ext[1], ext[3], ext[0], ext[3], ext[0], ext[2]}
			: lenX >= lenZ ? new float[]{ext[0], cz, ext[1], cz} : new float[]{cx, ext[2], cx, ext[3]};
		List<GrindSegment> out = new ArrayList<>();
		for (int i = 0; i + 3 < p.length; i += 2)
		{
			float[] a = toLocal(originX, originY, p[i], p[i + 1], orientation);
			float[] b = toLocal(originX, originY, p[i + 2], p[i + 3], orientation);
			out.add(new GrindSegment(a[0], a[1], b[0], b[1], 0f));
		}
		return out;
	}

	/** An orientation in JAU (2048 to a full turn) in radians. */
	private static float radians(int orientation)
	{
		return (orientation & 2047) * (float) (2 * Math.PI / 2048);
	}

	private static float[] toLocal(float ox, float oy, float mx, float mz, int orientation)
	{
		float a = radians(orientation);
		float sin = (float) Math.sin(a);
		float cos = (float) Math.cos(a);
		return new float[]{ox + mx * cos + mz * sin, oy + mz * cos - mx * sin};
	}
}

package com.gielinorskate.world;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.*;
import net.runelite.api.coords.LocalPoint;

/**
 * Converts the loaded scene into a GridCollisionWorld, including its tight object boxes
 * ({@link GridCollisionWorld#getBlockers()}) and grind map ({@link GridCollisionWorld#getGrinds()}).
 * <p>
 * Collision: the flags decide what is solid, the models decide its shape.
 * <ul>
 * <li>Wall edges block along the tile edge, as tall as the wall object's own model (not the tallest
 * model on the tile, so a lamp next to a fence doesn't raise the fence).</li>
 * <li>Tiles the flags block whole (objects, floor decorations) get one box per object on them, cut from
 * the model's vertices up to skater height ({@link ObjectShapes#SLICE_HEIGHT}, so a tree is its trunk)
 * and turned by its model orientation; its kind follows {@link ObjectShapes#classify} (steppable and
 * thin things are ridden through, low wide things are landable, the rest is solid). Such a tile with no
 * usable model gets a 96 x 96 fallback box. Water (BLOCK_MOVEMENT_FLOOR) stays a whole-tile wall.</li>
 * <li>Vegetation, and doors or gates standing open (walls included, both sides of their edge), are ridden through
 * ({@link ObjectNames}, names resolved through impostors). So are small decorative rocks and pebbles; a bigger rock
 * still collides but its box edges are never grind ledges ({@link ObjectNames}).</li>
 * <li>Every name-grindable object gets a landable box whatever the flags say, so a missed grind lands on
 * it rather than inside it ({@link GridCollisionWorld#addGrindableBlocker}).</li>
 * </ul>
 * Grinds come from two sources, merged together:
 * <ul>
 * <li>collision: low wall blockers, low full-tile platforms and LOW box edges (see
 * {@link GridCollisionWorld#rebuildGrinds()});</li>
 * <li>names: any wall, game, decorative or ground object whose (impostor-resolved) name
 * {@link ObjectNames#looksGrindable looks grindable} and whose model height is in
 * [{@link GridCollisionWorld#GRIND_WALL_MIN}, {@link GridCollisionWorld#GRIND_WALL_MAX}]. Walls give a rail
 * along the tile edges their orientation covers (wall fences are drawn there); game, decorative and ground
 * objects give a shape from their model's extents ({@link ObjectShapes}): a centreline rail along a
 * long object such as a fence piece (drawn through the middle of its tile), or the edges of a square-ish
 * object's own bounds. The top is the ground plus the model height.</li>
 * </ul>
 * Terrain steps (stairs, hills) are deliberately not grindable. Call on the client thread.
 */
public final class SceneCollisionBuilder
{
	/** The collision flags blocking each side, in side order (north, east, south, west). */
	private static final int[] SIDE_FLAGS = {CollisionDataFlag.BLOCK_MOVEMENT_NORTH, CollisionDataFlag.BLOCK_MOVEMENT_EAST,
		CollisionDataFlag.BLOCK_MOVEMENT_SOUTH, CollisionDataFlag.BLOCK_MOVEMENT_WEST};

	private final Client client;
	private final GridCollisionWorld world;
	/**
	 * When true (the default "Pass through vegetation" comfort setting), plants and crops are ridden straight
	 * through; when false they are classified like any other object (solid, low or thin-clutter pass, by
	 * {@link ObjectShapes#classify}). Open doors/gates always pass through either way.
	 */
	private final boolean passVegetation;
	/** Tiles whose whole-tile block should be replaced by the boxes of the objects on them. */
	final boolean[][] shapeable;
	/** Shapeable tiles that got a usable model. */
	final boolean[][] modelled;

	SceneCollisionBuilder(Client client, GridCollisionWorld world, boolean passVegetation)
	{
		this.client = client;
		this.world = world;
		this.passVegetation = passVegetation;
		shapeable = new boolean[world.size()][world.size()];
		modelled = new boolean[world.size()][world.size()];
	}

	public static GridCollisionWorld build(Client client, WorldView wv, int plane, boolean passVegetation)
	{
		Tile[][] tiles = wv.getScene().getTiles()[plane];
		CollisionData[] maps = wv.getCollisionMaps();
		int[][] flags = maps == null || maps[plane] == null ? null : maps[plane].getFlags();
		int size = flags == null ? tiles.length : Math.min(tiles.length, flags.length);
		GridCollisionWorld world = new GridCollisionWorld(size);
		applyTerrain(world, wv.getTileHeights(), wv.getTileSettings(), plane);
		SceneCollisionBuilder b = new SceneCollisionBuilder(client, world, passVegetation);
		if (flags != null)
		{
			// the client's collision maps block tile 0 and tiles flags.length - 5 and up on both axes: the loaded
			// area's edge
			world.setLoadedTiles(1, flags.length - 5);
			b.addCollision(tiles, flags);
		}
		b.addObjects(tiles);
		for (int tx = 0; tx < size; tx++)
		{
			for (int ty = 0; ty < size; ty++)
			{
				if (b.shapeable[tx][ty] && !b.modelled[tx][ty])
					world.addFallbackBlocker(tx, ty);
			}
		}
		world.rebuildBlockers();
		world.rebuildGrinds();
		return world;
	}

	/**
	 * Fills the world's terrain from the scene heightmap {@code heights} [plane][x][y] (RuneLite z, down
	 * positive, size + 1 corners a side) as {@link Perspective#getTileHeight} reads it: a tile flagged as a
	 * bridge ({@code settings[1][x][y] & 2}) takes its heights from the plane above.
	 */
	static void applyTerrain(GridCollisionWorld world, int[][][] heights, byte[][][] settings, int plane)
	{
		// per tile, not per shared corner: a bridge deck's edge corners would otherwise take the river-bed
		// heights of the river tiles beside it (and those the deck's), sloping the deck into the river
		for (int tx = 0; tx < world.size(); tx++)
		{
			for (int ty = 0; ty < world.size(); ty++)
			{
				int[][] hp = heights[effectivePlane(settings, plane, tx, ty)];
				world.setTileCorners(tx, ty, -at(hp, tx, ty), -at(hp, tx + 1, ty), -at(hp, tx, ty + 1),
					-at(hp, tx + 1, ty + 1));
			}
		}
	}

	/** Heightmap corner (cx, cy), clamped to the array. */
	private static int at(int[][] h, int cx, int cy)
	{
		int[] col = h[Math.min(cx, h.length - 1)];
		return col[Math.min(cy, col.length - 1)];
	}

	/** The plane whose heights tile (tx, ty) uses: the one above for a bridge tile, as Perspective does. */
	static int effectivePlane(byte[][][] settings, int plane, int tx, int ty)
	{
		// the bridge flag lives on plane 1's settings
		return plane < 3 && settings != null
			&& (settings[1][tx][ty] & Constants.TILE_FLAG_BRIDGE) == Constants.TILE_FLAG_BRIDGE ? plane + 1 : plane;
	}

	private void addCollision(Tile[][] tiles, int[][] flags)
	{
		List<int[]> open = new ArrayList<>();
		for (int tx = 0; tx < world.size(); tx++)
		{
			for (int ty = 0; ty < world.size(); ty++)
			{
				int f = flags[tx][ty];
				Tile tile = tiles[tx][ty];
				WallObject wall = tile == null ? null : tile.getWallObject();
				boolean pass = wall != null && passThrough(definition(wall.getId()));
				if (pass)
					open.add(new int[]{tx, ty, wallSides(wall.getOrientationA() | wall.getOrientationB())});
				int bits = 0;
				for (int i = 0; i < 4; i++)
					bits |= (f & SIDE_FLAGS[i]) != 0 ? 1 << i : 0;
				boolean water = (f & CollisionDataFlag.BLOCK_MOVEMENT_FLOOR) != 0;
				if ((f & (CollisionDataFlag.BLOCK_MOVEMENT_OBJECT | CollisionDataFlag.BLOCK_MOVEMENT_FLOOR
					| CollisionDataFlag.BLOCK_MOVEMENT_FLOOR_DECORATION)) != 0)
				{
					bits |= GridCollisionWorld.FULL;
					shapeable[tx][ty] = !water;
				}
				if (bits != 0)
				{
					world.setTile(tx, ty, bits, blockerHeight(tile, water));
					// an open door or gate swung against this edge is ridden through (height 0 never blocks);
					// other edges are as tall as the wall object's own model (curbs 16-31 keep their real
					// height), or keep the tile's blocker height when the tile has no wall model
					float wallHeight = pass || wall == null ? 0f : height(wall);
					if (pass || wallHeight > 0f)
						world.setWallHeight(tx, ty, wallHeight);
				}
			}
		}
		// The game flags a wall on both tiles it separates; the neighbour's mirrored flag still blocked at the
		// neighbour's own height after the wall's tile was zeroed. Open both sides, once every tile is set.
		open.forEach(o -> world.openWallEdges(o[0], o[1], o[2]));
	}

	/**
	 * Boxes for the objects on shapeable tiles, and grinds plus landable boxes for every object that looks
	 * grindable by name (see the class doc). Marks the shapeable tiles that got a usable model.
	 */
	private void addObjects(Tile[][] tiles)
	{
		for (int tx = 0; tx < world.size(); tx++)
		{
			for (int ty = 0; ty < world.size(); ty++)
			{
				Tile tile = tiles[tx][ty];
				if (tile == null)
					continue;
				WallObject wall = tile.getWallObject();
				float wallHeight = wall == null ? 0f : height(wall);
				if (wall != null && grindable(definition(wall.getId()), wallHeight))
				{
					int sides = wallSides(wall.getOrientationA() | wall.getOrientationB());
					for (int i = 0; i < 4; i++)
					{
						if ((sides & 1 << i) != 0)
							world.addEdgeGrind(tx, ty, 1 << i, wallHeight);
					}
				}
				GameObject[] objects = tile.getGameObjects();
				for (GameObject o : objects == null ? new GameObject[0] : objects)
				{
					Point min = o == null ? null : o.getSceneMinLocation();
					Point max = o == null ? null : o.getSceneMaxLocation();
					// a multi-tile object is listed on every tile it covers: handle it once, from its min tile.
					// The model's vertices already carry the 90-degree rotation from the object's config; the
					// client applies only the model orientation (e.g. 256 for diagonal pieces) when drawing,
					// so that is the angle the extents are turned by
					if (min != null && max != null && min.getX() == tx && min.getY() == ty)
						addObject(o, model(o.getRenderable()), 0, 0, o.getModelOrientation(), tx, ty, max.getX(), max.getY(),
							true);
				}
				DecorativeObject deco = tile.getDecorativeObject();
				if (deco != null)
				{
					Model m1 = model(deco.getRenderable());
					Model m2 = model(deco.getRenderable2());
					boolean second = height(m2) > height(m1);
					addObject(deco, second ? m2 : m1, second ? deco.getXOffset2() : deco.getXOffset(),
						second ? deco.getYOffset2() : deco.getYOffset(), 0, tx, ty, tx, ty, false);
				}
				GroundObject ground = tile.getGroundObject();
				if (ground != null)
					addObject(ground, model(ground.getRenderable()), 0, 0, 0, tx, ty, tx, ty, true);
			}
		}
	}

	/**
	 * One game/decorative/ground object drawn with model m at its local location plus (ox, oy) covering tiles
	 * [minTx..maxTx] x [minTy..maxTy]: a grind and landable box when it looks grindable, otherwise a
	 * classified box when it stands on a shapeable tile. A ridden-through object frees its tiles even
	 * without a usable model (an animated plant), instead of leaving them to the solid fallback box.
	 */
	private void addObject(TileObject o, Model m, int ox, int oy, int orientation, int minTx, int minTy, int maxTx,
		int maxTy, boolean canFreeTile)
	{
		ObjectComposition def = definition(o.getId());
		LocalPoint lp = o.getLocalLocation();
		String name = def == null ? null : def.getName();
		boolean pass = passThrough(def);
		float[] ext = m == null || lp == null ? null : extents(m, Float.POSITIVE_INFINITY);
		if (ext == null)
		{
			if (pass && canFreeTile)
				shapeTiles(minTx, minTy, maxTx, maxTy, true);
			return;
		}
		float x = lp.getX() + ox;
		float y = lp.getY() + oy;
		float h = height(m);
		// small decorative rocks and pebbles are ridden through; no rock's box edges are grind ledges (ObjectNames)
		boolean rock = ObjectNames.isRockName(name);
		pass |= rock && ObjectNames.isSmallDecorativeRock(name, def.getActions(), h, ext);
		// only objects that can themselves be the tile's blocker (game and ground objects) decide its shape; a wall
		// decoration (painting, sign) on a blocked tile must not free a model-less blocker sharing that tile
		boolean onShapeable = shapeTiles(minTx, minTy, maxTx, maxTy, canFreeTile);
		if (!pass && grindable(def, h))
		{
			world.addObjectGrind(x, y, ext, orientation, h);
			world.addGrindableBlocker(x, y, ext, orientation, h);
		}
		else if (onShapeable)
		{
			float[] slice = extents(m, ObjectShapes.SLICE_HEIGHT);
			if (slice != null)
				world.addObjectBlocker(x, y, slice, orientation, h, pass, !rock);
		}
	}

	/**
	 * True when any tile in the range is shapeable. When {@code mark}, also marks those tiles modelled, and
	 * shaped in the world (they then collide only through their objects' boxes, not as whole tiles).
	 */
	boolean shapeTiles(int minTx, int minTy, int maxTx, int maxTy, boolean mark)
	{
		boolean any = false;
		for (int tx = Math.max(0, minTx); tx <= Math.min(shapeable.length - 1, maxTx); tx++)
		{
			for (int ty = Math.max(0, minTy); ty <= Math.min(shapeable.length - 1, maxTy); ty++)
			{
				if (shapeable[tx][ty])
				{
					any = true;
					if (mark)
					{
						modelled[tx][ty] = true;
						world.markShaped(tx, ty);
					}
				}
			}
		}
		return any;
	}

	/** Height in the grindable range and the (impostor-resolved) definition's name looks grindable. */
	private static boolean grindable(ObjectComposition def, float height)
	{
		return height >= GridCollisionWorld.GRIND_WALL_MIN && height <= GridCollisionWorld.GRIND_WALL_MAX && def != null
			&& ObjectNames.looksGrindable(def.getName());
	}

	/**
	 * Ridden through by name: a door/gate standing open always, and a plant or crop only when
	 * {@link #passVegetation} is on ({@link ObjectNames}).
	 */
	private boolean passThrough(ObjectComposition def)
	{
		return def != null && ObjectNames.passThrough(def.getName(), def.getActions(), passVegetation);
	}

	/** The object's definition, resolved to its current impostor for varbit-driven objects (may be null). */
	private ObjectComposition definition(int id)
	{
		return ObjectNames.resolve(client.getObjectDefinition(id), d -> d.getImpostorIds() != null,
			ObjectComposition::getImpostor);
	}

	/**
	 * WallObject orientation bits (1 = west, 2 = north, 4 = east, 8 = south) to GridCollisionWorld sides.
	 * Diagonal bits (16/32/64/128) are skipped: diagonal wall pieces are corner posts, and full diagonal
	 * fences are GameObjects, which get their tile perimeter instead.
	 */
	static int wallSides(int orientation)
	{
		return orientation >> 1 & 7 | (orientation & 1) << 3;
	}

	/** Whole-tile blocker height (used for water and unshaped tiles): the tallest wall or game object model. */
	private static float blockerHeight(Tile tile, boolean floorBlock)
	{
		if (floorBlock || tile == null)
			return 400f;
		WallObject wall = tile.getWallObject();
		float best = wall == null ? -1f : height(wall);
		GameObject[] objects = tile.getGameObjects();
		for (GameObject o : objects == null ? new GameObject[0] : objects)
		{
			if (o != null)
				best = Math.max(best, height(o.getRenderable()));
		}
		// a tile with no model blocks 400 tall, a low model at least 32
		return best < 0 ? 400f : Math.max(32f, best);
	}

	/** The taller of a wall object's two models, or -1 with neither. */
	private static float height(WallObject wall)
	{
		return Math.max(height(wall.getRenderable1()), height(wall.getRenderable2()));
	}

	private static float height(Renderable r)
	{
		return height(model(r));
	}

	private static Model model(Renderable r)
	{
		return r == null || r instanceof Model ? (Model) r : r.getModel();
	}

	private static float height(Model m)
	{
		if (m == null)
			return -1f;
		m.calculateBoundsCylinder();
		return m.getModelHeight();
	}

	/** Model-space {minX, maxX, minZ, maxZ} of the model's vertices up to {@code maxHeight}, or null. */
	private static float[] extents(Model m, float maxHeight)
	{
		return ObjectShapes.sliceExtents(m.getVerticesX(), m.getVerticesY(), m.getVerticesZ(), m.getVerticesCount(),
			maxHeight);
	}
}

package com.gielinorskate;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.junit.Test;

/**
 * Checks the config interface's source text (no reflection): saved keys never change, every visible item has a
 * section and hidden ones don't.
 */
public class GielinorSkateConfigTest
{
	/** Keys saved before the Q2 settings pass: renaming any of them would reset players' settings. */
	private static final Set<String> EXISTING_KEYS = new HashSet<>(Arrays.asList(
		"toggleKey", "cameraZoom", "speedScale", "popScale", "cameraHeight", "manualKey", "flickSensitivity",
		"smoothMotion", "passThroughVegetation", "forgivingCollisions", "allowPvpAreas", "shareWithParty",
		"showPartySkaters", "soundEffects", "soundVolume", "particleEffects", "funnyBailMessages"));

	/** The annotation body runs up to the ')' that ends its line and is followed by the method declaration. */
	private static final Pattern ITEM = Pattern.compile(
		"@ConfigItem\\s*\\((.*?)\\)\\s*\\n\\s*(?:default\\s|[A-Za-z<>\\[\\].]+\\s+\\w+\\s*\\()", Pattern.DOTALL);
	private static final Pattern KEY = Pattern.compile("keyName\\s*=\\s*\"([^\"]+)\"");

	/** Each @ConfigItem's annotation body, from the source file. */
	private static List<String> items() throws IOException
	{
		String src = new String(Files.readAllBytes(
			Paths.get("src/main/java/com/gielinorskate/GielinorSkateConfig.java")), StandardCharsets.UTF_8);
		List<String> bodies = new ArrayList<>();
		Matcher m = ITEM.matcher(src);
		while (m.find())
		{
			bodies.add(m.group(1));
		}
		// every @ConfigItem must be parsed, or a key could slip past the checks unnoticed
		int declared = src.split("@ConfigItem", -1).length - 1;
		assertEquals("parsed config items", declared, bodies.size());
		return bodies;
	}

	private static String key(String body)
	{
		Matcher m = KEY.matcher(body);
		return m.find() ? m.group(1) : "";
	}

	@Test
	public void everyExistingKeyIsKept() throws IOException
	{
		Set<String> keys = new TreeSet<>();
		for (String body : items())
		{
