package com.gielinorskate;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;

public class TextTest
{
	/** A Text lookup with a literal key, or a literal key prefix followed by "+". */
	private static final Pattern LOOKUP = Pattern.compile(
		"Text\\.(?:get|lines|floats|ints)\\(\\s*\"([^\"]+)\"\\s*(\\+)?");

	private static String sources() throws IOException
	{
		Path root = Paths.get("src", "main", "java");
		try (Stream<Path> files = Files.walk(root))
		{
			List<Path> java = files.filter(p -> p.toString().endsWith(".java")).collect(Collectors.toList());
			StringBuilder all = new StringBuilder();
			for (Path p : java)
			{
				all.append(new String(Files.readAllBytes(p), StandardCharsets.UTF_8)).append('\n');
			}
			return all.toString();
		}
	}

	private static Set<String> bundledKeys() throws IOException
	{
		Set<String> keys = new TreeSet<>();
		for (String name : Text.FILES)
		{
			Properties p = new Properties();
			try (Reader r = new InputStreamReader(Text.class.getResourceAsStream("text/" + name + ".properties"),
				StandardCharsets.UTF_8))
			{
				p.load(r);
			}
			for (String k : p.stringPropertyNames())
			{
				assertTrue("key " + k + " is in more than one file", keys.add(k));
			}
		}
		return keys;
	}

	@Test
	public void everyLiteralKeyTheCodeLooksUpIsBundled() throws IOException
	{
		Set<String> keys = bundledKeys();
		Matcher m = LOOKUP.matcher(sources());
		List<String> missing = new ArrayList<>();
		while (m.find())
		{
			String key = m.group(1);
			boolean found = m.group(2) == null ? keys.contains(key) : keys.stream().anyMatch(k -> k.startsWith(key));
			if (!found)
			{
				missing.add(key);
			}
		}
		assertEquals("keys looked up but not bundled", List.of(), missing);
	}

	@Test
	public void everyBundledKeyIsLookedUp() throws IOException
	{
		Set<String> literal = new TreeSet<>();
		List<String> prefixes = new ArrayList<>();
		Matcher m = LOOKUP.matcher(sources());
		while (m.find())
		{
			(m.group(2) == null ? literal : prefixes).add(m.group(1));
		}
		List<String> unused = bundledKeys().stream()
			.filter(k -> !literal.contains(k) && prefixes.stream().noneMatch(k::startsWith))
			.collect(Collectors.toList());
		assertEquals("bundled keys nothing looks up", List.of(), unused);
	}

	@Test
	public void everyBundledValueLoads() throws IOException
	{
		for (String k : bundledKeys())
		{
			assertTrue(k, Text.has(k));
			assertTrue(k, !Text.get(k).isEmpty());
		}
	}
}

package com.gielinorskate.camera;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

/** The board camera turned by hand, and its ease back behind the skater once the stick is let go. */
public class BoardOrbitTest
{
	private static final float DT = 1f / 50f;

	@Test
	public void theTurnHoldsWhileTheStickMovesAndGoesAfterIdle()
	{
		BoardOrbit o = new BoardOrbit();
		assertEquals(0f, o.offset(), 0f);
		o.turn(0.5f);
		o.update(DT);
		assertEquals(0.5f, o.offset(), 1e-6f);
		// held still just short of the idle time: still turned
		for (int i = 0; i < Math.round(BoardOrbit.IDLE_SECONDS / DT) - 3; i++)
		{
			o.update(DT);
		}
		assertEquals(0.5f, o.offset(), 1e-6f);
		// a new turn restarts the idle time
		o.turn(0.25f);
		for (int i = 0; i < 50; i++)
		{
			o.update(DT);
		}
		assertEquals(0.75f, o.offset(), 1e-6f);
		for (int i = 0; i < Math.round(BoardOrbit.IDLE_SECONDS / DT); i++)
		{
			o.update(DT);
		}
		assertEquals(0f, o.offset(), 0f);
	}

	@Test
	public void resetDropsTheTurn()
	{
		BoardOrbit o = new BoardOrbit();
		o.turn(1f);
		o.reset();
		assertEquals(0f, o.offset(), 0f);
		o.turn(0f);
		o.update(DT);
		assertEquals(0f, o.offset(), 0f);
	}

	@Test
	public void theChaseCameraEasesBackBehindTheSkater()
	{
		// as the session drives it: the stick turns the rig and the offset, the rig sits behind heading + offset
		CameraRig rig = new CameraRig();
		BoardOrbit o = new BoardOrbit();
		float heading = 0f;
		rig.reset(0, 0, 0, heading);
		o.turn(1f);
		rig.orbit(1f);
		for (int i = 0; i < 50; i++)
		{
			o.update(DT);
			rig.update(0, 0, 0, heading + o.offset(), 300f, SkaterState.ROLLING, 0f, DT);
		}
		assertEquals("held where the stick put it", 1f, rig.getYaw(), 1e-3f);
		float last = rig.getYaw();
		boolean eased = false;
		for (int i = 0; i < 150; i++)
		{
			o.update(DT);
			rig.update(0, 0, 0, heading + o.offset(), 300f, SkaterState.ROLLING, 0f, DT);
			float step = Math.abs(Angles.wrap(rig.getYaw() - last));
			assertTrue("no snap: " + step, step <= CameraRig.MAX_YAW_RATE * DT + 1e-4f);
			eased |= step > 0f && step < 0.5f;
			last = rig.getYaw();
		}
		assertTrue(eased);
		assertEquals("back behind the skater", heading, rig.getYaw(), 1e-2f);
	}
}

package com.gielinorskate.camera;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

/** The landing camera kick: a dip scaled by landing speed, and a short jolt after big airs. */
public class CameraKickTest
{
	private static final float DT = 1f / 50f;

	@Test
	public void dipScalesFromEightToThirtyWithLandingSpeed()
	{
		assertEquals(8f, CameraRig.landingDip(0f), 1e-4f);
		assertEquals(8f, CameraRig.landingDip(500f), 1e-4f);
		// a flat ollie: 8 + 22 * 320 / 1200
		assertEquals(13.87f, CameraRig.landingDip(820f), 0.01f);
		assertEquals(19f, CameraRig.landingDip(1100f), 1e-4f);
		assertEquals(30f, CameraRig.landingDip(1700f), 1e-4f);
		assertEquals(30f, CameraRig.landingDip(5000f), 1e-4f);
	}

	/** Settles on the ground, falls at {@code fallSpeed} for five frames, lands; returns the dip seen. */
	private static float dipAfterFall(float fallSpeed, float airtime)
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		for (int i = 0; i < 50; i++)
		{
			rig.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0f, DT);
		}
		float settled = rig.getFocusHeight();
		// a short stretch of falling, ending at the ground
		float h = fallSpeed * DT * 5;
		for (int i = 0; i < 5; i++)
		{
			h -= fallSpeed * DT;
			rig.update(0, 0, h, 0f, 0, SkaterState.AIRBORNE, 0f, DT);
		}
		float before = rig.getFocusHeight();
		rig.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, airtime, DT);
		// the focus height without the dip would have kept settling toward 0 from 'before'
		float noDip = before + (settled - before) * (1f - (float) Math.exp(-12f * DT));
		return noDip - rig.getFocusHeight();
	}

	@Test
	public void harderLandingsDipFurther()
	{
		float soft = dipAfterFall(600f, 0.5f);
		float hard = dipAfterFall(1600f, 0.5f);
		assertTrue("soft " + soft + " hard " + hard, hard > soft + 10f);
		// the dip decays at rate 6 within the landing frame: 1 - (1 - e^(-0.12)) = e^(-0.12) of it remains
		float decay = (float) Math.exp(-6f * DT);
		assertEquals(CameraRig.landingDip(1600f) * decay, hard, 0.6f);
	}

	@Test
	public void unseenFallsGuessTheSpeedFromAirtime()
	{
		// no airborne updates seen: 0.9 s of flat-ground air lands at 2000 * 0.9 / 2 = 900 u/s
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		float settled = rig.getFocusHeight();
		rig.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0.9f, DT);
		float decay = (float) Math.exp(-6f * DT);
		assertEquals(CameraRig.landingDip(900f) * decay, settled - rig.getFocusHeight(), 0.01f);
	}

	@Test
	public void onlyBigAirsJolt()
	{
		CameraRig small = new CameraRig();
		small.reset(0, 0, 0, 0f);
		small.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0.9f, DT);
		for (int i = 0; i < 10; i++)
		{
			small.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0f, DT);
			assertEquals(0f, small.getFocusX(), 1e-6f);
		}

		CameraRig big = new CameraRig();
		big.reset(0, 0, 0, 0f);
		big.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 1.2f, DT);
		float maxSide = 0f;
		for (int i = 0; i < 10; i++)
		{
			big.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0f, DT);
			maxSide = Math.max(maxSide, Math.abs(big.getFocusX()));
		}
		assertTrue("jolts sideways " + maxSide, maxSide > 0.3f && maxSide <= CameraRig.JITTER_AMPLITUDE);
	}

	@Test
	public void joltDiesOutWithinHalfASecond()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		rig.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 1.5f, DT);
		for (int i = 0; i < 25; i++)
		{
			rig.update(0, 0, 0, 0f, 0, SkaterState.ROLLING, 0f, DT);
		}
		assertEquals(0f, rig.getFocusX(), 0f);
		assertEquals(0f, rig.getFocusY(), 0f);
	}

	@Test
	public void sidewaysJoltIsAcrossTheView()
	{
		// looking east (yaw PI/2), across the view is north-south: x stays put
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, (float) Math.PI / 2);
		rig.update(0, 0, 0, (float) Math.PI / 2, 0, SkaterState.ROLLING, 1.5f, DT);
		float maxY = 0f;
		for (int i = 0; i < 10; i++)
		{
			rig.update(0, 0, 0, (float) Math.PI / 2, 0, SkaterState.ROLLING, 0f, DT);
			assertEquals(0f, rig.getFocusX(), 1e-4f);
			maxY = Math.max(maxY, Math.abs(rig.getFocusY()));
		}
		assertTrue(maxY > 0.3f);
	}
}

package com.gielinorskate.camera;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

public class CameraRigTest
{
	private static final float DT = 1f / 50f;

	private static void run(CameraRig rig, float seconds, float x, float y, float h, float travel, float speed,
		SkaterState state)
	{
		for (int i = 0; i < Math.round(seconds / DT); i++)
		{
			rig.update(x, y, h, travel, speed, state, 0f, DT);
		}
	}

	@Test
	public void yawUsesFourteenBitCounterClockwiseUnits()
	{
		// RuneLite camera yaw is JAU14 (16384 per turn); 0 looks north and yaw grows counter-clockwise
		assertEquals(0, CameraRig.yawJau14(0f));
		assertEquals(12288, CameraRig.yawJau14(Angles.PI / 2)); // east
		assertEquals(8192, CameraRig.yawJau14(Angles.PI));      // south
		assertEquals(4096, CameraRig.yawJau14(-Angles.PI / 2)); // west
	}

	@Test
	public void swingsBehindTheDirectionOfTravelWithLag()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		rig.update(0, 0, 0, Angles.PI / 2, 800, SkaterState.ROLLING, 0f, DT);
		float afterOneFrame = rig.getYaw();
		assertTrue("lags behind", afterOneFrame > 0f && afterOneFrame < 0.3f);
		run(rig, 2f, 0, 0, 0, Angles.PI / 2, 800, SkaterState.ROLLING);
		assertEquals(Angles.PI / 2, rig.getYaw(), 0.01f);
	}

	@Test
	public void followsTheBoardTurningInPlace()
	{
		// the heading passed in is now the board's camera heading (not the noisy roll direction), so the
		// camera follows a standstill pivot instead of freezing below 60 u/s
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 2f, 0, 0, 0, Angles.PI / 2, 0, SkaterState.ROLLING);
		assertEquals(Angles.PI / 2, rig.getYaw(), 0.01f);
	}

	@Test
	public void followsFasterWhenFarBehind()
	{
		// error > 60 deg: rate 4 (else 3). One 0.02 s frame toward 90 deg: 90 * (1 - e^(-0.08)) = 6.92 deg
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		rig.update(0, 0, 0, Angles.PI / 2, 800, SkaterState.ROLLING, 0f, DT);
		assertEquals(Angles.PI / 2 * (1f - (float) Math.exp(-4f * DT)), rig.getYaw(), 1e-4f);
		// within 60 deg: rate 3. One frame toward 30 deg: 30 * (1 - e^(-0.06))
		CameraRig near = new CameraRig();
		near.reset(0, 0, 0, 0f);
		float target = (float) Math.toRadians(30);
		near.update(0, 0, 0, target, 800, SkaterState.ROLLING, 0f, DT);
		assertEquals(target * (1f - (float) Math.exp(-3f * DT)), near.getYaw(), 1e-4f);
	}

	@Test
	public void shortHopsDoNotDipTheCamera()
	{
		// only landings after more than 0.25 s in the air dip (bumps and tiny hops do not)
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 1f, 0, 0, 0, 0f, 500, SkaterState.ROLLING);
		float settled = rig.getFocusHeight();
		rig.update(0, 0, 0, 0f, 500, SkaterState.ROLLING, 0.2f, DT);
		assertEquals(settled, rig.getFocusHeight(), 0.01f);
	}

	@Test
	public void holdsYawWhileBailed()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 1f, 0, 0, 0, Angles.PI / 2, 900, SkaterState.BAILED);
		assertEquals(0f, rig.getYaw(), 1e-4f);
	}

	@Test
	public void turnsSlowerInTheAir()
	{
		CameraRig ground = new CameraRig();
		CameraRig air = new CameraRig();
		ground.reset(0, 0, 0, 0f);
		air.reset(0, 0, 0, 0f);
		run(ground, 0.3f, 0, 0, 0, 1f, 800, SkaterState.ROLLING);
		run(air, 0.3f, 0, 0, 0, 1f, 800, SkaterState.AIRBORNE);
		assertTrue(air.getYaw() < ground.getYaw());
	}

	@Test
	public void focusLeadsTheSkaterAtSpeed()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 2f, 0, 1000, 0, 0f, 1000, SkaterState.ROLLING);
		assertTrue("ahead of the skater", rig.getFocusY() > 1000f + 50f);
		assertTrue("capped", rig.getFocusY() <= 1000f + CameraRig.MAX_LOOK_AHEAD + 0.01f);
		assertEquals(0f, rig.getFocusX(), 0.5f);
	}

	@Test
	public void cameraRisesLessThanTheSkaterInTheAir()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 0.3f, 0, 0, 120, 0f, 500, SkaterState.AIRBORNE);
		float rise = rig.getFocusHeight() - CameraRig.FOCUS_HEIGHT;
		assertTrue("rise " + rise, rise > 10f && rise < 100f);
	}

	@Test
	public void landingDipsThenRecovers()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 1f, 0, 0, 0, 0f, 500, SkaterState.ROLLING);
		float settled = rig.getFocusHeight();
		rig.update(0, 0, 0, 0f, 500, SkaterState.ROLLING, 0.5f, DT);
		assertTrue(rig.getFocusHeight() < settled - 5f);
		run(rig, 1.5f, 0, 0, 0, 0f, 500, SkaterState.ROLLING);
		assertEquals(settled, rig.getFocusHeight(), 0.5f);
	}

	@Test
	public void pullsBackWithSpeed()
	{
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		run(rig, 0.1f, 0, 0, 0, 0f, 0, SkaterState.ROLLING);
		float slow = rig.getZoomFactor();
		run(rig, 0.1f, 0, 0, 0, 0f, 1500, SkaterState.ROLLING);
		assertEquals(1f, slow, 1e-4f);
		assertTrue(rig.getZoomFactor() < 0.9f);
	}

	@Test
	public void aHalfTurnSwingIsCappedAtOneTurnPerSecond()
	{
		// getting back on after a bail into a wall faces the skater away from it: a 179 degree swing. The
		// exponential follow alone started it at 4 * PI rad/s = 720 deg/s, a whip-around
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		float frame = 1f / 144f;
		float last = rig.getYaw();
		float maxRate = 0f;
		for (int i = 0; i < 288; i++)
		{
			rig.update(0, 0, 0, (float) Math.toRadians(179), 0, SkaterState.ROLLING, 0f, frame);
			maxRate = Math.max(maxRate, Angles.absDiff(rig.getYaw(), last) / frame);
			last = rig.getYaw();
		}
		assertTrue("max " + Math.toDegrees(maxRate) + " deg/s", maxRate <= 2 * Angles.PI + 1e-3f);
		assertEquals("still gets there", Math.toRadians(179), rig.getYaw(), 0.02f);
	}
}

package com.gielinorskate.camera;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class FootCameraTest
{
	private static float rad(float deg)
	{
		return (float) Math.toRadians(deg);
	}

	@Test
	public void walkingAwayOrDiagonallyTurnsTheCamera()
	{
		assertEquals(rad(10), FootCamera.targetHeading(0f, rad(10), true), 1e-6f);
		assertEquals(rad(-45), FootCamera.targetHeading(0f, rad(-45), true), 1e-6f);
	}

	@Test
	public void walkingTowardOrSidewaysHoldsTheCamera()
	{
		assertEquals(rad(30), FootCamera.targetHeading(rad(30), rad(30 + 180), true), 1e-6f);
		assertEquals(rad(30), FootCamera.targetHeading(rad(30), rad(30 + 90), true), 1e-6f);
	}

	@Test
	public void standingStillHoldsTheCamera()
	{
		assertEquals(rad(30), FootCamera.targetHeading(rad(30), rad(40), false), 1e-6f);
	}
}

package com.gielinorskate.camera;

import static org.junit.Assert.*;

import com.gielinorskate.physics.SkaterState;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import org.junit.Test;

/** The free camera can be switched off under the skater (by the game or another plugin): never an error. */
public class SkateCameraModeTest
{
	/** A client whose camera mode sticks only while {@code accepts}, and whose focal point needs the free camera. */
	private static final class FakeClient
	{
		int mode;
		boolean accepts = true;

		Client client()
		{
			return (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
				(proxy, method, args) ->
				{
					switch (method.getName())
					{
						case "getCameraMode":
							return mode;
						case "setCameraMode":
							if (accepts)
								mode = (int) args[0];
							return null;
						case "setCameraFocalPointX":
						case "setCameraFocalPointY":
						case "setCameraFocalPointZ":
							if (mode != 1)
								throw new IllegalArgumentException("must be in free camera mode");
							return null;
					}
					Class<?> r = method.getReturnType();
					if (r == boolean.class)
						return false;
					if (r == int.class)
						return 0;
					if (r == long.class)
						return 0L;
					if (r == float.class)
						return 0f;
					if (r == double.class)
						return 0d;
					return null;
				});
		}
	}

	private static boolean frame(SkateCamera camera)
	{
		return camera.update(0, 0, 0, 0, 0, SkaterState.ROLLING, 0, 1 / 60f, 400);
	}

	@Test
	public void freeCameraTurnedOffIsTurnedBackOn()
	{
		FakeClient fake = new FakeClient();
		SkateCamera camera = new SkateCamera(fake.client());
		camera.enter(0, 0, 0, 0, 800);
		assertEquals(1, fake.mode);
		fake.mode = 0;
		assertTrue(frame(camera));
		assertEquals(1, fake.mode);
	}

	@Test
	public void freeCameraThatWontStayOnStopsWithoutAnError()
	{
		FakeClient fake = new FakeClient();
		SkateCamera camera = new SkateCamera(fake.client());
		camera.enter(0, 0, 0, 0, 800);
		fake.mode = 0;
		fake.accepts = false;
		boolean ok = true;
		int frames = 0;
		while (ok && frames < 600)
		{
			ok = frame(camera);
			frames++;
		}
		assertFalse("gives up after a while", ok);
		assertTrue("not on the first frame", frames > 30);
	}
}

package com.gielinorskate.controller;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.Base64;
import java.util.Collections;
import org.junit.Test;

/** Layout codes: short, round-trip, and strict about what they accept. */
public class LayoutCodeTest
{
	private static String code(int... bytes)
	{
		byte[] b = new byte[bytes.length];
		for (int i = 0; i < bytes.length; i++)
		{
			b[i] = (byte) bytes[i];
		}
		return "RSK1:" + Base64.getUrlEncoder().withoutPadding().encodeToString(b);
	}

	private static String refusal(String code)
	{
		LayoutCode.Result r = LayoutCode.decode(code);
		assertFalse(code, r.ok());
		assertNull(r.preset);
		return r.error;
	}

	@Test
	public void skate3RoundTripsInAShortVersionedCode()
	{
		String c = LayoutCode.encode(PadPreset.skate3());
		assertTrue(c, c.startsWith("RSK1:"));
		assertTrue(c, c.length() < 80);
		LayoutCode.Result r = LayoutCode.decode(c);
		assertTrue(r.error, r.ok());
		assertNull(r.error);
		assertEquals(PadPreset.skate3(), r.preset);
	}

	@Test
	public void aCustomLayoutWithAnAirActionRoundTrips()
	{
		PadPreset p = PadPreset.skate3()
			.with(PadButton.L3, PadContext.BOARD, PadAction.OLLIE)
			.with(PadButton.DPAD_DOWN, PadContext.FOOT, PadAction.CAMERA_ORBIT)
			.with(PadButton.LB, PadContext.AIR, PadAction.LEAN_FORWARD)
			.with(PadButton.B, PadContext.BOARD, PadAction.NONE);
		assertEquals(p, LayoutCode.decode(LayoutCode.encode(p)).preset);
		assertEquals(new PadPreset(), LayoutCode.decode(LayoutCode.encode(new PadPreset())).preset);
	}

	@Test
	public void spacesAndLineBreaksAroundTheCodeAreIgnored()
	{
		String c = LayoutCode.encode(PadPreset.skate3());
		assertEquals(PadPreset.skate3(), LayoutCode.decode("  " + c + "\r\n").preset);
	}

	@Test
	public void somethingElseIsNotACode()
	{
		assertTrue(refusal("").contains("no layout code"));
		assertTrue(refusal(null).contains("no layout code"));
		assertTrue(refusal("hello").contains("isn't a RuneSkate layout code"));
		assertTrue(refusal("RSK:abc").contains("isn't a RuneSkate layout code"));
	}

	@Test
	public void aNewerVersionIsRefused()
	{
		assertTrue(refusal("RSK2:YQEOAA").contains("newer RuneSkate"));
		assertTrue(refusal("RSK0:YQEOAA").contains("version"));
	}

	@Test
	public void aCodeOverTheSizeLimitIsRefused()
	{
		String c = "RSK1:" + String.join("", Collections.nCopies(600, "A"));
		assertTrue(refusal(c).contains("too long"));
	}

	@Test
	public void damagedCodesAreRefused()
	{
		assertTrue(refusal("RSK1:ab+/").contains("damaged"));
		assertTrue(refusal("RSK1:a b").contains("damaged"));
		// three bytes: not a whole button
		assertTrue(refusal(code('a', 1, 14)).contains("damaged"));
		// a single base64 character is no byte at all
		assertTrue(refusal("RSK1:Y").contains("damaged"));
	}

	@Test
	public void unknownButtonsAndActionsAreRefused()
	{
		assertTrue(refusal(code('Z', 1, 14, 0xFF)).contains("button"));
		assertTrue(refusal(code('a', 99, 14, 0xFF)).contains("doesn't know"));
		assertTrue(refusal(code('a', 1, 99, 0xFF)).contains("doesn't know"));
		assertTrue(refusal(code('a', 1, 14, 99)).contains("doesn't know"));
	}

	@Test
	public void aButtonTwiceIsRefused()
	{
		assertTrue(refusal(code('a', 1, 14, 0xFF, 'a', 3, 0, 0xFF)).contains("A twice"));
	}

	@Test
	public void anActionWhereItCannotBeBoundIsRefused()
	{
		// push on foot, jump on the board, a flip button on foot
		assertTrue(refusal(code('a', 1, 1, 0xFF)).contains("can't be used"));
		assertTrue(refusal(code('a', 15, 0, 0xFF)).contains("can't be used"));
		assertTrue(refusal(code('a', 0, PadAction.FLIP_BUTTON.id, 0xFF)).contains("can't be used"));
		assertTrue(refusal(code('a', 1, 0, 15)).contains("can't be used"));
	}

	@Test
	public void changesListEachButtonAndPlaceThatDiffers()
	{
		assertTrue(LayoutCode.changes(PadPreset.skate3(), PadPreset.skate3()).isEmpty());
		PadPreset p = PadPreset.skate3()
			.with(PadButton.LB, PadContext.BOARD, PadAction.BRAKE)
			.with(PadButton.DPAD_DOWN, PadContext.FOOT, PadAction.JUMP);
		assertEquals(Arrays.asList("LB, on the board: Hard tricks (Shift) to Brake",
			"D-pad down, on foot: Nothing to Jump"), LayoutCode.changes(PadPreset.skate3(), p));
		PadPreset air = PadPreset.skate3().with(PadButton.LT, PadContext.AIR, PadAction.OLLIE);
		assertEquals(Collections.singletonList("LT, in the air: Grab (left hand) to Ollie (hold, let go)"),
			LayoutCode.changes(PadPreset.skate3(), air));
	}
}

package com.gielinorskate.controller;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.awt.event.KeyEvent;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

/** The pad keys, the actions and the Skate 3 preset. */
public class PadPresetTest
{
	@Test
	public void everyButtonHasItsOwnPadKeyFromTheUniversalTable()
	{
		int[] expected = {KeyEvent.VK_F13, KeyEvent.VK_F14, KeyEvent.VK_F15, KeyEvent.VK_F16, KeyEvent.VK_F17,
			KeyEvent.VK_F18, KeyEvent.VK_F19, KeyEvent.VK_F20, KeyEvent.VK_F21, KeyEvent.VK_F22, KeyEvent.VK_F23,
			KeyEvent.VK_F24, KeyEvent.VK_INSERT, KeyEvent.VK_DELETE, KeyEvent.VK_HOME, KeyEvent.VK_END};
		PadButton[] order = {PadButton.A, PadButton.B, PadButton.X, PadButton.Y, PadButton.LB, PadButton.RB,
			PadButton.LT, PadButton.RT, PadButton.BACK, PadButton.START, PadButton.L3, PadButton.R3,
			PadButton.DPAD_UP, PadButton.DPAD_DOWN, PadButton.DPAD_LEFT, PadButton.DPAD_RIGHT};
		assertEquals(16, PadButton.values().length);
		for (int i = 0; i < order.length; i++)
		{
			assertEquals(order[i].label, expected[i], order[i].keyCode);
			assertEquals(order[i], PadButton.forKey(expected[i]));
		}
		assertNull(PadButton.forKey(KeyEvent.VK_W));
		assertNull(PadButton.forKey(KeyEvent.VK_SHIFT));
		assertNull(PadButton.forKey(KeyEvent.VK_UP));
	}

	@Test
	public void functionKeyButtonsAreNamedAfterTheirKeys()
	{
		for (PadButton b : PadButton.values())
		{
			if (b.keyCode >= KeyEvent.VK_F13 && b.keyCode <= KeyEvent.VK_F24)
			{
				assertEquals("F" + (13 + b.keyCode - KeyEvent.VK_F13), b.keyName);
			}
		}
	}

	@Test
	public void idsAreUniqueAndFindTheirOwner()
	{
		Set<Character> buttonIds = new HashSet<>();
		for (PadButton b : PadButton.values())
		{
			assertTrue(buttonIds.add(b.id));
			assertEquals(b, PadButton.forId(b.id));
			assertTrue("printable", b.id > ' ' && b.id < 127);
		}
		Set<Integer> actionIds = new HashSet<>();
		for (PadAction a : PadAction.values())
		{
			assertTrue(actionIds.add(a.id));
			assertEquals(a, PadAction.forId(a.id));
			assertTrue(a.id >= 0 && a.id < LayoutCode.SAME_AS_BOARD);
		}
		assertNull(PadAction.forId(200));
	}

	@Test
	public void theButtonTrickActionsAreBoardOnly()
	{
		for (PadAction a : Arrays.asList(PadAction.FLIP_BUTTON, PadAction.GRAB_BUTTON, PadAction.GRIND_BUTTON,
			PadAction.SPIN_ASSIST))
		{
			assertTrue(a.allowedIn(PadContext.BOARD));
			assertTrue(a.allowedIn(PadContext.AIR));
			assertFalse(a.allowedIn(PadContext.FOOT));
		}
		// their layout-code ids never change
		assertEquals(18, PadAction.FLIP_BUTTON.id);
		assertEquals(19, PadAction.GRAB_BUTTON.id);
		assertEquals(20, PadAction.GRIND_BUTTON.id);
		assertEquals(21, PadAction.SPIN_ASSIST.id);
		assertTrue(PadAction.NONE.allowedIn(PadContext.FOOT));
		assertTrue(PadAction.PUSH.allowedIn(PadContext.AIR));
		assertFalse(PadAction.PUSH.allowedIn(PadContext.FOOT));
		assertFalse(PadAction.JUMP.allowedIn(PadContext.BOARD));
		assertTrue(PadAction.BOARD_TOGGLE.allowedIn(PadContext.FOOT));
	}

	@Test
	public void skate3IsTheOldPadLayout()
	{
		PadPreset p = PadPreset.skate3();
		assertEquals(PadAction.PUSH, p.action(PadButton.A, PadContext.BOARD));
		assertEquals(PadAction.SPRINT, p.action(PadButton.A, PadContext.FOOT));
		assertEquals(PadAction.PUSH, p.action(PadButton.X, PadContext.BOARD));
		assertEquals(PadAction.JUMP, p.action(PadButton.X, PadContext.FOOT));
		assertEquals(PadAction.BRAKE, p.action(PadButton.B, PadContext.BOARD));
		assertEquals(PadAction.NONE, p.action(PadButton.B, PadContext.FOOT));
		assertEquals(PadAction.BOARD_TOGGLE, p.action(PadButton.Y, PadContext.BOARD));
		assertEquals(PadAction.BOARD_TOGGLE, p.action(PadButton.Y, PadContext.FOOT));
		for (PadButton b : new PadButton[]{PadButton.LB, PadButton.RB})
		{
			assertEquals(PadAction.HARD_MODIFIER, p.action(b, PadContext.BOARD));
			assertEquals(PadAction.SPRINT, p.action(b, PadContext.FOOT));
		}
		assertEquals(PadAction.GRAB_LEFT, p.action(PadButton.LT, PadContext.BOARD));
		assertEquals(PadAction.GRAB_RIGHT, p.action(PadButton.RT, PadContext.BOARD));
		assertEquals(PadAction.DROP_PICKUP, p.action(PadButton.LT, PadContext.FOOT));
		assertEquals(PadAction.DROP_PICKUP, p.action(PadButton.RT, PadContext.FOOT));
		assertEquals(PadAction.RESET, p.action(PadButton.BACK, PadContext.FOOT));
		assertEquals(PadAction.STOP, p.action(PadButton.START, PadContext.BOARD));
		assertEquals(PadAction.CONTROLS_CARD, p.action(PadButton.DPAD_UP, PadContext.FOOT));
		for (PadButton b : new PadButton[]{PadButton.L3, PadButton.R3, PadButton.DPAD_DOWN, PadButton.DPAD_LEFT,
			PadButton.DPAD_RIGHT})
		{
			for (PadContext c : PadContext.values())
			{
				assertEquals(PadAction.NONE, p.action(b, c));
			}
		}
		assertNull(p.problem());
	}

	@Test
	public void inTheAirAButtonDoesItsBoardActionUnlessItHasItsOwn()
	{
		PadPreset p = PadPreset.skate3();
		assertEquals(PadAction.GRAB_LEFT, p.action(PadButton.LT, PadContext.AIR));
		PadPreset q = p.with(PadButton.LT, PadContext.AIR, PadAction.OLLIE);
		assertEquals(PadAction.OLLIE, q.action(PadButton.LT, PadContext.AIR));
		assertEquals(PadAction.GRAB_LEFT, q.action(PadButton.LT, PadContext.BOARD));
		// setting the air action back to the board one drops it
		assertEquals(p, q.with(PadButton.LT, PadContext.AIR, PadAction.GRAB_LEFT));
	}

	@Test
	public void withMakesAChangedCopyAndBindingNothingRemovesTheButton()
	{
		PadPreset p = PadPreset.skate3();
		PadPreset q = p.with(PadButton.LB, PadContext.BOARD, PadAction.BRAKE);
		assertEquals(PadAction.HARD_MODIFIER, p.action(PadButton.LB, PadContext.BOARD));
		assertEquals(PadAction.BRAKE, q.action(PadButton.LB, PadContext.BOARD));
		assertNotEquals(p, q);
		PadPreset cleared = new PadPreset().with(PadButton.A, PadContext.BOARD, PadAction.PUSH)
			.with(PadButton.A, PadContext.BOARD, PadAction.NONE);
		assertEquals(new PadPreset(), cleared);
	}

	@Test
	public void buttonsForListsEveryButtonOfAnAction()
	{
		PadPreset p = PadPreset.skate3();
		assertEquals(Arrays.asList(PadButton.A, PadButton.X), p.buttonsFor(PadAction.PUSH, PadContext.BOARD));
		assertEquals(Arrays.asList(PadButton.A, PadButton.LB, PadButton.RB),
			p.buttonsFor(PadAction.SPRINT, PadContext.FOOT));
		assertTrue(p.buttonsFor(PadAction.OLLIE, PadContext.BOARD).isEmpty());
	}

	@Test
	public void aBindingInTheWrongPlaceIsAProblem()
	{
		assertNotNull(new PadPreset().with(PadButton.A, PadContext.FOOT, PadAction.PUSH).problem());
		assertNotNull(new PadPreset().with(PadButton.A, PadContext.BOARD, PadAction.JUMP).problem());
		assertNotNull(new PadPreset().with(PadButton.A, PadContext.FOOT, PadAction.FLIP_BUTTON).problem());
		assertNull(new PadPreset().with(PadButton.A, PadContext.BOARD, PadAction.FLIP_BUTTON).problem());
		assertNull(new PadPreset().with(PadButton.A, PadContext.FOOT, PadAction.CAMERA_ORBIT).problem());
	}

	@Test
	public void thawIsTheTonyHawkLayout()
	{
		PadPreset p = PadPreset.thaw();
		assertNull(p.problem());
		assertTrue(p.buttonTricks());
		assertFalse(PadPreset.skate3().buttonTricks());
		assertFalse(new PadPreset().buttonTricks());
		assertEquals(PadAction.OLLIE, p.action(PadButton.A, PadContext.BOARD));
		assertEquals(PadAction.OLLIE, p.action(PadButton.A, PadContext.AIR));
		assertEquals(PadAction.JUMP, p.action(PadButton.A, PadContext.FOOT));
		assertEquals(PadAction.FLIP_BUTTON, p.action(PadButton.X, PadContext.AIR));
		assertEquals(PadAction.FLIP_BUTTON, p.action(PadButton.X, PadContext.BOARD));
		assertEquals(PadAction.NONE, p.action(PadButton.X, PadContext.FOOT));
		assertEquals(PadAction.GRAB_BUTTON, p.action(PadButton.B, PadContext.AIR));
		assertEquals(PadAction.DROP_PICKUP, p.action(PadButton.B, PadContext.FOOT));
		assertEquals(PadAction.GRIND_BUTTON, p.action(PadButton.Y, PadContext.BOARD));
		assertEquals(PadAction.GRIND_BUTTON, p.action(PadButton.Y, PadContext.AIR));
		assertEquals(PadAction.BOARD_TOGGLE, p.action(PadButton.Y, PadContext.FOOT));
		for (PadButton b : Arrays.asList(PadButton.LB, PadButton.RB))
		{
			assertEquals(PadAction.SPIN_ASSIST, p.action(b, PadContext.BOARD));
			assertEquals(PadAction.SPIN_ASSIST, p.action(b, PadContext.AIR));
			assertEquals(PadAction.SPRINT, p.action(b, PadContext.FOOT));
		}
		assertEquals(PadAction.RESET, p.action(PadButton.BACK, PadContext.BOARD));
		assertEquals(PadAction.STOP, p.action(PadButton.START, PadContext.FOOT));
		assertEquals(PadAction.CONTROLS_CARD, p.action(PadButton.DPAD_UP, PadContext.BOARD));
		assertEquals(PadAction.NONE, p.action(PadButton.LT, PadContext.BOARD));
		// a layout code round-trips it, and a custom layout with a grab button plays with button tricks
		assertEquals(p, LayoutCode.decode(LayoutCode.encode(p)).preset);
		assertTrue(new PadPreset().with(PadButton.B, PadContext.BOARD, PadAction.GRAB_BUTTON).buttonTricks());
	}

	@Test
	public void thePresetSettingPicksTheLayout()
	{
		assertEquals(PadPreset.thaw(), PadPresets.resolve(com.gielinorskate.GielinorSkateConfig.ControllerPreset.THAW,
			""));
		assertEquals(PadPreset.skate3(), PadPresets.resolve(
			com.gielinorskate.GielinorSkateConfig.ControllerPreset.SKATE_3, LayoutCode.encode(PadPreset.thaw())));
		assertFalse(PadPresets.customIsBroken(com.gielinorskate.GielinorSkateConfig.ControllerPreset.THAW, "junk"));
	}
}

package com.gielinorskate.controller;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.event.KeyEvent;
import org.junit.Test;

/** The pad tester lights the buttons whose pad keys arrive and shows the sticks. */
public class PadTesterTest
{
	private final PadTester t = new PadTester();

	@Test
	public void padKeysLightTheirButtonsWhileDown()
	{
		assertTrue(t.key(KeyEvent.VK_F17, true));
		assertTrue(t.isDown(PadButton.LB));
		assertTrue(t.wasSeen(PadButton.LB));
		assertFalse(t.isDown(PadButton.A));
		t.key(KeyEvent.VK_F17, false);
		assertFalse(t.isDown(PadButton.LB));
		assertTrue("stays ticked", t.wasSeen(PadButton.LB));
		assertTrue(t.key(KeyEvent.VK_HOME, true));
		assertTrue(t.isDown(PadButton.DPAD_LEFT));
	}

	@Test
	public void otherKeysAreNotItsBusiness()
	{
		assertFalse(t.key(KeyEvent.VK_W, true));
		assertFalse(t.key(KeyEvent.VK_SHIFT, true));
		for (PadButton b : PadButton.values())
		{
			assertFalse(t.isDown(b));
		}
	}

	@Test
	public void theArrowsAreTheLeftStick()
	{
		t.key(KeyEvent.VK_LEFT, true);
		assertEquals(-1, t.leftX());
		t.key(KeyEvent.VK_LEFT, false);
		t.key(KeyEvent.VK_DOWN, true);
		assertEquals(0, t.leftX());
		assertEquals(1, t.leftY());
	}

	@Test
	public void cursorSpeedIsTheRightStickAndAStillCursorCentresIt()
	{
		t.mouse(100, 100, 1000);
		t.mouse(160, 100, 1050);
		assertEquals(1.2f / PadTester.FULL_TILT, t.rightX(), 1e-4);
		assertEquals(0f, t.rightY(), 1e-4);
		t.mouse(160, 100, 1100);
		assertEquals("still, but not for long yet", 1f, t.rightX(), 1e-4);
		t.mouse(160, 100, 1300);
		assertEquals(0f, t.rightX(), 1e-4);
		// fast: clamped to a full tilt
		t.mouse(160, 90, 1310);
		t.mouse(160, 0, 1320);
		assertEquals(-1f, t.rightY(), 1e-4);
	}

	@Test
	public void theFirstMoveAfterAPauseHasNoSpeedYet()
	{
		t.mouse(100, 100, 1000);
		t.mouse(500, 100, 5000);
		assertEquals(0f, t.rightX(), 1e-4);
	}

	@Test
	public void resetLetsGoOfEverything()
	{
		t.key(KeyEvent.VK_F13, true);
		t.key(KeyEvent.VK_UP, true);
		t.reset();
		assertFalse(t.isDown(PadButton.A));
		assertEquals(0, t.leftY());
	}
}

package com.gielinorskate.controller;

import static org.junit.Assert.*;
import java.awt.event.KeyEvent;
import java.util.*;
import org.junit.Test;

/** The pad tables and layout-code refusals read from text/overlay.properties. */
public class PadTextTest
{
	@Test
	public void everyActionLoadsWithAUniqueIdAndAPlace()
	{
		Set<Integer> ids = new HashSet<>();
		for (PadAction a : PadAction.values())
		{
			assertTrue(a.name(), ids.add(a.id));
			assertFalse(a.name(), a.label.isEmpty());
			assertTrue(a.name(), a.onBoard || a.onFoot);
		}
		assertEquals(0, PadAction.NONE.id);
		assertEquals("Ollie (hold, let go)", PadAction.OLLIE.label);
		assertTrue(PadAction.STOP.onBoard && PadAction.STOP.onFoot);
		assertFalse(PadAction.SPRINT.onBoard);
		assertEquals(PadAction.SPIN_ASSIST, PadAction.forId(21));
	}

	@Test
	public void everyButtonLoadsWithAUniqueIdAndPadKey()
	{
		Set<Character> ids = new HashSet<>();
		Set<Integer> keys = new HashSet<>();
		for (PadButton b : PadButton.values())
		{
			assertTrue(b.name(), ids.add(b.id));
			assertTrue(b.name(), keys.add(b.keyCode));
			assertFalse(b.name(), b.label.isEmpty());
		}
		assertEquals(KeyEvent.VK_F13, PadButton.A.keyCode);
		assertEquals("F13", PadButton.A.keyName);
		assertEquals(KeyEvent.VK_F24, PadButton.R3.keyCode);
		assertEquals('4', PadButton.R3.id);
		assertEquals("Back", PadButton.BACK.label);
		assertEquals(KeyEvent.VK_INSERT, PadButton.DPAD_UP.keyCode);
		assertEquals("Insert", PadButton.DPAD_UP.keyName);
		assertEquals("D-pad up", PadButton.DPAD_UP.label);
	}

	private static String code(int... bytes)
	{
		byte[] b = new byte[bytes.length];
		for (int i = 0; i < bytes.length; i++)
			b[i] = (byte) bytes[i];
		return "RSK1:" + Base64.getUrlEncoder().withoutPadding().encodeToString(b);
	}

	@Test
	public void everyRefusalReadsInFull()
	{
		char[] big = new char[600];
		Arrays.fill(big, 'A');
		String[][] cases = {
			{"", "There is no layout code to read."},
			{new String(big), "That code is too long to be a RuneSkate layout (over 512 characters)."},
			{"XYZ", "That isn't a RuneSkate layout code: they start with RSK1:"},
			{"RSK2:AA", "That layout code is from a newer RuneSkate. Update the plugin to use it."},
			{"RSK0:AA", "That layout code's version (0) isn't one RuneSkate knows."},
			{"RSK1:!!", "That layout code is damaged: it has characters a code never has."},
			{"RSK1:AAA", "That layout code is damaged: part of it is missing."},
			{code('z', 1, 1, 1), "That layout code names a controller button RuneSkate doesn't know."},
			{code('a', 1, 1, 255, 'a', 1, 1, 255), "That layout code sets A twice."},
			{code('a', 99, 1, 255), "That layout code has an action this version of RuneSkate doesn't know. Update the "
				+ "plugin to use it."},
			{code('a', 1, 1, 255), "That layout code can't be used: A can't do \"Push\" on foot."},
		};
		for (String[] c : cases)
			assertEquals(c[1], LayoutCode.decode(c[0]).error);
	}
}

package com.gielinorskate.feedback;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class BailLinesTest
{
	@Test
	public void oneLineEveryTwentySeconds()
	{
		BailLines lines = new BailLines();
		assertEquals(BailLines.ROTATION[0], lines.onBail(0f, false, 500));
		assertNull(lines.onBail(5f, false, 500));
		assertNull(lines.onBail(19.9f, false, 500));
		assertEquals(BailLines.ROTATION[1], lines.onBail(20f, false, 500));
	}

	@Test
	public void rotationNeverRepeatsBackToBackAndWraps()
	{
		BailLines lines = new BailLines();
		String previous = null;
		for (int i = 0; i < BailLines.ROTATION.length * 2; i++)
		{
			String line = lines.onBail(i * 30f, false, 100);
			assertEquals(BailLines.ROTATION[i % BailLines.ROTATION.length], line);
			if (previous != null)
			{
				org.junit.Assert.assertNotEquals(previous, line);
			}
			previous = line;
		}
	}

	@Test
	public void wallAndEmptyBailsHaveTheirOwnLinesAndDoNotAdvanceTheRotation()
	{
		BailLines lines = new BailLines();
		assertEquals(BailLines.WALL, lines.onBail(0f, true, 900));
		assertEquals(BailLines.NOTHING_LOST, lines.onBail(30f, false, 0));
		assertEquals("wall wins over nothing lost", BailLines.WALL, lines.onBail(60f, true, 0));
		assertEquals(BailLines.ROTATION[0], lines.onBail(90f, false, 10));
	}

	@Test
	public void aCooledDownBailStillStartsTheCooldownOnlyWhenALineIsPosted()
	{
		BailLines lines = new BailLines();
		lines.onBail(0f, false, 10);
		assertNull(lines.onBail(10f, true, 10));
		// the skipped bail at 10 s did not restart the clock
		assertEquals(BailLines.ROTATION[1], lines.onBail(20f, false, 10));
	}
}

