package com.gielinorskate.feedback;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class HudAnimTest
{
	@Test
	public void popStartsBigAndSettlesToOneAfter120ms()
	{
		assertEquals(1.35f, HudAnim.popScale(0f), 1e-4f);
		assertEquals(1f, HudAnim.popScale(0.12f), 0f);
		assertEquals(1f, HudAnim.popScale(5f), 0f);
		assertEquals("never drawn before its time", 1f, HudAnim.popScale(-1f), 0f);
		// ease-out-back: most of the way there early, with a small dip below 1 before it settles
		float mid = HudAnim.popScale(0.06f);
		assertTrue("mid " + mid, mid < 1.1f);
		float min = Float.MAX_VALUE;
		for (float t = 0f; t < 0.12f; t += 0.001f)
		{
			min = Math.min(min, HudAnim.popScale(t));
		}
		assertTrue("overshoot stays small: " + min, min > 0.95f && min < 1f);
	}

	@Test
	public void easeOutBackHitsBothEnds()
	{
		assertEquals(0f, HudAnim.easeOutBack(0f), 1e-5f);
		assertEquals(1f, HudAnim.easeOutBack(1f), 1e-5f);
	}

	@Test
	public void ringPulsesFortyPercentThickerFor150ms()
	{
		assertEquals(1.4f, HudAnim.ringPulse(0f), 1e-5f);
		assertEquals(1.2f, HudAnim.ringPulse(0.075f), 1e-4f);
		assertEquals(1f, HudAnim.ringPulse(0.15f), 0f);
		assertEquals(1f, HudAnim.ringPulse(-Float.MAX_VALUE), 0f);
		assertEquals(1f, HudAnim.ringFlash(0f), 0f);
		assertEquals(0f, HudAnim.ringFlash(0.2f), 0f);
	}

	@Test
	public void landedScoreCountsUpOver300ms()
	{
		assertEquals(0, HudAnim.countUp(1000, 0f));
		// ease-out cubic: at half time 1 - 0.5^3 = 0.875 of the value
		assertEquals(875, HudAnim.countUp(1000, 0.15f));
		assertEquals(1000, HudAnim.countUp(1000, 0.3f));
		assertEquals(1000, HudAnim.countUp(1000, Float.MAX_VALUE));
		int last = -1;
		for (float t = 0f; t <= 0.31f; t += 0.01f)
		{
			int v = HudAnim.countUp(1000, t);
			assertTrue("never counts down", v >= last);
			last = v;
		}
	}

	@Test
	public void bailShakeStaysWithinThreePixelsAndStopsAfter200ms()
	{
		boolean moved = false;
		for (float t = 0f; t < 0.2f; t += 0.005f)
		{
			assertTrue(Math.abs(HudAnim.shakeX(t)) <= 3);
			assertTrue(Math.abs(HudAnim.shakeY(t)) <= 3);
			moved |= HudAnim.shakeX(t) != 0 || HudAnim.shakeY(t) != 0;
		}
		assertTrue(moved);
		assertEquals(0, HudAnim.shakeX(0.2f));
		assertEquals(0, HudAnim.shakeY(0.25f));
		assertEquals(0, HudAnim.shakeX(-1f));
	}

	@Test
	public void xpDropRisesAndFadesOverItsLife()
	{
		assertEquals(0f, HudAnim.xpDropRise(0f), 0f);
		assertEquals(1f, HudAnim.xpDropRise(1.2f), 0f);
		// ease-out: 1 - 0.5^2 = 0.75 of the way at half time
		assertEquals(0.75f, HudAnim.xpDropRise(0.6f), 1e-4f);
		assertEquals(1f, HudAnim.xpDropAlpha(0.5f), 0f);
		assertEquals(0.5f, HudAnim.xpDropAlpha(1.0f), 1e-4f);
		assertEquals(0f, HudAnim.xpDropAlpha(1.2f), 0f);
	}

	@Test
	public void calloutHoldsThenFades()
	{
		assertEquals(1f, HudAnim.calloutAlpha(0f), 0f);
		assertEquals(1f, HudAnim.calloutAlpha(1.2f), 0f);
		assertEquals(0.5f, HudAnim.calloutAlpha(1.4f), 1e-4f);
		assertEquals(0f, HudAnim.calloutAlpha(1.6f), 0f);
		assertEquals(1.35f, HudAnim.calloutScale(0f), 1e-4f);
		assertEquals(1f, HudAnim.calloutScale(0.18f), 0f);
	}

	@Test
	public void bannerHoldsThenFades()
	{
		assertEquals(0f, HudAnim.bannerAlpha(-1f), 0f);
		assertEquals(1f, HudAnim.bannerAlpha(3f), 0f);
		assertEquals(0.5f, HudAnim.bannerAlpha(3.6f), 1e-4f);
		assertEquals(0f, HudAnim.bannerAlpha(4f), 0f);
		assertEquals(1f, HudAnim.goalFlashAlpha(2f), 0f);
		assertEquals(0f, HudAnim.goalFlashAlpha(3f), 0f);
	}
}

package com.gielinorskate.feedback;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.SoundEffectID;
import org.junit.Test;

public class SoundPickerTest
{
	private static final float DT = 0.02f;
	private static final List<SkateEvent> NONE = Collections.emptyList();
	private static final List<TrickEvent> NO_TRICKS = Collections.emptyList();

	private static int[] ids(List<SoundPicker.Cue> cues)
	{
		return cues.stream().mapToInt(c -> c.id).toArray();
	}

	@Test
	public void popAndBailAndPlainTricks()
	{
		SoundPicker picker = new SoundPicker();
		assertEquals(0, picker.pick(NONE, NO_TRICKS, false, 0f, null, DT).size());
		assertEquals(SoundEffectID.UI_BOOP, ids(picker.pick(Arrays.asList(SkateEvent.POP), NO_TRICKS, false, 0f, null, DT))[0]);
		assertEquals(SoundEffectID.MAGIC_SPLASH_BOING, ids(picker.pick(Arrays.asList(SkateEvent.BAIL), NO_TRICKS, false, 0f, null, DT))[0]);
		// a plain kickflip makes no extra sound
		assertEquals(0, picker.pick(NONE, Arrays.asList(TrickEvent.trick(Trick.KICKFLIP)), false, 0f, null, DT).size());
	}

	@Test
	public void bigTricksWoosh()
	{
		assertTrue(SoundPicker.isBig(Trick.TRE_FLIP));
		assertTrue(SoundPicker.isBig(Trick.SHOVE_IT_360));
		assertTrue(SoundPicker.isBig(Trick.DOUBLE_KICKFLIP));
		assertTrue(SoundPicker.isBig(Trick.FRONTFLIP));
		assertFalse(SoundPicker.isBig(Trick.KICKFLIP));
		assertFalse(SoundPicker.isBig(Trick.POP_SHOVE_IT));
		SoundPicker picker = new SoundPicker();
		assertEquals(SoundEffectID.FIRE_WOOSH,
			ids(picker.pick(NONE, Arrays.asList(TrickEvent.trick(Trick.TRE_FLIP)), false, 0f, null, DT))[0]);
	}

	@Test
	public void landingVolumeFollowsLandingSpeed()
	{
		SoundPicker picker = new SoundPicker();
		List<SkateEvent> land = Arrays.asList(SkateEvent.LAND);
		assertEquals(0.3f, picker.pick(land, NO_TRICKS, false, 100f, null, DT).get(0).volume, 1e-5f);
		// 820 / 1400 = 0.586
		assertEquals(820f / 1400f, picker.pick(land, NO_TRICKS, false, 820f, null, DT).get(0).volume, 1e-5f);
		assertEquals(1f, picker.pick(land, NO_TRICKS, false, 3000f, null, DT).get(0).volume, 1e-5f);
	}

	@Test
	public void grindLocksWithATonkThenTinksEveryQuarterSecond()
	{
		SoundPicker picker = new SoundPicker();
		List<SoundPicker.Cue> lock = picker.pick(NONE, Arrays.asList(TrickEvent.holdStart(Trick.FIFTY_FIFTY)), true,
			0f, null, DT);
		assertEquals(1, lock.size());
		assertEquals(SoundEffectID.SMITH_ANVIL_TONK, lock.get(0).id);
		int tinks = 0;
		// just over a second more on the rail (float steps of 0.02 s): 0.25 s apart, so 4 tinks
		for (int i = 0; i < 52; i++)
		{
			tinks += picker.pick(NONE, NO_TRICKS, true, 0f, null, DT).size();
		}
		assertEquals(4, tinks);
		// off the rail: silence, and the beat restarts on the next rail
		assertEquals(0, picker.pick(NONE, NO_TRICKS, false, 0f, null, DT).size());
		assertEquals(0, picker.pick(NONE, NO_TRICKS, true, 0f, null, DT).size());
	}

	@Test
	public void manualHoldsDoNotTonk()
	{
		SoundPicker picker = new SoundPicker();
		assertEquals(0, picker.pick(NONE, Arrays.asList(TrickEvent.holdStart(Trick.MANUAL)), false, 0f, null, DT).size());
	}

	@Test
	public void landedCombosChimeBiggerFromFifteenThousand()
	{
		SoundPicker picker = new SoundPicker();
		assertEquals(SoundPicker.COMBO_LANDED,
			ids(picker.pick(NONE, NO_TRICKS, false, 0f, ComboScorer.Result.landed(14_999), DT))[0]);
		assertEquals(SoundEffectID.GE_ADD_OFFER_DINGALING,
			ids(picker.pick(NONE, NO_TRICKS, false, 0f, ComboScorer.Result.landed(15_000), DT))[0]);
		assertEquals(0, picker.pick(NONE, NO_TRICKS, false, 0f, ComboScorer.Result.bailed(20_000), DT).size());
	}

	@Test
	public void throttleAllowsEachSoundOncePerTenthOfASecond()
	{
		SkateSounds throttle = new SkateSounds();
		assertTrue(throttle.allow(1, 0f));
		assertFalse(throttle.allow(1, 0.05f));
		assertTrue("other sounds are separate", throttle.allow(2, 0.05f));
		assertTrue(throttle.allow(1, 0.1f));
	}

	@Test
	public void repeaterFiresAtMostOnceAFrame()
	{
		Repeater r = new Repeater(0.15f, true);
		assertTrue("fires on contact", r.update(true, 0.02f));
		assertTrue("a huge frame fires once", r.update(true, 1f));
		// owes at most one more beat after the long frame
		assertTrue(r.update(true, 0.001f));
		assertFalse(r.update(true, 0.001f));
		assertFalse(r.update(false, 0.02f));
		assertTrue("restarts", r.update(true, 0.02f));
	}
}

