		SpotanimDef def = SpotanimDef.parse(bytes(
			1, 0x12, 0x34,          // model 0x1234
			2, 0x03, 0xE8,          // animation 1000
			4, 0x00, 0x40,          // resize x 64
			5, 0x01, 0x00,          // resize y 256
			6, 0x00, 0x5A,          // rotation (skipped)
			7, 30,                  // ambient
			8, 200,                 // contrast
			9, 'p', 'u', 'f', 'f', 0, // debug name (skipped)
			10,                     // not clickable
			40, 1, 0x00, 0x10, 0xFF, 0xFE, // recolour 16 -> -2
			41, 1, 0, 1, 0, 2,      // retexture (skipped)
			42, 0, 9,               // full recolour (skipped)
			0));
		assertEquals(0x1234, def.modelId);
		assertEquals(1000, def.animationId);
		assertEquals(64, def.resizeX);
		assertEquals(256, def.resizeY);
		assertEquals(30, def.ambient);
		assertEquals(200, def.contrast);
		assertArrayEquals(new short[]{16}, def.recolorFrom);
		assertArrayEquals(new short[]{(short) 0xFFFE}, def.recolorTo);
	}

	@Test
	public void bigModelIdsUseTheIntOpcode()
	{
		SpotanimDef def = SpotanimDef.parse(bytes(3, 0x00, 0x01, 0x86, 0xA0, 0)); // 100000
		assertEquals(100_000, def.modelId);
		assertEquals(-1, def.animationId);
		assertEquals(128, def.resizeX);
	}

	@Test
	public void badDataIsSkippedNotThrown()
	{
		assertNull(SpotanimDef.parse(null));
		assertNull("truncated", SpotanimDef.parse(bytes(1, 0x12)));
		assertNull("no terminator", SpotanimDef.parse(bytes(1, 0x12, 0x34)));
		assertNull("unknown opcode", SpotanimDef.parse(bytes(1, 0, 5, 99, 0)));
		assertNull("no model", SpotanimDef.parse(bytes(2, 0, 5, 0)));
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.GielinorSkateConfig;
import java.awt.event.KeyEvent;
import com.gielinorskate.controller.PadButton;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import javax.xml.parsers.DocumentBuilderFactory;
import org.junit.Test;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.NodeList;

/**
 * The shipped AntiMicroX profile: well-formed, every binding exactly one key or mouse direction (no macros, turbo,
 * set changes or multi-slot sequences), every button sends its own pad key ({@link PadButton}), the left stick the
 * arrows and the right stick the mouse.
 */
public class AntiMicroXProfileTest
{
	/** AntiMicroX stores keys as Qt key codes. */
	private static final String CRLF = "\r\n";
	private static final String LF = "\n";
	private static final int QT_UP = 0x1000013;
	private static final int QT_DOWN = 0x1000015;
	private static final int QT_LEFT = 0x1000012;
	private static final int QT_RIGHT = 0x1000014;
	/** Qt::Key_F1; F2 to F35 follow it. */
	private static final int QT_F1 = 0x1000030;

	/**
	 * The Qt key code AntiMicroX stores for a Java key code: letters, digits and B / F / ... are the same; the
	 * function keys are Qt::Key_F1 + n (on Windows AntiMicroX sends them as VK_F1 + n, which Java reads as
	 * KeyEvent.VK_F1 + n for F1 to F12 and VK_F13 + n from F13); Insert / Delete / Home / End from qnamespace.h.
	 */
	private static int qt(int javaCode)
	{
		switch (javaCode)
		{
			case KeyEvent.VK_INSERT:
				return 0x1000006;
			case KeyEvent.VK_DELETE:
				return 0x1000007;
			case KeyEvent.VK_HOME:
				return 0x1000010;
			case KeyEvent.VK_END:
				return 0x1000011;
			default:
				break;
		}
		if (javaCode >= KeyEvent.VK_F13 && javaCode <= KeyEvent.VK_F24)
		{
			return QT_F1 + 12 + (javaCode - KeyEvent.VK_F13);
		}
		if (javaCode >= KeyEvent.VK_F1 && javaCode <= KeyEvent.VK_F12)
		{
			return QT_F1 + (javaCode - KeyEvent.VK_F1);
		}
		assertTrue("a plain ASCII key: " + javaCode, (javaCode >= KeyEvent.VK_0 && javaCode <= KeyEvent.VK_9)
			|| (javaCode >= KeyEvent.VK_A && javaCode <= KeyEvent.VK_Z));
		return javaCode;
	}

	private static Document profile() throws Exception
	{
		DocumentBuilderFactory f = DocumentBuilderFactory.newInstance();
		f.setExpandEntityReferences(false);
		f.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
		return f.newDocumentBuilder().parse(new File("controller/RuneSkate.amgp"));
	}

	private static String text(Element e, String child)
	{
		NodeList l = e.getElementsByTagName(child);
		return l.getLength() == 0 ? null : l.item(0).getTextContent().trim();
	}

	/** "stick1/3", "button2", "trigger5", "dpad1/1" -> the one slot's code (keyboard) or mouse direction. */
	private static Map<String, String> bindings(Document d)
	{
		Map<String, String> out = new HashMap<>();
		NodeList slotLists = d.getElementsByTagName("slots");
		for (int i = 0; i < slotLists.getLength(); i++)
		{
			Element slots = (Element) slotLists.item(i);
			Element owner = (Element) slots.getParentNode();
			NodeList slotNodes = slots.getElementsByTagName("slot");
			assertEquals("one slot per binding: " + owner.getTagName(), 1, slotNodes.getLength());
			Element slot = (Element) slotNodes.item(0);
			String mode = text(slot, "mode");
			assertTrue(mode, mode.equals("keyboard") || mode.equals("mousemovement"));
			Element parent = (Element) owner.getParentNode();
			String key;
			switch (owner.getTagName())
			{
				case "stickbutton":
					key = "stick" + parent.getAttribute("index") + "/" + owner.getAttribute("index");
					break;
				case "dpadbutton":
					key = "dpad" + parent.getAttribute("index") + "/" + owner.getAttribute("index");
					break;
				case "triggerbutton":
					assertEquals("2", owner.getAttribute("index"));
					key = "trigger" + parent.getAttribute("index");
					break;
				default:
					assertEquals("button", owner.getTagName());
					key = "button" + owner.getAttribute("index");
					break;
			}
			assertFalse("bound twice: " + key, out.containsKey(key));
			out.put(key, mode.charAt(0) + ":" + Integer.decode(text(slot, "code")));
		}
		return out;
	}

	private static String key(int code)
	{
		return "k:" + code;
	}

	@Test
	public void theProfileIsAGameControllerProfileWithOneSet() throws Exception
	{
		Document d = profile();
		assertEquals("gamecontroller", d.getDocumentElement().getTagName());
		assertEquals(1, d.getElementsByTagName("set").getLength());
	}

	@Test
	public void everyBindingIsOneToOneWithNoMacrosOrTurbo() throws Exception
	{
		Document d = profile();
		for (String banned : new String[]{"useturbo", "turbointerval", "turbomode", "setselect", "cycleresetactive",
			"toggle"})
		{
			assertEquals(banned, 0, d.getElementsByTagName(banned).getLength());
		}
		NodeList modes = d.getElementsByTagName("mode");
		for (int i = 0; i < modes.getLength(); i++)
		{
			String m = modes.item(i).getTextContent().trim();
			assertFalse(m, m.equals("mix") || m.equals("macro") || m.equals("pause") || m.equals("hold")
				|| m.equals("cycle") || m.equals("distance") || m.equals("delay") || m.equals("execute")
				|| m.equals("textentry") || m.equals("setchange"));
		}
		bindings(d);
	}

	/** Where each pad button sits in an AntiMicroX game controller profile. */
	private static final Map<PadButton, String> SLOTS = new EnumMap<>(PadButton.class);

	static
	{
		// SDL buttons, 1-based: A, B, X, Y, Back, (Guide), Start, L3, R3, LB, RB
		SLOTS.put(PadButton.A, "button1");
		SLOTS.put(PadButton.B, "button2");
		SLOTS.put(PadButton.X, "button3");
		SLOTS.put(PadButton.Y, "button4");
		SLOTS.put(PadButton.BACK, "button5");
		SLOTS.put(PadButton.START, "button7");
		SLOTS.put(PadButton.L3, "button8");
		SLOTS.put(PadButton.R3, "button9");
		SLOTS.put(PadButton.LB, "button10");
		SLOTS.put(PadButton.RB, "button11");
		// triggers: SDL axes 4 / 5, 1-based
		SLOTS.put(PadButton.LT, "trigger5");
		SLOTS.put(PadButton.RT, "trigger6");
		// the d-pad's directions: up 1, right 2, down 4, left 8
		SLOTS.put(PadButton.DPAD_UP, "dpad1/1");
		SLOTS.put(PadButton.DPAD_RIGHT, "dpad1/2");
		SLOTS.put(PadButton.DPAD_DOWN, "dpad1/4");
		SLOTS.put(PadButton.DPAD_LEFT, "dpad1/8");
	}

	@Test
	public void everyButtonSendsItsOwnPadKeyAndTheSticksAreArrowsAndMouse() throws Exception
	{
		Map<String, String> b = bindings(profile());
		assertEquals(PadButton.values().length, SLOTS.size());
		for (PadButton p : PadButton.values())
		{
			assertEquals(p.label, key(qt(p.keyCode)), b.get(SLOTS.get(p)));
		}
		// the F keys are Qt::Key_F1 + n, which AntiMicroX sends on Windows as VK_F1 + n
		assertEquals(key(qt(KeyEvent.VK_F13)), b.get("button1"));
		assertEquals(key(qt(KeyEvent.VK_F24)), b.get("button9"));
		// left stick: four-way arrow keys
		assertEquals(key(QT_UP), b.get("stick1/1"));
		assertEquals(key(QT_RIGHT), b.get("stick1/3"));
		assertEquals(key(QT_DOWN), b.get("stick1/5"));
		assertEquals(key(QT_LEFT), b.get("stick1/7"));
		// right stick: mouse up / down / left / right (AntiMicroX directions 1-4)
		assertEquals("m:1", b.get("stick2/1"));
		assertEquals("m:2", b.get("stick2/5"));
		assertEquals("m:3", b.get("stick2/7"));
		assertEquals("m:4", b.get("stick2/3"));
		assertEquals(16 + 4 + 4, b.size());
	}

	@Test
	public void theLeftStickIsFourWaySoASteerIsNeverALean() throws Exception
	{
		Document d = profile();
		NodeList sticks = d.getElementsByTagName("stick");
		for (int i = 0; i < sticks.getLength(); i++)
		{
			Element s = (Element) sticks.item(i);
			if ("1".equals(s.getAttribute("index")))
			{
				assertEquals("four-way", text(s, "mode"));
				return;
			}
		}
		throw new AssertionError("no left stick");
	}

	@Test
	public void theArrowsAreTheDefaultLeanKeysAndSteerAsAAndD()
	{
		GielinorSkateConfig defaults = new GielinorSkateConfig()
		{
		};
		assertEquals(KeyEvent.VK_UP, defaults.leanForwardKey().getKeyCode());
		assertEquals(KeyEvent.VK_DOWN, defaults.leanBackKey().getKeyCode());
	}

	@Test
	public void noPadKeyIsADefaultKeySettingOrASkateControl()
	{
		GielinorSkateConfig defaults = new GielinorSkateConfig()
		{
		};
		for (PadButton p : PadButton.values())
		{
			assertTrue(p.label, InputController.isPadKeyFree(p.keyCode, defaults.toggleKey().getKeyCode(),
				defaults.manualKey().getKeyCode(), defaults.leanForwardKey().getKeyCode(),
				defaults.leanBackKey().getKeyCode(), defaults.brakeKey().getKeyCode(), defaults.boardKey().getKeyCode(),
				KeyEvent.VK_C));
			assertFalse(p.label, KeyboardTricks.isTrickKey(p.keyCode));
			// a real key nothing in skate mode reads by itself
			assertTrue(p.label, InputController.isValidManualKey(p.keyCode));
			assertFalse(p.label, p.keyCode == KeyEvent.VK_SPACE);
		}
	}

	@Test
	public void thePanelSavesTheSameProfileAsTheControllerFolder() throws Exception
	{
		String folder = new String(Files.readAllBytes(Paths.get("controller/RuneSkate.amgp")), StandardCharsets.UTF_8);
		String resource = new String(Files.readAllBytes(
			Paths.get("src/main/resources/com/gielinorskate/RuneSkate.amgp")), StandardCharsets.UTF_8);
		assertEquals(folder.replace(CRLF, LF), resource.replace(CRLF, LF));
	}

	@Test
	public void theRightStickMatchesTheSpeedsTheDetectionIsTunedFor() throws Exception
	{
		Document d = profile();
		NodeList sticks = d.getElementsByTagName("stick");
		Element right = null;
		for (int i = 0; i < sticks.getLength(); i++)
		{
			Element s = (Element) sticks.item(i);
			if ("2".equals(s.getAttribute("index")))
			{
				right = s;
			}
		}
		NodeList buttons = right.getElementsByTagName("stickbutton");
		assertEquals(8, buttons.getLength());
		for (int i = 0; i < buttons.getLength(); i++)
		{
			Element sb = (Element) buttons.item(i);
			assertEquals("60", text(sb, "mousespeedx"));
			assertEquals("60", text(sb, "mousespeedy"));
			assertEquals("cursor", text(sb, "mousemode"));
			assertEquals("quadratic", text(sb, "mouseacceleration"));
		}
		// full tilt: speed x AntiMicroX's 20 px/s per unit = 1.2 px/ms, comfortably a flick (0.5) and fast (0.35)
		float fullTilt = 60 * 20 / 1000f;
		assertTrue(fullTilt >= 2 * GestureRecognizer.FLICK_MIN_SPEED);
		// a small tilt (a third of the way, quadratic) stays slow enough to be a manual
		assertTrue(fullTilt * (1 / 3f) * (1 / 3f) < ControllerStick.FAST_SPEED);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** F tap / hold detection. */
public class BoardKeyTest
{
	private final BoardKey key = new BoardKey();
	private final BoardKey.Edges e = new BoardKey.Edges();

	@Test
	public void aPressIsReportedAtOnce()
	{
		key.press(0);
		key.poll(1, e);
		assertTrue(e.pressed);
		assertFalse(e.tapped);
		assertFalse(e.held);
		key.poll(2, e);
		assertFalse("reported once", e.pressed);
	}

	@Test
	public void aQuickReleaseIsATap()
	{
		key.press(0);
		key.poll(10, e);
		key.release(999);
		key.poll(1000, e);
		assertTrue(e.tapped);
		assertFalse(e.held);
	}

	@Test
	public void holdingOneSecondIsAHoldReportedWhileStillHeldAndOnlyOnce()
	{
		key.press(0);
		key.poll(10, e);
		key.poll(999, e);
		assertFalse(e.held);
		key.poll(1000, e);
		assertTrue(e.held);
		key.poll(1500, e);
		assertFalse(e.held);
		key.release(2000);
		key.poll(2001, e);
		assertFalse("a hold is no tap", e.tapped);
		assertFalse(e.held);
	}

	@Test
	public void aHoldReleasedBeforeAnyPollIsStillAHold()
	{
		key.press(0);
		key.release(1200);
		key.poll(1300, e);
		assertTrue(e.pressed);
		assertTrue(e.held);
		assertFalse(e.tapped);
	}

	@Test
	public void keyRepeatsAreIgnored()
	{
		key.press(0);
		key.poll(1, e);
		key.press(300);
		key.press(600);
		key.poll(700, e);
		assertFalse(e.pressed);
		key.poll(1000, e);
		assertTrue("the hold still counts from the first press", e.held);
	}

	@Test
	public void resetForgetsAPressInProgress()
	{
		key.press(0);
		key.reset();
		key.poll(1500, e);
		assertFalse(e.pressed);
		assertFalse(e.held);
		key.press(1600);
		key.poll(1600, e);
		assertTrue("not still down: a new press counts", e.pressed);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Grabs;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickCatalog;
import java.awt.event.KeyEvent;
import org.junit.Test;

/** The button-trick tables: flip button + direction, grab button + direction. */
public class ButtonTricksTest
{
	@Test
	public void directionsCombineAndOppositesCancel()
	{
		assertNull(ButtonTricks.direction(false, false, false, false));
		assertNull(ButtonTricks.direction(true, true, true, true));
		assertEquals(Direction.UP, ButtonTricks.direction(true, false, false, false));
		assertEquals(Direction.DOWN, ButtonTricks.direction(false, true, true, true));
		assertEquals(Direction.LEFT, ButtonTricks.direction(false, false, true, false));
		assertEquals(Direction.RIGHT, ButtonTricks.direction(true, true, false, true));
		assertEquals(Direction.UP_LEFT, ButtonTricks.direction(true, false, true, false));
		assertEquals(Direction.UP_RIGHT, ButtonTricks.direction(true, false, false, true));
		assertEquals(Direction.DOWN_LEFT, ButtonTricks.direction(false, true, true, false));
		assertEquals(Direction.DOWN_RIGHT, ButtonTricks.direction(false, true, false, true));
	}

	@Test
	public void flipButtonTable()
	{
		assertEquals(Trick.KICKFLIP, ButtonTricks.flipTrick(Direction.LEFT, false));
		assertEquals(Trick.HEELFLIP, ButtonTricks.flipTrick(Direction.RIGHT, false));
		assertEquals(Trick.IMPOSSIBLE, ButtonTricks.flipTrick(Direction.UP, false));
		assertEquals(Trick.POP_SHOVE_IT, ButtonTricks.flipTrick(Direction.DOWN, false));
		assertEquals(Trick.VARIAL_KICKFLIP, ButtonTricks.flipTrick(Direction.UP_LEFT, false));
		assertEquals(Trick.VARIAL_HEELFLIP, ButtonTricks.flipTrick(Direction.UP_RIGHT, false));
		assertEquals(Trick.TRE_FLIP, ButtonTricks.flipTrick(Direction.DOWN_LEFT, false));
		assertEquals(Trick.HARDFLIP, ButtonTricks.flipTrick(Direction.DOWN_RIGHT, false));
		assertEquals(Trick.KICKFLIP, ButtonTricks.flipTrick(null, false));
	}

	@Test
	public void theHardModifierGivesTheHardVersionAsAShiftFlickDoes()
	{
		assertEquals(Trick.HARDFLIP, ButtonTricks.flipTrick(Direction.LEFT, true));
		assertEquals(Trick.INWARD_HEELFLIP, ButtonTricks.flipTrick(Direction.RIGHT, true));
		assertEquals(Trick.BIGSPIN, ButtonTricks.flipTrick(Direction.DOWN, true));
		assertEquals(Trick.IMPOSSIBLE, ButtonTricks.flipTrick(Direction.UP, true));
		assertEquals(Trick.HARDFLIP, ButtonTricks.flipTrick(null, true));
	}

	@Test
	public void eachFlipIsTheSameGestureAsItsTrickKey()
	{
		// so physics, scoring and the animations cannot tell a button trick from the key (or flick) for it
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_1, false, false), ButtonTricks.flip(Direction.LEFT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_2, false, false), ButtonTricks.flip(Direction.RIGHT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_3, false, false), ButtonTricks.flip(Direction.DOWN, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_5, false, false),
			ButtonTricks.flip(Direction.UP_LEFT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_6, false, false),
			ButtonTricks.flip(Direction.UP_RIGHT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_7, false, false),
			ButtonTricks.flip(Direction.DOWN_LEFT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_1, false, true),
			ButtonTricks.flip(Direction.DOWN_RIGHT, false));
		assertEquals(KeyboardTricks.gestureFor(KeyEvent.VK_SPACE, false, true), ButtonTricks.flip(Direction.UP, false));
	}

	@Test
	public void aSecondPressMidFlipDoublesThenTriples()
	{
		Gesture again = ButtonTricks.flip(Direction.LEFT, false);
		assertEquals(Trick.DOUBLE_KICKFLIP, TrickCatalog.upgrade(Trick.KICKFLIP, again));
		assertEquals(Trick.TRIPLE_KICKFLIP, TrickCatalog.upgrade(Trick.DOUBLE_KICKFLIP, again));
		assertEquals(Trick.DOUBLE_KICKFLIP, TrickCatalog.upgrade(Trick.KICKFLIP, ButtonTricks.flip(null, false)));
		Gesture heel = ButtonTricks.flip(Direction.RIGHT, false);
		assertEquals(Trick.DOUBLE_HEELFLIP, TrickCatalog.upgrade(Trick.HEELFLIP, heel));
		assertEquals(Trick.TRIPLE_HEELFLIP, TrickCatalog.upgrade(Trick.DOUBLE_HEELFLIP, heel));
		// a different flip mid-flip upgrades nothing, as a different flick
		assertNull(TrickCatalog.upgrade(Trick.KICKFLIP, heel));
	}

	@Test
	public void grabButtonTable()
	{
		assertEquals(Trick.MELON, ButtonTricks.grab(Direction.LEFT));
		assertEquals(Trick.INDY, ButtonTricks.grab(Direction.RIGHT));
		assertEquals(Trick.NOSEGRAB, ButtonTricks.grab(Direction.UP));
		assertEquals(Trick.TAILGRAB, ButtonTricks.grab(Direction.DOWN));
		assertEquals(Trick.CRAIL, ButtonTricks.grab(Direction.UP_LEFT));
		assertEquals(Trick.MUTE, ButtonTricks.grab(Direction.UP_RIGHT));
		assertEquals(Trick.STALEFISH, ButtonTricks.grab(Direction.DOWN_LEFT));
		assertEquals(Trick.INDY, ButtonTricks.grab(Direction.DOWN_RIGHT));
		assertEquals(Trick.INDY, ButtonTricks.grab(null));
	}

	@Test
	public void grabsAreTheGrabTablesHandsAndAims()
	{
		for (Direction d : Direction.values())
		{
			assertEquals(d.name(), Grabs.pick(ButtonTricks.grabLeftHand(d), ButtonTricks.grabAim(d)),
				ButtonTricks.grab(d));
		}
		// the default is the unaimed left-hand grab (the Q key's)
		assertTrue(ButtonTricks.grabLeftHand(null));
		assertNull(ButtonTricks.grabAim(null));
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import org.junit.Test;

/**
 * Controller mode's right stick, as AntiMicroX's cursor-mode mouse output: flicks with no button held, and small
 * held tilts as manuals. Speeds are px/ms; the shipped profile's full tilt is about 1.2 px/ms.
 */
public class ControllerStickTest
{
	private static final double FULL = 1.2;

	private final GestureRecognizer gesture = new GestureRecognizer();
	private final ControllerStick stick = new ControllerStick(gesture);

	private StickSim sim()
	{
		return new StickSim(stick::move, 400, 300, 1000);
	}

	private StickSim grabbing()
	{
		return new StickSim(stick::blockedMove, 400, 300, 1000);
	}

	@Test
	public void aFullPullDownThenFlickUpWithNoButtonIsAnOllie()
	{
		StickSim s = sim().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		stick.tick(s.ms);
		Gesture g = gesture.poll();
		assertEquals(Direction.UP, g.direction);
		assertFalse(g.nollie);
		assertNull(gesture.poll());
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
		assertFalse("the stroke ends once the stick is back at centre", stick.isActive());
		assertFalse(gesture.isStrokeActive());
	}

	@Test
	public void aPushUpThenFlickDownIsANollie()
	{
		StickSim s = sim().tilt(0, -FULL, 80).tilt(0, FULL, 80).rest(100);
		stick.tick(s.ms);
		Gesture g = gesture.poll();
		assertEquals(Direction.DOWN, g.direction);
		assertTrue(g.nollie);
	}

	@Test
	public void aFlickUpLeftIsAKickflipDirection()
	{
		StickSim s = sim().tilt(0, FULL, 80).tilt(-0.85, -0.85, 80).rest(100);
		stick.tick(s.ms);
		assertEquals(Direction.UP_LEFT, gesture.poll().direction);
	}

	@Test
	public void aFlickWithAShortPauseAtTheTurnaroundStillCounts()
	{
		// passing through the stick's dead zone takes a moment: no cursor events for a few ms
		StickSim s = sim().tilt(0, FULL, 80).rest(30).tilt(0, -FULL, 80).rest(100);
		stick.tick(s.ms);
		assertEquals(Direction.UP, gesture.poll().direction);
	}

	@Test
	public void aSmallTiltUpHeldIsAManualUntilTheStickIsReleased()
	{
		StickSim s = sim().tilt(0, -0.12, 200);
		stick.tick(s.ms);
		assertEquals("not before 0.25 s", ControllerStick.Manual.NONE, stick.manual());
		s.tilt(0, -0.12, 100);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.MANUAL, stick.manual());
		s.tilt(0, -0.12, 1000);
		stick.tick(s.ms);
		assertEquals("held as long as the tilt is", ControllerStick.Manual.MANUAL, stick.manual());
		s.rest(ControllerStick.STOP_MS + 10);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
		assertNull("a manual is never a flick", gesture.poll());
		assertNull("and gives no near-miss hint", gesture.pollNearMiss());
	}

	@Test
	public void aSmallTiltDownHeldIsANoseManual()
	{
		StickSim s = sim().tilt(0, 0.12, 300);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.NOSE, stick.manual());
		assertFalse("the slow pull never showed a crouch", !stick.hidesWindUp() && gesture.isCrouching());
		assertNull(gesture.poll());
	}

	@Test
	public void theSlowDriftBeforeAManualDoesNotCrouch()
	{
		StickSim s = sim().tilt(0, 0.12, 200);
		stick.tick(s.ms);
		assertTrue("the recogniser is wound up...", gesture.isCrouching());
		assertTrue("...but a slow stroke hides it until it is fast", stick.hidesWindUp());
	}

	@Test
	public void aFastPullShowsTheWindUp()
	{
		StickSim s = sim().tilt(0, FULL, 60);
		stick.tick(s.ms);
		assertTrue(gesture.isCrouching());
		assertFalse(stick.hidesWindUp());
	}

	@Test
	public void aFlickFollowedByASlowDriftIsNeverAManual()
	{
		StickSim s = sim().tilt(0, FULL, 80).tilt(0, -FULL, 80).tilt(0, -0.12, 500);
		stick.tick(s.ms);
		assertEquals(Direction.UP, gesture.poll().direction);
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
	}

	@Test
	public void aSidewaysDriftIsNoManual()
	{
		StickSim s = sim().tilt(0.12, 0, 500);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
	}

	@Test
	public void aTinyDriftIsNoManual()
	{
		StickSim s = sim().tilt(0, -0.01, 400);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
	}

	@Test
	public void aFlickOutOfAManualEndsItAndPops()
	{
		StickSim s = sim().tilt(0, -0.12, 400);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.MANUAL, stick.manual());
		s.tilt(0, FULL, 80).tilt(0, -FULL, 80);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
		assertEquals(Direction.UP, gesture.poll().direction);
	}

	@Test
	public void movingTheStickWithAGrabHeldIsNeverAFlick()
	{
		StickSim s = grabbing().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		stick.tick(s.ms);
		assertNull(gesture.poll());
		assertFalse(stick.isActive());
	}

	@Test
	public void aGrabPressedMidStrokeCancelsTheStrokeAndItsTailIsNoFlick()
	{
		StickSim s = sim().tilt(0, FULL, 80);
		stick.block(s.ms);
		assertFalse(gesture.isStrokeActive());
		// the grab key is let go while the stick is still moving: the rest of that motion is not a flick
		StickSim tail = new StickSim(stick::move, 400, 396, s.ms);
		tail.tilt(0, -FULL, 80).rest(100);
		stick.tick(tail.ms);
		assertNull(gesture.poll());
		// once the stick has been still, flicks work again
		tail.tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		stick.tick(tail.ms);
		assertEquals(Direction.UP, gesture.poll().direction);
	}

	@Test
	public void flicksCanBeTurnedOffLeavingManuals()
	{
		stick.setFlicks(false);
		StickSim s = sim().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		stick.tick(s.ms);
		assertNull(gesture.poll());
		s.tilt(0, -0.12, 300);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.MANUAL, stick.manual());
	}

	@Test
	public void resetForgetsTheStrokeWithoutTouchingTheRecogniser()
	{
		StickSim s = sim().tilt(0, -0.12, 300);
		stick.tick(s.ms);
		assertEquals(ControllerStick.Manual.MANUAL, stick.manual());
		stick.reset();
		assertEquals(ControllerStick.Manual.NONE, stick.manual());
		assertFalse(stick.isActive());
		// a right-drag that starts now is the recogniser's alone: the stick never ends it
		gesture.begin(400, 300, s.ms);
		stick.tick(s.ms + 500);
		assertTrue(gesture.isStrokeActive());
	}

	@Test
	public void flickSensitivityIsTheRecognisersOwn()
	{
		// a short flick: 12 px pull, 24 px snap (too small at 100%, enough at 150%)
		StickSim s = sim().tilt(0, FULL, 10).tilt(0, -FULL, 20).rest(100);
		stick.tick(s.ms);
		assertNull(gesture.poll());
		gesture.setSensitivity(150);
		StickSim t = new StickSim(stick::move, 400, 300, s.ms + 200).tilt(0, FULL, 15).tilt(0, -FULL, 25).rest(100);
		stick.tick(t.ms);
		assertEquals(Direction.UP, gesture.poll().direction);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import org.junit.Test;

/** Near misses: strokes that look like a trick attempt but did not make one say why, once per stroke. */
public class GestureNearMissTest
{
	@Test
	public void aCleanFlickHasNoNearMiss()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50);
		r.move(100, 195, 120);
		r.end();
		assertNotNull(r.poll());
		assertNull(r.pollNearMiss());
	}

	@Test
	public void aSlowDriftBackAfterTheWindUpIsTooSlow()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 25, 10); // wound up
		// creeping back up long after the hand left the extreme: the missed-flick release
		r.move(0, 20, 200);
		r.move(0, 15, 400);
		r.move(0, 10, 600);
		assertNull(r.poll());
		assertEquals(NearMiss.TOO_SLOW, r.pollNearMiss());
		assertNull("polled once", r.pollNearMiss());
	}

	@Test
	public void farButSlowThenReleasedIsTooSlow()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 25, 10);
		r.move(40, 25, 500); // sideways 40 px, far too slowly to flick
		r.end();
		assertNull(r.poll());
		assertEquals(NearMiss.TOO_SLOW, r.pollNearMiss());
	}

	@Test
	public void aShortFlickThenReleaseIsTooShort()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50); // wound up
		r.move(100, 215, 70); // 15 px up, less than the 30 px flick
		r.end();
		assertNull(r.poll());
		assertEquals(NearMiss.TOO_SHORT, r.pollNearMiss());
	}

	@Test
	public void holdingTheWindUpAndLettingGoIsJustACrouch()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50);
		r.move(101, 232, 300);
		r.end();
		assertNull(r.pollNearMiss());
	}

	@Test
	public void aSidewaysFlickWithNoPullDownSaysPullDownFirst()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 100, 0);
		r.move(120, 102, 20);
		r.move(140, 101, 40);
		r.move(170, 103, 60);
		r.end();
		assertNull(r.poll());
		assertEquals(NearMiss.NO_WIND_UP, r.pollNearMiss());
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickCatalog;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class GestureRecognizerTest
{
	@Test
	public void pullDownThenFlickUpProducesOllieDirection()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50); // down 30px >= 18 -> wound up (crouching)
		assertTrue(r.isCrouching());

		r.move(100, 195, 120); // 35px from the extreme in 70ms (0.5 px/ms) -> flick
		Gesture g = r.poll();
		assertEquals(Direction.UP, g.direction);
		assertFalse(g.nollie);
		assertEquals(0f, g.turnDegrees, 0.01f);
		assertNull(r.poll());
	}

	@Test
	public void slowDragDoesNotFlickEvenPastTheDistanceThreshold()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 25, 10); // wound up down
		r.move(40, 25, 500); // 40px away from the extreme, but 490ms later
		assertNull(r.poll());
	}

	@Test
	public void noFlickWithoutHavingBeenWoundUpFirst()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 5, 20); // only 5px down, not wound up
		r.move(0, -5, 40); // only 5px net up from base, still not wound up
		r.move(0, -50, 9999); // crosses the nollie wind-up threshold only on this very call,
		// so the current point IS the wind-up extreme: no distance has been travelled yet.
		assertNull(r.poll());
	}

	@Test
	public void nolliePathWindsUpOnUpwardPullAndIsNotCrouching()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 100, 0);
		r.move(0, 70, 20); // 30px up >= 18 -> wound up as nollie
		assertFalse(r.isCrouching());

		r.move(0, 100, 60); // 30px back down from the extreme in 40ms (0.75 px/ms) -> flick
		Gesture g = r.poll();
		assertEquals(Direction.DOWN, g.direction);
		assertTrue(g.nollie);
	}

	@Test
	public void curvedPathAccumulatesTurnDegreesWhileStraightDoesNot()
	{
		GestureRecognizer straight = new GestureRecognizer();
		straight.begin(0, 0, 0);
		straight.move(0, 20, 10); // wound up down, extreme (0, 20)
		straight.move(0, -20, 60); // straight flick, single segment
		Gesture sg = straight.poll();
		assertEquals(0f, sg.turnDegrees, 0.01f);

		GestureRecognizer curved = new GestureRecognizer();
		curved.begin(0, 0, 0);
		curved.move(0, 20, 10); // wound up down, extreme (0, 20)
		curved.move(20, 20, 20); // segment of 20px, heading "right"
		curved.move(20, -15, 40); // segment of 35px, heading "up": a 90 degree turn, then flick
		Gesture cg = curved.poll();
		assertEquals(90f, cg.turnDegrees, 0.01f);
	}

	@Test
	public void reFlickAfterGracePeriodLapsesNeedsFreshWindUp()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 20, 10); // wound up down, extreme (0, 20)
		r.move(0, -20, 60); // first flick
		assertEquals(Direction.UP, r.poll().direction);

		// More than 500ms after the flick, with no renewed 18px pull: no second flick.
		r.move(0, -55, 700);
		assertNull(r.poll());
	}

	@Test
	public void crouchEndsAfterAFlickEvenWithTheMouseHeldStill()
	{
		Hand h = new Hand(400, 300).pullDown().stroke(0, -60, 8, 64, false);
		assertEquals(1, h.out.size());
		h.tick(10);
		assertFalse("re-armed, not crouching", h.r.isCrouching());
		h.tick(600); // re-arm window lapses with no motion
		assertFalse(h.r.isCrouching());
	}

	@Test
	public void realisticPlainUpLeftFlickIsExactlyOneKickflip()
	{
		// 40px pull in 4px steps over 120ms, then a 100px up-left flick in ~8px steps over 84ms
		Hand h = new Hand(400, 300).pullDown().stroke(-71, -71, 12, 84, true).tick(50).tick(500);
		assertEquals(1, h.out.size());
		Gesture g = h.out.get(0);
		assertEquals(Direction.UP_LEFT, g.direction);
		assertFalse(g.nollie);
		assertEquals("turn " + g.turnDegrees, Trick.KICKFLIP, TrickCatalog.forGesture(g));
	}

	@Test
	public void realisticPlainUpRightFlickIsExactlyOneHeelflip()
	{
		Hand h = new Hand(400, 300).pullDown().stroke(64, -77, 10, 80, true).tick(50).tick(500);
		assertEquals(1, h.out.size());
		assertEquals(Trick.HEELFLIP, TrickCatalog.forGesture(h.out.get(0)));
	}

	@Test
	public void curvedHalfCircleIsATreFlip()
	{
		// from the bottom of the pull, a counter-clockwise half circle (80px across) that starts heading
		// up-right and ends heading down-left: its chord points up-left and its path turns ~180 degrees
		Hand h = new Hand(400, 300).pullDown().arc(40, 30, 180, 12, 96).tick(40).tick(500);
		assertEquals(1, h.out.size());
		Gesture g = h.out.get(0);
		assertEquals(Direction.UP_LEFT, g.direction);
		assertEquals("turn " + g.turnDegrees, Trick.TRE_FLIP, TrickCatalog.forGesture(g));
	}

	@Test
	public void longContinuousFlickIsOneGesture()
	{
		Hand h = new Hand(400, 300).pullDown().stroke(0, -150, 15, 120, true).tick(50).tick(500);
		assertEquals(1, h.out.size());
		assertEquals(Direction.UP, h.out.get(0).direction);
	}

	@Test
	public void downThenUpReFlickWithinHalfASecondIsASecondGesture()
	{
		Hand h = new Hand(400, 300).pullDown()
			.stroke(-50, -50, 8, 64, true) // first flick, up-left
			.stroke(25, 25, 6, 60, false) // back down-right
			.stroke(-45, -45, 7, 56, true); // re-flick up-left, ~180ms after the first
		assertEquals(2, h.out.size());
		assertEquals(Direction.UP_LEFT, h.out.get(0).direction);
		assertEquals(Direction.UP_LEFT, h.out.get(1).direction);
		assertEquals(Trick.DOUBLE_KICKFLIP, TrickCatalog.upgrade(Trick.KICKFLIP, h.out.get(1)));
	}

	@Test
	public void shortReturnStrokeStillReArmsWithoutAFreshWindUp()
	{
		// a 12px return is under the 18px wind-up, but it is a turnaround: the re-flick counts from it
		Hand h = new Hand(400, 300).pullDown()
			.stroke(-50, 0, 7, 56, false) // shove-it flick left
			.stroke(12, 0, 3, 30, false) // small return
			.stroke(-45, 0, 6, 48, false); // flick left again
		assertEquals(2, h.out.size());
		assertEquals(Direction.LEFT, h.out.get(1).direction);
	}

	@Test
	public void endStopsCrouchingAndDiscardsTheActiveWindUp()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		r.move(0, 20, 10);
		assertTrue(r.isCrouching());
		r.end();
		assertFalse(r.isCrouching());
	}

	@Test
	public void windUpHeldForASecondThenFlickedIsAnOllie()
	{
		// pull down 45 px in 150 ms, hold 1 s with hand jitter, flick up 70 px in 60 ms
		for (long seed = 0; seed < 50; seed++)
		{
			MousePath p = MousePath.of(seed, 0.6, MousePath.at(0, 0, 0), MousePath.at(150, 0, 45),
				MousePath.at(1150, 1, 46), MousePath.at(1210, 2, -25));
			GestureRecognizer r = new GestureRecognizer();
			List<Gesture> out = p.feed(r, p.endMs() + 200);
			assertEquals("seed " + seed, 1, out.size());
			assertEquals("seed " + seed, Direction.UP, out.get(0).direction);
			assertFalse("seed " + seed, out.get(0).nollie);
			assertFalse("flicked: no longer crouching", r.isCrouching());
		}
	}

	@Test
	public void windUpHeldPerfectlyStillThenFlickedIsAnOllie()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(0, 0, 0);
		for (int i = 1; i <= 10; i++)
		{
			r.move(0, 4 * i, 12 * i); // 40 px pull over 120 ms
		}
		r.tick(1120); // a full second with the mouse held still: no drag events at all
		assertTrue(r.isCrouching());
		int[] ys = {37, 30, 20, 8, -2, -8};
		for (int i = 0; i < ys.length; i++)
		{
			r.move(0, ys[i], 1128 + 8 * i);
		}
		Gesture g = r.poll();
		assertEquals(Direction.UP, g.direction);
		assertNull(r.poll());
	}

	@Test
	public void sidewaysDriftAfterTheWindUpIsNoTrick()
	{
		// re-centring the hand: 40 px sideways over 200 ms right after the pull
		for (long seed = 0; seed < 50; seed++)
		{
			float side = seed % 2 == 0 ? 40 : -40;
			MousePath p = MousePath.of(seed, 0.8, MousePath.at(0, 0, 0), MousePath.at(150, 0, 45),
				MousePath.at(350, side, 48));
			List<Gesture> out = p.feed(new GestureRecognizer(), p.endMs() + 300);
			assertTrue("seed " + seed + " " + out, out.isEmpty());
		}
	}

	@Test
	public void slowReturnAfterAMissedFlickClearsTheCrouch()
	{
		// pull down, then drift back up toward neutral far too slowly to flick
		MousePath p = MousePath.of(3, 0.5, MousePath.at(0, 0, 0), MousePath.at(150, 0, 45),
			MousePath.at(750, 0, 10));
		GestureRecognizer r = new GestureRecognizer();
		List<Gesture> out = p.feed(r, p.endMs() + 50);
		assertTrue(out.toString(), out.isEmpty());
		assertFalse("hand back near neutral: crouch released", r.isCrouching());
	}

	@Test
	public void holdingTheWindUpKeepsTheCrouchWithNoTimeLimit()
	{
		MousePath p = MousePath.of(5, 0.6, MousePath.at(0, 0, 0), MousePath.at(150, 0, 45),
			MousePath.at(3000, 2, 46));
		GestureRecognizer r = new GestureRecognizer();
		assertTrue(p.feed(r, 3000).isEmpty());
		assertTrue(r.isCrouching());
	}

	@Test
	public void flickTwentyDegreesOffVerticalIsStillAnOllie()
	{
		assertEquals(Direction.UP, straightFlick(20).direction);
		assertEquals(Direction.UP, straightFlick(-20).direction);
	}

	@Test
	public void flickThirtyFiveDegreesOffVerticalIsADiagonal()
	{
		assertEquals(Direction.UP_LEFT, straightFlick(-35).direction);
		assertEquals(Direction.UP_RIGHT, straightFlick(35).direction);
		assertEquals(Direction.UP_LEFT, straightFlick(-60).direction);
	}

	@Test
	public void flickSeventyDegreesOffVerticalIsHorizontal()
	{
		assertEquals(Direction.LEFT, straightFlick(-70).direction);
		assertEquals(Direction.RIGHT, straightFlick(70).direction);
	}

	@Test
	public void sectorsAreTwentyFiveDegreesEitherSideOfVerticalAndBeyondSixtyFive()
	{
		assertEquals(Direction.UP, sectorAt(24));
		assertEquals(Direction.UP, sectorAt(-24));
		assertEquals(Direction.UP_RIGHT, sectorAt(26));
		assertEquals(Direction.UP_LEFT, sectorAt(-64));
		assertEquals(Direction.LEFT, sectorAt(-66));
		assertEquals(Direction.RIGHT, sectorAt(66));
		assertEquals(Direction.DOWN, sectorAt(180 - 24));
		assertEquals(Direction.DOWN_LEFT, sectorAt(-180 + 40));
		assertEquals(Direction.DOWN_RIGHT, sectorAt(180 - 40));
	}

	/** Sector of a flick `degrees` clockwise from straight up on screen. */
	private static Direction sectorAt(double degrees)
	{
		double a = Math.toRadians(degrees);
		return GestureRecognizer.sector((float) (100 * Math.sin(a)), (float) (-100 * Math.cos(a)));
	}

	@Test
	public void fiftyQuickOlliesAreAllOllies()
	{
		for (long seed = 100; seed < 150; seed++)
		{
			MousePath p = MousePath.of(seed, 0.6, MousePath.at(0, 0, 0), MousePath.at(120, 0, 45),
				MousePath.at(170, 0, -20));
			List<Gesture> out = p.feed(new GestureRecognizer(), p.endMs() + 200);
			assertEquals("seed " + seed, 1, out.size());
			assertEquals("seed " + seed, Trick.OLLIE, TrickCatalog.forGesture(out.get(0)));
		}
	}

	/** Pull 40 px down, then a clean 70 px flick at `degrees` off straight up (+ = to the right) in 60 ms. */
	private static Gesture straightFlick(double degrees)
	{
		double a = Math.toRadians(degrees);
		MousePath p = MousePath.of(1, 0, MousePath.at(0, 0, 0), MousePath.at(120, 0, 40),
			MousePath.at(140, 0, 40), MousePath.at(200, 70 * Math.sin(a), 40 - 70 * Math.cos(a)));
		List<Gesture> out = p.feed(new GestureRecognizer(), p.endMs() + 100);
		assertEquals(1, out.size());
		return out.get(0);
	}


	@Test
	public void highFlickSensitivityShortensTheWindUpAndFlick()
	{
		// 150%: wind-up 18 / 1.5 = 12 px, flick 30 / 1.5 = 20 px. A 15 px pull and a 25 px flick fire;
		// at 100% the same path never even winds up.
		MousePath p = MousePath.of(2, 0, MousePath.at(0, 0, 0), MousePath.at(100, 0, 15),
			MousePath.at(120, 0, 15), MousePath.at(160, 0, -10));
		GestureRecognizer sensitive = new GestureRecognizer();
		sensitive.setSensitivity(150);
		assertEquals(1, p.feed(sensitive, p.endMs() + 100).size());
		assertTrue(p.feed(new GestureRecognizer(), p.endMs() + 100).isEmpty());
	}

	@Test
	public void lowFlickSensitivityNeedsALongerFlick()
	{
		// 70%: flick 30 / 0.7 = 43 px, so a 36 px flick is not enough
		MousePath p = MousePath.of(2, 0, MousePath.at(0, 0, 0), MousePath.at(120, 0, 40),
			MousePath.at(140, 0, 40), MousePath.at(180, 0, 4));
		GestureRecognizer dull = new GestureRecognizer();
		dull.setSensitivity(70);
		assertTrue(p.feed(dull, p.endMs() + 100).isEmpty());
		assertEquals(1, p.feed(new GestureRecognizer(), p.endMs() + 100).size());
	}

	/** Feeds a realistic multi-sample mouse path to a recognizer and collects every gesture it emits. */
	private static final class Hand
	{
		final GestureRecognizer r = new GestureRecognizer();
		final List<Gesture> out = new ArrayList<>();
		float x;
		float y;
		long ms;

		Hand(int x, int y)
		{
			this.x = x;
			this.y = y;
			r.begin(x, y, 0);
		}

		/** 40px straight down in 4px steps over 120ms, wobbling a pixel sideways. */
		Hand pullDown()
		{
			return stroke(0, 40, 10, 120, true);
		}

		/** A straight stroke in equal steps; `wobble` adds an alternating 1px sideways error per sample. */
		Hand stroke(float dx, float dy, int steps, long durMs, boolean wobble)
		{
			float sx = x;
			float sy = y;
			long s0 = ms;
			float len = (float) Math.hypot(dx, dy);
			float px = -dy / len;
			float py = dx / len;
			for (int i = 1; i <= steps; i++)
			{
				float f = (float) i / steps;
				int w = wobble && i < steps ? (i % 2 == 0 ? 1 : -1) : 0;
				feed(sx + dx * f + px * w, sy + dy * f + py * w, s0 + durMs * i / steps);
			}
			x = sx + dx;
			y = sy + dy;
			return this;
		}

		/**
		 * A circular arc of `radius` px starting along `startDeg` (maths angle, y up on screen) and
		 * sweeping `sweepDeg` counter-clockwise, in equal steps.
		 */
		Hand arc(float radius, double startDeg, double sweepDeg, int steps, long durMs)
		{
			double c = Math.toRadians(startDeg + 90);
			double cx = x + radius * Math.cos(c);
			double cy = y - radius * Math.sin(c);
			long s0 = ms;
			double px = x;
			double py = y;
			for (int i = 1; i <= steps; i++)
			{
				double phi = Math.toRadians(startDeg - 90 + sweepDeg * i / steps);
				px = cx + radius * Math.cos(phi);
				py = cy - radius * Math.sin(phi);
				feed((float) px, (float) py, s0 + durMs * i / steps);
			}
			x = (float) px;
			y = (float) py;
			return this;
		}

		/** Time passes with the mouse held still. */
		Hand tick(long afterMs)
		{
			ms += afterMs;
			r.tick(ms);
			drain();
			return this;
		}

		private void feed(float fx, float fy, long t)
		{
			ms = t;
			r.move(Math.round(fx), Math.round(fy), t);
			drain();
		}

		private void drain()
		{
			Gesture g;
			while ((g = r.poll()) != null)
			{
				out.add(g);
			}
		}
	}

	@Test
	public void theModifierIsSampledWhenTheFlickFires()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50); // wound up
		r.setModifier(true);
		r.move(100, 195, 120); // flick
		r.setModifier(false); // released after the flick: too late to matter
		Gesture g = r.poll();
		assertEquals(Direction.UP, g.direction);
		assertTrue(g.modified);
	}

	@Test
	public void noModifierMeansAPlainGesture()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.setModifier(true);
		r.begin(100, 200, 0);
		r.move(100, 230, 50);
		r.setModifier(false);
		r.move(100, 195, 120);
		assertFalse(r.poll().modified);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.gielinorskate.tricks.Grabs.Aim;
import org.junit.Test;

public class GrabAimTest
{
	@Test
	public void smallMovesDoNotAim()
	{
		assertNull(GrabAim.classify(0, 0, false));
		assertNull(GrabAim.classify(GrabAim.AIM_PX - 1, 0, false));
		assertNull(GrabAim.classify(10, -12, false));
	}

	@Test
	public void upIsTheNoseAndDownTheTail()
	{
		assertEquals(Aim.NOSE, GrabAim.classify(5, -GrabAim.AIM_PX, false));
		assertEquals(Aim.TAIL, GrabAim.classify(-5, GrabAim.AIM_PX, false));
	}

	@Test
	public void rightIsTheToeSideForRegularStanceAndMirroringSwapsIt()
	{
		// regular stance: the rider faces the right of the screen from behind, so the toes are on the right
		assertEquals(Aim.TOE, GrabAim.classify(GrabAim.AIM_PX, 3, false));
		assertEquals(Aim.HEEL, GrabAim.classify(-GrabAim.AIM_PX, 3, false));
		assertEquals(Aim.HEEL, GrabAim.classify(GrabAim.AIM_PX, 3, true));
		assertEquals(Aim.TOE, GrabAim.classify(-GrabAim.AIM_PX, 3, true));
		// mirroring never touches up and down
		assertEquals(Aim.NOSE, GrabAim.classify(0, -30, true));
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.physics.SkateInput;
import com.gielinorskate.tricks.Gesture;
import java.awt.Canvas;
import java.awt.Component;
import java.awt.Rectangle;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import java.util.Collections;
import org.junit.Test;

/** Shift as a brake only when held alone, clicks through the sidebar and chatbox, and remapped flick buttons. */
public class InputComfortTest
{
	private static final Component SOURCE = new Canvas();

	private final long[] now = {1000L};
	private final InputController c = new InputController(() -> now[0]);

	private static KeyEvent key(int code, boolean pressed)
	{
		return new KeyEvent(SOURCE, pressed ? KeyEvent.KEY_PRESSED : KeyEvent.KEY_RELEASED, 0L, 0, code,
			KeyEvent.CHAR_UNDEFINED);
	}

	private static MouseEvent mouse(int id, int button, int x, int y, long when)
	{
		int mask = button == MouseEvent.BUTTON1 ? InputEvent.BUTTON1_DOWN_MASK
			: button == MouseEvent.BUTTON2 ? InputEvent.BUTTON2_DOWN_MASK : InputEvent.BUTTON3_DOWN_MASK;
		return new MouseEvent(SOURCE, id, when, mask, x, y, 1, false, button);
	}

	private SkateInput drainAt(long ms)
	{
		now[0] = ms;
		SkateInput in = new SkateInput();
		c.drainInto(in);
		return in;
	}

	@Test
	public void shiftAloneBrakesOnlyAfterAQuarterSecond()
	{
		c.setEnabled(true);
		now[0] = 1000L;
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		SkateInput first = drainAt(1000L);
		assertTrue(first.powerslide);
		assertTrue("not a brake yet", first.brakeBlocked);
		assertTrue(drainAt(1200L).brakeBlocked);
		assertFalse("held alone for 0.25 s: brake", drainAt(1260L).brakeBlocked);
	}

	@Test
	public void shiftWithWHeldNeverBrakes()
	{
		c.setEnabled(true);
		now[0] = 1000L;
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		c.keyPressed(key(KeyEvent.VK_W, true));
		assertTrue(drainAt(1500L).brakeBlocked);
		assertTrue(drainAt(3000L).brakeBlocked);
		// W released: Shift is alone from now on, and must stay so for another 0.25 s
		c.keyReleased(key(KeyEvent.VK_W, false));
		assertTrue(drainAt(3010L).brakeBlocked);
		assertFalse(drainAt(3300L).brakeBlocked);
	}

	@Test
	public void shiftDuringAFlickWindUpDoesNotBrake()
	{
		c.setEnabled(true);
		now[0] = 1000L;
		c.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON3, 50, 200, 1000L));
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		c.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON3, 50, 230, 1050L));
		assertTrue(drainAt(1100L).brakeBlocked);
		assertTrue("a long Shift wind-up still does not brake", drainAt(1400L).brakeBlocked);
	}

	@Test
	public void releasingShiftEndsTheBrake()
	{
		c.setEnabled(true);
		now[0] = 1000L;
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		assertFalse(drainAt(1300L).brakeBlocked);
		c.keyReleased(key(KeyEvent.VK_SHIFT, false));
		SkateInput in = drainAt(1310L);
		assertFalse(in.powerslide);
		now[0] = 1320L;
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		assertTrue("a fresh press waits again", drainAt(1330L).brakeBlocked);
	}

	@Test
	public void clicksOverThePassThroughAreasReachTheGame()
	{
		c.setEnabled(true);
		c.setClickThroughAreas(Collections.singletonList(new Rectangle(500, 300, 200, 200)));
		MouseEvent sidebar = mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON1, 550, 350, 0L);
		c.mousePressed(sidebar);
		assertFalse(sidebar.isConsumed());
		MouseEvent sidebarRelease = mouse(MouseEvent.MOUSE_RELEASED, MouseEvent.BUTTON1, 550, 350, 0L);
		c.mouseReleased(sidebarRelease);
		assertFalse(sidebarRelease.isConsumed());
		MouseEvent sidebarClick = mouse(MouseEvent.MOUSE_CLICKED, MouseEvent.BUTTON1, 550, 350, 0L);
		c.mouseClicked(sidebarClick);
		assertFalse(sidebarClick.isConsumed());

		MouseEvent world = mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON1, 100, 100, 0L);
		c.mousePressed(world);
		assertTrue("world clicks stay blocked", world.isConsumed());
	}

	@Test
	public void aRightPressOverTheSidebarIsNotAFlick()
	{
		c.setEnabled(true);
		c.setClickThroughAreas(Collections.singletonList(new Rectangle(0, 0, 200, 400)));
		MouseEvent press = mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON3, 50, 200, 0L);
		c.mousePressed(press);
		assertFalse(press.isConsumed());
		c.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON3, 50, 230, 50L));
		c.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON3, 50, 195, 120L));
		assertTrue(drainAt(130L).gestures.isEmpty());
	}

	@Test
	public void clicksAreBlockedEverywhereWithoutPassThroughAreas()
	{
		c.setEnabled(true);
		MouseEvent press = mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON1, 550, 350, 0L);
		c.mousePressed(press);
		assertTrue(press.isConsumed());
	}

	@Test
	public void aRightDragRemappedToTheMiddleButtonStillFlicks()
	{
		// the core Camera plugin's "Right click moves camera" hands right presses on as the middle button
		c.setEnabled(true);
		c.mousePressed(mouse(MouseEvent.MOUSE_PRESSED, MouseEvent.BUTTON2, 50, 200, 0L));
		c.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON2, 50, 230, 50L));
		c.mouseDragged(mouse(MouseEvent.MOUSE_DRAGGED, MouseEvent.BUTTON2, 50, 195, 120L));
		SkateInput in = drainAt(130L);
		assertEquals(1, in.gestures.size());
		assertEquals(Gesture.Direction.UP, in.gestures.get(0).direction);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.GielinorSkateConfig;
import com.gielinorskate.physics.SkateInput;
import com.gielinorskate.tricks.Gesture.Direction;
import java.awt.Canvas;
import java.awt.Component;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import org.junit.Test;

/** Controller mode: the right stick as button-free mouse motion, lean-only arrows and the brake key. */
public class InputControllerControllerModeTest
{
	private static final Component SOURCE = new Canvas();
	private static final double FULL = 1.2;

	private long now = 1000;
	private final InputController c = new InputController(() -> now);

	private static KeyEvent key(int code, boolean pressed)
	{
		return key(code, KeyEvent.CHAR_UNDEFINED, pressed);
	}

	private static KeyEvent key(int code, char ch, boolean pressed)
	{
		return new KeyEvent(SOURCE, pressed ? KeyEvent.KEY_PRESSED : KeyEvent.KEY_RELEASED, 0, 0, code, ch);
	}

	private void moved(int x, int y, long ms)
	{
		c.mouseMoved(new MouseEvent(SOURCE, MouseEvent.MOUSE_MOVED, ms, 0, x, y, 0, false, MouseEvent.NOBUTTON));
	}

	private StickSim stick()
	{
		return new StickSim(this::moved, 400, 300, now);
	}

	private SkateInput drain(long at)
	{
		now = at;
		SkateInput in = new SkateInput();
		c.drainInto(in);
		return in;
	}

	private void controllerMode()
	{
		c.configureController(true, KeyEvent.VK_B);
		c.setEnabled(true);
	}

	@Test
	public void aStickFlickWithNoButtonIsATrickInControllerMode()
	{
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		SkateInput in = drain(s.ms);
		assertEquals(1, in.gestures.size());
		assertEquals(Direction.UP, in.gestures.get(0).direction);
	}

	@Test
	public void aStickFlickWithShiftHeldIsTheHardTrickJustLikeAMouseFlick()
	{
		// LB / RB send Shift: the stick path shares the same GestureRecognizer (and its modifier) as mouse flicks,
		// so a held Shift makes a stick flick the hard version exactly as it would a right-drag flick.
		controllerMode();
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		StickSim s = stick().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		SkateInput in = drain(s.ms);
		assertEquals(1, in.gestures.size());
		assertEquals(Direction.UP, in.gestures.get(0).direction);
		assertTrue("Shift held makes it the hard trick", in.gestures.get(0).modified);
	}

	@Test
	public void theSameMotionOutsideControllerModeIsNoTrick()
	{
		c.setEnabled(true);
		StickSim s = stick().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		assertTrue(drain(s.ms).gestures.isEmpty());
	}

	@Test
	public void mirroredFlicksAreMirroredFromTheStickToo()
	{
		c.configureTricks(GielinorSkateConfig.TrickControls.MOUSE, GielinorSkateConfig.FlickButton.RIGHT, true);
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 80).tilt(-0.85, -0.85, 80).rest(100);
		assertEquals(Direction.UP_RIGHT, drain(s.ms).gestures.get(0).direction);
	}

	@Test
	public void keyboardOnlyTrickControlsMakeNoStickFlicks()
	{
		c.configureTricks(GielinorSkateConfig.TrickControls.KEYBOARD, GielinorSkateConfig.FlickButton.RIGHT, false);
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		assertTrue(drain(s.ms).gestures.isEmpty());
	}

	@Test
	public void aSmallHeldTiltUpIsAManualAndDownANoseManual()
	{
		controllerMode();
		StickSim s = stick().tilt(0, -0.12, 300);
		SkateInput in = drain(s.ms);
		assertTrue(in.manualHeld);
		assertFalse(in.noseManualHeld);
		s.rest(ControllerStick.STOP_MS + 10);
		in = drain(s.ms);
		assertFalse("releasing the stick ends it", in.manualHeld);

		s.tilt(0, 0.12, 300);
		in = drain(s.ms);
		assertTrue(in.manualHeld);
		assertTrue(in.noseManualHeld);
		assertFalse("the nose manual never pushes", in.pushHeld);
		assertFalse("nor crouches", in.crouch);
	}

	@Test
	public void spaceStillDoesAManualInControllerMode()
	{
		controllerMode();
		c.keyPressed(key(KeyEvent.VK_SPACE, true));
		assertTrue(drain(now).manualHeld);
	}

	@Test
	public void theSlowStartOfAStickManualDoesNotCrouch()
	{
		controllerMode();
		StickSim s = stick().tilt(0, 0.12, 200);
		SkateInput in = drain(s.ms);
		assertFalse(in.crouch);
		assertFalse(in.charge);
	}

	@Test
	public void aFastStickPullCrouchesLikeAMouseWindUp()
	{
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 60);
		SkateInput in = drain(s.ms);
		assertTrue(in.crouch);
		assertTrue(in.charge);
	}

	@Test
	public void stickMotionWithAGrabHeldAimsTheGrabAndIsNeverAFlick()
	{
		controllerMode();
		moved(400, 300, now);
		c.keyPressed(key(KeyEvent.VK_Q, true));
		StickSim s = stick().tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		SkateInput in = drain(s.ms);
		assertTrue(in.gestures.isEmpty());
		assertNotNull("it aimed the grab", in.grabAim);
		c.keyReleased(key(KeyEvent.VK_Q, false));
		assertTrue(drain(s.ms + 200).gestures.isEmpty());
	}

	@Test
	public void rollingWithAGrabHeldTheStickFlicksAgainAfterTheAimWindow()
	{
		controllerMode();
		c.setRolling(true);
		moved(400, 300, now);
		c.keyPressed(key(KeyEvent.VK_Q, true));
		// within the aim window the stick aims the rolling grab, as in the air
		StickSim s = stick().tilt(FULL, 0, 60).rest(200);
		SkateInput in = drain(s.ms);
		assertTrue(in.gestures.isEmpty());
		assertNotNull(in.grabAim);
		// past it (the key auto-repeating) a flick pops out of the rolling grab
		now = s.ms;
		c.keyPressed(key(KeyEvent.VK_Q, true));
		s.tilt(0, FULL, 80);
		c.keyPressed(key(KeyEvent.VK_Q, true));
		s.tilt(0, -FULL, 80).rest(100);
		in = drain(s.ms);
		assertEquals(1, in.gestures.size());
		assertEquals(Direction.UP, in.gestures.get(0).direction);
		assertTrue("still grabbing", in.grabLeft);
	}

	@Test
	public void inTheAirTheStickWithAGrabHeldNeverFlicks()
	{
		controllerMode();
		c.setRolling(false);
		moved(400, 300, now);
		c.keyPressed(key(KeyEvent.VK_Q, true));
		StickSim s = stick().rest(300).tilt(0, FULL, 80).tilt(0, -FULL, 80).rest(100);
		assertTrue(drain(s.ms).gestures.isEmpty());
	}

	@Test
	public void pressingAGrabMidFlickDropsTheFlick()
	{
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 80);
		c.keyPressed(key(KeyEvent.VK_E, true));
		s.tilt(0, -FULL, 80).rest(100);
		assertTrue(drain(s.ms).gestures.isEmpty());
	}

	@Test
	public void aRightDragStillFlicksInControllerModeAndTheStickNeverEndsIt()
	{
		controllerMode();
		StickSim s = stick().tilt(0, 0.12, 100);
		c.mousePressed(new MouseEvent(SOURCE, MouseEvent.MOUSE_PRESSED, s.ms, InputEvent.BUTTON3_DOWN_MASK, 400, 312,
			1, false, MouseEvent.BUTTON3));
		SkateInput in = drain(s.ms + 500);
		assertTrue(drain(s.ms + 500).gestures.isEmpty());
		c.mouseDragged(new MouseEvent(SOURCE, MouseEvent.MOUSE_DRAGGED, s.ms + 550, InputEvent.BUTTON3_DOWN_MASK, 400,
			342, 1, false, MouseEvent.BUTTON3));
		c.mouseDragged(new MouseEvent(SOURCE, MouseEvent.MOUSE_DRAGGED, s.ms + 620, InputEvent.BUTTON3_DOWN_MASK, 400,
			307, 1, false, MouseEvent.BUTTON3));
		in = drain(s.ms + 630);
		assertEquals(1, in.gestures.size());
		assertEquals(Direction.UP, in.gestures.get(0).direction);
	}

	@Test
	public void arrowsAreLeanOnlyInControllerMode()
	{
		controllerMode();
		KeyEvent up = key(KeyEvent.VK_UP, true);
		c.keyPressed(up);
		assertTrue(up.isConsumed());
		SkateInput in = drain(now);
		assertTrue(in.leanForwardKey);
		assertFalse("the left stick up never pushes", in.pushHeld);
		assertFalse(in.pushPressed);
		c.keyReleased(key(KeyEvent.VK_UP, false));
		c.keyPressed(key(KeyEvent.VK_DOWN, true));
		in = drain(now);
		assertTrue(in.leanBackKey);
		assertFalse("the left stick down never crouches", in.crouch);
		assertFalse(in.leanBack);
		c.keyReleased(key(KeyEvent.VK_DOWN, false));
		in = drain(now);
		assertFalse(in.leanBackKey);
		assertFalse(in.leanForwardKey);
	}

	@Test
	public void wRemappedToTheUpArrowByKeyRemappingStillPushesInControllerMode()
	{
		// Key Remapping rewrites W's key code to VK_UP but leaves its key char: that is the A button, not the stick
		controllerMode();
		c.keyPressed(key(KeyEvent.VK_UP, 'w', true));
		SkateInput in = drain(now);
		assertTrue(in.pushHeld);
		assertTrue(in.pushPressed);
		c.keyReleased(key(KeyEvent.VK_UP, 'w', false));
		assertFalse(drain(now).pushHeld);
	}

	@Test
	public void theBrakeKeyAloneBrakesStraightAway()
	{
		controllerMode();
		KeyEvent b = key(KeyEvent.VK_B, true);
		c.keyPressed(b);
		assertTrue(b.isConsumed());
		SkateInput in = drain(now);
		assertTrue(in.powerslide);
		assertFalse(in.brakeBlocked);
		c.keyReleased(key(KeyEvent.VK_B, false));
		in = drain(now);
		assertFalse(in.powerslide);
	}

	@Test
	public void theBrakeKeyWithSteerCarvesTightAndWithPushNeverFlips()
	{
		controllerMode();
		c.keyPressed(key(KeyEvent.VK_B, true));
		c.keyPressed(key(KeyEvent.VK_A, true));
		SkateInput in = drain(now);
		assertTrue(in.powerslide);
		assertTrue("steering: not a brake", in.brakeBlocked);
		c.keyReleased(key(KeyEvent.VK_A, false));
		c.keyPressed(key(KeyEvent.VK_W, true));
		in = drain(now);
		// Shift+W is a front flip in the air; the brake key is only ever a brake
		assertFalse(in.powerslide);
	}

	@Test
	public void theBrakeKeyBrakesWhileTheRightStickMoves()
	{
		controllerMode();
		StickSim s = stick().tilt(0, FULL, 80);
		c.keyPressed(key(KeyEvent.VK_B, true));
		SkateInput in = drain(s.ms);
		assertTrue(in.powerslide);
		assertFalse("a stick stroke is no steer: B still brakes", in.brakeBlocked);
	}

	@Test
	public void theManualKeyWinsOverABrakeKeyOnTheSameKey()
	{
		c.configureController(false, KeyEvent.VK_C);
		c.configure(KeyEvent.VK_C, 100);
		c.setEnabled(true);
		c.keyPressed(key(KeyEvent.VK_C, true));
		SkateInput in = drain(now);
		assertTrue(in.manualHeld);
		assertFalse(in.powerslide);
	}

	@Test
	public void aTrickKeyWinsOverABrakeKeyOnTheSameKey()
	{
		c.configureController(false, KeyEvent.VK_1);
		c.configureTricks(GielinorSkateConfig.TrickControls.KEYBOARD, GielinorSkateConfig.FlickButton.RIGHT, false);
		c.setEnabled(true);
		c.keyPressed(key(KeyEvent.VK_1, true));
		assertFalse(drain(now).powerslide);
	}

	@Test
	public void aBrakeKeyOnALeanKeyLeansAndBrakes()
	{
		c.configureController(false, KeyEvent.VK_K);
		c.configureLeanKeys(KeyEvent.VK_K, KeyEvent.VK_DOWN);
		c.setEnabled(true);
		c.keyPressed(key(KeyEvent.VK_K, true));
		SkateInput in = drain(now);
		assertTrue(in.leanForwardKey);
		assertTrue(in.powerslide);
	}

	@Test
	public void theBrakeKeyWorksOnTheKeyboardOutsideControllerModeToo()
	{
		c.setEnabled(true);
		c.keyPressed(key(KeyEvent.VK_B, true));
		SkateInput in = drain(now);
		assertTrue(in.powerslide);
		assertFalse(in.brakeBlocked);
	}

	@Test
	public void shiftKeepsItsBrakeDelayAndModifier()
	{
		controllerMode();
		c.keyPressed(key(KeyEvent.VK_SHIFT, true));
		SkateInput in = drain(now);
		assertTrue(in.powerslide);
		assertTrue("Shift alone still waits before braking", in.brakeBlocked);
		in = drain(now + InputController.BRAKE_DELAY_MS);
		assertFalse(in.brakeBlocked);
	}

	@Test
	public void anUnsetBrakeKeyDoesNothing()
	{
		c.configureController(false, KeyEvent.VK_UNDEFINED);
		c.setEnabled(true);
		KeyEvent b = key(KeyEvent.VK_B, true);
		c.keyPressed(b);
		assertFalse(b.isConsumed());
		assertFalse(drain(now).powerslide);
	}

	@Test
	public void aBrakeKeyOnASkateKeyIsIgnored()
	{
		c.configureController(true, KeyEvent.VK_W);
		c.setEnabled(true);
		c.keyPressed(key(KeyEvent.VK_W, true));
		SkateInput in = drain(now);
		assertTrue(in.pushHeld);
		assertFalse(in.powerslide);
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.GielinorSkateConfig;
import com.gielinorskate.physics.SkateInput;
import java.awt.Canvas;
import java.awt.Component;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import org.junit.Test;

/** The board key and the on-foot reading of the keys. */
public class InputControllerOnFootTest
{
	private static final Component SOURCE = new Canvas();

	private long now = 1000;
	private final InputController c = new InputController(() -> now);

	private static KeyEvent key(int code, boolean pressed)
	{
		return key(code, KeyEvent.CHAR_UNDEFINED, pressed);
	}

	private static KeyEvent key(int code, char ch, boolean pressed)
	{
		return new KeyEvent(SOURCE, pressed ? KeyEvent.KEY_PRESSED : KeyEvent.KEY_RELEASED, 0, 0, code, ch);
	}

	private KeyEvent press(int code)
	{
		KeyEvent e = key(code, true);
		c.keyPressed(e);
		return e;
	}

	private KeyEvent release(int code)
	{
		KeyEvent e = key(code, false);
		c.keyReleased(e);
		return e;
	}

	private FootControls foot()
	{
		FootControls f = new FootControls();
		c.drainFoot(f);
		return f;
	}

	private BoardKey.Edges board(long at)
	{
		now = at;
		BoardKey.Edges e = new BoardKey.Edges();
		c.pollBoardKey(e);
		return e;
	}

	@Test
	public void fIsTheBoardKeyAndIsConsumedOnTheBoard()
	{
		c.setEnabled(true);
		KeyEvent e = press(KeyEvent.VK_F);
		assertTrue(e.isConsumed());
		assertTrue(board(1010).pressed);
		release(KeyEvent.VK_F);
		assertTrue(board(1020).tapped);
	}

	@Test
	public void holdingFOneSecondIsAHold()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_F);
		assertTrue(board(1001).pressed);
		// key repeats while held
		press(KeyEvent.VK_F);
		assertFalse(board(1999).held);
		assertTrue(board(2000).held);
		release(KeyEvent.VK_F);
		BoardKey.Edges after = board(2100);
		assertFalse(after.tapped);
		assertFalse(after.held);
	}

	@Test
	public void anUnsetBoardKeyDoesNothing()
	{
		c.configureBoardKey(KeyEvent.VK_UNDEFINED);
		c.setEnabled(true);
		assertFalse(press(KeyEvent.VK_F).isConsumed());
		assertFalse(board(1010).pressed);
	}

	@Test
	public void wasdWalkAndShiftSprintsOnFoot()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_W);
		press(KeyEvent.VK_A);
		press(KeyEvent.VK_SHIFT);
		FootControls f = foot();
		assertTrue(f.forward);
		assertTrue(f.left);
		assertFalse(f.back);
		assertFalse(f.right);
		assertTrue(f.sprint);
		release(KeyEvent.VK_W);
		press(KeyEvent.VK_S);
		press(KeyEvent.VK_D);
		f = foot();
		assertFalse(f.forward);
		assertTrue(f.back);
		assertTrue(f.right);
	}

	@Test
	public void keyRemappingsArrowsWalkToo()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		// Key Remapping rewrites W to the Up arrow, keeping the letter
		c.keyPressed(key(KeyEvent.VK_UP, 'w', true));
		assertTrue(foot().forward);
		c.keyReleased(key(KeyEvent.VK_UP, 'w', false));
		c.keyPressed(key(KeyEvent.VK_DOWN, 's', true));
		FootControls f = foot();
		assertFalse(f.forward);
		assertTrue(f.back);
	}

	@Test
	public void controllerModesLeanArrowsWalkForwardAndBack()
	{
		c.configureController(true, KeyEvent.VK_B);
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_UP);
		assertTrue(foot().forward);
		release(KeyEvent.VK_UP);
		press(KeyEvent.VK_DOWN);
		FootControls f = foot();
		assertFalse(f.forward);
		assertTrue(f.back);
	}

	@Test
	public void spaceJumpsOnFootOncePerPressAndIsNoTrick()
	{
		c.configureTricks(GielinorSkateConfig.TrickControls.BOTH, GielinorSkateConfig.FlickButton.RIGHT, false);
		c.setEnabled(true);
		c.setOnFoot(true);
		assertTrue(press(KeyEvent.VK_SPACE).isConsumed());
		press(KeyEvent.VK_SPACE);
		assertTrue(foot().jumpPressed);
		assertFalse(foot().jumpPressed);
		release(KeyEvent.VK_SPACE);
		SkateInput in = new SkateInput();
		c.drainInto(in);
		assertTrue("no ollie fired", in.gestures.isEmpty());
		assertFalse("no manual", in.manualHeld);
		press(KeyEvent.VK_SPACE);
		assertTrue(foot().jumpPressed);
	}

	@Test
	public void spaceOnTheBoardIsNoJump()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_SPACE);
		SkateInput in = new SkateInput();
		c.drainInto(in);
		assertTrue("still the manual", in.manualHeld);
		release(KeyEvent.VK_SPACE);
		c.setOnFoot(true);
		assertFalse(foot().jumpPressed);
	}

	@Test
	public void spaceHeldAcrossADismountIsNotANewJump()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_SPACE);
		c.setOnFoot(true);
		press(KeyEvent.VK_SPACE); // a key repeat
		assertFalse(foot().jumpPressed);
	}

	@Test
	public void qAndEDropOrPickUpOnFootOnly()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_Q);
		release(KeyEvent.VK_Q);
		c.setOnFoot(true);
		assertFalse("a grab on the board is no drop", foot().dropPickupPressed);
		press(KeyEvent.VK_E);
		press(KeyEvent.VK_E);
		assertTrue(foot().dropPickupPressed);
		assertFalse("once per press", foot().dropPickupPressed);
		release(KeyEvent.VK_E);
		press(KeyEvent.VK_Q);
		assertTrue(foot().dropPickupPressed);
	}

	@Test
	public void switchingModesDropsPendingEdges()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_SPACE);
		press(KeyEvent.VK_Q);
		c.setOnFoot(false);
		c.setOnFoot(true);
		FootControls f = foot();
		assertFalse(f.jumpPressed);
		assertFalse(f.dropPickupPressed);
	}

	@Test
	public void escStillExitsOnFoot()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_ESCAPE);
		assertTrue(c.consumeExit());
	}

	@Test
	public void enablingStartsOnTheBoard()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		c.setEnabled(true);
		press(KeyEvent.VK_SPACE);
		assertFalse(foot().jumpPressed);
	}

	@Test
	public void boardKeyFollowsTheConfiguredKey()
	{
		c.configureBoardKey(KeyEvent.VK_G);
		c.setEnabled(true);
		assertFalse(press(KeyEvent.VK_F).isConsumed());
		assertTrue(press(KeyEvent.VK_G).isConsumed());
		assertEquals(true, board(1010).pressed);
	}

	@Test
	public void aBoardKeyOnEscStillLetsEscExitAndFIsTheBoardKey()
	{
		c.configureBoardKey(KeyEvent.VK_ESCAPE);
		c.setEnabled(true);
		press(KeyEvent.VK_ESCAPE);
		assertTrue(c.consumeExit());
		assertFalse(board(1010).pressed);
		assertTrue(press(KeyEvent.VK_F).isConsumed());
		assertTrue(board(1020).pressed);
	}

	@Test
	public void aBoardKeyOnAHardCodedSkateKeyLeavesThatKeyAlone()
	{
		for (int code : new int[]{KeyEvent.VK_W, KeyEvent.VK_A, KeyEvent.VK_S, KeyEvent.VK_D, KeyEvent.VK_SHIFT,
			KeyEvent.VK_Q, KeyEvent.VK_E, KeyEvent.VK_H, KeyEvent.VK_R, KeyEvent.VK_UP, KeyEvent.VK_SPACE})
		{
			assertEquals(KeyEvent.VK_F, InputController.effectiveBoardKey(code, false));
		}
		c.configureBoardKey(KeyEvent.VK_W);
		c.setEnabled(true);
		press(KeyEvent.VK_W);
		SkateInput in = new SkateInput();
		c.drainInto(in);
		assertTrue(in.pushPressed);
		assertFalse(board(1010).pressed);
	}

	@Test
	public void spaceIsNeverTheBoardKeySoItStillJumpsOnFoot()
	{
		c.configureBoardKey(KeyEvent.VK_SPACE);
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_SPACE);
		assertTrue(foot().jumpPressed);
		assertFalse(board(1010).pressed);
	}

	@Test
	public void withKeyboardTricksATrickKeyIsNotTheBoardKey()
	{
		assertEquals(KeyEvent.VK_1, InputController.effectiveBoardKey(KeyEvent.VK_1, false));
		assertEquals(KeyEvent.VK_F, InputController.effectiveBoardKey(KeyEvent.VK_1, true));
		c.configureBoardKey(KeyEvent.VK_1);
		c.configureTricks(GielinorSkateConfig.TrickControls.KEYBOARD, GielinorSkateConfig.FlickButton.RIGHT, false);
		c.setEnabled(true);
		press(KeyEvent.VK_1);
		assertFalse(board(1010).pressed);
		release(KeyEvent.VK_1);
		SkateInput in = new SkateInput();
		c.drainInto(in);
		assertEquals(1, in.gestures.size());
		// switching keyboard tricks off gives the key back to the board
		c.configureTricks(GielinorSkateConfig.TrickControls.MOUSE, GielinorSkateConfig.FlickButton.RIGHT, false);
		press(KeyEvent.VK_1);
		assertTrue(board(1020).pressed);
	}

	@Test
	public void anUnsetBoardKeyStaysUnset()
	{
		assertEquals(KeyEvent.VK_UNDEFINED, InputController.effectiveBoardKey(KeyEvent.VK_UNDEFINED, true));
		assertEquals(KeyEvent.VK_G, InputController.effectiveBoardKey(KeyEvent.VK_G, true));
	}

	@Test
	public void changingTheBoardKeyWhileItIsHeldDoesNotLeaveItStuck()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_F);
		board(1010);
		c.configureBoardKey(KeyEvent.VK_G);
		release(KeyEvent.VK_F);
		press(KeyEvent.VK_G);
		assertTrue(board(1020).pressed);
	}

	private static MouseEvent middle(int id, int x, int y)
	{
		return new MouseEvent(SOURCE, id, 0, InputEvent.BUTTON2_DOWN_MASK, x, y, 1, false, MouseEvent.BUTTON2);
	}

	@Test
	public void middleDragOrbitsTheCameraOnFoot()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		MouseEvent down = middle(MouseEvent.MOUSE_PRESSED, 100, 100);
		c.mousePressed(down);
		assertTrue(down.isConsumed());
		c.mouseDragged(middle(MouseEvent.MOUSE_DRAGGED, 130, 105));
		c.mouseDragged(middle(MouseEvent.MOUSE_DRAGGED, 110, 90));
		assertEquals(10, c.drainOrbitPixels());
		assertEquals(0, c.drainOrbitPixels());
		c.mouseReleased(middle(MouseEvent.MOUSE_RELEASED, 110, 90));
		c.mouseDragged(middle(MouseEvent.MOUSE_DRAGGED, 200, 90));
		assertEquals(0, c.drainOrbitPixels());
	}

	@Test
	public void middleDragDoesNotOrbitOnTheBoard()
	{
		c.setEnabled(true);
		c.mousePressed(middle(MouseEvent.MOUSE_PRESSED, 100, 100));
		c.mouseDragged(middle(MouseEvent.MOUSE_DRAGGED, 160, 100));
		assertEquals(0, c.drainOrbitPixels());
	}

	@Test
	public void gettingOnTheBoardEndsAnOrbit()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		c.mousePressed(middle(MouseEvent.MOUSE_PRESSED, 100, 100));
		c.setOnFoot(false);
		c.mouseDragged(middle(MouseEvent.MOUSE_DRAGGED, 160, 100));
		assertEquals(0, c.drainOrbitPixels());
	}
}

package com.gielinorskate.input;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.controller.PadAction;
import com.gielinorskate.controller.PadButton;
import com.gielinorskate.controller.PadContext;
import com.gielinorskate.controller.PadPreset;
import com.gielinorskate.physics.SkateInput;
import com.gielinorskate.tricks.Gesture;
import java.awt.Canvas;
import java.awt.Component;
import java.awt.event.KeyEvent;
import java.awt.event.MouseEvent;
import org.junit.Before;
import org.junit.Test;

/**
 * The pad keys (one per controller button, see {@link PadButton}) turned into actions by the preset: only in
 * controller mode, and never on a key another key setting uses.
 */
public class InputControllerPadKeysTest
{
	private static final Component SOURCE = new Canvas();
	private static final int PAD_A = PadButton.A.keyCode;
	private static final int PAD_X = PadButton.X.keyCode;

	private long now = 1000;
	private final InputController c = new InputController(() -> now);

	@Before
	public void controllerMode()
	{
		c.configureController(true, KeyEvent.VK_B);
	}

	private KeyEvent press(int code)
	{
		KeyEvent e = new KeyEvent(SOURCE, KeyEvent.KEY_PRESSED, 0, 0, code, KeyEvent.CHAR_UNDEFINED);
		c.keyPressed(e);
		return e;
	}

	private KeyEvent release(int code)
	{
		KeyEvent e = new KeyEvent(SOURCE, KeyEvent.KEY_RELEASED, 0, 0, code, KeyEvent.CHAR_UNDEFINED);
		c.keyReleased(e);
		return e;
	}

	private SkateInput skate()
	{
		SkateInput in = new SkateInput();
		c.drainInto(in);
		return in;
	}

	private FootControls foot()
	{
		FootControls f = new FootControls();
		c.drainFoot(f);
		return f;
	}

	@Test
	public void everyPadKeyIsReadAndNeverTypedInControllerMode()
	{
		c.setEnabled(true);
		for (PadButton b : PadButton.values())
		{
			assertTrue(b.label, press(b.keyCode).isConsumed());
			assertTrue(b.label, release(b.keyCode).isConsumed());
		}
	}

	@Test
	public void padAPushesOnTheBoardTapOrHold()
	{
		c.setEnabled(true);
		assertTrue(press(PAD_A).isConsumed());
		SkateInput in = skate();
		assertTrue(in.pushPressed);
		assertTrue(in.pushHeld);
		// a key repeat while held is no new push
		press(PAD_A);
		in = skate();
		assertFalse(in.pushPressed);
		assertTrue(in.pushHeld);
		assertTrue(release(PAD_A).isConsumed());
		assertFalse(skate().pushHeld);
	}

	@Test
	public void padXPushesOnTheBoardTooAndIsNoManual()
	{
		c.setEnabled(true);
		press(PAD_X);
		SkateInput in = skate();
		assertTrue(in.pushPressed);
		assertTrue(in.pushHeld);
		assertFalse(in.manualHeld);
		assertFalse(in.powerslide);
		release(PAD_X);
		assertFalse(skate().pushHeld);
	}

	@Test
	public void releasingOnePushButtonKeepsTheOtherHeld()
	{
		c.setEnabled(true);
		press(KeyEvent.VK_W);
		press(PAD_A);
		release(PAD_A);
		assertTrue(skate().pushHeld);
		press(PAD_X);
		release(KeyEvent.VK_W);
		assertTrue(skate().pushHeld);
		release(PAD_X);
		assertFalse(skate().pushHeld);
	}

	@Test
	public void padBBrakesAtOnceAndPadPushBlocksIt()
	{
		c.setEnabled(true);
		press(PadButton.B.keyCode);
		SkateInput in = skate();
		assertTrue(in.powerslide);
		assertFalse(in.brakeBlocked);
		press(PAD_A);
		in = skate();
		assertFalse(in.powerslide);
		assertTrue(in.brakeBlocked);
	}

	@Test
	public void onFootPadASprintsWhileHeldAndDoesNotWalk()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(PAD_A);
		FootControls f = foot();
		assertTrue(f.sprint);
		assertFalse(f.forward);
		assertFalse(f.jumpPressed);
		release(PAD_A);
		assertFalse(foot().sprint);
	}

	@Test
	public void onFootPadXJumpsOncePerPressAndDoesNotWalk()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(PAD_X);
		FootControls f = foot();
		assertTrue(f.jumpPressed);
		assertFalse(f.forward);
		assertFalse(f.sprint);
		press(PAD_X);
		assertFalse(foot().jumpPressed);
		release(PAD_X);
		press(PAD_X);
		assertTrue(foot().jumpPressed);
	}

	@Test
	public void onFootThePushButtonsDoNotPush()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(PAD_A);
		press(PAD_X);
		SkateInput in = skate();
		assertFalse(in.pushPressed);
		assertFalse(in.pushHeld);
	}

	@Test
	public void aButtonHeldAcrossADismountDoesItsOnFootActionButIsNoNewPress()
	{
		c.setEnabled(true);
		press(PAD_X);
		press(PAD_A);
		c.setOnFoot(true);
		press(PAD_X);
		FootControls f = foot();
		assertFalse(f.jumpPressed);
		assertTrue(f.sprint);
	}

	@Test
	public void theKeyboardControlsAreUnchanged()
	{
		c.setEnabled(true);
		c.setOnFoot(true);
		press(KeyEvent.VK_SHIFT);
		press(KeyEvent.VK_SPACE);
		FootControls f = foot();
		assertTrue(f.sprint);
		assertTrue(f.jumpPressed);
		release(KeyEvent.VK_SHIFT);
		c.setOnFoot(false);
		release(KeyEvent.VK_SPACE);
		press(KeyEvent.VK_W);
		SkateInput in = skate();
		assertTrue(in.pushPressed);
		assertTrue(in.pushHeld);
	}

	@Test
	public void withControllerModeOffThePadKeysAreOrdinaryKeys()
	{
		c.configureController(false, KeyEvent.VK_B);
		c.setEnabled(true);
		for (PadButton b : PadButton.values())
		{
			assertFalse(b.label, press(b.keyCode).isConsumed());
		}
		assertFalse(skate().pushHeld);
		c.setOnFoot(true);
		press(PAD_X);
		assertFalse(foot().jumpPressed);
	}

	@Test
	public void withControllerModeOffAManualKeyOnAPadKeyIsStillTheManual()
	{
		c.configureController(false, KeyEvent.VK_B);
		c.configure(PAD_A, 100);
		c.setEnabled(true);
		assertTrue(press(PAD_A).isConsumed());
		SkateInput in = skate();
		assertTrue(in.manualHeld);
		assertFalse(in.pushHeld);
	}

	@Test
	public void aKeySettingOnAPadKeyWinsOverItsButton()
	{
		c.configure(PAD_A, 100);
		c.setEnabled(true);
		press(PAD_A);
		SkateInput in = skate();
		assertTrue(in.manualHeld);
		assertFalse(in.pushHeld);
		release(PAD_A);

		c.configure(KeyEvent.VK_SPACE, 100);
		c.configureController(true, PAD_X);
		press(PAD_X);
		in = skate();
		assertFalse(in.pushHeld);
		assertTrue(in.powerslide);
		release(PAD_X);

		c.configureController(true, KeyEvent.VK_B);
		c.configureLeanKeys(PAD_A, PAD_X);
		press(PAD_A);
		in = skate();
		assertTrue(in.leanForwardKey);
		assertFalse(in.pushHeld);
		release(PAD_A);

		c.configureLeanKeys(KeyEvent.VK_UP, KeyEvent.VK_DOWN);
		c.configureBoardKey(PAD_X);
		press(PAD_X);
		assertFalse(skate().pushHeld);
		BoardKey.Edges e = new BoardKey.Edges();
		c.pollBoardKey(e);
		assertTrue(e.pressed);
		// the other buttons are still read
		press(PadButton.B.keyCode);
		assertTrue(skate().powerslide);
	}

	@Test
	public void aPadKeyOnAPlainSkateModeKeyIsOffButNotOnOneWithModifiers()
	{
		c.configureToggleKey(PAD_A, 0);
		c.setEnabled(true);
