package com.gielinorskate.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class ControlsCardTimerTest
{
	@Test
	public void beforeSkateModeStartsAlphaIsZero()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		assertEquals(0f, t.alpha(0f), 0f);
		assertEquals(0f, t.alpha(100f), 0f);
	}

	@Test
	public void theBasicsPageStaysUpUntilThePlayerHasPushedAndJumped()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.onSkateStart(true);
		assertEquals(1f, t.alpha(500f), 0f);
		t.onPush(500f);
		assertEquals("pushing alone is not enough", 1f, t.alpha(900f), 0f);
		t.onJump(900f);
		assertTrue(t.learnedBasics());
		// lingers, then fades over a second
		assertEquals(1f, t.alpha(901.9f), 0f);
		assertEquals(0.5f, t.alpha(902.5f), 1e-4f);
		assertEquals(0f, t.alpha(903f), 0f);
	}

	@Test
	public void itComesBackNextSessionUntilTheBasicsAreLearned()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.onSkateStart(true);
		t.onPush(1f);
		t.onSkateStart(true);
		assertEquals(1f, t.alpha(10f), 0f);
		t.onJump(11f);
		t.onSkateStart(true);
		assertEquals(0f, t.alpha(100f), 0f);
	}

	@Test
	public void settingOffOrLearnedEarlierMeansNoAutoShow()
	{
		ControlsCardTimer off = new ControlsCardTimer();
		off.onSkateStart(false);
		assertEquals(0f, off.alpha(0f), 0f);

		ControlsCardTimer learned = new ControlsCardTimer();
		learned.markLearned();
		learned.onSkateStart(true);
		assertEquals(0f, learned.alpha(0f), 0f);
	}

	@Test
	public void hShowsTheCardThenHidesIt()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.toggle(0f);
		assertEquals(1f, t.alpha(0f), 0f);
		assertEquals("stays up while shown by H", 1f, t.alpha(1000f), 0f);
		t.toggle(1001f);
		assertEquals(0f, t.alpha(1001f), 0f);
		t.toggle(1002f);
		assertEquals(1f, t.alpha(1002f), 0f);
	}

	@Test
	public void hDuringTheAutoShowHidesIt()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.onSkateStart(true);
		assertEquals(1f, t.alpha(0.5f), 0f);
		t.toggle(1f);
		assertEquals(0f, t.alpha(1f), 0f);
		// learning the basics afterwards does not bring it back
		t.onPush(2f);
		t.onJump(2f);
		assertEquals(0f, t.alpha(3f), 0f);
	}

	@Test
	public void hShownCardIsNotFadedByLearningTheBasics()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.onSkateStart(true);
		t.toggle(1f);
		t.toggle(2f);
		t.onPush(3f);
		t.onJump(3f);
		assertEquals(1f, t.alpha(100f), 0f);
	}

	@Test
	public void aNewSessionDropsAnHShownCard()
	{
		ControlsCardTimer t = new ControlsCardTimer();
		t.markLearned();
		t.toggle(0f);
		t.onSkateStart(true);
		assertFalse(t.alpha(10f) > 0f);
	}
}

package com.gielinorskate.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.input.GestureRecognizer;
import com.gielinorskate.input.LiveStroke;
import com.gielinorskate.tricks.Gesture.Direction;
import org.junit.Test;

public class FlickVisualizerTest
{
	@Test
	public void theRingRadiusStandsForAWholeWindUpAndFlick()
	{
		// 48 px reach (18 + 30) on a 40 px ring: a 24 px pull down sits halfway down the ring
		float[] p = FlickVisualizer.toRing(0f, 24f, 48f, 40f);
		assertEquals(0f, p[0], 1e-4f);
		assertEquals(20f, p[1], 1e-4f);
	}

	@Test
	public void farOffsetsAreClampedToTheRingKeepingTheirDirection()
	{
		float[] p = FlickVisualizer.toRing(300f, -400f, 48f, 40f);
		assertEquals(40f, Math.hypot(p[0], p[1]), 1e-3);
		assertEquals(0.6f, p[0] / 40f, 1e-4f);
		assertEquals(-0.8f, p[1] / 40f, 1e-4f);
	}

	@Test
	public void trailFadesOverItsWindow()
	{
		assertEquals(1f, FlickVisualizer.trailAlpha(0), 0f);
		assertEquals(0.5f, FlickVisualizer.trailAlpha(150), 1e-4f);
		assertEquals(0f, FlickVisualizer.trailAlpha(300), 0f);
		assertEquals(0f, FlickVisualizer.trailAlpha(1000), 0f);
	}

	@Test
	public void flashFadesOverAQuarterSecond()
	{
		assertEquals(1f, FlickVisualizer.flashAlpha(0), 0f);
		assertEquals(0.5f, FlickVisualizer.flashAlpha(125), 1e-4f);
		assertEquals(0f, FlickVisualizer.flashAlpha(250), 0f);
	}

	@Test
	public void sectorsTileTheCircleAndMatchTheRecognizer()
	{
		double total = 0;
		for (Direction d : Direction.values())
		{
			total += FlickVisualizer.sector(d)[1];
		}
		assertEquals(360.0, total, 1e-9);
		// up is centred on 12 o'clock, up-left between up and left, right on 3 o'clock
		double[] up = FlickVisualizer.sector(Direction.UP);
		assertEquals(90.0, up[0] + up[1] / 2, 1e-9);
		assertEquals(2 * GestureRecognizer.OLLIE_SECTOR_DEG, up[1], 1e-9);
		double[] right = FlickVisualizer.sector(Direction.RIGHT);
		assertEquals(0.0, right[0] + right[1] / 2, 1e-9);
		double[] upLeft = FlickVisualizer.sector(Direction.UP_LEFT);
		assertEquals(135.0, upLeft[0] + upLeft[1] / 2, 1e-9);
		double[] downLeft = FlickVisualizer.sector(Direction.DOWN_LEFT);
		assertEquals(225.0, downLeft[0] + downLeft[1] / 2, 1e-9);
	}

	private static LiveStroke stroke(boolean held, Direction fired, long firedMs, long now)
	{
		return new LiveStroke(held, 0, 0, 0, 0, new float[0], new float[0], new long[0], false, false, 0, 0, fired,
			false, firedMs, 48f, now);
	}

	@Test
	public void visibleWhileHeldOrWhileTheWedgeFades()
	{
		assertTrue(FlickVisualizer.visible(stroke(true, null, 0, 1000)));
		assertTrue(FlickVisualizer.visible(stroke(false, Direction.UP, 900, 1000)));
		assertFalse(FlickVisualizer.visible(stroke(false, Direction.UP, 700, 1000)));
		assertFalse(FlickVisualizer.visible(stroke(false, null, 0, 1000)));
		assertFalse(FlickVisualizer.visible(null));
	}

	@Test
	public void recognizerLiveSnapshotTracksTheStroke()
	{
		GestureRecognizer r = new GestureRecognizer();
		r.begin(100, 200, 0);
		r.move(100, 230, 50);
		LiveStroke wound = r.live(50, FlickVisualizer.TRAIL_MS);
		assertTrue(wound.held);
		assertTrue(wound.wound);
		assertFalse(wound.nollie);
		assertEquals(30f, wound.y - wound.originY, 0f);
		assertEquals(GestureRecognizer.WIND_UP_PX + GestureRecognizer.FLICK_PX, wound.reachPx, 1e-4f);
		r.move(100, 195, 120);
		LiveStroke fired = r.live(400, FlickVisualizer.TRAIL_MS);
		assertEquals(Direction.UP, fired.firedDirection);
		assertEquals(120, fired.firedMs);
		// only the last 300 ms of path: the 120 ms sample, not the 0 and 50 ms ones
		assertEquals(1, fired.trailMs.length);
		r.end();
		assertFalse(r.live(500, FlickVisualizer.TRAIL_MS).held);
	}
}

package com.gielinorskate.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import com.gielinorskate.world.GrindSegment;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class GrindEdgesOverlayTest
{
	/** Top-down test projection: canvas = (x / 10, y / 10); the height must be passed through as given. */
	private float lastH;

	private Point project(float x, float y, float h)
	{
		lastH = h;
		return new Point(Math.round(x / 10f), Math.round(y / 10f));
	}

	private static BufferedImage render(GrindEdgesOverlay o)
	{
		BufferedImage img = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		o.render(g);
		g.dispose();
		return img;
	}

	private static boolean yellow(BufferedImage img, int x, int y)
	{
		return img.getRGB(x, y) == Color.YELLOW.getRGB();
	}

	@Test
	public void drawsEverySegmentAsAYellowLineAtItsTopWhenShown()
	{
		List<GrindSegment> segs = Arrays.asList(
			new GrindSegment(100, 200, 800, 200, 160),
			new GrindSegment(500, 300, 500, 900, 40));
		GrindEdgesOverlay o = new GrindEdgesOverlay(() -> true, () -> segs, this::project, () -> null);
		BufferedImage img = render(o);
		assertEquals("yellow at the first segment's middle", true, yellow(img, 45, 20));
		assertEquals("yellow at the second segment's middle", true, yellow(img, 50, 60));
		assertFalse(yellow(img, 5, 5));
		assertEquals(40f, lastH, 0f);
	}

	@Test
	public void drawsNothingAndReadsNothingWhenHidden()
	{
		GrindEdgesOverlay o = new GrindEdgesOverlay(() -> false, () ->
		{
			throw new AssertionError("segments read while hidden");
		}, this::project, () -> null);
		BufferedImage img = render(o);
		assertFalse(yellow(img, 45, 20));
	}

	@Test
	public void skipsSegmentsWithAnOffScreenEnd()
	{
		List<GrindSegment> segs = Collections.singletonList(new GrindSegment(100, 200, 800, 200, 60));
		GrindEdgesOverlay o = new GrindEdgesOverlay(() -> true, () -> segs, (x, y, h) -> x > 500 ? null : project(x, y, h), () -> null);
		BufferedImage img = render(o);
		assertFalse(yellow(img, 20, 20));
	}
}

package com.gielinorskate.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class HudLayoutTest
{
	@Test
	public void fixedModeViewportClampsRadiusToMinimum()
	{
		// fixed-mode viewport: 512 x 334 at (4, 4) on a 765 x 503 canvas
		// radius = round(334 * 0.045) = 15, clamped up to the 22px minimum
		HudLayout l = new HudLayout(4, 4, 512, 334, 765, 503, HudLayout.NO_OBSTACLE);
		assertEquals(22, l.ringRadius);
		assertEquals(4 + Math.round(512 * 0.09f) + 22, l.ringCenterX);
		assertEquals(4 + Math.round(334 * 0.78f), l.ringCenterY);
		assertEquals(l.ringCenterX - 22, l.stackLeftX);
		assertEquals(l.ringCenterY - 22 - Math.round(22 * 0.35f), l.stackBaselineY);
		assertEquals(l.ringCenterX + 22 + Math.round(22 * 0.6f), l.scoreLeftX);
		assertEquals(l.ringCenterY, l.ringCenterY);
		assertEquals(l.ringCenterY + 22 + Math.round(22 * 0.55f), l.totalY);
	}

	@Test
	public void resizableViewportIsNotTheCanvasCorner()
	{
		// radius = round(900 * 0.045) = 41, within the 22..48 clamp range
		HudLayout l = new HudLayout(0, 0, 1600, 900, 1600, 900, HudLayout.NO_OBSTACLE);
		assertEquals(41, l.ringRadius);
		assertEquals(Math.round(1600 * 0.09f) + 41, l.ringCenterX);
		assertEquals(Math.round(900 * 0.78f), l.ringCenterY);
		assertEquals(l.ringCenterX - 41, l.stackLeftX);
		assertEquals(l.ringCenterY - 41 - Math.round(41 * 0.35f), l.stackBaselineY);
		assertEquals(l.ringCenterX + 41 + Math.round(41 * 0.6f), l.scoreLeftX);
		assertEquals(l.ringCenterY + 41 + Math.round(41 * 0.55f), l.totalY);
	}

	@Test
	public void fallsBackToTheCanvasWithoutAViewport()
	{
		HudLayout l = new HudLayout(0, 0, 0, 0, 800, 600, HudLayout.NO_OBSTACLE);
		// radius = round(600 * 0.045) = 27, within the clamp range
		assertEquals(27, l.ringRadius);
		assertEquals(Math.round(800 * 0.09f) + 27, l.ringCenterX);
		assertEquals(Math.round(600 * 0.78f), l.ringCenterY);
		assertEquals(l.ringCenterX - 27, l.stackLeftX);
		assertEquals(l.ringCenterX + 27 + Math.round(27 * 0.6f), l.scoreLeftX);
	}

	@Test
	public void ringRadiusClampsToTheMaximumOnATallViewport()
	{
		HudLayout l = new HudLayout(0, 0, 3000, 2000, 3000, 2000, HudLayout.NO_OBSTACLE);
		assertEquals(48, l.ringRadius);
	}

	@Test
	public void calloutSitsCentredInTheUpperViewport()
	{
		HudLayout l = new HudLayout(4, 4, 512, 334, 765, 503, HudLayout.NO_OBSTACLE);
		assertEquals(4 + 256, l.calloutCenterX);
		assertEquals(4 + Math.round(334 * 0.3f), l.calloutBaselineY);
	}

	@Test
	public void xpDropsStayClearOfTheResizableMinimap()
	{
		// resizable: the viewport is the whole canvas and the minimap covers its top-right corner
		HudLayout resizable = new HudLayout(0, 0, 1600, 900, 1600, 900, HudLayout.NO_OBSTACLE);
		assertEquals(1600 - 240, resizable.xpDropRightX);
		// fixed: the minimap is outside the viewport
		HudLayout fixed = new HudLayout(4, 4, 512, 334, 765, 503, HudLayout.NO_OBSTACLE);
		assertEquals(4 + 512 - 8, fixed.xpDropRightX);
		assertEquals(4 + Math.round(334 * 0.32f), fixed.xpDropStartY);
		assertEquals(Math.round(334 * 0.18f), fixed.xpDropRise);
	}

	@Test
	public void withoutAChatboxTheClusterIsWhereItAlwaysWas()
	{
		HudLayout plain = new HudLayout(0, 0, 1600, 800, 1600, 800, HudLayout.NO_OBSTACLE);
		HudLayout none = new HudLayout(0, 0, 1600, 800, 1600, 800, HudLayout.NO_OBSTACLE);
		assertEquals(plain.ringCenterY, none.ringCenterY);
		assertEquals(plain.totalY, none.totalY);
		assertEquals(plain.stackBaselineY, none.stackBaselineY);
	}

	@Test
	public void resizableClusterRisesAboveTheChatbox()
	{
		// 800 px tall resizable canvas, chatbox top at 800 - 165 = 635: the old cluster ran into it
		HudLayout plain = new HudLayout(0, 0, 1600, 800, 1600, 800, HudLayout.NO_OBSTACLE);
		assertTrue(plain.clusterBottomY > 635);
		HudLayout l = new HudLayout(0, 0, 1600, 800, 1600, 800, 635);
		assertTrue(l.clusterBottomY <= 635 - 4);
		int shift = plain.ringCenterY - l.ringCenterY;
		assertTrue(shift > 0);
		// the whole cluster moves together; nothing else moves
		assertEquals(plain.totalY - shift, l.totalY);
		assertEquals(plain.stackBaselineY - shift, l.stackBaselineY);
		assertEquals(plain.stackTopY - shift, l.stackTopY);
		assertEquals(plain.ringCenterY - shift, l.ringCenterY);
		assertEquals(plain.ringCenterX, l.ringCenterX);
		assertEquals(plain.calloutBaselineY, l.calloutBaselineY);
		assertEquals(plain.xpDropStartY, l.xpDropStartY);
	}

	@Test
	public void aChatboxBelowTheClusterMovesNothing()
	{
		// fixed mode: the chatbox sits below the viewport
		HudLayout plain = new HudLayout(4, 4, 512, 334, 765, 503, HudLayout.NO_OBSTACLE);
		HudLayout l = new HudLayout(4, 4, 512, 334, 765, 503, 338);
		assertEquals(plain.ringCenterY, l.ringCenterY);
		assertEquals(plain.totalY, l.totalY);
	}

	@Test
	public void collapsedChatOnlyLiftsAboveTheTabRow()
	{
		// resizable with chat hidden: only the tab row (about 23 px) is left at the bottom
		HudLayout l = new HudLayout(0, 0, 1600, 800, 1600, 800, 777);
		assertTrue(l.clusterBottomY <= 777 - 4);
		HudLayout chatOpen = new HudLayout(0, 0, 1600, 800, 1600, 800, 635);
		assertTrue(l.ringCenterY > chatOpen.ringCenterY);
	}

	@Test
	public void neverRisesPastTheViewportTop()
	{
		// a tiny viewport with the chatbox almost at its top: the stack top stops at the viewport edge
		HudLayout l = new HudLayout(0, 0, 800, 300, 800, 300, 20);
		assertEquals(0, l.stackTopY);
	}
}

