package com.gielinorskate.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.feedback.HudAnim;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

/** Pop-in scales are snapped so Java2D can reuse its glyph rasters, without visibly changing the animation. */
public class ScoreScaleQuantiseTest
{
	@Test
	public void restingScaleIsExactlyOne()
	{
		assertEquals(Float.floatToRawIntBits(1f), Float.floatToRawIntBits(ScoreOverlay.quantiseScale(1f)));
		assertEquals(Float.floatToRawIntBits(1f), Float.floatToRawIntBits(ScoreOverlay.quantiseScale(HudAnim.popScale(1f))));
	}

	@Test
	public void snappedScaleIsWithinHalfAStep()
	{
		for (float s = 0.5f; s <= 2f; s += 0.0013f)
		{
			float q = ScoreOverlay.quantiseScale(s);
			assertTrue(s + " -> " + q, Math.abs(q - s) <= 0.5f / ScoreOverlay.SCALE_STEPS + 1e-6f);
		}
	}

	@Test
	public void aPopUsesABoundedSetOfScales()
	{
		Set<Float> trick = new HashSet<>();
		Set<Float> callout = new HashSet<>();
		for (int frame = 0; frame < 2000; frame++)
		{
			float age = frame / 10000f;
			trick.add(ScoreOverlay.quantiseScale(HudAnim.popScale(age)));
			callout.add(ScoreOverlay.quantiseScale(HudAnim.calloutScale(age)));
		}
		// 1.35 down past ~0.9 and back to 1: a bounded handful of strikes, not one per frame
		assertTrue("trick scales " + trick.size(), trick.size() <= 25);
		assertTrue("callout scales " + callout.size(), callout.size() <= 25);
		assertTrue(trick.contains(1f));
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import org.junit.Test;

public class BodyFlipMeterTest
{
	/** SkatePhysics' body flip rate: a whole flip in 0.55 s. */
	private static final float HELD = Angles.TWO_PI / 0.55f;

	@Test
	public void aHeldFlipIsMeasuredAndItsStartAndReleaseAreFlagged()
	{
		BodyFlipMeter m = new BodyFlipMeter();
		m.update(0f, true, 0.02f);
		assertFalse(m.directionChanged());
		m.update(HELD * 0.04f, true, 0.04f);
		assertEquals(HELD, m.rate(), 1e-3f);
		assertTrue("the flip started", m.directionChanged());
		m.update(HELD * 0.06f, true, 0.02f);
		assertFalse(m.directionChanged());
		// released inside the assist window: easing at 3 rad/s is not a held flip
		m.update(HELD * 0.06f + 3f * 0.02f, true, 0.02f);
		assertEquals(3f, m.rate(), 1e-3f);
		assertTrue("the flip was released", m.directionChanged());
		// a frame without a physics step keeps the rate
		m.update(HELD * 0.06f + 3f * 0.02f, true, 0f);
		assertEquals(3f, m.rate(), 1e-3f);
		assertFalse(m.directionChanged());
	}

	@Test
	public void backflipsAreNegativeAndTheGroundIsZero()
	{
		BodyFlipMeter m = new BodyFlipMeter();
		m.update(0f, true, 0.02f);
		m.update(-HELD * 0.02f, true, 0.02f);
		assertEquals(-HELD, m.rate(), 1e-3f);
		assertEquals(-1, m.direction());
		// landing resets the angle to 0: not a rotation
		m.update(0f, false, 0.02f);
		assertEquals(0f, m.rate(), 0f);
		assertEquals(0, m.direction());
		assertTrue(m.directionChanged());
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.FootBody;
import com.gielinorskate.render.KnockdownPose;
import com.gielinorskate.session.Knockdown;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

/** What a ghost's body plays and derives from its updates: pushes, crouch, knockdown, OSRS layer, detail. */
public class GhostAnimationTest
{
	private static final GhostFeed.Frame DRAW = (p, t) -> p.pose(t, GhostFeed.FLAT);
	private static final float HALF_PI = (float) (Math.PI / 2);

	private static GhostState rolling(float speed, int seq)
	{
		return GhostFeed.state(420, 0, 0f, 0f, 0f, 0f, 0f, speed, 0f, SkaterState.ROLLING, null, 0, null, 0f, seq);
	}

	@Test
	public void theChargeIsTheDrawnUpdates()
	{
		GhostFeed f = new GhostFeed();
		f.warmUp();
		GhostPredictor p = f.predictor;
		assertEquals(0f, p.charge(), 0f);
		f.send(GhostFeed.withBody(rolling(300f, 1), 0.5f, null, 0f));
		f.run(GhostFeed.DELAY + 0.2f, DRAW);
		assertEquals(0.5f, p.charge(), 0f);
		f.send(rolling(300f, 2));
		f.run(GhostFeed.DELAY + 0.2f, DRAW);
		assertEquals(0f, p.charge(), 0f);
	}

	private static GhostState knocked(KnockdownPose.Stage stage, int seq)
	{
		return GhostFeed.withBody(GhostFeed.state(420, 0, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.BAILED, null, 0, null,
			0f, seq, 0f, 0f, 0f, BoardState.DROPPED, 50f, 0f, 0f, 0f), 0f, stage, 3 * HALF_PI);
	}

	@Test
	public void eachKnockdownStageIsTimedFromWhenItWasFirstPlayed()
	{
		GhostFeed f = new GhostFeed();
		f.warmUp();
		GhostPredictor p = f.predictor;
		assertNull(p.current().knockStage);
		f.send(knocked(KnockdownPose.Stage.AIR, 1));
		f.run(GhostFeed.DELAY + 0.2f, DRAW);
		assertSame(KnockdownPose.Stage.AIR, p.current().knockStage);
		float age = p.knockStageAge(f.now);
		assertTrue("air for " + age, age > 0f && age <= 0.25f);
		// later updates of the same stage do not start it again
		f.run(0.3f, DRAW);
		assertEquals(age + 0.3f, p.knockStageAge(f.now), 0.02f);
		f.send(knocked(KnockdownPose.Stage.LIE, 2));
		f.run(GhostFeed.DELAY + 0.2f, DRAW);
		assertSame(KnockdownPose.Stage.LIE, p.current().knockStage);
		age = p.knockStageAge(f.now);
		assertTrue("lying for " + age, age > 0f && age <= 0.25f);
		f.send(rolling(0f, 3));
		f.run(GhostFeed.DELAY + 0.2f, DRAW);
		assertNull(p.current().knockStage);
	}

	@Test
	public void theKnockdownIsTimedAsTheSendersIs()
	{
		assertEquals(Knockdown.LIE_SECONDS, GhostKnockdown.LIE_SECONDS, 0f);
		assertEquals(Knockdown.GET_UP_SECONDS, GhostKnockdown.GET_UP_SECONDS, 0f);
	}

	@Test
	public void theTumbleSpinsOntoItsLyingAngleThenGetsUpToAWholeTurn()
	{
		float lie = 3 * HALF_PI;
		assertEquals(0f, GhostKnockdown.angle(KnockdownPose.Stage.AIR, lie, 0f), 0f);
		float mid = GhostKnockdown.angle(KnockdownPose.Stage.AIR, lie, GhostKnockdown.SPIN_SECONDS / 2);
		assertEquals(lie / 2, mid, 1e-5f);
		assertEquals(lie, GhostKnockdown.angle(KnockdownPose.Stage.AIR, lie, 5f), 0f);
		assertEquals(lie, GhostKnockdown.angle(KnockdownPose.Stage.LIE, lie, 0.2f), 0f);
		assertEquals(lie, GhostKnockdown.angle(KnockdownPose.Stage.GET_UP, lie, 0f), 1e-6f);
		// 3/4 turn rounds to the whole turn on its way up
		assertEquals(2 * Math.PI, GhostKnockdown.angle(KnockdownPose.Stage.GET_UP, lie, 1f), 1e-5f);
		assertEquals(0f, GhostKnockdown.angle(KnockdownPose.Stage.GET_UP, HALF_PI, 1f), 1e-6f);
		assertEquals(0.5f, GhostKnockdown.progress(KnockdownPose.Stage.LIE, GhostKnockdown.LIE_SECONDS / 2), 1e-6f);
		assertEquals(1f, GhostKnockdown.progress(KnockdownPose.Stage.GET_UP, 3f), 0f);
		assertEquals(0f, GhostKnockdown.progress(KnockdownPose.Stage.AIR, 3f), 0f);
	}

	@Test
	public void theLayerPlaysTheLocalSkatersAnimations()
	{
		assertSame(GhostAnim.STANCE, GhostAnim.pick(false, FootBody.Gait.IDLE, null));
		assertSame(GhostAnim.STANCE, GhostAnim.pick(false, FootBody.Gait.RUN, null));
		assertSame(GhostAnim.NONE, GhostAnim.pick(true, FootBody.Gait.IDLE, null));
		assertSame(GhostAnim.WALK, GhostAnim.pick(true, FootBody.Gait.WALK, null));
		assertSame(GhostAnim.RUN, GhostAnim.pick(true, FootBody.Gait.RUN, null));
		// the tumble is procedural on the stance; down, the OSRS lie-down and get-up
		assertSame(GhostAnim.STANCE, GhostAnim.pick(false, FootBody.Gait.IDLE, KnockdownPose.Stage.AIR));
		assertSame(GhostAnim.LIE, GhostAnim.pick(true, FootBody.Gait.WALK, KnockdownPose.Stage.LIE));
		assertSame(GhostAnim.GET_UP, GhostAnim.pick(false, FootBody.Gait.IDLE, KnockdownPose.Stage.GET_UP));
		assertEquals(AnimationID.HUMAN_SKI_IDLE, GhostAnim.STANCE.id(-1, -1));
		assertEquals(AnimationID.HUMAN_KNOCKDOWN_LOOP_NODELAY, GhostAnim.LIE.id(-1, -1));
		assertEquals(AnimationID.HUMAN_GETUP, GhostAnim.GET_UP.id(-1, -1));
		// the member's own walk and run (their weapon's), the game's when unknown
		assertEquals(1234, GhostAnim.WALK.id(1234, 5678));
		assertEquals(5678, GhostAnim.RUN.id(1234, 5678));
		assertEquals(AnimationID.HUMAN_WALK_F, GhostAnim.WALK.id(-1, -1));
		assertEquals(AnimationID.HUMAN_RUNNING, GhostAnim.RUN.id(1234, -1));
		assertEquals(-1, GhostAnim.NONE.id(1, 2));
		assertTrue(GhostAnim.STANCE.loops);
		assertFalse(GhostAnim.GET_UP.loops);
	}

	@Test
	public void theAppearanceKeyFollowsGearColoursAndIdle()
	{
		int[] gear = {256 + 1, 512 + 4151, 0, 0, 256 + 18, 512 + 1127, 256 + 26, 512 + 1079, 256 + 33, 256 + 42,
			256 + 48, 256 + 10};
		int[] colours = {1, 2, 3, 4, 5};
		int k = GhostBodyController.key(gear, colours, 0, -1, AnimationID.HUMAN_READY);
		assertEquals(k, GhostBodyController.key(gear.clone(), colours.clone(), 0, -1, AnimationID.HUMAN_READY));
		int[] other = gear.clone();
		other[1] = 512 + 4587;
		assertNotEquals(k, GhostBodyController.key(other, colours, 0, -1, AnimationID.HUMAN_READY));
		assertNotEquals(k, GhostBodyController.key(gear, new int[]{1, 2, 3, 4, 6}, 0, -1, AnimationID.HUMAN_READY));
		assertNotEquals(k, GhostBodyController.key(gear, colours, 1, -1, AnimationID.HUMAN_READY));
		assertNotEquals(k, GhostBodyController.key(gear, colours, 0, 2, AnimationID.HUMAN_READY));
		assertNotEquals(k, GhostBodyController.key(gear, colours, 0, -1, AnimationID.HUMAN_DS_READY));
		assertEquals(GhostBodyController.key(null, null, 0, -1, 808), GhostBodyController.key(null, null, 0, -1, 808));
	}

	@Test
	public void aSnapshotIsTakenOnlyOfThePlainStandingCharacter()
	{
		int ready = AnimationID.HUMAN_READY;
		assertTrue(GhostBodyController.mayTake(-1, ready, ready, -1));
		// mid action, walking or turning, or as an NPC (a transformation): not a standing body
		assertFalse(GhostBodyController.mayTake(AnimationID.HUMAN_GETUP, ready, ready, -1));
		assertFalse(GhostBodyController.mayTake(-1, AnimationID.HUMAN_WALK_F, ready, -1));
		assertFalse(GhostBodyController.mayTake(-1, ready, ready, 2));
		// OSRS animations go on top only of the game's own standing frame: a weapon's stance would double up
		assertTrue(GhostBodyController.layerable(ready));
		assertFalse(GhostBodyController.layerable(AnimationID.HUMAN_DS_READY));
	}

	@Test
	public void theNearestGhostsGetTheFullBody()
	{
		float near = 5 * 128f;
		float far = GhostVisibility.FULL_RANGE + 1f;
		assertTrue(GhostVisibility.full(0, near));
		assertTrue(GhostVisibility.full(GhostVisibility.MAX_FULL - 1, near));
		assertFalse(GhostVisibility.full(GhostVisibility.MAX_FULL, near));
		assertFalse(GhostVisibility.full(0, far));
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.progression.BoardDesign;
import com.gielinorskate.progression.BoardDesigns;
import com.gielinorskate.progression.DesignPart;
import com.gielinorskate.render.KnockdownPose;
import com.gielinorskate.tricks.Trick;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import net.runelite.client.party.messages.WebsocketMessage;
import net.runelite.client.util.RuntimeTypeAdapterFactory;
import org.junit.Test;

/** The optional body fields: the pop charge's crouch and the knockdown (tumble, lie, get-up). */
public class GhostBodyWireTest
{
	private static final Gson GSON = new GsonBuilder()
		.registerTypeAdapterFactory(RuntimeTypeAdapterFactory.of(WebsocketMessage.class)
			.registerSubtype(SkateGhostUpdate.class)
			.registerSubtype(SkateGhostStop.class))
		.create();

	private static GhostState rolling(float charge)
	{
		return GhostFeed.withBody(GhostFeed.frame(330, 0, 1000f, 2000f, 0f, 0f, 0f, 800f, 0f, SkaterState.ROLLING, null,
			null, 0f), charge, null, 0f);
	}

	private static SkateGhostUpdate roundTrip(SkateGhostUpdate m)
	{
		return (SkateGhostUpdate) GSON.fromJson(GSON.toJson(m, WebsocketMessage.class), WebsocketMessage.class);
	}

	@Test
	public void theChargeGoesInNinthsAndOnlyWhileCrouching()
	{
		assertNull(GhostCodec.encode(rolling(0f), 0, null).cr);
		assertNull(GhostCodec.encode(rolling(0.03f), 0, null).cr);
		assertEquals(Integer.valueOf(9), GhostCodec.encode(rolling(1f), 0, null).cr);
		assertEquals(Integer.valueOf(5), GhostCodec.encode(rolling(0.5f), 0, null).cr);
		GhostState s = GhostCodec.decode(roundTrip(GhostCodec.encode(rolling(0.5f), 0, null)));
		assertEquals(5f / 9f, s.charge, 1e-6f);
		assertNull(s.knockStage);
		// no charge in the air: the frame says so whatever the physics held
		GhostState air = GhostFeed.withBody(GhostFeed.frame(330, 0, 0f, 0f, 100f, 0f, 0f, 0f, 300f,
			SkaterState.AIRBORNE, null, null, 0f), 1f, null, 0f);
		assertNull(GhostCodec.encode(air, 0, null).cr);
	}

	@Test
	public void aChangedChargeIsAStateChange()
	{
		SkateGhostUpdate a = GhostCodec.encode(rolling(0f), 0, null);
		SkateGhostUpdate b = GhostCodec.encode(rolling(1f), 0, null);
		assertFalse(a.sameState(b));
		assertTrue(b.sameState(GhostCodec.encode(rolling(1f), 0, null)));
	}

	@Test
	public void olderVersionsMessagesHaveNoChargeAndNoKnockdown()
	{
		String json = "{\"type\":\"SkateGhostUpdate\",\"w\":330,\"x\":5,\"st\":\"BAILED\",\"seq\":3}";
		GhostState s = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		assertEquals(0f, s.charge, 0f);
		assertNull(s.knockStage);
		assertSame(SkaterState.BAILED, s.state);
	}

	private static final float HALF_PI = (float) (Math.PI / 2);

	private static GhostState knocked(KnockdownPose.Stage stage, float lie, boolean airborne)
	{
		return GhostFeed.knockdown(330, 2, 1_409_664f, 1_411_200f, -1237f, -3.14159f, -1400f, 1400f, airborne,
			stage, lie, 1_409_000f, 1_411_999f, -1237f, -3.14159f);
	}

	@Test
	public void aKnockdownRoundTrips()
	{
		SkateGhostUpdate m = GhostCodec.encode(knocked(KnockdownPose.Stage.GET_UP, 3 * HALF_PI, false), 0, null);
		assertEquals(Integer.valueOf(3 + 10 * 5), m.kd);
		GhostState s = GhostCodec.decode(roundTrip(m));
		assertSame(KnockdownPose.Stage.GET_UP, s.knockStage);
		assertEquals(3 * HALF_PI, s.knockLie, 1e-5f);
		assertSame(SkaterState.BAILED, s.state);
		assertSame(BoardState.DROPPED, s.offBoard);
		assertEquals(1_409_000f, s.boardX, 0f);
		assertEquals(-1400f, s.vx, 0f);
		// thrown off: in the air the predictor flies the body
		GhostState air = GhostCodec.decode(roundTrip(GhostCodec.encode(knocked(KnockdownPose.Stage.AIR, HALF_PI,
			true), 0, null)));
		assertSame(KnockdownPose.Stage.AIR, air.knockStage);
		assertSame(SkaterState.AIRBORNE, air.state);
		assertEquals(HALF_PI, air.knockLie, 1e-5f);
		// every lying angle the tumble plans or settles at: odd quarter turns, onto the back off a wall too
		for (int k = -4; k <= 5; k++)
		{
			float lie = (2 * k + 1) * HALF_PI;
			GhostState back = GhostCodec.decode(GhostCodec.encode(knocked(KnockdownPose.Stage.LIE, lie, false), 0,
				null));
			assertEquals(lie, back.knockLie, 1e-4f);
		}
	}

	@Test
	public void junkKnockdownCodesAreIgnored()
	{
		SkateGhostUpdate m = GhostCodec.encode(knocked(KnockdownPose.Stage.LIE, HALF_PI, false), 0, null);
		m.kd = 7;
		assertNull(GhostCodec.decode(m).knockStage);
		m.kd = 40;
		assertNull(GhostCodec.decode(m).knockStage);
		m.kd = 100;
		assertNull(GhostCodec.decode(m).knockStage);
		m.kd = -5;
		assertNull(GhostCodec.decode(m).knockStage);
		// a knockdown needs its board's place: without it the code means nothing
		SkateGhostUpdate onBoard = GhostCodec.encode(rolling(0f), 0, null);
		onBoard.kd = 42;
		assertNull(GhostCodec.decode(onBoard).knockStage);
	}

	@Test
	public void toOlderVersionsAKnockdownIsAWalkerWithItsBoardDropped()
	{
		// they decode ob / bx... as on foot and ignore kd: the body stands where it lies, the board where it rests
		SkateGhostUpdate m = GhostCodec.encode(knocked(KnockdownPose.Stage.LIE, HALF_PI, false), 0, null);
		assertEquals("DROPPED", m.ob);
		assertTrue(m.bx != null && m.by != null && m.bh != null && m.bd != null);
		assertFalse(GhostCodec.mayCarryLook(m));
	}

	private static String longest(DesignPart part)
	{
		String w = "";
		for (BoardDesign d : BoardDesigns.bundled().of(part))
		{
			if (d.wireName().length() > w.length())
			{
				w = d.wireName();
			}
		}
		return w;
	}

	@Test
	public void theBiggestUpdatesWithTheBodyFieldsStayWithinTheBound()
	{
		// a grind with a full charge and every event bit: the designs wait while crouching (with them it was 286)
		GhostState grind = GhostFeed.withBody(GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, -1237f, -3.14159f,
			-2600f, -2600f, -1820f, SkaterState.GRINDING, Trick.BOARDSLIDE, null, 0f, -TurnRateMeter.MAX_RATE,
			-4 * (float) Math.PI, -11.424f), 1f, null, 0f);
		SkateGhostUpdate g = GhostCodec.encode(grind, 0x7ff, null);
		g.seq = 1_234_567_890;
		g.dk = longest(DesignPart.DECK);
		assertFalse(GhostCodec.mayCarryLook(g));
		String gj = GSON.toJson(g, WebsocketMessage.class);
		assertTrue(gj.length() + " " + gj, gj.length() <= 284);

		// the busiest knockdown: every number at its longest, the longest deck (with the vertical
		// speed, tumble angle and rate and a progress it measured 298)
		SkateGhostUpdate k = GhostCodec.encode(GhostFeed.knockdown(330, 2, 1_409_664f, 1_411_200f, -1237f,
			-3.14159f, -2600f, -2600f, true, KnockdownPose.Stage.GET_UP, -7 * HALF_PI, 1_409_000f, 1_411_999f,
			-1237f, -3.14159f), 0x7ff, null);
		k.seq = 1_234_567_890;
		k.dk = longest(DesignPart.DECK);
		String kj = GSON.toJson(k, WebsocketMessage.class);
		assertTrue(kj.length() + " " + kj, kj.length() <= 284);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;

public class GhostClockSyncTest
{
	/** Our clock minus the sender's. */
	private static final double OFFSET = 1234.5;

	/**
	 * Updates every {@code every} seconds for {@code seconds}, delivered after {@code latency} +- {@code jitter}
	 * (uniform), {@code loss} of them lost, in arrival order (reordered by the jitter).
	 */
	private static GhostClockSync run(float every, float seconds, float latency, float jitter, float loss, long seed)
	{
		Random rnd = new Random(seed);
		List<double[]> arrivals = new ArrayList<>();
		for (double s = 0; s < seconds; s += every)
		{
			if (rnd.nextFloat() < loss)
			{
				continue;
			}
			double at = s + OFFSET + latency + (rnd.nextFloat() * 2 - 1) * jitter;
			arrivals.add(new double[]{at, s});
		}
		arrivals.sort((a, b) -> Double.compare(a[0], b[0]));
		GhostClockSync sync = new GhostClockSync();
		for (double[] a : arrivals)
		{
			double sent = sync.unwrap(GhostTrajectory.timeMs((float) a[1]));
			assertTrue(sync.observe((float) a[0], sent));
		}
		return sync;
	}

	@Test
	public void floorJitterAndDelayUnderLatencyJitterReorderingAndLoss()
	{
		GhostClockSync sync = run(0.6f, 60f, 0.15f, 0.08f, 0.05f, 1);
		// the quickest delivery is 70 ms: the floor is the clocks' difference plus about that
		assertEquals(OFFSET + 0.07, sync.floor(), 0.015);
		// 90 % of updates arrive within about 0.9 * 160 ms of the floor
		assertEquals(0.144, sync.jitter(), 0.025);
		assertEquals(0.6, sync.gap(), 0.01);
		float expected = 0.6f + sync.jitter() + GhostClockSync.MARGIN;
		assertEquals(expected, sync.delay(), 1e-6);
		assertTrue(sync.delay() > 0.7f && sync.delay() < 0.85f);
	}

	@Test
	public void aQuietNetworkGetsAShortDelayAndAWildOneIsCapped()
	{
		GhostClockSync lan = run(0.6f, 30f, 0.02f, 0.005f, 0f, 2);
		assertEquals(0.6 + 0.01 + GhostClockSync.MARGIN, lan.delay(), 0.01);
		GhostClockSync wild = run(0.6f, 30f, 1f, 0.9f, 0f, 3);
		assertEquals(GhostClockSync.MAX_DELAY, wild.delay(), 1e-6);
		// event updates in between make the gaps shorter, and the delay with them (never under the minimum)
		GhostClockSync busy = run(0.1f, 30f, 0.02f, 0.005f, 0f, 4);
		assertEquals(GhostClockSync.MIN_DELAY, busy.delay(), 1e-6);
	}

	@Test
	public void aStandingSkatersKeepAlivesAreNotMotionGaps()
	{
		GhostClockSync sync = new GhostClockSync();
		float now = 100f;
		for (int i = 0; i < 10; i++)
		{
			// one every 10 s
			sync.observe(now + i * 10f, sync.unwrap(GhostTrajectory.timeMs(i * 10f)));
		}
		assertEquals(GhostClockSync.DEFAULT_GAP, sync.gap(), 1e-6);
	}

	@Test
	public void sendTimesUnwrapAcrossTheModulus()
	{
		GhostClockSync sync = new GhostClockSync();
		double wrap = GhostTrajectory.TIME_MOD / 1000.0;
		double first = sync.unwrap(GhostTrajectory.TIME_MOD - 500);
		assertEquals(wrap - 0.5, first, 1e-9);
		// 0.6 s later, past the wrap
		assertEquals(wrap + 0.1, sync.unwrap(100), 1e-9);
		// a late one from before it
		assertEquals(wrap - 0.2, sync.unwrap(GhostTrajectory.TIME_MOD - 200), 1e-9);
		assertEquals(wrap + 0.7, sync.unwrap(700), 1e-9);
	}

	@Test
	public void aRestartedSendersClockIsNoticed()
	{
		GhostClockSync sync = run(0.6f, 20f, 0.1f, 0.02f, 0f, 5);
		double floor = sync.floor();
		// the sender's plugin restarted: its clock is back near 0
		double sent = sync.unwrap(GhostTrajectory.timeMs(0.3f));
		assertFalse(sync.observe((float) (OFFSET + 20.4), sent));
		assertEquals(floor, sync.floor(), 1e-9);
		sync = new GhostClockSync();
		assertFalse(sync.has());
		assertTrue(sync.observe((float) (OFFSET + 20.4), sync.unwrap(GhostTrajectory.timeMs(0.3f))));
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class GhostCodecTest
{
	static GhostState frame(float x, float y, float h, float heading, SkaterState state)
	{
		return GhostFeed.frame(420, 1, x, y, h, heading, 0f, 0f, 0f, state, null, null, 0f);
	}

	@Test
	public void roundTripStaysWithinRounding()
	{
		GhostState f = GhostFeed.frame(330, 2, 409_664.4f, 411_200.6f, -37.3f, 2.71828f, 812.4f, -1201.6f, 455.5f,
			SkaterState.AIRBORNE, Trick.INDY, Trick.KICKFLIP, 0.4f);
		SkateGhostUpdate m = GhostCodec.encode(f, GhostCodec.EV_POP | GhostCodec.EV_TRICK, Trick.KICKFLIP);
		m.seq = 77;
		GhostState s = GhostCodec.decode(m);
		assertEquals(330, s.world);
		assertEquals(2, s.plane);
		assertEquals(409_664.4f, s.x, 0.5f);
		assertEquals(411_200.6f, s.y, 0.5f);
		assertEquals(-37.3f, s.h, 0.5f);
		assertEquals(2.71828f, s.heading, 0.0005f);
		assertEquals(812.4f, s.vx, 0.5f);
		assertEquals(-1201.6f, s.vy, 0.5f);
		assertEquals(455.5f, s.vh, 0.5f);
		assertSame(SkaterState.AIRBORNE, s.state);
		assertSame(Trick.INDY, s.hold);
		assertSame(Trick.KICKFLIP, s.trick);
		// progress 0.4 of a 0.35 s kickflip, sent as nominal seconds
		assertEquals(0.4f * Trick.KICKFLIP.duration, s.flipTime, 0.0005f);
		assertEquals(GhostCodec.EV_POP | GhostCodec.EV_TRICK, s.events);
		assertEquals(77, s.seq);
	}

	@Test
	public void directionalAndTweakedGrabsRoundTripByName()
	{
		for (Trick grab : new Trick[]{Trick.MUTE, Trick.CRAIL, Trick.METHOD, Trick.CRAIL_TWEAK})
		{
			GhostState f = GhostFeed.frame(330, 0, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.AIRBORNE, grab, null, 0f);
			SkateGhostUpdate m = GhostCodec.encode(f, GhostCodec.EV_TRICK, grab);
			assertEquals(grab.name(), m.hold);
			GhostState s = GhostCodec.decode(m);
			assertSame(grab, s.hold);
			assertSame(grab, s.trick);
		}
		// an older plugin that does not know a grab's name just shows no grab
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.AIRBORNE), 0, null);
		m.hold = "SOME_FUTURE_GRAB";
		m.tr = "SOME_FUTURE_GRAB";
		GhostState s = GhostCodec.decode(m);
		assertNull(s.hold);
		assertNull(s.trick);
	}

	@Test
	public void noFlipAndNoHoldEncodeAsNull()
	{
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.ROLLING), 0, null);
		assertNull(m.hold);
		assertNull(m.tr);
		assertEquals(0, m.ft);
		GhostState s = GhostCodec.decode(m);
		assertNull(s.hold);
		assertNull(s.trick);
	}

	@Test
	public void aTrickEventWithoutAFlipStillCarriesItsTrickForTheLabel()
	{
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.AIRBORNE), GhostCodec.EV_TRICK,
			Trick.OLLIE);
		assertEquals("OLLIE", m.tr);
		assertEquals(0, m.ft);
	}

	@Test
	public void aFinishedFlipEventIsNotSentAsANewFlip()
	{
		// the kickflip's event was held back by the rate limit and the flip is over: animating it now would be wrong
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.ROLLING), GhostCodec.EV_TRICK,
			Trick.KICKFLIP);
		assertNull(m.tr);
	}

	@Test
	public void tricksAndStatesGoByName()
	{
		GhostState f = GhostFeed.frame(330, 2, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.GRINDING, Trick.FEEBLE,
			Trick.TRIPLE_KICKFLIP, 0.5f);
		SkateGhostUpdate m = GhostCodec.encode(f, 0, null);
		assertEquals("GRINDING", m.st);
		assertEquals("FEEBLE", m.hold);
		assertEquals("TRIPLE_KICKFLIP", m.tr);
		GhostState s = GhostCodec.decode(m);
		assertSame(SkaterState.GRINDING, s.state);
		assertSame(Trick.FEEBLE, s.hold);
		assertSame(Trick.TRIPLE_KICKFLIP, s.trick);
	}

	@Test
	public void unknownNamesDecodeSafely()
	{
		// a newer plugin's trick or state, an older plugin's ordinal read as a string, or nothing at all
		SkateGhostUpdate m = new SkateGhostUpdate();
		m.st = "WALL_RIDE";
		m.hold = "1234";
		m.tr = "kickflip";
		m.ft = 200;
		GhostState s = GhostCodec.decode(m);
		assertSame(SkaterState.ROLLING, s.state);
		assertNull(s.hold);
		assertNull(s.trick);
		m.st = null;
		m.tr = "";
		s = GhostCodec.decode(m);
		assertSame(SkaterState.ROLLING, s.state);
		assertNull(s.trick);
	}

	@Test
	public void turnRateRoundTripsInMilliradiansPerSecond()
	{
		GhostState f = GhostFeed.frame(420, 1, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING, null, null, 0f,
			-2.3456f);
		SkateGhostUpdate m = GhostCodec.encode(f, 0, null);
		assertEquals(-2346, m.tw);
		assertEquals(-2.346f, GhostCodec.decode(m).turnRate, 1e-6f);
	}

	@Test
	public void aTurnRateOutOfRangeIsBoundedOnReceipt()
	{
		// a buggy or hostile sender: no ghost spins faster than any real turn
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.ROLLING), 0, null);
		m.tw = Integer.MAX_VALUE;
		assertEquals(TurnRateMeter.MAX_RATE, GhostCodec.decode(m).turnRate, 0f);
		m.tw = Integer.MIN_VALUE;
		assertEquals(-TurnRateMeter.MAX_RATE, GhostCodec.decode(m).turnRate, 0f);
		// off the board too
		m.ob = "CARRIED";
		m.tw = 99_999;
		assertEquals(TurnRateMeter.MAX_RATE, GhostCodec.decode(m).turnRate, 0f);
		// in range is untouched
		m.tw = -9_999;
		assertEquals(-9.999f, GhostCodec.decode(m).turnRate, 1e-6f);
	}

	@Test
	public void bodyFlipRoundTripsInMilliradians()
	{
		GhostState f = GhostFeed.frame(420, 1, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.AIRBORNE, null, null, 0f, 0f,
			7.5f, -11.424f);
		SkateGhostUpdate m = GhostCodec.encode(f, 0, null);
		assertEquals(7500, m.bf);
		assertEquals(-11424, m.bw);
		GhostState s = GhostCodec.decode(m);
		assertEquals(7.5f, s.bodyFlip, 1e-6f);
		assertEquals(-11.424f, s.bodyFlipRate, 1e-6f);
	}

	@Test
	public void aLandedBodyFlipIsSentForTheLabel()
	{
		// body flips have no board rotation of their own: nothing to animate twice, so the label gets them
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 0f, SkaterState.ROLLING), GhostCodec.EV_TRICK,
			Trick.DOUBLE_BACKFLIP);
		assertEquals("DOUBLE_BACKFLIP", m.tr);
	}

	@Test
	public void headingIsWrapped()
	{
		SkateGhostUpdate m = GhostCodec.encode(frame(0f, 0f, 0f, 3 * Angles.PI / 2, SkaterState.ROLLING), 0, null);
		assertEquals(-Angles.PI / 2, GhostCodec.decode(m).heading, 0.001f);
	}

	@Test
	public void velocityFollowsTravelHeadingAndSpeedMagnitude()
	{
		// heading 0 = north (+y), PI/2 = east (+x); a negative (fakie) speed travels along the travel heading too
		float[] v = GhostCodec.velocity(-500f, Angles.PI / 2);
		assertEquals(500f, v[0], 0.01f);
		assertEquals(0f, v[1], 0.01f);
	}

	@Test
	public void sameStateIgnoresSeqAndEvents()
	{
		SkateGhostUpdate a = GhostCodec.encode(frame(100f, 200f, 0f, 1f, SkaterState.ROLLING), 0, null);
		SkateGhostUpdate b = GhostCodec.encode(frame(100.2f, 200f, 0f, 1f, SkaterState.ROLLING), GhostCodec.EV_POP,
			null);
		b.seq = 9;
		assertTrue(a.sameState(b));
		SkateGhostUpdate c = GhostCodec.encode(frame(102f, 200f, 0f, 1f, SkaterState.ROLLING), 0, null);
		assertFalse(a.sameState(c));
	}

	@Test
	public void eventBitsFromPhysicsEventsAndGrindTransitions()
	{
		int bits = GhostCodec.eventBits(Arrays.asList(SkateEvent.POP, SkateEvent.PUSH),
			Collections.singletonList(TrickEvent.trick(Trick.KICKFLIP)), SkaterState.ROLLING, SkaterState.AIRBORNE);
		// a push goes as a passive bit (it rides with the next update, never sends one of its own)
		assertEquals(GhostCodec.EV_POP | GhostCodec.EV_TRICK | GhostCodec.EV_PUSH, bits);
		assertEquals(GhostCodec.EV_GRIND_LOCK, GhostCodec.eventBits(Collections.emptyList(), Collections.emptyList(),
			SkaterState.AIRBORNE, SkaterState.GRINDING));
		assertEquals(GhostCodec.EV_GRIND_EXIT | GhostCodec.EV_POP, GhostCodec.eventBits(
			Collections.singletonList(SkateEvent.POP), Collections.emptyList(), SkaterState.GRINDING,
			SkaterState.AIRBORNE));
		assertEquals(GhostCodec.EV_LAND | GhostCodec.EV_BAIL | GhostCodec.EV_RESET, GhostCodec.eventBits(
			Arrays.asList(SkateEvent.LAND, SkateEvent.BAIL, SkateEvent.RESET), Collections.emptyList(),
			SkaterState.ROLLING, SkaterState.ROLLING));
		// a grab starting is a trick too
		assertEquals(GhostCodec.EV_TRICK, GhostCodec.eventBits(Collections.emptyList(),
			Collections.singletonList(TrickEvent.holdStart(Trick.INDY)), SkaterState.AIRBORNE, SkaterState.AIRBORNE));
	}

	@Test
	public void eventTrickIsTheLatestTrickOrHoldStart()
	{
		assertSame(Trick.MELON, GhostCodec.eventTrick(Arrays.asList(TrickEvent.trick(Trick.OLLIE),
			TrickEvent.holdStart(Trick.MELON))));
		assertNull(GhostCodec.eventTrick(Collections.emptyList()));
	}

	@Test
	public void absoluteCoordinatesUseTheSceneBase()
	{
		assertEquals(6464f, GhostCodec.toLocal(3200 * 128 + 6464f, 3200), 0f);
	}
}

