	@Test
	public void eventSpamStaysUnderTwoPerSecondAndEventsAreNotLost()
	{
		audience();
		for (int i = 0; i < 500; i++)
		{
			float t = i * FRAME;
			// pvp flapping on and off adds stops on top of the event spam
			frame(t, frame(i), GhostCodec.EV_TRICK, i % 37 == 0, true);
		}
		List<Float> times = link.times;
		for (int i = 2; i < times.size(); i++)
		{
			assertTrue("window at " + times.get(i), times.get(i) - times.get(i - 2) >= 1f - 1e-4f);
		}
		for (PartyMessage m : link.sent)
		{
			if (m instanceof SkateGhostUpdate)
			{
				assertEquals(GhostCodec.EV_TRICK, ((SkateGhostUpdate) m).ev);
			}
		}
	}

	@Test
	public void rateLimitedEventsAreCoalescedIntoTheNextUpdate()
	{
		audience();
		// two quick events use up the second's budget
		for (int i = 0; i < 2; i++)
		{
			frame(i * FRAME, frame(i), GhostCodec.EV_TRICK, false, true);
		}
		frame(0.1f, frame(5f), GhostCodec.EV_POP, false, true);
		frame(0.2f, frame(6f), GhostCodec.EV_LAND, false, true);
		assertEquals(2, link.updates());
		frame(1.0f, frame(7f), 0, false, true);
		SkateGhostUpdate last = (SkateGhostUpdate) link.sent.get(link.sent.size() - 1);
		assertEquals(GhostCodec.EV_POP | GhostCodec.EV_LAND, last.ev);
	}

	@Test
	public void eventTrickIsKeptUntilSent()
	{
		audience();
		for (int i = 0; i < 2; i++)
		{
			frame(i * FRAME, frame(i), GhostCodec.EV_POP, false, true);
		}
		link.now = 0.5f;
		hub.onLocalFrame(frame(9f), GhostCodec.EV_TRICK, Trick.INDY, false, true, 0.5f);
		frame(1.0f, frame(10f), 0, false, true);
		SkateGhostUpdate last = (SkateGhostUpdate) link.sent.get(link.sent.size() - 1);
		assertEquals("INDY", last.tr);
	}

	/** A member's update with a timeline (sent at seq / 10 s of their clock, no positions). */
	private static SkateGhostUpdate remote(float x, int seq)
	{
		SkateGhostUpdate m = GhostCodec.encode(frame(x), 0, null);
		m.seq = seq;
		m.tj = GhostFeed.wire(GhostTrajectory.timeMs(seq / 10f), 0, null, 0, new float[0], new float[0],
			new float[0], new float[0], new float[0], new SkaterState[0], m.x, m.y, m.h, m.hd);
		return m;
	}

	@Test
	public void remoteUpdatesMakeGhostsAndStopsRemoveThem()
	{
		hub.onRemoteUpdate(7L, remote(100f, 1), 0f, null);
		hub.onRemoteUpdate(8L, remote(200f, 1), 0f, null);
		assertEquals(2, hub.ghosts().size());
		assertNotNull(hub.ghosts().get(7L));
		hub.onMemberLeft(7L);
		assertFalse(hub.ghosts().containsKey(7L));
		hub.onMemberLeft(8L);
		assertTrue(hub.ghosts().isEmpty());
	}

	@Test
	public void silentGhostsArePruned()
	{
		hub.onRemoteUpdate(7L, remote(100f, 1), 0f, null);
		hub.onRemoteUpdate(8L, remote(200f, 1), 10f, null);
		hub.prune(16f);
		assertFalse(hub.ghosts().containsKey(7L));
		assertTrue(hub.ghosts().containsKey(8L));
		hub.clearGhosts();
		assertTrue(hub.ghosts().isEmpty());
	}

	@Test
	public void seqSeedGrowsWithWallClockSoARestartNeverGoesBackwards()
	{
		long t = 1_800_000_000_000L;
		assertTrue(GhostHub.seqSeed(t + 1000) > GhostHub.seqSeed(t));
		// four per second of wall time: a run sending at the 2/s limit never overtakes the next run's seed
		assertEquals(4, GhostHub.seqSeed(t + 1000) - GhostHub.seqSeed(t));
		assertTrue(GhostHub.seqSeed(t) > 0);
	}

	private static final BoardDesigns DESIGNS = BoardDesigns.bundled();

	private static BoardLook look(String grip, String deck, String wheels)
	{
		return new BoardLook(DESIGNS.byId(grip), DESIGNS.byId(deck), DESIGNS.byId(wheels));
	}

	private SkateGhostUpdate lastUpdate()
	{
		return (SkateGhostUpdate) link.sent.get(link.sent.size() - 1);
	}

	@Test
	public void theLocalLookGoesOutAndTheDefaultDeckIsLeftOut()
	{
		audience();
		frame(0f, frame(0f), 0, false, true);
		assertEquals(null, lastUpdate().dk);
		// the first update after starting names the grip and wheels
		assertEquals("BLACK.NATURAL", lastUpdate().gw);
		hub.setLocalLook(look("GRIP_RUNE", "RUNE", "WHEELS_NATURAL"));
		// a design change alone is a change worth sending
		frame(5f, frame(0f), 0, false, true);
		assertEquals("RUNE", lastUpdate().dk);
		assertEquals("RUNE.NATURAL", lastUpdate().gw);
		// back on the default deck (DECK_TROPICAL): left out again
		hub.setLocalLook(look("GRIP_RUNE", "DECK_TROPICAL", "WHEELS_NATURAL"));
		frame(10f, frame(0f), 0, false, true);
		assertNull(lastUpdate().dk);
		assertEquals("RUNE.NATURAL", lastUpdate().gw);
	}

	@Test
	public void theGripAndWheelsRideAlongNowAndThenNotInEveryUpdate()
	{
		audience();
		int with = 0;
		int without = 0;
		for (int i = 0; i < 600; i++)
		{
			// moving: snapshots every game tick for 12 s
			frame(i * FRAME, frame(i * 3f), 0, false, true);
		}
		for (PartyMessage m : link.sent)
		{
			if (((SkateGhostUpdate) m).gw != null)
			{
				with++;
			}
			else
			{
				without++;
			}
		}
		// at the start, then every LOOK_REFRESH_SECONDS
		assertEquals(1 + (int) (12f / GhostHub.LOOK_REFRESH_SECONDS), with);
		assertTrue(without > with * 4);
	}

	@Test
	public void theGripAndWheelsWaitForAnUpdateWithoutATrick()
	{
		audience();
		hub.setLocalLook(look("GRIP_SARADOMIN", "SARADOMIN", "WHEELS_SARADOMIN"));
		GhostState flipping = GhostFeed.frame(420, 0, 0f, 0f, 50f, 0f, 0f, 0f, 0f, SkaterState.AIRBORNE, null,
			Trick.KICKFLIP, 0.5f);
		frame(0f, flipping, 0, false, true);
		// a flip's name already makes it the biggest kind of update: the designs wait
		assertNotNull(lastUpdate().tr);
		assertNull(lastUpdate().gw);
		assertEquals("SARADOMIN", lastUpdate().dk);
		frame(0.6f, frame(5f), 0, false, true);
		assertEquals("SARADOMIN.SARADOMIN", lastUpdate().gw);
	}

	@Test
	public void restartingSendsTheDesignsAgainAtOnce()
	{
		audience();
		frame(0f, frame(0f), 0, false, true);
		frame(0.6f, frame(10f), 0, false, true);
		assertNull(lastUpdate().gw);
		hub.onLocalSkateEnd(1f);
		audience();
		frame(2f, frame(0f), 0, false, true);
		assertEquals("BLACK.NATURAL", lastUpdate().gw);
	}

	@Test
	public void remoteDesignsAreCheckedAgainstTheManifest()
	{
		SkateGhostUpdate m = remote(0f, 1);
		m.dk = "TORVA";
		m.gw = "TORVA.TORVA";
		hub.onRemoteUpdate(5L, m, 0f, null);
		assertEquals("GRIP_TORVA/TORVA/WHEELS_TORVA", hub.ghosts().get(5L).look().toString());
		// later updates without the grip and wheels keep them; the deck goes in every update
		SkateGhostUpdate next = remote(0f, 2);
		next.dk = "RUNE";
		hub.onRemoteUpdate(5L, next, 0.1f, null);
		assertEquals("GRIP_TORVA/RUNE/WHEELS_TORVA", hub.ghosts().get(5L).look().toString());
		// the old starter deck and decks removed from the ladder: the default deck
		SkateGhostUpdate classic = remote(0f, 1);
		classic.dk = "CLASSIC";
		hub.onRemoteUpdate(7L, classic, 0f, null);
		assertEquals(BoardLook.defaults(DESIGNS), hub.ghosts().get(7L).look());
		SkateGhostUpdate removed = remote(0f, 2);
		removed.dk = "MAX_CAPE";
		hub.onRemoteUpdate(7L, removed, 0.1f, null);
		assertEquals(BoardLook.defaults(DESIGNS), hub.ghosts().get(7L).look());
		// junk: defaults, never an exception
		SkateGhostUpdate odd = remote(0f, 3);
		odd.dk = "<b>GOLD</b>";
		odd.gw = "...TORVA.";
		hub.onRemoteUpdate(5L, odd, 0.2f, null);
		assertEquals(BoardLook.defaults(DESIGNS), hub.ghosts().get(5L).look());
		SkateGhostUpdate half = remote(0f, 4);
		half.gw = "BRONZE";
		hub.onRemoteUpdate(5L, half, 0.3f, null);
		assertEquals("GRIP_BRONZE/DECK_TROPICAL/WHEELS_NATURAL", hub.ghosts().get(5L).look().toString());
		// an older version naming the removed test designs: the defaults
		SkateGhostUpdate removedTest = remote(0f, 5);
		removedTest.dk = "RED_CAMO";
		removedTest.gw = "RUNESKATE.DEATH";
		hub.onRemoteUpdate(5L, removedTest, 0.4f, null);
		assertEquals(BoardLook.defaults(DESIGNS), hub.ghosts().get(5L).look());
		// an older version sends neither: the defaults
		hub.onRemoteUpdate(6L, remote(0f, 1), 0f, null);
		assertEquals(BoardLook.defaults(DESIGNS), hub.ghosts().get(6L).look());
	}

	@Test
	public void aStaleUpdateDoesNotChangeTheDesigns()
	{
		SkateGhostUpdate current = remote(0f, 2);
		current.dk = "DRAGON";
		current.gw = "DRAGON.DRAGON";
		hub.onRemoteUpdate(5L, current, 0f, null);
		assertEquals("GRIP_DRAGON/DRAGON/WHEELS_DRAGON", hub.ghosts().get(5L).look().toString());
		// an earlier, out-of-order packet (lower seq, within the resync window): rejected as stale
		SkateGhostUpdate stale = remote(0f, 1);
		stale.dk = "RUNE";
		stale.gw = "RUNE.RUNE";
		hub.onRemoteUpdate(5L, stale, 0.1f, null);
		assertEquals("GRIP_DRAGON/DRAGON/WHEELS_DRAGON", hub.ghosts().get(5L).look().toString());
	}

	@Test
	public void togglingSkatingFastStaysUnderTwoMessagesPerSecond()
	{
		// nobody else skating: each session announces once a token is free, and its end sends a stop
		float[] sessions = {0.5f, 0.6f, 0.3f, 0.9f, 0.2f, 0.45f};
		float t = 0f;
		for (int i = 0; i < 60; i++)
		{
			float end = t + sessions[i % sessions.length];
			for (; t < end; t += FRAME)
			{
				frame(t, frame(t), 0, false, true);
			}
			link.now = t;
			hub.onLocalSkateEnd(t);
			t += 0.1f;
		}
		List<Float> times = link.times;
		assertTrue(link.updates() > 1);
		for (int i = 2; i < times.size(); i++)
		{
			assertTrue("window at " + times.get(i), times.get(i) - times.get(i - 2) >= 1f - 1e-4f);
		}
	}

	@Test
	public void aRemoteUpdateWithUnknownEventBitsIsStillDrawn()
	{
		// bits 12 and 13 come from other builds of the plugin: ignored, the update itself still counts
		SkateGhostUpdate m = remote(0f, 1);
		m.ev = (1 << 12) | (1 << 13);
		hub.onRemoteUpdate(7L, m, 0f, null);
		assertNotNull(hub.ghosts().get(7L));
		assertNotNull(hub.ghosts().get(7L).pose(0.5f, null));
	}

	@Test
	public void aPushRidesWithTheNextSnapshotAndCarriesItsTime()
	{
		audience();
		frame(0f, frame(0f), 0, false, true);
		assertEquals(1, link.updates());
		// a push: a passive event, nothing goes out at once
		frame(0.1f, frame(5f), GhostCodec.EV_PUSH, false, true);
		frame(0.2f, frame(10f), 0, false, true);
		assertEquals(1, link.updates());
		// the next snapshot carries it, and when it happened
		frame(0.6f, frame(30f), 0, false, true);
		assertEquals(2, link.updates());
		SkateGhostUpdate m = (SkateGhostUpdate) link.sent.get(link.sent.size() - 1);
		assertEquals(GhostCodec.EV_PUSH, m.ev);
		GhostTrajectory tj = GhostTrajectory.decode(m.tj, m.ev, m.x, m.y, m.h, m.hd);
		assertEquals(0.5f, tj.eventAgo[11], 0.006f);
		assertEquals(600, tj.timeMs);
		// a pop still goes at once
		frame(0.7f, frame(35f), GhostCodec.EV_POP, false, true);
		assertEquals(2, link.updates());
		frame(1.21f, frame(40f), GhostCodec.EV_POP, false, true);
		assertEquals(3, link.updates());
	}

	@Test
	public void everyUpdateCarriesItsPositionsSinceTheLastAndNothingCarriesOverAStop()
	{
		audience();
		for (int i = 0; i <= 90; i++)
		{
			frame(i * FRAME, frame(i * 10f), 0, false, true);
		}
		SkateGhostUpdate last = (SkateGhostUpdate) link.sent.get(link.sent.size() - 1);
		GhostTrajectory tj = GhostTrajectory.decode(last.tj, last.ev, last.x, last.y, last.h, last.hd);
		assertTrue(tj.count >= 3);
		for (int i = 0; i < tj.count; i++)
		{
			// 10 units a frame
			assertEquals(last.x - tj.ago[i] / FRAME * 10f, tj.x[i], 10.5f);
		}
		hub.onLocalSkateEnd(2f);
		int before = link.sent.size();
		frame(10f, frame(5000f), 0, false, true);
		SkateGhostUpdate fresh = (SkateGhostUpdate) link.sent.get(before);
		assertEquals(0, GhostTrajectory.decode(fresh.tj, fresh.ev, fresh.x, fresh.y, fresh.h, fresh.hd).count);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.FootEvent;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.client.party.messages.WebsocketMessage;
import net.runelite.client.util.RuntimeTypeAdapterFactory;
import org.junit.Test;

/** On-foot ghosts: the new fields, their validation and their backward compatibility. */
public class GhostOffBoardTest
{
	private static final Gson GSON = new GsonBuilder()
		.registerTypeAdapterFactory(RuntimeTypeAdapterFactory.of(WebsocketMessage.class)
			.registerSubtype(SkateGhostUpdate.class)
			.registerSubtype(SkateGhostStop.class))
		.create();

	private static GhostState walker(BoardState board, float bx, float by, float bh, float bd)
	{
		return GhostFeed.onFoot(330, 2, 409_600f, 411_200f, 40f, 1.5f, 120f, -150f, 0f, false, 0.4f, board, bx, by,
			bh, bd);
	}

	@Test
	public void onTheBoardNothingNewGoesOnTheWire()
	{
		GhostState f = GhostFeed.frame(330, 2, 1f, 2f, 3f, 0f, 0f, 0f, 0f, SkaterState.ROLLING, null, null, 0f);
		SkateGhostUpdate m = GhostCodec.encode(f, 0, null);
		String json = GSON.toJson(m, WebsocketMessage.class);
		assertFalse(json, json.contains("\"ob\""));
		assertFalse(json, json.contains("\"bx\""));
		assertNull(GhostCodec.decode(m).offBoard);
	}

	@Test
	public void aCarryingWalkerRoundTrips()
	{
		SkateGhostUpdate m = GhostCodec.encode(walker(BoardState.CARRIED, 0f, 0f, 0f, 0f), 0, null);
		String json = GSON.toJson(m, WebsocketMessage.class);
		assertTrue(json, json.contains("\"ob\":\"CARRIED\""));
		// a carried board has no position of its own
		assertFalse(json, json.contains("\"bx\""));
		GhostState s = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		assertEquals(BoardState.CARRIED, s.offBoard);
		assertEquals(SkaterState.ROLLING, s.state);
		assertEquals(409_600f, s.x, 0.5f);
		assertEquals(120f, s.vx, 0.5f);
		assertEquals(1.5f, s.heading, 0.001f);
		assertEquals(0.4f, s.turnRate, 0.001f);
	}

	@Test
	public void aDroppedBoardRoundTripsWithinRounding()
	{
		SkateGhostUpdate m = GhostCodec.encode(walker(BoardState.DROPPED, 409_700.4f, 411_000.6f, 32.2f, -2.5f), 0,
			null);
		String json = GSON.toJson(m, WebsocketMessage.class);
		GhostState s = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		assertEquals(BoardState.DROPPED, s.offBoard);
		assertEquals(409_700.4f, s.boardX, 0.5f);
		assertEquals(411_000.6f, s.boardY, 0.5f);
		assertEquals(32.2f, s.boardH, 0.5f);
		assertEquals(-2.5f, s.boardHeading, 0.001f);
	}

	@Test
	public void anOnFootUpdateStaysSmall()
	{
		GhostState f = GhostFeed.onFoot(330, 2, 1_409_664f, 1_411_200f, -1237f, -3.14159f, -384f, -384f, -1820f,
			true, -TurnRateMeter.MAX_RATE, BoardState.DROPPED, 1_409_000f, 1_411_999f, -1237f, -3.14159f);
		SkateGhostUpdate m = GhostCodec.encode(f, 0x3ff, null);
		m.seq = 1_234_567_890;
		m.dk = "PARTYHAT_PURPLE";
		String json = GSON.toJson(m, WebsocketMessage.class);
		assertTrue(json, json.length() <= 280);
	}

	@Test
	public void anOldMessageIsOnTheBoard()
	{
		String json = "{\"type\":\"SkateGhostUpdate\",\"w\":330,\"x\":5,\"st\":\"MANUAL\",\"hold\":\"MANUAL\",\"seq\":3}";
		GhostState s = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		assertNull(s.offBoard);
		assertEquals(SkaterState.MANUAL, s.state);
		assertEquals(Trick.MANUAL, s.hold);
	}

	@Test
	public void unknownOrBrokenBoardFieldsAreSafe()
	{
		// an unknown board state (a later version): on the board, as an old message
		String json = "{\"type\":\"SkateGhostUpdate\",\"w\":330,\"ob\":\"FLYING\",\"seq\":3}";
		assertNull(GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class)).offBoard);
		// dropped with no position: drawn carried
		json = "{\"type\":\"SkateGhostUpdate\",\"w\":330,\"ob\":\"DROPPED\",\"bx\":5,\"seq\":3}";
		assertEquals(BoardState.CARRIED,
			GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class)).offBoard);
		// a dropped board sent without its heading lies with its nose north
		json = "{\"type\":\"SkateGhostUpdate\",\"w\":330,\"ob\":\"DROPPED\",\"bx\":5,\"by\":6,\"bh\":7,\"seq\":3}";
		GhostState s = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		assertEquals(BoardState.DROPPED, s.offBoard);
		assertEquals(0f, s.boardHeading, 0f);
	}

	@Test
	public void aDroppedBoardImplausiblyFarAwayIsDrawnCarried()
	{
		float far = GhostCodec.MAX_BOARD_DISTANCE + 10f;
		GhostState s = GhostCodec.decode(GhostCodec.encode(walker(BoardState.DROPPED, 409_600f + far, 411_200f, 40f,
			0f), 0, null));
		assertEquals(BoardState.CARRIED, s.offBoard);
		s = GhostCodec.decode(GhostCodec.encode(walker(BoardState.DROPPED, 409_600f, 411_200f,
			40f + GhostCodec.MAX_BOARD_DISTANCE + 10f, 0f), 0, null));
		assertEquals(BoardState.CARRIED, s.offBoard);
		s = GhostCodec.decode(GhostCodec.encode(walker(BoardState.DROPPED, 409_600f + 1000f, 411_200f, 40f, 0f), 0,
			null));
		assertEquals(BoardState.DROPPED, s.offBoard);
	}

	@Test
	public void aWalkerNeverGrindsFlipsOrBails()
	{
		SkateGhostUpdate m = GhostCodec.encode(walker(BoardState.CARRIED, 0f, 0f, 0f, 0f), 0, null);
		m.st = "GRINDING";
		m.hold = "BOARDSLIDE";
		m.tr = "KICKFLIP";
		m.ft = 100;
		m.bf = 3000;
		m.bw = 6000;
		GhostState s = GhostCodec.decode(m);
		assertEquals(SkaterState.ROLLING, s.state);
		assertNull(s.hold);
		assertNull(s.trick);
		assertEquals(0f, s.bodyFlip, 0f);
		assertEquals(0f, s.bodyFlipRate, 0f);
		m.st = "AIRBORNE";
		assertEquals(SkaterState.AIRBORNE, GhostCodec.decode(m).state);
	}

	@Test
	public void boardFieldsCountAsAStateChange()
	{
		SkateGhostUpdate a = GhostCodec.encode(walker(BoardState.DROPPED, 409_700f, 411_000f, 32f, 0f), 0, null);
		SkateGhostUpdate b = GhostCodec.encode(walker(BoardState.DROPPED, 409_700f, 411_000f, 32f, 0f), 0, null);
		assertTrue(a.sameState(b));
		b = GhostCodec.encode(walker(BoardState.DROPPED, 409_800f, 411_000f, 32f, 0f), 0, null);
		assertFalse(a.sameState(b));
		b = GhostCodec.encode(walker(BoardState.CARRIED, 0f, 0f, 0f, 0f), 0, null);
		assertFalse(a.sameState(b));
	}

	@Test
	public void footEventsAndSwapsGoOutAsEvents()
	{
		assertEquals(GhostCodec.EV_POP, GhostCodec.footEventBits(Collections.singletonList(FootEvent.JUMP)));
		assertEquals(GhostCodec.EV_LAND, GhostCodec.footEventBits(Collections.singletonList(FootEvent.LAND)));
		assertEquals(0, GhostCodec.footEventBits(Collections.singletonList(FootEvent.FALL)));
		assertEquals(GhostCodec.EV_POP | GhostCodec.EV_LAND,
			GhostCodec.footEventBits(Arrays.asList(FootEvent.JUMP, FootEvent.LAND)));

		assertEquals(0, GhostCodec.swapBits(null, null));
		assertEquals(GhostCodec.EV_BOARD_SWAP, GhostCodec.swapBits(null, BoardState.CARRIED));
		assertEquals(GhostCodec.EV_BOARD_SWAP, GhostCodec.swapBits(BoardState.CARRIED, BoardState.DROPPED));
		assertEquals(GhostCodec.EV_BOARD_SWAP, GhostCodec.swapBits(BoardState.DROPPED, null));
		assertEquals(0, GhostCodec.swapBits(BoardState.DROPPED, BoardState.DROPPED));
	}

	@Test
	public void newEventBitsDoNotCollide()
	{
		int old = GhostCodec.EV_POP | GhostCodec.EV_LAND | GhostCodec.EV_BAIL | GhostCodec.EV_RESET
			| GhostCodec.EV_GRIND_LOCK | GhostCodec.EV_GRIND_EXIT | GhostCodec.EV_TRICK | GhostCodec.EV_BODY_FLIP;
		assertEquals(0, old & GhostCodec.EV_BOARD_SWAP);
		assertEquals(0, old & GhostCodec.EV_GAIT);
		assertEquals(0, GhostCodec.EV_BOARD_SWAP & GhostCodec.EV_GAIT);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * A synthetic skate path through a real sender, Gson and a simulated network (150 ms +- 80 ms, 5 % loss, a 0.5 s
 * stall every 9 s) into a receiver: the timeline's playback against the true path at the playback time and at its
 * best constant lag.
 */
public class GhostPlaybackSimulationTest
{
	private static final float SECONDS = 90f;
	private static final float SKIP = 3f;

	@Test
	public void playbackFollowsTheTruePathCloselyAndSmoothly()
	{
		GhostSim.Net net = new GhostSim.Net();
		GhostSim timed = new GhostSim();
		timed.run(SECONDS, net);
		GhostSim.Stats t = timed.stats(SKIP, true, 0);
		GhostSim.Stats tBest = timed.bestLag(SKIP);

		double minDelay = Double.MAX_VALUE;
		double maxDelay = 0;
		double minRate = Double.MAX_VALUE;
		double maxRate = 0;
		double maxRateChange = 0;
		int underrunFrames = 0;
		int frames = 0;
		double[] prev = null;
		for (double[] d : timed.drawn)
		{
			if (d[0] < SKIP)
			{
				continue;
			}
			frames++;
			minDelay = Math.min(minDelay, d[7]);
			maxDelay = Math.max(maxDelay, d[7]);
			minRate = Math.min(minRate, d[6]);
			maxRate = Math.max(maxRate, d[6]);
			if (d[8] != 0)
			{
				underrunFrames++;
			}
			else if (prev != null && prev[8] == 0)
			{
				maxRateChange = Math.max(maxRateChange, Math.abs(d[6] - prev[6]) / GhostSim.DRAW_DT);
			}
			prev = d;
		}
		System.out.println("timeline vs truth at playback time: " + t);
		System.out.println("timeline vs truth at best constant lag: " + tBest);
		System.out.println(String.format("playback delay %.2f..%.2f s, rate %.3f..%.3f changing at most %.2f/s with "
			+ "samples to play, "
			+ "buffer dry %.1f %% of frames; updates %d sent, %d delivered,"
			+ " biggest %d chars", minDelay, maxDelay, minRate, maxRate, maxRateChange, 100.0 * underrunFrames / frames,
			timed.sentUpdates, timed.delivered,
			timed.maxJson));

		assertTrue("biggest update " + timed.maxJson, timed.maxJson <= GhostWire.MAX_UPDATE_CHARS);
		// close to the true path
		assertTrue(t.toString(), t.p95 < 12);
		assertTrue(t.toString(), t.max < 128);
		// no jumps: the velocity drawn never changes by more than a hard landing does in a frame
		assertTrue(t.toString(), t.p99Dv < 100);
		assertTrue(t.toString(), t.maxDv < 200);
		// never a visible speed change of playback while there are samples to play: it eases (a slight fast-forward
		// only to catch up after the buffer ran dry)
		assertTrue("rate change " + maxRateChange, maxRateChange <= GhostTimeline.RATE_SLEW * 1.02);
		assertTrue(minRate + ".." + maxRate, minRate >= 0
			&& maxRate <= 1 + GhostTimeline.MAX_CATCH_UP + 1e-6);
		assertTrue("dry " + underrunFrames + " of " + frames, underrunFrames < frames * 0.05);
		assertTrue(minDelay + ".." + maxDelay, minDelay >= GhostClockSync.MIN_DELAY
			&& maxDelay <= GhostClockSync.MAX_DELAY);
	}

	/** Runs the timeline under {@code net}; its stats at the best constant lag. */
	private static GhostSim.Stats run(String name, GhostSim.Net net)
	{
		GhostSim timed = new GhostSim();
		timed.run(SECONDS, net);
		GhostSim.Stats t = timed.stats(SKIP, true, 0);
		GhostSim.Stats tBest = timed.bestLag(SKIP);
		double delay = timed.drawn.get(timed.drawn.size() - 1)[7];
		System.out.println(name + ": timeline " + t + " | at best constant lag " + tBest
			+ String.format(" | delay %.2f s", delay));
		return tBest;
	}

	@Test
	public void aGoodConnectionGetsAShorterDelayAndAHarshOneStaysSmooth()
	{
		GhostSim.Net lan = new GhostSim.Net();
		lan.latency = 0.03f;
		lan.jitter = 0.01f;
		lan.loss = 0f;
		lan.stall = 0f;
		GhostSim.Stats good = run("good connection (30 +- 10 ms, no loss)", lan);
		assertTrue(good.lag < 0.75);

		GhostSim.Net harsh = new GhostSim.Net();
		harsh.latency = 0.25f;
		harsh.jitter = 0.15f;
		harsh.loss = 0.1f;
		harsh.stall = 0.8f;
		harsh.stallEvery = 7f;
		GhostSim.Stats bad = run("harsh connection (250 +- 150 ms, 10 % loss, 0.8 s stall every 7 s)", harsh);
		assertTrue(bad.toString(), bad.maxDv < 200);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.FootPhysics;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.BodyPose;
import org.junit.Test;

public class GhostRigOnFootTest
{
	private static final float FRAME = GhostFeed.FRAME;
	private static final float DELAY = GhostFeed.DELAY;

	private final GhostFeed feed = new GhostFeed();
	private final GhostRig rig = new GhostRig();
	private final BodyPose out = new BodyPose();

	public GhostRigOnFootTest()
	{
		feed.warmUp();
	}

	private void acceptWalker(SkaterState st, float vy, float vh, int events)
	{
		feed.send(GhostFeed.state(420, 0, 0f, 0f, 0f, 0f, 0f, vy, vh, st, null, events, null, 0f, 0, 0f, 0f, 0f,
			BoardState.CARRIED, 0f, 0f, 0f, 0f));
	}

	private void run(float seconds)
	{
		feed.run(seconds, (p, now) -> rig.updateOnFoot(p, p.pose(now, GhostFeed.FLAT), now, FRAME, out));
	}

	@Test
	public void aWalkingGhostStandsUpright()
	{
		acceptWalker(SkaterState.ROLLING, FootPhysics.SPRINT_SPEED, 0f, 0);
		run(DELAY + 0.5f);
		assertTrue(out.isNeutral());
	}

	@Test
	public void aJumpingGhostTucksAndLands()
	{
		acceptWalker(SkaterState.ROLLING, 0f, 0f, 0);
		run(0.1f);
		acceptWalker(SkaterState.AIRBORNE, 0f, FootPhysics.JUMP_VH, GhostCodec.EV_POP);
		run(DELAY + 0.35f);
		assertTrue("tucked: " + out.legScale, out.legScale < 0.9f);
		acceptWalker(SkaterState.ROLLING, 0f, 0f, GhostCodec.EV_LAND);
		run(1.5f);
		assertTrue(out.isNeutral());
	}

	@Test
	public void backOnTheBoardItSkatesAsBefore()
	{
		acceptWalker(SkaterState.AIRBORNE, 0f, FootPhysics.JUMP_VH, GhostCodec.EV_POP);
		run(DELAY + 0.35f);
		feed.send(GhostFeed.state(420, 0, 0f, 0f, 0f, 0f, 0f, 1200f, 0f, SkaterState.ROLLING, null, GhostCodec.EV_LAND,
			null, 0f, 0, 2f, 0f, 0f));
		feed.run(DELAY + 0.5f, (p, now) -> rig.update(p, p.pose(now, GhostFeed.FLAT), now, FRAME, out));
		assertTrue("leans into the carve: " + out.roll, out.roll < -0.3f);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.BodyFlip;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.BodyPose;
import org.junit.Test;

public class GhostRigTest
{
	private static final float FRAME = GhostFeed.FRAME;
	private static final float DELAY = GhostFeed.DELAY;

	private final GhostFeed feed = new GhostFeed();
	private final GhostPredictor predictor = feed.predictor;
	private final GhostRig rig = new GhostRig();
	private final BodyPose out = new BodyPose();

	public GhostRigTest()
	{
		feed.warmUp();
	}

	private void accept(SkaterState st, float h, float vy, float vh, int events, float turnRate, float bodyFlip,
		float bodyFlipRate)
	{
		feed.send(GhostFeed.state(420, 0, 0f, 0f, h, 0f, 0f, vy, vh, st, null, events, null, 0f, 0, turnRate, bodyFlip,
			bodyFlipRate));
	}

	private void run(float seconds)
	{
		feed.run(seconds, (p, now) -> rig.update(p, p.pose(now, GhostFeed.FLAT), now, FRAME, out));
	}

	@Test
	public void aCarvingGhostLeansIntoTheTurn()
	{
		// clockwise (right) at 2 rad/s and 1200 u/s: the physical lean is atan(1200 * 2 / 2000) = 0.88 rad
		accept(SkaterState.ROLLING, 0f, 1200f, 0f, 0, 2f, 0f, 0f);
		run(DELAY + 0.5f);
		assertTrue("leans right: " + out.roll, out.roll < -0.3f);
	}

	@Test
	public void aStraightRollingGhostKeepsTheStandingPose()
	{
		accept(SkaterState.ROLLING, 0f, 1200f, 0f, 0, 0f, 0f, 0f);
		run(DELAY + 0.5f);
		assertTrue(out.isNeutral());
	}

	@Test
	public void aPopTucksInTheAirAndALandingSquashesAndRecovers()
	{
		accept(SkaterState.AIRBORNE, 0f, 0f, 800f, GhostCodec.EV_POP, 0f, 0f, 0f);
		run(DELAY + 0.3f);
		assertTrue("tucked: " + out.legScale, out.legScale < 0.85f);
		accept(SkaterState.AIRBORNE, 100f, 0f, -800f, 0, 0f, 0f, 0f);
		run(0.1f);
		accept(SkaterState.ROLLING, 0f, 0f, 0f, GhostCodec.EV_LAND, 0f, 0f, 0f);
		run(DELAY + 0.1f);
		float squashed = out.legScale;
		assertTrue("squashed: " + squashed, squashed < 0.9f);
		run(0.8f);
		assertEquals(1f, out.legScale, 0.02f);
	}

	@Test
	public void theBodyFlipsWithTheGhost()
	{
		float held = Angles.TWO_PI / 0.55f;
		accept(SkaterState.AIRBORNE, 200f, 0f, 0f, GhostCodec.EV_POP, 0f, 0f, held);
		run(DELAY + 0.2f);
		assertEquals(predictor.bodyFlip(feed.now), out.flip, 0.01f);
		assertTrue(out.flip > 1f);
	}

	@Test
	public void aBailEasesTheFlipOutInsteadOfSnapping()
	{
		float held = Angles.TWO_PI / 0.55f;
		accept(SkaterState.AIRBORNE, 200f, 0f, 0f, GhostCodec.EV_POP, 0f, 0f, held);
		run(DELAY + 0.2f);
		accept(SkaterState.BAILED, 0f, 0f, 0f, GhostCodec.EV_BAIL, 0f, 0f, 0f);
		float[] step = {out.flip, 0f};
		feed.run(DELAY + 0.1f, (p, now) ->
		{
			rig.update(p, p.pose(now, GhostFeed.FLAT), now, FRAME, out);
			// a whole turn apart looks the same
			step[1] = Math.max(step[1], Math.abs(BodyFlip.residual(out.flip - step[0])));
			step[0] = out.flip;
		});
		assertTrue("no snap: " + step[1], step[1] < 0.5f);
		run(1f);
		assertEquals(0f, out.flip, 0.01f);
	}

	@Test
	public void aPushingGhostKicks()
	{
		accept(SkaterState.ROLLING, 0f, 300f, 0f, 0, 0f, 0f, 0f);
		run(DELAY + 0.3f);
		assertEquals(0f, out.legWeight, 0f);
		accept(SkaterState.ROLLING, 0f, 400f, 0f, GhostCodec.EV_PUSH, 0f, 0f, 0f);
		run(DELAY + 0.2f);
		assertTrue("the push leg swings: " + out.legWeight, out.legWeight > 0.1f);
		// it plays out and stands again
		run(1f);
		assertEquals(0f, out.legWeight, 0.01f);
	}

	@Test
	public void aChargingGhostCrouchesAndExtendsOnThePop()
	{
		feed.send(GhostFeed.withBody(GhostFeed.state(420, 0, 0f, 0f, 0f, 0f, 0f, 600f, 0f, SkaterState.ROLLING, null,
			0, null, 0f, 0), 1f, null, 0f));
		run(DELAY + 0.4f);
		assertTrue("crouched: " + out.legScale, out.legScale < 0.8f);
		accept(SkaterState.AIRBORNE, 0f, 600f, 800f, GhostCodec.EV_POP, 0f, 0f, 0f);
		run(DELAY + 0.05f);
		assertTrue("extends: " + out.legScale, out.legScale > 0.95f);
	}

	@Test
	public void aKnockedDownGhostTumblesLiesAndGetsUp()
	{
		float lie = 3 * (float) Math.PI / 2;
		rig.knockdown(new com.gielinorskate.render.KnockdownPose(
			com.gielinorskate.render.KnockdownPose.Stage.AIR, 0f, 0f, 0f, 0f, 0f, 1f, 0f, 0f, 0f, 0f, 0f, 0f, 0f),
			false, out);
		assertEquals(1f, out.flip, 0f);
		assertTrue(out.legScale < 1f);
		// an OSRS lie-down plays: the body is left as animated
		rig.knockdown(new com.gielinorskate.render.KnockdownPose(
			com.gielinorskate.render.KnockdownPose.Stage.LIE, 0.5f, 0f, 0f, 0f, 0f, lie, 0f, 0f, 0f, 0f, 0f, 0f, 0f),
			true, out);
		assertTrue(out.isNeutral());
		// back on the board the rig starts from standing (no left-over spring)
		accept(SkaterState.ROLLING, 0f, 300f, 0f, 0, 0f, 0f, 0f);
		run(FRAME);
		assertEquals(0f, out.flip, 0.01f);
		assertEquals(1f, out.legScale, 0.01f);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class GhostSendPolicyTest
{
	private static final float FRAME = 1f / 50f;

	@Test
	public void neverMoreThanTwoPerSecondEvenUnderEventSpam()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		List<Float> sent = new ArrayList<>();
		for (int i = 0; i < 500; i++)
		{
			float t = i * FRAME;
			// an event on every frame and the state always changing
			if (p.shouldSend(t, true, true))
			{
				p.recordSend(t);
				sent.add(t);
			}
		}
		// 10 s at 2 per second
		assertTrue(sent.size() >= 18);
		assertTrue(sent.size() <= 20);
		for (int i = 2; i < sent.size(); i++)
		{
			// any 3 consecutive sends span at least a second, so no 1 s window holds more than 2
			assertTrue("window at " + sent.get(i), sent.get(i) - sent.get(i - 2) >= 1f - 1e-4f);
		}
	}

	@Test
	public void eventsGoOutImmediately()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		p.recordSend(0f);
		assertTrue(p.shouldSend(0.05f, false, true));
	}

	@Test
	public void snapshotOnlyOnChangeAndAtMostOncePerTick()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		assertTrue(p.shouldSend(0f, true, false));
		p.recordSend(0f);
		// changed, but within the same 0.6 s tick
		assertFalse(p.shouldSend(0.3f, true, false));
		assertTrue(p.shouldSend(0.6f, true, false));
		p.recordSend(0.6f);
		// unchanged: nothing, tick after tick, until the keep-alive is due
		for (int i = 2; i < 17; i++)
		{
			float t = i * 0.6f;
			assertFalse("at " + t, p.shouldSend(t, false, false));
		}
	}

	@Test
	public void keepAliveAfterTenSecondsIdle()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		p.recordSend(0f);
		assertFalse(p.shouldSend(9.9f, false, false));
		assertTrue(p.shouldSend(10f, false, false));
	}

	@Test
	public void resetAllowsAnImmediateFirstSnapshot()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		p.recordSend(5f);
		p.reset();
		assertTrue(p.shouldSend(5.1f, true, false));
	}

	@Test
	public void resetDoesNotRefillTheRateLimit()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		for (int i = 0; i < GhostSendPolicy.MAX_PER_SECOND; i++)
		{
			p.recordSend(0.01f * i);
		}
		p.reset();
		assertFalse(p.hasToken(0.5f));
		assertTrue(p.hasToken(1.0f));
	}

	@Test
	public void limitIsTwoPerSecond()
	{
		assertEquals(2, GhostSendPolicy.MAX_PER_SECOND);
	}

	@Test
	public void announceAtMostEveryFiveSeconds()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		assertTrue("first announce at once", p.shouldAnnounce(0f));
		p.recordSend(0f);
		assertFalse(p.shouldAnnounce(4.9f));
		assertTrue(p.shouldAnnounce(5f));
		p.recordSend(5f);
		p.reset();
		// a new session announces as soon as a stop could follow its announce within the limit
		assertFalse(p.shouldAnnounce(5.5f));
		assertTrue("a new session announces at once", p.shouldAnnounce(6f));
	}

	@Test
	public void announceRespectsTheRateLimit()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		p.recordSend(0f);
		p.recordSend(0.1f);
		p.reset();
		assertFalse(p.shouldAnnounce(0.5f));
		// one token back, but none would be left for the stop that may follow the announce
		assertFalse(p.shouldAnnounce(1.0f));
		assertTrue(p.shouldAnnounce(1.1f));
	}

	@Test
	public void sequenceNumbersIncrease()
	{
		GhostSendPolicy p = new GhostSendPolicy(0);
		int a = p.nextSeq();
		p.reset();
		int b = p.nextSeq();
		int c = p.nextSeq();
		assertTrue(b > a);
		assertTrue(c > b);
	}
}

package com.gielinorskate.party;

import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;
import java.util.Random;
import net.runelite.client.party.messages.PartyMessage;
import net.runelite.client.party.messages.WebsocketMessage;
import net.runelite.client.util.RuntimeTypeAdapterFactory;

/**
 * A test bench for ghosts: a synthetic skater (carving over hills, pushing, popping kickflips) sent through a real
 * {@link GhostHub}, its updates through Gson and a simulated network (latency, jitter, loss, stalls), into a
 * receiving hub drawn every frame. Records the true path and what was drawn.
 */
final class GhostSim
{
	static final Gson GSON = new GsonBuilder()
		.registerTypeAdapterFactory(RuntimeTypeAdapterFactory.of(WebsocketMessage.class)
			.registerSubtype(SkateGhostUpdate.class)
			.registerSubtype(SkateGhostStop.class))
		.create();
	static final float SEND_DT = 0.02f;
	static final float DRAW_DT = 1f / 60f;
	static final long MEMBER = 7L;
	/** Our clock minus the sender's. */
	static final float CLOCK_OFFSET = 1000f;

	/** The hills both clients stand on. */
	static float terrain(float x, float y)
	{
		return (float) (40 * Math.sin(x / 900.0) + 25 * Math.cos(y / 700.0));
	}

	static final GhostPredictor.Ground GROUND = GhostSim::terrain;

	/** Network conditions. */
	static final class Net
	{
		float latency = 0.15f;
		float jitter = 0.08f;
		float loss = 0.05f;
		/** Every this many seconds, a stall this long holds every update back until it ends. */
		float stallEvery = 9f;
		float stall = 0.5f;
		long seed = 42;
	}

	// the true path, every sender frame
	final List<float[]> truth = new ArrayList<>();
	// what was drawn: {our time, x, y, h, heading, playback time (sender s), rate}
	final List<double[]> drawn = new ArrayList<>();
	final List<float[]> pops = new ArrayList<>();
	int sentUpdates;
	int maxJson;
	int delivered;
	/** Pop counts seen by the receiver at each draw. */
	final List<Integer> popCounts = new ArrayList<>();

	private static final class Delivery implements Comparable<Delivery>
	{
		final float at;
		final String json;
		final int order;

		Delivery(float at, String json, int order)
		{
			this.at = at;
			this.json = json;
			this.order = order;
		}

		@Override
		public int compareTo(Delivery o)
		{
			return at != o.at ? Float.compare(at, o.at) : Integer.compare(order, o.order);
		}
	}

	/** Runs {@code seconds} of skating under {@code net}. */
	void run(float seconds, Net net)
	{
		Random rnd = new Random(net.seed);
		List<PartyMessage> out = new ArrayList<>();
		GhostHub sender = new GhostHub(new GhostHub.Link()
		{
			@Override
			public boolean inParty()
			{
				return true;
			}

			@Override
			public void send(PartyMessage message)
			{
				out.add(message);
			}
		}, 1000);
		// someone is watching, so full updates go out
		SkateGhostUpdate hello = new SkateGhostUpdate();
		hello.w = 330;
		hello.st = "ROLLING";
		hello.seq = 1;
		sender.onRemoteUpdate(99L, hello, 0f, null);
		GhostHub receiver = new GhostHub(new GhostHub.Link()
		{
			@Override
			public boolean inParty()
			{
				return true;
			}

			@Override
			public void send(PartyMessage message)
			{
			}
		}, 5000);

		PriorityQueue<Delivery> wire = new PriorityQueue<>();
		int order = 0;
		// the skater
		float x = 1_409_664f;
		float y = 1_411_200f;
		float heading = 0.3f;
		float speed = 600f;
		float h = terrain(x, y);
		float vh = 0f;
		SkaterState state = SkaterState.ROLLING;
		float nextPush = 1.3f;
		float nextPop = 2.1f;
		float flipStart = Float.NaN;
		Trick flip = Trick.KICKFLIP;
		float nextDraw = 0f;
		int drawNo = 0;
		for (int frameNo = 0; frameNo * SEND_DT < seconds; frameNo++)
		{
			float s = frameNo * SEND_DT;
			int events = 0;
			float w = (float) (1.4 * Math.sin(0.7 * s) + 0.6 * Math.sin(1.9 * s));
			heading += w * SEND_DT;
			if (heading > Math.PI)
			{
				heading -= 2 * Math.PI;
			}
			else if (heading <= -Math.PI)
			{
				heading += 2 * Math.PI;
			}
			speed = Math.max(0f, speed - 40f * SEND_DT);
			if (state == SkaterState.ROLLING && s >= nextPush)
			{
				speed = Math.min(1400f, speed + 120f);
				events |= GhostCodec.EV_PUSH;
				nextPush = s + 2.5f;
			}
			float vx = (float) Math.sin(heading) * speed;
			float vy = (float) Math.cos(heading) * speed;
			x += vx * SEND_DT;
			y += vy * SEND_DT;
			if (state == SkaterState.ROLLING && s >= nextPop)
			{
				state = SkaterState.AIRBORNE;
				vh = 820f;
				events |= GhostCodec.EV_POP | GhostCodec.EV_TRICK;
				flipStart = s;
				pops.add(new float[]{s});
				nextPop = s + 3.7f;
			}
			if (state == SkaterState.AIRBORNE)
			{
				h += vh * SEND_DT - GhostPredictor.GRAVITY / 2f * SEND_DT * SEND_DT;
				vh -= GhostPredictor.GRAVITY * SEND_DT;
				float g = terrain(x, y);
				if (h <= g && vh < 0f)
				{
					h = g;
					vh = 0f;
					state = SkaterState.ROLLING;
					events |= GhostCodec.EV_LAND;
				}
			}
			else
			{
				h = terrain(x, y);
			}
			Trick flipNow = null;
			float progress = 0f;
			if (!Float.isNaN(flipStart) && s - flipStart < flip.duration)
			{
				flipNow = flip;
				progress = (s - flipStart) / flip.duration;
			}
			truth.add(new float[]{s, x, y, h, heading});
			GhostState frame = GhostFeed.frame(330, 0, x, y, h, heading, vx, vy,
				state == SkaterState.AIRBORNE ? vh : 0f, state, null, flipNow, progress, w);
			out.clear();
			sender.onLocalFrame(frame, events, (events & GhostCodec.EV_TRICK) != 0 ? flip : null, false, true, s);
			for (PartyMessage m : out)
			{
				if (!(m instanceof SkateGhostUpdate))
				{
					continue;
				}
				SkateGhostUpdate u = (SkateGhostUpdate) m;
				sentUpdates++;
				String json = GSON.toJson(u, WebsocketMessage.class);
				maxJson = Math.max(maxJson, json.length());
				if (rnd.nextFloat() < net.loss)
				{
					continue;
				}
				float at = s + net.latency + (rnd.nextFloat() * 2f - 1f) * net.jitter;
				float phase = s % net.stallEvery;
				if (net.stall > 0f && s > net.stallEvery && phase < net.stall)
				{
					// held back until the stall ends, then out in a burst
					at = Math.max(at, s - phase + net.stall + net.latency);
				}
				wire.add(new Delivery(at, json, order++));
			}
			// our frames up to this sender frame
			while (nextDraw <= s)
			{
				while (!wire.isEmpty() && wire.peek().at <= nextDraw)
				{
					Delivery d = wire.poll();
					SkateGhostUpdate u = (SkateGhostUpdate) GSON.fromJson(d.json, WebsocketMessage.class);
					receiver.onRemoteUpdate(MEMBER, u, nextDraw + CLOCK_OFFSET, GROUND);
					delivered++;
				}
				GhostPredictor g = receiver.ghosts().get(MEMBER);
				if (g != null)
				{
					float now = nextDraw + CLOCK_OFFSET;
					com.gielinorskate.render.RenderPose p = g.pose(now, GROUND);
					drawn.add(new double[]{nextDraw, p.x, p.y, p.h, p.heading, g.tp, g.rate,
						g.sync.delay(), g.dry || g.n > 0 && g.tp > g.t[g.n - 1] ? 1 : 0});
					popCounts.add(g.popCount());
				}
				drawNo++;
				nextDraw = drawNo * DRAW_DT;
			}
		}
	}

	/** The true position {x, y, h} at sender time {@code s} (linear between frames). */
	float[] truthAt(double s)
	{
		int i = (int) Math.floor(s / SEND_DT + 1e-6);
		i = Math.max(0, Math.min(truth.size() - 2, i));
		float[] a = truth.get(i);
		float[] b = truth.get(i + 1);
		float u = (float) Math.max(0, Math.min(1, (s - a[0]) / (b[0] - a[0])));
		return new float[]{a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u, a[3] + (b[3] - a[3]) * u};
	}

	/** Error statistics of what was drawn against the truth. */
	static final class Stats
	{
		double mean;
		double p95;
		double max;
		double lag;
		/** Largest frame-to-frame change of velocity, u/s per frame, and its 99th percentile. */
		double maxDv;
		double p99Dv;

		@Override
		public String toString()
		{
			return String.format("mean %.1f, p95 %.1f, max %.1f units (lag %.2f s); velocity change per frame p99 %.0f,"
				+ " max %.0f u/s", mean, p95, max, lag, p99Dv, maxDv);
		}
	}

	/**
	 * Errors from {@code skip} seconds on: against the truth at the playback time when {@code atPlayback}, else at a
	 * constant lag {@code lag} behind the sender's clock.
	 */
	Stats stats(float skip, boolean atPlayback, double lag)
	{
		List<Double> errors = new ArrayList<>();
		for (double[] d : drawn)
		{
			if (d[0] < skip)
			{
				continue;
			}
			double s = atPlayback ? d[5] : d[0] - lag;
			float[] t = truthAt(s);
			errors.add(Math.sqrt(sq(d[1] - t[0]) + sq(d[2] - t[1]) + sq(d[3] - t[2])));
		}
		Stats st = new Stats();
		errors.sort(null);
		double sum = 0;
		for (double e : errors)
		{
			sum += e;
		}
		st.mean = sum / errors.size();
		st.p95 = errors.get((int) (errors.size() * 0.95));
		st.max = errors.get(errors.size() - 1);
		st.lag = lag;
		List<Double> dvs = new ArrayList<>();
		for (int i = 2; i < drawn.size(); i++)
		{
			double[] a = drawn.get(i - 2);
			double[] b = drawn.get(i - 1);
			double[] c = drawn.get(i);
			if (a[0] < skip)
			{
				continue;
			}
			double dvx = (c[1] - 2 * b[1] + a[1]) / DRAW_DT;
			double dvy = (c[2] - 2 * b[2] + a[2]) / DRAW_DT;
			dvs.add(Math.hypot(dvx, dvy));
		}
		dvs.sort(null);
		st.maxDv = dvs.get(dvs.size() - 1);
		st.p99Dv = dvs.get((int) (dvs.size() * 0.99));
		return st;
	}

	/** {@link #stats} at the constant lag that fits best (0..1.5 s). */
	Stats bestLag(float skip)
	{
		Stats best = null;
		for (int i = 0; i <= 150; i++)
		{
			Stats s = stats(skip, false, i * 0.01);
			if (best == null || s.mean < best.mean)
			{
				best = s;
			}
		}
		return best;
	}

	private static double sq(double v)
	{
		return v * v;
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkatePhysics;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.RenderPose;
import com.gielinorskate.tricks.Trick;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** Snapshot interpolation of a party ghost (GhostTimeline through GhostPredictor), with hand-made updates. */
public class GhostTimelineTest
{
	private static final GhostPredictor.Ground FLAT = (x, y) -> 0f;
	/** Our clock minus the sender's. */
	private static final float OFFSET = 7.5f;
	private static final float LATENCY = 0.1f;
	/** Small coordinates: float rounding of world coordinates (1/8 unit there) would hide what these tests measure. */
	private static final float X0 = 12_800f;
	private static final float Y0 = 25_600f;
	private static final float G = GhostPredictor.GRAVITY;

	/** The true skater at a time: {x, y, h, heading, vx, vy, vh, state ordinal, turn rate}. */
	private interface Path
	{
		float[] at(double t);
	}

	/** Carving round a circle at {@code v} u/s, turning at {@code w} rad/s. */
	private static Path carve(float v, float w, float heading0)
	{
		return t ->
		{
			double th = heading0 + w * t;
			return new float[]{(float) (X0 - v / w * Math.cos(th)), (float) (Y0 + v / w * Math.sin(th)), 0f,
				Angles.wrap((float) th), (float) (v * Math.sin(th)), (float) (v * Math.cos(th)), 0f,
				SkaterState.ROLLING.ordinal(), w};
		};
	}

	/** Straight along x at 600 u/s, popping at 820 u/s at {@code pop}, landing on flat ground. */
	private static Path jump(double pop)
	{
		double land = pop + 2 * 820.0 / G;
		return t ->
		{
			boolean air = t > pop && t < land;
			double s = t - pop;
			float h = air ? (float) (820 * s - G / 2 * s * s) : 0f;
			float vh = air ? (float) (820 - G * s) : 0f;
			return new float[]{(float) (X0 + 600 * t), Y0, h, Angles.PI / 2, 600f, 0f, vh,
				(air ? SkaterState.AIRBORNE : SkaterState.ROLLING).ordinal(), 0f};
		};
	}

	private static double landOf(double pop)
	{
		return pop + 2 * 820.0 / G;
	}

	/**
	 * The update sent at {@code sent} with positions {@code ago} seconds before it, events {@code ev} that happened
	 * {@code evAgo} (by bit) before it.
	 */
	private static SkateGhostUpdate update(Path p, double sent, int seq, int ev, float[] evAgo, Trick flip,
		float flipTime, double... ago)
	{
		float[] f = p.at(sent);
		SkaterState st = SkaterState.values()[(int) f[7]];
		Trick flipTrick = flip != null && flipTime < flip.duration ? flip : null;
		GhostState frame = GhostFeed.frame(330, 0, f[0], f[1], f[2], f[3], f[4], f[5], f[6], st, null, flipTrick,
			flipTrick == null ? 0f : flipTime / flip.duration, f[8]);
		SkateGhostUpdate m = GhostCodec.encode(frame, ev, flip);
		m.seq = seq;
		int n = ago.length;
		float[] a = new float[n];
		float[] xs = new float[n];
		float[] ys = new float[n];
		float[] hs = new float[n];
		float[] hds = new float[n];
		SkaterState[] sts = new SkaterState[n];
		for (int i = 0; i < n; i++)
		{
			float[] s = p.at(sent - ago[i]);
			a[i] = (float) ago[i];
			xs[i] = s[0];
			ys[i] = s[1];
			hs[i] = s[2];
			hds[i] = s[3];
			sts[i] = SkaterState.values()[(int) s[7]];
		}
		m.tj = GhostFeed.wire(GhostTrajectory.timeMs((float) sent), ev, evAgo, n, a, xs, ys, hs, hds, sts,
			m.x, m.y, m.h, m.hd);
		return m;
	}

	private static SkateGhostUpdate update(Path p, double sent, int seq)
	{
		return update(p, sent, seq, 0, null, null, 0f, 0.15, 0.3, 0.45);
	}

	private static boolean accept(GhostPredictor g, SkateGhostUpdate m, float now, GhostPredictor.Ground ground)
	{
		return g.accept(GhostCodec.decode(m), GhostTrajectory.decode(m.tj, m.ev, m.x, m.y, m.h, m.hd), now, ground);
	}

	/** A run: updates every 0.6 s of {@code p} delivered after LATENCY, drawn every {@code dt}. */
	private static final class Run
	{
		final List<float[]> drawn = new ArrayList<>();
		final GhostPredictor g = new GhostPredictor();

		/**
		 * Draws from sender time {@code from} to {@code to}; updates sent at multiples of 0.6 s arrive after
		 * LATENCY, except those {@code skip} says not to deliver.
		 */
		Run go(Path p, double from, double to, double dt, java.util.function.IntPredicate skip)
		{
			int next = 0;
			for (double s = from; s < to; s += dt)
			{
				while (next * 0.6 + LATENCY <= s)
				{
					if (!skip.test(next))
					{
						accept(g, update(p, next * 0.6, next + 1), (float) (next * 0.6 + LATENCY) + OFFSET, FLAT);
					}
					next++;
				}
				if (next == 0)
				{
					continue;
				}
				RenderPose pose = g.pose((float) s + OFFSET, FLAT);
				drawn.add(new float[]{(float) s, pose.x, pose.y, pose.h, pose.heading, (float) g.tp,
					g.rate, g.speed()});
			}
			return this;
		}
	}

	@Test
	public void aCarveIsSmoothThroughEverySampleAndOnTheTruePath()
	{
		Path p = carve(800f, 1.5f, 0.2f);
		double dt = 0.001;
		Run r = new Run().go(p, 0, 6, dt, i -> false);
		double maxStep = 0;
		double maxDv = 0;
		double maxErr = 0;
		for (int i = 2; i < r.drawn.size(); i++)
		{
			float[] a = r.drawn.get(i - 2);
			float[] b = r.drawn.get(i - 1);
			float[] c = r.drawn.get(i);
			if (a[0] < 2)
			{
				continue;
			}
			maxStep = Math.max(maxStep, Math.hypot(c[1] - b[1], c[2] - b[2]));
			double dvx = ((c[1] - b[1]) - (b[1] - a[1])) / dt;
			double dvy = ((c[2] - b[2]) - (b[2] - a[2])) / dt;
			maxDv = Math.max(maxDv, Math.hypot(dvx, dvy));
			float[] t = p.at(c[5]);
			maxErr = Math.max(maxErr, Math.hypot(c[1] - t[0], c[2] - t[1]));
		}
		// at most 800 u/s (playback within 6 % of our clock) every millisecond
		assertTrue("step " + maxStep, maxStep <= 800 * 1.06 * dt + 0.01);
		// no velocity jump at a sample: per millisecond the velocity turns by v * w * dt = 1.2 u/s (and the playback
		// speed eases by a fraction of a percent)
		assertTrue("dv " + maxDv, maxDv <= 8);
		// on the circle (positions sent to whole units, headings to 1/100 rad)
		assertTrue("error " + maxErr, maxErr < 2.5);
		// interpolating, never past the last sample
		for (float[] d : r.drawn)
		{
			if (d[0] >= 2)
			{
				assertTrue(d[6] >= 1 - GhostTimeline.MAX_RATE_CHANGE - 1e-6);
			}
		}
	}

	@Test
	public void headingsWrapTheShortWayRound()
	{
		// turning clockwise through the +-PI seam at 2 rad/s
		Path p = carve(500f, 2f, 2.5f);
		Run r = new Run().go(p, 0, 4, 0.005, i -> false);
		for (int i = 1; i < r.drawn.size(); i++)
		{
			float[] a = r.drawn.get(i - 1);
			float[] b = r.drawn.get(i);
			if (a[0] < 1.5)
			{
				continue;
			}
			float turned = Angles.wrap(b[4] - a[4]);
			assertTrue(a[0] + ": " + turned, turned >= 0f && turned <= 2f * 1.07f * 0.005f + 1e-3f);
			float[] t = p.at(b[5]);
			assertTrue(Angles.absDiff(b[4], t[3]) < 0.02f);
		}
	}

	@Test
	public void aDryBufferExtrapolatesThenSettlesAndRecoversWithoutSnapping()
	{
		Path p = carve(900f, 0.8f, 0f);
		double dt = 1 / 60.0;
		// updates 5..7 never arrive: 1.8 s without any
		Run r = new Run().go(p, 0, 9, dt, i -> i >= 5 && i <= 7);
		double maxStep = 0;
		double maxDv = 0;
		boolean underran = false;
		float slowest = Float.MAX_VALUE;
		for (int i = 2; i < r.drawn.size(); i++)
		{
			float[] a = r.drawn.get(i - 2);
			float[] b = r.drawn.get(i - 1);
			float[] c = r.drawn.get(i);
			if (a[0] < 1.5)
			{
				continue;
			}
			maxStep = Math.max(maxStep, Math.hypot(c[1] - b[1], c[2] - b[2]));
			maxDv = Math.max(maxDv, Math.hypot((c[1] - 2 * b[1] + a[1]) / dt, (c[2] - 2 * b[2] + a[2]) / dt));
			assertTrue(c[6] >= 0 && c[6] <= 1 + GhostTimeline.MAX_CATCH_UP + 1e-6);
			if (c[6] < 1 - GhostTimeline.MAX_RATE_CHANGE)
			{
				underran = true;
			}
			if (c[0] > 4.6 && c[0] < 4.85)
			{
				slowest = Math.min(slowest, c[7]);
			}
		}
		assertTrue("the gap was noticed", underran);
		// settled to (nearly) a stop well into the silence instead of running on
		assertTrue("speed " + slowest, slowest < 150);
		// never a jump in position or velocity, even when the updates resume: at most a slight fast-forward
		assertTrue("step " + maxStep, maxStep <= 900 * (1 + GhostTimeline.MAX_CATCH_UP) * dt * 1.1);
		assertTrue("dv " + maxDv, maxDv < 3000);
		// back on the true path afterwards
		float[] last = r.drawn.get(r.drawn.size() - 1);
		float[] t = p.at(last[5]);
		assertEquals(0, Math.hypot(last[1] - t[0], last[2] - t[1]), 2.5);
	}

	@Test
	public void aPopPlaysWhenThePlaybackReachesItAndTheFlipStartsThere()
	{
		double pop = 3.03;
		Path p = jump(pop);
		GhostPredictor g = new GhostPredictor();
		// a quiet stretch first so the delay has settled
		for (int i = 0; i <= 5; i++)
		{
			accept(g, update(p, i * 0.6, i + 1), (float) (i * 0.6 + LATENCY) + OFFSET, FLAT);
		}
		// the pop's update was held back by the rate limit: sent 0.12 s after the pop, which it says
		float[] evAgo = new float[GhostTrajectory.EVENT_BITS];
		evAgo[0] = 0.12f;
		evAgo[6] = 0.12f;
		double sent = pop + 0.12;
		SkateGhostUpdate m = update(p, sent, 7, GhostCodec.EV_POP | GhostCodec.EV_TRICK, evAgo, Trick.KICKFLIP,
			0.12f, 0.1, 0.25);
		float arrive = (float) (sent + LATENCY) + OFFSET;
		int popsBefore = -1;
		boolean seen = false;
		for (double s = 3.0; s < 5.5; s += 0.004)
		{
			float now = (float) s + OFFSET;
			if (!seen && now >= arrive)
			{
				accept(g, m, arrive, FLAT);
				seen = true;
				// received, but not played yet
				assertEquals(0, g.popCount());
			}
			if (s > 3.6 + LATENCY && s < 3.62 + LATENCY)
			{
				accept(g, update(p, 3.6, 8, 0, null, Trick.KICKFLIP, (float) (3.6 - pop), 0.15, 0.3, 0.45),
					(float) (3.6 + LATENCY) + OFFSET, FLAT);
			}
			RenderPose pose = g.pose(now, FLAT);
			double tp = g.tp;
			if (popsBefore == 0 && g.popCount() == 1)
			{
				// the pop plays on the frame the playback passes it
				assertTrue("played at " + tp, tp >= pop && tp < pop + 0.006);
			}
			popsBefore = g.popCount();
			if (tp > pop + 0.05 && tp < pop + Trick.KICKFLIP.duration - 0.01)
			{
				// the board turns from the pop on the member's clock
				float expect = Trick.KICKFLIP.rollTurns * Angles.TWO_PI
					* SkatePhysics.flipEase((float) ((tp - pop) / Trick.KICKFLIP.duration));
				assertEquals(expect, pose.boardRoll, 0.02f);
			}
			if (tp < pop - 0.01)
			{
				assertEquals(0f, pose.boardRoll, 0f);
			}
		}
		assertEquals(1, g.popCount());
		assertNotNull(g.labelTrick());
	}

	@Test
	public void jumpsFollowTheGravityArcAndLandWithoutABump()
	{
		double pop = 2.5;
		Path p = jump(pop);
		double dt = 0.002;
		Run r = new Run().go(p, 0, 5, dt, i -> false);
		double maxErr = 0;
		double maxDvh = 0;
		for (int i = 2; i < r.drawn.size(); i++)
		{
			float[] a = r.drawn.get(i - 2);
			float[] b = r.drawn.get(i - 1);
			float[] c = r.drawn.get(i);
			if (a[0] < 1.5)
			{
				continue;
			}
			float[] t = p.at(c[5]);
			maxErr = Math.max(maxErr, Math.abs(c[3] - t[2]));
			boolean inAir = a[5] > pop + 0.01 && c[5] < landOf(pop) - 0.01;
			if (inAir)
			{
				maxDvh = Math.max(maxDvh, Math.abs((c[3] - 2 * b[3] + a[3]) / dt + G * dt));
			}
		}
		// heights sent to whole units: the arc is the true one within that
		assertTrue("error " + maxErr, maxErr < 1.5);
		// in the air the vertical speed changes by gravity, and at a sample by no more than whole-unit heights make it
		assertTrue("vertical speed jumps by " + maxDvh, maxDvh < 20);
	}

	@Test
	public void aLostLandingIsFoundOnTheArcNotGuessedAtTheNextSample()
	{
		double pop = 2.4;
		Path p = jump(pop);
		double land = landOf(pop);
		// the update just after the landing is lost (with the landing's own time)
		int lost = (int) Math.ceil(land / 0.6);
		Run r = new Run().go(p, 0, 5, 0.004, i -> i == lost);
		for (float[] d : r.drawn)
		{
			if (d[0] < 1.5)
			{
				continue;
			}
			float[] t = p.at(d[5]);
			assertTrue(d[5] + ": " + d[3] + " vs " + t[2], Math.abs(d[3] - t[2]) < 25);
		}
	}

	@Test
	public void aReorderedUpdateFillsInWithoutAJump()
	{
		Path p = carve(700f, -1.1f, 1f);
		GhostPredictor g = new GhostPredictor();
		List<float[]> drawn = new ArrayList<>();
		double dt = 1 / 60.0;
		for (double s = 0; s < 6; s += dt)
		{
			for (int i = 0; i < 10; i++)
			{
				// update 5 overtakes update 4 (which arrives 0.3 s late)
				double arrive = i * 0.6 + LATENCY + (i == 4 ? 0.4 : 0);
				if (arrive <= s && arrive > s - dt)
				{
					accept(g, update(p, i * 0.6, i + 1), (float) arrive + OFFSET, FLAT);
				}
			}
			if (g.latest() != null)
			{
				RenderPose pose = g.pose((float) s + OFFSET, FLAT);
				drawn.add(new float[]{(float) s, pose.x, pose.y, (float) g.tp});
			}
		}
		for (int i = 2; i < drawn.size(); i++)
		{
			float[] a = drawn.get(i - 2);
			float[] b = drawn.get(i - 1);
			float[] c = drawn.get(i);
			if (a[0] < 2)
			{
				continue;
			}
			assertTrue(Math.hypot(c[1] - b[1], c[2] - b[2]) <= 700 * 1.07 * dt + 0.5);
			assertTrue(Math.hypot((c[1] - 2 * b[1] + a[1]) / dt, (c[2] - 2 * b[2] + a[2]) / dt) < 600);
			float[] t = p.at(c[3]);
			assertTrue(Math.hypot(c[1] - t[0], c[2] - t[1]) < 4);
		}
	}

	@Test
	public void updatesWithoutRoomForTheTimelineArePlacedByArrival()
	{
		Path p = carve(600f, 0.5f, 0f);
		GhostPredictor g = new GhostPredictor();
		// with no timeline before it, an update has nothing to be placed on
		SkateGhostUpdate first = update(p, 0, 1);
		first.tj = null;
		assertFalse(accept(g, first, LATENCY + OFFSET, FLAT));
		assertNull(g.latest());
		double dt = 1 / 60.0;
		int next = 1;
		for (double s = 0.6; s < 12; s += dt)
		{
			while (next * 0.6 + LATENCY <= s)
			{
				SkateGhostUpdate m = update(p, next * 0.6, next + 1);
				if (next > 9)
				{
					// from 6 s on, no timeline (it did not fit)
					m.tj = null;
				}
				float arrive = (float) (next * 0.6 + LATENCY) + OFFSET;
				assertTrue(accept(g, m, arrive, FLAT));
				if (next > 9)
				{
					// placed on the timeline by its arrival
					RenderPose pose = g.pose((float) s + OFFSET, FLAT);
					float[] t = p.at(g.tp);
					assertEquals(0, Math.hypot(pose.x - t[0], pose.y - t[1]), 3);
				}
				next++;
			}
			if (g.latest() != null)
			{
				g.pose((float) s + OFFSET, FLAT);
			}
		}
	}

	@Test
	public void aRestartedSenderStartsAFreshTimeline()
	{
		Path p = carve(600f, 0.5f, 0f);
		GhostPredictor g = new GhostPredictor();
		for (int i = 0; i < 6; i++)
		{
			SkateGhostUpdate m = update(p, 100 + i * 0.6, i + 1);
			accept(g, m, (float) (100 + i * 0.6 + LATENCY) + OFFSET, FLAT);
		}
		g.pose(103.8f + OFFSET, FLAT);
		// the plugin restarted: its clock is near 0 again, its sequence numbers higher
		for (int i = 0; i < 6; i++)
		{
			SkateGhostUpdate m = update(p, 0.2 + i * 0.6, 1000 + i);
			accept(g, m, (float) (104 + i * 0.6 + LATENCY) + OFFSET, FLAT);
		}
		RenderPose pose = g.pose(107.4f + OFFSET, FLAT);
		double tp = g.tp;
		assertTrue("playing the new clock: " + tp, tp > 2 && tp < 3.4);
		float[] t = p.at(tp);
		assertEquals(0, Math.hypot(pose.x - t[0], pose.y - t[1]), 3);
	}

	@Test
	public void aTeleportSnapsInsteadOfSliding()
	{
		Path p = carve(600f, 0.5f, 0f);
		GhostPredictor g = new GhostPredictor();
		for (int i = 0; i < 6; i++)
		{
			accept(g, update(p, i * 0.6, i + 1), (float) (i * 0.6 + LATENCY) + OFFSET, FLAT);
		}
		// far away on the same plane, no positions in between (another world or plane is a fresh start)
		Path far = t -> new float[]{X0 + 20_000f, Y0, 0f, 0f, 0f, 0f, 0f, 0f, 0f};
		for (int i = 6; i < 10; i++)
		{
			accept(g, update(far, i * 0.6, i + 1, 0, null, null, 0f), (float) (i * 0.6 + LATENCY) + OFFSET, FLAT);
		}
		RenderPose pose = null;
		for (double s = 4; s < 6.5; s += 1 / 60.0)
		{
			pose = g.pose((float) s + OFFSET, FLAT);
		}
		assertEquals(X0 + 20_000f, pose.x, 1f);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

public class GhostTrajectoryTest
{
	private static GhostState at(float x, float y, float h, float heading, SkaterState st)
	{
		return GhostFeed.frame(330, 1, x, y, h, heading, 0f, 0f, 0f, st, null, null, 0f);
	}

	@Test
	public void samplesAndEventTimesRoundTripWithoutDrift()
	{
		float[] ago = {0.15f, 0.31f, 0.45f, 0.6f};
		float[] xs = {1_409_600.4f, 1_409_380.6f, 1_409_100.2f, 1_408_830f};
		float[] ys = {1_411_190f, 1_411_150f, 1_411_080f, 1_410_990f};
		float[] hs = {-120f, -40f, 0f, 3f};
		// headings across the +-PI seam
		float[] hd = {3.10f, -3.12f, -3.0f, 2.9f};
		SkaterState[] st = {SkaterState.AIRBORNE, SkaterState.AIRBORNE, SkaterState.ROLLING, SkaterState.GRINDING};
		float[] eventAgo = new float[GhostTrajectory.EVENT_BITS];
		eventAgo[0] = 0.33f;
		eventAgo[6] = 0f;
		int ev = GhostCodec.EV_POP | GhostCodec.EV_TRICK;
		String tj = GhostFeed.wire(123_456, ev, eventAgo, 4, ago, xs, ys, hs, hd, st, 1_409_664, 1_411_200,
			-150, -3140);
		GhostTrajectory back = GhostTrajectory.decode(tj, ev, 1_409_664, 1_411_200, -150, -3140);
		assertNotNull(back);
		assertEquals(123_456, back.timeMs);
		assertEquals(0.33f, back.eventAgo[0], 1e-4f);
		assertEquals(0f, back.eventAgo[6], 1e-4f);
		assertTrue(Float.isNaN(back.eventAgo[1]));
		assertEquals(4, back.count);
		for (int i = 0; i < 4; i++)
		{
			assertEquals(ago[i], back.ago[i], 0.005f + 1e-4f);
			assertEquals(Math.round(xs[i]), back.x[i], 0f);
			assertEquals(Math.round(ys[i]), back.y[i], 0f);
			assertEquals(Math.round(hs[i]), back.h[i], 0f);
			// never more than half a unit off, however long the chain
			assertTrue(back.heading[i] + " vs " + hd[i], Angles.absDiff(back.heading[i], hd[i]) <= 0.005f + 1e-4f);
			assertEquals(st[i], back.state[i]);
		}
		// four samples of fast skating (about 1900 u/s, rising and falling) in about 10 characters each
		assertTrue(tj, tj.length() <= 44);
	}

	@Test
	public void junkAndOtherVersionsAreIgnored()
	{
		assertNull(GhostTrajectory.decode(null, 0, 0, 0, 0, 0));
		assertNull(GhostTrajectory.decode("", 0, 0, 0, 0, 0));
		assertNull(GhostTrajectory.decode("!!!", 0, 0, 0, 0, 0));
		// header says 2 samples, none there
		assertNull(GhostTrajectory.decode("4000", 0, 0, 0, 0, 0));
		// version 1
		assertNull(GhostTrajectory.decode(GhostWire.ALPHABET.charAt(16) + "000", 0, 0, 0, 0, 0));
		// just a time
		GhostTrajectory t = GhostTrajectory.decode("0001", 0, 0, 0, 0, 0);
		assertNotNull(t);
		assertEquals(1, t.timeMs);
		assertEquals(0, t.count);
	}

	@Test
	public void theSendTimeWrapsEvery262Seconds()
	{
		assertEquals(0, GhostTrajectory.timeMs(0f));
		assertEquals(1500, GhostTrajectory.timeMs(1.5f));
		assertEquals(1000, GhostTrajectory.timeMs(GhostTrajectory.TIME_MOD / 1000f + 1f), 1);
	}

	@Test
	public void theTrailSendsThePositionsSinceTheLastUpdateNewestFirst()
	{
		GhostTrail trail = new GhostTrail();
		float now = 10f;
		for (int i = 0; i <= 60; i++)
		{
			float tt = now + i * 0.02f;
			trail.record(at(1000f + i * 10f, 500f, 0f, 0.5f, SkaterState.ROLLING), tt);
		}
		float sendAt = now + 1.2f;
		SkateGhostUpdate m = GhostCodec.encode(at(1000f + 600f, 500f, 0f, 0.5f, SkaterState.ROLLING), 0, null);
		trail.sent(now + 0.6f);
		String tj = trail.encode(m, sendAt, GhostTrail.MAX_SAMPLES, true);
		GhostTrajectory back = GhostTrajectory.decode(tj, 0, m.x, m.y, m.h, m.hd);
		assertNotNull(back);
		// positions newer than the update before (0.6 s) and at least 0.05 s older than this one
		assertTrue(back.count >= 3 && back.count <= 4);
		for (int i = 0; i < back.count; i++)
		{
			float ago = back.ago[i];
			assertTrue(ago >= 0.05f && ago < 0.6f);
			if (i > 0)
			{
				assertTrue(ago > back.ago[i - 1]);
			}
			// 10 units per 0.02 s: x tracks its time
			assertEquals(1600f - ago * 500f, back.x[i], 11f);
		}
	}

	@Test
	public void anotherWorldOrPlaneOrATeleportEndsTheChain()
	{
		GhostTrail trail = new GhostTrail();
		trail.record(at(0f, 0f, 0f, 0f, SkaterState.ROLLING), 0f);
		trail.record(at(5000f, 0f, 0f, 0f, SkaterState.ROLLING), 0.2f);
		trail.record(at(5050f, 0f, 0f, 0f, SkaterState.ROLLING), 0.4f);
		SkateGhostUpdate m = GhostCodec.encode(at(5100f, 0f, 0f, 0f, SkaterState.ROLLING), 0, null);
		GhostTrajectory back = GhostTrajectory.decode(trail.encode(m, 0.6f, 4, false), 0, m.x, m.y, m.h, m.hd);
		assertEquals(2, back.count);
		m.p = 2;
		back = GhostTrajectory.decode(trail.encode(m, 0.6f, 4, false), 0, m.x, m.y, m.h, m.hd);
		assertEquals(0, back.count);
	}

	@Test
	public void eventTimesAreHowLongBeforeTheSend()
	{
		GhostTrail trail = new GhostTrail();
		trail.noteEvents(GhostCodec.EV_POP, 3.0f);
		trail.noteEvents(GhostCodec.EV_LAND | GhostCodec.EV_TRICK, 3.4f);
		SkateGhostUpdate m = GhostCodec.encode(at(0f, 0f, 0f, 0f, SkaterState.ROLLING),
			GhostCodec.EV_POP | GhostCodec.EV_LAND | GhostCodec.EV_TRICK, null);
		GhostTrajectory back = GhostTrajectory.decode(trail.encode(m, 3.5f, 4, true), m.ev, m.x, m.y, m.h, m.hd);
		assertEquals(0.5f, back.eventAgo[0], 0.006f);
		assertEquals(0.1f, back.eventAgo[1], 0.006f);
		assertEquals(0.1f, back.eventAgo[6], 0.006f);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
