	/** A trail of a skater at full speed (2600 u/s), turning fast and falling, sampled for {@code seconds}. */
	private static GhostTrail fastTrail(float seconds)
	{
		GhostTrail trail = new GhostTrail();
		for (float t = 0f; t <= seconds; t += 0.02f)
		{
			trail.record(GhostFeed.frame(330, 2, 1_409_664f - 2600f * (seconds - t), 1_411_200f - 2600f * (seconds - t),
				-1237f + 900f * (seconds - t), -3.14159f + 10f * (seconds - t), 0f, 0f, 0f, SkaterState.AIRBORNE,
				null, null, 0f), t);
		}
		trail.noteEvents(0xfff, seconds - 0.9f);
		return trail;
	}

	@Test
	public void theTimelineOnlyGoesInTheRoomLeftUnderTheBound()
	{
		// the busiest updates of theBiggestUpdatesWithDesignsStayWithinTheBound, now with every event bit (pushes
		// included) set long before, and the fastest skater's positions to send
		GhostState busy = GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, -1237f, -3.14159f, -2600f, -2600f, -1820f,
			SkaterState.AIRBORNE, Trick.BOARDSLIDE, Trick.NOLLIE_INWARD_HEELFLIP, 0.5f, -TurnRateMeter.MAX_RATE,
			-4 * (float) Math.PI, -11.424f);
		SkateGhostUpdate m = GhostCodec.encode(busy, 0xfff, null);
		m.seq = 1_234_567_890;
		m.dk = longest(DesignPart.DECK);
		fastTrail(1f).fit(m, 1f);
		String json = GSON.toJson(m, WebsocketMessage.class);
		assertEquals(json.length(), GhostWire.jsonLength(m));
		System.out.println("busiest flip: " + json.length() + " chars, timeline " + m.tj);
		assertTrue(json.length() + " " + json, json.length() <= GhostWire.MAX_UPDATE_CHARS);

		GhostState grind = GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, -1237f, -3.14159f, -2600f, -2600f, -1820f,
			SkaterState.GRINDING, Trick.BOARDSLIDE, null, 0f, -TurnRateMeter.MAX_RATE, -4 * (float) Math.PI,
			-11.424f);
		SkateGhostUpdate g = GhostCodec.encode(grind, 0xfff, null);
		g.seq = 1_234_567_890;
		g.dk = longest(DesignPart.DECK);
		g.gw = longest(DesignPart.GRIP) + "." + longest(DesignPart.WHEELS);
		fastTrail(1f).fit(g, 1f);
		String gj = GSON.toJson(g, WebsocketMessage.class);
		assertTrue(gj.length() + " " + gj, gj.length() <= GhostWire.MAX_UPDATE_CHARS);
		System.out.println("busiest grind with designs: " + gj.length() + " chars, timeline " + g.tj);
	}

	@Test
	public void aTypicalUpdateCarriesItsFourPositionsAndAPopItsTime()
	{
		// rolling at speed, a custom deck, seq of today's size
		GhostState rolling = GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, -237f, 1.234f, 1200f, -900f, 0f,
			SkaterState.ROLLING, null, null, 0f, 1.2f);
		SkateGhostUpdate m = GhostCodec.encode(rolling, GhostCodec.EV_PUSH, null);
		m.seq = 412_345_678;
		m.dk = "C:0a1b2c3d";
		GhostTrail trail = fastTrail(1f);
		trail.sent(0.2f);
		trail.fit(m, 1f);
		GhostTrajectory back = GhostTrajectory.decode(m.tj, m.ev, m.x, m.y, m.h, m.hd);
		assertEquals(GhostTrail.MAX_SAMPLES, back.count);
		assertEquals(0.9f, back.eventAgo[11], 0.006f);
		int withTimeline = GSON.toJson(m, WebsocketMessage.class).length();
		m.tj = null;
		int without = GSON.toJson(m, WebsocketMessage.class).length();
		System.out.println("typical update: " + without + " chars, " + withTimeline + " with its timeline");
		assertTrue(withTimeline <= GhostWire.MAX_UPDATE_CHARS);

		// a kickflip's pop, sent at once
		GhostState pop = GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, -237f, 1.234f, 1200f, -900f, 820f,
			SkaterState.AIRBORNE, null, Trick.KICKFLIP, 0.04f, 1.2f);
		SkateGhostUpdate p = GhostCodec.encode(pop, GhostCodec.EV_POP | GhostCodec.EV_TRICK, Trick.KICKFLIP);
		p.seq = 412_345_679;
		p.dk = "C:0a1b2c3d";
		fastTrail(1f).fit(p, 1f);
		GhostTrajectory pb = GhostTrajectory.decode(p.tj, p.ev, p.x, p.y, p.h, p.hd);
		assertTrue(pb.count >= 2);
		assertEquals(0.9f, pb.eventAgo[0], 0.006f);
		System.out.println("kickflip pop: " + GSON.toJson(p, WebsocketMessage.class).length() + " chars with "
			+ pb.count + " positions");
	}

	@Test
	public void olderVersionsReadAnUpdateWithATimelineAsBefore()
	{
		GhostState f = GhostFeed.frame(330, 2, 1_409_664f, 1_411_200f, 0f, 1f, 600f, 0f, 0f, SkaterState.ROLLING, null,
			null, 0f);
		SkateGhostUpdate m = GhostCodec.encode(f, GhostCodec.EV_PUSH, null);
		m.seq = 5;
		fastTrail(1f).fit(m, 1f);
		String json = GSON.toJson(m, WebsocketMessage.class);
		assertTrue(json, json.contains("\"tj\":\""));
		// an older version has no tj field: Gson skips it, and the push bit means nothing to it
		String older = json.replaceAll(",?\"tj\":\"[^\"]*\"", "");
		GhostState a = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(json, WebsocketMessage.class));
		GhostState b = GhostCodec.decode((SkateGhostUpdate) GSON.fromJson(older, WebsocketMessage.class));
		assertEquals(a.x, b.x, 0f);
		assertEquals(a.heading, b.heading, 0f);
		assertEquals(a.events, b.events);
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.BoardState;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.util.Random;
import net.runelite.client.party.messages.WebsocketMessage;
import net.runelite.client.util.RuntimeTypeAdapterFactory;
import org.junit.Test;

public class GhostWireTest
{
	private static final Gson GSON = new GsonBuilder()
		.registerTypeAdapterFactory(RuntimeTypeAdapterFactory.of(WebsocketMessage.class)
			.registerSubtype(SkateGhostUpdate.class))
		.create();

	@Test
	public void varintsRoundTripAndSmallOnesTakeOneCharacter()
	{
		StringBuilder sb = new StringBuilder();
		int[] values = {0, 1, -1, 15, -16, 16, 511, -512, 512, 100_000, -100_000, Integer.MAX_VALUE / 4};
		for (int v : values)
		{
			GhostWire.putSigned(sb, v);
		}
		GhostWire.putUnsigned(sb, 31);
		GhostWire.putUnsigned(sb, 32);
		GhostWire.putFixed(sb, 262_143, 3);
		GhostWire.Reader r = new GhostWire.Reader(sb.toString());
		for (int v : values)
		{
			assertEquals(v, r.signed());
		}
		assertEquals(31, r.unsigned());
		assertEquals(32, r.unsigned());
		assertEquals(262_143, r.fixed(3));
		assertTrue(r.ok());
		// nothing is left: reading on fails
		r.fixed(1);
		assertFalse(r.ok());

		StringBuilder one = new StringBuilder();
		GhostWire.putSigned(one, -16);
		GhostWire.putSigned(one, 15);
		GhostWire.putUnsigned(one, 31);
		assertEquals(3, one.length());
	}

	@Test
	public void junkNeverThrows()
	{
		for (String junk : new String[]{"", "!", "\"", "______________", "ZZZZ", "é"})
		{
			GhostWire.Reader r = new GhostWire.Reader(junk);
			r.signed();
			r.unsigned();
			r.fixed(3);
			assertFalse(junk, r.ok());
		}
	}

	@Test
	public void theAlphabetIsNeverEscapedByGson()
	{
		String json = GSON.toJson(GhostWire.ALPHABET);
		assertEquals(GhostWire.ALPHABET.length() + 2, json.length());
	}

	@Test
	public void jsonLengthMatchesGsonExactly()
	{
		Random rnd = new Random(7);
		Trick[] tricks = Trick.values();
		SkaterState[] states = SkaterState.values();
		for (int i = 0; i < 2000; i++)
		{
			SkateGhostUpdate m = new SkateGhostUpdate();
			m.w = rnd.nextInt(600);
			m.p = rnd.nextInt(4);
			m.x = rnd.nextInt() / (1 + rnd.nextInt(1000));
			m.y = rnd.nextInt() / (1 + rnd.nextInt(1000));
			m.h = rnd.nextInt(4000) - 2000;
			m.hd = rnd.nextInt(6284) - 3142;
			m.tw = rnd.nextInt(20001) - 10000;
			m.vx = rnd.nextInt(5201) - 2600;
			m.vy = rnd.nextInt(5201) - 2600;
			m.vh = rnd.nextInt(5201) - 2600;
			m.st = rnd.nextBoolean() ? states[rnd.nextInt(states.length)].name() : null;
			m.hold = rnd.nextBoolean() ? tricks[rnd.nextInt(tricks.length)].name() : null;
			m.bf = rnd.nextInt(30000) - 15000;
			m.bw = rnd.nextInt(30000) - 15000;
			m.ev = rnd.nextInt(4096);
			m.tr = rnd.nextBoolean() ? tricks[rnd.nextInt(tricks.length)].name() : null;
			m.ft = rnd.nextInt(2000);
			m.seq = rnd.nextInt(Integer.MAX_VALUE);
			m.dk = rnd.nextBoolean() ? "C:0a1b2c3d" : null;
			m.gw = rnd.nextBoolean() ? "GRIP_X.WHEELS_Y" : null;
			m.ob = rnd.nextBoolean() ? BoardState.DROPPED.name() : null;
			m.bx = rnd.nextBoolean() ? rnd.nextInt() : null;
			m.by = rnd.nextBoolean() ? -rnd.nextInt(1000) : null;
			m.bh = rnd.nextBoolean() ? 0 : null;
			m.bd = rnd.nextBoolean() ? rnd.nextInt(6000) : null;
			m.cr = rnd.nextBoolean() ? rnd.nextInt(10) : null;
			m.kd = rnd.nextBoolean() ? rnd.nextInt(99) : null;
			m.tj = rnd.nextBoolean() ? GhostWire.ALPHABET.substring(rnd.nextInt(64)) : null;
			String json = GSON.toJson(m, WebsocketMessage.class);
			assertEquals(json, json.length(), GhostWire.jsonLength(m));
		}
	}

	@Test
	public void htmlCharactersCountAsGsonEscapesThem()
	{
		SkateGhostUpdate m = new SkateGhostUpdate();
		m.dk = "<a&b='c'>\"\\";
		assertEquals(GSON.toJson(m, WebsocketMessage.class).length(), GhostWire.jsonLength(m));
	}
}

package com.gielinorskate.party;

import static org.junit.Assert.assertEquals;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

public class TurnRateMeterTest
{
	@Test
	public void steadyCarveIsMeasuredEvenWithUnevenPhysicsSteps()
	{
		TurnRateMeter m = new TurnRateMeter();
		float heading = 0f;
		float rate = 0f;
		// 1.5 rad/s; render frames run 0, 1, 2 or 3 physics steps of 0.02 s and pass the physics time
		for (int i = 0; i < 100; i++)
		{
			int steps = i % 4;
			heading = Angles.wrap(heading + 1.5f * 0.02f * steps);
			rate = m.update(heading, null, 0f, 0.02f * steps);
		}
		assertEquals(1.5f, rate, 0.05f);
	}

	@Test
	public void wrapsAroundThroughPi()
	{
		TurnRateMeter m = new TurnRateMeter();
		float heading = Angles.PI - 0.2f;
		float rate = 0f;
		for (int i = 0; i < 30; i++)
		{
			heading = Angles.wrap(heading - 2f / 60f);
			rate = m.update(heading, null, 0f, 1f / 60f);
		}
		assertEquals(-2f, rate, 0.01f);
	}

	@Test
	public void aHeadingSnapIsNotATurn()
	{
		TurnRateMeter m = new TurnRateMeter();
		float rate = 0f;
		for (int i = 0; i < 30; i++)
		{
			rate = m.update(i == 15 ? 2f : 0f + (i > 15 ? 2f : 0f), null, 0f, 1f / 60f);
		}
		assertEquals(0f, rate, 1e-4f);
	}

	@Test
	public void aBigspinsOwnBodyTurnIsLeftOut()
	{
		// the receiver animates the bigspin's body 180 from the trick table: the rate is only the steering
		TurnRateMeter m = new TurnRateMeter();
		float rate = 0f;
		for (int i = 0; i <= 27; i++)
		{
			float progress = Math.min(1f, i / 60f / Trick.BIGSPIN.duration);
			float heading = Angles.wrap(GhostCodec.bodySpin(Trick.BIGSPIN, progress) + 0.5f * i / 60f);
			rate = m.update(heading, Trick.BIGSPIN, progress, 1f / 60f);
		}
		assertEquals(0.5f, rate, 0.02f);
		// the flip clears: its body turn is kept in the heading, not unwound
		rate = m.update(Angles.wrap(Angles.PI + 0.5f * 28 / 60f), null, 0f, 1f / 60f);
		for (int i = 29; i < 40; i++)
		{
			rate = m.update(Angles.wrap(Angles.PI + 0.5f * i / 60f), null, 0f, 1f / 60f);
		}
		assertEquals(0.5f, rate, 0.02f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class AnglesTest
{
	private static final float PI = (float) Math.PI;

	@Test
	public void wrapKeepsAnglesInRange()
	{
		assertEquals(0f, Angles.wrap(2 * PI), 1e-5f);
		assertEquals(-PI / 2, Angles.wrap(3 * PI / 2), 1e-5f);
		assertEquals(PI / 2, Angles.wrap(-3 * PI / 2), 1e-5f);
	}

	@Test
	public void absDiffIsShortestArc()
	{
		assertEquals(0.2f, Angles.absDiff(PI - 0.1f, -PI + 0.1f), 1e-5f);
		assertEquals(PI, Angles.absDiff(0f, PI), 1e-5f);
	}

	@Test
	public void jauConversionMatchesOsrsCompass()
	{
		// OSRS orientation: 0 = south, 512 = west, 1024 = north, 1536 = east
		assertEquals(1024, Angles.toJau(0f));
		assertEquals(1536, Angles.toJau(PI / 2));
		assertEquals(0, Angles.toJau(PI));
		assertEquals(512, Angles.toJau(-PI / 2));
		assertEquals(PI / 2, Angles.fromJau(1536), 1e-3f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class BailReasonTest
{
	@Test
	public void landingReasonsInTheOrderPhysicsChecksThem()
	{
		assertNull(BailReason.forLanding(false, false, false));
		assertEquals(BailReason.SIDEWAYS, BailReason.forLanding(true, true, true));
		assertEquals(BailReason.FLIP_NOT_CAUGHT, BailReason.forLanding(false, true, true));
		assertEquals(BailReason.BODY_FLIP, BailReason.forLanding(false, false, true));
	}

	@Test
	public void wordingForTheHud()
	{
		assertEquals("Landed sideways - finish the spin", BailReason.SIDEWAYS.text);
		assertEquals("Board still flipping - jump higher", BailReason.FLIP_NOT_CAUGHT.text);
		assertEquals("Hit a wall", BailReason.WALL.text);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Random;
import org.junit.Test;

/** The board flying off after a bail: spins, bounces off walls and the ground, rests flat; always finite. */
public class BoardBounceTest
{
	private static final float DT = 0.02f;
	private static final float G = new SkateTuning().gravity;

	private static BoardBounce thrown(CollisionWorld w, float speed, long seed)
	{
		BoardBounce b = new BoardBounce(w, G);
		b.start(0, 0, w.groundHeight(0, 0), 0f, speed, 0f, new Random(seed));
		return b;
	}

	private static float runToRest(BoardBounce b, float seconds)
	{
		float t = 0f;
		while (t < seconds && !b.isAtRest())
		{
			b.step(DT);
			assertFinite(b);
			t += DT;
		}
		return t;
	}

	private static void assertFinite(BoardBounce b)
	{
		float[] v = {b.getX(), b.getY(), b.getH(), b.getYaw(), b.getRoll(), b.getPitch()};
		for (float f : v)
		{
			assertFalse("not finite: " + f, Float.isNaN(f) || Float.isInfinite(f));
		}
	}

	@Test
	public void itFliesOffSpinningAndComesToRestFlat()
	{
		for (long seed = 0; seed < 20; seed++)
		{
			for (float speed : new float[]{0f, 400f, 1500f, 2600f})
			{
				BoardBounce b = thrown(TestWorlds.flat(), speed, seed);
				assertTrue(b.getVerticalSpeed() > 0f);
				float t = runToRest(b, 5f);
				assertTrue("rests (seed " + seed + ", " + speed + ")", b.isAtRest());
				assertTrue("rests in time: " + t, t < BoardBounce.REST_TIMEOUT + 1e-3f);
				// wheels down, flat on the ground
				assertEquals(0f, b.getRoll(), 0f);
				assertEquals(0f, b.getPitch(), 0f);
				assertEquals(0f, b.getH(), 0f);
			}
		}
	}

	@Test
	public void itGoesTheWayTheSkaterWas()
	{
		BoardBounce b = thrown(TestWorlds.flat(), 1500f, 3);
		runToRest(b, 5f);
		assertTrue(b.getY() > 200f);
	}

	@Test
	public void itSpinsAndFlipsInTheAir()
	{
		BoardBounce b = thrown(TestWorlds.flat(), 1500f, 7);
		float yaw0 = b.getYaw();
		for (int i = 0; i < 5; i++)
		{
			b.step(DT);
		}
		assertTrue(Math.abs(b.getYaw() - yaw0) > 0.1f);
		assertTrue(Math.abs(b.getRoll()) > 0.1f);
	}

	@Test
	public void neverPassesThroughAWall()
	{
		CollisionWorld w = TestWorlds.wallAtY(150f, 300f);
		for (long seed = 0; seed < 10; seed++)
		{
			BoardBounce b = thrown(w, 2600f, seed);
			for (int i = 0; i < 300; i++)
			{
				b.step(DT);
				assertTrue("through the wall: y " + b.getY(), b.getY() < 150f);
			}
			assertTrue(b.isAtRest());
		}
	}

	@Test
	public void staysInsideTheLoadedArea()
	{
		BoardBounce b = thrown(TestWorlds.edgeAtY(100f), 2600f, 1);
		runToRest(b, 5f);
		assertTrue(b.getY() < 100f);
	}

	@Test
	public void restNowPutsItFlatOnTheGroundWhereItIs()
	{
		BoardBounce b = thrown(TestWorlds.flat(), 1500f, 2);
		b.step(DT);
		b.step(DT);
		b.restNow();
		assertTrue(b.isAtRest());
		assertEquals(0f, b.getH(), 0f);
		assertEquals(0f, b.getRoll(), 0f);
		float y = b.getY();
		b.step(DT);
		assertEquals(y, b.getY(), 0f);
	}

	@Test
	public void aNonFiniteStartStaysFinite()
	{
		BoardBounce b = new BoardBounce(TestWorlds.flat(), G);
		b.start(Float.NaN, 0, 0, Float.POSITIVE_INFINITY, 0f, Float.NaN, new Random(0));
		runToRest(b, 5f);
		assertTrue(b.isAtRest());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import org.junit.Test;

public class BodyFlipTest
{
	static final float TWO_PI = (float) (2 * Math.PI);

	private static float deg(double d)
	{
		return (float) Math.toRadians(d);
	}

	@Test
	public void landingNeedsTheBodyWithin40DegreesOfAWholeRotation()
	{
		assertTrue(BodyFlip.landable(0f));
		assertTrue(BodyFlip.landable(TWO_PI + deg(40)));
		assertFalse(BodyFlip.landable(TWO_PI + deg(41)));
		assertTrue(BodyFlip.landable(TWO_PI - deg(40)));
		assertFalse(BodyFlip.landable(TWO_PI - deg(41)));
		assertTrue(BodyFlip.landable(-TWO_PI - deg(40)));
		assertFalse(BodyFlip.landable(-TWO_PI + deg(41)));
		assertTrue(BodyFlip.landable(deg(40)));
		assertFalse(BodyFlip.landable(deg(41)));
		assertFalse(BodyFlip.landable(deg(180)));
	}

	@Test
	public void rotationsRoundToTheNearestWholeTurn()
	{
		assertEquals(0, BodyFlip.rotations(deg(30)));
		assertEquals(1, BodyFlip.rotations(deg(330)));
		assertEquals(1, BodyFlip.rotations(deg(390)));
		assertEquals(2, BodyFlip.rotations(deg(700)));
		assertEquals(-1, BodyFlip.rotations(deg(-350)));
	}

	@Test
	public void residualIsTheSignedDistanceFromTheNearestWholeTurn()
	{
		assertEquals(deg(20), BodyFlip.residual(TWO_PI + deg(20)), 1e-5f);
		assertEquals(deg(-20), BodyFlip.residual(TWO_PI - deg(20)), 1e-5f);
	}

	@Test
	public void forwardIsAFrontflipBackwardABackflip()
	{
		assertNull(BodyFlip.trick(0));
		assertEquals(Trick.FRONTFLIP, BodyFlip.trick(1));
		assertEquals(Trick.BACKFLIP, BodyFlip.trick(-1));
		assertEquals(Trick.DOUBLE_FRONTFLIP, BodyFlip.trick(2));
		assertEquals(Trick.DOUBLE_BACKFLIP, BodyFlip.trick(-2));
		assertEquals(Trick.DOUBLE_FRONTFLIP, BodyFlip.trick(3));
	}

	@Test
	public void bodyFlipTricksScoreAsSpecified()
	{
		assertEquals(1000, Trick.FRONTFLIP.points);
		assertEquals(1000, Trick.BACKFLIP.points);
		assertEquals(2200, Trick.DOUBLE_FRONTFLIP.points);
		assertEquals(2200, Trick.DOUBLE_BACKFLIP.points);
		assertEquals("Frontflip", Trick.FRONTFLIP.displayName);
		assertEquals("Double Backflip", Trick.DOUBLE_BACKFLIP.displayName);
		assertEquals(TrickKind.FLIP, Trick.FRONTFLIP.kind);
		assertEquals(1f, Trick.FRONTFLIP.bodyFlipTurns, 0f);
		assertEquals(-2f, Trick.DOUBLE_BACKFLIP.bodyFlipTurns, 0f);
		assertEquals(0f, Trick.KICKFLIP.bodyFlipTurns, 0f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.camera.CameraRig;
import com.gielinorskate.render.RenderPose;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.world.BlockerSet;
import com.gielinorskate.world.GridCollisionWorld;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * The chase camera stays steady when the skater runs into objects: physics, the session's render
 * interpolation and the camera rig together, at 144 frames a second, against a rotated box, the inside corner
 * of two boxes, a fence and a box at the corner of a wall, with W held, idle, W tapped, and hops (ollies)
 * into them. Without steering the camera must never jump (no camera heading step over 20 degrees), never
 * turn faster than {@link #MAX_RATE_DEG} and never swing back and forth.
 */
public class CameraSteadinessTest
{
	private static final float T = GridCollisionWorld.TILE;
	private static final float STEP = 0.02f;
	private static final float FRAME = 1f / 144f;
	/** The rig's yaw rate cap (CameraRig.MAX_YAW_RATE, 2 PI rad/s), plus rounding. */
	private static final float MAX_RATE_DEG = 361f;
	/** A swing counts once the yaw moved this far one way; a back-and-forth is two such swings in turn. */
	private static final float SWING_DEG = 5f;

	private static final int HOLD_W = 0;
	private static final int IDLE = 1;
	private static final int TAP_W = 2;
	private static final int HOLD_W_HOPS = 3;
	private static final int HOPS = 4;
	private static final int STEER_SLOW = 5;
	private static final int SHIFT_TURN = 6;

	static GridCollisionWorld rotatedBox()
	{
		GridCollisionWorld w = new GridCollisionWorld(40);
		float a = (float) Math.toRadians(37);
		w.addBlocker(20 * T, 20 * T, 30, 20, (float) Math.cos(a), (float) Math.sin(a), 300, BlockerSet.SOLID, 0);
		return w;
	}

	static GridCollisionWorld boxCorner()
	{
		GridCollisionWorld w = new GridCollisionWorld(40);
		w.addBlocker(20 * T, 20 * T + 60, 80, 20, 1f, 0f, 300, BlockerSet.SOLID, 0);
		w.addBlocker(20 * T + 60, 20 * T, 20, 80, 1f, 0f, 300, BlockerSet.SOLID, 0);
		return w;
	}

	static GridCollisionWorld fence()
	{
		GridCollisionWorld w = new GridCollisionWorld(40);
		for (int tx = 5; tx <= 35; tx++)
		{
			w.setTile(tx, 20, GridCollisionWorld.WALL_N, 300);
			w.setTile(tx, 21, GridCollisionWorld.WALL_S, 300);
		}
		return w;
	}

	static GridCollisionWorld boxAtWallCorner()
	{
		GridCollisionWorld w = new GridCollisionWorld(40);
		for (int tx = 10; tx <= 20; tx++)
		{
			w.setTile(tx, 20, GridCollisionWorld.WALL_N, 300);
		}
		for (int ty = 10; ty <= 20; ty++)
		{
			w.setTile(20, ty, GridCollisionWorld.WALL_E | (ty == 20 ? GridCollisionWorld.WALL_N : 0), 300);
		}
		w.addBlocker(21 * T - 25, 21 * T - 25, 20, 20, 1f, 0f, 300, BlockerSet.SOLID, 0);
		return w;
	}

	/** Measurements of one run, up to its first bail (a bail and its recovery are not "steady riding"). */
	static final class Run
	{
		int cameraJumps;
		float maxRateDeg;
		int backAndForth;
		/** The board's own back-and-forth turns (pinballing in a corner): the camera may follow those. */
		int boardBackAndForth;
		String worst = "";
	}

	static Run ride(GridCollisionWorld w, float x, float y, float headingDeg, float speed, int input)
	{
		SkatePhysics p = new SkatePhysics(new SkateTuning(), w, x, y, (float) Math.toRadians(headingDeg));
		p.setRollingSpeed(speed);
		CameraRig rig = new CameraRig();
		rig.reset(x, y, 0, p.getCameraHeading());
		SkateInput in = new SkateInput();
		Run run = new Run();
		float acc = 0f;
		RenderPose prev = RenderPose.of(p);
		float lastYaw = rig.getYaw();
		Swings cameraSwings = new Swings(lastYaw);
		Swings boardSwings = new Swings(p.getHeading());
		boolean hopQueued = false;
		for (int f = 0; f < Math.round(4f / FRAME); f++)
		{
			in.pushHeld = input == HOLD_W || input == HOLD_W_HOPS;
			in.pushPressed = input == TAP_W && f % 72 == 0;
			in.steer = input == STEER_SLOW ? 0.3f : input == SHIFT_TURN ? 1f : 0f;
			in.powerslide = input == SHIFT_TURN;
			if ((input == HOLD_W_HOPS || input == HOPS) && f % 72 == 36)
			{
				hopQueued = true;
			}
			acc += FRAME;
			while (acc >= STEP)
			{
				if (hopQueued)
				{
					in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
					hopQueued = false;
				}
				prev = RenderPose.of(p);
				float camBefore = p.getCameraHeading();
				p.step(STEP, in);
				acc -= STEP;
				if (p.getState() == SkaterState.BAILED)
				{
					return run;
				}
				float jump = (float) Math.toDegrees(Angles.absDiff(p.getCameraHeading(), camBefore));
				if (jump > 20f && in.steer == 0f)
				{
					run.cameraJumps++;
					run.worst = String.format("camera heading jumped %.0f deg at t=%.2f (%s)", jump, f * FRAME,
						p.getState());
				}
			}
			RenderPose pose = RenderPose.lerp(prev, RenderPose.of(p), acc / STEP);
			rig.update(pose.x, pose.y, pose.h, pose.cameraHeading, p.getSpeed(), p.getState(), 0f, FRAME);
			float yaw = rig.getYaw();
			run.maxRateDeg = Math.max(run.maxRateDeg, (float) Math.toDegrees(Angles.absDiff(yaw, lastYaw) / FRAME));
			lastYaw = yaw;
			run.backAndForth = cameraSwings.feed(yaw);
			run.boardBackAndForth = boardSwings.feed(p.getHeading());
		}
		return run;
	}

	/** Counts reversals of an angle that swings at least SWING_DEG each way (smaller dither is ignored). */
	static final class Swings
	{
		private float extreme;
		private int dir;
		private int count;

		Swings(float start)
		{
			extreme = start;
		}

		int feed(float angle)
		{
			float fromExtreme = (float) Math.toDegrees(Angles.wrap(angle - extreme));
			if (dir == 0)
			{
				if (Math.abs(fromExtreme) >= SWING_DEG)
				{
					dir = fromExtreme > 0 ? 1 : -1;
					extreme = angle;
				}
			}
			else if (fromExtreme * dir > 0)
			{
				extreme = angle;
			}
			else if (-fromExtreme * dir >= SWING_DEG)
			{
				count++;
				dir = -dir;
				extreme = angle;
			}
			return count;
		}
	}

	private interface Scene
	{
		GridCollisionWorld make();
	}

	private static List<String> failures(int[] inputs, boolean steadyOnly)
	{
		Scene[] scenes = {CameraSteadinessTest::rotatedBox, CameraSteadinessTest::boxCorner,
			CameraSteadinessTest::fence, CameraSteadinessTest::boxAtWallCorner};
		String[] names = {"rotated box", "box corner", "fence", "box at wall corner"};
		List<String> bad = new ArrayList<>();
		for (int s = 0; s < scenes.length; s++)
		{
			// the fence runs east-west north of the skater; the others are approached toward their corner
			float base = s == 1 || s == 3 ? 45f : 0f;
			for (float ang = -30; ang <= 30; ang += 5)
			{
				for (float speed : new float[]{0f, 150f, 400f, 700f})
				{
					for (int input : inputs)
					{
						float h = (float) Math.toRadians(base + ang);
						float x = s == 2 ? 20 * T : 20 * T - (float) Math.sin(h) * 140;
						float y = s == 2 ? 21 * T - 140 : 20 * T - (float) Math.cos(h) * 140;
						Run r = ride(scenes[s].make(), x, y, base + ang, speed, input);
						String at = String.format("%s ang %.0f speed %.0f input %d: ", names[s], ang, speed, input);
						if (r.cameraJumps > 0)
						{
							bad.add(at + r.worst);
						}
						if (r.maxRateDeg > MAX_RATE_DEG)
						{
							bad.add(at + "yaw rate " + r.maxRateDeg + " deg/s");
						}
						if (steadyOnly && r.backAndForth > r.boardBackAndForth)
						{
							bad.add(at + r.backAndForth + " back-and-forth swings, the board made " + r.boardBackAndForth);
						}
					}
				}
			}
		}
		return bad;
	}

	@Test
	public void withoutSteeringTheCameraNeverJumpsRacesOrSwingsBackAndForth()
	{
		List<String> bad = failures(new int[]{HOLD_W, IDLE, TAP_W, HOLD_W_HOPS, HOPS}, true);
		assertTrue(bad.size() + " runs:\n" + String.join("\n", bad.subList(0, Math.min(20, bad.size()))),
			bad.isEmpty());
	}

	@Test
	public void steeringIntoObjectsNeverJumpsTheCamera()
	{
		List<String> bad = failures(new int[]{STEER_SLOW, SHIFT_TURN}, false);
		assertTrue(bad.size() + " runs:\n" + String.join("\n", bad.subList(0, Math.min(20, bad.size()))),
			bad.isEmpty());
	}

	@Test
	public void aHopIntoAFenceNearlyHeadOnKeepsTheCameraBehindTheBoard()
	{
		// the evidence case: 2 degrees off head-on, the wall leaves only a sliver of the flight along it, and
		// the camera used to follow that sliver: 90 degrees to one side in the air, then back on landing
		for (float ang : new float[]{2f, -2f})
		{
			SkatePhysics p = new SkatePhysics(new SkateTuning(), fence(), 20 * T + 10, 21 * T - 60,
				(float) Math.toRadians(ang));
			p.setRollingSpeed(600f);
			SkateInput in = new SkateInput();
			in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
			for (int i = 0; i < 40; i++)
			{
				p.step(STEP, in);
				assertEquals("step " + i + " " + p.getState(), Math.toRadians(ang), p.getCameraHeading(), 0.02f);
			}
		}
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.world.GridCollisionWorld;
import com.gielinorskate.world.WorldTests;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** On-foot walking, sprinting, turning, stepping, jumping and collision. */
public class FootPhysicsTest
{
	static final float DT = 0.02f;
	static final float G = new SkateTuning().gravity;
	static final float R = new SkateTuning().skaterRadius;

	private static FootPhysics at(CollisionWorld w, float x, float y, float heading)
	{
		return new FootPhysics(w, G, R, x, y, w.groundHeight(x, y), heading);
	}

	private static FootInput move(float mx, float my, boolean sprint)
	{
		FootInput in = new FootInput();
		in.moveX = mx;
		in.moveY = my;
		in.sprint = sprint;
		return in;
	}

	/** Steps for {@code seconds}, collecting every event. */
	private static List<FootEvent> run(FootPhysics p, FootInput in, float seconds)
	{
		List<FootEvent> all = new ArrayList<>();
		int n = Math.round(seconds / DT);
		for (int i = 0; i < n; i++)
		{
			p.step(DT, in);
			all.addAll(p.drainEvents());
		}
		return all;
	}

	@Test
	public void walkReachesWalkSpeedWithinATenthOfASecond()
	{
		FootPhysics p = at(TestWorlds.flat(), 0, 0, 0);
		run(p, move(0, 1, false), 0.1f);
		assertEquals(FootPhysics.WALK_SPEED, p.getSpeed(), 0.01f);
		float y0 = p.getY();
		run(p, move(0, 1, false), 1f);
		assertEquals(FootPhysics.WALK_SPEED, p.getY() - y0, 1f);
	}

	@Test
	public void walkIsOneAndAHalfTimesTheGamesWalk()
	{
		// the game's walk is one tile (128) per 0.6 s tick; Skate 3 on foot is brisker
		assertEquals(128f / 0.6f, FootPhysics.GAME_WALK_SPEED, 0.01f);
		assertEquals(1.5f, FootPhysics.WALK_SPEED_SCALE, 0f);
		assertEquals(320f, FootPhysics.WALK_SPEED, 0.01f);
	}

	@Test
	public void sprintIsTwiceTheGamesRunAndReachedWithinATenthOfASecond()
	{
		FootPhysics p = at(TestWorlds.flat(), 0, 0, 0);
		run(p, move(0, 1, true), 0.1f);
		assertEquals(FootPhysics.SPRINT_SPEED, p.getSpeed(), 0.01f);
		// the game's run: two tiles per tick
		assertEquals(256f / 0.6f, FootPhysics.GAME_RUN_SPEED, 0.01f);
		assertEquals(2f, FootPhysics.SPRINT_SPEED_SCALE, 0f);
		assertEquals(512f / 0.6f, FootPhysics.SPRINT_SPEED, 0.01f);
		assertTrue(p.sprinting);
	}

	@Test
	public void sprintStaysWellUnderThePushTopSpeed()
	{
		// the board is still the fast way round
		assertTrue(FootPhysics.SPRINT_SPEED < 0.6f * new SkateTuning().maxPushSpeed);
	}

	@Test
	public void sprintWithoutMovingIsNotSprinting()
	{
		FootPhysics p = at(TestWorlds.flat(), 0, 0, 0);
		run(p, move(0, 0, true), 0.2f);
		assertFalse(p.sprinting);
		assertEquals(0f, p.getSpeed(), 0f);
	}

	@Test
	public void releasingTheKeysStopsWithinATenthOfASecond()
	{
		FootPhysics p = at(TestWorlds.flat(), 0, 0, 0);
		run(p, move(0, 1, true), 0.5f);
		run(p, move(0, 0, false), 0.1f);
		assertEquals(0f, p.getSpeed(), 0.01f);
	}

	@Test
	public void bodyTurnsTowardTheMoveDirectionAt720DegreesASecond()
	{
		FootPhysics p = at(TestWorlds.flat(), 0, 0, 0);
		p.step(DT, move(1, 0, false));
		assertEquals(720f * DT, (float) Math.toDegrees(p.getHeading()), 0.01f);
		// 90 degrees takes 0.125 s
		run(p, move(1, 0, false), 0.12f);
		assertEquals(90f, (float) Math.toDegrees(p.getHeading()), 0.01f);
	}

	@Test
	public void turnTowardTakesTheShortWayRound()
	{
		float h = Angles.turnToward((float) Math.toRadians(170), (float) Math.toRadians(-170), 0.1f);
		assertTrue(Math.toDegrees(h) > 170 || Math.toDegrees(h) < -170);
	}

	@Test
	public void cameraRelativeKeysFollowTheCameraYaw()
	{
		FootInput in = new FootInput();
		float yaw = (float) Math.toRadians(90); // camera looking east
		in.setCameraRelative(true, false, false, false, yaw);
		assertEquals(1f, in.moveX, 1e-5f);
		assertEquals(0f, in.moveY, 1e-5f);
		in.setCameraRelative(false, false, false, true, yaw);
		// right of east is south
		assertEquals(0f, in.moveX, 1e-5f);
		assertEquals(-1f, in.moveY, 1e-5f);
		in.setCameraRelative(true, false, false, true, 0f);
		// a diagonal is normalised: same speed in all eight directions
		assertEquals(1f, Math.hypot(in.moveX, in.moveY), 1e-5f);
		assertEquals(in.moveX, in.moveY, 1e-5f);
		in.setCameraRelative(true, true, true, true, 0f);
		assertEquals(0f, in.moveX, 0f);
		assertEquals(0f, in.moveY, 0f);
	}

	@Test
