			for (int y = 0; y <= size; y++)
			{
				WorldTests.setCornerHeight(w, x, y, 0f);
			}
		}
		return w;
	}

	/** A FULL tile (2, 2) of a 6x6 world holding one centred square object, as GridBlockersTest builds it. */
