		for (int i = 0; i < 100; i++)
		{
			p.step(DT, in);
			top = Math.max(top, p.getH());
		}
		return top;
	}

	@Test
	public void aJumpOntoTheBoardIsABiggerHopThanAPlainJump()
	{
