public class SkatePhysicsAirTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	/** Crouches for `crouchSeconds`, pops, then steps until landed or bailed. Returns peak height. */
	static float ollie(SkatePhysics p, float crouchSeconds, float steer, float steerSeconds)
	{
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < Math.round(crouchSeconds / DT); i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		float peak = p.getH();
		int steerSteps = Math.round(steerSeconds / DT);
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			in.steer = i < steerSteps ? steer : 0f;
			p.step(DT, in);
			peak = Math.max(peak, p.getH());
		}
		return peak;
	}

	@Test
	public void fullyChargedOllieReachesExpectedHeightAndLands()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		float peak = ollie(p, 0.4f, 0f, 0f);
		// v^2 / 2g = 820^2 / 4000 = 168.1 (ollieImpulse 700 -> 820; was 122.5)
		assertTrue("peak " + peak, peak > 155f && peak < 170f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getSpeed() > 400f);
		List<SkateEvent> ev = p.drainEvents();
		assertTrue(ev.contains(SkateEvent.POP));
		assertTrue(ev.contains(SkateEvent.LAND));
	}

	@Test
	public void uncrouchedOllieIsSmaller()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		float peak = ollie(p, 0f, 0f, 0f);
		// (0.92 * 820)^2 / 4000 = 754.4^2 / 4000 = 142.3 analytic; 20 ms steps reach 0.02 * (18 * 754.4 - 40 * 171)
		// = 134.8 (minPopFraction 0.85 -> 0.92; was 121.5)
		assertTrue("peak " + peak, peak > 130f && peak < 143f);
	}

	@Test
	public void ollieClearsLowWall()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(640, 80), 0, 0, 0);
		p.setRollingSpeed(600);
		SkateInput idle = new SkateInput();
		// pop lands around y=490 after the 0.4 s crouch, leaving ~150 units of climb before the wall
		while (p.getY() < 250)
		{
			p.step(DT, idle);
		}
		ollie(p, 0.4f, 0f, 0f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("y " + p.getY(), p.getY() > 640f);
	}

	@Test
	public void quarterSpinLandingBails()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		ollie(p, 0.4f, 1f, 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
		assertEquals(BailReason.SIDEWAYS, p.getLastBailReason());
	}

	@Test
	public void halfSpinLandsFakie()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		// 7 rad/s for 0.44 s = 3.08 rad (176.5 deg), within landingToleranceDeg (55, was 35) of 180
		ollie(p, 0.4f, 1f, 0.44f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getSpeed() < -400f);
		assertTrue(Angles.absDiff(p.getTravelHeading(), 0f) < 0.1f);
	}

	@Test
	public void fiftyDegreeOffAxisLandingNowLands()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		// Full charge -> vh = ollieImpulse = 820, continuous hang time T = 2*vh/gravity = 0.82 s.
		// Steer at 0.1520 (|steer| > 0.1, so spin assist never engages) for the whole flight:
		// rotation = steer * airSpinRate * T = 0.1520 * 7 * 0.82 = 0.8725 rad = 50 deg
		// (was 0.1781 for the old 0.7 s hang time).
		// 50 > old landingToleranceDeg (35) -> would have bailed; 50 <= new tolerance (55) -> lands,
		// and forward (50 < 90, so it lands nose-first rather than fakie).
		ollie(p, 0.4f, 0.1520f, 1.0f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getSpeed() > 0f);
	}

	@Test
	public void spinAssistClosesTheGapAndLandsFakie()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		// Uncharged pop -> charge = minPopFraction = 0.92, vh = 0.92 * 820 = 754.4, continuous hang time
		// T = 2*754.4/2000 = 0.754 s. Steer at full (1) for 0.3 s: rotation = 7*0.3 = 2.1 rad = 120.3 deg,
		// leaving 0.454 s of hang time (T - 0.3).
		// diff to travel+pi (180) = 180 - 120.3 = 59.7 deg, within the 70 deg spin-assist window
		// (diff to travel (0) is 120.3, further away, so 180 is the nearer target) and > tolerance
		// (55), so without spin assist this would bail. With |steer| < 0.1 for the remaining 0.454 s,
		// spin assist eases heading toward 180 at 6 rad/s: up to 6*0.454 = 2.72 rad, more than the
		// 59.7 deg (1.04 rad) gap, so it snaps fully to 180 -> lands fakie. (With the old 0.42 s hang
		// time this was only a partial ease, to 161.6 deg.)
		ollie(p, 0f, 1f, 0.3f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getSpeed() < 0f);
		assertTrue(Angles.absDiff(p.getTravelHeading(), 0f) < 0.4f);
	}

	@Test
	public void rollingOffALedgeGoesAirborneThenLands()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.stepAtY(300, 100, 0), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput idle = new SkateInput();
		boolean wasAirborne = false;
		for (int i = 0; i < 100; i++)
		{
			p.step(DT, idle);
			wasAirborne |= p.getState() == SkaterState.AIRBORNE;
		}
		assertTrue(wasAirborne);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(0f, p.getH(), 0.01f);
		assertTrue(p.drainEvents().contains(SkateEvent.ROLL_OFF));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.render.AnimationPicker;
import com.gielinorskate.tricks.Gesture;
import java.util.List;
import org.junit.Test;

/** How a bail moves the skater: what the renderer draws while the bail animation plays. */
public class SkatePhysicsBailTest
{
	private static final float DT = 0.02f;
	private final SkateTuning t = new SkateTuning();

	@Test
	public void aBailInTheAirFallsToTheGroundInsteadOfSnappingDown()
	{
		// an ollie at 1200 head-on into a 300-high wall bails in the air, well above the ground. It used to be put
		// straight on the ground in the next step (an 80-unit drop in 0.02 s): now it falls under gravity
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, 0f);
		p.setRollingSpeed(1200f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		for (int i = 0; i < 30 && p.getState() != SkaterState.BAILED; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.BAILED, p.getState());
		float h = p.getH();
		assertTrue("bailed in the air: h " + h, h > 40f);
		int steps = 0;
		float fallSpeed = 0f;
		while (p.getH() > 0f && steps < 100)
		{
			p.step(DT, in);
			float drop = h - p.getH();
			assertTrue("never rises: " + drop, drop >= 0f);
			// gravity 2000: after t seconds the fall speed is 2000 t, so a step drops by at most (2000 t + 40) * 0.02
			fallSpeed += t.gravity * DT;
			assertTrue("falls, not snaps: dropped " + drop + " in one step", drop <= fallSpeed * DT + 1e-3f);
			h = p.getH();
			steps++;
		}
		assertEquals(0f, p.getH(), 0f);
		assertEquals(SkaterState.BAILED, p.getState());
	}

	@Test
	public void theBailAnimationIsPickedOnceForTheWholeBail()
	{
		// the animator restarts an animation only when the picked action changes: a bail into a wall, W held
		// throughout, picks BAIL exactly once and keeps it until the reset
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, 0f);
		p.setRollingSpeed(1500f);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		AnimationPicker.Action current = AnimationPicker.Action.NONE;
		int bailPicks = 0;
		boolean reset = false;
		for (int i = 0; i < 150 && !reset; i++)
		{
			p.step(DT, in);
			List<SkateEvent> events = p.drainEvents();
			AnimationPicker.Action next =
				AnimationPicker.pick(p.getState(), events, current, 0f);
			if (next != current && next == AnimationPicker.Action.BAIL)
			{
				bailPicks++;
			}
			current = next;
			reset = events.contains(SkateEvent.RESET);
		}
		assertTrue("got back up", reset);
		assertEquals(1, bailPicks);
	}

	@Test
	public void aBailOnTheGroundStaysOnTheGround()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, 0f);
		p.setRollingSpeed(1500f);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 10 && p.getState() != SkaterState.BAILED; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.BAILED, p.getState());
		float x = p.getX();
		float y = p.getY();
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
			assertEquals(0f, p.getH(), 0f);
			// the bail does not shuffle about against the wall it hit
			assertEquals(x, p.getX(), 0f);
			assertEquals(y, p.getY(), 0f);
		}
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * Front and back flips: Shift + W (forward) or Shift + S (backward) held in the air turns the whole skater at
 * 2 pi / 0.55 rad/s. A fully charged pop hangs 2 * 820 / 2000 = 0.82 s, room for one flip.
 */
public class SkatePhysicsBodyFlipTest
{
	static final float DT = 0.02f;
	static final float TWO_PI = (float) (2 * Math.PI);
	static final float RATE = TWO_PI / 0.55f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	/** Crouches for 0.4 s (full charge) then ollies, in steps of `dt`. */
	private static void chargedOllie(SkatePhysics p, SkateInput in, float dt)
	{
		in.crouch = true;
		for (float s = 0f; s < 0.4f - 1e-4f; s += dt)
		{
			p.step(dt, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(dt, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
	}

	private static void steps(SkatePhysics p, SkateInput in, int n, float dt)
	{
		for (int i = 0; i < n; i++)
		{
			p.step(dt, in);
		}
	}

	private static List<TrickEvent> land(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return p.drainTrickEvents();
	}

	@Test
	public void holdingShiftAndWForPoint55SecondsIsOneFrontflip()
	{
		float dt = 0.01f;
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, dt);
		in.powerslide = true;
		in.pushHeld = true; // pressed after take-off
		steps(p, in, 55, dt); // 0.55 s
		assertEquals(TWO_PI, p.getBodyFlipAngle(), 1e-3f);
		in.powerslide = false;
		in.pushHeld = false;
		assertEquals(SkaterState.AIRBORNE, p.getState());
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.FRONTFLIP)), events.subList(0, 2));
		assertEquals(TrickEvent.Type.LANDED, events.get(2).type);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void shiftAndSIsABackflip()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, DT);
		in.powerslide = true;
		in.leanBack = true;
		steps(p, in, 5, DT);
		assertEquals(-5 * DT * RATE, p.getBodyFlipAngle(), 1e-4f);
		// 0.52 s held then released 20 degrees short: the assist turns the rest
		steps(p, in, 21, DT);
		in.powerslide = false;
		in.leanBack = false;
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(TrickEvent.trick(Trick.BACKFLIP), events.get(1));
	}

	@Test
	public void inControllerModeShiftAndLeanUpFlipsLikeShiftAndW()
	{
		float dt = 0.01f;
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.controllerMode = true;
		chargedOllie(p, in, dt);
		in.powerslide = true;
		in.leanForwardKey = true; // the left stick's up arrow, pressed after take-off
		steps(p, in, 55, dt); // 0.55 s: one whole turn
		assertEquals(TWO_PI, p.getBodyFlipAngle(), 1e-3f);
		in.powerslide = false;
		in.leanForwardKey = false;
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.FRONTFLIP)), events.subList(0, 2));
	}

	@Test
	public void inControllerModeShiftAndLeanDownIsABackflip()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.controllerMode = true;
		chargedOllie(p, in, DT);
		in.powerslide = true;
		in.leanBackKey = true;
		steps(p, in, 5, DT);
		assertEquals(-5 * DT * RATE, p.getBodyFlipAngle(), 1e-4f);
		// 0.52 s held then released 20 degrees short: the assist turns the rest, as shiftAndSIsABackflip
		steps(p, in, 21, DT);
		in.powerslide = false;
		in.leanBackKey = false;
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(TrickEvent.trick(Trick.BACKFLIP), events.get(1));
	}

	@Test
	public void leanUpAloneInControllerModeDoesNotFlipWithoutShift()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.controllerMode = true;
		chargedOllie(p, in, DT);
		in.leanForwardKey = true; // no Shift: just a lean, not a flip
		steps(p, in, 10, DT);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void shiftAndLeanUpOutsideControllerModeDoesNotFlip()
	{
		// off the pad, the lean keys are the real Up / Down arrows, not W / S: no body flip without controllerMode
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, DT);
		in.powerslide = true;
		in.leanForwardKey = true;
		steps(p, in, 10, DT);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void wAloneInTheAirDoesNotFlip()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, DT);
		in.pushHeld = true;
		steps(p, in, 10, DT);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
		in.pushHeld = false;
		in.leanBack = true;
		steps(p, in, 10, DT);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void wHeldSinceTakeOffIsIgnoredUntilPressedAgain()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.powerslide = true;
		in.pushHeld = true; // pushing (and Shift held) into the pop
		chargedOllie(p, in, DT);
		steps(p, in, 10, DT);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
		in.pushHeld = false; // released...
		p.step(DT, in);
		in.pushHeld = true; // ...and pressed again, Shift still held from the ground
		p.step(DT, in);
		assertEquals(DT * RATE, p.getBodyFlipAngle(), 1e-5f);
	}

	@Test
	public void releasingStopsTheFlipWithAGentleAssistNearAWholeTurn()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, DT);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 5, DT); // 5 * 0.02 * 11.42 = 1.14 rad = 65 degrees
		in.pushHeld = false;
		float released = p.getBodyFlipAngle();
		steps(p, in, 3, DT);
		// no auto-continue: 65 degrees is outside the 60 degree assist window, so it stays put
		assertEquals(released, p.getBodyFlipAngle(), 0f);

		in.pushHeld = true;
		steps(p, in, 21, DT); // 26 steps: 0.52 s, 340 degrees
		in.pushHeld = false;
		float before = p.getBodyFlipAngle();
		p.step(DT, in);
		float after = p.getBodyFlipAngle();
		assertTrue("assisted toward 360", after > before);
		assertTrue("gently", after - before < 0.1f);
	}

	@Test
	public void landingHalfwayRoundBails()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedOllie(p, in, DT);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 14, DT); // 0.28 s * 654.5 deg/s = 183 degrees
		in.pushHeld = false;
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.BAILED, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.bailed()), events);
		assertEquals(BailReason.BODY_FLIP, p.getLastBailReason());
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void aBodyFlipAndABoardFlipAreSeparateTricks()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.crouch = true;
		steps(p, in, 20, DT);
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
		p.step(DT, in);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 27, DT); // 0.54 s: 353 degrees, assisted the rest
		in.powerslide = false;
		in.pushHeld = false;
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.KICKFLIP), TrickEvent.trick(Trick.FRONTFLIP)), events.subList(0, 2));
		assertEquals(TrickEvent.Type.LANDED, events.get(2).type);
	}

	@Test
	public void noFlipsInAManual()
	{
		SkatePhysics p = rolling(800);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		p.step(DT, in);
		assertEquals(SkaterState.MANUAL, p.getState());
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 10, DT);
		assertEquals(SkaterState.MANUAL, p.getState());
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	private static GrindMap rail(float y0, float y1)
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(10, y0, 10, y1, 30));
		return m;
	}

	@Test
	public void noFlipsOnARail()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), rail(50, 1500), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 10, DT);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	/** Uncharged ollie at 500 north toward a rail from y = 300, reached on the way down (see SkatePhysicsGrindTest). */
	private SkatePhysics towardLateRail(SkateInput in)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), rail(300, 1500), 0, 0, 0);
		p.setRollingSpeed(500);
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		return p;
	}

	@Test
	public void theLateRailLocksWithoutAFlip()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = towardLateRail(in);
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
	}

	@Test
	public void aFrontflipFinishedOntoARailScoresBeforeTheGrind()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = towardLateRail(in);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 28, DT); // 0.56 s: 366 degrees
		in.pushHeld = false;
		in.powerslide = false;
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		// the rail comes within reach once the flip is within 40 degrees of whole, while W is still held, so the
		// lock picks W's nosegrind
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.FRONTFLIP),
			TrickEvent.holdStart(Trick.NOSEGRIND)), p.drainTrickEvents());
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void noGrindLockHalfwayThroughAFlip()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = towardLateRail(in);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 8, DT); // 105 degrees, then left there
		in.pushHeld = false;
		in.powerslide = false;
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.BAILED, p.getState());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import org.junit.Test;

/**
 * What the button-trick preset adds to physics: the spin assist (a faster spin while held in the air), the grind
 * button (a rail catches from further to the side while it is held) and whether a rail is near (the grind button
 * grinds rather than stepping off). Without the buttons nothing changes.
 */
public class SkatePhysicsButtonTricksTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static GrindMap map(GrindSegment... segs)
	{
		GrindMap m = new GrindMap();
		for (GrindSegment s : segs)
		{
			m.add(s);
		}
		return m;
	}

	/** The air spin after popping and steering right for {@code steps} steps. */
	private float spin(boolean fast, int steps)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(400);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		in.steer = 1f;
		in.spinFast = fast;
		for (int i = 0; i < steps; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		return p.airSpin;
	}

	@Test
	public void theSpinAssistSpinsFasterInTheAir()
	{
		float plain = spin(false, 10);
		float fast = spin(true, 10);
		assertTrue(plain > 0f);
		assertEquals(plain * SkatePhysics.SPIN_FAST_MULT, fast, 1e-3f);
	}

	@Test
	public void theSpinAssistDoesNothingOnTheGround()
	{
		SkatePhysics a = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkatePhysics b = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		a.setRollingSpeed(400);
		b.setRollingSpeed(400);
		SkateInput ia = new SkateInput();
		SkateInput ib = new SkateInput();
		ia.steer = ib.steer = 1f;
		ib.spinFast = true;
		for (int i = 0; i < 20; i++)
		{
			a.step(DT, ia);
			b.step(DT, ib);
		}
		assertEquals(a.getHeading(), b.getHeading(), 0f);
	}

	/** Pops north along a north rail {@code side} units to the east and flies out; the state it ends in. */
	private SkaterState popAlongRail(float side, boolean grindHeld)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(side, -2000, side, 2000, 30)),
			0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.grindHeld = grindHeld;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return p.getState();
	}

	@Test
	public void theGrindButtonCatchesARailFurtherToTheSide()
	{
		float between = (GrindMap.SNAP_DISTANCE + GrindMap.ASSIST_SNAP_DISTANCE) / 2f;
		assertNotEquals(SkaterState.GRINDING, popAlongRail(between, false));
		assertEquals(SkaterState.GRINDING, popAlongRail(between, true));
		// within the usual snap distance it catches either way: never harder than without the button
		assertEquals(SkaterState.GRINDING, popAlongRail(GrindMap.SNAP_DISTANCE - 4f, false));
		assertEquals(SkaterState.GRINDING, popAlongRail(GrindMap.SNAP_DISTANCE - 4f, true));
		// and beyond the assist it does not
		assertNotEquals(SkaterState.GRINDING, popAlongRail(GrindMap.ASSIST_SNAP_DISTANCE + 8f, true));
	}

	@Test
	public void aRailIsNearWithinOneAndAHalfTiles()
	{
		assertTrue(new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(150, -500, 150, 500, 30)), 0, 0, 0)
			.isRailNear());
		// across the rail: a few tiles of bucket away
		assertTrue(new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(-500, 180, 500, 180, 30)), 0, 0, 0)
			.isRailNear());
		assertFalse(new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(300, -500, 300, 500, 30)), 0, 0, 0)
			.isRailNear());
		// one far overhead is not near
		assertFalse(new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(50, -500, 50, 500, 900)), 0, 0, 0)
			.isRailNear());
		assertFalse(new SkatePhysics(t, TestWorlds.flat(), map(), 0, 0, 0).isRailNear());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.camera.CameraRig;
import com.gielinorskate.tricks.Gesture;
import org.junit.Test;

/** The heading the chase camera follows: the board, not the roll direction. */
public class SkatePhysicsCameraTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	@Test
	public void cameraHeadingIsTheBoardWhileRollingBackSlowly()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0.5f);
		p.setRollingSpeed(-300f);
		assertEquals(0.5f, p.getCameraHeading(), 1e-6f);
		// the travel direction is behind the board
		assertEquals(Angles.wrap(0.5f + Angles.PI), p.getTravelHeading(), 1e-5f);
	}

	@Test
	public void cameraHeadingFlipsOnlyForRealFakieSpeed()
	{
		// faster than 400 backwards counts as riding fakie: the camera turns to look along the travel
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0.5f);
		p.setRollingSpeed(-500f);
		assertEquals(Angles.wrap(0.5f + Angles.PI), p.getCameraHeading(), 1e-5f);
	}

	@Test
	public void cameraHeadingInTheAirIgnoresSpins()
	{
		// regular ollie heading north, spun in the air: the camera keeps looking along the flight
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(500f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		in.steer = 1f;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		assertTrue(p.getHeading() > 1f);
		assertEquals(0f, p.getCameraHeading(), 1e-5f);
	}

	@Test
	public void cameraHeadingInTheAirAfterASlowRollBackStaysOnTheBoard()
	{
		// popped while rolling back slowly: flight goes south, but the camera kept facing the board (north)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(-300f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(0f, p.getCameraHeading(), 1e-5f);
	}

	@Test
	public void lastAirtimeIsTheFlightLength()
	{
		// uncharged pop: vh 0.92 * 820 = 754.4, 2 * 754.4 / 2000 = 0.754 s in the air (was 0.85: 0.70 s)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(500f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(0.754f, p.getLastAirtime(), 0.03f);
	}

	@Test
	public void uphillCoastIntoRollbackKeepsTheCameraOnTheBoard()
	{
		// 30 per tile uphill from 1000: it stops after ~4 s and rolls back; the old travel heading flipped
		// by 180 deg the moment the speed went negative and the camera spun after it
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(-30f / 128f), 0, 0, 0f);
		p.setRollingSpeed(1000f);
		CameraRig rig = new CameraRig();
		rig.reset(0, 0, 0, 0f);
		SkateInput in = new SkateInput();
		boolean rolledBack = false;
		for (int i = 0; i < 1000 && p.getSpeed() > -390f; i++)
		{
			p.step(DT, in);
			rig.update(p.getX(), p.getY(), p.getH(), p.getCameraHeading(), p.getSpeed(), p.getState(), 0f, DT);
			rolledBack |= p.getSpeed() < -100f;
			float err = (float) Math.toDegrees(Angles.absDiff(rig.getYaw(), p.getHeading()));
			assertTrue("camera " + err + " deg off at step " + i, err < 20f);
		}
		assertTrue(rolledBack);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.tricks.Gesture;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** Comfort fixes: the loaded-area edge scrapes, stumbles are announced, wall bails recover along the wall, R. */
public class SkatePhysicsComfortTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static float deg(float rad)
	{
		return (float) Math.toDegrees(rad);
	}

	private static List<SkateEvent> run(SkatePhysics p, SkateInput in, float seconds)
	{
		List<SkateEvent> events = new ArrayList<>();
		for (int i = 0; i < Math.round(seconds / DT); i++)
		{
			p.step(DT, in);
			events.addAll(p.drainEvents());
		}
		return events;
	}

	@Test
	public void headOnIntoTheLoadedAreaEdgeScrapesInsteadOfBailing()
	{
		// 1500 head-on would bail on any wall (1500 > wallBailSpeed 1100); the edge of the loaded area is no
		// real wall, so it stops the skater instead
		SkatePhysics p = new SkatePhysics(t, TestWorlds.edgeAtY(200), 0, 0, 0f);
		p.setRollingSpeed(1500f);
		List<SkateEvent> events = run(p, new SkateInput(), 0.4f);
		assertFalse(events.contains(SkateEvent.BAIL));
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getY() < 200f);
	}

	@Test
	public void theSameHitOnAnOrdinaryWallStillBails()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, Float.POSITIVE_INFINITY), 0, 0, 0f);
		p.setRollingSpeed(1500f);
		assertTrue(run(p, new SkateInput(), 0.4f).contains(SkateEvent.BAIL));
	}

	@Test
	public void flyingIntoTheLoadedAreaEdgeDoesNotBail()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.edgeAtY(300), 0, 0, 0f);
		p.setRollingSpeed(1500f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		List<SkateEvent> events = run(p, in, 1.2f);
		assertTrue(events.contains(SkateEvent.POP));
		assertFalse(events.contains(SkateEvent.BAIL));
	}

	@Test
	public void aHardHitStumblesOutLoud()
	{
		// 45 deg at 1000: impact 1000 * cos 45 = 707 > wallStumbleSpeed 600
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(45));
		p.setRollingSpeed(1000f);
		List<SkateEvent> events = run(p, new SkateInput(), 0.1f);
		assertEquals(1, events.stream().filter(e -> e == SkateEvent.STUMBLE).count());
		assertFalse(events.contains(SkateEvent.BAIL));
	}

	@Test
	public void aLightHitIsNoStumble()
	{
		// 70 deg at 1000: impact 1000 * cos 70 = 342 < 600
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(70));
		p.setRollingSpeed(1000f);
		assertFalse(run(p, new SkateInput(), 0.1f).contains(SkateEvent.STUMBLE));
	}

	@Test
	public void aWallBailRecoversAlongTheWallNearestTheOldHeading()
	{
		// 20 deg at 1500: 1500 * cos 20 = 1410 > 1100 within 30 deg of head-on: a bail. Facing straight away
		// (180) swung the camera 160 degrees; along the wall to the east (90) it turns only 70.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, (float) Math.toRadians(20));
		p.setRollingSpeed(1500f);
		run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
		List<SkateEvent> events = run(p, new SkateInput(), t.bailDuration + t.bailAutoReset + 0.1f);
		assertTrue(events.contains(SkateEvent.RESET));
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(90f, deg(p.getHeading()), 0.01f);
		// rides off along the wall
		float x0 = p.getX();
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		List<SkateEvent> after = run(p, in, 0.3f);
		assertFalse(after.contains(SkateEvent.BAIL));
		assertTrue("x " + p.getX(), p.getX() > x0 + 50f);
	}

	@Test
	public void aWallBailFromTheLeftRecoversToTheWest()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, (float) Math.toRadians(-20));
		p.setRollingSpeed(1500f);
		run(p, new SkateInput(), 0.2f);
		run(p, new SkateInput(), t.bailDuration + t.bailAutoReset + 0.1f);
		assertEquals(-90f, deg(p.getHeading()), 0.01f);
	}

	@Test
	public void rWhileRollingSlowlyStandsTheSkaterStill()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(100f);
		SkateInput in = new SkateInput();
		in.resetRequested = true;
		p.step(DT, in);
		assertEquals(0f, p.getSpeed(), 0f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.RESET));
	}

	@Test
	public void rWhileRollingFastDoesNothing()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(600f);
		SkateInput in = new SkateInput();
		in.resetRequested = true;
		p.step(DT, in);
		assertTrue(p.getSpeed() > 500f);
		assertFalse(p.drainEvents().contains(SkateEvent.RESET));
	}

	@Test
	public void startingFacingAWallTurnsToTheMostOpenWay()
	{
		// a wall 96 units ahead (under 1.5 tiles): face one of the wide open ways instead
		float h = StartHeading.choose(TestWorlds.wallAtY(96, 300), 0, 0, 0f, t.skaterRadius, t.maxStepUp);
		assertTrue("heading " + deg(h), Math.abs(deg(h)) >= 89.9f);
		// nearest the old heading among the equally open ways: east or west, not south
		assertEquals(90f, Math.abs(deg(h)), 0.01f);
	}

	@Test
	public void startingWithRoomAheadKeepsTheHeading()
	{
		float h = StartHeading.choose(TestWorlds.wallAtY(400, 300), 0, 0, 0.3f, t.skaterRadius, t.maxStepUp);
		assertEquals(0.3f, h, 0f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.world.BlockerSet;
import com.gielinorskate.world.GridCollisionWorld;
import org.junit.Test;

/**
 * Wall scrapes and bails against the world's real contact shapes ({@link CollisionWorld#contact}): a rotated
 * box is scraped along its own face (not a grid axis), and a bail recovers along that face's normal.
 */
public class SkatePhysicsContactTest
{
	private static final float DT = 0.02f;
	private static final float C = 10 * 128f;
	private final SkateTuning t = new SkateTuning();

	/** A long solid box at the centre of a 20-tile world, its long axis along (cos a, sin a) in x/y. */
	private static GridCollisionWorld rotatedWall(float aDeg)
	{
		GridCollisionWorld w = new GridCollisionWorld(20);
		float a = (float) Math.toRadians(aDeg);
		w.addBlocker(C, C, 600, 32, (float) Math.cos(a), (float) Math.sin(a), 200, BlockerSet.SOLID, 0);
		return w;
	}

	private static float deg(float rad)
	{
		return (float) Math.toDegrees(rad);
	}

	@Test
	public void scrapingARotatedBoxFollowsItsFaceNotAGridAxis()
	{
		// box axis at 30 degrees from +x, i.e. heading 60 (0 = north, clockwise); its south-east face normal is
		// (0.5, -0.866), heading 150. Riding at heading 50 grazes that face at 10 degrees.
		GridCollisionWorld w = rotatedWall(30);
		float ux = (float) Math.cos(Math.toRadians(30));
		float uy = (float) Math.sin(Math.toRadians(30));
		float vx = -uy;
		float vy = ux;
		float sx = C - vx * 60 - ux * 400;
		float sy = C - vy * 60 - uy * 400;
		SkatePhysics p = new SkatePhysics(t, w, sx, sy, (float) Math.toRadians(50));
		p.setRollingSpeed(1000);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
			assertEquals(SkaterState.ROLLING, p.getState());
		}
		// a 10-degree graze costs 25% * sin 10 = 4% on contact plus the scrape; the grid-axis normal used to
		// read it as a 30-60 degree hit, zig-zag between axes and end near 740, 1-2 degrees short of the face
		assertTrue("keeps its speed: " + p.getSpeed(), p.getSpeed() > 850f);
		assertEquals("eased along the face, heading " + deg(p.getHeading()), 60f, deg(p.getHeading()), 0.5f);
		// moved along the face, not stuck: well past where it first touched
		float along = (p.getX() - sx) * ux + (p.getY() - sy) * uy;
		assertTrue("along " + along, along > 500f);
		float off = (p.getX() - C) * vx + (p.getY() - C) * vy;
		assertTrue("stays outside the box: " + off, off <= -32f);
	}

	@Test
	public void headOnIntoARockAt1400Bails()
	{
		GridCollisionWorld w = new GridCollisionWorld(20);
		w.addBlocker(C, C, 32, 32, 1f, 0f, 100, BlockerSet.SOLID, 0);
		SkatePhysics p = new SkatePhysics(t, w, C, C - 400, 0);
		p.setRollingSpeed(1400);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 30 && p.getState() == SkaterState.ROLLING; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.BAILED, p.getState());
	}

	@Test
	public void diagonalPassSixtyFromARockCentreIsClean()
	{
		// a 64 x 64 rock: its corner is 32 * sqrt 2 = 45.3 from the centre, so a 45-degree line 60 from the centre
		// clears it by 14.7, more than the 12 skater radius
		GridCollisionWorld rock = new GridCollisionWorld(20);
		rock.addBlocker(C, C, 32, 32, 1f, 0f, 100, BlockerSet.SOLID, 0);
		GridCollisionWorld open = new GridCollisionWorld(20);
		float s = (float) Math.sqrt(0.5);
		float sx = C + s * 60 - s * 400;
		float sy = C - s * 60 - s * 400;
		SkatePhysics p = new SkatePhysics(t, rock, sx, sy, (float) Math.toRadians(45));
		SkatePhysics q = new SkatePhysics(t, open, sx, sy, (float) Math.toRadians(45));
		p.setRollingSpeed(1000);
		q.setRollingSpeed(1000);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 40; i++)
		{
			p.step(DT, in);
			q.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(q.getSpeed(), p.getSpeed(), 1e-3f);
		assertEquals(q.getX(), p.getX(), 1e-3f);
		assertEquals(q.getY(), p.getY(), 1e-3f);
		assertEquals(45f, deg(p.getHeading()), 1e-3f);
	}

	@Test
	public void aBailIntoARotatedBoxRecoversAlongItsFace()
	{
		// into the south-east face (normal heading 150) at heading -10, 20 degrees off head-on, at 1400: 1400 *
		// cos 20 = 1316 > 1100 bails. The recovery faces along the face (normal 150 - 90 = 60, 70 degrees from the
		// old heading; the other way, 240, is 110 away), not a grid axis, and is pushed clear of the box
		GridCollisionWorld w = rotatedWall(30);
		float ux = (float) Math.cos(Math.toRadians(30));
		float uy = (float) Math.sin(Math.toRadians(30));
		float vx = -uy;
		float vy = ux;
		SkatePhysics p = new SkatePhysics(t, w, C - vx * 300, C - vy * 300, (float) Math.toRadians(-10));
		p.setRollingSpeed(1400);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 30 && p.getState() == SkaterState.ROLLING; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.BAILED, p.getState());
		for (int i = 0; i < 200 && p.getState() == SkaterState.BAILED; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(60f, deg(p.getHeading()), 2f);
		Contact c = new Contact();
		assertFalse("pushed clear of the box", w.contact(p.getX(), p.getY(), t.skaterRadius, p.getH(), t.maxStepUp, c));
	}

	@Test
	public void smallerHitboxPassesTenFromABoxCleanly()
	{
		// forgiving collisions: radius 8. Riding north 10 units west of a box's west face never touches it
		t.skaterRadius = 8f;
		GridCollisionWorld w = new GridCollisionWorld(20);
		w.addBlocker(C, C, 32, 32, 1f, 0f, 200, BlockerSet.SOLID, 0);
		SkatePhysics p = new SkatePhysics(t, w, C - 32 - 10, C - 300, 0);
		p.setRollingSpeed(800);
		SkateInput in = new SkateInput();
		float startSpeed = 800;
		for (int i = 0; i < 40; i++)
		{
			p.step(DT, in);
			assertEquals(SkaterState.ROLLING, p.getState());
		}
		assertTrue("passed the box: y " + p.getY(), p.getY() > C + 100);
		assertEquals("no scrape, x unchanged", C - 42f, p.getX(), 1e-3f);
		assertEquals(0f, p.getHeading(), 1e-6f);
		assertTrue("no wall speed loss: " + p.getSpeed(), p.getSpeed() > startSpeed - 100f);
	}

	@Test
	public void smallerHitboxScrapesARotatedBoxAlongItsOwnFace()
	{
		// as scrapingARotatedBoxFollowsItsFaceNotAGridAxis with radius 8: blocking must use the same 8 so the
		// contact always finds the real face (no grid-axis fallback in the 8-12 band)
		t.skaterRadius = 8f;
		GridCollisionWorld w = rotatedWall(30);
		float ux = (float) Math.cos(Math.toRadians(30));
		float uy = (float) Math.sin(Math.toRadians(30));
		float vx = -uy;
		float vy = ux;
		float sx = C - vx * 60 - ux * 400;
		float sy = C - vy * 60 - uy * 400;
		SkatePhysics p = new SkatePhysics(t, w, sx, sy, (float) Math.toRadians(50));
		p.setRollingSpeed(1000);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
			assertEquals(SkaterState.ROLLING, p.getState());
		}
		assertTrue("keeps its speed: " + p.getSpeed(), p.getSpeed() > 850f);
		assertEquals("eased along the face, heading " + deg(p.getHeading()), 60f, deg(p.getHeading()), 0.5f);
		float off = (p.getX() - C) * vx + (p.getY() - C) * vy;
		assertTrue("stays outside the box: " + off, off <= -32f && off >= -32f - 12f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import java.util.Arrays;
import org.junit.Test;

/** Flip easing, catching an unfinished flip, and late flicks. */
public class SkatePhysicsFlipTest
{
	static final float DT = 0.02f;
	static final float TWO_PI = (float) (2 * Math.PI);
	final SkateTuning t = new SkateTuning();

	private static Gesture flick(Direction d)
	{
		return new Gesture(d, false, 0f);
	}

	private SkatePhysics rolling(CollisionWorld w, float speed)
	{
		SkatePhysics p = new SkatePhysics(t, w, 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	/** Ease-out 1 - (1 - u)^2. */
	private static float easeOut(float u)
	{
		u = Math.max(0f, Math.min(1f, u));
		return 1f - (1f - u) * (1f - u);
	}

	@Test
	public void flipStartsFastAndEasesOut()
	{
		// a kickflip popped from the ground: flipTime 0.02 per air step. After 3 air steps (0.06 s of 0.35)
		// ease-out has turned 1 - (1 - 0.171)^2 = 31% (smoothstep had only 8%)
		SkatePhysics p = rolling(TestWorlds.flat(), 500);
		SkateInput in = new SkateInput();
		in.gestures.add(flick(Direction.UP_LEFT));
		p.step(DT, in);
		for (int i = 0; i < 3; i++)
		{
			p.step(DT, in);
		}
		assertEquals(TWO_PI * easeOut(0.06f / 0.35f), p.getBoardRoll(), 1e-3f);
		assertTrue(p.getBoardRoll() > 0.3f * TWO_PI);
	}

	@Test
	public void lateFlickIsCompressedToFinishByTouchdown()
	{
		// uncharged pop: vh 754.4. After 25 air steps (0.5 s) h = 127.2 and vh = -245.6, so the ground is
		// (-245.6 + sqrt(245.6^2 + 2 * 2000 * 127.2)) / 2000 = 0.254 s away: the 0.35 s kickflip would be
		// only 0.254 / 0.35 = 73% done (a bail); compressed to 0.254 s (>= 0.6 * 0.35 = 0.21) it is caught
		SkatePhysics p = rolling(TestWorlds.flat(), 500);
		SkateInput in = new SkateInput();
		in.gestures.add(flick(Direction.UP));
		p.step(DT, in);
		for (int i = 0; i < 25; i++)
		{
			p.step(DT, in);
		}
		in.gestures.add(flick(Direction.UP_LEFT));
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.KICKFLIP), TrickEvent.landed()),
			p.drainTrickEvents());
	}

	@Test
	public void flickTooLateToCompressIsIgnored()
	{
		// after 30 air steps (0.6 s) h = 92.6, vh = -445.6: ground in 0.154 s < 0.6 * 0.35 = 0.21 s, so
		// the flick does nothing (no trick, no bail)
		SkatePhysics p = rolling(TestWorlds.flat(), 500);
		SkateInput in = new SkateInput();
		in.gestures.add(flick(Direction.UP));
		p.step(DT, in);
		for (int i = 0; i < 30; i++)
		{
			p.step(DT, in);
		}
		in.gestures.add(flick(Direction.UP_LEFT));
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.landed(true)), p.drainTrickEvents());
		assertEquals(0f, p.getBoardRoll(), 0f);
	}

	@Test
	public void caughtFlipKeepsRotatingAfterTouchdownInsteadOfSnapping()
	{
		// full pop north at 500 onto a 120-high platform from y = 300: in 20 ms steps h = 16.4n - 0.4n(n + 1)
		// reaches 120 at n = 30 (0.6 s). A kickflip flicked on air step 15 (h 145.6, vh 260, flat ground
		// 0.53 s away, so not compressed) has turned for 15 steps = 0.30 s of 0.35 = 86% at touchdown:
		// caught, not finished.
		SkatePhysics p = rolling(TestWorlds.platformAtY(300, 120), 500);
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(flick(Direction.UP));
		p.step(DT, in);
		for (int i = 0; i < 14; i++)
		{
			p.step(DT, in);
		}
		in.gestures.add(flick(Direction.UP_LEFT));
		float before = 0f;
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			before = p.getBoardRoll();
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(120f, p.getH(), 1e-3f);
		float atLanding = p.getBoardRoll();
		assertTrue("still turning at touchdown: " + atLanding, atLanding > 0.75f * TWO_PI && atLanding < TWO_PI);
		assertTrue("no snap at touchdown", atLanding - before < 0.6f);

		float prev = atLanding;
		boolean finished = false;
		for (int i = 0; i < 20 && !finished; i++)
		{
			p.step(DT, in);
			float roll = p.getBoardRoll();
			if (roll == 0f)
			{
				finished = true;
			}
			else
			{
				assertTrue("keeps turning forward", roll > prev);
				assertTrue("small steps", roll - prev < 0.6f);
				prev = roll;
			}
		}
		assertTrue("the flip finishes on the ground", finished);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.KICKFLIP), TrickEvent.landed()),
			p.drainTrickEvents());
	}

	@Test
	public void flipCaughtOnARailKeepsRotatingWhileGrinding()
	{
		// a rail ahead from y = 300 (top 30) is caught falling, about 0.63 s after an uncharged pop. Air
		// kickflips flicked at different times; whichever lock on still turning must finish on the rail.
		int inProgress = 0;
		for (int k = 10; k <= 24; k++)
		{
			GrindMap rail = new GrindMap();
			rail.add(new GrindSegment(10, 300, 10, 3000, 30));
			SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), rail, 0, 0, 0);
			p.setRollingSpeed(500);
			SkateInput in = new SkateInput();
			in.gestures.add(flick(Direction.UP));
			p.step(DT, in);
			for (int i = 0; i < k; i++)
			{
				p.step(DT, in);
			}
			in.gestures.add(flick(Direction.UP_LEFT));
			for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
			{
				p.step(DT, in);
			}
			if (p.getState() != SkaterState.GRINDING || p.getBoardRoll() == 0f)
			{
				continue;
			}
			inProgress++;
			float prev = p.getBoardRoll();
			assertTrue(prev >= 0.75f * TWO_PI);
			boolean finished = false;
			for (int i = 0; i < 20 && !finished; i++)
			{
				p.step(DT, in);
				assertEquals(SkaterState.GRINDING, p.getState());
				float roll = p.getBoardRoll();
				finished = roll == 0f;
				assertTrue(finished || roll > prev);
				prev = roll;
			}
			assertTrue(finished);
		}
		assertTrue("some flick locked on mid-flip", inProgress > 0);
	}

	@Test
	public void ollieWhileTheLastFlipIsStillFinishingClearsIt()
	{
		SkatePhysics p = rolling(TestWorlds.platformAtY(300, 120), 500);
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(flick(Direction.UP));
		p.step(DT, in);
		for (int i = 0; i < 14; i++)
		{
			p.step(DT, in);
		}
		in.gestures.add(flick(Direction.UP_LEFT));
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertTrue(p.getBoardRoll() != 0f);
		in.gestures.add(flick(Direction.UP));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(0f, p.getBoardRoll(), 0f);
		assertFalse(p.drainEvents().contains(SkateEvent.BAIL));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Grabs.Aim;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * Directional grabs (the aim within 0.15 s of the press picks the grab), tweaks (held past 0.5 s) and grab-flips
 * (a lean key with a grab held turns a front / back flip). A fully charged ollie hangs 0.82 s.
 */
public class SkatePhysicsGrabTest
{
	static final float DT = 0.02f;
	static final float TWO_PI = (float) (2 * Math.PI);
	final SkateTuning t = new SkateTuning();

	private SkatePhysics airborne(SkateInput in)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		in.crouch = true;
		steps(p, in, 20);
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		p.drainTrickEvents();
		return p;
	}

	private static void steps(SkatePhysics p, SkateInput in, int n)
	{
		for (int i = 0; i < n; i++)
		{
			p.step(DT, in);
		}
	}

	private static List<TrickEvent> land(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return p.drainTrickEvents();
	}

	@Test
	public void unaimedGrabsAreTodaysIndyAndMelon()
	{
		for (boolean left : new boolean[]{true, false})
		{
			SkateInput in = new SkateInput();
			SkatePhysics p = airborne(in);
			in.grabLeft = left;
			in.grabRight = !left;
			steps(p, in, 10); // 0.2 s, past the aim window
			Trick want = left ? Trick.INDY : Trick.MELON;
			assertEquals(want, p.getActiveHold());
			in.grabLeft = in.grabRight = false;
			p.step(DT, in);
			assertEquals(Arrays.asList(TrickEvent.holdStart(want), TrickEvent.holdEnd(want, 0.2f)),
				roundSeconds(p.drainTrickEvents()));
		}
	}

	@Test
	public void anAimAtThePressPicksTheGrabStraightAway()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		in.grabAim = Aim.TOE;
		p.step(DT, in);
		assertEquals(Trick.MUTE, p.getActiveHold());
		assertEquals(Arrays.asList(TrickEvent.holdStart(Trick.MUTE)), p.drainTrickEvents());
	}

	@Test
	public void anAimWithinTheWindowRenamesTheGrab()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabRight = true;
		steps(p, in, 5); // 0.1 s
		assertEquals(Trick.MELON, p.getActiveHold());
		in.grabAim = Aim.NOSE;
		p.step(DT, in);
		assertEquals(Trick.CRAIL, p.getActiveHold());
		// a later change of aim does not move it again
		in.grabAim = Aim.TAIL;
		steps(p, in, 3);
		assertEquals(Trick.CRAIL, p.getActiveHold());
		in.grabRight = false;
		p.step(DT, in);
		assertEquals(Arrays.asList(TrickEvent.holdStart(Trick.MELON), TrickEvent.holdStart(Trick.CRAIL),
			TrickEvent.holdEnd(Trick.CRAIL, 0.18f)), roundSeconds(p.drainTrickEvents()));
	}

	@Test
	public void anAimAfterTheWindowIsIgnored()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		steps(p, in, 9); // 0.18 s
		in.grabAim = Aim.NOSE;
		steps(p, in, 2);
		assertEquals(Trick.INDY, p.getActiveHold());
	}

	@Test
	public void holdingPastHalfASecondTweaksTheGrabOnce()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabRight = true;
		steps(p, in, 25); // 0.5 s: not past it yet
		assertEquals(Trick.MELON, p.getActiveHold());
		p.step(DT, in);
		assertEquals(Trick.METHOD, p.getActiveHold());
		steps(p, in, 5);
		assertEquals(Trick.METHOD, p.getActiveHold());
		in.grabRight = false;
		p.step(DT, in);
		assertEquals(Arrays.asList(TrickEvent.holdStart(Trick.MELON), TrickEvent.holdStart(Trick.METHOD),
			TrickEvent.holdEnd(Trick.METHOD, 0.62f)), roundSeconds(p.drainTrickEvents()));
	}

	@Test
	public void aTweakedGrabAutoReleasesOnTouchdown()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		in.grabAim = Aim.TAIL;
		List<TrickEvent> ev = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(TrickEvent.holdStart(Trick.TAILGRAB), ev.get(0));
		assertEquals(TrickEvent.holdStart(Trick.TAILBONE), ev.get(1));
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(2).type);
		assertEquals(Trick.TAILBONE, ev.get(2).trick);
	}

	@Test
	public void leanForwardWithAGrabIsAFrontflip()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		in.leanForwardKey = true;
		steps(p, in, 27); // 0.54 s: nearly a whole turn
		assertEquals(TWO_PI * 27 * DT / 0.55f, p.getBodyFlipAngle(), 1e-3f);
		in.leanForwardKey = false;
		List<TrickEvent> ev = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(ev.toString(), ev.contains(TrickEvent.trick(Trick.FRONTFLIP)));
	}

	@Test
	public void leanBackWithAGrabIsABackflip()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabRight = true;
		in.leanBackKey = true;
		steps(p, in, 5);
		assertEquals(-TWO_PI * 5 * DT / 0.55f, p.getBodyFlipAngle(), 1e-3f);
	}

	@Test
	public void leanKeysWithoutAGrabDoNothing()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.leanForwardKey = true;
		steps(p, in, 10);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void aLeanKeyHeldAtTakeOffCountsOnlyOncePressedAgain()
	{
		SkateInput in = new SkateInput();
		in.leanForwardKey = true; // held into the pop
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		steps(p, in, 5);
		assertEquals(0f, p.getBodyFlipAngle(), 0f);
		in.leanForwardKey = false;
		p.step(DT, in);
		in.leanForwardKey = true;
		steps(p, in, 5);
		assertEquals(TWO_PI * 5 * DT / 0.55f, p.getBodyFlipAngle(), 1e-3f);
	}

	@Test
	public void releasingTheGrabStopsTheGrabFlip()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.grabLeft = true;
		in.leanForwardKey = true;
		steps(p, in, 5);
		in.grabLeft = false;
		float before = p.getBodyFlipAngle();
		p.step(DT, in);
		// no longer driven: it stops where it is (65 degrees: outside the 60 degree assist)
		assertEquals(before, p.getBodyFlipAngle(), 0f);
	}

	@Test
	public void shiftWStillFlipsWithoutAGrab()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = airborne(in);
		in.powerslide = true;
		in.pushHeld = true;
		steps(p, in, 5);
		assertEquals(TWO_PI * 5 * DT / 0.55f, p.getBodyFlipAngle(), 1e-3f);
	}

	/** The events with HOLD_END seconds rounded to 0.01 (they are sums of float steps). */
	private static List<TrickEvent> roundSeconds(List<TrickEvent> events)
	{
		for (int i = 0; i < events.size(); i++)
		{
			TrickEvent e = events.get(i);
			if (e.type == TrickEvent.Type.HOLD_END)
			{
				events.set(i, TrickEvent.holdEnd(e.trick, Math.round(e.seconds * 100f) / 100f));
			}
		}
		return events;
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import org.junit.Test;

/**
 * Leaving a rail (review P1/P5, extra 5): a pop with no steer comes back down onto the same rail, a slow
 * drop-off lands clear of the rail on the side the skater came from, and the exit hop grows with speed.
 */
public class SkatePhysicsGrindExitTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	/** An 8-tile (1024 unit) rail 10 east of the skater, from y = 50 north, top {@code top}. */
	private static GrindMap eightTileRail(float top)
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(10, 50, 10, 50 + 1024, top));
		return m;
	}

	private SkatePhysics lockOn(GrindMap m, float speed, SkateInput in)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), m, 0, 0, 0);
		p.setRollingSpeed(speed);
		in.crouch = true;
		for (int i = 0; i < 12; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		for (int i = 0; i < 200 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		p.drainTrickEvents();
		return p;
	}

	@Test
	public void popWithNoSteerComesBackDownOntoTheSameRail()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(eightTileRail(60), 600, in);
		for (int i = 0; i < 15; i++) // grind 0.3 s
		{
			p.step(DT, in);
		}
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		float minH = Float.POSITIVE_INFINITY;
		for (int i = 0; i < 200 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
			if (p.getState() == SkaterState.AIRBORNE)
			{
				minH = Math.min(minH, p.getH());
			}
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertTrue("caught again before sinking to top - 12: min h " + minH, minH >= 60 - 12);
		assertEquals(60f, p.getH(), 1e-3f);
	}

	@Test
	public void kickflipOutWithNoSteerLandsBackOnTheRail()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(eightTileRail(30), 500, in);
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		for (int i = 0; i < 200 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(0f, p.getBoardRoll(), 1e-3f);
	}

	@Test
	public void slowDropOffLandsClearOfTheRailOnTheApproachSide()
	{
		// lock at 200 lifts the rail speed to 300; friction 60 u/s^2 drops it below 100 after 3.3 s,
		// about 700 units along the 1024 rail, so the exit is the slow one, not the rail end
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(eightTileRail(60), 200, in);
		for (int i = 0; i < 1000 && p.getState() == SkaterState.GRINDING; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.getY() < 50 + 1024 - 32);
		for (int i = 0; i < 200 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		// the skater came from x = 0, west of the x = 10 rail: 150 u/s west for the ~0.33 s drop is ~50
		assertTrue("lands west of the rail line: x " + p.getX(), p.getX() <= 10 - 40);
	}

	@Test
	public void exitHopGrowsWithRailSpeed()
	{
		SkateInput in = new SkateInput();
		SkatePhysics slow = lockOn(railEndingAt(800), 500, in);
		float slowVh = vhAtExit(slow, in);
		SkateInput in2 = new SkateInput();
		SkatePhysics fast = lockOn(railEndingAt(1500), 1400, in2);
		float fastVh = vhAtExit(fast, in2);
		assertTrue("slow " + slowVh + " fast " + fastVh, fastVh > slowVh + 60f);
	}

	@Test
	public void steeringOffTheRailEndLandsToThatSide()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(railEndingAt(400), 600, in);
		in.steer = 1f;
		for (int i = 0; i < 300 && p.getState() != SkaterState.ROLLING; i++)
		{
			p.step(DT, in);
			in.steer = p.getState() == SkaterState.GRINDING ? 1f : 0f;
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("steered east off the end: x " + p.getX(), p.getX() > 10 + 20);
	}

	private static GrindMap railEndingAt(float endY)
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(10, 50, 10, endY, 30));
		return m;
	}

	private static float vhAtExit(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 1000 && p.getState() == SkaterState.GRINDING; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		return p.getVerticalVelocity();
	}

	@Test
	public void noLockAtTheEndOfARailYouAreLeaving()
	{
		// the closest point is clamped to the y = 100 end; heading north only 10 units of rail are left
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 0, 100, 30));
		assertNull(m.nearest(10, 90, 30, 0f, null, GrindMap.SNAP_DISTANCE));
		assertTrue(m.nearest(10, 90, 30, (float) Math.PI, null, GrindMap.SNAP_DISTANCE) != null);
	}

	@Test
	public void slowDropOffDoesNotPingPongBetweenParallelRails()
	{
		// two long flat rails 40 apart (a table's top edges): the slow drop-off hops 150 u/s toward the side
		// the first rail was approached from, right over the other rail. It must not lock that one (and get
		// lifted back to the 300 lock speed) over and over: at most one relock, then the skater lands.
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(10, 50, 10, 50 + 4096, 60));
		m.add(new GrindSegment(-30, 50, -30, 50 + 4096, 60));
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(m, 400, in);
		int relocks = 0;
		for (int i = 0; i < 3000 && p.getState() != SkaterState.ROLLING; i++)
		{
			SkaterState before = p.getState();
			p.step(DT, in);
			if (before == SkaterState.AIRBORNE && p.getState() == SkaterState.GRINDING)
			{
				relocks++;
			}
			if (before == SkaterState.GRINDING && p.getState() == SkaterState.AIRBORNE)
			{
				assertNull("no rail highlighted after a drop-off", p.getPredictedGrind());
			}
		}
		assertTrue("relocks " + relocks, relocks <= 1);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void downhillRailNeverGrindsPastMaxSpeed()
	{
		t.maxSpeed = 700f;
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(10, 50, 10, 50 + 1024, 100, -250));
		SkateInput in = new SkateInput();
		SkatePhysics p = lockOn(m, 600, in);
		float top = 0f;
		for (int i = 0; i < 500 && p.getState() == SkaterState.GRINDING; i++)
		{
			p.step(DT, in);
			if (p.getState() == SkaterState.GRINDING)
			{
				top = Math.max(top, p.getSpeed());
			}
		}
		assertTrue("grind speed " + top, top <= 700f + 1e-3f);
		assertTrue("did speed up to the cap: " + top, top > 690f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import org.junit.Test;

/**
 * Grind magnetism (review P3/P5): wider lock windows while rising ([top - 32, top + 90]) and falling
 * ([top - 28, top + 160]), approaches up to 88 degrees, flips that lock once half done, and a short global
 * relock cooldown so rail-to-rail transfers work.
 */
public class SkatePhysicsGrindMagnetTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static GrindMap map(GrindSegment... segs)
	{
		GrindMap m = new GrindMap();
		for (GrindSegment s : segs)
		{
			m.add(s);
		}
		return m;
	}

	/** Steps until the state leaves AIRBORNE; returns the seconds that took. */
	private static float flyOut(SkatePhysics p, SkateInput in)
	{
		int i = 0;
		for (; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return i * DT;
	}

	@Test
	public void fastFortyFiveDegreePopCrossingHighAboveARailStillLocks()
	{
		// 1000 u/s at 45 degrees to an east-west rail at y = 0 (top 30): 707 u/s toward it. Popped 150 short,
		// the skater enters the 44-unit band 0.15 s later at h = 754.4 * 0.15 - 1000 * 0.15^2 = 91 and crosses
		// the rail at about 115, i.e. 61..85 above its top: past the old top + 48 limit, inside top + 90
		float heading = (float) Math.toRadians(45);
		float perp = 150f;
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(-2000, 0, 2000, 0, 30)),
			0, -perp, heading);
		p.setRollingSpeed(1000);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(30f, p.getH(), 1e-3f);
	}

	@Test
	public void eightyFiveDegreeApproachLocks()
	{
		// rail along y (north); heading 85 degrees, nearly square to it (old limit 80)
		float heading = (float) Math.toRadians(85);
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(60, -1000, 60, 1000, 30)),
			0, 0, heading);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
	}

	@Test
	public void nearlySquareApproachTakesTheGrindDirectionFromTheSteer()
	{
		// heading 87 degrees to a north rail: cos 87 = 0.05 < 0.2, so the travel does not pick a way along it
		float heading = (float) Math.toRadians(87);
		for (float steer : new float[]{1f, -1f})
		{
			SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(60, -1000, 60, 1000, 30)),
				0, 0, heading);
			p.setRollingSpeed(600);
			SkateInput in = new SkateInput();
			in.gestures.add(new Gesture(Direction.UP, false, 0f));
			p.step(DT, in);
			in.steer = steer;
			flyOut(p, in);
			assertEquals(SkaterState.GRINDING, p.getState());
			// steering right (clockwise) from an 87-degree travel turns south (180); left turns north (0)
			float expected = steer > 0 ? (float) Math.PI : 0f;
			assertEquals("steer " + steer, 0f, Angles.absDiff(expected, p.getTravelHeading()), 1e-3f);
		}
	}

	@Test
	public void aKickflipLocksOnceHalfDone()
	{
		// rail alongside from the start; the kickflip (0.35 s) may lock at 0.175 s (was 75%, and the rising
		// h = 754.4 * 0.26 - 1000 * 0.26^2 = 128 was then far above the old top + 48 window)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(10, 30, 10, 1500, 30)), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
		p.step(DT, in);
		float secs = flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertTrue("locked after " + secs, secs >= 0.15f && secs <= 0.2f);
	}

	@Test
	public void popOffOneRailOntoAParallelOneRightAway()
	{
		// rails at x = 10 and x = 70; popping off the first with full right steer (200 u/s) brings the second
		// within 44 units after 16 / 200 = 0.08 s, still rising at 30 + 754.4 * 0.08 - 1000 * 0.08^2 = 84
		// (inside top + 90): the old 0.45 s global cooldown blocked that transfer
		GrindMap m = map(new GrindSegment(10, 30, 10, 3000, 30), new GrindSegment(70, 30, 70, 3000, 30));
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), m, 0, 0, 0);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(10f, p.getX(), 1e-3f);
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.steer = 1f;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		in.steer = 0f;
		float secs = flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(70f, p.getX(), 1e-3f);
		assertTrue("transferred after " + secs, secs < 0.2f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import com.gielinorskate.world.GridCollisionWorld;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/**
 * Grinds on flat ground. An uncharged pop (vh = 820 * 0.92 = 754.4) peaks at 754.4^2 / (2 * 2000) = 142 after
 * about 0.38 s. Lock-on needs h in [top - 16, top + 48] = [14, 78] for a top-30 rail, rising or falling, and
 * within 44 units horizontally (the closest point is clamped to the rail, so its end counts too). Rising,
 * h passes 14 about 3 steps after the pop, so a rail alongside the skater from y = 50 is caught almost
 * at once. Falling back through 78 happens about 0.63 s after the pop, near y = 315 heading north at
 * 500 u/s: rails that start at y = 300 are only reached on the way down.
 */
public class SkatePhysicsGrindTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static GrindMap rail(float x0, float y0, float x1, float y1, float top)
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(x0, y0, x1, y1, top));
		return m;
	}

	/** A rail 10 units east of the skater, from y = 50 north to endY, top 30. */
	private static GrindMap northRail(float endY)
	{
		return rail(10, 50, 10, endY, 30);
	}

	private SkatePhysics rolling(GrindMap grinds, float speed, float heading)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), grinds, 0, 0, heading);
		p.setRollingSpeed(speed);
		return p;
	}

	private static void pop(SkatePhysics p, SkateInput in)
	{
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
	}

	private static void stepWhile(SkatePhysics p, SkateInput in, SkaterState s)
	{
		for (int i = 0; i < 1000 && p.getState() == s; i++)
		{
			p.step(DT, in);
		}
	}

	private static List<TrickEvent.Type> types(List<TrickEvent> events)
	{
		List<TrickEvent.Type> out = new ArrayList<>();
		for (TrickEvent e : events)
		{
			out.add(e.type);
		}
		return out;
	}

	/** Pops and flies onto the rail; returns the trick events so far. */
	private static List<TrickEvent> ollieOn(SkatePhysics p, SkateInput in)
	{
		pop(p, in);
		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.GRINDING, p.getState());
		return p.drainTrickEvents();
	}

	@Test
	public void ollieOntoRailLocksIntoFiftyFifty()
	{
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		List<TrickEvent> ev = ollieOn(p, in);

		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.holdStart(Trick.FIFTY_FIFTY)), ev);
		assertEquals(Trick.FIFTY_FIFTY, p.getActiveHold());
		assertEquals(30f, p.getH(), 1e-4f);
		assertEquals(10f, p.getX(), 1e-3f);
		assertEquals(0f, p.getHeading(), 1e-4f);
		assertTrue(p.getSpeed() > 450f);

		float y = p.getY();
		p.step(DT, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertTrue("moves north along the rail", p.getY() > y + 9f);
		assertEquals(10f, p.getX(), 1e-3f);
		assertEquals(30f, p.getH(), 1e-4f);
	}

	@Test
	public void wHeldGivesNosegrindAndSHeldGivesFiveO()
	{
		SkatePhysics nose = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		ollieOn(nose, in);
		assertEquals(Trick.NOSEGRIND, nose.getActiveHold());

		SkatePhysics five = rolling(northRail(1500), 500, 0);
		SkateInput in2 = new SkateInput();
		in2.leanBack = true;
		ollieOn(five, in2);
		assertEquals(Trick.FIVE_O, five.getActiveHold());
	}

	@Test
	public void wHeldWhileGrindingDoesNotPush()
	{
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		p.drainEvents();
		float s = p.getSpeed();
		in.pushHeld = true;
		in.pushPressed = true;
		p.step(DT, in);
		assertFalse(p.drainEvents().contains(SkateEvent.PUSH));
		assertTrue(p.getSpeed() < s);
	}

	@Test
	public void switchingKeysMidGrindSwitchesTheStraightGrind()
	{
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		in.pushHeld = true;
		p.step(DT, in);
		assertEquals(Trick.NOSEGRIND, p.getActiveHold());
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(Arrays.asList(TrickEvent.Type.HOLD_END, TrickEvent.Type.HOLD_START), types(ev));
		assertEquals(Trick.FIFTY_FIFTY, ev.get(0).trick);
		assertEquals(Trick.NOSEGRIND, ev.get(1).trick);
	}

	@Test
	public void seventyDegreeBoardAngleGivesBoardslideAndKeepsHeading()
	{
		// the rail starts at y = 300 so the skater cannot lock on while rising, before the spin is done
		SkatePhysics p = rolling(rail(10, 300, 10, 1500, 30), 500, 0);
		SkateInput in = new SkateInput();
		pop(p, in);
		// spin 9 steps at 7 rad/s: 9 * 0.14 = 1.26 rad (72 deg), outside the 70 deg spin-assist window
		in.steer = 1f;
		for (int i = 0; i < 9; i++)
		{
			p.step(DT, in);
		}
		in.steer = 0f;
		float heading = p.getHeading();
		assertEquals(72.2f, (float) Math.toDegrees(heading), 0.5f);
		stepWhile(p, in, SkaterState.AIRBORNE);

		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(Trick.BOARDSLIDE, p.getActiveHold());
		assertEquals(heading, p.getHeading(), 1e-4f);
		p.step(DT, in);
		assertEquals(heading, p.getHeading(), 1e-4f);
	}

	@Test
	public void fortyDegreeRailGivesCrookedGrind()
	{
		// rail through (0, 300) along 40 deg, so it passes the y = 265 lock point (class doc) within
		// (300 - 265) * sin 40 = 22 units < SNAP_DISTANCE 28; the skater travels north with heading 0
		float sx = (float) Math.sin(Math.toRadians(40)) * 300;
		float sy = (float) Math.cos(Math.toRadians(40)) * 300;
		SkatePhysics p = rolling(rail(-sx, 300 - sy, sx, 300 + sy, 30), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		assertEquals(Trick.CROOKED, p.getActiveHold());
	}

	@Test
	public void endOfRailExitsToAirborneThenLands()
	{
		SkatePhysics p = rolling(northRail(300), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		stepWhile(p, in, SkaterState.GRINDING);

		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.getY() >= 300f);
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(Arrays.asList(TrickEvent.Type.HOLD_END), types(ev));
		assertEquals(Trick.FIFTY_FIFTY, ev.get(0).trick);
		assertNull(p.getActiveHold());

		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.landed(true)), p.drainTrickEvents());
		assertTrue(p.getSpeed() > 300f);
	}

	@Test
	public void grindLongerThanOneSecondReportsItsLength()
	{
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		stepWhile(p, in, SkaterState.GRINDING);
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(0).type);
		assertTrue("grind length " + ev.get(0).seconds, ev.get(0).seconds >= 1f);
	}

	@Test
	public void droppingBelowMinimumSpeedPopsOff()
	{
		SkatePhysics p = rolling(northRail(1500), 200, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		// lock-on lifts the rail speed to at least 300; 60 u/s^2 friction then takes (300 - 100) / 60
		// = 3.3 s, about 50 + 300 * 3.3 - 30 * 3.3^2 = 717 units, to drop below the 100 u/s leave speed
		assertEquals(300f, p.getSpeed(), 2f);
		stepWhile(p, in, SkaterState.GRINDING);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.getY() < 1500f);
		assertEquals(TrickEvent.Type.HOLD_END, p.drainTrickEvents().get(0).type);
	}

	@Test
	public void flipGestureWhileGrindingPopsOffWithTheFlip()
	{
		// locks around y = 265 (see class doc), grinds 10 steps (100 units), flicks before the y = 450 end
		SkatePhysics p = rolling(northRail(450), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		p.drainEvents();
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.POP));
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(Arrays.asList(TrickEvent.Type.HOLD_END, TrickEvent.Type.TRICK), types(ev));
		assertEquals(Trick.KICKFLIP, ev.get(1).trick);

		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.landed(true)), p.drainTrickEvents());
	}

	@Test
	public void flipOutOfALongRailWithSteerLeavesItAndLands()
	{
		// review P1: with no steer a flip out comes back down onto the same rail (a hop along it, see
		// SkatePhysicsGrindExitTest); steering off carries the skater 200 * 0.75 = 151 units clear of it
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		in.steer = 1f;
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
