	/**
	 * A 160-tall fence along the east edge of tile column 2 (x = 384), from y = 128 to y = 2048. Tall
	 * fences (GRIND_WALL_MAX 180) are rails and still walls.
	 */
	private static GridCollisionWorld tallFenceWorld()
	{
		GridCollisionWorld w = new GridCollisionWorld(20);
		for (int ty = 1; ty < 16; ty++)
		{
			w.setTile(2, ty, GridCollisionWorld.WALL_E, 160f);
		}
		w.rebuildGrinds();
		return w;
	}

	@Test
	public void chargedOllieLocksOntoA160TallFenceFromFlatGround()
	{
		// Full charge: vh = 820, peak 820^2 / 4000 = 168. Lock window for top 160 is [160 - 16, 160 + 48]
		// = [144, 208], so the skater locks on the way down from the peak, while still above 144:
		// falling 168 - 144 = 24 takes sqrt(2 * 24 / 2000) = 0.15 s, i.e. ~90 units at 600 u/s along the rail.
		GridCollisionWorld w = tallFenceWorld();
		SkatePhysics p = new SkatePhysics(t, w, w.getGrinds(), 374, 150, 0);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < 20; i++) // 0.4 s > crouchChargeTime 0.20 s
		{
			p.step(DT, in);
		}
		in.crouch = false;
		pop(p, in);
		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(160f, p.getH(), 1e-4f);
		assertEquals(384f, p.getX(), 1e-3f);
	}

	@Test
	public void quickFlickNowReachesA160TallFenceThroughTheMagnet()
	{
		// Uncharged peak (0.92 * 820)^2 / 4000 = 142.3 (134.8 in 20 ms steps). The old window bottom was
		// 160 - 16 = 144, out of reach; the review P3 magnet locks from 160 - 32 = 128 while rising, so the
		// quick flick now catches it (snapping up at most 32)
		GridCollisionWorld w = tallFenceWorld();
		SkatePhysics p = new SkatePhysics(t, w, w.getGrinds(), 374, 150, 0);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		pop(p, in);
		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(160f, p.getH(), 1e-4f);
	}

	@Test
	public void a160TallFenceStillBlocksASkaterWhoDoesNotClearIt()
	{
		// rolling east into the fence at x = 384: blocker top 160 > h 0 + maxStepUp 24
		GridCollisionWorld w = tallFenceWorld();
		SkatePhysics rollIn = new SkatePhysics(t, w, w.getGrinds(), 200, 600, (float) Math.PI / 2);
		rollIn.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 50; i++)
		{
			rollIn.step(DT, in);
		}
		assertTrue("x " + rollIn.getX(), rollIn.getX() < 384f);

		// a quick flick peaks at 134.8 in 20 ms steps, and 160 > 134.8 + 24, so it is stopped in the air too
		SkatePhysics hop = new SkatePhysics(t, w, w.getGrinds(), 200, 600, (float) Math.PI / 2);
		hop.setRollingSpeed(600);
		pop(hop, in);
		for (int i = 0; i < 100 && hop.getState() != SkaterState.ROLLING; i++)
		{
			hop.step(DT, in);
		}
		assertTrue("x " + hop.getX(), hop.getX() < 384f);
	}

	@Test
	public void steepSeventyFiveDegreeOllieOverAFenceLocksAndSlidesAlongIt()
	{
		// fence along x = 100; heading 75 deg (east of north). Rising through the lock window: at
		// x = 100 - 44 = 56 (0.116 s at 500 * sin 75 = 483 u/s east) h = 754.4 * 0.116 - 1000 * 0.116^2 = 74,
		// inside [14, 78], so it locks before it is past the fence
		float heading = (float) Math.toRadians(75);
		SkatePhysics p = rolling(rail(100, -500, 100, 1500, 30), 500, heading);
		SkateInput in = new SkateInput();
		pop(p, in);
		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(Trick.BOARDSLIDE, p.getActiveHold());
		assertEquals(100f, p.getX(), 1e-3f);
		// speed redirected along the rail: max(500 cos 75 = 129, 0.6 * 500 = 300, 300) = 300, keeping the
		// northward sign of the along-rail component
		assertEquals(300f, p.getSpeed(), 2f);
		assertEquals(0f, p.getTravelHeading(), 1e-4f);
		float y = p.getY();
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(100f, p.getX(), 1e-3f);
		assertTrue("slides north along the fence", p.getY() > y + 50f);
	}

	@Test
	public void locksOnWhileStillRising()
	{
		// rail top 30 alongside: the window [14, 78] is reached about 3 steps after the pop, long before
		// the 0.38 s peak
		SkatePhysics p = rolling(northRail(1500), 500, 0);
		SkateInput in = new SkateInput();
		pop(p, in);
		for (int i = 0; i < 6 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(30f, p.getH(), 1e-4f);
	}

	@Test
	public void rollingStillOnlyLocksOntoRailsAboveTheRidingSurface()
	{
		SkatePhysics p = rolling(rail(10, 60, 10, 800, 3), 500, 0);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	/** Grinds from the ollie until the grind ends; returns the largest x reached while still grinding. */
	private static float grindOut(SkatePhysics p, SkateInput in)
	{
		float maxX = Float.NEGATIVE_INFINITY;
		for (int i = 0; i < 1000 && p.getState() == SkaterState.GRINDING; i++)
		{
			maxX = Math.max(maxX, p.getX());
			p.step(DT, in);
		}
		return maxX;
	}

	@Test
	public void grindFollowsTheFenceAroundAGentleBend()
	{
		// north along x = 10 to y = 600, then a 45-degree bend north-east for 400 units, 5 units higher
		// and with a 6-unit gap between the pieces
		GrindMap m = northRail(600);
		float d = 400f * (float) Math.sqrt(0.5);
		m.add(new GrindSegment(14, 604, 14 + d, 604 + d, 35));
		SkatePhysics p = rolling(m, 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		float maxX = grindOut(p, in);

		assertTrue("followed the bend east: max x " + maxX, maxX > 14 + d - 20);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(Arrays.asList(TrickEvent.Type.HOLD_END), types(ev));
		assertEquals(Trick.FIFTY_FIFTY, ev.get(0).trick);
		assertTrue("one continuous grind: " + ev.get(0).seconds, ev.get(0).seconds > 0.6f);
	}

	@Test
	public void boardTurnsWithTheBend()
	{
		GrindMap m = northRail(600);
		float d = 400f * (float) Math.sqrt(0.5);
		m.add(new GrindSegment(10, 600, 10 + d, 600 + d, 30));
		SkatePhysics p = rolling(m, 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		for (int i = 0; i < 1000 && p.getState() == SkaterState.GRINDING && p.getX() < 60; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(45f, (float) Math.toDegrees(p.getTravelHeading()), 0.1f);
		assertEquals(45f, (float) Math.toDegrees(p.getHeading()), 0.1f);
	}

	@Test
	public void ninetyDegreeCornerEndsTheGrind()
	{
		GrindMap m = northRail(600);
		m.add(new GrindSegment(10, 600, 600, 600, 30));
		SkatePhysics p = rolling(m, 500, 0);
		SkateInput in = new SkateInput();
		ollieOn(p, in);
		float maxX = grindOut(p, in);
		assertEquals(10f, maxX, 1e-3f);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.getY() >= 600f);
		stepWhile(p, in, SkaterState.AIRBORNE);
		assertEquals(SkaterState.ROLLING, p.getState());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import org.junit.Test;

/** Sloped rails under the physics, and the slide / crooked variations picked by W / S and the spin. */
public class SkatePhysicsGrindVarietyTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static GrindMap map(GrindSegment s)
	{
		GrindMap m = new GrindMap();
		m.add(s);
		return m;
	}

	private static void flyOut(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
	}

	@Test
	public void grindingASlopedRailFollowsItsHeight()
	{
		// 30 high at y = 30 rising to 130 at y = 1030 (0.1 per unit)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(10, 30, 10, 1030, 30, 130)), 0, 0, 0);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		assertEquals(30 + 0.1f * (p.getY() - 30), p.getH(), 1e-2f);
		for (int i = 0; i < 20; i++)
		{
			p.step(DT, in);
			assertEquals(30 + 0.1f * (p.getY() - 30), p.getH(), 1e-2f);
		}
	}

	@Test
	public void grindingDownASlopedRailIsFasterThanUpIt()
	{
		SkatePhysics up = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(10, 30, 10, 2030, 30, 330)), 0, 0, 0);
		SkatePhysics down = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(10, 30, 10, 2030, 30, -270)), 0, 0, 0);
		float[] speeds = new float[2];
		int k = 0;
		for (SkatePhysics p : new SkatePhysics[]{up, down})
		{
			p.setRollingSpeed(600);
			SkateInput in = new SkateInput();
			in.gestures.add(new Gesture(Direction.UP, false, 0f));
			p.step(DT, in);
			flyOut(p, in);
			assertEquals(SkaterState.GRINDING, p.getState());
			for (int i = 0; i < 25; i++)
			{
				p.step(DT, in);
			}
			speeds[k++] = p.getSpeed();
		}
		assertTrue("up " + speeds[0] + " down " + speeds[1], speeds[1] > speeds[0] + 50f);
	}

	/** Pops and spins right (clockwise) for {@code spinSteps} steps, then flies onto a north rail starting at y = 300. */
	private SkatePhysics slideOn(int spinSteps, SkateInput keys)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(10, 300, 10, 1500, 30)), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = keys;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		in.steer = 1f;
		for (int i = 0; i < spinSteps; i++)
		{
			p.step(DT, in);
		}
		in.steer = 0f;
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		return p;
	}

	/** Ollies (no spin) onto a rail along the 40-degree line through (0, 300): a crooked-angle lock. */
	private SkatePhysics crookedOn(SkateInput in)
	{
		float sx = (float) Math.sin(Math.toRadians(40)) * 300;
		float sy = (float) Math.cos(Math.toRadians(40)) * 300;
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), map(new GrindSegment(-sx, 300 - sy, sx, 300 + sy, 30)), 0, 0, 0);
		p.setRollingSpeed(500);
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		flyOut(p, in);
		assertEquals(SkaterState.GRINDING, p.getState());
		return p;
	}

	@Test
	public void slidesAndTheirVariations()
	{
		// 9 steps at 7 rad/s = 72 degrees off the rail: a boardslide
		assertEquals(Trick.BOARDSLIDE, slideOn(9, new SkateInput()).getActiveHold());
		SkateInput w = new SkateInput();
		w.pushHeld = true;
		assertEquals(Trick.NOSESLIDE, slideOn(9, w).getActiveHold());
		SkateInput s = new SkateInput();
		s.leanBack = true;
		assertEquals(Trick.TAILSLIDE, slideOn(9, s).getActiveHold());

		assertEquals(Trick.CROOKED, crookedOn(new SkateInput()).getActiveHold());
		SkateInput s2 = new SkateInput();
		s2.leanBack = true;
		assertEquals(Trick.SMITH, crookedOn(s2).getActiveHold());
		SkateInput w2 = new SkateInput();
		w2.pushHeld = true;
		assertEquals(Trick.FEEBLE, crookedOn(w2).getActiveHold());
	}

	@Test
	public void wAndSSwitchTheSlideMidGrind()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = slideOn(9, in);
		in.pushHeld = true;
		p.step(DT, in);
		assertEquals(Trick.NOSESLIDE, p.getActiveHold());
		in.pushHeld = false;
		in.leanBack = true;
		p.step(DT, in);
		assertEquals(Trick.TAILSLIDE, p.getActiveHold());
	}

	@Test
	public void spinningPastNinetyDegreesGivesALipslide()
	{
		// 12 steps at 7 rad/s = 96 degrees from the approach (outside the 70-degree spin assist either way):
		// across the rail like a boardslide, but turned past square
		assertEquals(Trick.LIPSLIDE, slideOn(12, new SkateInput()).getActiveHold());
	}

	@Test
	public void newGrindsAreGrindTricksWithPoints()
	{
		for (Trick g : new Trick[]{Trick.NOSESLIDE, Trick.TAILSLIDE, Trick.SMITH, Trick.FEEBLE, Trick.LIPSLIDE})
		{
			assertEquals(TrickKind.GRIND, g.kind);
			assertTrue(g.points > Trick.FIFTY_FIFTY.points);
		}
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertSame;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.TrickEvent;
import com.gielinorskate.world.GrindMap;
import com.gielinorskate.world.GrindSegment;
import org.junit.Test;

/** Read-only values for the HUD: the latest landing's quality and the rail the current flight will catch. */
public class SkatePhysicsHudTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics popped(CollisionWorld w, GrindMap m, Direction flick)
	{
		SkatePhysics p = new SkatePhysics(t, w, m, 0, 0, 0);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(flick, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		return p;
	}

	private static void land(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
	}

	@Test
	public void aStraightOllieLandsClean()
	{
		SkatePhysics p = popped(TestWorlds.flat(), new GrindMap(), Direction.UP);
		assertNull(p.lastLandingQuality);
		land(p, new SkateInput());
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(LandingQuality.CLEAN, p.lastLandingQuality);
	}

	@Test
	public void aFinishedKickflipLandsClean()
	{
		SkatePhysics p = popped(TestWorlds.flat(), new GrindMap(), Direction.UP_LEFT);
		land(p, new SkateInput());
		assertEquals(LandingQuality.CLEAN, p.lastLandingQuality);
	}

	@Test
	public void landingTwentyDegreesOffTheTravelIsSloppy()
	{
		// steer in the last 3 steps before touchdown: 3 * 0.14 rad = 24 degrees, inside the 55-degree landing
		// tolerance but over the 15 of a clean landing
		SkatePhysics p = popped(TestWorlds.flat(), new GrindMap(), Direction.UP);
		SkateInput in = new SkateInput();
		float prevH = p.getH();
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			boolean falling = p.getH() < prevH;
			prevH = p.getH();
			in.steer = falling && p.getH() < 40 ? 1f : 0f;
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(LandingQuality.SLOPPY, p.lastLandingQuality);
	}

	@Test
	public void rollingOffALedgeHasNoQuality()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.stepAtY(0, 0, 100), 0, 100, (float) Math.PI);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 20 && p.getState() == SkaterState.ROLLING; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertNull(p.lastLandingQuality);
	}

	@Test
	public void predictedGrindIsTheRailTheFlightWillCatch()
	{
		// the rail starts at y = 400, reached only on the way down
		GrindSegment rail = new GrindSegment(10, 400, 10, 1500, 30);
		GrindMap m = new GrindMap();
		m.add(rail);
		SkatePhysics rolling = new SkatePhysics(t, TestWorlds.flat(), m, 0, 0, 0);
		assertNull(rolling.getPredictedGrind());

		SkatePhysics p = popped(TestWorlds.flat(), m, Direction.UP);
		assertSame(rail, p.getPredictedGrind());
		SkateInput in = new SkateInput();
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			assertSame(rail, p.getPredictedGrind());
			p.step(DT, in);
		}
		assertEquals(SkaterState.GRINDING, p.getState());
		assertNull(p.getPredictedGrind());
	}

	@Test
	public void noPredictionWhenTheFlightMissesEveryRail()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(300, 0, 300, 1500, 30));
		SkatePhysics p = popped(TestWorlds.flat(), m, Direction.UP);
		assertNull(p.getPredictedGrind());
	}

	@Test
	public void theLandedEventCarriesTheLandingQuality()
	{
		SkatePhysics clean = popped(TestWorlds.flat(), new GrindMap(), Direction.UP);
		clean.drainTrickEvents();
		land(clean, new SkateInput());
		assertTrue(clean.drainTrickEvents().contains(TrickEvent.landed(true)));

		SkatePhysics p = popped(TestWorlds.flat(), new GrindMap(), Direction.UP);
		p.drainTrickEvents();
		SkateInput in = new SkateInput();
		float prevH = p.getH();
		for (int i = 0; i < 300 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			boolean falling = p.getH() < prevH;
			prevH = p.getH();
			in.steer = falling && p.getH() < 40 ? 1f : 0f;
			p.step(DT, in);
		}
		assertTrue(p.drainTrickEvents().contains(TrickEvent.landed(false)));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Manuals on the manual key (Space): hold for a manual, with W for a nose manual. */
public class SkatePhysicsManualTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	@Test
	public void spaceAndWIsANoseManualThatNeverPushes()
	{
		SkatePhysics p = rolling(400);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		in.pushHeld = true;
		in.pushPressed = true;
		List<SkateEvent> events = new ArrayList<>();
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
			events.addAll(p.drainEvents());
		}
		assertEquals(SkaterState.MANUAL, p.getState());
		assertEquals(Trick.NOSE_MANUAL, p.getActiveHold());
		assertFalse(events.toString(), events.contains(SkateEvent.PUSH));
		assertTrue("coasting, not pushing", p.getSpeed() < 400f);

		// a flick during the nose manual pops out and links into the same combo
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(TrickEvent.holdStart(Trick.NOSE_MANUAL), ev.get(0));
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(1).type);
		assertEquals(TrickEvent.trick(Trick.OLLIE), ev.get(2));
	}

	@Test
	public void theControllersTiltDownIsANoseManualWithoutW()
	{
		SkatePhysics p = rolling(400);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		in.noseManualHeld = true;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.MANUAL, p.getState());
		assertEquals(Trick.NOSE_MANUAL, p.getActiveHold());
		in.noseManualHeld = false;
		p.step(DT, in);
		assertEquals(Trick.MANUAL, p.getActiveHold());
	}

	@Test
	public void pressingWMidManualSwapsToANoseManual()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.pushHeld = true;
		in.pushPressed = true;
		p.step(DT, in);
		assertEquals(Trick.NOSE_MANUAL, p.getActiveHold());
		assertFalse(p.drainEvents().contains(SkateEvent.PUSH));
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(3, ev.size());
		assertEquals(Trick.MANUAL, ev.get(1).trick);
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(1).type);
		assertEquals(TrickEvent.holdStart(Trick.NOSE_MANUAL), ev.get(2));

		in.pushHeld = false;
		p.step(DT, in);
		assertEquals(Trick.MANUAL, p.getActiveHold());
	}

	@Test
	public void wPushesAgainOnceSpaceIsReleased()
	{
		SkatePhysics p = rolling(400);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		in.pushHeld = true;
		p.step(DT, in);
		in.manualHeld = false;
		p.step(DT, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.PUSH));
	}

	@Test
	public void manualEndsBelowOneHundredTwentyAndDoesNotStartBelowOneHundredFifty()
	{
		// 160 u/s coasting loses about 45 + 0.00006 * 140^2 = 46.2 u/s^2: below 120 after ~0.87 s (44 steps)
		SkatePhysics p = rolling(160);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		p.step(DT, in);
		assertEquals(SkaterState.MANUAL, p.getState());
		for (int i = 0; i < 50; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertNull(p.getActiveHold());
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(2, ev.size());
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(1).type);

		SkatePhysics slow = rolling(100);
		slow.step(DT, in);
		assertEquals(SkaterState.ROLLING, slow.getState());
	}

	@Test
	public void manualNeverBails()
	{
		SkatePhysics p = rolling(1200);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		for (int i = 0; i < 200; i++)
		{
			in.steer = (i / 25) % 2 == 0 ? 1f : -1f;
			p.step(DT, in);
			assertTrue(p.getState() == SkaterState.MANUAL || p.getState() == SkaterState.ROLLING);
		}
		assertFalse(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void kickflipIntoASpaceHeldLandingIsOneComboThatResolvesAfterRelease()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		ComboScorer scorer = new ComboScorer();
		float[] now = {0f};
		List<SkateEvent> events = new ArrayList<>();

		in.crouch = true;
		run(p, in, scorer, now, events, 10);
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP_LEFT, false, 0f));
		run(p, in, scorer, now, events, 1);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		in.manualHeld = true; // Space held through the landing
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			run(p, in, scorer, now, events, 1);
		}
		assertEquals(SkaterState.MANUAL, p.getState());
		assertEquals(Trick.MANUAL, p.getActiveHold());
		assertTrue("camera dip / landing anim still fire", events.contains(SkateEvent.LAND));
		assertEquals("combo still open", ComboScorer.Result.NONE, scorer.lastResult());
		assertEquals(Arrays.asList("Kickflip"), scorer.comboNames());

		run(p, in, scorer, now, events, 25); // 0.5 s manual
		assertEquals(ComboScorer.Result.NONE, scorer.lastResult());
		in.manualHeld = false;
		run(p, in, scorer, now, events, 1);
		assertEquals(SkaterState.ROLLING, p.getState());
		float released = now[0];
		run(p, in, scorer, now, events, 20); // 0.4 s: still rolling out
		assertEquals(ComboScorer.Result.NONE, scorer.lastResult());
		run(p, in, scorer, now, events, 6); // past 0.5 s after the release
		assertTrue(now[0] - released >= 0.5f);
		assertTrue(scorer.lastResult().isLanded());
		assertEquals(Arrays.asList("Kickflip", "Manual"), scorer.lastComboNames());
	}

	/** Steps `n` times, feeding trick events and the roll-out clock to the scorer like the session does. */
	private static void run(SkatePhysics p, SkateInput in, ComboScorer scorer, float[] now, List<SkateEvent> events, int n)
	{
		for (int i = 0; i < n; i++)
		{
			p.step(DT, in);
			now[0] += DT;
			events.addAll(p.drainEvents());
			for (TrickEvent e : p.drainTrickEvents())
			{
				assertFalse("no LANDED while the combo carries on into a manual",
					e.type == TrickEvent.Type.LANDED && p.getState() == SkaterState.MANUAL);
				scorer.accept(e, now[0]);
			}
			scorer.update(now[0], p.getState() == SkaterState.ROLLING && p.getActiveHold() == null);
		}
	}

	@Test
	public void manualSpeedHasHysteresisEnterAt150LeaveBelow120()
	{
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		SkatePhysics slow = rolling(140);
		slow.step(DT, in);
		assertEquals("140 is too slow to start a manual", SkaterState.ROLLING, slow.getState());

		SkatePhysics p = rolling(160);
		p.step(DT, in);
		assertEquals(SkaterState.MANUAL, p.getState());
		for (int i = 0; i < 300 && p.getSpeed() >= 125f; i++)
		{
			p.step(DT, in);
		}
		assertEquals("still in the manual at " + p.getSpeed(), SkaterState.MANUAL, p.getState());
		for (int i = 0; i < 300 && p.getState() == SkaterState.MANUAL; i++)
		{
			p.step(DT, in);
		}
		assertTrue("left the manual below 120: " + p.getSpeed(), p.getSpeed() < 120f && p.getSpeed() > 110f);
	}

	@Test
	public void bumpySlopeHoveringNear150DoesNotFlickerTheManual()
	{
		// downhill grade 0.057 * 2000 * 0.4 = 45.6 u/s^2 balances the 45 rolling friction, so the speed hovers
		// at 150; 3-unit bumps every 126 units swing it by about +-16 (slope 0.15 * 800 = 120 u/s^2 over a
		// 0.84 s bump), back and forth across 150
		SkatePhysics p = new SkatePhysics(t, TestWorlds.bumpyDownhillNorth(0.057f, 3f, 20f), 0, 0, 0);
		p.setRollingSpeed(155);
		SkateInput in = new SkateInput();
		in.manualHeld = true;
		int starts = 0;
		for (int i = 0; i < 200; i++)
		{
			p.step(DT, in);
			for (TrickEvent e : p.drainTrickEvents())
			{
				if (e.type == TrickEvent.Type.HOLD_START)
				{
					starts++;
				}
			}
		}
		assertEquals("one manual, no flicker", 1, starts);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.input.MousePath;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Random;
import org.junit.Test;

/** Pop height (charge) and the full mouse-path-to-pop pipeline. */
public class SkatePhysicsPopTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	@Test
	public void chargeIsNotLostOnThePopStep()
	{
		// 18 steps (0.36 s) crouched, then the flick arrives with crouch already false (the recognizer
		// re-arms on the flick). The pop step must not decay crouchTime before reading it:
		// 0.36 s >= crouchChargeTime -> full charge -> vh = ollieImpulse = 820.
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < 18; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(820f, p.getVerticalVelocity(), 1e-3f);
	}

	@Test
	public void crouchingForCrouchChargeTimeGivesAFullPop()
	{
		// crouchChargeTime 0.20 s = 10 steps of 0.02 s -> charge 1 -> vh 820
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.crouch = true;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(820f, p.getVerticalVelocity(), 1e-3f);
	}

	@Test
	public void uncrouchedPopIsMinPopFraction()
	{
		// 0.92 * 820 = 754.4
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(0.92f * 820f, p.getVerticalVelocity(), 1e-2f);
	}

	@Test
	public void nollieWindUpChargesWithoutCrouching()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		in.charge = true; // nollie wind-up: charging, but no crouch pose
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		in.charge = false;
		in.gestures.add(new Gesture(Direction.DOWN, true, 0f));
		p.step(DT, in);
		assertEquals(820f, p.getVerticalVelocity(), 1e-3f);
		assertTrue(p.isLastPopNollie());
	}

	@Test
	public void chargingAloneDoesNotBlockPushing()
	{
		SkatePhysics p = rolling(0);
		SkateInput in = new SkateInput();
		in.charge = true;
		in.pushPressed = true;
		p.step(DT, in);
		assertTrue(p.drainEvents().contains(SkateEvent.PUSH));
	}

	@Test
	public void fiftyQuickOlliesPopToWithinTenPercentOfEachOther()
	{
		// quick ollies: a 40-50 px pull over 120-180 ms, then a 60-75 px flick up in 45-70 ms.
		// They all pop at or near minPopFraction: 20 ms steps peak at 0.02 * (18 * 754.4 - 40 * 171) = 134.8 for
		// 0.92 (was 114.6 at 0.85) and 160.0 for a full 820, and these must land within 10% of each other.
		Random rnd = new Random(11);
		float min = Float.MAX_VALUE;
		float max = 0f;
		for (int k = 0; k < 50; k++)
		{
			double pullMs = 120 + rnd.nextDouble() * 60;
			double pull = 40 + rnd.nextDouble() * 10;
			double flickMs = 45 + rnd.nextDouble() * 25;
			MousePath path = MousePath.of(k, 0.6, MousePath.at(0, 0, 0), MousePath.at(pullMs, 0, pull),
				MousePath.at(pullMs + flickMs, rnd.nextGaussian() * 4, pull - 60 - rnd.nextDouble() * 15));
			GestureRig rig = new GestureRig(rolling(800)).play(path, 1800, 144);
			assertEquals("ollie " + k + " " + rig.trickEvents, TrickEvent.trick(Trick.OLLIE), rig.trickEvents.get(0));
			min = Math.min(min, rig.peak);
			max = Math.max(max, rig.peak);
		}
		assertTrue("min peak " + min, min >= 130f);
		assertTrue("spread " + min + ".." + max, (max - min) / max < 0.10f);
	}

	@Test
	public void windUpPausedForASecondThenFlickedIsAFullOllieAndPushWorksAfterRelease()
	{
		MousePath path = MousePath.of(21, 0.6, MousePath.at(0, 0, 0), MousePath.at(150, 0, 45),
			MousePath.at(1150, 1, 46), MousePath.at(1210, 2, -25));
		GestureRig rig = new GestureRig(rolling(800)).play(path, 2600, 144);
		assertEquals(TrickEvent.trick(Trick.OLLIE), rig.trickEvents.get(0));
		// a full 1 s crouch: vh 820, peak 0.02 * (20 * 820 - 40 * 210) = 160.0 in 20 ms steps
		assertTrue("peak " + rig.peak, rig.peak > 159f);
		assertEquals(SkaterState.ROLLING, rig.physics.getState());

		rig.recognizer.end();
		assertFalse(rig.recognizer.isCrouching());
		rig.in.crouch = rig.recognizer.isCrouching();
		rig.in.charge = rig.recognizer.isCharging();
		rig.in.pushPressed = true;
		rig.physics.step(DT, rig.in);
		assertTrue(rig.physics.drainEvents().contains(SkateEvent.PUSH));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import org.junit.Test;

/** The read-only signals the renderer's body animation reads: pop charge, vertical speed, landing speed. */
public class SkatePhysicsRenderSignalsTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	@Test
	public void popChargeRisesWithCrouchAndCapsAtOne()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		assertEquals(0f, p.getPopCharge(), 0f);
		in.crouch = true;
		// 5 steps of 0.02 s = 0.1 s of crouchChargeTime 0.2 s -> half charge
		for (int i = 0; i < 5; i++)
		{
			p.step(DT, in);
		}
		assertEquals(0.5f, p.getPopCharge(), 1e-3f);
		for (int i = 0; i < 20; i++)
		{
			p.step(DT, in);
		}
		assertEquals(1f, p.getPopCharge(), 0f);
		// released: decays at twice the charge rate (0.2 s back to empty from 0.5 s held is clamped at 1 first)
		in.crouch = false;
		for (int i = 0; i < 40; i++)
		{
			p.step(DT, in);
		}
		assertEquals(0f, p.getPopCharge(), 0f);
	}

	@Test
	public void verticalVelocityAndLandingSpeedOfAnOllie()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(0f, p.getPopCharge(), 0f);
		int guard = 0;
		while (p.getState() == SkaterState.AIRBORNE && guard++ < 200)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(0f, p.getVerticalVelocity(), 0f);
		// lands at about its take-off speed: 0.92 * 820 = 754, within a step of gravity (2000 * 0.02 = 40)
		float landing = p.getLastLandingSpeed();
		assertTrue("landing " + landing, landing > 700f && landing < 800f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Grabs.Aim;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.List;
import org.junit.Test;

/**
 * The rolling grab: Q / E held while rolling crouches and grabs the board on the ground. Pose only: no trick events,
 * no points, no push while held; a pop lets go and the held key grabs again in the air, and landing with the key
 * still held settles back into it.
 */
public class SkatePhysicsRollingGrabTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(400);
		return p;
	}

	private static void steps(SkatePhysics p, SkateInput in, int n)
	{
		for (int i = 0; i < n; i++)
		{
			p.step(DT, in);
		}
	}

	@Test
	public void holdingAGrabKeyWhileRollingGrabsTheBoardWithNoTrick()
	{
		for (boolean left : new boolean[]{true, false})
		{
			SkateInput in = new SkateInput();
			SkatePhysics p = rolling();
			in.grabLeft = left;
			in.grabRight = !left;
			steps(p, in, 30);
			assertEquals(SkaterState.ROLLING, p.getState());
			assertEquals(left ? Trick.INDY : Trick.MELON, p.getGroundGrab());
			assertEquals(left, p.isGrabLeftHand());
			// not a hold: nothing to score, nothing for the combo
			assertNull(p.getActiveHold());
			assertTrue(p.drainTrickEvents().isEmpty());
			in.grabLeft = in.grabRight = false;
			p.step(DT, in);
			assertNull(p.getGroundGrab());
			assertTrue(p.drainTrickEvents().isEmpty());
		}
	}

	@Test
	public void theAimPicksTheRollingGrabLikeInTheAir()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.grabRight = true;
		steps(p, in, 3);
		assertEquals(Trick.MELON, p.getGroundGrab());
		in.grabAim = Aim.NOSE;
		p.step(DT, in);
		assertEquals(Trick.CRAIL, p.getGroundGrab());
		// a rolling grab never tweaks
		steps(p, in, 50);
		assertEquals(Trick.CRAIL, p.getGroundGrab());
		in.grabRight = false;
		in.grabAim = null;
		in.grabLeft = true;
		p.step(DT, in);
		p.step(DT, in);
		in.grabAim = Aim.TAIL;
		p.step(DT, in);
		assertEquals(Trick.TAILGRAB, p.getGroundGrab());
		assertTrue(p.drainTrickEvents().isEmpty());
	}

	@Test
	public void noPushWhileGrabbingAndWDoesNotLetGo()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.grabLeft = true;
		steps(p, in, 5);
		p.drainEvents();
		float before = p.getSpeed();
		in.pushPressed = true;
		in.pushHeld = true;
		steps(p, in, 40);
		assertFalse(p.drainEvents().contains(SkateEvent.PUSH));
		assertTrue("no push speed: " + p.getSpeed(), p.getSpeed() < before);
		assertEquals(Trick.INDY, p.getGroundGrab());
		// let go with W still held: pushing again
		in.grabLeft = false;
		steps(p, in, 2);
		assertNull(p.getGroundGrab());
		assertTrue(p.drainEvents().contains(SkateEvent.PUSH));
	}

	@Test
	public void theRollingGrabDoesNotChangeTheRoll()
	{
		SkateInput plain = new SkateInput();
		SkateInput grab = new SkateInput();
		grab.grabRight = true;
		SkatePhysics a = rolling();
		SkatePhysics b = rolling();
		plain.steer = grab.steer = 0.6f;
		steps(a, plain, 60);
		steps(b, grab, 60);
		assertEquals(a.getSpeed(), b.getSpeed(), 1e-4f);
		assertEquals(a.getHeading(), b.getHeading(), 1e-5f);
		assertEquals(a.getX(), b.getX(), 1e-3f);
		assertEquals(a.getY(), b.getY(), 1e-3f);
	}

	@Test
	public void aManualWinsOverTheRollingGrab()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.grabLeft = true;
		steps(p, in, 3);
		in.manualHeld = true;
		p.step(DT, in);
		assertEquals(SkaterState.MANUAL, p.getState());
		assertEquals(Trick.MANUAL, p.getActiveHold());
		assertNull(p.getGroundGrab());
	}

	@Test
	public void aPopLetsGoAndTheHeldKeyGrabsAgainInTheAirAndScores()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.grabLeft = true;
		in.grabAim = Aim.TOE;
		steps(p, in, 10);
		assertEquals(Trick.MUTE, p.getGroundGrab());
		assertTrue(p.drainTrickEvents().isEmpty());
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertNull(p.getGroundGrab());
		p.step(DT, in);
		assertEquals(Trick.MUTE, p.getActiveHold());
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(TrickEvent.trick(Trick.OLLIE, false), ev.get(0));
		assertEquals(TrickEvent.holdStart(Trick.MUTE), ev.get(1));
	}

	@Test
	public void landingWithTheKeyHeldReleasesTheAirGrabThenSettlesIntoTheRollingGrab()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.crouch = true;
		steps(p, in, 20);
		in.crouch = false;
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		p.drainTrickEvents();
		in.grabRight = true;
		in.grabAim = Aim.HEEL;
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		List<TrickEvent> ev = p.drainTrickEvents();
		// the air grab scores as always: held, tweaked, released at touchdown, landed
		assertEquals(TrickEvent.holdStart(Trick.STALEFISH), ev.get(0));
		assertEquals(TrickEvent.holdStart(Trick.TWEAKED_STALEFISH), ev.get(1));
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(2).type);
		assertEquals(TrickEvent.Type.LANDED, ev.get(3).type);
		assertEquals(4, ev.size());
		assertNull(p.getActiveHold());
		// the same grab carries on, on the ground, at once
		assertEquals(Trick.TWEAKED_STALEFISH, p.getGroundGrab());
		steps(p, in, 20);
		assertEquals(Trick.TWEAKED_STALEFISH, p.getGroundGrab());
		assertTrue(p.drainTrickEvents().isEmpty());
	}

	@Test
	public void landingIntoAManualWithTheKeyHeldIsAManual()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		in.grabLeft = true;
		in.manualHeld = true;
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.MANUAL, p.getState());
		assertNull(p.getGroundGrab());
	}

	@Test
	public void airGrabScoringIsUnchangedWhenTheKeyIsLetGoBeforeTouchdown()
	{
		SkateInput in = new SkateInput();
		SkatePhysics p = rolling();
		in.gestures.add(new Gesture(Direction.UP, false, 0f));
		p.step(DT, in);
		p.drainTrickEvents();
		in.grabRight = true;
		steps(p, in, 5);
		in.grabRight = false;
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		List<TrickEvent> ev = p.drainTrickEvents();
		assertEquals(TrickEvent.holdStart(Trick.MELON), ev.get(0));
		assertEquals(TrickEvent.Type.HOLD_END, ev.get(1).type);
		assertEquals(TrickEvent.Type.LANDED, ev.get(2).type);
		assertNull(p.getGroundGrab());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class SkatePhysicsRollingTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	static void run(SkatePhysics p, SkateInput in, float seconds)
	{
		int steps = Math.round(seconds / DT);
		for (int i = 0; i < steps; i++)
		{
			p.step(DT, in);
		}
	}

	@Test
	public void pushAddsImpulseAndMovesNorth()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		// the first push from rest is pushFromRest (360, stronger than the 240 pushImpulse), then one
		// step of friction and drag: (45 + 0.00012 * 360^2) * 0.02 = 1.21
		assertEquals(t.pushFromRest - (t.rollingFriction + t.drag * 360f * 360f) * DT, p.getSpeed(), 0.05f);
		assertTrue(p.drainEvents().contains(SkateEvent.PUSH));
		run(p, in, 1f);
		assertTrue(p.getY() > 50f);
		assertEquals(0f, p.getX(), 0.01f);
	}

	@Test
	public void pushHasCooldown()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		in.pushPressed = true;
		p.step(DT, in);
		// one push only: under the 360 first push (a second one would add ~200 more)
		assertTrue(p.getSpeed() < t.pushFromRest);
	}

	@Test
	public void pushingIsCappedAtMaxPushSpeed()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 20; i++)
		{
			in.pushPressed = true;
			run(p, in, 0.5f);
		}
		assertTrue(p.getSpeed() <= t.maxPushSpeed);
		// Air drag (0.00012 * v^2) now limits flat push speed below maxPushSpeed: a push every 0.5 s adds
		// max(60, 240 * (1 - s/1500)^0.5) and 0.5 s of friction + drag takes 0.5 * (45 + 0.00012 * s^2);
		// they balance at ~1280 just after a push, ~1166 at the end of each 0.5 s (simulated), so 0.75.
		assertTrue(p.getSpeed() > t.maxPushSpeed * 0.75f);
	}

	@Test
	public void holdingPushKeepsPushing()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		run(p, in, 2.0f);
		assertTrue(p.getSpeed() > 3 * t.pushImpulse);
		assertTrue(p.getSpeed() <= t.maxPushSpeed);
		int pushCount = 0;
		for (SkateEvent e : p.drainEvents())
		{
			if (e == SkateEvent.PUSH)
			{
				pushCount++;
			}
		}
		assertTrue(pushCount >= 3);
	}

	@Test
	public void holdingPushRespectsCooldown()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		run(p, in, t.pushCooldown * 0.9f);
		int pushCount = 0;
		for (SkateEvent e : p.drainEvents())
		{
			if (e == SkateEvent.PUSH)
			{
				pushCount++;
			}
		}
		assertEquals(1, pushCount);
	}

	@Test
	public void crouchingBlocksHeldPush()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		in.crouch = true;
		run(p, in, 1f);
		assertEquals(0f, p.getSpeed(), 0f);
		assertTrue(p.drainEvents().isEmpty());
	}

	@Test
	public void steerRightCarvesClockwise()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500);
		SkateInput in = new SkateInput();
		in.steer = 1f;
		run(p, in, 0.5f);
		assertTrue(p.getHeading() > 0.3f);
		assertTrue(p.getX() > 0f);
	}

	@Test
	public void powerslideWithSteerCarvesTightlyAndScrubsSpeed()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(800);
		SkateInput in = new SkateInput();
		in.powerslide = true;
		in.steer = 1f;
		// Shift + steer used to brake 900 u/s^2 and ignore the steer; it is now a tight carve (carve x2.2,
		// bleeding 200 + 0.3 v u/s^2), and Shift alone still brakes (SkatePhysicsTurnTest). Over 0.5 s from
		// 800 it bleeds ~(200 + 0.3 * 700 + 45 + 60) * 0.5 = 258 -> ~540, turning ~2 rad.
		run(p, in, 0.5f);
		assertTrue(p.getSpeed() < 600f && p.getSpeed() > 450f);
		assertTrue(p.getHeading() > 1.5f);
	}

	@Test
	public void rollsDownhillFromRest()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(0.2f), 0, 0, 0);
		run(p, new SkateInput(), 1f);
		// slope gravity is scaled: 2000 * 0.2 * slopeGravityScale 0.4 = 160, less friction 45 -> ~115
		// after 1 s (was 2000 * 0.2 - 45 = 355, asserted > 250)
		assertTrue(p.getSpeed() > 100f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void rollsBackwardsDownhillWhenFacingUphill()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(0.2f), 0, 0, Angles.PI);
		run(p, new SkateInput(), 1f);
		// see rollsDownhillFromRest: ~-115 after 1 s with the scaled slope gravity
		assertTrue(p.getSpeed() < -100f);
		assertTrue(p.getY() > 0f);
	}

	@Test
	public void slowIntoWallStops()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, 0);
		p.setRollingSpeed(500);
		run(p, new SkateInput(), 1f);
		assertTrue(p.getY() < 200f);
		assertEquals(0f, p.getSpeed(), 0f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void fastIntoWallBails()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, 0);
		// wallBailSpeed=1100 (speed * cos(incidence), head-on here so cos = 1); friction + drag trim the speed slightly before impact.
		// y(k) = dt*(v0*k - 0.45*k*(k+1)); with v0=1500, y(7) = 0.02*(1500*7 - 0.45*7*8) = 209.5 >= 200,
		// y(6) = 0.02*(9000 - 0.45*42) = 179.6 < 200, so the wall is hit on step 7 at
		// speed = 1500 - 0.9*7 = 1493.7 > 1300 -> bails with margin. Heading is due north (straight
		// into the wall), so both the x-only and y-only slide probes are blocked (dx=0 trivially,
		// dy crosses the wall) and it falls back to hitWall()/bail() as before.
		p.setRollingSpeed(1500);
		run(p, new SkateInput(), 0.5f);
		assertEquals(SkaterState.BAILED, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void headOnWallAt1400Bails()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, 0);
		// wallBailSpeed=1300; v0=1400, friction trims 0.9/step.
		// y(k) = dt*(v0*k - 0.45*k*(k+1)); y(8) = 0.02*(1400*8 - 0.45*72) = 223.3 >= 200,
		// y(7) = 0.02*(9800 - 0.45*56) = 195.5 < 200, so the wall is hit on step 8 at
		// speed = 1400 - 0.9*8 = 1392.8 > 1300 -> bails. Head-on (heading 0 == wall normal), so
		// neither the x-only nor y-only slide probe finds an escape and it bails as a direct hit.
		p.setRollingSpeed(1400);
		run(p, new SkateInput(), 0.5f);
		assertEquals(SkaterState.BAILED, p.getState());
		assertEquals(BailReason.WALL, p.getLastBailReason());
		assertTrue(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void glancingWallAt35DegreesSlidesWithoutBailing()
	{
		// Was 30 degrees: walls now bail only when speed * cos(incidence) > wallBailSpeed 1100 AND the
		// incidence is within wallBailAngleDeg 30 of head-on, so exactly 30 degrees at 1400 now bails (see
		// SkatePhysicsWallTest). At 35 degrees: 1400 * cos 35 = 1147 > 1100, but 35 > 30, so the skater
		// scrapes along the wall (x keeps advancing, y stays pinned below 200) instead of bailing.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, (float) Math.toRadians(35));
		p.setRollingSpeed(1400);
		run(p, new SkateInput(), 1f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getY() < 200f);
		assertTrue(p.getX() > 300f);
		assertFalse(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void fakieGlancingWallSlideStaysFakie()
	{
		// Rolling backwards (speed -300) with the heading 180 + 30 degrees: the actual motion is 30 degrees
		// east of north, into the wall at y=60. The slide runs east along the wall; the board's closer
		// axis heading is west (-90 degrees: |210 - 270| = 60 vs |210 - 90| = 120), so it must keep
		// rolling backwards towards the east instead of being flipped round to regular.
		// The board now eases along the wall at wallAlignRate 1.5 rad/s (was a 0.5 rad/step snap): contact
		// starts after 60 / (300 * cos 30) = 0.23 s and the 60 degrees (1.05 rad) take 0.7 s more, so this
		// runs 1.2 s (was 0.6). Speed: 300 * (1 - 0.25 * 0.866) = 235 at contact, minus at most
		// 0.7 * (400 * 0.866 + 45 + 7) = 278 of scrape (into falls to 0 as it aligns, so really ~150) -> fakie.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(60, 300), 0, 0, (float) Math.toRadians(210));
		p.setRollingSpeed(-300);
		float x0 = p.getX();
		run(p, new SkateInput(), 1.2f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getY() < 60f);
		assertTrue("slid east", p.getX() > x0 + 20f);
		assertTrue("still fakie: " + p.getSpeed(), p.getSpeed() < 0f);
		assertEquals(-Math.PI / 2, p.getHeading(), 1e-3);
	}

	@Test
	public void bigStepUpActsAsWall()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.stepAtY(200, 0, 100), 0, 0, 0);
		p.setRollingSpeed(500);
		run(p, new SkateInput(), 1f);
		assertTrue(p.getY() < 200f);
		assertEquals(0f, p.getH(), 0f);
	}

	@Test
	public void resetAfterBailOnlyWhenTimerExpired()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 0, 0);
		// wallBailSpeed=1300; wall at y=100, v0=1500. y(k) = dt*(v0*k - 0.45*k*(k+1));
		// y(4) = 0.02*(6000 - 0.45*20) = 119.8 >= 100, y(3) = 0.02*(4500 - 0.45*12) = 89.9 < 100,
		// so the wall is hit on step 4 at speed = 1500 - 0.9*4 = 1496.4 > 1300 -> bails.
		p.setRollingSpeed(1500);
		run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
		SkateInput in = new SkateInput();
		in.resetRequested = true;
		p.step(DT, in);
		assertEquals(SkaterState.BAILED, p.getState());
		run(p, new SkateInput(), t.bailDuration);
		in.resetRequested = true;
		p.step(DT, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(0f, p.getSpeed(), 0f);
	}

	@Test
	public void bailRecoversAutomatically()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 0, 0);
		// See resetAfterBailOnlyWhenTimerExpired for the step/speed math (v0=1500, wall at y=100).
		p.setRollingSpeed(1500);
		run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
		p.drainEvents();
		run(p, new SkateInput(), t.bailDuration + t.bailAutoReset + 0.1f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.RESET));
	}

	@Test
	public void resetPressedDuringBailIsRemembered()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 0, 0);
		// See resetAfterBailOnlyWhenTimerExpired for the step/speed math (v0=1500, wall at y=100).
		p.setRollingSpeed(1500);
		run(p, new SkateInput(), 0.2f);
		SkateInput in = new SkateInput();
		in.resetRequested = true;
		p.step(DT, in);
		assertEquals(SkaterState.BAILED, p.getState());
		// no further R presses: back on the board as soon as the bail finishes, before auto-recovery
		run(p, new SkateInput(), t.bailDuration + 0.05f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Shift-modified flicks: impossibles, hardflips, inward heelflips and bigspins. */
public class SkatePhysicsShiftTrickTest
{
	static final float DT = 0.02f;
	static final float TWO_PI = (float) (2 * Math.PI);
	static final float PI = (float) Math.PI;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	/** Crouches for 0.4 s (full charge: hang time 0.82 s) then pops with a Shift-held flick. */
	private static void chargedShiftPop(SkatePhysics p, SkateInput in, Direction d, boolean nollie)
	{
		in.crouch = true;
		for (int i = 0; i < 20; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(new Gesture(d, nollie, 0f, true));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
	}

	private static void steps(SkatePhysics p, SkateInput in, int n)
	{
		for (int i = 0; i < n; i++)
		{
			p.step(DT, in);
		}
	}

	private static List<TrickEvent> land(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return p.drainTrickEvents();
	}

	@Test
	public void anImpossibleWrapsTheBoardEndOverEnd()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.UP, false);
		steps(p, in, 5);
		assertTrue("nose comes up first", p.getBoardPitch() > 0.5f);
		steps(p, in, 16); // 0.42 s > 0.40 s
		assertEquals(TWO_PI, p.getBoardPitch(), 1e-4f);
		assertEquals(0f, p.getBoardRoll(), 1e-6f);
		assertEquals(0f, p.getBoardYawOffset(), 1e-6f);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.IMPOSSIBLE), TrickEvent.landed(true)), land(p, in));
		assertEquals(0f, p.getBoardPitch(), 1e-6f);
	}

	@Test
	public void aHardflipFlipsAndShovesFrontside()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.UP_LEFT, false);
		steps(p, in, 21);
		assertEquals(TWO_PI, p.getBoardRoll(), 1e-4f);
		assertEquals(-PI, p.getBoardYawOffset(), 1e-4f);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.HARDFLIP), TrickEvent.landed(true)), land(p, in));
	}

	@Test
	public void anInwardHeelflipFlipsAndShovesBackside()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.UP_RIGHT, false);
		steps(p, in, 21);
		assertEquals(-TWO_PI, p.getBoardRoll(), 1e-4f);
		assertEquals(PI, p.getBoardYawOffset(), 1e-4f);
	}

	@Test
	public void nollieShiftFlipsAreNollieHardflipsAndInwardHeels()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.DOWN_LEFT, true);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.NOLLIE_HARDFLIP), TrickEvent.landed(true)), land(p, in));

		SkatePhysics q = rolling(600);
		SkateInput in2 = new SkateInput();
		chargedShiftPop(q, in2, Direction.DOWN_RIGHT, true);
		assertEquals(TrickEvent.trick(Trick.NOLLIE_INWARD_HEELFLIP), land(q, in2).get(0));
	}

	@Test
	public void aBigspinTurnsTheBodyHalfwayWithTheBoardAndLandsFakieWithNoExtraSpinName()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.LEFT, false);
		steps(p, in, 24); // 0.48 s > 0.45 s
		// the body has turned 180 clockwise; the board a whole 360 in the world, i.e. 180 past the body
		assertEquals(PI, Math.abs(p.getHeading()), 1e-3f);
		assertEquals(PI, p.airSpin, 1e-3f);
		assertEquals(PI, p.getBoardYawOffset(), 1e-3f);
		List<TrickEvent> events = land(p, in);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("landed fakie", p.getSpeed() < 0f);
		// the body 180 is part of the bigspin: no "BS 180" on top
		assertEquals(TrickEvent.trick(Trick.BIGSPIN), events.get(0));
		assertEquals(TrickEvent.Type.LANDED, events.get(1).type);
		assertEquals(2, events.size());
	}

	@Test
	public void aFrontsideBigspinTurnsTheOtherWay()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.RIGHT, false);
		steps(p, in, 24);
		assertEquals(-PI, p.airSpin, 1e-3f);
		assertEquals(-PI, p.getBoardYawOffset(), 1e-3f);
		List<TrickEvent> events = land(p, in);
		assertEquals(TrickEvent.trick(Trick.FS_BIGSPIN), events.get(0));
		assertEquals(TrickEvent.Type.LANDED, events.get(1).type);
	}

	@Test
	public void boardYawDuringABigspinIsTheBoardsTurnLessTheBodys()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedShiftPop(p, in, Direction.LEFT, false);
		steps(p, in, 5);
		// world board yaw (heading + offset) is the whole eased 360 turn: offset = 2 pi e - pi e = pi e
		float e = p.airSpin / PI;
		assertTrue(e > 0.2f && e < 0.9f);
		assertEquals(PI * e, p.getBoardYawOffset(), 1e-3f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Air spins: the accumulated heading change from take-off to landing is named in half turns. */
public class SkatePhysicsSpinTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	/** Crouches for 0.4 s (full charge: vh 820, hang time 0.82 s) then pops with `g`. */
	private static void chargedPop(SkatePhysics p, SkateInput in, Gesture g)
	{
		in.crouch = true;
		for (int i = 0; i < 20; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(g);
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
	}

	/** Holds `steer` for `steps` air steps, then lets go and runs to touchdown; returns the trick events. */
	private static List<TrickEvent> spinAndLand(SkatePhysics p, SkateInput in, float steer, int steps)
	{
		in.steer = steer;
		for (int i = 0; i < steps; i++)
		{
			p.step(DT, in);
		}
		in.steer = 0f;
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		return p.drainTrickEvents();
	}

	private static List<TrickEvent.Type> types(List<TrickEvent> events)
	{
		List<TrickEvent.Type> out = new ArrayList<>();
		for (TrickEvent e : events)
		{
			out.add(e.type);
		}
		return out;
	}

	@Test
	public void aClockwiseHalfTurnLandsAsABackside180()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedPop(p, in, new Gesture(Direction.UP, false, 0f));
		// 0.4 s at 7 rad/s = 160 degrees, then the spin assist turns the last 20 onto travel + 180
		List<TrickEvent> events = spinAndLand(p, in, 1f, 20);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.spin(1)), events.subList(0, 2));
		assertEquals(TrickEvent.Type.LANDED, events.get(2).type);
		assertTrue(p.getSpeed() < 0f); // landed fakie
	}

	@Test
	public void aCounterClockwiseHalfTurnIsAFrontside180()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedPop(p, in, new Gesture(Direction.UP_LEFT, false, 0f));
		List<TrickEvent> events = spinAndLand(p, in, -1f, 20);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.KICKFLIP), TrickEvent.spin(-1)), events.subList(0, 2));
		assertEquals(TrickEvent.Type.LANDED, events.get(2).type);
	}

	@Test
	public void aSmallTurnAssistedBackIsNoSpin()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedPop(p, in, new Gesture(Direction.UP, false, 0f));
		// 0.15 s at 7 rad/s = 60 degrees, assisted back onto the travel
		List<TrickEvent> events = spinAndLand(p, in, 1f, 8);
		assertEquals(Arrays.asList(TrickEvent.Type.TRICK, TrickEvent.Type.LANDED), types(events));
	}

	@Test
	public void airSpinIsTheSignedHeadingChangeSinceTakeOff()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		chargedPop(p, in, new Gesture(Direction.UP, false, 0f));
		assertEquals(0f, p.airSpin, 1e-6f);
		in.steer = -1f;
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		// 10 steps of 7 * 0.02 = 0.14 rad, counter-clockwise
		assertEquals(-1.4f, p.airSpin, 1e-3f);
	}

	@Test
	public void aSpinHeldIntoTheTakeOffIsNotCountedUntilRepressed()
	{
		SkatePhysics p = rolling(600);
		SkateInput in = new SkateInput();
		in.steer = 1f; // carving into the pop
		chargedPop(p, in, new Gesture(Direction.UP, false, 0f));
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		assertEquals(0f, p.airSpin, 1e-6f);
	}

	@Test
	public void aRollOffWithASpinIsATrick()
	{
		// rolling south off a 300-high platform: sqrt(2 * 300 / 2000) = 0.55 s of fall, enough for a 180
		SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(10f, 300f), 0, 20, (float) Math.PI);
		p.setRollingSpeed(600);
		SkateInput in = new SkateInput();
		for (int i = 0; i < 20 && p.getState() != SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		List<TrickEvent> events = spinAndLand(p, in, 1f, 20);
		assertFalse(events.isEmpty());
		assertEquals(TrickEvent.spin(1), events.get(0));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.world.GridCollisionWorld;
import com.gielinorskate.world.WorldTests;
import java.util.List;
import java.util.Random;
import org.junit.Test;

/**
 * Flat ground and moderate hills (nothing that blocks or rolls off) must ride bit for bit as they did before
 * the steep-terrain additions (ramp launch, momentum climbs, drop-ins). Each trace hashes every step's raw
 * float bits; the expected hashes were recorded on the code before those additions.
 */
public class SkatePhysicsSteepRegressionTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();
	/** Fastest speed reached by the last trace: the ramp-launch and climb speed gates must be in play. */
	static float topSpeed;

	/** Pushes, carves left and right, pops, grabs and coasts for {@code steps} steps, hashing every step. */
	static long trace(SkatePhysics p, int steps)
	{
		SkateInput in = new SkateInput();
		long hash = 17;
		topSpeed = 0f;
		for (int i = 0; i < steps; i++)
		{
			in.pushHeld = (i / 150) % 2 == 0;
			in.pushPressed = in.pushHeld && i % 20 == 0;
			in.steer = (float) Math.sin(i * 0.013);
			if (Math.abs(in.steer) < 0.3f || p.getState() != SkaterState.ROLLING)
			{
				in.steer = 0f;
			}
			if (i % 90 == 45)
			{
				in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
			}
			in.grabLeft = i % 90 > 50 && i % 90 < 60;
			p.step(DT, in);
			topSpeed = Math.max(topSpeed, Math.abs(p.getSpeed()));
			hash = mix(hash, p.getX());
			hash = mix(hash, p.getY());
			hash = mix(hash, p.getH());
			hash = mix(hash, p.getSpeed());
			hash = mix(hash, p.getHeading());
			hash = mix(hash, p.getVerticalVelocity());
			hash = hash * 31 + p.getState().ordinal();
			List<SkateEvent> ev = p.drainEvents();
			assertFalse("step " + i, ev.contains(SkateEvent.ROLL_OFF));
			assertFalse("step " + i, ev.contains(SkateEvent.BAIL));
			for (SkateEvent e : ev)
			{
				hash = hash * 31 + e.ordinal();
			}
			p.drainTrickEvents();
		}
		return hash;
	}

	private static long mix(long hash, float v)
	{
		return hash * 1_000_003L + Float.floatToIntBits(v);
	}

	private static CollisionWorld rollingHills()
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return terrainHeight(x, y);
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return 80f * (float) Math.sin(x / 350f) + 60f * (float) Math.cos(y / 280f);
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return Float.NEGATIVE_INFINITY;
			}
		};
	}

	private static GridCollisionWorld gentleGrid()
	{
		GridCollisionWorld w = new GridCollisionWorld(200);
		Random r = new Random(11);
		for (int cx = 0; cx <= 200; cx++)
		{
			for (int cy = 0; cy <= 200; cy++)
			{
				WorldTests.setCornerHeight(w, cx, cy, 40f * (float) Math.sin(cx * 0.4) + (float) r.nextGaussian() * 6f);
			}
		}
		return w;
	}

	@Test
	public void flatTraceUnchanged()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		assertEquals(1153949014361533376L, trace(p, 1200));
		assertTrue("top speed " + topSpeed, topSpeed > 1000f);
	}

	@Test
	public void rollingHillsTraceUnchanged()
	{
		SkatePhysics p = new SkatePhysics(t, rollingHills(), 0, 0, 0.3f);
		assertEquals(7113641921327721744L, trace(p, 1500));
		assertTrue("top speed " + topSpeed, topSpeed > 1000f);
	}

	@Test
	public void gentleGridTraceUnchanged()
	{
		SkatePhysics p = new SkatePhysics(t, gentleGrid(), 100 * 128, 100 * 128, 0.1f);
		assertEquals(6769500491294778404L, trace(p, 1200));
		assertTrue("top speed " + topSpeed, topSpeed > 1000f);
	}

	@Test
	public void bumpyDownhillTraceUnchanged()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.bumpyDownhillNorth(0.15f, 6f, 30f), 0, 0, 0);
		assertEquals(-2908321794293859373L, trace(p, 900));
		assertTrue("top speed " + topSpeed, topSpeed > 1000f);
	}

	@Test
	public void steadyUphillTraceUnchanged()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(-0.4f), 0, 0, 0);
		assertEquals(-799882887334767439L, trace(p, 900));
		assertTrue("top speed " + topSpeed, topSpeed > 700f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Trick;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** Steep terrain: ramp launches off crests, momentum climbs up steep terrain rises, drop-ins down steep slopes. */
public class SkatePhysicsSteepTerrainTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	interface Height
	{
		float at(float y);
	}

	/** Terrain varying northwards only, no blockers, with an optional loaded-area edge at y = edgeY. */
	static CollisionWorld world(Height terrain, float blockerTop, float edgeY)
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return terrain.at(y);
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return terrain.at(y);
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return y1 >= 200f && y0 < 200f ? blockerTop : Float.NEGATIVE_INFINITY;
			}

			@Override
			public float edgeDistance(float x, float y)
			{
				return edgeY - y;
			}
		};
	}

	static CollisionWorld world(Height terrain)
	{
		return world(terrain, Float.NEGATIVE_INFINITY, Float.POSITIVE_INFINITY);
	}

	/** Uphill at {@code grade} up to the crest at y = 400 (a 3-tile run-up), then {@code after} per unit beyond it. */
	static CollisionWorld crest(float grade, float after)
	{
		return world(y -> y < 400f ? grade * y : grade * 400f + after * (y - 400f));
	}

	/** Flat, then a terrain rise of {@code gradient} per unit from y = 200 up to {@code top}, flat again above. */
	static Height rise(float gradient, float top)
	{
		return y -> y < 200f ? 0f : Math.min(top, gradient * (y - 200f));
	}

	/** Flat at 0, then a terrain fall of {@code gradient} per unit from y = 200 down to {@code -depth}. */
	static CollisionWorld fall(float gradient, float depth)
	{
		return world(y -> y < 200f ? 0f : -Math.min(depth, gradient * (y - 200f)));
	}

	private static List<SkateEvent> ride(SkatePhysics p, int steps, SkaterState mustStay)
	{
		List<SkateEvent> events = new ArrayList<>();
		for (int i = 0; i < steps; i++)
		{
			p.step(DT, new SkateInput());
			if (mustStay != null)
			{
				assertEquals("step " + i, mustStay, p.getState());
			}
			events.addAll(p.drainEvents());
		}
		return events;
	}

	// ---- ramp launch ----

	@Test
	public void fastOverACrestLaunches()
	{
		// grade 0.45 then flat: the slope ahead drops by 0.45 >= 0.35
		SkatePhysics p = new SkatePhysics(t, crest(0.45f, 0f), 0, 0, 0);
		p.setRollingSpeed(1300f);
		float launchSpeed = 0f;
		for (int i = 0; i < 40 && p.getState() == SkaterState.ROLLING; i++)
		{
			launchSpeed = p.getSpeed();
			p.step(DT, new SkateInput());
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertTrue(p.drainEvents().contains(SkateEvent.ROLL_OFF));
		// vh = speed * approach slope at take-off (one step of gravity at most since)
		assertEquals(launchSpeed * 0.45f, p.getVerticalVelocity(), 0.02f * t.gravity + 20f);
		assertTrue("left near the crest " + p.getY(), p.getY() > 360f && p.getY() < 440f);
		// a plain launch has no landing grade, like a roll-off
		List<SkateEvent> ev = ride(p, 100, null);
		assertFalse(ev.contains(SkateEvent.BAIL));
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(null, p.lastLandingQuality);
		assertTrue("flew past the crest " + p.getY(), p.getY() > 500f);
	}

	@Test
	public void aLaunchIsANormalAirForGrabs()
	{
		SkatePhysics p = new SkatePhysics(t, crest(0.45f, 0f), 0, 0, 0);
		p.setRollingSpeed(1300f);
		while (p.getState() == SkaterState.ROLLING && p.getY() < 500f)
		{
			p.step(DT, new SkateInput());
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		SkateInput grab = new SkateInput();
		grab.grabLeft = true;
		p.step(DT, grab);
		p.step(DT, grab);
		assertEquals(Trick.INDY, p.getActiveHold());
		ride(p, 100, null);
		assertEquals(SkaterState.ROLLING, p.getState());
		// a grabbed launch lands with a grade, like any trick
		assertTrue(p.lastLandingQuality != null);
	}

	@Test
	public void launchKeepsTheHorizontalSpeed()
	{
		SkatePhysics p = new SkatePhysics(t, crest(0.45f, -0.2f), 0, 0, 0);
		p.setRollingSpeed(1300f);
		float before = 0f;
		while (p.getState() == SkaterState.ROLLING && p.getY() < 500f)
		{
			before = p.getSpeed();
			p.step(DT, new SkateInput());
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(before, p.getSpeed(), 15f);
	}

	@Test
	public void aFlatPlatformOverACrestNeverLaunches()
	{
		// riding a flat platform top at 500 whose terrain underneath climbs at 0.45 to a crest at y = 400
		CollisionWorld w = new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return 500f;
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return y < 400f ? 0.45f * y : 0.45f * 400f;
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return Float.NEGATIVE_INFINITY;
			}

			@Override
			public float edgeDistance(float x, float y)
			{
				return Float.POSITIVE_INFINITY;
			}
		};
		SkatePhysics p = new SkatePhysics(t, w, 0, 0, 0);
		p.setRollingSpeed(1300f);
		List<SkateEvent> ev = ride(p, 40, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
		assertTrue("rolled past the crest " + p.getY(), p.getY() > 440f);
	}

	@Test
	public void aResetStartsANewRunUp()
	{
		SkatePhysics p = new SkatePhysics(t, crest(0.45f, 0f), 0, 0, 0);
		p.setRollingSpeed(1300f);
		while (p.getY() < 300f)
		{
			p.step(DT, new SkateInput());
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		// R while (nearly) stopped, 100 short of the crest: the run-up so far does not count any more
		p.setRollingSpeed(0f);
		SkateInput reset = new SkateInput();
		reset.resetRequested = true;
		p.step(DT, reset);
		assertTrue(p.drainEvents().contains(SkateEvent.RESET));
		p.setRollingSpeed(1300f);
		List<SkateEvent> ev = ride(p, 15, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
		assertTrue("rolled over the crest " + p.getY(), p.getY() > 420f);
	}

	@Test
	public void slowOverACrestStaysDown()
	{
		// 60 % of maxPushSpeed 1500 is 900
		SkatePhysics p = new SkatePhysics(t, crest(0.45f, 0f), 0, 0, 0);
		p.setRollingSpeed(850f);
		List<SkateEvent> ev = ride(p, 50, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
		assertTrue(p.getY() > 440f);
	}

	@Test
	public void aShortSteepBumpIsNotARamp()
	{
		// one tile of 0.45 uphill (less than the 256 run-up) then flat: rough ground, not a ramp
		CollisionWorld bump = world(y -> y < 300f ? 0f : 0.45f * (Math.min(y, 428f) - 300f));
		SkatePhysics p = new SkatePhysics(t, bump, 0, 0, 0);
		p.setRollingSpeed(1500f);
		List<SkateEvent> ev = ride(p, 40, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
		assertTrue(p.getY() > 500f);
	}

	@Test
	public void gentleCrestStaysDown()
	{
		// grade 0.3 then flat: a drop of 0.3 < 0.35
		SkatePhysics p = new SkatePhysics(t, crest(0.3f, 0f), 0, 0, 0);
		p.setRollingSpeed(1500f);
		List<SkateEvent> ev = ride(p, 40, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
	}

	@Test
	public void fastOnFlatOrDownhillOverABreakStaysDown()
	{
		// flat ground, and downhill steepening (not an uphill crest), never launch
		for (CollisionWorld w : new CollisionWorld[]{TestWorlds.flat(), crest(-0.1f, -0.6f)})
		{
			SkatePhysics p = new SkatePhysics(t, w, 0, 0, 0);
			p.setRollingSpeed(1500f);
			List<SkateEvent> ev = ride(p, 40, SkaterState.ROLLING);
			assertFalse(ev.contains(SkateEvent.ROLL_OFF));
		}
	}

	@Test
	public void launchScalesWithThePushSpeedSetting()
	{
		// at 150 % push speed the gate is 0.6 * 2250 = 1350: 1300 no longer launches
		SkatePhysics p = new SkatePhysics(t.scaled(1.5f, 1f), crest(0.45f, 0f), 0, 0, 0);
		p.setRollingSpeed(1300f);
		List<SkateEvent> ev = ride(p, 30, SkaterState.ROLLING);
		assertFalse(ev.contains(SkateEvent.ROLL_OFF));
	}

	// ---- momentum climbs ----

	@Test
	public void fastClimbsASteepTerrainRise()
	{
		// gradient 4: 8-unit substeps rise 32 > maxStepUp 24, a wall today; 1600 >= 40 * 32 = 1280 climbs it
		SkatePhysics p = new SkatePhysics(t, world(rise(4f, 120f)), 0, 0, 0);
		p.setRollingSpeed(1600f);
		ride(p, 20, SkaterState.ROLLING);
		assertEquals(120f, p.getH(), 0f);
		assertTrue(p.getY() > 300f);
		// the climb costs speed as gravity on the rise: well below a flat ride's ~1590 after 0.4 s
		SkatePhysics flat = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		flat.setRollingSpeed(1600f);
		ride(flat, 20, null);
		assertTrue("speed " + p.getSpeed() + " vs " + flat.getSpeed(), p.getSpeed() < flat.getSpeed() - 100f);
		assertEquals(0f, p.getHeading(), 0f);
	}

	@Test
	public void slowIsStillBlockedBySteepTerrain()
	{
		// 1000: 6.67-unit substeps rise 26.7 > 24 (blocked today) and 1000 < 40 * 26.7 = 1067
		SkatePhysics p = new SkatePhysics(t, world(rise(4f, 120f)), 0, 0, 0);
		p.setRollingSpeed(1000f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertTrue("h " + p.getH(), p.getH() < 30f);
		assertTrue("y " + p.getY(), p.getY() < 210f);
	}

	@Test
	public void blockersAreNeverClimbable()
	{
		// the same rise with a tall blocker across its foot
		SkatePhysics p = new SkatePhysics(t, world(rise(4f, 120f), 400f, Float.POSITIVE_INFINITY), 0, 0, 0);
		p.setRollingSpeed(2500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertTrue("y " + p.getY(), p.getY() < 200f);
		assertEquals(0f, p.getH(), 0f);
	}

	@Test
	public void platformsAreNeverClimbable()
	{
		// a 60 platform edge is ground, not terrain
		SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(200, 60), 0, 0, 0);
		p.setRollingSpeed(2500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertTrue("y " + p.getY(), p.getY() < 200f);
		assertEquals(0f, p.getH(), 0f);
	}

	@Test
	public void theSceneEdgeIsNeverClimbable()
	{
		// past the loaded area (edgeDistance < 0) the rise stays a wall, as do +INF out-of-bounds heights
		CollisionWorld edge = world(rise(4f, 120f), Float.NEGATIVE_INFINITY, 205f);
		CollisionWorld infinite = world(y -> y < 200f ? 0f : Float.POSITIVE_INFINITY);
		for (CollisionWorld w : new CollisionWorld[]{edge, infinite})
		{
			SkatePhysics p = new SkatePhysics(t, w, 0, 0, 0);
			p.setRollingSpeed(2500f);
			SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
			assertTrue("y " + p.getY(), p.getY() < 206f);
			assertTrue("h " + p.getH(), p.getH() < 25f);
		}
	}

	// ---- drop-ins ----

	@Test
	public void dropInHugsASteepTerrainSlope()
	{
		// gradient 3.5: 8-unit substeps drop 28 > rollOffDrop 24, a roll-off today
		SkatePhysics p = new SkatePhysics(t, fall(3.5f, 140f), 0, 0, 0);
		p.setRollingSpeed(1200f);
		for (int i = 0; i < 30; i++)
		{
			p.step(DT, new SkateInput());
			assertEquals("step " + i, SkaterState.ROLLING, p.getState());
			assertEquals(-Math.min(140f, Math.max(0f, 3.5f * (p.getY() - 200f))), p.getH(), 0.01f);
		}
		assertFalse(p.drainEvents().contains(SkateEvent.ROLL_OFF));
		assertTrue(p.getY() > 300f);
	}

	@Test
	public void tooSteepATerrainDropStillRollsOff()
	{
		// gradient 6 is past dropInMaxGradient: rolls off as today
		SkatePhysics p = new SkatePhysics(t, fall(6f, 140f), 0, 0, 0);
		p.setRollingSpeed(1200f);
		List<SkateEvent> ev = ride(p, 20, null);
		assertTrue(ev.contains(SkateEvent.ROLL_OFF));
	}

	@Test
	public void ledgesStillRollOff()
	{
		// a terrain step (vertical) and a platform edge are ledges
		SkatePhysics step = new SkatePhysics(t, TestWorlds.stepAtY(200, 0, -100), 0, 0, 0);
		step.setRollingSpeed(1200f);
		assertTrue(ride(step, 20, null).contains(SkateEvent.ROLL_OFF));
		SkatePhysics ledge = new SkatePhysics(t, TestWorlds.platformAtY(200, 60), 0, 300, Angles.PI);
		ledge.setRollingSpeed(1200f);
		assertTrue(ride(ledge, 20, null).contains(SkateEvent.ROLL_OFF));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.world.GridCollisionWorld;
import com.gielinorskate.world.WorldTests;
import java.util.List;
import java.util.Random;
import org.junit.Test;

/** Hills, bumps, curbs and pushing: the riding-feel review's terrain scenarios. */
public class SkatePhysicsTerrainTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static float drag(SkateTuning t, float v)
	{
		return t.rollingFriction + t.drag * v * v;
	}

	@Test
	public void slopeGravityIsScaledDown()
	{
		// grade 0.2: 2000 * 0.2 * 0.4 = 160 u/s^2 down the hill, less friction 45 and drag
		// (0.00012 * 115^2 = 1.6 at most): about 115 after 1 s (was 2000 * 0.2 - 45 = 355)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(0.2f), 0, 0, 0);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertEquals(114.5f, p.getSpeed(), 1f);
	}

	@Test
	public void slopeIsClampedBeforeScaling()
	{
		// grade 2 is clamped to 0.6: 2000 * 0.6 * 0.4 = 480, less friction 45 -> 435 u/s^2,
		// so about 217 after 0.5 s (drag at most 0.00012 * 217^2 = 5.7 u/s^2)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(2f), 0, 0, 0);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.5f);
		assertEquals(216f, p.getSpeed(), 2f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void steepUphillHoldingPushNeverRollsBack()
	{
		// 80 per tile uphill (0.625, clamped 0.6): 480 + 45 = 525 u/s^2 against the skater. Pushes every
		// 0.4 s: 360 from rest, then 240 * (1 - s/1500)^0.5. The pushes balance the 0.4 * 525 = 210 lost
		// per cycle at s = 1500 * (1 - (210/240)^2) = 352, so the speed saw-tooths between ~350 and ~560.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(-80f / 128f), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		float min = Float.MAX_VALUE;
		for (int i = 0; i < 150; i++)
		{
			p.step(DT, in);
			min = Math.min(min, p.getSpeed());
		}
		assertTrue("min " + min, min >= 0f);
		assertTrue("end " + p.getSpeed(), p.getSpeed() > 300f);
		assertFalse(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void firstPushFromRestIsStronger()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		assertEquals(t.pushFromRest - drag(t, 360f) * DT, p.getSpeed(), 0.05f);
	}

	@Test
	public void pushImpulseTapersWithSpeed()
	{
		// at 1000: 240 * (1 - 1000/1500)^0.5 = 138.56 -> 1138.56, then friction + drag for one step:
		// (45 + 0.00012 * 1138.56^2) * 0.02 = 4.01
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(1000f);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		assertEquals(1138.56f - drag(t, 1138.56f) * DT, p.getSpeed(), 0.05f);
	}

	@Test
	public void pushNearMaxPushSpeedStillGivesTheMinimum()
	{
		// at 1450: 240 * (50/1500)^0.5 = 43.8 < the 60 minimum, capped at maxPushSpeed 1500
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(1450f);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		assertEquals(1500f - drag(t, 1500f) * DT, p.getSpeed(), 0.05f);
	}

	@Test
	public void pushWhileRollingBackSlowlyPushesForward()
	{
		// stalled and rolling back at 200 (not a fakie landing): max(60, -200 + 360) = 160 forward
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(-200f);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		assertEquals(160f - drag(t, 160f) * DT, p.getSpeed(), 0.05f);
	}

	@Test
	public void pushAfterAFakieLandingPushesFakie()
	{
		// half spin at 300: 7 rad/s * 0.44 s = 176.5 deg, lands fakie at about -300 (above -400)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(300f);
		SkatePhysicsAirTest.ollie(p, 0.4f, 1f, 0.44f);
		assertEquals(SkaterState.ROLLING, p.getState());
		float landed = p.getSpeed();
		assertTrue("landed fakie " + landed, landed < -200f && landed > -400f);
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		p.step(DT, in);
		assertTrue("pushed fakie " + p.getSpeed(), p.getSpeed() < landed - 100f);
	}

	@Test
	public void coastingFastIsSlowedByAirDrag()
	{
		// (45 + 0.00006 * 2000^2) * 0.02 = 5.7 in one step
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(2000f);
		p.step(DT, new SkateInput());
		assertEquals(1994.3f, p.getSpeed(), 0.05f);
	}

	@Test
	public void popOnAnUphillAddsTheGroundsVerticalSpeed()
	{
		// grade 0.25 uphill at 800: the pop step first loses (200 + 45 + 0.00006 * 800^2) * 0.02 = 5.67
		// -> 794.33; vh = 0.92 * 820 + 794.33 * 0.25 = 952.98 (minPopFraction 0.85 -> 0.92). The next step:
		// vh -= 40, h += 912.98 * 0.02 = 18.26
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(-0.25f), 0, 0, 0);
		p.setRollingSpeed(800f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		float h0 = p.getH();
		p.step(DT, in);
		assertEquals(18.26f, p.getH() - h0, 0.05f);
	}

	@Test
	public void steepUphillAtSpeedDoesNotBail()
	{
		// 110 per tile = 0.86: a whole 0.02 s step at 1500 used to rise 26 > maxStepUp 24 and hit a "wall"
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(-110f / 128f), 0, 0, 0);
		p.setRollingSpeed(1500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue(p.getSpeed() > 500f);
		assertEquals(0f, p.getHeading(), 0f);
	}

	@Test
	public void steepDownhillAtSpeedStaysGlued()
	{
		// 80 per tile down from 1500 used to reach ~1930 and roll off (a 0.02 s step dropping > 24)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.downhillNorth(80f / 128f), 0, 0, 0);
		p.setRollingSpeed(1500f);
		for (int i = 0; i < 150; i++)
		{
			p.step(DT, new SkateInput());
			assertEquals(SkaterState.ROLLING, p.getState());
			assertEquals(-80f / 128f * p.getY(), p.getH(), 0.01f);
		}
		assertFalse(p.drainEvents().contains(SkateEvent.ROLL_OFF));
	}

	@Test
	public void roughTerrainGivesNoHopsBailsOrTurns()
	{
		for (float sigma : new float[]{35f, 50f})
		{
			for (float speed : new float[]{1500f, 2000f})
			{
				GridCollisionWorld w = new GridCollisionWorld(40);
				Random r = new Random(7);
				for (int cx = 0; cx <= 40; cx++)
				{
					for (int cy = 0; cy <= 40; cy++)
					{
						WorldTests.setCornerHeight(w, cx, cy, (float) r.nextGaussian() * sigma);
					}
				}
				SkatePhysics p = new SkatePhysics(t, w, 20 * 128 + 40, 4 * 128 + 20, 0);
				p.setRollingSpeed(speed);
				for (int i = 0; i < 60; i++)
				{
					p.step(DT, new SkateInput());
					assertEquals("sigma " + sigma + " at " + speed, SkaterState.ROLLING, p.getState());
				}
				List<SkateEvent> ev = p.drainEvents();
				assertFalse(ev.contains(SkateEvent.ROLL_OFF));
				assertFalse(ev.contains(SkateEvent.LAND));
				assertFalse(ev.contains(SkateEvent.BAIL));
				assertEquals(0f, p.getHeading(), 0f);
			}
		}
	}

	@Test
	public void sixtyUnitPlatformStillBlocks()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(200, 60), 0, 0, 0);
		p.setRollingSpeed(500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertTrue(p.getY() < 200f);
		assertEquals(0f, p.getH(), 0f);
	}

	@Test
	public void sixtyUnitPlatformStillRollsOff()
	{
		// on the platform (y >= 200 is 60 high) heading south off its edge
		SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(200, 60), 0, 300, Angles.PI);
		p.setRollingSpeed(500f);
		boolean airborne = false;
		for (int i = 0; i < 100; i++)
		{
			p.step(DT, new SkateInput());
			airborne |= p.getState() == SkaterState.AIRBORNE;
		}
		assertTrue(airborne);
		assertTrue(p.drainEvents().contains(SkateEvent.ROLL_OFF));
		assertEquals(0f, p.getH(), 0f);
	}

	@Test
	public void twentyUnitCurbRollsUp()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(200, 20), 0, 0, 0);
		p.setRollingSpeed(500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 1f);
		assertTrue(p.getY() > 300f);
		assertEquals(20f, p.getH(), 0f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void stoppedNextToACurbOrPlatformStaysStill()
	{
		for (float top : new float[]{20f, 60f})
		{
			// the slope sampler (+-16 along the heading) straddles the edge both facing it and facing away
			for (float heading : new float[]{0f, Angles.PI})
			{
				SkatePhysics p = new SkatePhysics(t, TestWorlds.platformAtY(200, top), 0, 190, heading);
				SkatePhysicsRollingTest.run(p, new SkateInput(), 2f);
				assertEquals("top " + top + " heading " + heading, 0f, p.getSpeed(), 0f);
				assertEquals(190f, p.getY(), 0f);
			}
		}
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.tricks.Gesture.Direction;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class SkatePhysicsTrickTest
{
	static final float DT = 0.02f;
	static final float TWO_PI = (float) (2 * Math.PI);
	final SkateTuning t = new SkateTuning();

	static Gesture flick(Direction d)
	{
		return new Gesture(d, false, 0f);
	}

	private SkatePhysics rolling(float speed)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		return p;
	}

	/** Crouches for 0.4 s (full charge: vh 820, hang time 2*820/2000 = 0.82 s) then pops with `g`. */
	private static void chargedPop(SkatePhysics p, SkateInput in, Gesture g)
	{
		in.crouch = true;
		for (int i = 0; i < 20; i++)
		{
			p.step(DT, in);
		}
		in.crouch = false;
		in.gestures.add(g);
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
	}

	private static void stepUntilGrounded(SkatePhysics p, SkateInput in)
	{
		for (int i = 0; i < 500 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
	}

	@Test
	public void kickflipGestureInTheAirCompletesAndLands()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP));
		in.gestures.add(flick(Direction.UP_LEFT));
		p.step(DT, in);
		stepUntilGrounded(p, in);

		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.OLLIE), TrickEvent.trick(Trick.KICKFLIP), TrickEvent.landed(true)),
			p.drainTrickEvents());
		assertEquals(0f, p.getBoardRoll(), 1e-6f);
	}

	@Test
	public void flipGestureWhileRollingPopsAndFlips()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_LEFT));
		assertTrue(p.drainEvents().contains(SkateEvent.POP));
		stepUntilGrounded(p, in);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.KICKFLIP), TrickEvent.landed(true)), p.drainTrickEvents());
	}

	@Test
	public void nollieGesturePopsLikeAnOllie()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, new Gesture(Direction.DOWN, true, 0f));
		stepUntilGrounded(p, in);
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.NOLLIE), TrickEvent.landed(true)), p.drainTrickEvents());
	}

	@Test
	public void reflickUpgradesToDoubleKickflip()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_LEFT));
		p.step(DT, in);
		in.gestures.add(flick(Direction.UP_LEFT));
		p.step(DT, in);
		stepUntilGrounded(p, in);

		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.KICKFLIP),
			TrickEvent.upgrade(Trick.DOUBLE_KICKFLIP, Trick.KICKFLIP), TrickEvent.landed(true)), p.drainTrickEvents());
	}

	@Test
	public void reflickingADoubleUpgradesToATripleThatLands()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_RIGHT));
		p.step(DT, in);
		in.gestures.add(flick(Direction.UP_RIGHT));
		p.step(DT, in);
		p.step(DT, in);
		float rollBefore = p.getBoardRoll();
		in.gestures.add(flick(Direction.UP_RIGHT));
		p.step(DT, in);
		// the roll carries on from where the double was (no jump back), in the heelflip direction
		assertTrue(p.getBoardRoll() < rollBefore);
		assertTrue(rollBefore - p.getBoardRoll() < 1.5f);
		// after the full 0.65 s the board has turned three times
		for (int i = 0; i < 33; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(-3 * TWO_PI, p.getBoardRoll(), 1e-4f);
		stepUntilGrounded(p, in);

		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(Arrays.asList(TrickEvent.trick(Trick.HEELFLIP),
			TrickEvent.upgrade(Trick.DOUBLE_HEELFLIP, Trick.HEELFLIP),
			TrickEvent.upgrade(Trick.TRIPLE_HEELFLIP, Trick.DOUBLE_HEELFLIP), TrickEvent.landed(true)),
			p.drainTrickEvents());
	}

	@Test
	public void boardRollAfterAFullKickflipIsTwoPi()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_LEFT));
		for (int i = 0; i < 20; i++) // 0.4 s > 0.35 s duration, < 0.82 s hang time
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.AIRBORNE, p.getState());
		assertEquals(TWO_PI, p.getBoardRoll(), 1e-4f);
		assertEquals(0f, p.getBoardYawOffset(), 1e-6f);
	}

	@Test
	public void popShoveItSpinsTheBoardHalfATurn()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.LEFT));
		// duration 0.30 s; 0.32 s later the half turn is complete
		for (int i = 0; i < 16; i++) // 0.32 s
		{
			p.step(DT, in);
		}
		assertEquals((float) Math.PI, p.getBoardYawOffset(), 1e-4f);
		assertEquals(0f, p.getBoardRoll(), 1e-6f);
	}

	@Test
	public void flipRollIsEasedOut()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_LEFT));
		// re-flick on the first air step upgrades to the 0.5 s double kickflip; the upgrade rescales
		// flipTime so the roll carries over continuously (see rescaleFlipTime), so the expected curve
		// here is computed the same way: match the KICKFLIP roll at flipTime 0.02 onto the
		// DOUBLE_KICKFLIP curve by inverting the ease-out as the production code does, then run the
		// eased curve forward another 0.22 s.
		float oldEased = eased(0.02f / 0.35f);
		float targetRoll = 1f * TWO_PI * oldEased;
		float tPrime = rescale(2f, 0.5f, targetRoll);
		in.gestures.add(flick(Direction.UP_LEFT));
		p.step(DT, in); // flipTime 0.02 before upgrade, rescaled to tPrime after
		for (int i = 0; i < 11; i++) // 0.22 s further
		{
			p.step(DT, in);
		}
		float finalEased = eased((tPrime + 0.22f) / 0.5f);
		assertEquals(2 * TWO_PI * finalEased, p.getBoardRoll(), 1e-3f);
	}

	@Test
	public void reflickUpgradeKeepsRollContinuous()
	{
		SkatePhysics p = rolling(500);
		SkateInput in = new SkateInput();
		chargedPop(p, in, flick(Direction.UP_LEFT));
		// run the kickflip close to completion (0.3 of its 0.35 s) before upgrading, where the old
		// (buggy) behaviour of keeping flipTime literally would jump the roll by over 2 radians
		for (int i = 0; i < 15; i++)
		{
			p.step(DT, in);
		}
		float rollBefore = p.getBoardRoll();
		in.gestures.add(flick(Direction.UP_LEFT));
		p.step(DT, in);
		float rollAfter = p.getBoardRoll();
		assertTrue(Math.abs(rollAfter - rollBefore) < 0.3f);
	}

	/** Ease-out 1 - (1 - u)^2: fast off the flick, gentle into the catch. */
	private static float eased(float u)
	{
		u = Math.max(0f, Math.min(1f, u));
		return 1f - (1f - u) * (1f - u);
	}

	/** Mirrors SkatePhysics' upgrade rescale: the time on the new flip whose eased roll is targetRoll. */
	private static float rescale(float rollTurns, float duration, float targetRoll)
	{
		float targetEased = Math.max(0f, Math.min(1f, targetRoll / (rollTurns * TWO_PI)));
		return (1f - (float) Math.sqrt(1f - targetEased)) * duration;
	}

