package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import org.junit.Test;

/** Shift turns, standstill pivots, air steering held through the pop and landing blends. */
public class SkatePhysicsTurnTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	/** Result of a hold-A turn until the board has turned 180 degrees. */
	private static final class Turn
	{
		float seconds;
		float radius;
		float exitSpeed;
	}

	private Turn turnAround(float speed, boolean shift)
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(speed);
		SkateInput in = new SkateInput();
		in.steer = -1f;
		in.powerslide = shift;
		float turned = 0f;
		float maxSide = 0f;
		int steps = 0;
		while (turned < Angles.PI && steps < 500)
		{
			float before = p.getHeading();
			p.step(DT, in);
			turned += Angles.absDiff(before, p.getHeading());
			maxSide = Math.max(maxSide, Math.abs(p.getX()));
			steps++;
		}
		Turn r = new Turn();
		r.seconds = steps * DT;
		// turning left from north: after 180 degrees the skater is one diameter west of the start
		r.radius = maxSide / 2f;
		r.exitSpeed = p.getSpeed();
		return r;
	}

	@Test
	public void shiftWithoutSteerStillBrakes()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(800);
		SkateInput in = new SkateInput();
		in.powerslide = true;
		SkatePhysicsRollingTest.run(p, in, 0.5f);
		// 900 u/s^2 brake plus friction and drag: under 400 after 0.5 s
		assertTrue(p.getSpeed() < 400f);
		assertEquals(0f, p.getHeading(), 0f);
	}

	@Test
	public void shiftThatIsNotYetABrakeDoesNotBrake()
	{
		// the input layer blocks the brake while Shift is a trick modifier (W held, a flick wind-up, or not yet
		// 0.25 s alone): only friction and drag, (45 + 0.00006 * 800^2) * 0.5 = 41.7, so still over 750
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(800);
		SkateInput in = new SkateInput();
		in.powerslide = true;
		in.brakeBlocked = true;
		SkatePhysicsRollingTest.run(p, in, 0.5f);
		assertTrue("speed " + p.getSpeed(), p.getSpeed() > 750f);
	}

	@Test
	public void shiftPlusSteerIsATightCarveFrom900()
	{
		// carve 2.6 / (1 + 900/2200) = 1.85 rad/s, x2.2 = 4.06 rad/s and rising as the speed bleeds at
		// (200 + 0.3 v) u/s^2 (+ friction and drag): 180 deg in ~0.75 s, radius ~200, exit ~500.
		// A normal carve at 900 has a radius of 900 / 1.85 = 487.
		Turn tight = turnAround(900f, true);
		Turn normal = turnAround(900f, false);
		assertTrue("seconds " + tight.seconds, tight.seconds >= 0.6f && tight.seconds <= 0.9f);
		assertTrue("radius " + tight.radius, tight.radius > 150f && tight.radius < 300f);
		assertTrue("exit " + tight.exitSpeed, tight.exitSpeed > 400f && tight.exitSpeed < 650f);
		assertTrue("normal radius " + normal.radius, normal.radius > 400f);
	}

	@Test
	public void shiftPlusSteerIsATightCarveFrom1500()
	{
		// carve 2.6 / (1 + 1500/2200) = 1.55 rad/s, x2.2 = 3.4: 180 deg in ~0.95 s, exit ~800
		Turn tight = turnAround(1500f, true);
		assertTrue("seconds " + tight.seconds, tight.seconds >= 0.8f && tight.seconds <= 1.1f);
		assertTrue("exit " + tight.exitSpeed, tight.exitSpeed > 650f && tight.exitSpeed < 1000f);
	}

	@Test
	public void standstillPivotTurnsAroundInAboutSevenTenths()
	{
		// below 250 u/s the carve blends toward a 4.5 rad/s pivot: from rest pi / 4.5 = 0.70 s
		Turn pivot = turnAround(0f, false);
		assertEquals(0.70f, pivot.seconds, 0.03f);
	}

	@Test
	public void carveFalloffIsGentlerAtSpeed()
	{
		// carveSpeedFalloff 1600 -> 2200: at 1100, 2.6 / (1 + 1100/2200) = 1.733 rad/s
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(1100f);
		SkateInput in = new SkateInput();
		in.steer = 1f;
		p.step(DT, in);
		assertEquals(1.7333f * DT, p.getHeading(), 1e-4f);
	}

	@Test
	public void ollieWhileHoldingSteerLands()
	{
		// carving with A held into the pop used to spin 7 rad/s through an uncharged ollie (0.7 s, 280 deg)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(900f);
		SkateInput in = new SkateInput();
		in.steer = -1f;
		SkatePhysicsRollingTest.run(p, in, 0.3f);
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void steerReleasedAndPressedAgainInTheAirSpins()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500f);
		SkateInput in = new SkateInput();
		in.steer = 1f;
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in); // the pop step still carves on the ground first
		float atPop = p.getHeading();
		p.step(DT, in);
		assertEquals("held from before the pop: ignored", atPop, p.getHeading(), 1e-6f);
		in.steer = 0f;
		p.step(DT, in);
		in.steer = 1f;
		p.step(DT, in);
		// re-pressed: 7 rad/s for one step
		assertEquals(atPop + t.airSpinRate * DT, p.getHeading(), 1e-4f);
	}

	@Test
	public void landingBlendsTheTravelOntoTheBoardInsteadOfSnapping()
	{
		// as SkatePhysicsAirTest.fiftyDegreeOffAxisLandingNowLands: a 0.152 steer held through a charged
		// ollie lands ~50 deg off the travel (north). The travel then turns onto the board over ~0.15 s.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0);
		p.setRollingSpeed(500f);
		SkateInput in = new SkateInput();
		in.crouch = true;
		SkatePhysicsRollingTest.run(p, in, 0.4f);
		in.crouch = false;
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		in.steer = 0.152f;
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("landed off-axis " + p.getHeading(), p.getHeading() > 0.7f);
		assertEquals("still travelling north", 0f, p.getTravelHeading(), 0.05f);
		in.steer = 0f;
		p.step(DT, in);
		float oneStep = p.getTravelHeading();
		assertTrue("blending " + oneStep, oneStep > 0.05f && oneStep < p.getHeading() - 0.3f);
		SkatePhysicsRollingTest.run(p, in, 0.16f);
		assertEquals(p.getHeading(), p.getTravelHeading(), 1e-5f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.TrickEvent;
import org.junit.Test;

/**
 * Walls scrape instead of steering. Incidence is measured from head-on: 0 deg = straight into the wall,
 * "into" = cos(incidence). All walls here are the line y = wallY across the skater's path (normal south).
 */
public class SkatePhysicsWallTest
{
	static final float DT = 0.02f;
	final SkateTuning t = new SkateTuning();

	private static float deg(float rad)
	{
		return (float) Math.toDegrees(rad);
	}

	@Test
	public void steeringIsNeverOverriddenByAWall()
	{
		// 30 deg incidence at 800; the old slide turned the board 30 -> 87 deg in two steps. A barely-held
		// steer (0.01 * <= 2.6 rad/s = 1.5 deg/s at most) must be all that turns it.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 90, (float) Math.toRadians(30));
		p.setRollingSpeed(800f);
		SkateInput in = new SkateInput();
		in.steer = 0.01f;
		SkatePhysicsRollingTest.run(p, in, 0.5f);
		assertTrue("x " + p.getX(), p.getX() > 60f);
		assertTrue(p.getY() < 100f);
		assertEquals(30f, deg(p.getHeading()), 1f);
	}

	@Test
	public void withoutSteerTheBoardEasesAlongTheWallSlowly()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 90, (float) Math.toRadians(30));
		p.setRollingSpeed(800f);
		SkateInput in = new SkateInput();
		float maxTurn = 0f;
		for (int i = 0; i < 60; i++)
		{
			float before = p.getHeading();
			p.step(DT, in);
			maxTurn = Math.max(maxTurn, Angles.absDiff(before, p.getHeading()));
		}
		// at most wallAlignRate 1.5 rad/s: 0.03 rad per 0.02 s step
		assertTrue("max turn " + maxTurn, maxTurn <= 1.5f * DT + 1e-4f);
		// 60 deg to go at 1.5 rad/s takes 0.7 s of the 1.2 s
		assertEquals(90f, deg(p.getHeading()), 0.01f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void glancingScrapeKeepsMostOfTheSpeed()
	{
		// 80 deg incidence (10 deg off the wall line) at 1400: into = cos 80 = 0.174, the first contact
		// costs 25% * 0.174 = 4.3% (1400 -> 1339); then 0.5 s of friction + drag (45 + 0.00012 * 1300^2 =
		// 248 u/s^2, ~124) and a scrape of 400 * into while the board eases the last 10 deg (~0.12 s, < 5):
		// about 1210 left. The old slide re-projected the speed every step.
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(80));
		p.setRollingSpeed(1400f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.5f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("speed " + p.getSpeed(), p.getSpeed() > 1150f);
		assertEquals(90f, deg(p.getHeading()), 0.01f);
	}

	@Test
	public void holdingSteerAndPushEscapesAWallWithinASecondAndAHalf()
	{
		// stopped right at the wall, facing it 10 deg off head-on; A + W: the old slide forced the board
		// back toward the wall line every step ("impossible to turn around")
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(10));
		SkateInput in = new SkateInput();
		in.steer = -1f;
		in.pushHeld = true;
		boolean left = false;
		for (int i = 0; i < 75 && !left; i++)
		{
			p.step(DT, in);
			left = p.getY() < 60f;
		}
		assertTrue("left the wall, y " + p.getY() + " heading " + deg(p.getHeading()), left);
	}

	@Test
	public void bailsWithin30DegreesOfHeadOnAboveBailSpeed()
	{
		// 1400 at 30 deg: 1400 * cos 30 = 1212 > 1100 and within the 30 deg cone -> bail
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 90, (float) Math.toRadians(30));
		p.setRollingSpeed(1400f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
	}

	@Test
	public void noBailAt31DegreesEvenAboveBailSpeed()
	{
		// 1400 * cos 31 = 1200 > 1100, but outside the 30 deg cone: a hard scrape, not a bail
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 90, (float) Math.toRadians(31));
		p.setRollingSpeed(1400f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertFalse(p.drainEvents().contains(SkateEvent.BAIL));
	}

	@Test
	public void headOnBelowBailSpeedStopsWithoutBailing()
	{
		// 1000 head-on: 1000 * 1 < wallBailSpeed 1100
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, 0f);
		p.setRollingSpeed(1000f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.3f);
		assertEquals(SkaterState.ROLLING, p.getState());
		assertEquals(0f, p.getSpeed(), 0f);
		assertTrue(p.getY() < 100f);
	}

	@Test
	public void hardHitStumblesWithSteeringLockedButKeepsTheCombo()
	{
		// 45 deg at 1000: impact 1000 * cos 45 = 707 > wallStumbleSpeed 600 -> 0.3 s with steering locked
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(45));
		p.setRollingSpeed(1000f);
		SkateInput in = new SkateInput();
		in.steer = -1f; // into the wall: would turn the board left (toward north) if it worked
		p.step(DT, in);
		p.drainTrickEvents();
		float atContact = p.getHeading();
		for (int i = 0; i < 12; i++)
		{
			p.step(DT, in);
		}
		// locked: the held left steer does nothing, and a wall never turns a board that is being steered
		float afterLock = p.getHeading();
		assertTrue("heading " + deg(afterLock), afterLock >= atContact);
		assertFalse(p.drainTrickEvents().contains(TrickEvent.bailed()));
		assertEquals(SkaterState.ROLLING, p.getState());
		// the 0.3 s lock ends during the next steps; then the steer works again (8 steps at ~1.7 rad/s
		// left = -0.27 rad)
		for (int i = 0; i < 10; i++)
		{
			p.step(DT, in);
		}
		assertTrue("heading " + deg(p.getHeading()), p.getHeading() < afterLock);
	}

	@Test
	public void lightHitDoesNotLockSteering()
	{
		// 60 deg at 1000 (58 after the first step's steer): impact 1000 * cos 58 = 530 < 600, no stumble
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(60));
		p.setRollingSpeed(1000f);
		SkateInput in = new SkateInput();
		in.steer = -1f;
		p.step(DT, in);
		float atContact = p.getHeading();
		p.step(DT, in);
		assertTrue(p.getHeading() < atContact);
	}

	@Test
	public void airborneHeadOnAbove1100Bails()
	{
		// a dropped-in ollie at 1200 head-on into a 300-high wall: 1200 * 1 > 1100 (was only > 1300)
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(200, 300), 0, 0, 0f);
		p.setRollingSpeed(1200f);
		SkateInput in = new SkateInput();
		in.gestures.add(new com.gielinorskate.tricks.Gesture(com.gielinorskate.tricks.Gesture.Direction.UP, false, 0f));
		SkatePhysicsRollingTest.run(p, in, 0.3f);
		assertEquals(SkaterState.BAILED, p.getState());
	}

	@Test
	public void afterAWallBailTheSkaterRecoversAlongTheWallAndCanRideOff()
	{
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 50, 0f);
		p.setRollingSpeed(1500f);
		SkatePhysicsRollingTest.run(p, new SkateInput(), 0.2f);
		assertEquals(SkaterState.BAILED, p.getState());
		// bailAutoReset 1.0 -> 0.5
		SkatePhysicsRollingTest.run(p, new SkateInput(), t.bailDuration + 0.55f);
		assertEquals(SkaterState.ROLLING, p.getState());
		// along the wall (a 90 degree turn at most), not straight away from it (a 180 degree camera swing)
		assertEquals(90f, Math.abs(deg(p.getHeading())), 0.01f);
		float x0 = p.getX();
		SkateInput in = new SkateInput();
		in.pushPressed = true;
		SkatePhysicsRollingTest.run(p, in, 0.3f);
		assertTrue(Math.abs(p.getX() - x0) > 50f);
		assertEquals(SkaterState.ROLLING, p.getState());
	}

	@Test
	public void stumbleRunsOutInTheAirToo()
	{
		// stumble (as above), pop straight away and land ~0.75 s later: the 0.3 s steering lock is long over
		SkatePhysics p = new SkatePhysics(t, TestWorlds.wallAtY(100, 300), 0, 95, (float) Math.toRadians(45));
		p.setRollingSpeed(1000f);
		SkateInput in = new SkateInput();
		p.step(DT, in);
		in.gestures.add(new com.gielinorskate.tricks.Gesture(com.gielinorskate.tricks.Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		float landed = p.getHeading();
		in.steer = -1f;
		p.step(DT, in);
		p.step(DT, in);
		assertTrue("steers straight after landing: " + deg(landed) + " -> " + deg(p.getHeading()),
			p.getHeading() < landed - 0.01f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

public class SkateTuningTest
{
	@Test
	public void missingFieldsKeepDefaults()
	{
		SkateTuning t = SkateTuning.load(new Gson(), new StringReader("{\"gravity\": 1000}"));
		assertEquals(1000f, t.gravity, 0f);
		assertEquals(new SkateTuning().ollieImpulse, t.ollieImpulse, 0f);
	}

	@Test
	public void bundledJsonLoads() throws Exception
	{
		try (Reader r = new InputStreamReader(
			SkateTuning.class.getResourceAsStream("/com/gielinorskate/skate-tuning.json"), StandardCharsets.UTF_8))
		{
			SkateTuning t = SkateTuning.load(new Gson(), r);
			assertEquals(new SkateTuning().maxPushSpeed, t.maxPushSpeed, 0f);
		}
	}

	/** The session loads the bundled JSON, so it must carry every retuned default, not the old values. */
	@Test
	public void bundledJsonMatchesEveryDefault() throws Exception
	{
		SkateTuning d = new SkateTuning();
		try (Reader r = new InputStreamReader(
			SkateTuning.class.getResourceAsStream("/com/gielinorskate/skate-tuning.json"), StandardCharsets.UTF_8))
		{
			SkateTuning j = SkateTuning.load(new Gson(), r);
			float[][] pairs = {
				{d.pushImpulse, j.pushImpulse}, {d.pushFromRest, j.pushFromRest}, {d.pushMinImpulse, j.pushMinImpulse},
				{d.pushCooldown, j.pushCooldown}, {d.maxPushSpeed, j.maxPushSpeed}, {d.maxSpeed, j.maxSpeed},
				{d.rollingFriction, j.rollingFriction}, {d.drag, j.drag}, {d.powerslideDecel, j.powerslideDecel},
				{d.carveRate, j.carveRate}, {d.carveSpeedFalloff, j.carveSpeedFalloff},
				{d.tightCarveMult, j.tightCarveMult}, {d.tightCarveBleed, j.tightCarveBleed},
				{d.tightCarveBleedFraction, j.tightCarveBleedFraction}, {d.pivotSpeed, j.pivotSpeed},
				{d.pivotRate, j.pivotRate}, {d.airSpinRate, j.airSpinRate}, {d.gravity, j.gravity},
				{d.slopeGravityScale, j.slopeGravityScale}, {d.maxSlope, j.maxSlope}, {d.ollieImpulse, j.ollieImpulse},
				{d.minPopFraction, j.minPopFraction}, {d.crouchChargeTime, j.crouchChargeTime},
				{d.landingToleranceDeg, j.landingToleranceDeg}, {d.maxStepUp, j.maxStepUp}, {d.rollOffDrop, j.rollOffDrop},
				{d.wallBailSpeed, j.wallBailSpeed}, {d.wallBailAngleDeg, j.wallBailAngleDeg},
				{d.wallStumbleSpeed, j.wallStumbleSpeed}, {d.stumbleTime, j.stumbleTime},
				{d.wallContactLoss, j.wallContactLoss}, {d.wallScrape, j.wallScrape}, {d.wallAlignRate, j.wallAlignRate},
				{d.spinAssistRate, j.spinAssistRate}, {d.bailDuration, j.bailDuration}, {d.bailFriction, j.bailFriction},
				{d.bailAutoReset, j.bailAutoReset}, {d.skaterRadius, j.skaterRadius},
				{d.rampLaunchSpeedFraction, j.rampLaunchSpeedFraction}, {d.rampLaunchSlopeDrop, j.rampLaunchSlopeDrop},
				{d.rampLaunchMinSlope, j.rampLaunchMinSlope}, {d.rampLaunchMinRun, j.rampLaunchMinRun},
{d.momentumClimbSpeedPerRise, j.momentumClimbSpeedPerRise},
				{d.momentumClimbGravityScale, j.momentumClimbGravityScale}, {d.dropInMaxGradient, j.dropInMaxGradient},
			};
			for (int i = 0; i < pairs.length; i++)
			{
				assertEquals("field #" + i, pairs[i][0], pairs[i][1], 0f);
			}
		}
	}

	@Test
	public void scaledAdjustsPushAndPop()
	{
		SkateTuning base = new SkateTuning();
		SkateTuning s = base.scaled(1.5f, 0.5f);
		assertEquals(base.pushImpulse * 1.5f, s.pushImpulse, 1e-3f);
		assertEquals(base.maxPushSpeed * 1.5f, s.maxPushSpeed, 1e-3f);
		assertEquals(base.ollieImpulse * 0.5f, s.ollieImpulse, 1e-3f);
		assertEquals(base.gravity, s.gravity, 0f);
	}

	@Test
	public void wallBailSpeedScalesWithPushSpeed()
	{
		// faster pushing must not turn ordinary head-ons into bails: 1100 * 1.5 = 1650
		SkateTuning base = new SkateTuning();
		assertEquals(base.wallBailSpeed * 1.5f, base.scaled(1.5f, 1f).wallBailSpeed, 1e-3f);
		assertEquals(base.wallBailSpeed * 0.75f, base.scaled(0.75f, 1f).wallBailSpeed, 1e-3f);
	}

	@Test
	public void scalePercentIsClampedTo75To150()
	{
		// a value saved before the 75-150 range (50 or 200) is clamped
		assertEquals(0.75f, SkateTuning.scaleFromPercent(50), 0f);
		assertEquals(0.75f, SkateTuning.scaleFromPercent(75), 0f);
		assertEquals(1f, SkateTuning.scaleFromPercent(100), 0f);
		assertEquals(1.5f, SkateTuning.scaleFromPercent(150), 0f);
		assertEquals(1.5f, SkateTuning.scaleFromPercent(200), 0f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Where a knocked-off board ends up, and where a skater can stand. */
public class StandSpotTest
{
	private static final float TILE = 128f;
	private static final float R = 12f;

	@Test
	public void aBoardRestingSomewhereReachableStaysThere()
	{
		float[] at = StandSpot.boardRest(TestWorlds.flat(), 300f, 400f, 0f, 0f, 0f, 0f, R);
		assertArrayEquals(new float[]{300f, 400f, 0f}, at, 0f);
	}

	@Test
	public void aBoardOutsideTheLoadedAreaComesBackWithinTwoTilesOfTheSkater()
	{
		CollisionWorld w = TestWorlds.edgeAtY(100f);
		float[] at = StandSpot.boardRest(w, 0f, 105f, 0f, 0f, 0f, 0f, R);
		assertTrue("inside: " + at[1], w.edgeDistance(at[0], at[1]) > R);
		assertTrue(Math.hypot(at[0], at[1]) <= 2 * TILE + 1e-3);
	}

	@Test
	public void aBoardOnAHighLedgeComesDownNearTheSkater()
	{
		// a 300-high platform from y = 200: the board landed up there, the skater lies below
		CollisionWorld w = TestWorlds.platformAtY(200f, 300f);
		float[] at = StandSpot.boardRest(w, 0f, 250f, 300f, 0f, 0f, 0f, R);
		assertEquals(0f, at[2], 0f);
		assertTrue(at[1] < 200f);
		assertTrue(Math.hypot(at[0], at[1]) <= 2 * TILE + 1e-3);
	}

	@Test
	public void withNowhereBetterTheBoardLiesAtTheSkatersFeet()
	{
		// nothing within two tiles is inside the loaded area
		CollisionWorld w = TestWorlds.edgeAtY(-5000f);
		float[] at = StandSpot.boardRest(w, 0f, 100f, 0f, 0f, 0f, 0f, R);
		assertArrayEquals(new float[]{0f, 0f, 0f}, at, 0f);
	}

	@Test
	public void aStandableSpotIsKept()
	{
		assertArrayEquals(new float[]{10f, 20f, 0f}, StandSpot.nearest(TestWorlds.flat(), 10f, 20f, R, 2 * TILE), 0f);
	}

	@Test
	public void outsideTheLoadedAreaTheNearestStandableSpotIsFound()
	{
		CollisionWorld w = TestWorlds.edgeAtY(100f);
		float[] at = StandSpot.nearest(w, 0f, 110f, R, 2 * TILE);
		assertTrue(w.edgeDistance(at[0], at[1]) > R);
		assertTrue(Math.hypot(at[0], at[1] - 110f) <= 2 * TILE);
	}

	@Test
	public void nothingStandableNearbyKeepsThePoint()
	{
		CollisionWorld w = TestWorlds.edgeAtY(-5000f);
		assertArrayEquals(new float[]{0f, 0f, 0f}, StandSpot.nearest(w, 0f, 0f, R, 2 * TILE), 0f);
	}
}

package com.gielinorskate.physics;

/** Simple analytic worlds for physics tests. */
final class TestWorlds
{
	private TestWorlds()
	{
	}

	static CollisionWorld flat()
	{
		return of((x, y) -> 0f, null);
	}

	/** Ground descending northwards: height = -grade * y (a negative grade climbs northwards). */
	static CollisionWorld downhillNorth(float grade)
	{
		return of((x, y) -> -grade * y, null);
	}

	/** Flat ground with a blocker line at y = wallY of the given top height. */
	static CollisionWorld wallAtY(float wallY, float top)
	{
		return of((x, y) -> 0f, (y0, y1) -> (y0 < wallY && y1 >= wallY) || (y0 >= wallY && y1 < wallY) ? top : Float.NEGATIVE_INFINITY);
	}

	/**
	 * Ground descending northwards at {@code grade} with bumps of {@code amp} every 2 * PI * {@code scale}
	 * units on top: height = -grade * y + amp * sin(y / scale).
	 */
	static CollisionWorld bumpyDownhillNorth(float grade, float amp, float scale)
	{
		return of((x, y) -> -grade * y + amp * (float) Math.sin(y / scale), null);
	}

	/** Ground at height `low` for y < edgeY and `high` beyond it (terrain itself steps). */
	static CollisionWorld stepAtY(float edgeY, float low, float high)
	{
		return of((x, y) -> y < edgeY ? low : high, null);
	}

	/**
	 * Flat terrain at 0 with a platform (a curb, crate or ledge) of the given top for y >= edgeY: the
	 * skateable ground steps up there, the terrain does not.
	 */
	static CollisionWorld platformAtY(float edgeY, float top)
	{
		return of((x, y) -> y >= edgeY ? top : 0f, (x, y) -> 0f, null);
	}

	/**
	 * Flat ground ending at the edge of the loaded area at y = edgeY: an endless wall there, as the client's
	 * blocked outer tiles are, and {@link CollisionWorld#edgeDistance} measuring to it.
	 */
	static CollisionWorld edgeAtY(float edgeY)
	{
		CollisionWorld w = wallAtY(edgeY, Float.POSITIVE_INFINITY);
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return w.blockerTop(x0, y0, x1, y1);
			}

			@Override
			public float edgeDistance(float x, float y)
			{
				return edgeY - y;
			}
		};
	}

	interface Ground
	{
		float at(float x, float y);
	}

	interface WallY
	{
		float top(float y0, float y1);
	}

	private static CollisionWorld of(Ground ground, WallY wall)
	{
		return of(ground, ground, wall);
	}

	private static CollisionWorld of(Ground ground, Ground terrain, WallY wall)
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return ground.at(x, y);
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return terrain.at(x, y);
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return wall == null ? Float.NEGATIVE_INFINITY : wall.top(y0, y1);
			}
		};
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The knocked-off skater's body: hop, tumble, impact, skid; never through walls, always at rest, always finite. */
public class TumbleBodyTest
{
	private static final float DT = 0.02f;
	private static final float G = new SkateTuning().gravity;
	private static final float R = new SkateTuning().skaterRadius;

	private static TumbleBody flung(CollisionWorld w, float speed, float travel)
	{
		TumbleBody b = new TumbleBody(w, G, R);
		b.start(0, 0, w.groundHeight(0, 0), (float) Math.sin(travel) * speed, (float) Math.cos(travel) * speed,
			travel, false, 0f, 0f, 0.3f);
		return b;
	}

	/** Steps until at rest or {@code seconds} pass; returns the seconds stepped. */
	private static float runToRest(TumbleBody b, float seconds)
	{
		float t = 0f;
		while (t < seconds && !b.isAtRest())
		{
			b.step(DT);
			assertFinite(b);
			t += DT;
		}
		return t;
	}

	private static void assertFinite(TumbleBody b)
	{
		float[] v = {b.getX(), b.getY(), b.getH(), b.getAngle(), b.getRoll(), b.getSpeed()};
		for (float f : v)
		{
			assertFalse("not finite: " + f, Float.isNaN(f) || Float.isInfinite(f));
		}
	}

	@Test
	public void aFastBailHopsTumblesForwardAndLandsQuickly()
	{
		TumbleBody b = flung(TestWorlds.flat(), 1500f, 0f);
		assertTrue(b.isAirborne());
		float t = 0f;
		while (b.isAirborne() && t < 2f)
		{
			b.step(DT);
			t += DT;
		}
		// short and punchy: the hop is about a quarter second
		assertTrue("airtime " + t, t > 0.15f && t < 0.4f);
		assertTrue(b.takeImpact());
		assertFalse("the impact is reported once", b.takeImpact());
		// carried forward along the travel direction (north)
		assertTrue(b.getY() > 100f);
		assertEquals(0f, b.getX(), 1e-3f);
		// over a turn, about the side axis (forward)
		assertTrue("tumbled " + b.getAngle(), b.getAngle() > 2 * Math.PI);
	}

	@Test
	public void aSlowBailHopsLessAndTurnsLess()
	{
		TumbleBody fast = flung(TestWorlds.flat(), 1500f, 0f);
		TumbleBody slow = flung(TestWorlds.flat(), 200f, 0f);
		assertTrue(slow.getVerticalSpeed() < fast.getVerticalSpeed());
		assertTrue(slow.getLieAngle() < fast.getLieAngle());
		assertTrue(slow.getLieAngle() > 0f);
	}

	@Test
	public void itComesToRestLyingFlatOnBackOrFront()
	{
		for (float speed : new float[]{0f, 200f, 800f, 1500f, 2600f})
		{
			TumbleBody b = flung(TestWorlds.flat(), speed, 1f);
			float t = runToRest(b, 3f);
			assertTrue("rests at " + speed + " within " + t, b.isAtRest());
			assertTrue("rests quickly: " + t, t < 1.2f);
			// lying: a quarter turn plus whole half turns
			double lying = (b.getAngle() - Math.PI / 2) / Math.PI;
			assertEquals("lying at " + speed + ": " + b.getAngle(), Math.round(lying), lying, 0.05);
			assertEquals(0f, b.getH(), 0f);
			assertEquals(0f, b.getSpeed(), 0f);
		}
	}

	@Test
	public void neverPassesThroughAWall()
	{
		CollisionWorld w = TestWorlds.wallAtY(150f, 300f);
		for (float speed : new float[]{300f, 1500f, 2600f})
		{
			TumbleBody b = flung(w, speed, 0f);
			for (int i = 0; i < 200; i++)
			{
				b.step(DT);
				assertTrue("through the wall at " + speed + ": y " + b.getY(), b.getY() < 150f);
				assertFinite(b);
			}
			assertTrue(b.isAtRest());
		}
	}

	@Test
	public void aWallBailReboundsOffTheWallAndFallsBackward()
	{
		CollisionWorld w = TestWorlds.wallAtY(20f, 300f);
		TumbleBody b = new TumbleBody(w, G, R);
		// ran north into the wall: its normal points south
		b.start(0, 0, 0, 0f, 1400f, 0f, true, 0f, -1f, 0f);
		runToRest(b, 3f);
		assertTrue("rebounded south: y " + b.getY(), b.getY() < -20f);
		// low speed: it stays near the wall
		assertTrue(b.getY() > -3 * 128f);
		// backward, onto the back
		assertTrue("fell backward: " + b.getAngle(), b.getAngle() < 0f);
		assertEquals(-Math.PI / 2, b.getAngle(), 0.05);
	}

	@Test
	public void fallingOffALedgeLandsBelow()
	{
		CollisionWorld w = TestWorlds.stepAtY(60f, 0f, -300f);
		TumbleBody b = new TumbleBody(w, G, R);
		b.start(0, 0, 0, 0f, 900f, 0f, false, 0f, 0f, 0f);
		runToRest(b, 4f);
		assertTrue(b.isAtRest());
		assertEquals(-300f, b.getH(), 0f);
	}

	@Test
	public void aBailInTheAirFallsToTheGround()
	{
		TumbleBody b = new TumbleBody(TestWorlds.flat(), G, R);
		b.start(0, 0, 200f, 0f, 600f, 0f, false, 0f, 0f, 0f);
		assertTrue(b.isAirborne());
		runToRest(b, 4f);
		assertEquals(0f, b.getH(), 0f);
	}

	@Test
	public void staysInsideTheLoadedArea()
	{
		CollisionWorld w = TestWorlds.edgeAtY(100f);
		TumbleBody b = flung(w, 2600f, 0f);
		runToRest(b, 4f);
		assertTrue(b.getY() < 100f);
	}

	@Test
	public void restsHeldAtRest()
	{
		TumbleBody b = flung(TestWorlds.flat(), 900f, 0f);
		runToRest(b, 3f);
		float x = b.getX();
		float y = b.getY();
		float a = b.getAngle();
		for (int i = 0; i < 50; i++)
		{
			b.step(DT);
		}
		assertEquals(x, b.getX(), 0f);
		assertEquals(y, b.getY(), 0f);
		assertEquals(a, b.getAngle(), 1e-4f);
	}

	@Test
	public void stopNowEndsTheSkid()
	{
		TumbleBody b = flung(TestWorlds.flat(), 1500f, 0f);
		b.step(DT);
		b.stop();
		assertEquals(0f, b.getSpeed(), 0f);
	}

	@Test
	public void theGroundOffsetKeepsTheLowestPointOnTheGround()
	{
		assertEquals(0f, TumbleBody.groundOffset(0f), 1e-3f);
		assertEquals(0f, TumbleBody.groundOffset((float) (2 * Math.PI)), 1e-3f);
		// lying: the centre of mass comes down to the body's half thickness
		float lying = TumbleBody.groundOffset((float) (Math.PI / 2));
		assertTrue("lying drops the body: " + lying, lying < -20f);
		assertEquals(lying, TumbleBody.groundOffset((float) (-Math.PI / 2)), 1e-3f);
		// upside down the head would be under the feet' line: raised
		assertTrue(TumbleBody.groundOffset((float) Math.PI) > 0f);
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertTrue;
import com.gielinorskate.world.BlockerSet;
import com.gielinorskate.world.GridCollisionWorld;
import com.gielinorskate.world.WorldTests;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/**
 * Sweep: ride into fences (tall and low, both sides, a gap's end posts), wall corners (inner and outer), rotated
 * solid boxes and rocks, grindable boxes, a box against a fence and a V of two boxes, at incidences 0-85 degrees
 * and 200-1500 u/s, coasting, pushing or ollieing into it. Then get away as a player would: find the most open
 * way (looked for again every quarter second), steer towards it with W held (also the long way round for a
 * near head-on hit, and with Shift for a tight carve) and ride on once within 15 degrees of it. Whatever was hit,
 * the skater must never be wedged: within 1.5 s back on the board (plus the deliberate stumble steering lock)
 * it is more than 30 units clear of every blocker, or riding away along a neighbouring wall more than a tile from
 * the hit; and every bail ends by itself.
 */
public class WallEscapeSweepTest
{
	private static final float DT = 0.02f;
	private static final float T = GridCollisionWorld.TILE;
	private static final float C = 10 * T;
	private static final float CLEAR = 30f;
	private static final float ESCAPE_TIME = 1.5f;

	/** One geometry with a point on its face and the face's outward normal (the approach side). */
	private static final class Scene
	{
		final String name;
		final GridCollisionWorld world;
		final float px;
		final float py;
		final float nx;
		final float ny;

		Scene(String name, GridCollisionWorld world, float px, float py, float nDeg)
		{
			this.name = name;
			this.world = world;
			this.px = px;
			this.py = py;
			// normal as a heading: 0 = +y, clockwise
			this.nx = (float) Math.sin(Math.toRadians(nDeg));
			this.ny = (float) Math.cos(Math.toRadians(nDeg));
			world.rebuildBlockers();
			world.rebuildGrinds();
		}
	}

	private static GridCollisionWorld fenceRow(float height, int fromTx, int toTx, int gapTx)
	{
		GridCollisionWorld w = new GridCollisionWorld(20);
		for (int tx = fromTx; tx <= toTx; tx++)
		{
			if (tx != gapTx)
			{
				w.setTile(tx, 10, GridCollisionWorld.WALL_N, height);
			}
		}
		return w;
	}

	private static List<Scene> scenes()
	{
		List<Scene> s = new ArrayList<>();
		float fenceY = 11 * T;
		for (float hgt : new float[]{40f, 60f, 140f, 300f})
		{
			s.add(new Scene("fence" + (int) hgt, fenceRow(hgt, 4, 16, -1), C + 40, fenceY, 180));
			// the far side of the same fence line (approached from the north)
			s.add(new Scene("fenceN" + (int) hgt, fenceRow(hgt, 4, 16, -1), C + 40, fenceY, 0));
		}
		// a fence with a one-tile gap: ride into the post at the end of the gap
		s.add(new Scene("fenceGapEnd", fenceRow(60f, 4, 16, 10), 10 * T + 6, fenceY, 180));
		s.add(new Scene("fenceGapEnd2", fenceRow(60f, 4, 16, 10), 11 * T - 6, fenceY, 180));
		// inner corner of an L: north wall over tiles 4..10, east wall up tiles 4..10 of column 10
		for (float hgt : new float[]{60f, 300f})
		{
			GridCollisionWorld w = fenceRow(hgt, 4, 10, -1);
			for (int ty = 4; ty <= 10; ty++)
			{
				w.setTile(10, ty, ty == 10 ? GridCollisionWorld.WALL_N | GridCollisionWorld.WALL_E : GridCollisionWorld.WALL_E, hgt);
			}
			s.add(new Scene("innerCorner" + (int) hgt, w, 11 * T, 11 * T, 225));
			// the outer corner of the same L, from the north-east
			GridCollisionWorld w2 = fenceRow(hgt, 4, 10, -1);
			for (int ty = 4; ty <= 10; ty++)
			{
				w2.setTile(10, ty, ty == 10 ? GridCollisionWorld.WALL_N | GridCollisionWorld.WALL_E : GridCollisionWorld.WALL_E, hgt);
			}
			s.add(new Scene("outerCorner" + (int) hgt, w2, 11 * T, 11 * T, 45));
		}
		// rotated solid boxes (a wall piece, a rock)
		for (float a : new float[]{0f, 30f, 45f, 70f})
		{
			GridCollisionWorld w = new GridCollisionWorld(20);
			float r = (float) Math.toRadians(a);
			w.addBlocker(C, C, 300, 20, (float) Math.cos(r), (float) Math.sin(r), 200, BlockerSet.SOLID, 0);
			// the face normal of the -v face: v = (-sin, cos), outward -v = (sin, -cos) -> heading 180 - a
			float fx = C - (float) -Math.sin(r) * 20;
			float fy = C - (float) Math.cos(r) * 20;
			s.add(new Scene("box" + (int) a, w, fx, fy, 180 - a));
			GridCollisionWorld rock = new GridCollisionWorld(20);
			rock.addBlocker(C, C, 30, 30, (float) Math.cos(r), (float) Math.sin(r), 200, BlockerSet.SOLID, 0);
			s.add(new Scene("rock" + (int) a, rock, C - (float) -Math.sin(r) * 30, C - (float) Math.cos(r) * 30, 180 - a));
		}
		// grindable boxes (a fence piece, a bench): landable, LOW up to 120, rails on top
		for (float hgt : new float[]{40f, 60f, 100f, 150f})
		{
			for (float a : new float[]{0f, 45f})
			{
				GridCollisionWorld w = new GridCollisionWorld(20);
				w.addGrindableBlocker(C, C, new float[]{-200f, 200f, -4f, 4f}, (int) (a / 360f * 2048f), hgt);
				for (com.gielinorskate.world.GrindSegment g : com.gielinorskate.world.ObjectShapes.segments(C, C,
					new float[]{-200f, 200f, -4f, 4f}, (int) (a / 360f * 2048f)))
				{
					WorldTests.addGrindSegment(w, new com.gielinorskate.world.GrindSegment(g.x0, g.y0, g.x1, g.y1, hgt));
				}
				Scene probe = new Scene("x", w, C, C, 0);
				float[] n = faceOf(probe.world, C, C);
				s.add(new Scene("grindable" + (int) hgt + "a" + (int) a, w, n[0], n[1], n[2]));
			}
		}
		// fence plus a box against it: the corner between them
		for (float hgt : new float[]{60f, 300f})
		{
			GridCollisionWorld w = fenceRow(hgt, 4, 16, -1);
			w.addBlocker(C, fenceY - 40, 30, 40, 1f, 0f, 200, BlockerSet.SOLID, 0);
			s.add(new Scene("fenceBoxCorner" + (int) hgt, w, C + 30, fenceY, 135));
			s.add(new Scene("fenceBoxFace" + (int) hgt, w, C + 30, fenceY - 40, 90));
		}
		// a V of two boxes meeting at a point
		{
			GridCollisionWorld w = new GridCollisionWorld(20);
			float r1 = (float) Math.toRadians(45);
			float r2 = (float) Math.toRadians(135);
			w.addBlocker(C - 140, C + 140, 200, 12, (float) Math.cos(r1), (float) Math.sin(r1), 200, BlockerSet.SOLID, 0);
			w.addBlocker(C + 140, C + 140, 200, 12, (float) Math.cos(r2), (float) Math.sin(r2), 200, BlockerSet.SOLID, 0);
			s.add(new Scene("vee", w, C, C + 10, 180));
		}
		return s;
	}

	/** Point and outward normal heading of the -y-most face of the box near (x, y): probes from the south. */
	private static float[] faceOf(GridCollisionWorld w, float x, float y)
	{
		Contact c = new Contact();
		for (float d = 300; d > 0; d -= 1f)
		{
			if (w.contact(x, y - d, 0.01f, -1e4f, 0f, c))
			{
				return new float[]{x, y - d, (float) Math.toDegrees(Math.atan2(c.nx, c.ny))};
			}
		}
		return new float[]{x, y, 180};
	}

	/** Clear of every blocker taller than a step by more than CLEAR (standing on top of one counts too). */
	private static boolean clear(GridCollisionWorld w, SkatePhysics p, SkateTuning t)
	{
		return !w.contact(p.getX(), p.getY(), CLEAR, p.getH(), t.maxStepUp, new Contact());
	}

	/**
	 * Of 32 headings, the one with the longest free run (up to 3 tiles) from the skater's position, judged by
	 * the world's own blocking in 4-unit steps (moving out of an overlap is always free).
	 */
	private static float openHeading(GridCollisionWorld w, SkatePhysics p, SkateTuning t)
	{
		float best = p.getHeading();
		float bestRun = -1f;
		for (int k = 0; k < 32; k++)
		{
			float a = (float) (k * 2 * Math.PI / 32);
			float sx = (float) Math.sin(a);
			float sy = (float) Math.cos(a);
			float run = 0f;
			while (run < 3 * T)
			{
				float x0 = p.getX() + sx * run;
				float y0 = p.getY() + sy * run;
				float x1 = x0 + sx * 4f;
				float y1 = y0 + sy * 4f;
				if (w.blockerTop(x0, y0, x1, y1, t.skaterRadius) > p.getH() + t.maxStepUp
					|| w.groundHeight(x1, y1) > p.getH() + t.maxStepUp)
				{
					break;
				}
				run += 4f;
			}
			// the longest run; among (nearly) equal runs the one needing the least turn, so a skater along a
			// wall does not flip between its two open ends
			boolean longer = run > bestRun + 8f;
			boolean asLong = run > bestRun - 8f && Angles.absDiff(a, p.getHeading()) < Angles.absDiff(best, p.getHeading());
			if (bestRun < 0f || longer || asLong)
			{
				bestRun = Math.max(run, bestRun);
				best = a;
			}
		}
		return Angles.wrap(best);
	}

	/**
	 * Riding away along a neighbouring wall counts too (out of a corner, along the fence beside a box): more
	 * than a tile from where it hit and still rolling.
	 */
	private static boolean awayAlong(SkatePhysics p, float hitX, float hitY)
	{
		return Math.hypot(p.getX() - hitX, p.getY() - hitY) > T && Math.abs(p.getSpeed()) > 150f;
	}

	private static boolean touching(GridCollisionWorld w, SkatePhysics p, SkateTuning t)
	{
		return w.contact(p.getX(), p.getY(), t.skaterRadius + 2f, p.getH(), t.maxStepUp, new Contact());
	}

	enum Escape
	{
		STEER_AWAY_PUSH, STEER_OTHER_PUSH, SHIFT_STEER_AWAY, NONE
	}

	/** Returns null on success, else a description of how it got stuck. */
	private static String run(Scene sc, float incidenceDeg, float speed, boolean pushIn, boolean ollie, Escape esc,
		SkateTuning t)
	{
		// travel direction: -n turned by the incidence (clockwise)
		float nHead = (float) Math.atan2(sc.nx, sc.ny);
		float travel = Angles.wrap(nHead + Angles.PI + (float) Math.toRadians(incidenceDeg));
		float dx = (float) Math.sin(travel);
		float dy = (float) Math.cos(travel);
		float start = 260f;
		SkatePhysics p = new SkatePhysics(t, sc.world, sc.world.getGrinds(), sc.px - dx * start + sc.nx * 1f,
			sc.py - dy * start + sc.ny * 1f, travel);
		p.setRollingSpeed(speed);
		SkateInput in = new SkateInput();
		in.pushHeld = pushIn;
		boolean hit = false;
		boolean popped = false;
		for (int i = 0; i < 150; i++)
		{
			// ollie in time to be in the air at the face (a pop lasts about 0.75 s; go 0.15 s before)
			float toFace = (sc.px - p.getX()) * dx + (sc.py - p.getY()) * dy;
			if (ollie && !popped && p.getState() == SkaterState.ROLLING && toFace < Math.abs(p.getSpeed()) * 0.15f + 20f)
			{
				popped = true;
				in.gestures.add(new com.gielinorskate.tricks.Gesture(com.gielinorskate.tricks.Gesture.Direction.UP, false, 0f));
			}
			p.step(DT, in);
			if (p.getState() == SkaterState.BAILED
				|| (p.getState() != SkaterState.GRINDING && p.getState() != SkaterState.AIRBORNE && touching(sc.world, p, t)))
			{
				hit = true;
				break;
			}
			if (p.getState() == SkaterState.GRINDING || p.getState() == SkaterState.AIRBORNE)
			{
				continue; // caught the rail or still in the air: carry on until it hits or rides away
			}
		}
		if (!hit)
		{
			return null;
		}
		in.pushHeld = false;
		float hitX = p.getX();
		float hitY = p.getY();
		// away = towards the most open space, as a player looks for it (a hit can end up anywhere: over a low
		// fence into the corner behind it, round the far side of a box)
		float nHeadAway = 0f;
		boolean chosen = false;
		float turn = 0f;
		int bailSteps = 0;
		int freeSteps = 0;
		// a hard hit locks steering for stumbleTime on purpose (a penalty, not a trap): the clock allows for it
		while (freeSteps < (ESCAPE_TIME + t.stumbleTime) / DT)
		{
			if (p.getState() == SkaterState.BAILED)
			{
				if (esc == Escape.STEER_OTHER_PUSH)
				{
					return null; // the recovery already faces away: turning the long way round is not an escape
				}
				// a bail must end by itself; the escape clock starts once back on the board
				if (++bailSteps > (t.bailDuration + t.bailAutoReset + 0.2f) / DT)
				{
					return "bail never ended";
				}
				in.steer = 0f;
				in.pushHeld = false;
				in.powerslide = false;
				chosen = false;
			}
			else
			{
				bailSteps = 0;
				// look again for the open way every quarter second, as a player would while turning
				if (freeSteps % 12 == 0)
				{
					chosen = false;
				}
				if (!chosen)
				{
					chosen = true;
					nHeadAway = openHeading(sc.world, p, t);
					// which way turns the heading toward it (the other way for STEER_OTHER_PUSH); the long way
					// round stays the long way when the target is looked for again
					float away = Angles.wrap(nHeadAway - p.getHeading()) >= 0 ? 1f : -1f;
					if (turn == 0f || esc != Escape.STEER_OTHER_PUSH)
					{
						turn = esc == Escape.STEER_OTHER_PUSH ? -away : away;
					}
				}
				// steer until the board points away from the face (within 15 degrees of the most open way), then ride
				// straight on, as a player would; W held throughout
				boolean facingAway = Math.cos(Angles.wrap(nHeadAway - p.getHeading())) > Math.cos(Math.toRadians(15));
				boolean steering = esc != Escape.NONE && !facingAway;
				in.steer = steering ? turn : 0f;
				in.pushHeld = esc != Escape.NONE;
				in.powerslide = steering && esc == Escape.SHIFT_STEER_AWAY;
				if (esc != Escape.NONE && (clear(sc.world, p, t) || awayAlong(p, hitX, hitY)))
				{
					return null;
				}
				freeSteps++;
			}
			p.step(DT, in);
		}
		if (esc == Escape.NONE)
		{
			return null;
		}
		return "not clear after " + ESCAPE_TIME + " s: " + p.getState() + " at " + p.getX() + "," + p.getY() + " h " + p.getH()
			+ " heading " + Math.toDegrees(p.getHeading()) + " speed " + p.getSpeed();
	}

	private static List<String> sweep(SkateTuning t)
	{
		List<String> fails = new ArrayList<>();
		for (Scene sc : scenes())
		{
			for (float inc = 0; inc <= 85; inc += 5)
			{
				for (float speed : new float[]{200, 400, 700, 1000, 1200, 1500})
				{
					for (int mode = 0; mode < 3; mode++)
					{
						boolean pushIn = mode == 1;
						boolean ollie = mode == 2;
						for (Escape esc : Escape.values())
						{
							if (esc == Escape.STEER_OTHER_PUSH && inc > 15)
							{
								continue; // only near head-on is turning either way a way out
							}
							String r = run(sc, inc, speed, pushIn, ollie, esc, t);
							if (r != null)
							{
								fails.add(sc.name + " inc " + inc + " speed " + speed + " push " + pushIn + " ollie " + ollie + " " + esc + ": " + r);
							}
						}
					}
				}
			}
		}
		return fails;
	}

	private static void assertNoneStuck(List<String> fails)
	{
		StringBuilder sb = new StringBuilder(fails.size() + " stuck configurations");
		for (int i = 0; i < Math.min(5, fails.size()); i++)
		{
			sb.append("; ").append(fails.get(i));
		}
		assertTrue(sb.toString(), fails.isEmpty());
	}

	@Test
	public void neverStuckOnAWallFenceOrBox()
	{
		assertNoneStuck(sweep(new SkateTuning()));
	}

	@Test
	public void neverStuckWithForgivingCollisions()
	{
		// the "Forgiving collisions" option (SkateSession: radius 8, bails above 1500)
		SkateTuning t = new SkateTuning();
		t.skaterRadius = 8f;
		t.wallBailSpeed = 1500f;
		assertNoneStuck(sweep(t));
	}
}

package com.gielinorskate.physics;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Gesture;
import com.gielinorskate.world.BlockerSet;
import com.gielinorskate.world.GridCollisionWorld;
import org.junit.Test;

/**
 * The ways a skater got wedged against walls and fences (found by {@link WallEscapeSweepTest}), one test each.
 */
public class WallStuckTest
{
	private static final float DT = 0.02f;
	private static final float T = GridCollisionWorld.TILE;
	private final SkateTuning t = new SkateTuning();

	@Test
	public void ridingAlongAWallIntoItPassesTheJointBetweenTwoWallTiles()
	{
		// a wall along the east edge of column 10 (x = 1408), one wall box per tile. Riding south down it 16
		// degrees into it, at a tile joint (y = 1280) the next box's end reported a normal along the wall, the
		// slide along it ran into the wall, and the skater stopped dead there for good
		GridCollisionWorld w = new GridCollisionWorld(20);
		for (int ty = 4; ty <= 10; ty++)
		{
			w.setTile(10, ty, GridCollisionWorld.WALL_E, 300f);
		}
		for (float startY = 10 * T + 4; startY <= 10 * T + 60; startY += 4)
		{
			for (float off : new float[]{0.5f, 1.2f, 3f})
			{
				SkatePhysics p = new SkatePhysics(t, w, 11 * T - off, startY, (float) Math.toRadians(164));
				p.setRollingSpeed(450);
				SkateInput in = new SkateInput();
				in.pushHeld = true;
				for (int i = 0; i < 50; i++)
				{
					p.step(DT, in);
				}
				String at = "start y " + startY + " off " + off + ": ";
				assertEquals(at, SkaterState.ROLLING, p.getState());
				assertTrue(at + "past the joint: y " + p.getY(), p.getY() < 10 * T - 150);
				assertTrue(at + "still rolling: " + p.getSpeed(), p.getSpeed() > 100f);
			}
		}
	}

	@Test
	public void slidingOffTheEndOfABoxFaceRoundsItsCorner()
	{
		// a 60 x 60 rock; riding east along its south face, 15 degrees into it. Past the corner the slide along
		// the face clipped the rounded corner on its way, nothing was free and the skater stopped dead
		GridCollisionWorld w = new GridCollisionWorld(20);
		float c = 10 * T;
		w.addBlocker(c, c, 30, 30, 1f, 0f, 200, BlockerSet.SOLID, 0);
		SkatePhysics p = new SkatePhysics(t, w, c - 100, c - 30 - 12.5f, (float) Math.toRadians(75));
		p.setRollingSpeed(200);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		for (int i = 0; i < 60; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		assertTrue("round the corner: x " + p.getX(), p.getX() > c + 60);
		assertTrue("still rolling: " + p.getSpeed(), p.getSpeed() > 100f);
	}

	@Test
	public void pushingPastARockCornerIsNotBlocked()
	{
		// a skater just clear of a 45-degree rock's east corner, pushing north: the move grazes the corner within
		// the skater radius at its middle but ends clear. That counted as stepping over the rock, and with no
		// contact at the clear end the skater stopped dead against the corner
		GridCollisionWorld w = new GridCollisionWorld(20);
		float c = 10 * T;
		float r = (float) Math.toRadians(45);
		w.addBlocker(c, c, 30, 30, (float) Math.cos(r), (float) Math.sin(r), 200, BlockerSet.SOLID, 0);
		float corner = c + 30 * (float) Math.sqrt(2);
		SkatePhysics p = new SkatePhysics(t, w, corner + 11.76f, c - 2.72f, 0f);
		SkateInput in = new SkateInput();
		in.pushHeld = true;
		for (int i = 0; i < 25; i++)
		{
			p.step(DT, in);
		}
		assertTrue("rode on north: y " + p.getY(), p.getY() > c + 60);
	}

	@Test
	public void aNearVerticalLandingIsNeverFakie()
	{
		// dropping back down after bouncing off a wall in the air: a few u/s backwards at touchdown. That set
		// the fakie flag, so every W push went backwards, straight back into the wall
		SkatePhysics p = new SkatePhysics(t, TestWorlds.flat(), 0, 0, 0f);
		p.setRollingSpeed(-20f);
		SkateInput in = new SkateInput();
		in.gestures.add(new Gesture(Gesture.Direction.UP, false, 0f));
		p.step(DT, in);
		assertEquals(SkaterState.AIRBORNE, p.getState());
		for (int i = 0; i < 100 && p.getState() == SkaterState.AIRBORNE; i++)
		{
			p.step(DT, in);
		}
		assertEquals(SkaterState.ROLLING, p.getState());
		in.pushPressed = true;
		p.step(DT, in);
		assertTrue("a push from a near-standstill goes forwards: " + p.getSpeed(), p.getSpeed() > 0f);
	}
}

package com.gielinorskate.progression;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.io.StringReader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Pattern;
import org.junit.Test;

/** The design manifest (designs.json), id fallbacks, the old deck names, unlocks and wire names. */
public class BoardDesignsTest
{
	private static final String SMALL = "{\"designs\": ["
		+ "{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1},"
		+ "{\"id\": \"GRIP_B\", \"name\": \"B\", \"part\": \"grip\", \"unlock\": 10, \"credit\": \"someone\"},"
		+ "{\"id\": \"DECK_A\", \"name\": \"A\", \"part\": \"deck\", \"unlock\": 1},"
		+ "{\"id\": \"RUNE\", \"name\": \"Rune\", \"part\": \"deck\", \"unlock\": 50},"
		+ "{\"id\": \"WHEELS_A\", \"name\": \"A\", \"part\": \"wheels\", \"unlock\": 1},"
		+ "{\"id\": \"WHEELS_RUNE\", \"name\": \"Rune\", \"part\": \"wheels\", \"unlock\": 50}"
		+ "]}";

	private static final Pattern ID = Pattern.compile("[A-Z][A-Z0-9_]{0,23}");

	private static BoardDesigns small()
	{
		return checked(BoardDesigns.parse(new StringReader(SMALL)));
	}

	/**
	 * The manifest's rules (also checked by tools/designs.py when it writes the manifest): ids in uppercase A-Z,
	 * 0-9 and _, unique; a known part; a name; an unlock level 1..99;
	 * wire names short and unique within a part; each part has designs and its first (the default) unlocks at 1.
	 */
	private static BoardDesigns checked(BoardDesigns d)
	{
		Set<String> ids = new HashSet<>();
		Set<String> wires = new HashSet<>();
		Set<DesignPart> parts = new HashSet<>();
		for (BoardDesign b : d.all())
		{
			check(ID.matcher(b.id).matches() && ids.add(b.id), b);
			check(b.part != null && !b.name.trim().isEmpty() && b.unlock >= 1 && b.unlock <= SkateLevels.MAX_LEVEL, b);
			check(b.wireName().length() <= BoardDesigns.WIRE_MAX && wires.add(b.part + ":" + b.wireName()), b);
			check(!parts.add(b.part) || b.unlock == 1, b);
		}
		check(parts.size() == DesignPart.values().length, "a part without designs");
		return d;
	}

	private static void check(boolean ok, Object what)
	{
		if (!ok)
		{
			throw new IllegalArgumentException("designs.json: " + what);
		}
	}

	private static void refused(String json)
	{
		try
		{
			checked(BoardDesigns.parse(new StringReader(json)));
			fail("accepted " + json);
		}
		catch (RuntimeException expected)
		{
			// refused
		}
	}

	@Test
	public void theBundledManifestKeepsTheRules()
	{
		checked(BoardDesigns.bundled());
		assertTrue(BoardDesigns.bundled().all().size() > 3);
	}

	@Test
	public void parsesTheManifestInOrder()
	{
		BoardDesigns d = small();
		assertEquals(6, d.all().size());
		BoardDesign b = d.byId("GRIP_B");
		assertEquals("B", b.name);
		assertEquals(DesignPart.GRIP, b.part);
		assertEquals(10, b.unlock);
		assertEquals("someone", b.credit);
		assertNull(d.byId("GRIP_A").credit);
		assertEquals(Arrays.asList("GRIP_A", "GRIP_B"), ids(d.of(DesignPart.GRIP)));
		assertEquals(Arrays.asList("DECK_A", "RUNE"), ids(d.of(DesignPart.DECK)));
		assertNull(d.byId("NOPE"));
	}

	@Test
	public void theFirstDesignOfEachPartIsItsDefault()
	{
		BoardDesigns d = small();
		assertEquals("GRIP_A", d.defaultFor(DesignPart.GRIP).id);
		assertEquals("DECK_A", d.defaultFor(DesignPart.DECK).id);
		assertEquals("WHEELS_A", d.defaultFor(DesignPart.WHEELS).id);
	}

	@Test
	public void badManifestsAreRefused()
	{
		refused("[]");
		refused("{\"designs\": []}");
		// a part without designs
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1}]}");
		String deck = "{\"id\": \"DECK_A\", \"name\": \"A\", \"part\": \"deck\", \"unlock\": 1},"
			+ "{\"id\": \"WHEELS_A\", \"name\": \"A\", \"part\": \"wheels\", \"unlock\": 1}";
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 5}," + deck + "]}");
		refused("{\"designs\": [{\"id\": \"grip_a\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1}," + deck + "]}");
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"tail\", \"unlock\": 1}," + deck + "]}");
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 100}," + deck + "]}");
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"\", \"part\": \"grip\", \"unlock\": 1}," + deck + "]}");
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1},"
			+ "{\"id\": \"GRIP_A\", \"name\": \"B\", \"part\": \"grip\", \"unlock\": 1}," + deck + "]}");
		// wire names (the id without the part's prefix) are short and unique within a part
		refused("{\"designs\": [{\"id\": \"GRIP_MUCH_TOO_LONG\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1},"
			+ deck + "]}");
		refused("{\"designs\": [{\"id\": \"GRIP_A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1},"
			+ "{\"id\": \"A\", \"name\": \"A\", \"part\": \"grip\", \"unlock\": 1}," + deck + "]}");
		refused("not json");
	}

	@Test
	public void unknownOrWrongPartIdsFallBackToTheDefault()
	{
		BoardDesigns d = small();
		assertEquals("GRIP_B", d.find(DesignPart.GRIP, "GRIP_B").id);
		assertEquals("GRIP_A", d.find(DesignPart.GRIP, null).id);
		assertEquals("GRIP_A", d.find(DesignPart.GRIP, "").id);
		assertEquals("GRIP_A", d.find(DesignPart.GRIP, "GOLDEN_GNOME").id);
		assertEquals("GRIP_A", d.find(DesignPart.GRIP, "grip_b").id);
		// a deck id saved as the grip
		assertEquals("GRIP_A", d.find(DesignPart.GRIP, "RUNE").id);
		assertEquals("RUNE", d.find(DesignPart.DECK, " RUNE ").id);
	}

	@Test
	public void aLockedSavedDesignIsTheDefaultUntilItsLevel()
	{
		BoardDesigns d = small();
		assertEquals("DECK_A", d.usable(DesignPart.DECK, "RUNE", 49).id);
		assertEquals("RUNE", d.usable(DesignPart.DECK, "RUNE", 50).id);
		assertTrue(d.byId("RUNE").isUnlocked(50));
		assertFalse(d.byId("RUNE").isUnlocked(49));
	}

	@Test
	public void unlocksBetweenLevelsInManifestOrder()
	{
		BoardDesigns d = small();
		assertTrue(d.unlockedBetween(10, 49).isEmpty());
		assertEquals(Arrays.asList("GRIP_B"), ids(d.unlockedBetween(9, 10)));
		assertEquals(Arrays.asList("GRIP_B", "RUNE", "WHEELS_RUNE"), ids(d.unlockedBetween(1, 99)));
		assertTrue(d.unlockedBetween(50, 99).isEmpty());
	}

	@Test
	public void wireNamesDropThePartPrefix()
	{
		BoardDesigns d = small();
		assertEquals("B", d.byId("GRIP_B").wireName());
		assertEquals("RUNE", d.byId("RUNE").wireName());
		assertEquals("RUNE", d.byId("WHEELS_RUNE").wireName());
		assertSame(d.byId("GRIP_B"), d.fromWire(DesignPart.GRIP, "B"));
		assertSame(d.byId("RUNE"), d.fromWire(DesignPart.DECK, "RUNE"));
		assertSame(d.byId("WHEELS_RUNE"), d.fromWire(DesignPart.WHEELS, "RUNE"));
		// a full id is understood too; unknown or another part's: the default
		assertSame(d.byId("GRIP_B"), d.fromWire(DesignPart.GRIP, "GRIP_B"));
		assertSame(d.defaultFor(DesignPart.GRIP), d.fromWire(DesignPart.GRIP, "RUNE"));
		assertSame(d.defaultFor(DesignPart.DECK), d.fromWire(DesignPart.DECK, null));
		assertSame(d.defaultFor(DesignPart.DECK), d.fromWire(DesignPart.DECK, "ZZZ"));
	}

	@Test
	public void theBundledManifestKeepsTheOldDeckNames()
	{
		BoardDesigns d = BoardDesigns.bundled();
		assertEquals("GRIP_BLACK", d.defaultFor(DesignPart.GRIP).id);
		assertEquals("DECK_TROPICAL", d.defaultFor(DesignPart.DECK).id);
		assertEquals("WHEELS_NATURAL", d.defaultFor(DesignPart.WHEELS).id);
		// every rung of the old ladder is a deck design under the same name and level, so a saved skateDeck or
		// a party member's deck name keeps working
		String[] ladder = {"BRONZE", "IRON", "STEEL", "MITHRIL", "ADAMANT", "RUNE", "DRAGON", "BANDOS", "ARMADYL",
			"GUTHIX", "ZAMORAK", "SARADOMIN", "TORVA"};
		int[] levels = {1, 10, 20, 30, 40, 50, 60, 70, 70, 70, 70, 70, 99};
		for (int i = 0; i < ladder.length; i++)
		{
			String old = ladder[i];
			BoardDesign b = d.byId(old);
			assertEquals(old, DesignPart.DECK, b.part);
			assertEquals(old, levels[i], b.unlock);
			// with a grip and wheels of the same name and level: a full set
			for (DesignPart p : new DesignPart[]{DesignPart.GRIP, DesignPart.WHEELS})
			{
				BoardDesign set = d.byId(p.prefix + old);
				assertEquals(p + " " + old, levels[i], set.unlock);
				assertEquals(b.name, set.name);
			}
		}
		// the old starter deck (and decks removed from the ladder long ago) are the default deck now
		assertEquals("DECK_TROPICAL", d.find(DesignPart.DECK, "CLASSIC").id);
		assertEquals("DECK_TROPICAL", d.find(DesignPart.DECK, "PARTYHAT_PURPLE").id);
		assertEquals("DECK_TROPICAL", d.find(DesignPart.DECK, "DECK_TROPICAL").id);
		assertEquals("GRIP_BLACK", d.find(DesignPart.GRIP, "GRIP_BLACK").id);
		assertEquals("WHEELS_NATURAL", d.find(DesignPart.WHEELS, "WHEELS_NATURAL").id);
	}

	@Test
	public void removedTestDesignsFallBackToTheDefaults()
	{
		// the early test designs are gone: saved or received names for them draw the part's default
		BoardDesigns d = BoardDesigns.bundled();
		assertNull(d.byId("GRIP_RUNESKATE"));
		assertNull(d.byId("DECK_RED_CAMO"));
		assertNull(d.byId("WHEELS_DEATH"));
		assertSame(d.defaultFor(DesignPart.GRIP), d.find(DesignPart.GRIP, "GRIP_RUNESKATE"));
		assertSame(d.defaultFor(DesignPart.DECK), d.find(DesignPart.DECK, "DECK_RED_CAMO"));
		assertSame(d.defaultFor(DesignPart.WHEELS), d.find(DesignPart.WHEELS, "WHEELS_DEATH"));
		assertSame(d.defaultFor(DesignPart.GRIP), d.fromWire(DesignPart.GRIP, "RUNESKATE"));
		assertSame(d.defaultFor(DesignPart.DECK), d.fromWire(DesignPart.DECK, "RED_CAMO"));
		assertSame(d.defaultFor(DesignPart.WHEELS), d.fromWire(DesignPart.WHEELS, "DEATH"));
		assertSame(d.defaultFor(DesignPart.DECK), d.usable(DesignPart.DECK, "DECK_RED_CAMO", 99));
	}

	@Test
	public void bundledIdsAreUniqueAndFitTheWire()
	{
		Set<String> seen = new HashSet<>();
		for (BoardDesign b : BoardDesigns.bundled().all())
		{
			assertTrue(b.id, seen.add(b.id));
			assertTrue(b.id, b.wireName().length() <= BoardDesigns.WIRE_MAX);
		}
	}

	@Test
	public void aSavedIdThatIsNoDesignFallsBackToTheDefault()
	{
		BoardDesigns d = small();
		assertEquals("GRIP_A", d.usable(DesignPart.GRIP, "CUSTOM_0A1B2C3D", 99).id);
		assertEquals("DECK_A", d.find(DesignPart.DECK, "CUSTOM_0A1B2C3E").id);
		assertEquals("GRIP_A", d.fromWire(DesignPart.GRIP, "C:0a1b2c3d").id);
		assertEquals(Arrays.asList("GRIP_A", "GRIP_B"), ids(d.of(DesignPart.GRIP)));
	}

	private static List<String> ids(List<BoardDesign> list)
	{
		List<String> out = new ArrayList<>();
		for (BoardDesign b : list)
		{
			out.add(b.id);
		}
		return out;
	}
}

package com.gielinorskate.progression;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.Trick;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Random;
import org.junit.Before;
import org.junit.Test;

/** Goals that last the UTC day per account, so stopping and starting skating no longer rerolls them. */
public class DailyGoalsTest
{
	private static final LocalDate DAY = LocalDate.of(2026, 10, 5);

	private ProgressionTest.FakeStore store;
	private DailyGoals daily;
	private Random random;

	private static ComboScorer.Summary combo(int value, Trick... tricks)
	{
		return new ComboScorer.Summary(Arrays.asList(tricks), 0f, 0f, 0, value, tricks.length, false, 0, false);
	}

	private static List<SessionGoals.Type> types(DailyGoals d)
	{
		List<SessionGoals.Type> out = new ArrayList<>();
		for (SessionGoals.Goal g : d.goals().goals())
		{
			out.add(g.type);
		}
		return out;
	}

	/** Puts these goals in the account's profile for {@code day}. */
	private void saved(String profile, LocalDate day, SessionGoals.Type... types)
	{
		SessionGoals g = new SessionGoals();
		g.start(Arrays.asList(types));
		store.values.put(profile + "." + DailyGoals.DAY_KEY, day.toString());
		store.values.put(profile + "." + DailyGoals.STATE_KEY, DailyGoals.encode(g.goals()));
	}

	@Before
	public void setUp()
	{
		store = new ProgressionTest.FakeStore();
		store.current = "rsprofile.a";
		daily = new DailyGoals(store);
		random = new Random(3);
	}

	@Test
	public void firstLoadRollsThreeGoalsAndSavesThemForTheDay()
	{
		daily.load(DAY, random);
		assertEquals(3, daily.goals().goals().size());
		assertEquals("2026-10-05", store.values.get("rsprofile.a." + DailyGoals.DAY_KEY));
		assertEquals(DailyGoals.encode(daily.goals().goals()), store.values.get("rsprofile.a." + DailyGoals.STATE_KEY));
	}

	@Test
	public void startingAgainTheSameDayKeepsTheGoalsAndTheirProgress()
	{
		saved("rsprofile.a", DAY, SessionGoals.Type.BODY_FLIP, SessionGoals.Type.DIFFERENT_FLIPS,
			SessionGoals.Type.TOTAL_POINTS);
		daily.load(DAY, random);
		assertEquals(1, daily.onLanded(combo(300, Trick.BACKFLIP, Trick.KICKFLIP), DAY, random).size());

		// stop and start skating (and even reload the account) the same day: nothing rerolls or pays twice
		DailyGoals again = new DailyGoals(store);
		again.load(DAY, new Random(99));
		again.startSession(DAY, new Random(99));
		assertEquals(Arrays.asList(SessionGoals.Type.BODY_FLIP, SessionGoals.Type.DIFFERENT_FLIPS,
			SessionGoals.Type.TOTAL_POINTS), types(again));
		assertTrue(again.goals().goals().get(0).isDone());
		assertTrue(again.onLanded(combo(300, Trick.BACKFLIP), DAY, random).isEmpty());
		// the "different" goals remember which tricks they have seen
		assertEquals("1/5", again.goals().goals().get(1).progressText());
		again.onLanded(combo(300, Trick.KICKFLIP), DAY, random);
		assertEquals("1/5", again.goals().goals().get(1).progressText());
		assertEquals("900/50,000", again.goals().goals().get(2).progressText());
	}

	@Test
	public void aNewUtcDayRollsNewGoals()
	{
		saved("rsprofile.a", DAY, SessionGoals.Type.BODY_FLIP, SessionGoals.Type.DIFFERENT_FLIPS,
			SessionGoals.Type.TOTAL_POINTS);
		daily.load(DAY, random);
		daily.onLanded(combo(300, Trick.BACKFLIP), DAY, random);
		LocalDate next = DAY.plusDays(1);
		daily.startSession(next, random);
		for (SessionGoals.Goal g : daily.goals().goals())
		{
			assertFalse(g.isDone());
		}
		assertEquals("2026-10-06", store.values.get("rsprofile.a." + DailyGoals.DAY_KEY));
	}

	@Test
	public void theDayCanTurnMidSession()
	{
		saved("rsprofile.a", DAY, SessionGoals.Type.BODY_FLIP, SessionGoals.Type.DIFFERENT_FLIPS,
			SessionGoals.Type.TOTAL_POINTS);
		daily.load(DAY, random);
		daily.onLanded(combo(300, Trick.BACKFLIP), DAY, random);
		daily.onLanded(combo(300, Trick.OLLIE), DAY.plusDays(1), random);
		assertEquals("2026-10-06", store.values.get("rsprofile.a." + DailyGoals.DAY_KEY));
	}

	@Test
	public void eachAccountHasItsOwnGoals()
	{
		saved("rsprofile.a", DAY, SessionGoals.Type.BODY_FLIP, SessionGoals.Type.DIFFERENT_FLIPS,
			SessionGoals.Type.TOTAL_POINTS);
		saved("rsprofile.b", DAY, SessionGoals.Type.GRABS, SessionGoals.Type.SPIN_360, SessionGoals.Type.MULTIPLIER);
		daily.load(DAY, random);
		daily.onLanded(combo(300, Trick.BACKFLIP), DAY, random);

		store.current = "rsprofile.b";
		daily.load(DAY, random);
		assertEquals(Arrays.asList(SessionGoals.Type.GRABS, SessionGoals.Type.SPIN_360, SessionGoals.Type.MULTIPLIER),
			types(daily));
		daily.onLanded(combo(300, Trick.OLLIE), DAY, random);
		// b's landing is saved to b, not a
		assertTrue(store.values.get("rsprofile.a." + DailyGoals.STATE_KEY).contains("BODY_FLIP"));
		assertTrue(store.values.get("rsprofile.b." + DailyGoals.STATE_KEY).contains("GRABS"));

		store.current = "rsprofile.a";
		daily.load(DAY, random);
		assertTrue(daily.goals().goals().get(0).isDone());
	}

	@Test
	public void loggedOutGoalsLiveInMemoryOnly()
	{
		store.current = null;
		daily.load(DAY, random);
		assertEquals(3, daily.goals().goals().size());
		List<SessionGoals.Type> first = types(daily);
		daily.startSession(DAY, random);
		assertEquals(first, types(daily));
		assertTrue(store.writes.isEmpty());
	}

	@Test
	public void unreadableSavedGoalsAreRerolled()
	{
		store.values.put("rsprofile.a." + DailyGoals.DAY_KEY, DAY.toString());
		store.values.put("rsprofile.a." + DailyGoals.STATE_KEY, "garbage");
		daily.load(DAY, random);
		assertEquals(3, daily.goals().goals().size());
		assertNotEquals("garbage", store.values.get("rsprofile.a." + DailyGoals.STATE_KEY));
	}

	@Test
	public void decodeRejectsBadData()
	{
		assertNull(DailyGoals.decode(null));
		assertNull(DailyGoals.decode(""));
		assertNull(DailyGoals.decode("1|BODY_FLIP,0,0,"));
		assertNull(DailyGoals.decode("1|NOPE,0,0,|GRABS,0,0,|SPIN_360,0,0,"));
		assertNull(DailyGoals.decode("1|GRABS,NaN,0,|BODY_FLIP,0,0,|SPIN_360,0,0,"));
		assertNull(DailyGoals.decode("1|GRABS,-1,0,|BODY_FLIP,0,0,|SPIN_360,0,0,"));
		assertNull(DailyGoals.decode("1|GRABS,0,0,|GRABS,0,0,|SPIN_360,0,0,"));
		// unknown trick names (a trick removed in an update) are dropped, not fatal
		List<SessionGoals.Goal> ok = DailyGoals.decode("1|DIFFERENT_FLIPS,2,0,KICKFLIP+GONE|GRABS,3,1,|SPIN_360,0,0,");
		assertEquals(3, ok.size());
		assertEquals("2/5", ok.get(0).progressText());
		assertTrue(ok.get(1).isDone());
	}

	@Test
	public void roundTrips()
	{
		SessionGoals g = new SessionGoals();
		g.start(Arrays.asList(SessionGoals.Type.DIFFERENT_GRINDS, SessionGoals.Type.GRIND_SECONDS,
			SessionGoals.Type.CLEAN_LANDINGS));
		g.onLanded(new ComboScorer.Summary(Arrays.asList(Trick.FIFTY_FIFTY), 4.25f, 0f, 0, 900, 1, true, 0, false));
		String s = DailyGoals.encode(g.goals());
		assertEquals(s, DailyGoals.encode(DailyGoals.decode(s)));
	}

	@Test
	public void savedGoalsAreProgressNotSettings()
	{
		assertTrue(ProgressionService.isProgressKey(DailyGoals.DAY_KEY));
		assertTrue(ProgressionService.isProgressKey(DailyGoals.STATE_KEY));
	}
}

