package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.FootPhysics;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.render.FootBody.Gait;
import org.junit.Test;

public class FootBodyTest
{
	@Test
	public void gaitFollowsSpeedWithHysteresis()
	{
		assertEquals(Gait.IDLE, FootBody.gait(Gait.IDLE, 0f, false));
		assertEquals(Gait.IDLE, FootBody.gait(Gait.IDLE, FootBody.IDLE_TO_WALK - 1f, false));
		assertEquals(Gait.WALK, FootBody.gait(Gait.IDLE, FootPhysics.WALK_SPEED, false));
		// slowing through the band keeps walking, below it stands
		assertEquals(Gait.WALK, FootBody.gait(Gait.WALK, FootBody.IDLE_TO_WALK - 1f, false));
		assertEquals(Gait.IDLE, FootBody.gait(Gait.WALK, FootBody.WALK_TO_IDLE - 1f, false));
		assertEquals(Gait.RUN, FootBody.gait(Gait.WALK, FootPhysics.SPRINT_SPEED, false));
		assertEquals(Gait.RUN, FootBody.gait(Gait.IDLE, FootPhysics.SPRINT_SPEED, false));
		assertEquals(Gait.RUN, FootBody.gait(Gait.RUN, FootBody.WALK_TO_RUN - 1f, false));
		assertEquals(Gait.WALK, FootBody.gait(Gait.RUN, FootBody.RUN_TO_WALK - 1f, false));
		assertEquals(Gait.IDLE, FootBody.gait(Gait.RUN, 0f, false));
	}

	@Test
	public void walkAndSprintSpeedsSitClearOfTheBands()
	{
		assertTrue(FootPhysics.WALK_SPEED > FootBody.IDLE_TO_WALK);
		assertTrue(FootPhysics.WALK_SPEED < FootBody.RUN_TO_WALK);
		assertTrue(FootPhysics.SPRINT_SPEED > FootBody.WALK_TO_RUN);
		assertTrue(FootBody.WALK_TO_IDLE < FootBody.IDLE_TO_WALK);
		assertTrue(FootBody.RUN_TO_WALK < FootBody.WALK_TO_RUN);
	}

	@Test
	public void inTheAirTheBodyStandsForTheTuck()
	{
		assertEquals(Gait.IDLE, FootBody.gait(Gait.RUN, FootPhysics.SPRINT_SPEED, true));
	}

	@Test
	public void aJumpPopsTucksAndLands()
	{
		FootBody body = new FootBody();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		body.fill(s, FootPhysics.WALK_SPEED, false, false, 0f);
		assertEquals(SkaterState.ROLLING, s.state);
		assertTrue(s.onFoot);
		assertFalse(s.popped);
		assertEquals(Gait.WALK, body.gait());

		body.fill(s, FootPhysics.WALK_SPEED, true, true, 500f);
		assertEquals(SkaterState.AIRBORNE, s.state);
		assertTrue(s.popped);
		assertFalse(s.rolledOff);
		body.fill(s, FootPhysics.WALK_SPEED, true, true, -480f);
		assertFalse(s.popped);
		assertFalse(s.landed);

		body.fill(s, FootPhysics.WALK_SPEED, false, false, 0f);
		assertTrue(s.landed);
		assertEquals(480f, s.landingSpeed, 0f);
		assertEquals(SkaterState.ROLLING, s.state);
		body.fill(s, FootPhysics.WALK_SPEED, false, false, 0f);
		assertFalse(s.landed);
	}

	@Test
	public void aFallIsNotAJump()
	{
		FootBody body = new FootBody();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		body.fill(s, 0f, false, false, 0f);
		body.fill(s, 0f, true, false, -10f);
		assertFalse(s.popped);
		assertTrue(s.rolledOff);
	}

	@Test
	public void theOnFootTuckIsLighterThanATrickAndAFallBarelyBends()
	{
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		s.state = SkaterState.AIRBORNE;
		s.onFoot = true;
		s.verticalSpeed = 100f;
		assertEquals(Tuning.FOOT_JUMP_TUCK, SkaterPoseRig.crouchTarget(s, 0.3f, true), 0f);
		assertEquals(Tuning.FOOT_FALL_TUCK, SkaterPoseRig.crouchTarget(s, 0.3f, false), 0f);
		// straight legs just after take-off, reaching for the ground when falling fast
		assertEquals(Tuning.POP_EXTEND, SkaterPoseRig.crouchTarget(s, 0.05f, true), 0f);
		s.verticalSpeed = -Tuning.LAND_REACH_SPEED - 1f;
		assertEquals(Tuning.LAND_REACH, SkaterPoseRig.crouchTarget(s, 0.3f, true), 0f);
		assertTrue(Tuning.FOOT_JUMP_TUCK < Tuning.TRICK_TUCK);
		assertTrue(Tuning.FOOT_FALL_TUCK < Tuning.FOOT_JUMP_TUCK);
	}

	@Test
	public void theRigTucksOnAFootJumpAndSettlesAfter()
	{
		FootBody body = new FootBody();
		SkaterPoseRig rig = new SkaterPoseRig();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		BodyPose pose = new BodyPose();
		float dt = 1f / 50f;
		body.fill(s, 0f, false, false, 0f);
		rig.update(s, dt);
		float vh = FootPhysics.JUMP_VH;
		float minLeg = 1f;
		for (int i = 0; i < 25; i++)
		{
			body.fill(s, 0f, true, true, vh);
			rig.update(s, dt);
			rig.writeTo(pose);
			minLeg = Math.min(minLeg, pose.legScale);
			vh -= 2000f * dt;
		}
		assertTrue("knees bend in the jump: " + minLeg, minLeg < 0.9f);
		for (int i = 0; i < 100; i++)
		{
			body.fill(s, 0f, false, false, 0f);
			rig.update(s, dt);
		}
		rig.writeTo(pose);
		assertTrue(pose.isNeutral());
	}

	@Test
	public void resetForgetsTheFlight()
	{
		FootBody body = new FootBody();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		body.fill(s, FootPhysics.SPRINT_SPEED, true, true, 100f);
		body.reset();
		assertEquals(Gait.IDLE, body.gait());
		body.fill(s, 0f, false, false, 0f);
		assertFalse(s.landed);
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import com.gielinorskate.physics.FootPhysics;
import org.junit.Test;

public class GaitPlaybackTest
{
	private static final int[] LENGTHS = {4, 4, 4, 4};

	@Test
	public void rateMatchesTheWalkerSpeedToTheGamesGaitSpeed()
	{
		assertEquals(1.5f, GaitPlayback.rate(FootBody.Gait.WALK, FootPhysics.WALK_SPEED), 1e-4f);
		assertEquals(2f, GaitPlayback.rate(FootBody.Gait.RUN, FootPhysics.SPRINT_SPEED), 1e-4f);
		assertEquals(1f, GaitPlayback.rate(FootBody.Gait.IDLE, FootPhysics.SPRINT_SPEED), 0f);
	}

	@Test
	public void rateIsNeverSlowerThanTheGameOrWildlyFaster()
	{
		assertEquals(1f, GaitPlayback.rate(FootBody.Gait.WALK, 50f), 0f);
		assertEquals(Tuning.MAX_RATE, GaitPlayback.rate(FootBody.Gait.RUN, 100000f), 0f);
		assertEquals(1f, GaitPlayback.rate(FootBody.Gait.WALK, Float.NaN), 0f);
	}

	@Test
	public void atTheGamesRateNothingIsAdded()
	{
		GaitPlayback g = new GaitPlayback();
		for (int i = 0; i < 100; i++)
		{
			assertEquals(-1, g.advance(0, LENGTHS, 1f, 0.02f));
		}
	}

	@Test
	public void doubleRateAddsOneExtraTickPerTick()
	{
		GaitPlayback g = new GaitPlayback();
		// 1 s at 2x is 50 extra client ticks: 12 whole 4-tick frames (48 ticks), 2 left over
		int frame = 0;
		int skips = 0;
		for (int i = 0; i < 50; i++)
		{
			int f = g.advance(frame, LENGTHS, 2f, 0.02f);
			if (f >= 0)
			{
				skips += Math.floorMod(f - frame, LENGTHS.length);
				frame = f;
			}
		}
		assertEquals(12, skips);
		assertEquals(0, frame);
	}

	@Test
	public void framesWrapRoundTheCycle()
	{
		GaitPlayback g = new GaitPlayback();
		// 0.12 s at 3x: 12 extra ticks, 3 frames on from frame 3 -> frame 2
		assertEquals(2, g.advance(3, LENGTHS, 3f, 0.12f));
	}

	@Test
	public void aLongHitchSkipsAtMostOneCycleAndOwesNoMore()
	{
		GaitPlayback g = new GaitPlayback();
		assertEquals(0, g.advance(0, LENGTHS, 3f, 10f));
		// nothing piled up from the hitch: one more tick is not a frame
		assertEquals(-1, g.advance(0, LENGTHS, 2f, 0.02f));
	}

	@Test
	public void unusableAnimationsAreLeftAlone()
	{
		GaitPlayback g = new GaitPlayback();
		assertEquals(-1, g.advance(0, null, 2f, 1f));
		assertEquals(-1, g.advance(0, new int[0], 2f, 1f));
		assertEquals(-1, g.advance(7, LENGTHS, 2f, 1f));
		assertEquals(-1, g.advance(-1, LENGTHS, 2f, 1f));
		// zero-length frames count as one tick, so the loop always ends
		assertEquals(1, g.advance(0, new int[]{0, 0}, 2f, 0.02f));
	}

	@Test
	public void resetDropsTheCarriedOverTime()
	{
		GaitPlayback g = new GaitPlayback();
		assertEquals(-1, g.advance(0, LENGTHS, 2f, 0.06f));
		g.reset();
		// 3 + 2 ticks would make a whole frame without the reset
		assertEquals(-1, g.advance(0, LENGTHS, 2f, 0.04f));
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

/**
 * Every grab, end to end on the 200-unit test body: the rig's pose held in the air, the board drawn as the renderer
 * draws it (the grab's tweak, the lift), then the mesh deformed. The hand ends on its spot of the board, the feet on
 * the lifted board, the knees up in front of the chest and the free arm out.
 */
public class GrabBodyTest
{
	private static final float DT = 1 / 60f;
	private static final Trick[] GRABS = {Trick.INDY, Trick.MELON, Trick.MUTE, Trick.STALEFISH, Trick.NOSEGRAB,
		Trick.TAILGRAB, Trick.CRAIL, Trick.TWEAKED_INDY, Trick.METHOD, Trick.JAPAN, Trick.TWEAKED_STALEFISH,
		Trick.NOSEBONE, Trick.TAILBONE, Trick.CRAIL_TWEAK};
	/** The grab keys: Q (left), E (right), and not known (a party ghost). */
	private static final int[] KEYS = {1, -1, 0};
	/** How close (units) the hand must end to its spot on the board. */
	private static final float HAND_TOLERANCE = 6f;

	/** The pose the rig holds {@code grab} in after half a second in the air, with the board as drawn. */
	private static BodyPose held(Trick grab, int key)
	{
		SkaterPoseRig rig = new SkaterPoseRig();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		s.state = SkaterState.AIRBORNE;
		s.popped = true;
		rig.update(s, DT);
		s.popped = false;
		s.hold = grab;
		s.grabHand = key;
		for (int i = 0; i < 30; i++)
		{
			rig.update(s, DT);
		}
		BodyPose p = new BodyPose();
		rig.writeTo(p);
		drawBoard(p, grab);
		return p;
	}

	/** What the renderer writes: the board's drawn roll, pitch, deck lift and the grab's lift. */
	private static void drawBoard(BodyPose p, Trick grab)
	{
		p.boardRoll = GrabPose.boardRoll(grab);
		p.boardPitch = GrabPose.boardPitch(grab);
		p.deckLift = Math.round(BoardPlacement.deckLift(p.boardPitch));
		p.boardLift = BoardPlacement.grabLift(p.feetLift, false);
	}

	private static float[] target(BodyPose p)
	{
		float[] t = new float[3];
		BoardPlacement.grabTarget(p.grabAlong, p.grabAcross, p.grabBoardY, p.boardRoll, p.boardPitch,
			p.deckLift - p.boardLift, t);
		return t;
	}

	private static int hand(float side)
	{
		Humanoid rest = new Humanoid();
		ArmLocator a = new ArmLocator();
		assertTrue(a.locate(rest.xs, rest.ys, rest.zs, rest.n, side));
		return a.handIndex;
	}

	private static float distance(Humanoid b, int i, float[] t)
	{
		float dx = b.xs[i] - t[0];
		float dy = b.ys[i] - t[1];
		float dz = b.zs[i] - t[2];
		return (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
	}

	private static Humanoid deformed(BodyPose p)
	{
		Humanoid b = new Humanoid();
		MeshDeformer.deform(b.xs, b.ys, b.zs, b.n, p);
		return b;
	}

	@Test
	public void everyGrabsHandEndsOnItsSpotOfTheBoard()
	{
		for (Trick grab : GRABS)
		{
			for (int key : KEYS)
			{
				BodyPose p = held(grab, key);
				assertEquals(grab + " arm", 1f, p.armWeight, 0.01f);
				float d = distance(deformed(p), hand(p.armSide), target(p));
				assertTrue(grab + " key " + key + ": hand " + d + " from its spot", d < HAND_TOLERANCE);
			}
		}
	}

	@Test
	public void eachGrabIsHeldWithItsOwnHand()
	{
		// front (left, +x) hand: melon, mute, nosegrab; back (right): indy, stalefish, crail; tailgrab: the key's
		Trick[] front = {Trick.MELON, Trick.METHOD, Trick.MUTE, Trick.JAPAN, Trick.NOSEGRAB, Trick.NOSEBONE};
		Trick[] back = {Trick.INDY, Trick.TWEAKED_INDY, Trick.STALEFISH, Trick.TWEAKED_STALEFISH, Trick.CRAIL,
			Trick.CRAIL_TWEAK};
		for (int key : KEYS)
		{
			for (Trick g : front)
			{
				assertEquals(g + " key " + key, 1f, held(g, key).armSide, 0f);
			}
			for (Trick g : back)
			{
				assertEquals(g + " key " + key, -1f, held(g, key).armSide, 0f);
			}
		}
		assertEquals(1f, held(Trick.TAILGRAB, 1).armSide, 0f);
		assertEquals(-1f, held(Trick.TAILGRAB, -1).armSide, 0f);
		assertEquals(-1f, held(Trick.TAILGRAB, 0).armSide, 0f);
	}

	@Test
	public void anEdgeGrabsHandStaysOnItsOwnSideOfTheBody()
	{
		// the hand never crosses the centre line to the middle of the board, in front of the crotch (a Q Indy
		// held with the front hand ended 2.3 units past it)
		for (Trick grab : new Trick[]{Trick.INDY, Trick.MELON, Trick.MUTE, Trick.STALEFISH, Trick.TWEAKED_INDY,
			Trick.METHOD})
		{
			for (int key : KEYS)
			{
				BodyPose p = held(grab, key);
				Humanoid b = deformed(p);
				float x = b.xs[hand(p.armSide)] * p.armSide;
				assertTrue(grab + " key " + key + ": hand " + x + " from the centre line", x > 4f);
			}
		}
	}

	@Test
	public void theFeetStayOnTheLiftedBoard()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			assertEquals(grab + " lift", Tuning.GRAB_LIFT, p.boardLift, 1f);
			Humanoid rest = new Humanoid();
			Humanoid b = deformed(p);
			// the middle of the deck top as the board is drawn (its tweak, the lift), in the puppet's space: board
			// (x, y, z) = (puppet z, puppet y - 20 - deckLift + lift, -puppet x)
			float[] deck = BoardPlacement.pose(new float[]{0f, -BoardGeometry.BOARD_TOP, 0f}, p.boardRoll,
				p.boardPitch);
			float deckY = deck[1] + BoardGeometry.BOARD_TOP + BoardPlacement.FOOT_CLEARANCE + p.deckLift - p.boardLift;
			float sum = 0f;
			int count = 0;
			for (int i = 0; i < rest.n; i++)
			{
				if (rest.ys[i] == 0f)
				{
					sum += b.ys[i];
					count++;
					// over the deck, not off its toe or heel edge
					assertTrue(grab + " sole " + i + " z " + b.zs[i], Math.abs(b.zs[i]) < 6f);
				}
			}
			// the soles stand on the middle of the deck (the tweak's tilt under each foot is as it always was)
			assertEquals(grab + " soles above the deck", BoardPlacement.FOOT_CLEARANCE, deckY - sum / count, 1.5f);
		}
	}

	@Test
	public void theFeetFollowTheLiftAsItEasesInAndOut()
	{
		for (float lift = 0f; lift <= 30f; lift += 2.5f)
		{
			for (float fold = 0f; fold <= 1f; fold += 0.25f)
			{
				BodyPose p = new BodyPose();
				p.legScale = 0.55f;
				p.torsoBend = 0.6f;
				p.kneeFold = fold;
				p.armWeight = fold;
				p.boardLift = lift;
				Humanoid rest = new Humanoid();
				Humanoid b = deformed(p);
				for (int i = 0; i < rest.n; i++)
				{
					if (rest.ys[i] == 0f)
					{
						assertEquals("fold " + fold + " lift " + lift, -lift, b.ys[i], 0.5f);
					}
				}
			}
		}
	}

	@Test
	public void theKneesComeUpInFrontOfTheChest()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			Humanoid rest = new Humanoid();
			Humanoid b = deformed(p);
			float hipY = -MeshDeformer.hipHeight(-200f) * p.legScale;
			float frontmost = Float.MAX_VALUE;
			float kneeY = 0f;
			for (int i = 0; i < rest.n; i++)
			{
				// the legs, halfway down
				if (Math.abs(rest.ys[i] + 50f) < 0.1f && Math.abs(rest.xs[i]) <= 12f && b.zs[i] < frontmost)
				{
					frontmost = b.zs[i];
					kneeY = b.ys[i];
				}
			}
			assertTrue(grab + " knee z " + frontmost, frontmost < -25f);
			// up near the hips' height, above the lifted feet (a toe-side roll tips the knees down a little)
			assertTrue(grab + " knee y " + kneeY + " hips " + hipY, kneeY < -p.boardLift - 4f && kneeY > hipY - 15f);
		}
	}

	@Test
	public void theFreeArmSwingsOutForBalance()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			float side = -p.armSide;
			ArmLocator a = new ArmLocator();
			Humanoid rest = new Humanoid();
			assertTrue(a.locate(rest.xs, rest.ys, rest.zs, rest.n, side));
			Humanoid b = deformed(p);
			int h = a.handIndex;
			// out along the board well past where it hung on its own side, and not hanging below the hips
			float hipY = -MeshDeformer.hipHeight(-200f) * p.legScale;
			assertTrue(grab + " free hand x " + b.xs[h], b.xs[h] * side > Humanoid.ARM_OUTER + 15f);
			assertTrue(grab + " free hand y " + b.ys[h] + " hips " + hipY, b.ys[h] < hipY - 20f);
		}
	}


	@Test
	public void outsideAGrabTheLegsAndHandsSquashAsBefore()
	{
		// no knee fold, no lift, no reach: every point below the hips is the plain squash, the hands included
		BodyPose p = new BodyPose();
		p.legScale = 0.62f;
		p.torsoBend = 0.34f;
		Humanoid rest = new Humanoid();
		Humanoid b = deformed(p);
		float hip = MeshDeformer.hipHeight(-200f);
		for (int i = 0; i < rest.n; i++)
		{
			if (rest.ys[i] > -hip)
			{
				assertEquals(rest.ys[i] * 0.62f, b.ys[i], 0f);
				assertEquals(rest.xs[i], b.xs[i], 0f);
				assertEquals(rest.zs[i], b.zs[i], 0f);
			}
		}
		assertEquals(0, BoardPlacement.grabLift(0f, false));
	}

	@Test
	public void brokenGrabInputsNeverExplodeTheMesh()
	{
		float[] bad = {Float.NaN, Float.POSITIVE_INFINITY, Float.NEGATIVE_INFINITY, -50f, 1e6f};
		for (float v : bad)
		{
			BodyPose p = held(Trick.INDY, 0);
			p.kneeFold = v;
			p.boardLift = v;
			Humanoid b = deformed(p);
			for (int i = 0; i < b.n; i++)
			{
				for (float c : new float[]{b.xs[i], b.ys[i], b.zs[i]})
				{
					assertTrue(v + ": vertex " + i + " " + c, !Float.isNaN(c) && Math.abs(c) < 400f);
				}
			}
			int lift = BoardPlacement.grabLift(v, false);
			assertTrue(v + ": lift " + lift, lift >= 0 && lift <= Tuning.MAX_GRAB_LIFT);
		}
	}
}

