package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Grabs;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickKind;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

public class GrabPoseTest
{
	@Test
	public void noseAndTailGrabsReachAndPitchTheirWay()
	{
		assertTrue(GrabPose.torsoLean(Trick.NOSEGRAB) > 0.3f);
		assertTrue(Math.abs(GrabPose.boardPitch(Trick.NOSEGRAB)) > 0.2f);
		assertTrue(GrabPose.torsoLean(Trick.TAILGRAB) < -0.3f);
		assertTrue(Math.abs(GrabPose.boardPitch(Trick.TAILGRAB)) > 0.2f);
		// the two pitch the board opposite ways: each lifts its own end (see below)
		assertTrue(GrabPose.boardPitch(Trick.NOSEGRAB) * GrabPose.boardPitch(Trick.TAILGRAB) < 0f);
		// a crail is the back hand reaching all the way to the nose
		assertTrue(GrabPose.torsoLean(Trick.CRAIL) > 0.3f);
	}

	@Test
	public void toeSideGrabsLeanToTheChestAndHeelSideOnesAway()
	{
		// BodyPose.roll: negative leans the head toward the chest (the toe side)
		for (Trick toe : new Trick[]{Trick.INDY, Trick.MUTE})
		{
			assertTrue(toe.toString(), GrabPose.bodyRoll(toe) < 0f);
			assertTrue(toe.toString(), GrabPose.boardRoll(toe) > 0f);
		}
		for (Trick heel : new Trick[]{Trick.MELON, Trick.STALEFISH})
		{
			assertTrue(heel.toString(), GrabPose.bodyRoll(heel) > 0f);
			assertTrue(heel.toString(), GrabPose.boardRoll(heel) < 0f);
		}
	}

	@Test
	public void tweaksGoFurtherTheSameWay()
	{
		for (Trick t : Trick.values())
		{
			Trick tw = Grabs.tweaked(t);
			if (tw == null)
			{
				continue;
			}
			assertEquals(Tuning.TWEAK * GrabPose.torsoLean(t), GrabPose.torsoLean(tw), 1e-6f);
			assertEquals(Tuning.TWEAK * GrabPose.bodyRoll(t), GrabPose.bodyRoll(tw), 1e-6f);
			assertEquals(Tuning.TWEAK * GrabPose.boardPitch(t), GrabPose.boardPitch(tw), 1e-6f);
			assertEquals(Tuning.TWEAK * GrabPose.boardRoll(t), GrabPose.boardRoll(tw), 1e-6f);
		}
	}

	@Test
	public void everyGrabHasItsOwnPoseAndNothingElseHasOne()
	{
		Set<String> poses = new HashSet<>();
		for (Trick t : Trick.values())
		{
			String pose = GrabPose.torsoLean(t) + "/" + GrabPose.bodyRoll(t) + "/" + GrabPose.boardPitch(t) + "/"
				+ GrabPose.boardRoll(t);
			if (t.kind == TrickKind.GRAB)
			{
				assertTrue("same pose as another grab: " + t, poses.add(pose));
			}
			else
			{
				assertEquals(t.toString(), "0.0/0.0/0.0/0.0", pose);
			}
		}
		assertEquals("0.0/0.0/0.0/0.0", GrabPose.torsoLean(null) + "/" + GrabPose.bodyRoll(null) + "/"
			+ GrabPose.boardPitch(null) + "/" + GrabPose.boardRoll(null));
	}

	@Test
	public void eachGrabHoldsItsPartOfTheBoard()
	{
		assertTrue(GrabPose.grabAlong(Trick.NOSEGRAB) > 35f);
		assertTrue(GrabPose.grabAlong(Trick.TAILGRAB) < -35f);
		assertTrue(GrabPose.grabAlong(Trick.CRAIL) > 35f);
		// toe- and heel-edge grabs hold the deck's edge, 13 units (half its width) either side of the centre line
		for (Trick toe : new Trick[]{Trick.INDY, Trick.MUTE, Trick.JAPAN, Trick.TWEAKED_INDY})
		{
			assertEquals(toe.toString(), -13f, GrabPose.grabAcross(toe), 0f);
		}
		for (Trick heel : new Trick[]{Trick.MELON, Trick.METHOD, Trick.STALEFISH})
		{
			assertEquals(heel.toString(), 13f, GrabPose.grabAcross(heel), 0f);
		}
		// a tweak holds the same spot as its grab
		assertEquals(GrabPose.grabAlong(Trick.TAILGRAB), GrabPose.grabAlong(Trick.TAILBONE), 0f);
		assertEquals(GrabPose.grabBoardY(Trick.NOSEGRAB), GrabPose.grabBoardY(Trick.NOSEBONE), 0f);
	}

	@Test
	public void onlyGrabsReach()
	{
		Set<Trick> reaching = new HashSet<>();
		for (Trick t : Trick.values())
		{
			if (GrabPose.reaches(t))
			{
				reaching.add(t);
				assertEquals(t.toString(), TrickKind.GRAB, t.kind);
			}
		}
		assertTrue(reaching.contains(Trick.INDY));
		assertTrue(reaching.contains(Trick.CRAIL_TWEAK));
		assertTrue(!GrabPose.reaches(null));
	}

	@Test
	public void aGhostsGrabUsesTheUsualHand()
	{
		assertTrue(GrabPose.usualLeftHand(Trick.MELON));
		assertTrue(GrabPose.usualLeftHand(Trick.METHOD));
		assertTrue(GrabPose.usualLeftHand(Trick.NOSEGRAB));
		assertTrue(!GrabPose.usualLeftHand(Trick.INDY));
		assertTrue(!GrabPose.usualLeftHand(Trick.CRAIL));
	}

	@Test
	public void everyGrabKeyAndAimIsHeldWithTheGrabsOwnHand()
	{
		// the keys' unaimed grabs (Q an Indy, E a Melon) are not crossed over to the key's hand
		assertTrue(!GrabPose.leftHand(Grabs.pick(true, null), 1));
		assertTrue(GrabPose.leftHand(Grabs.pick(false, null), -1));
		for (int key : new int[]{1, -1, 0})
		{
			assertTrue(GrabPose.leftHand(Trick.MUTE, key));
			assertTrue(GrabPose.leftHand(Trick.JAPAN, key));
			assertTrue(GrabPose.leftHand(Trick.NOSEBONE, key));
			assertTrue(!GrabPose.leftHand(Trick.TWEAKED_STALEFISH, key));
			assertTrue(!GrabPose.leftHand(Trick.CRAIL_TWEAK, key));
		}
		// a tailgrab is either hand's: the key's, the back hand when not known
		assertTrue(GrabPose.leftHand(Trick.TAILGRAB, 1));
		assertTrue(!GrabPose.leftHand(Trick.TAILBONE, -1));
		assertTrue(!GrabPose.leftHand(Trick.TAILGRAB, 0));
		// every aimed pick already matches its hand
		for (Grabs.Aim aim : new Grabs.Aim[]{Grabs.Aim.NOSE, Grabs.Aim.TOE, Grabs.Aim.HEEL, Grabs.Aim.TAIL})
		{
			assertEquals(aim + " left", true, GrabPose.leftHand(Grabs.pick(true, aim), 1));
			assertEquals(aim + " right", false, GrabPose.leftHand(Grabs.pick(false, aim), -1));
		}
	}

	/**
	 * The tweak brings the grabbed part of the board up to the hand: the spot, as drawn with the tweak's pitch (and
	 * the deck lift that pitch gives the body), is higher relative to the soles than on a flat board. The drawn
	 * pitch turns the board's +z end up, and a spot along the board toward the nose sits at board -z for regular
	 * stance (GrabReach), so a nose-end grab pitches negative.
	 */
	@Test
	public void theTweakLiftsTheGrabbedEndOfTheBoardTowardTheHand()
	{
		for (Trick t : Trick.values())
		{
			float pitch = GrabPose.boardPitch(t);
			if (!GrabPose.reaches(t) || pitch == 0f)
			{
				continue;
			}
			float[] flat = new float[3];
			float[] tweaked = new float[3];
			BoardPlacement.grabTarget(GrabPose.grabAlong(t), GrabPose.grabAcross(t), GrabPose.grabBoardY(t), 0f, 0f, 0f,
				flat);
			BoardPlacement.grabTarget(GrabPose.grabAlong(t), GrabPose.grabAcross(t), GrabPose.grabBoardY(t), 0f, pitch,
				BoardPlacement.deckLift(pitch), tweaked);
			// y down: the grabbed spot comes up toward the body
			assertTrue(t + ": spot y " + tweaked[1] + " vs flat " + flat[1], tweaked[1] < flat[1] - 1f);
		}
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class GrabReachTest
{
	private static float[] target(float along, float across, float by, float roll, float pitch, float lift)
	{
		float[] out = new float[3];
		BoardPlacement.grabTarget(along, across, by, roll, pitch, lift, out);
		return out;
	}

	@Test
	public void aFlatBoardsToeEdgeIsJustBelowTheSolesOnTheChestSide()
	{
		float[] t = target(-6f, -13f, -14f, 0f, 0f, 0f);
		assertEquals(-6f, t[0], 1e-4f);
		// board y -14 is 2 under the deck top (-16), which is FOOT_CLEARANCE under the soles
		assertEquals(-14f + BoardGeometry.BOARD_TOP + BoardPlacement.FOOT_CLEARANCE, t[1], 1e-4f);
		assertEquals(-13f, t[2], 1e-4f);
	}


	@Test
	public void theTargetTurnsWithTheBoardsDrawnRollAndPitch()
	{
		float along = 30f;
		float across = -13f;
		float by = -14f;
		float roll = 0.4f;
		float pitch = 0.3f;
		float lift = BoardPlacement.deckLift(pitch);
		float[] t = target(along, across, by, roll, pitch, lift);
		// the board's own pose of the same point, mapped to puppet space
		float[] b = BoardPlacement.pose(new float[]{across, by, -along}, roll, pitch);
		assertEquals(-b[2], t[0], 1e-3f);
		assertEquals(b[1] + BoardGeometry.BOARD_TOP + BoardPlacement.FOOT_CLEARANCE + lift, t[1], 1e-3f);
		assertEquals(b[0], t[2], 1e-3f);
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class HandAnchorTest
{
	private static final float DT = 1f / 50f;

	private static HandAnchor active()
	{
		HandAnchor a = new HandAnchor();
		a.setActive(true);
		return a;
	}

	@Test
	public void withNoReadingItIsTheFixedAnchor()
	{
		HandAnchor a = active();
		a.step(DT);
		assertEquals(-CarryPose.HAND_SIDE, a.x(), 0f);
		assertEquals(-CarryPose.HAND_HEIGHT, a.y(), 0f);
		assertEquals(0f, a.z(), 0f);
	}

	@Test
	public void followsTheRightHandOfTheDrawnMesh()
	{
		Humanoid b = new Humanoid();
		HandAnchor a = active();
		a.sample(b.xs, b.ys, b.zs, b.n);
		a.step(DT);
		// the first reading is taken as is
		assertEquals(Humanoid.HAND_Y, a.y(), 3f);
		assertEquals(-(Humanoid.ARM_INNER + Humanoid.ARM_OUTER) / 2f, a.x(), 3.5f);
	}

	@Test
	public void aSwingingHandIsFollowedWithinAFewFrames()
	{
		Humanoid b = new Humanoid();
		HandAnchor a = active();
		a.sample(b.xs, b.ys, b.zs, b.n);
		a.step(DT);
		float z0 = a.z();
		// the hand swings 30 forward
		for (int i = 0; i < b.n; i++)
		{
			if (b.isArm(i, -1f) && b.ys[i] > -100f)
			{
				b.zs[i] -= 30f;
			}
		}
		for (int k = 0; k < 4; k++)
		{
			a.sample(b.xs, b.ys, b.zs, b.n);
			a.step(DT);
		}
		// 0.08 s against a 0.025 s easing: 96% of the way
		assertEquals(z0 - 30f, a.z(), 2f);
	}

	@Test
	public void aStaleOrBadReadingEasesBackToTheFixedAnchor()
	{
		Humanoid b = new Humanoid();
		HandAnchor a = active();
		a.sample(b.xs, b.ys, b.zs, b.n);
		for (int k = 0; k < 100; k++)
		{
			a.step(DT);
		}
		assertEquals(-CarryPose.HAND_HEIGHT, a.y(), 0.5f);
		a.sample(new float[]{0f}, new float[]{0f}, new float[]{0f}, 1);
		a.step(DT);
		assertEquals(-CarryPose.HAND_HEIGHT, a.y(), 0.5f);
	}

	@Test
	public void inactiveItReadsNothing()
	{
		Humanoid b = new Humanoid();
		HandAnchor a = new HandAnchor();
		a.sample(b.xs, b.ys, b.zs, b.n);
		a.setActive(true);
		a.step(DT);
		assertEquals(-CarryPose.HAND_HEIGHT, a.y(), 0f);
	}
}

package com.gielinorskate.render;

/**
 * A blocky 200-unit test body in puppet model space (y down, soles at 0, facing -z, left hand +x): two legs up to
 * the hips at -90, a torso 32 wide up to -160, a head to -200, and two arms hanging at the sides (x 19..25) from
 * the shoulders (-158) down to the hands (-86), a vertex row every 6 units.
 */
final class Humanoid
{
	static final float ARM_INNER = 19f;
	static final float ARM_OUTER = 25f;
	static final float ARM_TOP = -158f;
	static final float HAND_Y = -86f;

	final float[] xs;
	final float[] ys;
	final float[] zs;
	final int n;

	Humanoid()
	{
		float[][] v = new float[3][400];
		int i = 0;
		for (float x : new float[]{-12f, -4f, 4f, 12f})
		{
			for (float y = 0f; y >= -90f; y -= 10f)
			{
				i = put(v, i, x, y, 0f);
			}
		}
		for (float x : new float[]{-16f, -8f, 0f, 8f, 16f})
		{
			for (float y = -90f; y >= -160f; y -= 10f)
			{
				i = put(v, i, x, y, -8f);
				i = put(v, i, x, y, 8f);
			}
		}
		for (float x : new float[]{-8f, 0f, 8f})
		{
			for (float y = -160f; y >= -200f; y -= 10f)
			{
				i = put(v, i, x, y, 0f);
			}
		}
		for (float side : new float[]{-1f, 1f})
		{
			for (float x : new float[]{ARM_INNER, ARM_OUTER})
			{
				for (float y = ARM_TOP; y <= HAND_Y + 0.01f; y += 6f)
				{
					i = put(v, i, side * x, y, -3f);
					i = put(v, i, side * x, y, 3f);
				}
			}
		}
		n = i;
		xs = v[0];
		ys = v[1];
		zs = v[2];
	}

	private static int put(float[][] v, int i, float x, float y, float z)
	{
		v[0][i] = x;
		v[1][i] = y;
		v[2][i] = z;
		return i + 1;
	}

	/** True for an arm vertex on {@code side}. */
	boolean isArm(int i, float side)
	{
		return xs[i] * side >= ARM_INNER - 0.01f && ys[i] >= ARM_TOP - 0.01f;
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

/** The idle pose given back on exit follows what the game set while skating. */
public class IdlePoseTrackerTest
{
	private static final int UNARMED = 808;
	private static final int TWO_HANDED = 2561;
	private static final int STANCE = 1000;
	private static final int CROUCH = 1001;

	@Test
	public void givesBackThePoseFromBeforeSkating()
	{
		IdlePoseTracker t = new IdlePoseTracker();
		t.start(UNARMED);
		t.wrote(STANCE);
		t.observe(STANCE);
		t.wrote(CROUCH);
		t.observe(CROUCH);
		assertEquals(UNARMED, t.restorePose());
	}

	@Test
	public void aWeaponWieldedWhileSkatingChangesThePoseGivenBack()
	{
		IdlePoseTracker t = new IdlePoseTracker();
		t.start(UNARMED);
		t.wrote(STANCE);
		// the server's appearance update replaced our stance with the two-handed idle
		t.observe(TWO_HANDED);
		assertEquals(TWO_HANDED, t.restorePose());
		t.wrote(STANCE);
		t.observe(STANCE);
		assertEquals(TWO_HANDED, t.restorePose());
	}

	@Test
	public void nothingWrittenYetMeansNothingToCompare()
	{
		IdlePoseTracker t = new IdlePoseTracker();
		t.start(UNARMED);
		t.observe(UNARMED);
		assertEquals(UNARMED, t.restorePose());
		t.observe(TWO_HANDED);
		assertEquals(TWO_HANDED, t.restorePose());
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The knocked-off skater as drawn: the get-up animation squeezed into its time, the body pose, the blend. */
public class KnockdownRenderTest
{
	private static KnockdownPose pose(KnockdownPose.Stage stage, float progress, float x, float angle)
	{
		return new KnockdownPose(stage, progress, x, 0f, 0f, 0f, angle, 0.2f, 100f, 0f, 0f, 0.5f, 3f, 0.1f);
	}

	@Test
	public void theGetUpAnimationIsScrubbedThroughItsFramesByProgress()
	{
		int[] lengths = {10, 10, 20, 10};
		assertEquals(0, AnimClock.frameAt(0f, lengths));
		assertEquals(1, AnimClock.frameAt(0.25f, lengths));
		assertEquals(2, AnimClock.frameAt(0.5f, lengths));
		assertEquals(2, AnimClock.frameAt(0.7f, lengths));
		assertEquals(3, AnimClock.frameAt(0.8f, lengths));
		// the end holds the last frame
		assertEquals(3, AnimClock.frameAt(1f, lengths));
		assertEquals(3, AnimClock.frameAt(5f, lengths));
		assertEquals(0, AnimClock.frameAt(-1f, lengths));
	}

	@Test
	public void anUnusableAnimationIsLeftAlone()
	{
		assertEquals(-1, AnimClock.frameAt(0.5f, null));
		assertEquals(-1, AnimClock.frameAt(0.5f, new int[0]));
		assertEquals(-1, AnimClock.frameAt(Float.NaN, new int[]{1, 2}));
		// zero-length frames count as one tick
		assertEquals(1, AnimClock.frameAt(0.6f, new int[]{0, 0}));
	}

	@Test
	public void inTheAirTheBodyTumblesProcedurally()
	{
		BodyPose out = new BodyPose();
		KnockdownBody.write(pose(KnockdownPose.Stage.AIR, 0f, 0f, 2f), false, out);
		assertEquals(2f, out.flip, 0f);
		assertEquals(0.2f, out.roll, 0f);
		assertTrue("tucked", out.legScale < 1f);
		assertEquals(BoardPlacement.puppetFlipPivotY(), out.flipPivotY, 0f);
		// the animation flag only matters once down
		KnockdownBody.write(pose(KnockdownPose.Stage.AIR, 0f, 0f, 2f), true, out);
		assertEquals(2f, out.flip, 0f);
	}

	@Test
	public void withAnAnimationPlayingTheBodyIsNotTurnedAsWell()
	{
		BodyPose out = new BodyPose();
		KnockdownBody.write(pose(KnockdownPose.Stage.LIE, 0.5f, 0f, 1.57f), true, out);
		assertTrue(out.isNeutral());
		KnockdownBody.write(pose(KnockdownPose.Stage.GET_UP, 0.5f, 0f, 1f), true, out);
		assertTrue(out.isNeutral());
	}

	@Test
	public void proceduralLyingAndGettingUpFollowTheAngle()
	{
		BodyPose out = new BodyPose();
		KnockdownBody.write(pose(KnockdownPose.Stage.LIE, 0.5f, 0f, 1.57f), false, out);
		assertEquals(1.57f, out.flip, 0f);
		assertEquals(0f, out.roll, 0f);
		KnockdownBody.write(pose(KnockdownPose.Stage.GET_UP, 0.5f, 0f, 0.8f), false, out);
		assertEquals(0.8f, out.flip, 0f);
		assertTrue("knees bent rising", out.legScale < 1f);
	}

	@Test
	public void posesBlendBetweenSteps()
	{
		KnockdownPose a = pose(KnockdownPose.Stage.AIR, 0f, 0f, 1f);
		KnockdownPose b = pose(KnockdownPose.Stage.AIR, 0f, 20f, 2f);
		KnockdownPose m = KnockdownPose.lerp(a, b, 0.5f);
		assertEquals(10f, m.bodyX, 1e-4f);
		assertEquals(1.5f, m.bodyAngle, 1e-4f);
		assertSame(b, KnockdownPose.lerp(null, b, 0.5f));
		// a jump (a skip) is not blended
		KnockdownPose far = pose(KnockdownPose.Stage.AIR, 0f, 500f, 2f);
		assertSame(far, KnockdownPose.lerp(a, far, 0.5f));
	}

	@Test
	public void theBoardIsRaisedWhenUpsideDown()
	{
		assertEquals(0f, KnockdownPose.boardLift(0f), 1e-4f);
		assertEquals(BoardGeometry.BOARD_TOP, KnockdownPose.boardLift((float) Math.PI), 1e-3f);
		assertEquals(0f, KnockdownPose.boardLift((float) (2 * Math.PI)), 1e-3f);
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class LayeredBodyTest
{
	/** A model with vertex arrays (longer than the count, like the client's shared buffer) and a face count. */
	static final class Fake
	{
		int count;
		int faces = 2;
		float[] xs = new float[8];
		float[] ys = new float[8];
		float[] zs = new float[8];
		int deformedCalls;
	}

	static final LayeredBody.Mesh<Fake> MESH = new LayeredBody.Mesh<Fake>()
	{
		@Override
		public int count(Fake m)
		{
			return m.count;
		}

		@Override
		public int faces(Fake m)
		{
			return m.faces;
		}

		@Override
		public float[] xs(Fake m)
		{
			return m.xs;
		}

		@Override
		public float[] ys(Fake m)
		{
			return m.ys;
		}

		@Override
		public float[] zs(Fake m)
		{
			return m.zs;
		}

		@Override
		public void deformed(Fake m)
		{
			m.deformedCalls++;
		}
	};

	/** The member's real character as the client hands it out: its idle frame rebuilt into one shared buffer. */
	static final class Member implements BufferProbe.Source<Fake>
	{
		final Fake base = new Fake();
		final Fake shared = new Fake();
		/** Added to every x of the idle frame (the real character's own animation moving). */
		float idleOffset;
		boolean persistent;

		Member()
		{
			base.count = 3;
			float[] y = {0f, -90f, -200f};
			for (int i = 0; i < 3; i++)
			{
				base.xs[i] = 4f * i;
				base.ys[i] = y[i];
				base.zs[i] = -i;
			}
		}

		@Override
		public Fake get()
		{
			if (persistent)
			{
				return base;
			}
			shared.count = base.count;
			shared.faces = base.faces;
			for (int i = 0; i < base.count; i++)
			{
				shared.xs[i] = base.xs[i] + idleOffset;
				shared.ys[i] = base.ys[i];
				shared.zs[i] = base.zs[i];
			}
			return shared;
		}
	}

	/** An OSRS animation applied in place: every vertex 100 units up. */
	static final LayeredBody.Layer<Fake> LIFT = m ->
	{
		for (int i = 0; i < m.count; i++)
		{
			m.ys[i] -= 100f;
		}
		return m;
	};

	private final MeshSnapshot snap = new MeshSnapshot();
	private final BufferProbe.Probe<Fake> probe = new BufferProbe.Probe<>();
	private final BodyPose neutral = new BodyPose();

	private Fake draw(Member m, int key, boolean mayTake, LayeredBody.Layer<Fake> layer, BodyPose pose)
	{
		return LayeredBody.drawable(m, MESH, snap, key, mayTake, layer, pose, probe);
	}

	@Test
	public void theFirstIdleFrameIsSnapshottedAndDrawnFromThen()
	{
		Member m = new Member();
		Fake f = draw(m, 7, true, null, neutral);
		assertSame(m.shared, f);
		assertTrue(snap.matches(3, 2, 7));
		// the real character moves on; the ghost keeps the snapshot
		m.idleOffset = 30f;
		f = draw(m, 7, false, null, neutral);
		assertEquals(0f, f.xs[0], 0f);
		assertEquals(8f, f.xs[2], 0f);
		// and the real character's own model was never edited
		assertEquals(0f, m.base.xs[0], 0f);
	}

	@Test
	public void theLayerAnimatesTheSnapshotNotTheLiveFrame()
	{
		Member m = new Member();
		draw(m, 7, true, null, neutral);
		m.idleOffset = 30f;
		Fake f = draw(m, 7, false, LIFT, neutral);
		assertEquals(-100f, f.ys[0], 0f);
		assertEquals(0f, f.xs[0], 0f);
		assertEquals(0f, m.base.ys[0], 0f);
	}

	@Test
	public void noSnapshotYetDrawsTheLiveFrameDeformedAsBefore()
	{
		Member m = new Member();
		BodyPose lean = new BodyPose();
		lean.legScale = 0.7f;
		Fake f = draw(m, 7, false, LIFT, lean);
		assertSame(m.shared, f);
		assertFalse((snap.count >= 0));
		// not lifted: no layer without a snapshot of the plain frame
		assertTrue("not lifted: " + f.ys[2], f.ys[2] > -250f);
		assertEquals(1, f.deformedCalls);
	}

	@Test
	public void anAppearanceChangeWaitsForANewSnapshot()
	{
		Member m = new Member();
		draw(m, 7, true, null, neutral);
		m.idleOffset = 30f;
		// new gear (another key): the old snapshot is not drawn on it
		Fake f = draw(m, 8, false, LIFT, neutral);
		assertEquals(30f, f.xs[0], 0f);
		assertTrue(snap.matches(3, 2, 7));
		draw(m, 8, true, null, neutral);
		assertTrue(snap.matches(3, 2, 8));
	}

	@Test
	public void aDifferentVertexOrFaceCountIsNeverCopiedOnto()
	{
		Member m = new Member();
		draw(m, 7, true, null, neutral);
		m.base.faces = 3;
		m.idleOffset = 30f;
		Fake f = draw(m, 7, false, null, neutral);
		assertEquals(30f, f.xs[0], 0f);
		m.base.faces = 2;
		m.base.count = 2;
		f = draw(m, 7, false, null, neutral);
		assertEquals(30f, f.xs[0], 0f);
	}

	@Test
	public void aPersistentModelIsDrawnAsIsAndNeverSnapshotted()
	{
		Member m = new Member();
		m.persistent = true;
		Fake f = draw(m, 7, true, LIFT, neutral);
		assertSame(m.base, f);
		assertFalse((snap.count >= 0));
		assertEquals(0f, m.base.xs[0], 0f);
		assertEquals(0f, m.base.ys[0], 0f);
	}

	@Test
	public void aLayerThatGivesNothingBackLeavesThePlainSnapshot()
	{
		Member m = new Member();
		draw(m, 7, true, null, neutral);
		// a layer that half-wrote the buffer, then failed
		LayeredBody.Layer<Fake> broken = b ->
		{
			b.xs[0] = 999f;
			return null;
		};
		Fake f = draw(m, 7, false, broken, neutral);
		assertEquals(0f, f.xs[0], 0f);
		// another buffer handed back is not drawn: the snapshot in the proven one is
		Fake other = new Fake();
		other.count = 3;
		f = draw(m, 7, false, b -> other, neutral);
		assertSame(m.shared, f);
		assertEquals(0f, f.xs[0], 0f);
	}

	@Test
	public void thePoseDeformsTheLayeredSnapshot()
	{
		Member m = new Member();
		draw(m, 7, true, null, neutral);
		BodyPose squat = new BodyPose();
		squat.legScale = 0.7f;
		Fake f = draw(m, 7, false, null, squat);
		assertNotEquals(-200f, f.ys[2], 0.01f);
		assertTrue(f.deformedCalls > 0);
		// the snapshot itself is untouched by the deform
		f = draw(m, 7, false, null, neutral);
		assertEquals(-200f, f.ys[2], 0f);
	}

	@Test
	public void snapshotGrowsOnlyWhenNeeded()
	{
		MeshSnapshot s = new MeshSnapshot();
		float[] a = {1f, 2f, 3f, 4f};
		s.take(a, a, a, 4, 1, 1);
		float[] out = new float[4];
		s.copyInto(out, new float[4], new float[4]);
		assertEquals(4f, out[3], 0f);
		s.take(a, a, a, 2, 1, 2);
		assertTrue(s.matches(2, 1, 2));
		assertEquals(4, s.xs.length);
		s.clear();
		assertFalse((s.count >= 0));
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

public class LockBlendTest
{
	private static RenderPose pose(float x, float y, float h, float heading, SkaterState state)
	{
		return new RenderPose(x, y, h, heading, heading, 0f, 0f, 0f, state, null);
	}

	@Test
	public void passesThroughWhenNothingLocks()
	{
		LockBlend b = new LockBlend();
		RenderPose p = pose(1f, 2f, 3f, 0f, SkaterState.AIRBORNE);
		assertSame(p, b.apply(p, 0.016f));
		RenderPose q = pose(5f, 2f, 3f, 0f, SkaterState.ROLLING);
		assertSame(q, b.apply(q, 0.016f));
	}

	@Test
	public void lockStartsFromTheLastDrawnPoseAndReachesTheRailIn90Ms()
	{
		assertEquals(0.09f, LockBlend.DURATION, 0f);
		LockBlend b = new LockBlend();
		b.apply(pose(0f, 0f, 100f, 0.4f, SkaterState.AIRBORNE), 0.016f);
		RenderPose rail = pose(30f, 0f, 60f, 0f, SkaterState.GRINDING);
		// the lock frame itself is still drawn where the skater was
		RenderPose first = b.apply(rail, 0.016f);
		assertEquals(0f, first.x, 1e-4f);
		assertEquals(100f, first.h, 1e-4f);
		assertEquals(0.4f, first.heading, 1e-4f);
		assertEquals(SkaterState.GRINDING, first.state);

		RenderPose mid = b.apply(rail, LockBlend.DURATION / 2f);
		assertTrue(mid.x > 0f && mid.x < 30f);
		assertTrue(mid.h < 100f && mid.h > 60f);

		RenderPose done = b.apply(rail, LockBlend.DURATION);
		assertEquals(30f, done.x, 1e-4f);
		assertEquals(60f, done.h, 1e-4f);
		assertEquals(0f, done.heading, 1e-4f);
		assertSame(rail, b.apply(rail, 0.016f));
	}

	@Test
	public void blendIsMonotonic()
	{
		LockBlend b = new LockBlend();
		b.apply(pose(0f, 0f, 0f, 0f, SkaterState.AIRBORNE), 0.016f);
		RenderPose rail = pose(40f, 0f, 0f, 0f, SkaterState.GRINDING);
		float last = b.apply(rail, 0f).x;
		for (int i = 0; i < 20; i++)
		{
			float x = b.apply(rail, 0.006f).x;
			assertTrue(x >= last - 1e-5f);
			last = x;
		}
		assertEquals(40f, last, 1e-4f);
	}

	@Test
	public void popOffBeforeTheBlendEndsKeepsEasing()
	{
		LockBlend b = new LockBlend();
		b.apply(pose(0f, 0f, 0f, 0f, SkaterState.AIRBORNE), 0.016f);
		b.apply(pose(40f, 0f, 0f, 0f, SkaterState.GRINDING), 0.03f);
		RenderPose air = pose(44f, 0f, 10f, 0f, SkaterState.AIRBORNE);
		RenderPose out = b.apply(air, 0.03f);
		assertTrue(out.x < 44f);
		assertSame(air, b.apply(air, LockBlend.DURATION));
	}

	@Test
	public void headingBlendsTheShortWay()
	{
		LockBlend b = new LockBlend();
		b.apply(pose(0f, 0f, 0f, 3.0f, SkaterState.AIRBORNE), 0.016f);
		b.apply(pose(0f, 0f, 0f, -3.0f, SkaterState.GRINDING), 0f);
		RenderPose mid = b.apply(pose(0f, 0f, 0f, -3.0f, SkaterState.GRINDING), LockBlend.DURATION / 2f);
		// from 3.0 to -3.0 the short way passes PI, not 0
		assertTrue(Math.abs(mid.heading) > 3.0f);
	}

	@Test
	public void resetForgetsThePreviousPose()
	{
		LockBlend b = new LockBlend();
		b.apply(pose(0f, 0f, 0f, 0f, SkaterState.AIRBORNE), 0.016f);
		b.reset();
		RenderPose rail = pose(40f, 0f, 0f, 0f, SkaterState.GRINDING);
		assertSame(rail, b.apply(rail, 0.016f));
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class MeshDeformerTest
{
	/** A stick figure: soles (0), knee (-50), hip line (-90), chest (-150, 10 forward), head top (-200). */
	private static float[][] figure()
	{
		return new float[][]{
			{0f, 0f, 0f, 0f, 20f},
			{0f, -50f, -90f, -150f, -200f},
			{0f, 0f, 0f, -10f, 0f}};
	}

	private static float[][] deformed(BodyPose p)
	{
		float[][] f = figure();
		MeshDeformer.deform(f[0], f[1], f[2], f[0].length, p);
		return f;
	}

	@Test
	public void neutralPoseChangesNothing()
	{
		float[][] f = deformed(new BodyPose());
		float[][] g = figure();
		for (int a = 0; a < 3; a++)
		{
			for (int i = 0; i < g[a].length; i++)
			{
				assertEquals(g[a][i], f[a][i], 1e-4f);
			}
		}
	}

	@Test
	public void hipHeightIsAFractionOfTheModelClamped()
	{
		// 0.45 * 200 = 90
		assertEquals(90f, MeshDeformer.hipHeight(-200f), 1e-4f);
		assertEquals(Tuning.MIN_HIP, MeshDeformer.hipHeight(-20f), 0f);
		assertEquals(Tuning.MAX_HIP, MeshDeformer.hipHeight(-1000f), 0f);
		assertEquals(90f, MeshDeformer.hipHeight(0f), 1e-4f);
	}

	@Test
	public void crouchBendsTheLegsAndDropsTheUpperBodyRigidly()
	{
		BodyPose p = new BodyPose();
		p.legScale = 0.8f;
		float[][] f = deformed(p);
		// hip 90: the soles stay, the knee squashes to -50 * 0.8, everything above drops 90 * 0.2 = 18
		assertEquals(0f, f[1][0], 1e-4f);
		assertEquals(-40f, f[1][1], 1e-4f);
		assertEquals(-72f, f[1][2], 1e-4f);
		assertEquals(-182f, f[1][4], 1e-4f);
		assertEquals(20f, f[0][4], 1e-4f);
	}

	@Test
	public void squashIsContinuousAcrossTheHipLine()
	{
		BodyPose p = new BodyPose();
		p.legScale = 0.7f;
		p.torsoBend = 0.3f;
		float[] xs = {0f, 0f};
		float[] ys = {-89.99f, -90.01f};
		float[] zs = {5f, 5f};
		MeshDeformer.deform(xs, ys, zs, 2, p);
		assertEquals(ys[0], ys[1], 0.05f);
		assertEquals(zs[0], zs[1], 0.05f);
	}

	@Test
	public void torsoBendFoldsTheHeadTowardTheChest()
	{
		BodyPose p = new BodyPose();
		p.torsoBend = 0.4f;
		float[][] f = deformed(p);
		// the body faces -z: the head goes forward (-z) and down (y grows)
		assertTrue(f[2][4] < -10f);
		assertTrue(f[1][4] > -200f);
		// legs untouched
		assertEquals(-50f, f[1][1], 1e-4f);
		assertEquals(0f, f[2][1], 1e-4f);
	}

	@Test
	public void negativeRollLeansTheHeadTowardTheChestAboutTheFeet()
	{
		BodyPose p = new BodyPose();
		p.roll = -0.3f;
		float[][] f = deformed(p);
		assertEquals(0f, f[1][0], 1e-4f);
		assertEquals(0f, f[2][0], 1e-4f);
		// head (0, -200, 0) -> z = 200 sin(-0.3) = -59.1
		assertEquals(200f * (float) Math.sin(-0.3), f[2][4], 1e-2f);
		assertEquals(-200f * (float) Math.cos(0.3), f[1][4], 1e-2f);
	}

	@Test
	public void pitchTurnsAboutThePivotLikeTheBoard()
	{
		BodyPose p = new BodyPose();
		p.pitch = 0.25f;
		p.pivotX = 30f;
		float[] xs = {30f, 30f};
		float[] ys = {0f, -100f};
		float[] zs = {0f, 0f};
		MeshDeformer.deform(xs, ys, zs, 2, p);
		assertEquals(30f, xs[0], 1e-4f);
		assertEquals(0f, ys[0], 1e-4f);
		// a point above the pivot tips toward +x for a positive pitch
		assertEquals(30f + 100f * (float) Math.sin(0.25), xs[1], 1e-3f);
	}

	/**
	 * The body turns with the board: the board's model space is (board x, y, board z) = (puppet z, y,
	 * -puppet x) (see MeshDeformer), so rolling and pitching a point by the board's own rotation and mapping
	 * it back must match the deformer.
	 */
	@Test
	public void rollAndPitchMatchTheBoardRotationSense()
	{
		float px = 12f;
		float py = -80f;
		float pz = 7f;
		float roll = 0.35f;
		float pitch = -0.2f;

		float[] board = BoardGeometry.rotate(new float[]{pz, py, -px}, roll, 0f);
		BodyPose r = new BodyPose();
		r.roll = roll;
		float[] xs = {px};
		float[] ys = {py};
		float[] zs = {pz};
		MeshDeformer.deform(xs, ys, zs, 1, r);
		assertEquals(board[0], zs[0], 1e-3f);
		assertEquals(board[1], ys[0], 1e-3f);
		assertEquals(board[2], -xs[0], 1e-3f);

		board = BoardGeometry.rotate(new float[]{pz, py, -px}, 0f, pitch);
		BodyPose q = new BodyPose();
		q.pitch = pitch;
		xs[0] = px;
		ys[0] = py;
		zs[0] = pz;
		MeshDeformer.deform(xs, ys, zs, 1, q);
		assertEquals(board[0], zs[0], 1e-3f);
		assertEquals(board[1], ys[0], 1e-3f);
		assertEquals(board[2], -xs[0], 1e-3f);
	}
	/**
	 * Two legs side by side along x (the board axis) at x = -12 (rear, for a regular rider going +x) and
	 * x = +12 (front), a vertex every 10 units from the soles up to the hip line at -90, then a torso up to
	 * the head top at -200 (model height 200, so hip 90).
	 */
	private static float[][] twoLegs()
	{
		int legVerts = 10;
		int torso = 11;
		float[] xs = new float[2 * legVerts + torso];
		float[] ys = new float[xs.length];
		float[] zs = new float[xs.length];
		int i = 0;
		for (float side : new float[]{-12f, 12f})
		{
			for (int k = 0; k < legVerts; k++)
			{
				xs[i] = side;
				ys[i] = -10f * k;
				i++;
			}
		}
		for (int k = 0; k < torso; k++)
		{
			xs[i] = (k % 3 - 1) * 12f;
			ys[i] = -100f - 10f * k;
			i++;
		}
		return new float[][]{xs, ys, zs};
	}

	private static BodyPose push(float footX, float footY, float footZ)
	{
		BodyPose p = new BodyPose();
		p.legWeight = 1f;
		p.legSide = -1f;
		p.footX = footX;
		p.footY = footY;
		p.footZ = footZ;
		return p;
	}

	@Test
	public void pushMovesOnlyTheRearLegAndPutsTheFootOnTheTarget()
	{
		float[][] f = twoLegs();
		float[][] g = twoLegs();
		// 30 back, 20 below the soles (the ground), 15 toward the chest
		MeshDeformer.deform(f[0], f[1], f[2], f[0].length, push(-30f, 20f, -15f));
		// rear sole: (-12, 0, 0) -> (-42, 20, -15); reach sqrt(30^2 + 110^2) = 114 of a 90 leg (stretch 1.27)
		assertEquals(-42f, f[0][0], 0.05f);
		assertEquals(20f, f[1][0], 0.05f);
		assertEquals(-15f, f[2][0], 0.05f);
		// the front leg and the torso are untouched (no crouch in this pose)
		for (int i = 10; i < g[0].length; i++)
		{
			assertEquals(g[0][i], f[0][i], 1e-4f);
			assertEquals(g[1][i], f[1][i], 1e-4f);
			assertEquals(g[2][i], f[2][i], 1e-4f);
		}
		// the rear foot really moved, the rear hip vertex did not
		assertTrue(Math.abs(f[0][0] - g[0][0]) > 20f);
		assertEquals(g[0][9], f[0][9], 1e-3f);
		assertEquals(g[1][9], f[1][9], 1e-3f);
	}

	@Test
