package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

public class PoseSmoothingTest
{
	private static final float PEAK = PoseSmoothing.POP_PITCH;

	@Test
	public void popIsFlatBeforeAndAfter()
	{
		assertEquals(0f, PoseSmoothing.popPitch(-0.01f, false), 0f);
		assertEquals(0f, PoseSmoothing.popPitch(0f, false), 1e-6f);
		assertEquals(0f, PoseSmoothing.popPitch(PoseSmoothing.POP_RISE + PoseSmoothing.POP_FALL, false), 1e-6f);
		assertEquals(0f, PoseSmoothing.popPitch(1f, false), 0f);
	}

	@Test
	public void popRisesOverFiftyMillisecondsWithoutAOneFrameJump()
	{
		assertEquals(0.05f, PoseSmoothing.POP_RISE, 0f);
		assertEquals(PEAK, PoseSmoothing.popPitch(0.05f, false), 1e-5f);
		// one 144 fps frame in: well below the peak
		float firstFrame = PoseSmoothing.popPitch(1f / 144f, false);
		assertTrue(firstFrame > 0f && firstFrame < 0.4f * PEAK);
		float last = 0f;
		for (float t = 0.005f; t <= 0.05f; t += 0.005f)
		{
			float v = PoseSmoothing.popPitch(t, false);
			assertTrue(v >= last);
			last = v;
		}
	}

	@Test
	public void popEasesBackOverTwoHundredMilliseconds()
	{
		assertEquals(0.2f, PoseSmoothing.POP_FALL, 0f);
		assertEquals(PEAK / 2f, PoseSmoothing.popPitch(0.05f + 0.1f, false), 1e-4f);
		float last = PEAK;
		for (float t = 0.06f; t < 0.25f; t += 0.01f)
		{
			float v = PoseSmoothing.popPitch(t, false);
			assertTrue(v <= last + 1e-6f);
			assertTrue(v > 0f);
			last = v;
		}
	}

	@Test
	public void nolliePopTipsTheNoseDown()
	{
		for (float t = 0.01f; t < 0.25f; t += 0.02f)
		{
			assertEquals(-PoseSmoothing.popPitch(t, false), PoseSmoothing.popPitch(t, true), 0f);
		}
	}

	@Test
	public void nollieTricksAreRecognised()
	{
		assertTrue(PoseSmoothing.isNollie(Trick.NOLLIE));
		assertTrue(PoseSmoothing.isNollie(Trick.NOLLIE_KICKFLIP));
		assertTrue(PoseSmoothing.isNollie(Trick.NOLLIE_HEELFLIP));
		assertFalse(PoseSmoothing.isNollie(Trick.OLLIE));
		assertFalse(PoseSmoothing.isNollie(Trick.KICKFLIP));
		assertFalse(PoseSmoothing.isNollie(null));
	}

	@Test
	public void approachIsExponentialWithTheGivenTimeConstant()
	{
		// after exactly one time constant 1 - 1/e of the gap is closed
		assertEquals(1f - (float) Math.exp(-1), PoseSmoothing.approach(0f, 1f, 0.08f, 0.08f), 1e-5f);
		// frame-rate independent: two half steps equal one whole step
		float half = PoseSmoothing.approach(PoseSmoothing.approach(0f, 0.25f, 0.01f, 0.08f), 0.25f, 0.01f, 0.08f);
		assertEquals(PoseSmoothing.approach(0f, 0.25f, 0.02f, 0.08f), half, 1e-6f);
		// never overshoots, even over a long hitch
		assertEquals(0.25f, PoseSmoothing.approach(0f, 0.25f, 5f, 0.08f), 1e-6f);
		assertEquals(0.4f, PoseSmoothing.approach(0.4f, 0.4f, 0.016f, 0.08f), 0f);
		// dt 0 leaves it where it was
		assertEquals(0.1f, PoseSmoothing.approach(0.1f, 1f, 0f, 0.08f), 0f);
	}

	@Test
	public void manualPitchSettlesWithinAFewTimeConstants()
	{
		float pitch = 0f;
		for (int i = 0; i < 24; i++)
		{
			pitch = PoseSmoothing.approach(pitch, 0.25f, 1f / 60f, PoseSmoothing.POSE_TAU);
		}
		// 0.4 s = 5 tau: within 1%
		assertEquals(0.25f, pitch, 0.0025f);
	}

	@Test
	public void stumbleWobbleShakesTheBoardThenSettles()
	{
		assertEquals(0f, PoseSmoothing.stumbleWobble(0f), 1e-6f);
		float peak = 0f;
		boolean bothWays = false;
		float last = 0f;
		for (float s = 0f; s < PoseSmoothing.STUMBLE_TIME; s += 0.005f)
		{
			float w = PoseSmoothing.stumbleWobble(s);
			peak = Math.max(peak, Math.abs(w));
			bothWays |= w * last < 0f;
			last = w;
		}
		assertTrue("visible: " + peak, peak > 0.1f);
		assertTrue("small: " + peak, peak <= Tuning.STUMBLE_ROLL);
		assertTrue(bothWays);
		assertEquals(0f, PoseSmoothing.stumbleWobble(PoseSmoothing.STUMBLE_TIME), 0f);
		assertEquals(0f, PoseSmoothing.stumbleWobble(Float.MAX_VALUE), 0f);
	}

	@Test
	public void aGrabsBoardTweakSnapsInWithinATenthOfASecond()
	{
		float target = 0.4f;
		float v = 0f;
		for (int i = 0; i < 6; i++)
		{
			v = PoseSmoothing.approach(v, target, 1f / 60f, PoseSmoothing.GRAB_TAU);
		}
		assertTrue("tweak " + v, v > 0.9f * target);
		// the first frame is not a jump all the way
		assertTrue(PoseSmoothing.approach(0f, target, 1f / 60f, PoseSmoothing.GRAB_TAU) < 0.6f * target);
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PushCycleTest
{
	private static PushCycle.Sample at(float phase)
	{
		PushCycle.Sample s = new PushCycle.Sample();
		PushCycle.sample(phase, s);
		return s;
	}

	@Test
	public void startsAndEndsOnTheBoardWithNoEffect()
	{
		for (float p : new float[]{0f, 1f, -0.5f, 1.5f})
		{
			PushCycle.Sample s = at(p);
			assertEquals(0f, s.back, 1e-5f);
			assertEquals(0f, s.footY, 1e-5f);
			assertEquals(0f, s.side, 1e-5f);
			assertEquals(0f, s.legWeight, 1e-5f);
			assertEquals(0f, s.squash, 1e-5f);
			assertEquals(0f, s.lean, 1e-5f);
		}
	}

	@Test
	public void footLiftsOffTheBoardFirst()
	{
		PushCycle.Sample s = at(PushCycle.LIFT_END);
		assertTrue(s.footY < -5f);
		// off to the toe side, clear of the deck edge
		assertTrue(s.side > 10f);
	}

	@Test
	public void footIsOnTheGroundMidCycleAndTheFrontKneeBends()
	{
		PushCycle.Sample s = at(0.5f);
		assertEquals(PushCycle.GROUND_DEPTH, s.footY, 1e-4f);
		assertEquals(BoardGeometry.BOARD_TOP + BoardPlacement.FOOT_CLEARANCE, PushCycle.GROUND_DEPTH, 0f);
		assertEquals(1f, s.legWeight, 1e-5f);
		assertEquals(PushCycle.PLANT_SQUASH, s.squash, 1e-4f);
		assertTrue(s.lean > 0.05f);
		// beside the deck (half width 13), not through it
		assertTrue(s.side > 13f);
	}

	@Test
	public void plantSweepsBackwardMonotonically()
	{
		float last = -Float.MAX_VALUE;
		for (float p = PushCycle.PLANT_START; p <= PushCycle.PLANT_END + 1e-6f; p += 0.01f)
		{
			PushCycle.Sample s = at(p);
			assertEquals("on the ground at " + p, PushCycle.GROUND_DEPTH, s.footY, 1e-3f);
			assertTrue("sweep goes backward at " + p, s.back >= last - 1e-4f);
			last = s.back;
		}
		assertTrue(last >= 40f && last <= 55f);
		assertTrue(at(PushCycle.PLANT_START).back < 5f);
	}

	@Test
	public void footReturnsForwardAboveTheGround()
	{
		PushCycle.Sample s = at(PushCycle.RECOVER_END);
		assertTrue(s.footY < 0f);
		assertTrue(s.back < at(PushCycle.PLANT_END).back);
	}

	@Test
	public void everyChannelIsContinuous()
	{
		PushCycle.Sample prev = at(0f);
		for (int i = 1; i <= 1000; i++)
		{
			PushCycle.Sample s = at(i / 1000f);
			assertTrue(Math.abs(s.back - prev.back) < 0.5f);
			assertTrue(Math.abs(s.footY - prev.footY) < 0.5f);
			assertTrue(Math.abs(s.side - prev.side) < 0.5f);
			assertTrue(Math.abs(s.legWeight - prev.legWeight) < 0.05f);
			assertTrue(Math.abs(s.squash - prev.squash) < 0.01f);
			assertTrue(Math.abs(s.lean - prev.lean) < 0.01f);
			prev = s;
		}
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import com.gielinorskate.physics.Angles;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

public class RenderPoseTest
{
	private static RenderPose pose(float x, float y, float h, float heading, float roll, float yaw, float pitch,
		SkaterState state)
	{
		return new RenderPose(x, y, h, heading, heading, roll, yaw, pitch, state, null);
	}

	@Test
	public void lerpsPositionLinearly()
	{
		RenderPose a = pose(0f, 100f, 10f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose b = pose(30f, 130f, 20f, 0f, 0f, 0f, 0.2f, SkaterState.ROLLING);
		RenderPose m = RenderPose.lerp(a, b, 0.25f);
		assertEquals(7.5f, m.x, 1e-4f);
		assertEquals(107.5f, m.y, 1e-4f);
		assertEquals(12.5f, m.h, 1e-4f);
		assertEquals(0.05f, m.boardPitch, 1e-5f);
	}

	@Test
	public void alphaEndsReturnTheSnapshots()
	{
		RenderPose a = pose(0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose b = pose(10f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		assertEquals(0f, RenderPose.lerp(a, b, 0f).x, 0f);
		assertEquals(10f, RenderPose.lerp(a, b, 1f).x, 0f);
		// out-of-range alpha is clamped, never extrapolated
		assertEquals(10f, RenderPose.lerp(a, b, 1.7f).x, 0f);
		assertEquals(0f, RenderPose.lerp(a, b, -0.5f).x, 0f);
	}

	@Test
	public void headingTakesTheShortWayAcrossPi()
	{
		RenderPose a = pose(0f, 0f, 0f, Angles.PI - 0.1f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose b = pose(0f, 0f, 0f, -Angles.PI + 0.1f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose m = RenderPose.lerp(a, b, 0.5f);
		assertEquals(Angles.PI, Math.abs(m.heading), 1e-4f);
		assertEquals(Angles.PI, Math.abs(m.cameraHeading), 1e-4f);
	}

	@Test
	public void flipRollIsLerpedUnwrappedBeyondOneTurn()
	{
		// mid double kickflip: 6.0 -> 6.8 rad must not wrap back through zero
		RenderPose a = pose(0f, 0f, 50f, 0f, 6.0f, 0f, 0f, SkaterState.AIRBORNE);
		RenderPose b = pose(0f, 0f, 60f, 0f, 6.8f, 0f, 0f, SkaterState.AIRBORNE);
		assertEquals(6.4f, RenderPose.lerp(a, b, 0.5f).boardRoll, 1e-4f);
	}

	@Test
	public void flipCompletionSnapToZeroRotatesForwardNotBack()
	{
		// a caught kickflip at 94% (5.9 rad) whose roll becomes 0 on landing: the short way is +0.38
		float caught = 0.94f * Angles.TWO_PI;
		RenderPose a = pose(0f, 0f, 5f, 0f, caught, 0f, 0f, SkaterState.AIRBORNE);
		RenderPose b = pose(0f, 30f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose m = RenderPose.lerp(a, b, 0.5f);
		float expected = caught + 0.5f * (Angles.TWO_PI - caught);
		assertEquals(0f, Angles.wrap(m.boardRoll - expected), 1e-4f);
		// a landing is continuous: position still lerps
		assertEquals(15f, m.y, 1e-4f);
	}

	@Test
	public void halfTurnYawSnapIsNotLerped()
	{
		// a shove-it at 180 degrees whose yaw becomes 0: either way round would be a fake spin
		RenderPose a = pose(0f, 0f, 0f, 0f, 0f, Angles.PI, 0f, SkaterState.AIRBORNE);
		RenderPose b = pose(0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		assertEquals(0f, RenderPose.lerp(a, b, 0.3f).boardYaw, 0f);
	}

	@Test
	public void grindLockIsNotLerped()
	{
		RenderPose a = pose(0f, 0f, 80f, 0f, 0f, 0f, 0f, SkaterState.AIRBORNE);
		RenderPose b = pose(40f, 0f, 60f, 0.5f, 0f, 0f, 0f, SkaterState.GRINDING);
		assertSame(b, RenderPose.lerp(a, b, 0.2f));
	}

	@Test
	public void leavingARailIsLerped()
	{
		RenderPose a = pose(0f, 0f, 60f, 0f, 0f, 0f, 0f, SkaterState.GRINDING);
		RenderPose b = pose(0f, 20f, 64f, 0f, 0f, 0f, 0f, SkaterState.AIRBORNE);
		assertEquals(10f, RenderPose.lerp(a, b, 0.5f).y, 1e-4f);
	}

	@Test
	public void bailAndResetAreNotLerped()
	{
		RenderPose rolling = pose(0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose bailed = pose(20f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.BAILED);
		assertSame(bailed, RenderPose.lerp(rolling, bailed, 0.5f));
		assertSame(rolling, RenderPose.lerp(bailed, rolling, 0.5f));
	}

	@Test
	public void teleportIsNotLerped()
	{
		RenderPose a = pose(0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose b = pose(500f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		assertSame(b, RenderPose.lerp(a, b, 0.5f));
	}

	@Test
	public void holdAndStateComeFromTheNewerSnapshot()
	{
		RenderPose a = new RenderPose(0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING, null);
		RenderPose b = new RenderPose(0f, 4f, 0f, 0f, 0f, 0f, 0f, 0.25f, SkaterState.MANUAL, Trick.MANUAL);
		RenderPose m = RenderPose.lerp(a, b, 0.5f);
		assertEquals(SkaterState.MANUAL, m.state);
		assertEquals(Trick.MANUAL, m.hold);
	}

	@Test
	public void constantSpeedGivesConstantPerFrameDisplacementAt144Fps()
	{
		// 1500 u/s with 20 ms physics steps rendered at 144 fps: every frame moves 1500/144 units (+-1)
		float step = 0.02f;
		float frame = 1f / 144f;
		float speed = 1500f;
		float simTime = 0f;
		float accumulator = 0f;
		RenderPose prev = pose(0f, 0f, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
		RenderPose cur = prev;
		float lastY = Float.NaN;
		for (int i = 0; i < 300; i++)
		{
			accumulator += frame;
			while (accumulator >= step)
			{
				prev = cur;
				simTime += step;
				cur = pose(0f, speed * simTime, 0f, 0f, 0f, 0f, 0f, SkaterState.ROLLING);
				accumulator -= step;
			}
			float y = RenderPose.lerp(prev, cur, accumulator / step).y;
			// from the frame after the first step (before it there is nothing to move between)
			if (!Float.isNaN(lastY))
			{
				assertEquals(speed * frame, y - lastY, 1f);
			}
			lastY = simTime > 0f ? y : Float.NaN;
		}
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

/**
 * The rolling grab on the 200-unit test body: rolling with a grab held (the physics' ground grab as the rig's hold) the
 * skater crouches low and the hand reaches down to its spot of the board, which stays on the ground under planted
 * feet. Landing out of an air grab with the key held settles into it with no jump.
 */
public class RollingGrabBodyTest
{
	private static final float DT = 1 / 60f;
	private static final Trick[] GRABS = {Trick.INDY, Trick.MELON, Trick.MUTE, Trick.STALEFISH, Trick.NOSEGRAB,
		Trick.TAILGRAB, Trick.CRAIL, Trick.TWEAKED_INDY, Trick.METHOD, Trick.JAPAN, Trick.TWEAKED_STALEFISH,
		Trick.NOSEBONE, Trick.TAILBONE, Trick.CRAIL_TWEAK};
	private static final int[] KEYS = {1, -1, 0};
	private static final float HAND_TOLERANCE = 6f;
	private static final float CRAIL_TOLERANCE = 8f;

	private static SkaterPoseRig.Signals rollingSignals(Trick grab, int key)
	{
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		s.state = SkaterState.ROLLING;
		s.speed = 400f;
		s.hold = grab;
		s.grabHand = key;
		return s;
	}

	/** The pose after a second rolling with {@code grab} held, the board drawn flat on the ground. */
	private static BodyPose held(Trick grab, int key)
	{
		SkaterPoseRig rig = new SkaterPoseRig();
		SkaterPoseRig.Signals s = rollingSignals(grab, key);
		for (int i = 0; i < 60; i++)
		{
			rig.update(s, DT);
		}
		return drawn(rig);
	}

	/** What the renderer writes on the ground: no tweak (the board is not a hold), the rig's lift. */
	private static BodyPose drawn(SkaterPoseRig rig)
	{
		BodyPose p = new BodyPose();
		rig.writeTo(p);
		p.boardRoll = 0f;
		p.boardPitch = 0f;
		p.deckLift = 0f;
		p.boardLift = BoardPlacement.grabLift(p.feetLift, false);
		return p;
	}

	private static float[] target(BodyPose p)
	{
		float[] t = new float[3];
		BoardPlacement.grabTarget(p.grabAlong, p.grabAcross, p.grabBoardY, p.boardRoll, p.boardPitch,
			p.deckLift - p.boardLift, t);
		return t;
	}

	private static int hand(float side)
	{
		Humanoid rest = new Humanoid();
		ArmLocator a = new ArmLocator();
		assertTrue(a.locate(rest.xs, rest.ys, rest.zs, rest.n, side));
		return a.handIndex;
	}

	private static Humanoid deformed(BodyPose p)
	{
		Humanoid b = new Humanoid();
		MeshDeformer.deform(b.xs, b.ys, b.zs, b.n, p);
		return b;
	}

	private static float distance(Humanoid b, int i, float[] t)
	{
		float dx = b.xs[i] - t[0];
		float dy = b.ys[i] - t[1];
		float dz = b.zs[i] - t[2];
		return (float) Math.sqrt(dx * dx + dy * dy + dz * dz);
	}

	@Test
	public void theHandReachesDownToItsSpotOfTheBoardOnTheGround()
	{
		for (Trick grab : GRABS)
		{
			for (int key : KEYS)
			{
				BodyPose p = held(grab, key);
				assertEquals(grab + " arm", 1f, p.armWeight, 0.01f);
				assertEquals(grab + " lift", 0f, p.boardLift, 0f);
				float d = distance(deformed(p), hand(p.armSide), target(p));
				// a crail is the back hand all the way to the nose on the ground: the longest reach
				float tolerance = grab == Trick.CRAIL || grab == Trick.CRAIL_TWEAK ? CRAIL_TOLERANCE : HAND_TOLERANCE;
				assertTrue(grab + " key " + key + ": hand " + d + " from its spot", d < tolerance);
			}
		}
	}

	@Test
	public void aRollingTailgrabIsTheBackHandsWhicheverKey()
	{
		for (int key : KEYS)
		{
			assertEquals(-1f, held(Trick.TAILGRAB, key).armSide, 0f);
			assertEquals(-1f, held(Trick.TAILBONE, key).armSide, 0f);
		}
		assertEquals(1f, held(Trick.NOSEGRAB, -1).armSide, 0f);
	}

	@Test
	public void theFeetStayPlantedOnTheBoardOnTheGround()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			assertEquals(0f, p.feetLift, 1e-3f);
			Humanoid rest = new Humanoid();
			Humanoid b = deformed(p);
			for (int i = 0; i < rest.n; i++)
			{
				if (rest.ys[i] == 0f)
				{
					// a grab's body roll tips the soles a little about the board's long axis, never off the deck
					assertEquals(grab + " sole " + i, 0f, b.ys[i], 3f);
					assertTrue(grab + " sole " + i + " z " + b.zs[i], Math.abs(b.zs[i]) < 6f);
				}
			}
		}
	}

	@Test
	public void itIsALowCrouch()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			assertTrue(grab + " legScale " + p.legScale, p.legScale < 0.6f);
			assertTrue(grab + " fold " + p.kneeFold, p.kneeFold > 0.99f);
			Humanoid b = deformed(p);
			float top = 0f;
			for (int i = 0; i < b.n; i++)
			{
				top = Math.min(top, b.ys[i]);
			}
			assertTrue("head at " + top, top > -150f);
		}
	}

	@Test
	public void theFreeArmGoesOutForBalance()
	{
		for (Trick grab : GRABS)
		{
			BodyPose p = held(grab, 0);
			float side = -p.armSide;
			ArmLocator a = new ArmLocator();
			Humanoid rest = new Humanoid();
			assertTrue(a.locate(rest.xs, rest.ys, rest.zs, rest.n, side));
			Humanoid b = deformed(p);
			assertTrue(grab + " free hand x " + b.xs[a.handIndex], b.xs[a.handIndex] * side > Humanoid.ARM_OUTER + 15f);
		}
	}

	@Test
	public void withoutAGrabRollingIsAsBefore()
	{
		SkaterPoseRig rig = new SkaterPoseRig();
		SkaterPoseRig.Signals s = rollingSignals(null, 1);
		for (int i = 0; i < 60; i++)
		{
			rig.update(s, DT);
		}
		BodyPose p = new BodyPose();
		rig.writeTo(p);
		assertEquals(0f, p.armWeight, 0f);
		assertEquals(0f, p.kneeFold, 0f);
		assertEquals(0f, p.feetLift, 0f);
		assertEquals(1f, p.legScale, 1e-4f);
	}

	@Test
	public void landingFromAnAirGrabSettlesIntoTheRollingGrabSmoothly()
	{
		SkaterPoseRig rig = new SkaterPoseRig();
		SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
		s.state = SkaterState.AIRBORNE;
		s.popped = true;
		rig.update(s, DT);
		s.popped = false;
		s.hold = Trick.INDY;
		s.grabHand = 1;
		for (int i = 0; i < 30; i++)
		{
			rig.update(s, DT);
		}
		BodyPose last = drawn(rig);
		assertEquals(Tuning.GRAB_LIFT, last.feetLift, 0.5f);
		// touchdown: the physics' air grab is released and the same grab carries on as the rolling grab
		s.state = SkaterState.ROLLING;
		s.landed = true;
		s.landingSpeed = 800f;
		for (int i = 0; i < 40; i++)
		{
			rig.update(s, DT);
			s.landed = false;
			BodyPose p = drawn(rig);
			assertEquals("arm stays on the board", 1f, p.armWeight, 0.02f);
			assertTrue("lift step " + (last.feetLift - p.feetLift), Math.abs(last.feetLift - p.feetLift) < 3f);
			assertTrue("crouch step", Math.abs(last.legScale - p.legScale) < 0.08f);
			last = p;
		}
		assertEquals(0f, last.feetLift, 0.5f);
	}
}

package com.gielinorskate.render;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.tricks.Trick;
import org.junit.Test;

public class SkaterPoseRigTest
{
	static final float DT = 1 / 60f;

	private final SkaterPoseRig rig = new SkaterPoseRig();
	private final SkaterPoseRig.Signals s = new SkaterPoseRig.Signals();
	private final BodyPose out = new BodyPose();

	/** Runs {@code seconds} of frames, clearing one-frame events after the first; fails on a visible jump. */
	private void run(float seconds)
	{
		int n = Math.round(seconds / DT);
		for (int i = 0; i < n; i++)
		{
			float roll = out.roll;
			float pitch = out.pitch;
			float legs = out.legScale;
			float footX = out.legWeight * out.footX;
			float footY = out.legWeight * out.footY;
			rig.update(s, DT);
			rig.writeTo(out);
			// continuity: nothing moves more than this in one 60 fps frame
			assertTrue("roll jump " + (out.roll - roll), Math.abs(out.roll - roll) < 0.08f);
			assertTrue("pitch jump", Math.abs(out.pitch - pitch) < 0.06f);
			assertTrue("legs jump " + (out.legScale - legs), Math.abs(out.legScale - legs) < 0.15f);
			// the push foot's weighted offset is what the mesh shows. Its fastest real move is the reach down
			// to the ground, 30 units in 0.16 of a 0.42 s cycle with smoothstep's 1.5x peak rate:
			// 30 * 1.5 / (0.16 * 0.42 * 60) = 11.2 units per frame
			assertTrue("push foot jump x", Math.abs(out.legWeight * out.footX - footX) < 12f);
			assertTrue("push foot jump y", Math.abs(out.legWeight * out.footY - footY) < 12f);
			s.popped = false;
			s.rolledOff = false;
			s.landed = false;
			s.bailed = false;
			s.pushed = false;
		}
	}

	@Test
	public void leanIntoTheTurnScalesWithSpeedAndTurnRateAndCaps()
	{
		// right (clockwise) carve rolls negative like the board's steer lean; 0.6 * atan(800 * 1 / 2000)
		assertEquals(-0.6f * (float) Math.atan(0.4), SkaterPoseRig.leanFor(800f, 1f), 1e-5f);
		assertTrue(SkaterPoseRig.leanFor(800f, -1f) > 0f);
		assertTrue(Math.abs(SkaterPoseRig.leanFor(1600f, 1f)) > Math.abs(SkaterPoseRig.leanFor(800f, 1f)));
		// riding fakie the centre of the turn is on the other side
		assertTrue(SkaterPoseRig.leanFor(-800f, 1f) > 0f);
		assertEquals(-SkaterPoseRig.MAX_LEAN, SkaterPoseRig.leanFor(2600f, 50f), 1e-6f);
		assertEquals(0f, SkaterPoseRig.leanFor(0f, 2f), 0f);
	}

	@Test
	public void tightCarveLeansFurtherAndTheLeanEasesIn()
	{
		s.speed = 900f;
		s.carveRate = 1.2f;
		run(1f);
		float normal = out.roll;
		assertEquals(SkaterPoseRig.leanFor(900f, 1.2f), normal, 1e-3f);
		// Shift + steer: the physics carve rate is tightCarveMult (2.2) times higher
		s.carveRate = 1.2f * 2.2f;
		run(1f);
		assertTrue(out.roll < normal - 0.05f);
		s.carveRate = 0f;
		run(1f);
		assertEquals(0f, out.roll, 1e-3f);
	}

	@Test
	public void crouchDepthFollowsTheCharge()
	{
		s.charge = 0.5f;
		run(0.5f);
		assertEquals(1f - 0.5f * SkaterPoseRig.CHARGE_CROUCH, out.legScale, 1e-3f);
		assertTrue(out.torsoBend > 0f);
		s.charge = 1f;
		run(0.5f);
		assertEquals(1f - SkaterPoseRig.CHARGE_CROUCH, out.legScale, 1e-3f);
	}

	@Test
	public void popExtendsThenTucksThenReachesForTheGround()
	{
		s.charge = 1f;
		run(0.4f);
		s.charge = 0f;
		s.state = SkaterState.AIRBORNE;
		s.popped = true;
		s.verticalSpeed = 800f;
		float minCrouch = Float.MAX_VALUE;
		for (int i = 0; i < 7; i++)
		{
			run(DT);
			minCrouch = Math.min(minCrouch, 1f - out.legScale);
		}
		// the legs straighten past standing within the extension window
		assertTrue("extension " + minCrouch, minCrouch < 0f);
		run(0.3f);
		assertEquals(Tuning.AIR_TUCK, 1f - out.legScale, 0.02f);
		s.flipping = true;
		run(0.3f);
		assertEquals(Tuning.TRICK_TUCK, 1f - out.legScale, 0.02f);
