	}
}

package com.gielinorskate.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.GielinorSkateConfig.AfterBail;
import com.gielinorskate.physics.BailReason;
import com.gielinorskate.physics.CollisionWorld;
import com.gielinorskate.physics.SkateEvent;
import com.gielinorskate.physics.SkateInput;
import com.gielinorskate.physics.SkatePhysics;
import com.gielinorskate.physics.SkateTuning;
import com.gielinorskate.physics.SkaterState;
import com.gielinorskate.scoring.ComboScorer;
import com.gielinorskate.tricks.Trick;
import com.gielinorskate.tricks.TrickEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;
import org.junit.Test;

/**
 * The knockdown changes only what a bail looks like and what follows it: the bail itself (its cause, its events),
 * the lost combo are what they were, whichever "After a bail" is chosen.
 */
public class KnockdownRegressionTest
{
	private static final float DT = 0.02f;
	private static final SkateTuning T = new SkateTuning();

	/** Flat ground with a tall wall across at y = wallY. */
	private static CollisionWorld wallAt(float wallY)
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return (y0 < wallY) != (y1 < wallY) ? 300f : Float.NEGATIVE_INFINITY;
			}
		};
	}

	@Test
	public void aHeadOnWallHitStillBailsAsAWallBail()
	{
		SkatePhysics p = new SkatePhysics(T, wallAt(300f), 0f, 0f, 0f);
		p.setRollingSpeed(1500f);
		SkateInput in = new SkateInput();
		List<SkateEvent> events = new ArrayList<>();
		List<TrickEvent> tricks = new ArrayList<>();
		for (int i = 0; i < 50 && p.getState() != SkaterState.BAILED; i++)
		{
			p.step(DT, in);
			events.addAll(p.drainEvents());
			tricks.addAll(p.drainTrickEvents());
		}
		assertEquals(SkaterState.BAILED, p.getState());
		assertEquals(BailReason.WALL, p.getLastBailReason());
		assertTrue(events.contains(SkateEvent.BAIL));
		assertTrue(tricks.stream().anyMatch(e -> e.type == TrickEvent.Type.BAILED));
		// the knockdown reads the wall: knocked back off it, on the near side
		assertTrue(p.isBailWall());
		assertEquals(-1f, p.getBailWallNy(), 1e-3f);
		Knockdown k = new Knockdown(wallAt(300f), T.gravity, T.skaterRadius);
		k.start(p.getX(), p.getY(), p.getH(), p.getVelocityX(), p.getVelocityY(), p.getHeading(), p.isBailWall(),
			p.getBailWallNx(), p.getBailWallNy(), new Random(4));
		while (!k.isDone())
		{
			k.step(DT);
			assertTrue(k.getBody().getY() < 300f);
			assertTrue(k.getBoard().getY() < 300f);
		}
		assertTrue(k.getBody().getY() < p.getY());
	}

	@Test
	public void theBailStillLosesTheCombo()
	{
		ComboScorer scorer = new ComboScorer();
		scorer.accept(TrickEvent.trick(Trick.OLLIE), 0f);
		scorer.accept(TrickEvent.trick(Trick.KICKFLIP), 0.1f);
		scorer.accept(TrickEvent.bailed(), 0.2f);
		assertEquals(0, scorer.sessionScore());
		assertTrue(scorer.lastResult().isBailed());
		assertEquals(0, scorer.comboPoints());
	}

	@Test
	public void bothSettingsKeepTheBail()
	{
		// the choice only decides what follows the bail; it is never a reason not to bail
		assertTrue(BailRules.knocksOff(AfterBail.KNOCKED_OFF));
		assertFalse(BailRules.knocksOff(AfterBail.HOP_BACK_ON));
		assertEquals(AfterBail.KNOCKED_OFF, new com.gielinorskate.GielinorSkateConfig()
		{
		}.afterBail());
	}

	@Test
	public void hopBackOnStillGetsUpByItself()
	{
		// the old path, unchanged: the bailed skater is back on after bailDuration + bailAutoReset
		SkatePhysics p = new SkatePhysics(T, wallAt(300f), 0f, 0f, 0f);
		p.setRollingSpeed(1500f);
		SkateInput in = new SkateInput();
		float t = 0f;
		boolean bailed = false;
		while (t < 5f)
		{
			p.step(DT, in);
			t += DT;
			bailed |= p.getState() == SkaterState.BAILED;
			if (bailed && p.getState() == SkaterState.ROLLING)
			{
				break;
			}
		}
		assertTrue(bailed);
		assertEquals(SkaterState.ROLLING, p.getState());
	}
}

package com.gielinorskate.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.CollisionWorld;
import com.gielinorskate.physics.SkateTuning;
import java.util.Random;
import org.junit.Test;

/** The knockdown sequence: knock-off, lie down, get up; its timing and the skips. */
public class KnockdownTest
{
	/** The longest the whole sequence can take (plus a physics step per phase). */
	private static final float MAX_TOTAL = Knockdown.MAX_TUMBLE + Knockdown.LIE_SECONDS + Knockdown.GET_UP_SECONDS;
	private static final float DT = 0.02f;
	private static final SkateTuning T = new SkateTuning();

	static CollisionWorld flat()
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return 0f;
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return Float.NEGATIVE_INFINITY;
			}
		};
	}

	/** A cliff: the ground drops 5000 just ahead (a very long fall). */
	static CollisionWorld cliff()
	{
		return new CollisionWorld()
		{
			@Override
			public float groundHeight(float x, float y)
			{
				return y > 40f ? -5000f : 0f;
			}

			@Override
			public float terrainHeight(float x, float y)
			{
				return groundHeight(x, y);
			}

			@Override
			public float blockerTop(float x0, float y0, float x1, float y1)
			{
				return Float.NEGATIVE_INFINITY;
			}
		};
	}

	private static Knockdown knocked(CollisionWorld w, float speed)
	{
		Knockdown k = new Knockdown(w, T.gravity, T.skaterRadius);
		k.start(0f, 0f, 0f, 0f, speed, 0f, false, 0f, 0f, new Random(1));
		return k;
	}

	/** Steps with no input until done; returns the seconds it took. */
	private static float runIdle(Knockdown k)
	{
		float t = 0f;
		while (!k.isDone() && t < 10f)
		{
			k.step(DT);
			assertEquals(Knockdown.Outcome.NONE, k.input(false, false, false, false));
			t += DT;
		}
		return t;
	}

	@Test
	public void theWholeSequenceIsShort()
	{
		// the longest it can ever take, by design
		assertTrue(MAX_TOTAL <= 2.0f);
		assertTrue(Knockdown.LIE_SECONDS <= 0.5f);
		assertTrue(Knockdown.GET_UP_SECONDS <= 0.4f);
		for (float speed : new float[]{0f, 300f, 900f, 1500f, 2600f})
		{
			float t = runIdle(knocked(flat(), speed));
			assertTrue("at " + speed + ": " + t, t <= 2.0f);
			// a typical crash: about a second and a half at most, at least a second
			assertTrue("at " + speed + ": " + t, t >= 0.9f && t <= 1.5f);
		}
	}

	@Test
	public void evenAVeryLongFallEndsWithinTwoSeconds()
	{
		Knockdown k = knocked(cliff(), 1500f);
		float t = runIdle(k);
		assertTrue("done: " + t, k.isDone());
		assertTrue(t <= MAX_TOTAL + 3 * DT + 1e-4f);
		assertTrue(t <= 2.0f);
	}

	@Test
	public void phasesRunInOrder()
	{
		Knockdown k = knocked(flat(), 1500f);
		assertEquals(Knockdown.Phase.TUMBLE, k.getPhase());
		boolean impact = false;
		while (k.getPhase() == Knockdown.Phase.TUMBLE)
		{
			k.step(DT);
			impact |= k.takeImpact();
		}
		assertTrue("the impact comes as the lie-down starts", impact);
		assertEquals(Knockdown.Phase.LIE, k.getPhase());
		float lie = 0f;
		while (k.getPhase() == Knockdown.Phase.LIE)
		{
			k.step(DT);
			lie += DT;
		}
		assertEquals(Knockdown.LIE_SECONDS, lie, DT + 1e-4f);
		assertEquals(Knockdown.Phase.GET_UP, k.getPhase());
		assertEquals(0f, k.getBody().getSpeed(), 0f);
		float up = 0f;
		while (!k.isDone())
		{
			k.step(DT);
			up += DT;
		}
		assertEquals(Knockdown.GET_UP_SECONDS, up, DT + 1e-4f);
		assertFalse(k.takeImpact());
	}

	@Test
	public void rSkipsTheRestAndPutsTheSkaterBackOnTheBoard()
	{
		Knockdown k = knocked(flat(), 1500f);
		k.step(DT);
		assertEquals(Knockdown.Outcome.BACK_ON_BOARD, k.input(true, false, false, false));
		assertTrue(k.isDone());
	}

	@Test
	public void anyNewInputDuringTheLieDownSkipsToTheGetUp()
	{
		for (int which = 0; which < 2; which++)
		{
			Knockdown k = knocked(flat(), 1500f);
			k.input(false, false, false, false);
			toLie(k);
			k.step(DT);
			assertEquals(Knockdown.Outcome.NONE, k.input(false, which == 0, which == 1, false));
			assertEquals(Knockdown.Phase.GET_UP, k.getPhase());
		}
	}

	@Test
	public void aMoveKeyHeldThroughTheBailMustBePressedAgain()
	{
		Knockdown k = knocked(flat(), 1500f);
		k.input(false, true, false, false);
		toLie(k);
		k.step(DT);
		k.input(false, true, false, false);
		assertEquals(Knockdown.Phase.LIE, k.getPhase());
		k.input(false, false, false, false);
		k.input(false, true, false, false);
		assertEquals(Knockdown.Phase.GET_UP, k.getPhase());
	}

	@Test
	public void theBoardKeyDuringTheLieDownGoesStraightToReclaiming()
	{
		Knockdown k = knocked(flat(), 1500f);
		toLie(k);
		assertEquals(Knockdown.Outcome.RECLAIM, k.input(false, false, false, true));
		assertTrue(k.isDone());
	}

	@Test
	public void inputInTheAirIsIgnored()
	{
		Knockdown k = knocked(flat(), 1500f);
		k.step(DT);
		assertEquals(Knockdown.Outcome.NONE, k.input(false, true, true, true));
		assertEquals(Knockdown.Phase.TUMBLE, k.getPhase());
	}

	@Test
	public void theBodyFacesTheBoardOnceUp()
	{
		Knockdown k = knocked(flat(), 1500f);
		runIdle(k);
		float[] board = {k.getBoard().getX(), k.getBoard().getY()};
		float want = (float) Math.atan2(board[0] - k.getBody().getX(), board[1] - k.getBody().getY());
		assertEquals(want, k.standHeading(), 1e-4f);
	}

	@Test
	public void theBoardIsAtRestOnceTheSkaterStands()
	{
		Knockdown k = knocked(flat(), 2600f);
		runIdle(k);
		assertTrue(k.getBoard().isAtRest());
	}

	@Test
	public void theGetUpTurnsTheBodyUprightSmoothly()
	{
		Knockdown k = knocked(flat(), 1500f);
		while (k.getPhase() != Knockdown.Phase.GET_UP)
		{
			k.step(DT);
		}
		float lie = k.getBody().getAngle();
		assertEquals(lie, k.bodyAngle(), 0.05f);
		float last = k.bodyAngle();
		while (!k.isDone())
		{
			k.step(DT);
			float a = k.bodyAngle();
			assertTrue(Math.abs(a - last) < 0.5f);
			last = a;
		}
		// upright: whole turns
		double turns = k.bodyAngle() / (2 * Math.PI);
		assertEquals(Math.round(turns), turns, 1e-4);
	}

	private static void toLie(Knockdown k)
	{
		while (k.getPhase() == Knockdown.Phase.TUMBLE)
		{
			k.step(DT);
		}
		assertEquals(Knockdown.Phase.LIE, k.getPhase());
	}
}

package com.gielinorskate.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import net.runelite.api.WorldType;
import org.junit.Test;

public class SafetyRulesMinigameTest
{
	private static final int LUMBRIDGE = SafetyRules.regionId(3222, 3218);

	private static String always(boolean instance, boolean lms, boolean dmmWild, EnumSet<WorldType> types, int region)
	{
		return SafetyRules.alwaysBlockedReason(instance, lms, dmmWild, types, region);
	}

	@Test
	public void regionIdMatchesTheGameFormula()
	{
		// (x >> 6) << 8 | (y >> 6): Lumbridge castle is region 12850
		assertEquals(12850, SafetyRules.regionId(3222, 3218));
	}

	@Test
	public void normalPlaceIsNotAlwaysBlocked()
	{
		assertNull(always(false, false, false, EnumSet.of(WorldType.MEMBERS), LUMBRIDGE));
	}

	@Test
	public void instancesAlwaysBlocked()
	{
		assertNotNull(always(true, false, false, EnumSet.noneOf(WorldType.class), LUMBRIDGE));
	}

	@Test
	public void lastManStandingInGameAlwaysBlocked()
	{
		assertNotNull(always(false, true, false, EnumSet.noneOf(WorldType.class), LUMBRIDGE));
	}

	@Test
	public void deadmanWildernessAlwaysBlocked()
	{
		assertNotNull(always(false, false, true, EnumSet.noneOf(WorldType.class), LUMBRIDGE));
	}

	@Test
	public void pvpMinigameWorldTypesAlwaysBlocked()
	{
		assertNotNull(always(false, false, false, EnumSet.of(WorldType.PVP_ARENA), LUMBRIDGE));
		assertNotNull(always(false, false, false, EnumSet.of(WorldType.LAST_MAN_STANDING), LUMBRIDGE));
		assertNotNull(always(false, false, false, EnumSet.of(WorldType.BOUNTY, WorldType.MEMBERS), LUMBRIDGE));
	}

	@Test
	public void optInPvpWorldTypesAreNotAlwaysBlocked()
	{
		assertNull(always(false, false, false, EnumSet.of(WorldType.PVP), LUMBRIDGE));
		assertNull(always(false, false, false, EnumSet.of(WorldType.HIGH_RISK), LUMBRIDGE));
		assertNull(always(false, false, false, EnumSet.of(WorldType.DEADMAN), LUMBRIDGE));
	}

	@Test
	public void optInPvpWorlds()
	{
		assertTrue(SafetyRules.isOptInPvpWorld(EnumSet.of(WorldType.PVP)));
		assertTrue(SafetyRules.isOptInPvpWorld(EnumSet.of(WorldType.HIGH_RISK, WorldType.MEMBERS)));
		assertTrue(SafetyRules.isOptInPvpWorld(EnumSet.of(WorldType.DEADMAN)));
		assertFalse(SafetyRules.isOptInPvpWorld(EnumSet.of(WorldType.MEMBERS)));
		assertFalse(SafetyRules.isOptInPvpWorld(EnumSet.noneOf(WorldType.class)));
	}

	@Test
	public void castleWarsRegionsAlwaysBlocked()
	{
		assertNotNull(always(false, false, false, EnumSet.noneOf(WorldType.class), 9520));
		assertNotNull(always(false, false, false, EnumSet.noneOf(WorldType.class), 9620));
		// a tile in the Castle Wars arena, not just the raw region number
		assertTrue(SafetyRules.isBlockedMinigameRegion(SafetyRules.regionId(2400, 3100)));
	}

	@Test
	public void soulWarsRegionsAlwaysBlocked()
	{
		for (int r : new int[]{8493, 8748, 8749, 9005})
		{
			assertTrue(SafetyRules.isBlockedMinigameRegion(r));
		}
	}

	@Test
	public void clanWarsRegionsAlwaysBlocked()
	{
		for (int r : new int[]{12621, 12622, 12623, 13130, 13131, 13133, 13134, 13135, 13386, 13387, 13390,
			13641, 13642, 13643, 13644, 13645, 13646, 13647, 13899, 13900, 14155, 14156})
		{
			assertTrue(SafetyRules.isBlockedMinigameRegion(r));
		}
	}

	@Test
	public void pvpArenaAndLastManStandingRegionsAlwaysBlocked()
	{
		for (int r : new int[]{13362, 13363, 13658, 13659, 13660, 13914, 13915, 13916, 13918, 13919, 13920,
			14174, 14175, 14176, 14430, 14431, 14432})
		{
			assertTrue(SafetyRules.isBlockedMinigameRegion(r));
		}
	}

	@Test
	public void ordinaryRegionsNotMinigames()
	{
