	{
		for (java.awt.Component child : c.getComponents())
		{
			if (child instanceof javax.swing.JLabel)
			{
				out.add((javax.swing.JLabel) child);
			}
			if (child instanceof java.awt.Container)
			{
				collect((java.awt.Container) child, out);
			}
		}
	}
