			"Indy")));
	}

	@Test
	public void theBasicsAndOffTheBoardUseTheConfiguredKeys()
	{
		TrickBook.Settings s = new TrickBook.Settings("Ctrl+J", "G", "Space", "right", false, true, false, false,
