		assertEquals("Land along a rail, holding S", TrickGuide.controllerHow(Trick.FIVE_O, null, PadPreset.skate3()));
		assertEquals("Hold {LB} or {RB} and {LS} up in the air (or hold a grab and {LS} up)",
