	}
}

package com.gielinorskate.world;

import java.util.ArrayList;
import java.util.List;

/** Collects boxes for a test {@link BlockerSet}, then indexes them for a grid of size x size tiles. */
public final class BlockerSetBuilder
{
	private final List<float[]> boxes = new ArrayList<>();

	/** A box centred at (cx, cy), half extents hx along the unit vector (cos, sin) and hy across it. */
	public BlockerSetBuilder add(float cx, float cy, float hx, float hy, float cos, float sin, float top, byte kind, int flags)
	{
		boxes.add(new float[]{cx, cy, hx, hy, cos, sin, top, kind, flags});
		return this;
	}

	public BlockerSet build(int gridSize)
	{
		return new BlockerSet(boxes, gridSize);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Contact;
import org.junit.Test;

public class BlockerSetTest
{
	private static final float T = 128f;
	private static final float R = BlockerSet.SKATER_R;
	private static final float S45 = (float) Math.sqrt(0.5);

	/** One axis-aligned 40x40 rock (half 20) centred in tile (2, 2), top 70. */
	private static BlockerSet rock(byte kind, int flags)
	{
		return new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 20, 20, 1, 0, 70, kind, flags).build(5);
	}

	@Test
	public void registersOnlyInTilesItsExpandedBoundsTouch()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		assertEquals(1, WorldTests.countAt(s, 2, 2));
		assertEquals(0, WorldTests.countAt(s, 1, 2));
		assertEquals(0, WorldTests.countAt(s, 3, 3));
		// half 50 + skater radius 12 = 62 from the centre at 2.5 T reaches 2.5 T + 62 = 382 < 384: still one tile
		BlockerSet wide = new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 50, 50, 1, 0, 70, BlockerSet.SOLID, 0).build(5);
		assertEquals(0, WorldTests.countAt(wide, 3, 2));
		// half 60 + 12 = 72 > 64: spills into all eight neighbours
		BlockerSet wider = new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 60, 60, 1, 0, 70, BlockerSet.SOLID, 0).build(5);
		assertEquals(1, WorldTests.countAt(wider, 3, 3));
		assertEquals(1, WorldTests.countAt(wider, 1, 2));
		assertEquals(0, WorldTests.countAt(wider, 4, 2));
	}

	@Test
	public void boxesOutsideTheGridAreClipped()
	{
		BlockerSet s = new BlockerSetBuilder().add(-300, 2.5f * T, 20, 20, 1, 0, 70, BlockerSet.SOLID, 0).build(5);
		assertEquals(1, s.boxes.length);
		for (int tx = 0; tx < 5; tx++)
		{
			assertEquals(0, WorldTests.countAt(s, tx, 2));
		}
	}

	@Test
	public void sideContactPushesOutAlongTheFaceNormal()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		Contact c = new Contact();
		// 5 units east of the east face (x = 2.5 T + 20)
		assertTrue(s.contact(2.5f * T + 25, 2.5f * T + 3, R, 0, 24, c));
		assertEquals(1f, c.nx, 1e-5f);
		assertEquals(0f, c.ny, 1e-5f);
		assertEquals(R - 5, c.depth, 1e-4f);
		assertEquals(70f, c.top, 0f);
		assertFalse(s.contact(2.5f * T + 33, 2.5f * T, R, 0, 24, c));
	}

	@Test
	public void cornerContactNormalPointsFromTheCorner()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		Contact c = new Contact();
		assertTrue(s.contact(2.5f * T + 20 + 6, 2.5f * T + 20 + 6, R, 0, 24, c));
		assertEquals(S45, c.nx, 1e-5f);
		assertEquals(S45, c.ny, 1e-5f);
		assertEquals(R - 6 * (float) Math.sqrt(2), c.depth, 1e-3f);
	}

	@Test
	public void insideTheBoxPushesOutTheShortestWay()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		Contact c = new Contact();
		// 15 east and 2 north of centre: 5 from the east face, 18 from the north face
		assertTrue(s.contact(2.5f * T + 15, 2.5f * T + 2, R, 0, 24, c));
		assertEquals(1f, c.nx, 0f);
		assertEquals(0f, c.ny, 0f);
		assertEquals(5 + R, c.depth, 1e-4f);
		// 2 west and 17 south: out through the south face
		assertTrue(s.contact(2.5f * T - 2, 2.5f * T - 17, R, 0, 24, c));
		assertEquals(0f, c.nx, 0f);
		assertEquals(-1f, c.ny, 0f);
		assertEquals(3 + R, c.depth, 1e-4f);
	}

	@Test
	public void blockersAtOrBelowAStepAboveTheFeetAreIgnored()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		Contact c = new Contact();
		assertTrue(s.contact(2.5f * T + 25, 2.5f * T, R, 45, 24, c));
		assertFalse("top 70 <= 46 + 24", s.contact(2.5f * T + 25, 2.5f * T, R, 46, 24, c));
	}

	@Test
	public void passBlockersNeverCollide()
	{
		BlockerSet s = rock(BlockerSet.PASS, BlockerSet.LANDABLE);
		Contact c = new Contact();
		assertFalse(s.contact(2.5f * T, 2.5f * T, R, 0, 24, c));
		assertEquals(Float.NEGATIVE_INFINITY, s.landTop(2.5f * T, 2.5f * T), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(2.5f * T - 40, 2.5f * T, 2.5f * T, 2.5f * T, BlockerSet.SKATER_R), 0f);
	}

	@Test
	public void rotatedBoxUsesItsOwnAxes()
	{
		// 100 x 10 plank turned 45 degrees: its long (u) axis runs north-east, v = (-sin, cos) north-west
		BlockerSet s = new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 50, 5, S45, S45, 150, BlockerSet.SOLID, 0).build(5);
		Contact c = new Contact();
		// 40 along the plank then 10 off its north-west side: 5 clear of the face, inside the radius
		float ax = 40 * S45 - 10 * S45;
		float ay = 40 * S45 + 10 * S45;
		assertTrue(s.contact(2.5f * T + ax, 2.5f * T + ay, R, 0, 24, c));
		assertEquals(-S45, c.nx, 1e-4f);
		assertEquals(S45, c.ny, 1e-4f);
		assertEquals(R - 5, c.depth, 1e-3f);
		// 30 due east of the centre would be inside an unrotated 100 x 10 box; turned, it is 21 off the
		// plank's axis (16 clear of its face), out of reach
		assertFalse(s.contact(2.5f * T + 30, 2.5f * T, R, 0, 24, c));
	}

	@Test
	public void deepestOfSeveralContactsWins()
	{
		BlockerSet s = new BlockerSetBuilder()
			.add(2.5f * T, 2.5f * T, 20, 20, 1, 0, 70, BlockerSet.SOLID, 0)
			.add(2.5f * T + 50, 2.5f * T, 20, 20, 1, 0, 300, BlockerSet.SOLID, 0)
			.build(5);
		Contact c = new Contact();
		// 3 from the first box's east face (depth 9), 7 from the second's west face (depth 5)
		assertTrue(s.contact(2.5f * T + 23, 2.5f * T, R, 0, 24, c));
		assertEquals(1f, c.nx, 1e-5f);
		assertEquals(70f, c.top, 0f);
		assertEquals(9f, c.depth, 1e-4f);
	}

	@Test
	public void largeRadiusQueriesFindBoxesInNeighbouringTiles()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		Contact c = new Contact();
		// 45 east of the east face, in tile 3 (x = 385), with radius 50; the rock is registered in tile 2 only
		assertTrue(s.contact(2.5f * T + 65, 2.5f * T, 50, 0, 24, c));
		assertEquals(5f, c.depth, 1e-4f);
	}

	@Test
	public void landTopOnlyInsideALandableBoxNotItsSkaterMargin()
	{
		BlockerSet s = rock(BlockerSet.LOW, BlockerSet.LANDABLE);
		assertEquals(70f, s.landTop(2.5f * T + 19, 2.5f * T - 19), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, s.landTop(2.5f * T + 21, 2.5f * T), 0f);
		BlockerSet notLandable = rock(BlockerSet.SOLID, 0);
		assertEquals(Float.NEGATIVE_INFINITY, notLandable.landTop(2.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void blockTopStopsEnteringSolidBoxesWithTheSkaterRadius()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		float face = 2.5f * T - 20;
		// 13 west of the west face -> 11 west: inside the 12-unit skater radius
		assertEquals(70f, s.blockTop(face - 13, 2.5f * T, face - 11, 2.5f * T, BlockerSet.SKATER_R), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(face - 30, 2.5f * T, face - 13, 2.5f * T, BlockerSet.SKATER_R), 0f);
	}

	@Test
	public void blockTopLetsATrappedSkaterMoveOutButNotDeeper()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		float cx = 2.5f * T;
		// 15 east of centre (5 inside the east face): east is out, along the face is no deeper, west is deeper
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(cx + 15, cx, cx + 18, cx, BlockerSet.SKATER_R), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(cx + 15, cx, cx + 15, cx + 3, BlockerSet.SKATER_R), 0f);
		assertEquals(70f, s.blockTop(cx + 15, cx, cx + 12, cx, BlockerSet.SKATER_R), 0f);
	}

	@Test
	public void blockTopCatchesAFastMoveSkippingOverAThinBox()
	{
		// 4 thick (half 2) box: expanded by the radius it is 28 thick; a 40-unit step jumps right over it
		BlockerSet s = new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 60, 2, 1, 0, 300, BlockerSet.SOLID, 0).build(5);
		assertEquals(300f, s.blockTop(2.5f * T, 2.5f * T - 20, 2.5f * T, 2.5f * T + 20, BlockerSet.SKATER_R), 0f);
	}

	@Test
	public void blockTopLetsAMoveGrazePastACornerWhenItEndsClear()
	{
		// a 45-degree rock (half 20): its east corner 20 sqrt 2 east of the centre. A move north 11.9 east of
		// that corner starts and ends 12.55 from it (clear of the radius) and passes within it only in the
		// middle: grazing the corner, not stepping over the rock
		BlockerSet s = new BlockerSetBuilder().add(2.5f * T, 2.5f * T, 20, 20, S45, S45, 70, BlockerSet.SOLID, 0).build(5);
		float x = 2.5f * T + 20 * (float) Math.sqrt(2) + 11.9f;
		float y = 2.5f * T;
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(x, y - 4, x, y + 4, BlockerSet.SKATER_R), 0f);
	}

	@Test
	public void blockTopIgnoresLowBoxesWhichBlockThroughTheirRaisedGround()
	{
		BlockerSet s = rock(BlockerSet.LOW, BlockerSet.LANDABLE);
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(2.5f * T - 40, 2.5f * T, 2.5f * T, 2.5f * T, BlockerSet.SKATER_R), 0f);
		Contact c = new Contact();
		assertTrue("LOW boxes still collide on their sides", s.contact(2.5f * T - 25, 2.5f * T, R, 0, 24, c));
	}

	@Test
	public void cornersFollowTheRotation()
	{
		BlockerSet s = new BlockerSetBuilder().add(100, 200, 10, 5, 0, 1, 50, BlockerSet.SOLID, 0).build(5);
		float[] out = new float[8];
		BlockerSet.corners(s.boxes[0], out);
		// u = (0, 1) points north, v = (-1, 0) west; corner 0 = -hx u - hy v, corner 1 = +hx u - hy v
		assertEquals(105, out[0], 1e-4f);
		assertEquals(190, out[1], 1e-4f);
		assertEquals(105, out[2], 1e-4f);
		assertEquals(210, out[3], 1e-4f);
	}

	@Test
	public void blockTopUsesTheGivenSmallerRadius()
	{
		BlockerSet s = rock(BlockerSet.SOLID, 0);
		float face = 2.5f * T - 20;
		// ending 10 west of the west face: inside a 12 radius, clear of an 8 one
		assertEquals(70f, s.blockTop(face - 30, 2.5f * T, face - 10, 2.5f * T, 12f), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, s.blockTop(face - 30, 2.5f * T, face - 10, 2.5f * T, 8f), 0f);
		assertEquals(70f, s.blockTop(face - 30, 2.5f * T, face - 7, 2.5f * T, 8f), 0f);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.SkateInput;
import com.gielinorskate.physics.SkatePhysics;
import com.gielinorskate.physics.SkateTuning;
import com.gielinorskate.physics.SkaterState;
import org.junit.Test;

/**
 * A bridge deck takes its heights from the plane above (tile settings bridge flag, as
 * {@code Perspective.getTileHeight} reads them). Corner heights shared between tiles let the deck's edge
 * corners take the river-bed heights of the neighbouring river tiles, so the deck sloped into the river and
 * the skater sank through it; each tile now keeps its own corners.
 * <p>
 * Synthetic scene, 12 x 12: a river (bed at 0) runs north-south over columns 4..7, banks at 200 either
 * side; a bridge 3 tiles wide crosses it east-west over rows 5..7, its deck on plane 1 at 200.
 */
public class BridgeTerrainTest
{
	private static final float T = GridCollisionWorld.TILE;
	private static final int N = 12;
	private static final float DECK = 200f;

	private static GridCollisionWorld bridgeWorld()
	{
		int[][][] heights = new int[4][N + 1][N + 1];
		byte[][][] settings = new byte[4][N][N];
		for (int cx = 0; cx <= N; cx++)
		{
			for (int cy = 0; cy <= N; cy++)
			{
				boolean bank = cx <= 4 || cx >= 8;
				heights[0][cx][cy] = bank ? -(int) DECK : 0; // RuneLite z is down-positive
				heights[1][cx][cy] = -(int) DECK;
				heights[2][cx][cy] = -(int) DECK - 240;
				heights[3][cx][cy] = -(int) DECK - 480;
			}
		}
		for (int tx = 4; tx <= 7; tx++)
		{
			for (int ty = 5; ty <= 7; ty++)
			{
				settings[1][tx][ty] = 2;
			}
		}
		GridCollisionWorld w = new GridCollisionWorld(N);
		SceneCollisionBuilder.applyTerrain(w, heights, settings, 0);
		return w;
	}

	@Test
	public void theWholeDeckIsFlatAtDeckHeight()
	{
		GridCollisionWorld w = bridgeWorld();
		for (int tx = 4; tx <= 7; tx++)
		{
			for (int ty = 5; ty <= 7; ty++)
			{
				for (float fx : new float[]{0.01f, 0.5f, 0.99f})
				{
					for (float fy : new float[]{0.01f, 0.5f, 0.99f})
					{
						float x = (tx + fx) * T;
						float y = (ty + fy) * T;
						assertEquals("deck at tile " + tx + "," + ty + " (" + fx + "," + fy + ")", DECK,
							w.groundHeight(x, y), 0.5f);
						assertEquals(DECK, w.terrainHeight(x, y), 0.5f);
					}
				}
			}
		}
	}

	@Test
	public void theRiverBesideTheBridgeKeepsItsBed()
	{
		GridCollisionWorld w = bridgeWorld();
		// river tiles just north and south of the deck are still at the bed, not dragged up to the deck
		assertEquals(0f, w.groundHeight(5.5f * T, 8.5f * T), 0.5f);
		assertEquals(0f, w.groundHeight(5.5f * T, 4.5f * T), 0.5f);
		assertEquals(0f, w.groundHeight(5.5f * T, 8.01f * T), 0.5f);
	}

	@Test
	public void ridingAlongTheBridgeEdgeRowNeverSinks()
	{
		for (float rowY : new float[]{5.15f, 5.5f, 7.5f, 7.85f})
		{
			GridCollisionWorld w = bridgeWorld();
			SkatePhysics p = new SkatePhysics(new SkateTuning(), w, 2.5f * T, rowY * T, (float) (Math.PI / 2));
			SkateInput in = new SkateInput();
			in.pushHeld = true;
			float minH = Float.POSITIVE_INFINITY;
			for (int i = 0; i < 400 && p.getX() < 9.5f * T; i++)
			{
				p.step(0.02f, in);
				assertNotEquals(SkaterState.BAILED, p.getState());
				minH = Math.min(minH, p.getH());
				// no sideways drift off the row: the deck is level across
				assertEquals("row " + rowY, rowY * T, p.getY(), 1f);
			}
			assertTrue("crossed the bridge on row " + rowY + ": x " + p.getX(), p.getX() >= 9.5f * T);
			assertEquals("never sank on row " + rowY, DECK, minH, 0.5f);
		}
	}

	@Test
	public void aTileFlaggedAsBridgeReadsThePlaneAbove()
	{
		byte[][][] settings = new byte[4][2][2];
		settings[1][1][0] = 2;
		assertEquals(1, SceneCollisionBuilder.effectivePlane(settings, 0, 1, 0));
		assertEquals(0, SceneCollisionBuilder.effectivePlane(settings, 0, 0, 0));
		assertEquals(3, SceneCollisionBuilder.effectivePlane(settings, 3, 1, 0));
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class ClutterNamesTest
{
	@Test
	public void plantsAndCropsAreRiddenThrough()
	{
		for (String n : new String[]{"Plant", "Flowers", "Bush", "Bushes", "Fern", "Long grass", "Shrub", "Weeds",
			"Mushrooms", "Crops", "Hay bales", "Reeds", "Daisies", "Cabbage", "Flax", "Potatoes", "Sapling",
			"Tree roots", "Thistle", "Nettles", "Red flower"})
		{
			assertTrue(n, ObjectNames.passByName(n));
		}
	}

	@Test
	public void solidThingsAndLookalikeWordsAreNot()
	{
		for (String n : new String[]{"Rocks", "Boulder", "Tree", "Crate", "Fence", "Planter", "Flowerpot stand",
			"Grassland sign", "Haystack", "Weedkiller", "", null})
		{
			assertFalse(String.valueOf(n), ObjectNames.passByName(n));
		}
	}

	@Test
	public void compoundAndMoreVegetationNamesAreRiddenThrough()
	{
		// whole-word matching missed these: the plant word is glued into a longer word, or was not listed
		for (String n : new String[]{"Rosebush", "Tea bush", "Shrubbery", "Thick vines", "Vines", "Leafy plant",
			"Fallen leaves", "Cactus", "Tall grass", "Ivy", "Lily", "Lilypad", "Bamboo", "Sunflowers", "Tulips",
			"Poppies", "Daisy", "Bramble", "Brambles", "Fungus", "Seaweed", "Kelp", "Foliage", "Herbs", "Onions",
			"Wheat", "Sweetcorn", "Marigolds", "Undergrowth", "Bluebells", "Mossy roots", "Treeroot", "Bullrushes",
			"Wildflowers", "Hay bales", "Jungle bush", "Dead plant", "Small fern", "Snape grass", "Cabbages",
			"Lavender", "Thornbush", "Creeper", "Flowerbed", "Vegetable patch", "Herb patch"})
		{
			assertTrue(n, ObjectNames.passByName(n));
		}
	}

	@Test
	public void treesHedgesFurnitureAndLookalikesStaySolid()
	{
		for (String n : new String[]{"Oak tree", "Bushy tree", "Tree stump", "Hedge", "Rose hedge", "Planter",
			"Plant pot", "Potted plant", "Flowerpot", "Rosewood chair", "Flower stall", "Vine-covered wall",
			"Ivy-covered wall", "Infernal altar", "Ravine", "Divine statue", "Vinegar barrel", "Herblore table",
			"Herbiboar", "Street lamp", "Corner shelf", "Ambush point", "Mushroom stall", "Bamboo desk",
			"Fungus-covered cavern wall", "Rose trellis", "Sign", "Vase of flowers", "Mossy rocks", "Shayzien banner",
			"Wooden table", "Willow", "Yew"})
		{
			assertFalse(n, ObjectNames.passByName(n));
		}
	}

	@Test
	public void theVegetationToggleOffMakesPlantsCollideButOpenDoorsStillPass()
	{
		assertTrue(ObjectNames.passThrough("Rosebush", null, true));
		assertTrue(ObjectNames.passThrough("Thick vines", new String[]{"Cut"}, true));
		assertFalse(ObjectNames.passThrough("Rosebush", null, false));
		assertFalse(ObjectNames.passThrough("Thick vines", new String[]{"Cut"}, false));
		assertTrue(ObjectNames.passThrough("Door", new String[]{"Close"}, false));
		assertFalse(ObjectNames.passThrough("Oak tree", null, true));
	}

	@Test
	public void openDoorsAndGatesPassClosedOnesDoNot()
	{
		assertTrue(ObjectNames.isOpenDoor("Door", new String[]{"Close", null, null}));
		assertTrue(ObjectNames.isOpenDoor("Large door", new String[]{null, "close"}));
		assertTrue(ObjectNames.isOpenDoor("Gate", new String[]{"Close"}));
		assertFalse(ObjectNames.isOpenDoor("Door", new String[]{"Open"}));
		assertFalse(ObjectNames.isOpenDoor("Gate", null));
		assertFalse(ObjectNames.isOpenDoor("Chest", new String[]{"Close"}));
		assertFalse(ObjectNames.isOpenDoor(null, new String[]{"Close"}));
	}

	@Test
	public void passThroughCombinesPlantsAndOpenDoors()
	{
		assertTrue(ObjectNames.passThrough("Bush", null, true));
		assertTrue(ObjectNames.passThrough("Door", new String[]{"Close"}, true));
		assertFalse(ObjectNames.passThrough("Door", new String[]{"Open"}, true));
		assertFalse(ObjectNames.passThrough("Rocks", new String[]{"Mine"}, true));
	}

	/** Stand-in for an object definition with an optional impostor. */
	private static final class Def
	{
		final String name;
		final Def impostor;
		final boolean hasImpostors;

		Def(String name, boolean hasImpostors, Def impostor)
		{
			this.name = name;
			this.hasImpostors = hasImpostors;
			this.impostor = impostor;
		}
	}

	@Test
	public void impostorsAreResolvedBeforeReadingTheName()
	{
		Def flowers = new Def("Flowers", false, null);
		Def wrapper = new Def("null", true, flowers);
		Def resolved = ObjectNames.resolve(wrapper, d -> d.hasImpostors, d -> d.impostor);
		assertEquals("Flowers", resolved.name);
		assertTrue(ObjectNames.passByName(resolved.name));
		assertFalse("the wrapper's own name says nothing", ObjectNames.passByName(wrapper.name));
		Def plain = new Def("Rocks", false, null);
		assertEquals("Rocks", ObjectNames.resolve(plain, d -> d.hasImpostors, d -> d.impostor).name);
		// a varbit-driven object currently showing nothing resolves to nothing
		assertNull(ObjectNames.resolve(new Def("null", true, null), d -> d.hasImpostors, d -> d.impostor));
		assertNull(ObjectNames.resolve((Def) null, d -> d.hasImpostors, d -> d.impostor));
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import org.junit.Test;

public class ClutterRulesTest
{
	@Test
	public void classifyByNameHeightAndFootprint()
	{
		assertEquals(BlockerSet.PASS, ObjectShapes.classify(true, 300, 200));
		assertEquals("height 24 is stepped over", BlockerSet.PASS, ObjectShapes.classify(false, 24, 100));
		assertEquals("thin slice", BlockerSet.PASS, ObjectShapes.classify(false, 200, 29));
		assertEquals(BlockerSet.LOW, ObjectShapes.classify(false, 25, 40));
		assertEquals(BlockerSet.LOW, ObjectShapes.classify(false, 120, 110));
		assertEquals("too narrow to stand on", BlockerSet.SOLID, ObjectShapes.classify(false, 100, 39));
		assertEquals(BlockerSet.SOLID, ObjectShapes.classify(false, 121, 110));
	}

	@Test
	public void grindablesAreLowUpToThePlatformHeightAndAlwaysLandable()
	{
		assertEquals(BlockerSet.LOW, grindableKind(16));
		assertEquals(BlockerSet.LOW, grindableKind(120));
		assertEquals(BlockerSet.SOLID, grindableKind(150));
	}

	private static byte grindableKind(float height)
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.addGrindableBlocker(256, 256, new float[]{-40, 40, -4, 4}, 0, height);
		assertEquals(BlockerSet.LANDABLE, WorldTests.flags(w.getBlockers(), 0));
		return WorldTests.kind(w.getBlockers(), 0);
	}

	@Test
	public void sliceKeepsOnlyVerticesAtSkaterHeight()
	{
		// tree: trunk 50 wide from the ground to 90 up, canopy 200 wide from 150 to 300 up (model y is negative-up)
		float[] xs = {-25, 25, -25, 25, -100, 100, -100, 100};
		float[] ys = {0, 0, -90, -90, -150, -150, -300, -300};
		float[] zs = {-25, 25, -25, 25, -100, 100, -100, 100};
		assertArrayEquals(new float[]{-25, 25, -25, 25}, ObjectShapes.sliceExtents(xs, ys, zs, 8, 90), 0f);
		// a floating sign with nothing below 90 has no slice
		assertNull(ObjectShapes.sliceExtents(new float[]{-5, 5}, new float[]{-100, -120}, new float[]{0, 0}, 2, 90));
		// the vertex count limits the arrays
		assertArrayEquals(new float[]{-25, 25, -25, 25}, ObjectShapes.sliceExtents(xs, ys, zs, 4, 90), 0f);
	}

	@Test
	public void crateSliceIsItsWholeFootprint()
	{
		float[] xs = {-55, 55, 55, -55, -55, 55, 55, -55};
		float[] ys = {0, 0, 0, 0, -100, -100, -100, -100};
		float[] zs = {-55, -55, 55, 55, -55, -55, 55, 55};
		float[] ext = ObjectShapes.sliceExtents(xs, ys, zs, 8, 90);
		assertArrayEquals(new float[]{-55, 55, -55, 55}, ext, 0f);
		assertEquals(110f, ObjectShapes.minSide(ext), 0f);
	}

	@Test
	public void boxIsTheRotatedExtentsLikeTheRailShape()
	{
		// 100 x 20 model offset 10 along +x, at origin (1000, 2000), unrotated
		float[] b = ObjectShapes.box(1000, 2000, new float[]{-40, 60, -10, 10}, 0, 0);
		assertArrayEquals(new float[]{1010, 2000, 50, 10, 1, 0}, b, 1e-4f);
		// orientation 512 (a quarter turn): model x maps to local -y (x' = x cos + z sin, y' = z cos - x sin)
		float[] r = ObjectShapes.box(1000, 2000, new float[]{-40, 60, -10, 10}, 512, 0);
		assertEquals(1000f, r[0], 1e-3f);
		assertEquals(1990f, r[1], 1e-3f);
		assertEquals(50f, r[2], 0f);
		assertEquals(10f, r[3], 0f);
		assertEquals(0f, r[4], 1e-5f);
		assertEquals(-1f, r[5], 1e-5f);
	}

	@Test
	public void boxInflatesThinSidesToTheMinimumHalf()
	{
		float[] b = ObjectShapes.box(0, 0, new float[]{-60, 60, -2, 2}, 0, 12);
		assertEquals(60f, b[2], 0f);
		assertEquals(12f, b[3], 0f);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import java.util.List;
import org.junit.Test;

public class GridAddedGrindsTest
{
	private static final float T = GridCollisionWorld.TILE;

	@Test
	public void addedSegmentAppearsInTheGrindMap()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.addGrindSegment(w, new GrindSegment(0, T, 2 * T, T, 40f));
		w.rebuildGrinds();
		List<GrindSegment> s = w.getGrinds().segments();
		assertEquals(1, s.size());
		assertEquals(40f, s.get(0).top, 1e-3f);
		assertEquals(2 * T, s.get(0).length(), 1e-3f);
	}

	@Test
	public void addedSegmentDuplicatingAFlagRailCollapses()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 50f);
		w.addEdgeGrind(1, 1, GridCollisionWorld.WALL_N, 50f);
		w.addEdgeGrind(1, 2, GridCollisionWorld.WALL_S, 50f); // same edge seen from the other tile
		w.rebuildGrinds();
		assertEquals(1, w.getGrinds().segments().size());
	}

	@Test
	public void addedSegmentExtendingAFlagRailMerges()
	{
		GridCollisionWorld w = new GridCollisionWorld(6);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 40f);
		w.addEdgeGrind(2, 1, GridCollisionWorld.WALL_N, 40f);
		w.rebuildGrinds();
		List<GrindSegment> s = w.getGrinds().segments();
		assertEquals(1, s.size());
		assertEquals(2 * T, s.get(0).length(), 1e-3f);
	}

	@Test
	public void edgeGrindSitsOnTheEdgeGround()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.setCornerHeight(w, 1, 2, 10f);
		WorldTests.setCornerHeight(w, 2, 2, 30f);
		w.addEdgeGrind(1, 1, GridCollisionWorld.WALL_N, 40f);
		w.rebuildGrinds();
		assertEquals(20f + 40f, w.getGrinds().segments().get(0).top, 1e-3f);
	}

	@Test
	public void oneTileFootprintGivesFourEdges()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		addFootprintGrind(w, 1, 1, 1, 1, 40f);
		w.rebuildGrinds();
		List<GrindSegment> s = w.getGrinds().segments();
		assertEquals(4, s.size());
		for (GrindSegment g : s)
		{
			assertEquals(T, g.length(), 1e-3f);
			assertEquals(40f, g.top, 1e-3f);
		}
	}

	@Test
	public void longFootprintMergesIntoItsPerimeter()
	{
		GridCollisionWorld w = new GridCollisionWorld(8);
		addFootprintGrind(w, 1, 2, 4, 2, 60f); // a 4x1 fence/bench run
		w.rebuildGrinds();
		List<GrindSegment> s = w.getGrinds().segments();
		assertEquals(4, s.size());
		float total = 0f;
		for (GrindSegment g : s)
		{
			total += g.length();
		}
		assertEquals(10 * T, total, 1e-3f); // 4 + 4 + 1 + 1 tiles
	}

	@Test
	public void footprintIsClippedToTheGrid()
	{
		GridCollisionWorld w = new GridCollisionWorld(2);
		addFootprintGrind(w, -1, 0, 5, 0, 40f);
		w.rebuildGrinds();
		for (GrindSegment g : w.getGrinds().segments())
		{
			assertEquals(true, g.x0 >= 0 && g.x1 <= 2 * T && g.y1 <= 2 * T);
		}
	}

	@Test
	public void addedGrindsSurviveARebuild()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.addEdgeGrind(1, 1, GridCollisionWorld.WALL_E, 40f);
		w.rebuildGrinds();
		w.rebuildGrinds();
		assertEquals(1, w.getGrinds().segments().size());
	}

	@Test
	public void benchFootprintIsCaughtFromAnOllieButNotWhileRollingPast()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		addFootprintGrind(w, 1, 1, 1, 1, 40f); // bench, 40 high on flat ground
		w.rebuildGrinds();
		GrindMap m = w.getGrinds();
		// dropping onto its north edge from an ollie, travelling east along it
		assertEquals(true, m.nearest(1.5f * T, 2 * T + 10f, 35f, (float) (Math.PI / 2), null, GrindMap.SNAP_DISTANCE) != null);
		// rolling along the ground beside it: 0 is below top - BELOW_TOP = 24, so no snap
		assertEquals(null, m.nearest(1.5f * T, 2 * T + 10f, 0f, (float) (Math.PI / 2), null, GrindMap.SNAP_DISTANCE));
	}

	@Test
	public void wallOrientationBitsMapToSides()
	{
		assertEquals(GridCollisionWorld.WALL_W, SceneCollisionBuilder.wallSides(1));
		assertEquals(GridCollisionWorld.WALL_N, SceneCollisionBuilder.wallSides(2));
		assertEquals(GridCollisionWorld.WALL_E, SceneCollisionBuilder.wallSides(4));
		assertEquals(GridCollisionWorld.WALL_S, SceneCollisionBuilder.wallSides(8));
		assertEquals(GridCollisionWorld.WALL_W | GridCollisionWorld.WALL_N, SceneCollisionBuilder.wallSides(1 | 2));
		assertEquals(0, SceneCollisionBuilder.wallSides(16)); // diagonals are skipped
		assertEquals(0, SceneCollisionBuilder.wallSides(128));
	}

	@Test
	public void objectGrindIsACentrelineAtTerrainUnderItsCentrePlusHeight()
	{
		// a 128 x 10 fence centred in tile (1, 1) on a 20-high corner-raised tile that is also a FULL
		// platform: the rail sits at terrain + model height, not on top of the platform
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.setCornerHeight(w, 1, 1, 20f);
		WorldTests.setCornerHeight(w, 2, 1, 20f);
		WorldTests.setCornerHeight(w, 1, 2, 20f);
		WorldTests.setCornerHeight(w, 2, 2, 20f);
		w.setTile(1, 1, GridCollisionWorld.FULL, 50f);
		w.addObjectGrind(192, 192, new float[]{-64, 64, -5, 5}, 0, 50f);
		w.rebuildGrinds();
		GrindSegment rail = null;
		for (GrindSegment g : w.getGrinds().segments())
		{
			if (Math.abs(g.y0 - 192) < 1e-3f && Math.abs(g.y1 - 192) < 1e-3f)
			{
				rail = g;
			}
		}
		assertNotNull(rail);
		assertEquals(70f, rail.top, 1e-3f);
		assertEquals(T, rail.length(), 1e-3f);
		assertEquals(20f, w.terrainHeight(192, 192), 1e-3f);
		assertEquals(70f, w.groundHeight(192, 192), 1e-3f);
	}

	/**
	 * The perimeter of the tile rectangle [minX..maxX] x [minY..maxY] (inclusive, clipped to the grid) as one-tile
	 * edge grinds at ground plus {@code above}; rebuildGrinds merges each side into one run.
	 */
	private static void addFootprintGrind(GridCollisionWorld w, int minX, int minY, int maxX, int maxY, float above)
	{
		int x0 = Math.max(0, minX);
		int y0 = Math.max(0, minY);
		int x1 = Math.min(w.size() - 1, maxX);
		int y1 = Math.min(w.size() - 1, maxY);
		for (int tx = x0; tx <= x1 && y0 <= y1; tx++)
		{
			w.addEdgeGrind(tx, y0, GridCollisionWorld.WALL_S, above);
			w.addEdgeGrind(tx, y1, GridCollisionWorld.WALL_N, above);
		}
		for (int ty = y0; ty <= y1 && x0 <= x1; ty++)
		{
			w.addEdgeGrind(x0, ty, GridCollisionWorld.WALL_W, above);
			w.addEdgeGrind(x1, ty, GridCollisionWorld.WALL_E, above);
		}
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Contact;
import org.junit.Test;

/** Tight object boxes and wall-edge boxes inside {@link GridCollisionWorld}. */
public class GridBlockersTest
{
	private static final float T = GridCollisionWorld.TILE;
	private static final float NEG = Float.NEGATIVE_INFINITY;

	/** 6x6 world, terrain at `ground` everywhere. */
	private static GridCollisionWorld world(float ground)
	{
		GridCollisionWorld w = new GridCollisionWorld(6);
		for (int x = 0; x <= 6; x++)
		{
			for (int y = 0; y <= 6; y++)
			{
				WorldTests.setCornerHeight(w, x, y, ground);
			}
		}
		return w;
	}

	/** A grind segment passing within 1 unit of (x, y), or null. */
	private static GrindSegment near(GridCollisionWorld w, float x, float y)
	{
		for (GrindSegment s : w.getGrinds().segments())
		{
			float dx = s.x1 - s.x0;
			float dy = s.y1 - s.y0;
			float t = Math.max(0f, Math.min(1f, ((x - s.x0) * dx + (y - s.y0) * dy) / (dx * dx + dy * dy)));
			if (Math.hypot(s.x0 + t * dx - x, s.y0 + t * dy - y) < 1f)
			{
				return s;
			}
		}
		return null;
	}

	/** A FULL tile (2, 2) holding one model whose slice is a centred square of the given half size. */
	private static GridCollisionWorld oneObject(float half, float height, boolean pass)
	{
		GridCollisionWorld w = world(0);
		w.setTile(2, 2, GridCollisionWorld.FULL, height);
		w.markShaped(2, 2);
		w.addObjectBlocker(2.5f * T, 2.5f * T, new float[]{-half, half, -half, half}, 0, height, pass, true);
		return w;
	}

	@Test
	public void aRockBlocksOnlyAroundItselfNotTheWholeTile()
	{
		GridCollisionWorld w = oneObject(32, 200, false);
		// crossing into the tile far from the 64x64 rock: free (the whole tile used to block)
		assertEquals(NEG, w.blockerTop(1.95f * T, 2.1f * T, 2.05f * T, 2.1f * T), 0f);
		// rolling into the rock's west face (2.5 T - 32), within the 12 skater radius
		float face = 2.5f * T - 32;
		assertEquals(200f, w.blockerTop(face - 14, 2.5f * T, face - 10, 2.5f * T), 0f);
		Contact c = new Contact();
		assertTrue(w.contact(face - 10, 2.5f * T, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(-1f, c.nx, 1e-5f);
		assertEquals(2f, c.depth, 1e-4f);
	}

	@Test
	public void aRotatedRockTurnsWithItsModel()
	{
		GridCollisionWorld w = world(0);
		w.setTile(2, 2, GridCollisionWorld.FULL, 200);
		w.markShaped(2, 2);
		// 120 x 40 slab turned an eighth (256 JAU): it runs from south-east to north-west
		w.addObjectBlocker(2.5f * T, 2.5f * T, new float[]{-60, 60, -20, 20}, 256, 200, false, true);
		Contact c = new Contact();
		float d = 40 * (float) Math.sqrt(0.5);
		assertTrue("on the slab's axis, 40 from the centre", w.contact(2.5f * T - d, 2.5f * T + d, 1, 0, 24, c));
		assertFalse("40 along the unrotated x axis is off the slab", w.contact(2.5f * T + 40, 2.5f * T, 1, 0, 24, c));
	}

	@Test
	public void aCrateIsLandableOnlyInsideItsOwnBox()
	{
		GridCollisionWorld w = world(20);
		w.setTile(2, 2, GridCollisionWorld.FULL, 100);
		w.markShaped(2, 2);
		assertEquals(BlockerSet.LOW, w.addObjectBlocker(2.5f * T, 2.5f * T, new float[]{-40, 40, -40, 40}, 0, 100, false, true));
		assertEquals(120f, w.groundHeight(2.5f * T + 39, 2.5f * T), 1e-3f);
		assertEquals("just outside the crate is plain ground (was the whole tile)", 20f, w.groundHeight(2.5f * T + 41, 2.5f * T), 1e-3f);
		assertEquals(20f, w.groundHeight(2.1f * T, 2.1f * T), 1e-3f);
	}

	@Test
	public void lowObjectsAreStillHitOnTheirSides()
	{
		GridCollisionWorld w = oneObject(40, 100, false);
		Contact c = new Contact();
		assertTrue(w.contact(2.5f * T, 2.5f * T - 45, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(-1f, c.ny, 1e-5f);
		assertFalse("airborne above the top", w.contact(2.5f * T, 2.5f * T - 45, BlockerSet.SKATER_R, 80, 24, c));
	}

	@Test
	public void lowObjectEdgesAreLedges()
	{
		GridCollisionWorld w = oneObject(40, 100, false);
		w.rebuildGrinds();
		GrindSegment s = near(w, 2.5f * T, 2.5f * T - 40);
		assertTrue(s != null);
		assertEquals(100f, s.top, 1e-3f);
		assertEquals(80f, s.length(), 1e-3f);
	}

	@Test
	public void objectsUpToAStepTallAreIgnored()
	{
		GridCollisionWorld w = oneObject(40, 24, false);
		assertEquals(0f, w.groundHeight(2.5f * T, 2.5f * T), 0f);
		assertFalse(w.contact(2.5f * T, 2.5f * T, BlockerSet.SKATER_R, 0, 0, new Contact()));
		assertEquals(NEG, w.blockerTop(2.5f * T - 60, 2.5f * T, 2.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void plantsAreRiddenThrough()
	{
		GridCollisionWorld w = oneObject(40, 90, true);
		assertEquals(BlockerSet.PASS, WorldTests.kind(w.getBlockers(), 0));
		assertEquals(0f, w.groundHeight(2.5f * T, 2.5f * T), 0f);
		assertFalse(w.contact(2.5f * T, 2.5f * T, BlockerSet.SKATER_R, 0, 24, new Contact()));
		assertEquals(NEG, w.blockerTop(2.5f * T - 60, 2.5f * T, 2.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void aModelLessFullTileFallsBackToA96Box()
	{
		GridCollisionWorld w = world(0);
		w.setTile(2, 2, GridCollisionWorld.FULL, 32);
		w.addFallbackBlocker(2, 2);
		assertEquals(NEG, w.blockerTop(1.95f * T, 2.05f * T, 2.05f * T, 2.05f * T), 0f);
		float face = 2.5f * T - 48;
		assertEquals(400f, w.blockerTop(face - 13, 2.5f * T, face - 11, 2.5f * T), 0f);
		assertEquals("no platform rise", 0f, w.groundHeight(2.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void unshapedFullTilesKeepWholeTileCollisionInContact()
	{
		GridCollisionWorld w = world(0);
		w.setTile(2, 2, GridCollisionWorld.FULL, 400);
		Contact c = new Contact();
		assertTrue(w.contact(2 * T - 5, 2.1f * T, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(-1f, c.nx, 1e-5f);
		assertEquals(7f, c.depth, 1e-4f);
		assertEquals(400f, c.top, 0f);
	}

	@Test
	public void wallEdgesAreThinBoxesInContact()
	{
		GridCollisionWorld w = world(0);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 60);
		Contact c = new Contact();
		// 10 south of the north edge (y = 2 T); the wall is 2 thick on this side
		assertTrue(w.contact(1.5f * T, 2 * T - 10, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(0f, c.nx, 1e-5f);
		assertEquals(-1f, c.ny, 1e-5f);
		assertEquals(4f, c.depth, 1e-4f);
		assertEquals(60f, c.top, 0f);
		assertFalse("hopping over: 60 <= 40 + 24", w.contact(1.5f * T, 2 * T - 10, BlockerSet.SKATER_R, 40, 24, c));
		// the east wall runs north-south
		w.setTile(3, 3, GridCollisionWorld.WALL_E, 300);
		assertTrue(w.contact(4 * T + 8, 3.5f * T, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(1f, c.nx, 1e-5f);
		assertEquals(300f, c.top, 0f);
	}

	@Test
	public void wallHeightIsKeptApartFromTheTallestObjectOnTheTile()
	{
		GridCollisionWorld w = world(0);
		// a fence (60) on the north edge of a tile that also has a lamp post (300)
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 300);
		w.setWallHeight(1, 1, 60);
		assertEquals(60f, w.blockerTop(1.5f * T, 1.95f * T, 1.5f * T, 2.05f * T), 1e-3f);
		w.rebuildGrinds();
		GrindSegment s = near(w, 1.5f * T, 2 * T);
		assertTrue(s != null);
		assertEquals(60f, s.top, 1e-3f);
	}

	@Test
	public void aSkaterInsideATallBoxCanOnlyLeaveTheShortestWay()
	{
		GridCollisionWorld w = oneObject(40, 300, false);
		Contact c = new Contact();
		// 30 east of centre: 10 inside the east face
		assertTrue(w.contact(2.5f * T + 30, 2.5f * T + 5, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(1f, c.nx, 0f);
		assertEquals(10f + BlockerSet.SKATER_R, c.depth, 1e-4f);
		assertEquals(NEG, w.blockerTop(2.5f * T + 30, 2.5f * T, 2.5f * T + 34, 2.5f * T), 0f);
		assertEquals(300f, w.blockerTop(2.5f * T + 30, 2.5f * T, 2.5f * T + 26, 2.5f * T), 0f);
	}

	@Test
	public void aGrindableBenchIsInflatedBlocksAndIsLandable()
	{
		GridCollisionWorld w = world(0);
		// 200 x 8 bench, 100 tall, on a tile the collision flags leave open
		w.addGrindableBlocker(2.5f * T, 2.5f * T, new float[]{-100, 100, -4, 4}, 0, 100);
		assertEquals(BlockerSet.LOW, WorldTests.kind(w.getBlockers(), 0));
		assertEquals("thin side inflated to 12 either side", 100f, w.groundHeight(2.5f * T, 2.5f * T + 11), 1e-3f);
		assertEquals(0f, w.groundHeight(2.5f * T, 2.5f * T + 13), 1e-3f);
		Contact c = new Contact();
		assertTrue(w.contact(2.5f * T, 2.5f * T - 20, BlockerSet.SKATER_R, 0, 24, c));
		assertEquals(-1f, c.ny, 1e-5f);
		// a 150-tall counter is SOLID (blocks in blockerTop) but still landable
		GridCollisionWorld w2 = world(0);
		w2.addGrindableBlocker(2.5f * T, 2.5f * T, new float[]{-100, 100, -4, 4}, 0, 150);
		assertEquals(BlockerSet.SOLID, WorldTests.kind(w2.getBlockers(), 0));
		assertEquals(150f, w2.groundHeight(2.5f * T, 2.5f * T), 1e-3f);
		assertEquals(150f, w2.blockerTop(2.5f * T, 2.5f * T - 30, 2.5f * T, 2.5f * T - 22), 0f);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GridCollisionWorldTest
{
	private static final float T = GridCollisionWorld.TILE;

	@Test
	public void flatWorldIsZero()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		assertEquals(0f, w.groundHeight(1.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void edgeDistanceIsUnlimitedUntilTheLoadedAreaIsSet()
	{
		GridCollisionWorld w = new GridCollisionWorld(104);
		assertEquals(Float.POSITIVE_INFINITY, w.edgeDistance(50 * T, 50 * T), 0f);
	}

	@Test
	public void edgeDistanceMeasuresToTheNearestSideOfTheLoadedArea()
	{
		// the client blocks tile 0 and tiles 99+ of a 104-tile scene: free tiles 1..98
		GridCollisionWorld w = new GridCollisionWorld(104);
		w.setLoadedTiles(1, 99);
		assertEquals(49 * T, w.edgeDistance(50 * T, 50 * T), 1e-3f);
		assertEquals(2 * T, w.edgeDistance(3 * T, 50 * T), 1e-3f);
		assertEquals(T, w.edgeDistance(50 * T, 98 * T), 1e-3f);
		assertTrue(w.edgeDistance(0.5f * T, 50 * T) < 0f);
	}

	@Test
	public void groundIsBilinearBetweenCorners()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.setCornerHeight(w, 1, 0, 100f);
		WorldTests.setCornerHeight(w, 1, 1, 100f);
		// tile (0,0): west corners 0, east corners 100 -> centre 50
		assertEquals(50f, w.groundHeight(0.5f * T, 0.5f * T), 1e-3f);
		assertEquals(100f, w.groundHeight(1.0f * T, 0.5f * T), 1e-3f);
	}

	@Test
	public void eastWallBlocksCrossingAndReportsTop()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_E, 300f);
		float top = w.blockerTop(1.9f * T, 1.5f * T, 2.05f * T, 1.5f * T);
		assertEquals(300f, top, 1e-3f);
	}

	@Test
	public void neighbourWestWallBlocksSameEdge()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(2, 1, GridCollisionWorld.WALL_W, 80f);
		assertEquals(80f, w.blockerTop(1.9f * T, 1.5f * T, 2.05f * T, 1.5f * T), 1e-3f);
	}

	@Test
	public void movingInsideATileIsNeverBlocked()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_N | GridCollisionWorld.WALL_E, 300f);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(1.2f * T, 1.2f * T, 1.4f * T, 1.4f * T), 0f);
	}

	@Test
	public void northWallUsesPositiveY()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 200f);
		assertEquals(200f, w.blockerTop(1.5f * T, 1.95f * T, 1.5f * T, 2.05f * T), 1e-3f);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(1.5f * T, 1.05f * T, 1.5f * T, 0.95f * T), 0f);
	}

	@Test
	public void tallFullTileBlocks()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(2, 2, GridCollisionWorld.FULL, 400f);
		assertEquals(400f, w.blockerTop(1.9f * T, 2.5f * T, 2.05f * T, 2.5f * T), 1e-3f);
		assertEquals(0f, w.groundHeight(2.5f * T, 2.5f * T), 0f);
	}

	@Test
	public void lowFullTileIsAPlatform()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(2, 2, GridCollisionWorld.FULL, 60f);
		assertEquals(60f, w.groundHeight(2.5f * T, 2.5f * T), 1e-3f);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(1.9f * T, 2.5f * T, 2.05f * T, 2.5f * T), 0f);
	}

	@Test
	public void diagonalMoveCannotCutThroughCornerWalls()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_E | GridCollisionWorld.WALL_N, 300f);
		float top = w.blockerTop(1.95f * T, 1.95f * T, 2.05f * T, 2.05f * T);
		assertEquals(300f, top, 1e-3f);
	}

	@Test
	public void diagonalMoveSlipsPastSingleWall()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_E, 300f);
		float top = w.blockerTop(1.95f * T, 1.95f * T, 2.05f * T, 2.05f * T);
		assertEquals(Float.NEGATIVE_INFINITY, top, 0f);
	}

	@Test
	public void diagonalMoveIgnoresUnrelatedWallOnTarget()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(2, 2, GridCollisionWorld.WALL_W, 300f);
		float top = w.blockerTop(1.95f * T, 1.95f * T, 2.05f * T, 2.05f * T);
		assertEquals(Float.NEGATIVE_INFINITY, top, 0f);
	}

	@Test
	public void leavingTheWorldIsInfinitelyBlocked()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		assertTrue(Float.isInfinite(w.blockerTop(0.05f * T, 1.5f * T, -0.05f * T, 1.5f * T)));
		assertTrue(w.blockerTop(3.95f * T, 1.5f * T, 4.05f * T, 1.5f * T) > 0);
	}

	@Test
	public void skaterInsideASolidTileCanMoveOut()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(2, 2, GridCollisionWorld.FULL, 400f);
		// moving within the solid tile and out of it is allowed; moving in is still blocked
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(2.4f * T, 2.5f * T, 2.6f * T, 2.5f * T), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(2.95f * T, 2.5f * T, 3.05f * T, 2.5f * T), 0f);
		assertEquals(400f, w.blockerTop(1.95f * T, 2.5f * T, 2.05f * T, 2.5f * T), 1e-3f);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class GridGrindExtractionTest
{
	private static final float T = GridCollisionWorld.TILE;

	private static List<GrindSegment> grinds(GridCollisionWorld w)
	{
		w.rebuildGrinds();
		return w.getGrinds().segments();
	}

	@Test
	public void newWorldHasAnEmptyGrindMap()
	{
		assertTrue(new GridCollisionWorld(4).getGrinds().segments().isEmpty());
	}

	@Test
	public void lowEastWallBecomesARailAlongThatEdge()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.setCornerHeight(w, 2, 1, 10f);
		WorldTests.setCornerHeight(w, 2, 2, 30f);
		w.setTile(1, 1, GridCollisionWorld.WALL_E, 50f);
		List<GrindSegment> s = grinds(w);
		assertEquals(1, s.size());
		GrindSegment g = s.get(0);
		assertEquals(2 * T, g.x0, 1e-3f);
		assertEquals(2 * T, g.x1, 1e-3f);
		assertEquals(T, Math.min(g.y0, g.y1), 1e-3f);
		assertEquals(2 * T, Math.max(g.y0, g.y1), 1e-3f);
		assertEquals(20f + 50f, g.top, 1e-3f); // mean edge ground (10, 30) + blocker height
	}

	@Test
	public void sameEdgeFlaggedOnBothNeighboursGivesOneRail()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_E, 50f);
		w.setTile(2, 1, GridCollisionWorld.WALL_W, 50f);
		assertEquals(1, grinds(w).size());
	}

	@Test
	public void adjacentFenceTilesMergeIntoOneLongRail()
	{
		GridCollisionWorld w = new GridCollisionWorld(6);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 40f);
		w.setTile(2, 1, GridCollisionWorld.WALL_N, 40f);
		w.setTile(3, 1, GridCollisionWorld.WALL_N, 40f);
		List<GrindSegment> s = grinds(w);
		assertEquals(1, s.size());
		assertEquals(3 * T, s.get(0).length(), 1e-3f);
		assertEquals(2 * T, s.get(0).y0, 1e-3f);
	}

	@Test
	public void tallFenceUpToTheNewMaximumIsARail()
	{
		// GRIND_WALL_MAX raised 100 -> 180 so taller fences can be ground with a charged ollie
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_N, 160f);
		List<GrindSegment> s = grinds(w);
		assertEquals(1, s.size());
		assertEquals(160f, s.get(0).top, 1e-3f);
	}

	@Test
	public void wallsOutsideTheGrindableHeightRangeAreIgnored()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.WALL_S, 400f);
		w.setTile(2, 2, GridCollisionWorld.WALL_S, 10f);
		assertTrue(grinds(w).isEmpty());
	}

	@Test
	public void lonePlatformContributesAllFourEdgesAtItsTop()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.FULL, 60f);
		List<GrindSegment> s = grinds(w);
		assertEquals(4, s.size());
		for (GrindSegment g : s)
		{
			assertEquals(60f, g.top, 1e-3f);
			assertEquals(T, g.length(), 1e-3f);
		}
	}

	@Test
	public void platformRowOnlyGrindsItsPerimeter()
	{
		GridCollisionWorld w = new GridCollisionWorld(5);
		w.setTile(1, 1, GridCollisionWorld.FULL, 60f);
		w.setTile(2, 1, GridCollisionWorld.FULL, 60f);
		List<GrindSegment> s = grinds(w);
		// north and south edges merge to 2 tiles long, plus the west and east ends; no inner edge
		assertEquals(4, s.size());
		float total = 0f;
		for (GrindSegment g : s)
		{
			total += g.length();
		}
		assertEquals(6 * T, total, 1e-3f);
	}

	@Test
	public void tallFullBlockersAreNotLedges()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(1, 1, GridCollisionWorld.FULL, 300f);
		assertTrue(grinds(w).isEmpty());
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import org.junit.Test;

public class GrindMapTest
{
	private static final float NORTH = 0f;
	private static final float EAST = (float) (Math.PI / 2);

	private static float deg(double d)
	{
		return (float) Math.toRadians(d);
	}

	@Test
	public void segmentLengthAndClampedProjection()
	{
		GrindSegment s = new GrindSegment(0, 0, 0, 200, 50);
		assertEquals(200f, s.length(), 1e-4f);
		assertEquals(0.25f, s.project(10, 50), 1e-5f);
		assertEquals(0f, s.project(0, -80), 0f);
		assertEquals(1f, s.project(5, 900), 0f);
	}

	@Test
	public void mergeJoinsCollinearTouchingSegmentsWithEqualTop()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(128, 0, 128, 128, 50));
		m.add(new GrindSegment(128, 256, 128, 128, 53)); // reversed direction, top within 4
		m.add(new GrindSegment(128, 256, 128, 384, 50));
		m.merge();
		assertEquals(1, m.segments().size());
		GrindSegment s = m.segments().get(0);
		assertEquals(384f, s.length(), 1e-3f);
		assertEquals(128f, s.x0, 1e-3f);
		assertEquals(128f, s.x1, 1e-3f);
	}

	@Test
	public void mergeDedupesIdenticalSegments()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 128, 128, 128, 40));
		m.add(new GrindSegment(0, 128, 128, 128, 40));
		m.merge();
		assertEquals(1, m.segments().size());
		assertEquals(128f, m.segments().get(0).length(), 1e-3f);
	}

	@Test
	public void mergeKeepsDifferentTopsGapsAndParallelLinesApart()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 128, 0, 40));
		m.add(new GrindSegment(128, 0, 256, 0, 60)); // touching but 20 higher
		m.add(new GrindSegment(300, 0, 400, 0, 40)); // collinear but a gap
		m.add(new GrindSegment(0, 128, 128, 128, 40)); // parallel, other line
		m.add(new GrindSegment(128, 0, 128, 128, 40)); // touching, perpendicular
		m.merge();
		assertEquals(5, m.segments().size());
	}

	@Test
	public void nearestFindsSegmentWithinSnapDistanceAndHeightWindow()
	{
		GrindMap m = new GrindMap();
		GrindSegment s = new GrindSegment(0, 0, 0, 400, 50);
		m.add(s);
		GrindMap.Hit hit = m.nearest(20, 100, 60, NORTH, null, GrindMap.SNAP_DISTANCE);
		assertNotNull(hit);
		assertSame(s, hit.segment);
		assertEquals(0.25f, hit.t, 1e-5f);

		assertNotNull("44 sideways", m.nearest(44, 100, 60, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNull("too far sideways", m.nearest(45, 100, 60, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNotNull("lowest h", m.nearest(0, 100, 34, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNull("below the window", m.nearest(0, 100, 33, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNotNull("highest h", m.nearest(0, 100, 98, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNull("above the window", m.nearest(0, 100, 99, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNull("past the end", m.nearest(0, 445, 50, NORTH, null, GrindMap.SNAP_DISTANCE));
	}

	/** MAX_APPROACH is 88 degrees (review P3; was 80). */
	@Test
	public void nearestRequiresTravelWithinEightyEightDegreesOfTheLineEitherWay()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 0, 400, 50));
		assertNotNull(m.nearest(0, 100, 50, deg(87), null, GrindMap.SNAP_DISTANCE));
		assertNotNull(m.nearest(0, 100, 50, deg(180 + 87), null, GrindMap.SNAP_DISTANCE));
		assertNotNull(m.nearest(0, 100, 50, deg(180), null, GrindMap.SNAP_DISTANCE));
		assertNull(m.nearest(0, 100, 50, deg(89), null, GrindMap.SNAP_DISTANCE));
		assertNull(m.nearest(0, 100, 50, EAST, null, GrindMap.SNAP_DISTANCE));
		assertNull(m.nearest(0, 100, 50, deg(-91), null, GrindMap.SNAP_DISTANCE));
	}

	@Test
	public void nearestPicksTheClosestCandidate()
	{
		GrindMap m = new GrindMap();
		GrindSegment far = new GrindSegment(20, 0, 20, 400, 50);
		GrindSegment near = new GrindSegment(-5, 0, -5, 400, 50);
		m.add(far);
		m.add(near);
		assertSame(near, m.nearest(0, 100, 50, NORTH, null, GrindMap.SNAP_DISTANCE).segment);
	}

	@Test
	public void emptyMapFindsNothing()
	{
		assertNull(new GrindMap().nearest(0, 0, 0, NORTH, null, GrindMap.SNAP_DISTANCE));
	}

	@Test
	public void connectedAtFindsTheNextPieceAroundAGentleBend()
	{
		GrindMap m = new GrindMap();
		GrindSegment a = new GrindSegment(0, 0, 0, 200, 30);
		GrindSegment b = new GrindSegment(10, 210, 110, 310, 40); // 45 degrees, a 14-unit gap, 10 higher
		m.add(a);
		m.add(b);
		assertSame(b, m.connectedAt(0, 200, 30, 0, 1, a));
		// travelling the other way along a, from its (0, 0) end: nothing there
		assertNull(m.connectedAt(0, 0, 30, 0, -1, a));
	}

	@Test
	public void connectedAtAcceptsEitherEndOfTheNextPiece()
	{
		GrindMap m = new GrindMap();
		GrindSegment a = new GrindSegment(0, 0, 0, 200, 30);
		GrindSegment b = new GrindSegment(110, 310, 10, 210, 30); // stored far end first
		m.add(a);
		m.add(b);
		assertSame(b, m.connectedAt(0, 200, 30, 0, 1, a));
	}

	@Test
	public void connectedAtLimitsBendGapTopAndExcludesTheCurrentPiece()
	{
		GrindSegment a = new GrindSegment(0, 0, 0, 200, 30);
		float c74 = (float) Math.cos(Math.toRadians(74));
		float s74 = (float) Math.sin(Math.toRadians(74));
		float c76 = (float) Math.cos(Math.toRadians(76));
		float s76 = (float) Math.sin(Math.toRadians(76));

		assertNotNull("74 degree bend", only(new GrindSegment(0, 200, 100 * s74, 200 + 100 * c74, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNull("76 degree bend", only(new GrindSegment(0, 200, 100 * s76, 200 + 100 * c76, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNull("90 degree corner", only(new GrindSegment(0, 200, 200, 200, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNull("doubling back", only(new GrindSegment(0, 200, 0, 50, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNotNull("24 gap", only(new GrindSegment(0, 224, 0, 400, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNull("25 gap", only(new GrindSegment(0, 225, 0, 400, 30)).connectedAt(0, 200, 30, 0, 1, a));
		assertNotNull("24 higher", only(new GrindSegment(0, 200, 0, 400, 54)).connectedAt(0, 200, 30, 0, 1, a));
		assertNull("25 higher", only(new GrindSegment(0, 200, 0, 400, 55)).connectedAt(0, 200, 30, 0, 1, a));
		GrindMap self = only(a);
		assertNull("itself", self.connectedAt(0, 200, 30, 0, 1, a));
	}

	@Test
	public void connectedAtPrefersTheStraighterContinuation()
	{
		GrindMap m = new GrindMap();
		GrindSegment a = new GrindSegment(0, 0, 0, 200, 30);
		GrindSegment bend = new GrindSegment(0, 200, 100, 300, 30);
		GrindSegment straight = new GrindSegment(0, 200, 0, 400, 30);
		m.add(a);
		m.add(bend);
		m.add(straight);
		assertSame(straight, m.connectedAt(0, 200, 30, 0, 1, a));
	}

	private static GrindMap only(GrindSegment s)
	{
		GrindMap m = new GrindMap();
		m.add(s);
		return m;
	}

	/** Brute force over every segment, as nearest() worked before the per-tile index. */
	private static GrindSegment bruteNearest(java.util.List<GrindSegment> segs, float x, float y, float h, float travel)
	{
		GrindSegment best = null;
		float bestD = Float.POSITIVE_INFINITY;
		for (GrindSegment s : segs)
		{
			float t = s.project(x, y);
			float d = (float) Math.hypot(x - s.xAt(t), y - s.yAt(t));
			if (h < s.top - GrindMap.BELOW_TOP || h > s.top + GrindMap.ABOVE_TOP || d > GrindMap.SNAP_DISTANCE
				|| d >= bestD || s.lineAngle(travel) > GrindMap.MAX_APPROACH + 1e-4f || !GrindMap.enoughAhead(s, t, travel))
			{
				continue;
			}
			best = s;
			bestD = d;
		}
		return best;
	}

	@Test
	public void tileIndexFindsTheSameSegmentsAsAFullScan()
	{
		java.util.Random r = new java.util.Random(7);
		GrindMap m = new GrindMap();
		java.util.List<GrindSegment> all = new java.util.ArrayList<>();
		for (int i = 0; i < 300; i++)
		{
			float x0 = r.nextFloat() * 3000 - 1000;
			float y0 = r.nextFloat() * 3000 - 1000;
			float a = r.nextFloat() * 6.28f;
			float len = 20 + r.nextFloat() * 600;
			GrindSegment s = new GrindSegment(x0, y0, x0 + len * (float) Math.sin(a), y0 + len * (float) Math.cos(a), 50);
			all.add(s);
			m.add(s);
		}
		for (int i = 0; i < 5000; i++)
		{
			float x = r.nextFloat() * 3200 - 1100;
			float y = r.nextFloat() * 3200 - 1100;
			float travel = r.nextFloat() * 6.28f;
			GrindMap.Hit hit = m.nearest(x, y, 50, travel, null, GrindMap.SNAP_DISTANCE);
			assertSame(bruteNearest(all, x, y, 50, travel), hit == null ? null : hit.segment);
		}
	}

	@Test
	public void segmentsAddedAfterAQueryAreFound()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 0, 400, 50));
		assertNotNull(m.nearest(10, 100, 50, NORTH, null, GrindMap.SNAP_DISTANCE));
		assertNull(m.nearest(-5000, 100, 50, NORTH, null, GrindMap.SNAP_DISTANCE));
		GrindSegment late = new GrindSegment(-5000, 0, -5000, 400, 50);
		m.add(late);
		assertSame(late, m.nearest(-5000, 100, 50, NORTH, null, GrindMap.SNAP_DISTANCE).segment);
	}
}

