package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class ObjectRailShapeTest
{
	private static final float EPS = 1e-3f;

	/** True when s runs between (ax, ay) and (bx, by), either way round. */
	private static boolean runs(GrindSegment s, float ax, float ay, float bx, float by)
	{
		boolean fwd = near(s.x0, ax) && near(s.y0, ay) && near(s.x1, bx) && near(s.y1, by);
		boolean rev = near(s.x0, bx) && near(s.y0, by) && near(s.x1, ax) && near(s.y1, ay);
		return fwd || rev;
	}

	private static boolean near(float a, float b)
	{
		return Math.abs(a - b) < EPS;
	}

	@Test
	public void extentsOfVertices()
	{
		float[] e = ObjectShapes.sliceExtents(new float[]{-64, 10, 64, 99}, new float[4], new float[]{-5, 5, 0, 1000}, 3,
			Float.POSITIVE_INFINITY);
		assertEquals(-64f, e[0], 0f);
		assertEquals(64f, e[1], 0f);
		assertEquals(-5f, e[2], 0f);
		assertEquals(5f, e[3], 0f);
		assertNull(ObjectShapes.sliceExtents(new float[0], new float[0], new float[0], 0, Float.POSITIVE_INFINITY));
	}

	@Test
	public void longFenceAtOrientationZeroIsOneRailAlongXThroughItsCentre()
	{
		float[] ext = {-64, 64, -5, 5};
		List<GrindSegment> s = ObjectShapes.segments(192, 320, ext, 0);
		assertEquals(1, s.size());
		assertTrue(s.get(0).toString(), runs(s.get(0), 128, 320, 256, 320));
		assertEquals(128f, s.get(0).length(), EPS);
	}

	@Test
	public void longFenceAtOrientation512RunsAlongY()
	{
		float[] ext = {-64, 64, -5, 5};
		List<GrindSegment> s = ObjectShapes.segments(192, 320, ext, 512);
		assertEquals(1, s.size());
		assertTrue(s.get(0).toString(), runs(s.get(0), 192, 256, 192, 384));
	}

	@Test
	public void longAxisAlongModelZAndAnOffCentreModel()
	{
		// a fence 10 x 100 along model z, centred at model (20, 30)
		float[] ext = {15, 25, -20, 80};
		List<GrindSegment> s = ObjectShapes.segments(0, 0, ext, 0);
		assertEquals(1, s.size());
		assertTrue(s.get(0).toString(), runs(s.get(0), 20, -20, 20, 80));
		float[] c = ObjectShapes.centre(0, 0, ext, 0);
		assertEquals(20f, c[0], EPS);
		assertEquals(30f, c[1], EPS);
		// rotated 90 degrees: model (x, z) -> local (z, -x)
		c = ObjectShapes.centre(100, 100, ext, 512);
		assertEquals(130f, c[0], EPS);
		assertEquals(80f, c[1], EPS);
	}

	@Test
	public void diagonalFenceRailFollowsTheRotation()
	{
		float[] ext = {-90, 90, -4, 4};
		List<GrindSegment> s = ObjectShapes.segments(0, 0, ext, 256);
		assertEquals(1, s.size());
		float d = 90f * (float) Math.sqrt(0.5);
		// 45 degrees: model (x, 0) -> local (x cos, -x sin)
		assertTrue(s.get(0).toString(), runs(s.get(0), -d, d, d, -d));
	}

	@Test
	public void squareCrateGivesTheFourEdgesOfItsOwnBounds()
	{
		float[] ext = {-20, 20, -20, 20};
		List<GrindSegment> s = ObjectShapes.segments(64, 64, ext, 0);
		assertEquals(4, s.size());
		boolean south = false;
		boolean north = false;
		boolean west = false;
		boolean east = false;
		for (GrindSegment g : s)
		{
			assertEquals(40f, g.length(), EPS);
			south |= runs(g, 44, 44, 84, 44);
			north |= runs(g, 44, 84, 84, 84);
			west |= runs(g, 44, 44, 44, 84);
			east |= runs(g, 84, 44, 84, 84);
		}
		assertTrue(south && north && west && east);
	}

	@Test
	public void squareIsWithinTwentyFivePercent()
	{
		// 100 x 76: shorter is 76% of longer, square-ish -> perimeter
		assertEquals(4, ObjectShapes.segments(0, 0, new float[]{-50, 50, -38, 38}, 0).size());
		// 100 x 74: a rail
		assertEquals(1, ObjectShapes.segments(0, 0, new float[]{-50, 50, -37, 37}, 0).size());
	}

	@Test
	public void degenerateModelGivesNothing()
	{
		assertTrue(ObjectShapes.segments(0, 0, new float[]{0, 0, 0, 0}, 0).isEmpty());
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Contact;
import org.junit.Test;

/**
 * A wall object that is ridden through (a vine or bush drawn as a wall, an open door). The game flags a
 * wall on both tiles it separates (the wall's own tile one side, the neighbour the opposite side), so zeroing
 * only the owning tile's wall height left the neighbour's mirrored flag blocking at the neighbour's height.
 */
public class PassableWallEdgeTest
{
	private static final float T = GridCollisionWorld.TILE;

	/** A wall on the west edge of (5, 5), flagged as the game does: WALL_W on (5, 5), WALL_E on (4, 5). */
	private static GridCollisionWorld westWall()
	{
		GridCollisionWorld w = new GridCollisionWorld(10);
		w.setTile(5, 5, GridCollisionWorld.WALL_W, 80f);
		w.setTile(4, 5, GridCollisionWorld.WALL_E, 400f);
		return w;
	}

	@Test
	public void theMirroredNeighbourFlagStillBlocksWhenOnlyTheOwnerIsZeroed()
	{
		// what the builder did before: evidence for the bug
		GridCollisionWorld w = westWall();
		w.setWallHeight(5, 5, 0f);
		assertEquals(400f, w.blockerTop(4.9f * T, 5.5f * T, 5.1f * T, 5.5f * T), 1e-3f);
	}

	@Test
	public void openingTheEdgeClearsBothSidesOfIt()
	{
		GridCollisionWorld w = westWall();
		w.openWallEdges(5, 5, GridCollisionWorld.WALL_W);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(4.9f * T, 5.5f * T, 5.1f * T, 5.5f * T), 0f);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(5.1f * T, 5.5f * T, 4.9f * T, 5.5f * T), 0f);
		assertFalse("no wall box left to scrape", w.contact(5f * T, 5.5f * T, 12f, 0f, 24f, new Contact()));
		w.rebuildGrinds();
		assertTrue("no rail left either", w.getGrinds().segments().isEmpty());
	}

	@Test
	public void openingOneEdgeKeepsTheTilesOtherWalls()
	{
		GridCollisionWorld w = new GridCollisionWorld(10);
		w.setTile(5, 5, GridCollisionWorld.WALL_W | GridCollisionWorld.WALL_N, 300f);
		w.setTile(4, 5, GridCollisionWorld.WALL_E | GridCollisionWorld.WALL_S, 300f);
		w.openWallEdges(5, 5, GridCollisionWorld.WALL_W);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(4.9f * T, 5.5f * T, 5.1f * T, 5.5f * T), 0f);
		// (5, 5)'s north wall and (4, 5)'s south wall are other walls: still there
		assertEquals(300f, w.blockerTop(5.5f * T, 5.9f * T, 5.5f * T, 6.1f * T), 1e-3f);
		assertEquals(300f, w.blockerTop(4.5f * T, 5.1f * T, 4.5f * T, 4.9f * T), 1e-3f);
	}

	@Test
	public void edgesOnTheGridBorderAreIgnoredSafely()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		w.setTile(0, 0, GridCollisionWorld.WALL_W | GridCollisionWorld.WALL_S, 300f);
		w.openWallEdges(0, 0, GridCollisionWorld.WALL_W | GridCollisionWorld.WALL_S);
		assertFalse(w.contact(0.5f, 0.5f * T, 12f, 0f, 24f, new Contact()));
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.gielinorskate.physics.Contact;
import org.junit.Test;

/**
 * Small decorative rocks are ridden through and never grinded; mining rocks and big boulders still block. The
 * fixtures are the objects as the scene builder sees them: (impostor-resolved) name, actions, model height and the
 * model's footprint extents.
 */
public class RockRulesTest
{
	private static final float T = GridCollisionWorld.TILE;
	private static final String[] NO_ACTIONS = {null, null, null, null, null};
	private static final float[] PEBBLE_FOOTPRINT = {-30, 30, -24, 24};
	private static final float[] ROCK_FOOTPRINT = {-56, 56, -48, 48};

	@Test
	public void rockWordsAreMatchedAsWholeWords()
	{
		for (String name : new String[]{"Rock", "Rocks", "rocks", "Mossy rocks", "Pebbles", "Stones", "Stone",
			"Boulder", "Small boulders", "Rubble", "Rocky outcrop", "Gravel"})
		{
			assertTrue(name, ObjectNames.isRockName(name));
		}
		for (String name : new String[]{null, "", "Gravestone", "Stone wall", "Stone bench", "Stone pillar",
			"Stone table", "Stone statue", "Rock wall", "Crate", "Rockslide", "Stone steps", "Stone archway",
			"Stone circle altar", "Bush", "Stone fence", "Brimstone"})
		{
			assertFalse(String.valueOf(name), ObjectNames.isRockName(name));
		}
	}

	@Test
	public void aSmallRockWithNothingToDoOnItIsDecoration()
	{
		assertTrue(ObjectNames.isSmallDecorativeRock("Rocks", NO_ACTIONS, 40f, ROCK_FOOTPRINT));
		assertTrue(ObjectNames.isSmallDecorativeRock("Pebbles", null, 20f, PEBBLE_FOOTPRINT));
		assertTrue(ObjectNames.isSmallDecorativeRock("Stones", new String[0], 80f,
			ROCK_FOOTPRINT));
		assertTrue("a small boulder", ObjectNames.isSmallDecorativeRock("Boulder", NO_ACTIONS, 70f, ROCK_FOOTPRINT));
	}

	@Test
	public void miningRocksAndOtherRocksYouCanUseStaySolid()
	{
		assertFalse("ore", ObjectNames.isSmallDecorativeRock("Rocks", new String[]{"Mine", "Prospect", null, null, null},
			40f, ROCK_FOOTPRINT));
		assertFalse("agility", ObjectNames.isSmallDecorativeRock("Rocks", new String[]{null, "Climb", null, null, null},
			40f, ROCK_FOOTPRINT));
		assertFalse("searchable", ObjectNames.isSmallDecorativeRock("Rock", new String[]{"Search"}, 40f,
			ROCK_FOOTPRINT));
	}

	@Test
	public void bigBouldersAndNonRocksStaySolid()
	{
		assertFalse("tall", ObjectNames.isSmallDecorativeRock("Boulder", NO_ACTIONS,
			80f + 1f, ROCK_FOOTPRINT));
		assertFalse("wide", ObjectNames.isSmallDecorativeRock("Rocks", NO_ACTIONS, 60f,
			new float[]{-120, 120, -40, 40}));
		assertFalse("not a rock", ObjectNames.isSmallDecorativeRock("Crate", NO_ACTIONS, 40f, ROCK_FOOTPRINT));
		assertFalse("no model", ObjectNames.isSmallDecorativeRock("Rocks", NO_ACTIONS, 40f, null));
	}

	/** A 6x6 flat world with the FULL-flagged rock tile (2, 2), shaped by the rock's box as the builder does. */
	private static GridCollisionWorld rockTile(float height, boolean pass, boolean ledges)
	{
		GridCollisionWorld w = new GridCollisionWorld(6);
		w.setTile(2, 2, GridCollisionWorld.FULL, height);
		w.addObjectBlocker(2.5f * T, 2.5f * T, ROCK_FOOTPRINT, 0, height, pass, ledges);
		w.markShaped(2, 2);
		w.rebuildBlockers();
		w.rebuildGrinds();
		return w;
	}

	@Test
	public void aRockBoxWasALandableLedgeAllRound()
	{
		// evidence: a 64-tall rock with a 112 x 96 footprint classified LOW, and LOW boxes' top edges are grinds
		assertEquals(BlockerSet.LOW, ObjectShapes.classify(false, 64f, ObjectShapes.minSide(ROCK_FOOTPRINT)));
		GridCollisionWorld w = rockTile(64f, false, true);
		assertEquals(4, w.getGrinds().segments().size());
	}

	@Test
	public void aSmallDecorativeRockIsRiddenThroughWithNoGrind()
	{
		GridCollisionWorld w = rockTile(64f, true, false);
		assertTrue(w.getGrinds().segments().isEmpty());
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(1.5f * T, 2.5f * T, 3.5f * T, 2.5f * T), 0f);
		assertEquals("no step up onto it", 0f, w.groundHeight(2.5f * T, 2.5f * T), 1e-3f);
		Contact c = new Contact();
		assertFalse(w.contact(2.5f * T, 2.5f * T, 12f, 0f, 24f, c));
	}

	@Test
	public void aRockTooBigToRideThroughStillBlocksButIsNoRail()
	{
		GridCollisionWorld w = rockTile(100f, false, false);
		assertTrue(w.getGrinds().segments().isEmpty());
		// still a box you can land on
		assertEquals(100f, w.groundHeight(2.5f * T, 2.5f * T), 1e-3f);
		assertEquals(BlockerSet.LOW, WorldTests.kind(w.getBlockers(), 0));
	}

	@Test
	public void ledgesStayForOtherLowBoxes()
	{
		GridCollisionWorld w = new GridCollisionWorld(6);
		w.setTile(2, 2, GridCollisionWorld.FULL, 64f);
		assertEquals(BlockerSet.LOW, w.addObjectBlocker(2.5f * T, 2.5f * T, ROCK_FOOTPRINT, 0, 64f, false, true));
		w.markShaped(2, 2);
		w.rebuildGrinds();
		assertEquals(4, w.getGrinds().segments().size());
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/**
 * A FULL-flagged tile with a modelled object on it collides only through that object's box. The builder
 * marked such tiles "modelled" (no fallback box) but never shaped in the world, so every object tile still
 * blocked as a whole 128 x 128 tile: a plant's PASS box sat inside a solid whole-tile box.
 */
public class ShapedTileTest
{
	private static final float T = GridCollisionWorld.TILE;

	private static GridCollisionWorld plantTile()
	{
		GridCollisionWorld w = new GridCollisionWorld(10);
		// a bush 150 tall flags its tile as blocked whole; its box is ridden through by name
		w.setTile(5, 5, GridCollisionWorld.FULL, 150f);
		w.addObjectBlocker(5.5f * T, 5.5f * T, new float[]{-40, 40, -40, 40}, 0, 150f, true, true);
		return w;
	}

	@Test
	public void anUnshapedPlantTileStillBlocksWhole()
	{
		// evidence: the state the builder left plant tiles in
		GridCollisionWorld w = plantTile();
		assertEquals(150f, w.blockerTop(4.9f * T, 5.5f * T, 5.1f * T, 5.5f * T), 1e-3f);
	}

	@Test
	public void markingTheTileModelledShapesItSoThePlantIsRiddenThrough()
	{
		GridCollisionWorld w = plantTile();
		SceneCollisionBuilder b = new SceneCollisionBuilder(null, w, true);
		b.shapeable[5][5] = true;
		assertTrue(b.shapeTiles(5, 5, 5, 5, true));
		assertTrue(b.modelled[5][5]);
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(4.9f * T, 5.5f * T, 5.5f * T, 5.5f * T), 0f);
		assertEquals("no platform rise either", 0f, w.groundHeight(5.5f * T, 5.5f * T), 1e-3f);
	}

	@Test
	public void aShapedTileWithASolidObjectBlocksOnlyAtTheObject()
	{
		GridCollisionWorld w = new GridCollisionWorld(10);
		w.setTile(5, 5, GridCollisionWorld.FULL, 300f);
		w.addObjectBlocker(5.5f * T, 5.5f * T, new float[]{-20, 20, -20, 20}, 0, 300f, false, true);
		SceneCollisionBuilder b = new SceneCollisionBuilder(null, w, true);
		b.shapeable[5][5] = true;
		b.shapeTiles(5, 5, 5, 5, true);
		// the tile's edge is free, the rock in the middle is not
		assertEquals(Float.NEGATIVE_INFINITY, w.blockerTop(4.9f * T, 5.1f * T, 5.1f * T, 5.1f * T), 0f);
		assertEquals(300f, w.blockerTop(5.5f * T - 40, 5.5f * T, 5.5f * T - 25, 5.5f * T), 1e-3f);
	}
}

package com.gielinorskate.world;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import org.junit.Test;

/** Sloped rails (review extra 2): a top at each end, interpolated along the segment. */
public class SlopedRailTest
{
	@Test
	public void topIsInterpolatedAlongTheSegment()
	{
		GrindSegment s = new GrindSegment(0, 0, 0, 400, 30, 130);
		assertEquals(30f, s.topAt(0f), 1e-4f);
		assertEquals(80f, s.topAt(0.5f), 1e-4f);
		assertEquals(130f, s.topAt(1f), 1e-4f);
		assertEquals(80f, s.top, 1e-4f);
		GrindSegment flat = new GrindSegment(0, 0, 0, 400, 50);
		assertEquals(50f, flat.top0, 0f);
		assertEquals(50f, flat.top1, 0f);
		assertEquals(50f, flat.topAt(0.3f), 0f);
	}

	@Test
	public void lockWindowUsesTheHeightUnderTheSkater()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 0, 400, 30, 230));
		// at y = 350 the rail is 205 high: the mean top 130 would put 200 in the window, the local top does too,
		// but at y = 50 (top 55) h 200 is far above it
		assertNotNull(m.nearest(10, 350, 200, 0f, null, GrindMap.SNAP_DISTANCE));
		assertNull(m.nearest(10, 50, 200, 0f, null, GrindMap.SNAP_DISTANCE));
	}

	@Test
	public void aGrindRunsOnFromTheHighEndOfASlopedRail()
	{
		GrindMap m = new GrindMap();
		GrindSegment ramp = new GrindSegment(0, 0, 0, 400, 30, 130);
		GrindSegment flat = new GrindSegment(0, 400, 0, 800, 130);
		m.add(ramp);
		m.add(flat);
		// the ramp's mean top (80) is 50 below the flat one, but at the joint both are 130
		assertSame(flat, m.connectedAt(0, 400, ramp.topAt(1f), 0, 1, ramp));
	}

	@Test
	public void mergeJoinsCollinearPiecesOnTheSameIncline()
	{
		GrindMap m = new GrindMap();
		m.add(new GrindSegment(0, 0, 0, 128, 0, 64));
		m.add(new GrindSegment(0, 256, 0, 128, 128, 64)); // reversed, same incline
		m.add(new GrindSegment(0, 256, 0, 384, 128, 128)); // flattens out: kept apart
		m.merge();
		assertEquals(2, m.segments().size());
		GrindSegment ramp = m.segments().get(0).length() > 200 ? m.segments().get(0) : m.segments().get(1);
		assertEquals(256f, ramp.length(), 1e-3f);
		assertEquals(0f, Math.min(ramp.top0, ramp.top1), 1e-3f);
		assertEquals(128f, Math.max(ramp.top0, ramp.top1), 1e-3f);
	}

	@Test
	public void wallEdgeRailsFollowTheGroundAtEachEnd()
	{
		GridCollisionWorld w = new GridCollisionWorld(4);
		WorldTests.setCornerHeight(w, 1, 1, 0);
		WorldTests.setCornerHeight(w, 2, 1, 64);
		w.addEdgeGrind(1, 1, GridCollisionWorld.WALL_S, 40);
		w.rebuildGrinds();
		GrindSegment s = w.getGrinds().segments().get(0);
		float west = s.x0 < s.x1 ? s.top0 : s.top1;
		float east = s.x0 < s.x1 ? s.top1 : s.top0;
		assertEquals(40f, west, 1e-3f);
		assertEquals(104f, east, 1e-3f);
	}

	@Test
	public void objectRailsUseTheTerrainUnderEachEnd()
	{
		// a 256-long handrail (model x -128..128) on ground rising 0.25 per unit eastward
		GridCollisionWorld w = new GridCollisionWorld(6);
		for (int cx = 0; cx <= 6; cx++)
		{
			for (int cy = 0; cy <= 6; cy++)
			{
				WorldTests.setCornerHeight(w, cx, cy, cx * 32f);
			}
		}
		w.addObjectGrind(384, 384, new float[]{-128, 128, -4, 4}, 0, 50);
		w.rebuildGrinds();
		GrindSegment s = w.getGrinds().segments().get(0);
		float west = s.x0 < s.x1 ? s.top0 : s.top1;
		float east = s.x0 < s.x1 ? s.top1 : s.top0;
		assertEquals(256 * 0.25f + 50, west, 1e-2f);
		assertEquals(512 * 0.25f + 50, east, 1e-2f);
	}
}

package com.gielinorskate.world;

/** Test-only access to world internals: shared terrain corners, extra grinds and box index details. */
public final class WorldTests
{
	private WorldTests()
	{
	}

	/** Sets grid corner (cx, cy) for every tile that shares it (up to four). */
	public static void setCornerHeight(GridCollisionWorld w, int cx, int cy, float h)
	{
		for (int k = 0; k < 4; k++)
		{
			// corner k (SW, SE, NW, NE) of the tile k & 1 west and k >> 1 south of it
			int tx = cx - (k & 1);
			int ty = cy - (k >> 1);
			if (tx >= 0 && ty >= 0 && tx < w.size() && ty < w.size())
			{
				float[] c = w.tileCorners[tx][ty].clone();
				c[k] = h;
				w.setTileCorners(tx, ty, c[0], c[1], c[2], c[3]);
			}
		}
	}

	/**
	 * Adds a grind segment that does not come from the collision flags. It is included, and merged with the
	 * flag-derived segments, by every later rebuildGrinds. Never affects collision.
	 */
	public static void addGrindSegment(GridCollisionWorld w, GrindSegment s)
	{
		w.added.add(s);
	}

	/** Number of boxes registered in tile (tx, ty) (0 off the grid). */
	public static int countAt(BlockerSet s, int tx, int ty)
	{
		return tx < 0 || ty < 0 || tx >= s.size || ty >= s.size ? 0 : s.tileBoxes[tx * s.size + ty].length;
	}

	public static byte kind(BlockerSet s, int i)
	{
		return (byte) s.boxes[i][7];
	}

	public static int flags(BlockerSet s, int i)
	{
		return (int) s.boxes[i][8];
	}
}
